# 1.5. Public-name registration
# -----------------------------------------------------------------------------

__all__: List[str] = []


def _register_public_names(names: Iterable[str]) -> None:
    """Register unique public names."""

    known = set(__all__)
    for name in names:
        if name not in known:
            __all__.append(name)
            known.add(name)


