# 1.11. Lightweight protocols
# -----------------------------------------------------------------------------

@runtime_checkable
class SupportsToDict(Protocol):
    """Object exposing ``to_dict``."""

    def to_dict(self) -> Mapping[str, Any]:
        """Return a mapping."""


@runtime_checkable
class SupportsCoordinates(Protocol):
    """Object exposing Cartesian coordinates."""

    @property
    def coord(self) -> Any:
        """Return coordinates."""


@runtime_checkable
class SupportsAtomspec(Protocol):
    """Object exposing a ChimeraX atom specification."""

    @property
    def atomspec(self) -> str:
        """Return an atom specification."""


@runtime_checkable
class SupportsCommandRun(Protocol):
    """Backend capable of running one command."""

    def run(self, command: str) -> Any:
        """Execute one command."""


@runtime_checkable
class SupportsCommandBatch(Protocol):
    """Backend capable of running several commands."""

    def run_many(self, commands: Sequence[str]) -> Any:
        """Execute several commands."""


