# 3.1. Error codes and safe context handling
# -----------------------------------------------------------------------------

ERROR_CODE_VISUALIZATION: Final[str] = "visualization_error"
ERROR_CODE_CONFIGURATION: Final[str] = "configuration_error"
ERROR_CODE_SPECIFICATION: Final[str] = "specification_error"
ERROR_CODE_SELECTION: Final[str] = "selection_error"
ERROR_CODE_INTERACTION: Final[str] = "interaction_error"
ERROR_CODE_PLAN: Final[str] = "plan_error"
ERROR_CODE_SCENE: Final[str] = "scene_error"
ERROR_CODE_STYLE: Final[str] = "style_error"
ERROR_CODE_COLOR: Final[str] = "color_error"
ERROR_CODE_GEOMETRY: Final[str] = "geometry_error"
ERROR_CODE_COORDINATE: Final[str] = "coordinate_error"
ERROR_CODE_BACKEND: Final[str] = "backend_error"
ERROR_CODE_CHIMERAX_UNAVAILABLE: Final[str] = "chimerax_unavailable"
ERROR_CODE_COMMAND: Final[str] = "command_error"
ERROR_CODE_EXECUTION: Final[str] = "execution_error"
ERROR_CODE_SNAPSHOT: Final[str] = "snapshot_error"
ERROR_CODE_IMAGE: Final[str] = "image_error"
ERROR_CODE_EXPORT: Final[str] = "export_error"
ERROR_CODE_SERIALIZATION: Final[str] = "serialization_error"
ERROR_CODE_INTEGRATION: Final[str] = "integration_error"
ERROR_CODE_DOCK_MODEL: Final[str] = "dock_model_error"
ERROR_CODE_VALIDATION: Final[str] = "validation_error"
ERROR_CODE_LIMIT: Final[str] = "limit_error"
ERROR_CODE_STATE: Final[str] = "state_error"
ERROR_CODE_DEPENDENCY: Final[str] = "dependency_error"
ERROR_CODE_UNSUPPORTED: Final[str] = "unsupported_error"
ERROR_CODE_CANCELLED: Final[str] = "cancelled"
ERROR_CODE_MULTIPLE: Final[str] = "multiple_errors"

ERROR_SEVERITY_INFO: Final[str] = "info"
ERROR_SEVERITY_WARNING: Final[str] = "warning"
ERROR_SEVERITY_ERROR: Final[str] = "error"
ERROR_SEVERITY_FATAL: Final[str] = "fatal"
ERROR_SEVERITIES: Final[Tuple[str, ...]] = (
    ERROR_SEVERITY_INFO,
    ERROR_SEVERITY_WARNING,
    ERROR_SEVERITY_ERROR,
    ERROR_SEVERITY_FATAL,
)

_MAX_ERROR_CONTEXT_DEPTH: Final[int] = 4
_MAX_ERROR_CONTEXT_ITEMS: Final[int] = 64
_MAX_ERROR_TEXT_LENGTH: Final[int] = 4096


def _truncate_error_text(value: str, limit: int = _MAX_ERROR_TEXT_LENGTH) -> str:
    """Limit diagnostic text."""

    if len(value) <= limit:
        return value
    return value[: max(0, limit - 3)] + "..."


def _safe_error_value(value: Any, *, depth: int = 0) -> JSONValue:
    """Convert diagnostics to bounded JSON-compatible values."""

    if value is None or isinstance(value, (str, int, bool)):
        return _truncate_error_text(value) if isinstance(value, str) else value
    if isinstance(value, float):
        return value if math.isfinite(value) else str(value)
    if depth >= _MAX_ERROR_CONTEXT_DEPTH:
        return _truncate_error_text(repr(value))
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Enum):
        return _safe_error_value(value.value, depth=depth + 1)
    if is_dataclass(value) and not isinstance(value, type):
        try:
            value = asdict(value)
        except Exception:
            return _truncate_error_text(repr(value))
    if isinstance(value, Mapping):
        result: Dict[str, JSONValue] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= _MAX_ERROR_CONTEXT_ITEMS:
                result["__truncated__"] = True
                break
            result[_truncate_error_text(str(key), 256)] = _safe_error_value(
                item,
                depth=depth + 1,
            )
        return result
    if isinstance(value, (list, tuple, set, frozenset)):
        result_list: List[JSONValue] = []
        for index, item in enumerate(value):
            if index >= _MAX_ERROR_CONTEXT_ITEMS:
                result_list.append("<truncated>")
                break
            result_list.append(_safe_error_value(item, depth=depth + 1))
        return result_list
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        try:
            return _safe_error_value(to_dict(), depth=depth + 1)
        except Exception:
            pass
    try:
        return _truncate_error_text(repr(value))
    except Exception:
        return f"<{type(value).__name__}>"


def _normalize_error_context(context: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    """Copy exception context using stable string keys."""

    if not context:
        return {}
    normalized: Dict[str, Any] = {}
    for index, (key, value) in enumerate(context.items()):
        if index >= _MAX_ERROR_CONTEXT_ITEMS:
            normalized["__truncated__"] = True
            break
        normalized[str(key)] = value
    return normalized


def _normalize_error_severity(value: str) -> str:
    """Normalize severity without depending on Section 4 enums."""

    normalized = str(value).strip().lower()
    return normalized if normalized in ERROR_SEVERITIES else ERROR_SEVERITY_ERROR


# 3.2. Base exception
# -----------------------------------------------------------------------------

class VisualizationError(Exception):
    """Base error for visualization planning and execution."""

    default_code: Final[str] = ERROR_CODE_VISUALIZATION
    default_severity: Final[str] = ERROR_SEVERITY_ERROR
    default_recoverable: Final[bool] = False

    def __init__(
        self,
        message: str,
        *,
        code: Optional[str] = None,
        context: Optional[Mapping[str, Any]] = None,
        cause: Optional[BaseException] = None,
        hint: Optional[str] = None,
        recoverable: Optional[bool] = None,
        severity: Optional[str] = None,
    ) -> None:
        clean_message = str(message).strip() or self.__class__.__name__
        super().__init__(clean_message)
        self.message = clean_message
        self.code = str(code or self.default_code)
        self.context = _normalize_error_context(context)
        self.cause = cause
        self.hint = str(hint).strip() if hint else None
        self.recoverable = (
            self.default_recoverable if recoverable is None else bool(recoverable)
        )
        self.severity = _normalize_error_severity(
            severity or self.default_severity
        )

    def __str__(self) -> str:
        """Return a compact diagnostic."""

        text = self.message
        if self.code:
            text = f"[{self.code}] {text}"
        if self.hint:
            text = f"{text} Hint: {self.hint}"
        return text

    def __repr__(self) -> str:
        """Return a reproducible diagnostic representation."""

        return (
            f"{self.__class__.__name__}({self.message!r}, code={self.code!r}, "
            f"recoverable={self.recoverable!r}, severity={self.severity!r})"
        )

    def add_context(self, **values: Any) -> "VisualizationError":
        """Append context in place and return this error."""

        self.context.update(values)
        return self

    def with_context(self, **values: Any) -> "VisualizationError":
        """Clone the error with merged context."""

        clone = self.__class__.__new__(self.__class__)
        Exception.__init__(clone, self.message)
        clone.__dict__ = dict(self.__dict__)
        clone.context = dict(self.context)
        clone.context.update(values)
        return clone

    def to_dict(
        self,
        *,
        include_cause: bool = True,
        include_traceback: bool = False,
    ) -> Dict[str, Any]:
        """Serialize the error for reports and permissive mode."""

        payload: Dict[str, Any] = {
            "type": self.__class__.__name__,
            "message": self.message,
            "code": self.code,
            "severity": self.severity,
            "recoverable": self.recoverable,
            "context": _safe_error_value(self.context),
        }
        if self.hint:
            payload["hint"] = self.hint
        if include_cause and self.cause is not None:
            if isinstance(self.cause, VisualizationError):
                payload["cause"] = self.cause.to_dict(
                    include_cause=True,
                    include_traceback=False,
                )
            else:
                payload["cause"] = {
                    "type": self.cause.__class__.__name__,
                    "message": str(self.cause),
                }
        if include_traceback:
            payload["traceback"] = format_visualization_traceback(self)
        return payload

    def to_json(
        self,
        *,
        indent: Optional[int] = 2,
        include_cause: bool = True,
        include_traceback: bool = False,
    ) -> str:
        """Serialize the error as JSON."""

        return json.dumps(
            self.to_dict(
                include_cause=include_cause,
                include_traceback=include_traceback,
            ),
            ensure_ascii=False,
            indent=indent,
            sort_keys=True,
        )


