# 3.5. Backend and command errors
# -----------------------------------------------------------------------------

class VisualizationBackendError(VisualizationError):
    """Backend discovery, setup or communication failure."""

    default_code = ERROR_CODE_BACKEND


class ChimeraXUnavailableError(VisualizationBackendError):
    """ChimeraX backend is unavailable."""

    default_code = ERROR_CODE_CHIMERAX_UNAVAILABLE
    default_recoverable = True

    def __init__(
        self,
        message: str = "ChimeraX is not available in this Python environment.",
        **kwargs: Any,
    ) -> None:
        kwargs.setdefault(
            "hint",
            "Run inside ChimeraX or export commands for later execution.",
        )
        super().__init__(message, **kwargs)


class VisualizationCommandError(VisualizationBackendError):
    """Command generation or command syntax failure."""

    default_code = ERROR_CODE_COMMAND

    def __init__(
        self,
        message: str,
        *,
        command: Optional[str] = None,
        command_index: Optional[int] = None,
        **kwargs: Any,
    ) -> None:
        context = _normalize_error_context(kwargs.pop("context", None))
        if command is not None:
            context.setdefault("command", command)
        if command_index is not None:
            context.setdefault("command_index", command_index)
        super().__init__(message, context=context, **kwargs)
        self.command = command
        self.command_index = command_index


class VisualizationExecutionError(VisualizationBackendError):
    """Backend command execution failure."""

    default_code = ERROR_CODE_EXECUTION

    def __init__(
        self,
        message: str,
        *,
        command: Optional[str] = None,
        command_index: Optional[int] = None,
        completed_commands: int = 0,
        **kwargs: Any,
    ) -> None:
        context = _normalize_error_context(kwargs.pop("context", None))
        if command is not None:
            context.setdefault("command", command)
        if command_index is not None:
            context.setdefault("command_index", command_index)
        context.setdefault("completed_commands", max(0, int(completed_commands)))
        super().__init__(message, context=context, **kwargs)
        self.command = command
        self.command_index = command_index
        self.completed_commands = max(0, int(completed_commands))


class VisualizationDependencyError(VisualizationError):
    """Optional dependency required by an operation is missing."""

    default_code = ERROR_CODE_DEPENDENCY
    default_recoverable = True

    def __init__(
        self,
        dependency: str,
        operation: Optional[str] = None,
        *,
        message: Optional[str] = None,
        **kwargs: Any,
    ) -> None:
        dependency_name = str(dependency).strip() or "unknown dependency"
        context = _normalize_error_context(kwargs.pop("context", None))
        context.setdefault("dependency", dependency_name)
        if operation:
            context.setdefault("operation", str(operation))
        text = message or f"Optional dependency {dependency_name!r} is required."
        super().__init__(text, context=context, **kwargs)
        self.dependency = dependency_name
        self.operation = operation


class VisualizationNotSupportedError(VisualizationError):
    """Requested capability is unsupported."""

    default_code = ERROR_CODE_UNSUPPORTED
    default_recoverable = True


class VisualizationCancelledError(VisualizationError):
    """Visualization operation was cancelled."""

    default_code = ERROR_CODE_CANCELLED
    default_severity = ERROR_SEVERITY_INFO
    default_recoverable = True


