# 3.7. Integration and validation errors
# -----------------------------------------------------------------------------

class VisualizationIntegrationError(VisualizationError):
    """Cross-module integration failure."""

    default_code = ERROR_CODE_INTEGRATION


class DockModelVisualizationError(VisualizationIntegrationError):
    """DockModel visualization integration failure."""

    default_code = ERROR_CODE_DOCK_MODEL


class VisualizationValidationError(VisualizationError, ValueError):
    """Validation failure with field-level diagnostics."""

    default_code = ERROR_CODE_VALIDATION
    default_recoverable = True

    def __init__(
        self,
        message: str,
        *,
        field_name: Optional[str] = None,
        value: Any = None,
        expected: Optional[str] = None,
        **kwargs: Any,
    ) -> None:
        context = _normalize_error_context(kwargs.pop("context", None))
        if field_name is not None:
            context.setdefault("field", str(field_name))
        if value is not None:
            context.setdefault("value", value)
        if expected is not None:
            context.setdefault("expected", str(expected))
        super().__init__(message, context=context, **kwargs)
        self.field_name = field_name
        self.value = value
        self.expected = expected


# 3.8. Aggregated errors
# -----------------------------------------------------------------------------

class VisualizationErrorGroup(VisualizationError):
    """Ordered collection of visualization errors."""

    default_code = ERROR_CODE_MULTIPLE

    def __init__(
        self,
        message: str,
        errors: Sequence[BaseException],
        *,
        context: Optional[Mapping[str, Any]] = None,
        **kwargs: Any,
    ) -> None:
        normalized = tuple(
            error
            if isinstance(error, VisualizationError)
            else wrap_visualization_error(error)
            for error in errors
        )
        merged_context = _normalize_error_context(context)
        merged_context.setdefault("error_count", len(normalized))
        recoverable = bool(normalized) and all(
            error.recoverable for error in normalized
        )
        severity = _highest_error_severity(normalized)
        super().__init__(
            message,
            context=merged_context,
            recoverable=recoverable,
            severity=severity,
            **kwargs,
        )
        self.errors: Tuple[VisualizationError, ...] = normalized

    def __len__(self) -> int:
        """Return contained error count."""

        return len(self.errors)

    def __iter__(self) -> Iterator[VisualizationError]:
        """Iterate over contained errors."""

        return iter(self.errors)

    def __getitem__(self, index: int) -> VisualizationError:
        """Return one contained error."""

        return self.errors[index]

    def __str__(self) -> str:
        """Return message with aggregate count."""

        return f"{super().__str__()} ({len(self.errors)} error(s))"

    def to_dict(
        self,
        *,
        include_cause: bool = True,
        include_traceback: bool = False,
    ) -> Dict[str, Any]:
        """Serialize the aggregate and contained errors."""

        payload = super().to_dict(
            include_cause=include_cause,
            include_traceback=include_traceback,
        )
        payload["errors"] = [
            error.to_dict(
                include_cause=include_cause,
                include_traceback=include_traceback,
            )
            for error in self.errors
        ]
        return payload

    def flatten(self) -> Tuple[VisualizationError, ...]:
        """Flatten nested groups while preserving order."""

        flattened: List[VisualizationError] = []
        for error in self.errors:
            if isinstance(error, VisualizationErrorGroup):
                flattened.extend(error.flatten())
            else:
                flattened.append(error)
        return tuple(flattened)


