class VisualizationWarning(UserWarning):
    """Base warning emitted by visualization workflows."""


class VisualizationDataWarning(VisualizationWarning):
    """Incomplete or ambiguous molecular data."""


class VisualizationBackendWarning(VisualizationWarning):
    """Backend-specific limitation or behavior."""


class VisualizationFallbackWarning(VisualizationWarning):
    """A safe fallback replaced the requested behavior."""


class VisualizationPerformanceWarning(VisualizationWarning):
    """Operation may be expensive or produce many elements."""


class VisualizationCompatibilityWarning(VisualizationWarning):
    """Potential version or format incompatibility."""


class VisualizationDeprecationWarning(DeprecationWarning):
    """Deprecated visualization API usage."""


# 3.10. Exception utilities
# -----------------------------------------------------------------------------

_SEVERITY_RANK: Final[Mapping[str, int]] = MappingProxyType(
    {
        ERROR_SEVERITY_INFO: 0,
        ERROR_SEVERITY_WARNING: 1,
        ERROR_SEVERITY_ERROR: 2,
        ERROR_SEVERITY_FATAL: 3,
    }
)


def _highest_error_severity(errors: Iterable[VisualizationError]) -> str:
    """Return the highest severity in an iterable."""

    highest = ERROR_SEVERITY_INFO
    highest_rank = _SEVERITY_RANK[highest]
    found = False
    for error in errors:
        found = True
        rank = _SEVERITY_RANK.get(error.severity, _SEVERITY_RANK[ERROR_SEVERITY_ERROR])
        if rank > highest_rank:
            highest = error.severity
            highest_rank = rank
    return highest if found else ERROR_SEVERITY_ERROR


def wrap_visualization_error(
    error: BaseException,
    *,
    message: Optional[str] = None,
    code: Optional[str] = None,
    context: Optional[Mapping[str, Any]] = None,
    recoverable: Optional[bool] = None,
    severity: Optional[str] = None,
) -> VisualizationError:
    """Wrap an arbitrary exception without discarding its cause."""

    if isinstance(error, VisualizationError):
        if not any((message, code, context, recoverable is not None, severity)):
            return error
        merged_context = dict(error.context)
        merged_context.update(_normalize_error_context(context))
        return VisualizationError(
            message or error.message,
            code=code or error.code,
            context=merged_context,
            cause=error,
            hint=error.hint,
            recoverable=(
                error.recoverable if recoverable is None else recoverable
            ),
            severity=severity or error.severity,
        )
    return VisualizationError(
        message or str(error) or error.__class__.__name__,
        code=code,
        context=context,
        cause=error,
        recoverable=recoverable,
        severity=severity,
    )


def exception_to_dict(
    error: BaseException,
    *,
    include_cause: bool = True,
    include_traceback: bool = False,
) -> Dict[str, Any]:
    """Serialize any exception using the visualization schema."""

    wrapped = wrap_visualization_error(error)
    return wrapped.to_dict(
        include_cause=include_cause,
        include_traceback=include_traceback,
    )


def format_visualization_traceback(
    error: BaseException,
    *,
    limit: Optional[int] = None,
) -> str:
    """Format a bounded traceback for diagnostics."""

    lines = traceback.format_exception(
        type(error),
        error,
        error.__traceback__,
        limit=limit,
    )
    return _truncate_error_text("".join(lines), _MAX_ERROR_TEXT_LENGTH * 4)


def emit_visualization_warning(
    message: str,
    *,
    category: type[Warning] = VisualizationWarning,
    stacklevel: int = 2,
) -> None:
    """Emit a visualization warning with a stable stack level."""

    warnings.warn(str(message), category, stacklevel=max(1, int(stacklevel)))


def raise_visualization_error(
    error: BaseException,
    *,
    message: Optional[str] = None,
    code: Optional[str] = None,
    context: Optional[Mapping[str, Any]] = None,
) -> None:
    """Raise a normalized visualization error."""

    wrapped = wrap_visualization_error(
        error,
        message=message,
        code=code,
        context=context,
    )
    if wrapped is error:
        raise wrapped
    raise wrapped from error


def collect_visualization_errors(
    errors: Iterable[BaseException],
    *,
    message: str = "Multiple visualization errors occurred.",
    context: Optional[Mapping[str, Any]] = None,
) -> Optional[VisualizationErrorGroup]:
    """Build an aggregate or return ``None`` for an empty iterable."""

    collected = tuple(errors)
    if not collected:
        return None
    return VisualizationErrorGroup(message, collected, context=context)


def raise_if_visualization_errors(
    errors: Iterable[BaseException],
    *,
    message: str = "Multiple visualization errors occurred.",
    context: Optional[Mapping[str, Any]] = None,
) -> None:
    """Raise one aggregate when the iterable is non-empty."""

    group = collect_visualization_errors(
        errors,
        message=message,
        context=context,
    )
    if group is not None:
        raise group


