# 4.1. Base enums
# -----------------------------------------------------------------------------

_ENUM_TOKEN_PATTERN: Final[re.Pattern[str]] = re.compile(r"[^a-z0-9]+")


def _normalize_enum_token(value: Any) -> str:
    """Normalize enum input."""

    if isinstance(value, Enum):
        value = value.value
    return _ENUM_TOKEN_PATTERN.sub("_", str(value).strip().lower()).strip("_")


class TextEnum(str, Enum):
    """Serializable string enum with alias parsing."""

    def __str__(self) -> str:
        return str(self.value)

    def __repr__(self) -> str:
        return f"{type(self).__name__}.{self.name}"

    @classmethod
    def aliases(cls) -> Mapping[str, str]:
        registry = globals().get("_ENUM_ALIASES", {})
        return registry.get(cls.__name__, MappingProxyType({}))

    @classmethod
    def values(cls) -> Tuple[str, ...]:
        return tuple(str(member.value) for member in cls)

    @classmethod
    def names(cls) -> Tuple[str, ...]:
        return tuple(member.name for member in cls)

    @classmethod
    def choices(cls) -> Tuple[str, ...]:
        return cls.values()

    @classmethod
    def parse(
        cls,
        value: Any,
        *,
        default: Any = None,
        strict: bool = True,
        field_name: Optional[str] = None,
    ) -> Optional["TextEnum"]:
        """Parse names, values or aliases."""

        if isinstance(value, cls):
            return value
        if value is None or (isinstance(value, str) and not value.strip()):
            if default is not None:
                return cls.parse(default, field_name=field_name)
            if not strict:
                return None
            raise VisualizationValidationError(
                f"A {cls.__name__} value is required.",
                field_name=field_name or cls.__name__,
                value=value,
                expected=", ".join(cls.choices()),
            )

        token = _normalize_enum_token(value)
        canonical: Optional[str] = None
        for member in cls:
            if token in {
                _normalize_enum_token(member.name),
                _normalize_enum_token(member.value),
            }:
                canonical = str(member.value)
                break
        if canonical is None:
            aliases = {
                _normalize_enum_token(alias): target
                for alias, target in cls.aliases().items()
            }
            canonical = aliases.get(token)
        if canonical is not None:
            for member in cls:
                if _normalize_enum_token(member.value) == _normalize_enum_token(canonical):
                    return member
        if default is not None:
            return cls.parse(default, field_name=field_name)
        if not strict:
            return None
        raise VisualizationValidationError(
            f"Unsupported {cls.__name__} value: {value!r}.",
            field_name=field_name or cls.__name__,
            value=value,
            expected=", ".join(cls.choices()),
        )

    @classmethod
    def contains(cls, value: Any) -> bool:
        return cls.parse(value, strict=False) is not None

    @property
    def label(self) -> str:
        return self.value.replace("_", " ").title()

    def to_dict(self) -> Dict[str, str]:
        return {
            "enum": type(self).__name__,
            "name": self.name,
            "value": str(self.value),
            "label": self.label,
        }


class OrderedIntEnum(IntEnum):
    """Integer enum with name parsing."""

    @classmethod
    def parse(
        cls,
        value: Any,
        *,
        default: Any = None,
        strict: bool = True,
        field_name: Optional[str] = None,
    ) -> Optional["OrderedIntEnum"]:
        if isinstance(value, cls):
            return value
        if isinstance(value, str):
            token = _normalize_enum_token(value)
            for member in cls:
                if token == _normalize_enum_token(member.name):
                    return member
        try:
            if value is not None and str(value).strip():
                return cls(int(value))
        except (TypeError, ValueError):
            pass
        if default is not None:
            return cls.parse(default, field_name=field_name)
        if not strict:
            return None
        raise VisualizationValidationError(
            f"Unsupported {cls.__name__} value: {value!r}.",
            field_name=field_name or cls.__name__,
            value=value,
            expected=", ".join(member.name.lower() for member in cls),
        )

    @classmethod
    def values(cls) -> Tuple[int, ...]:
        return tuple(int(member.value) for member in cls)

    @property
    def label(self) -> str:
        return self.name.replace("_", " ").title()

    def to_dict(self) -> Dict[str, Any]:
        return {
            "enum": type(self).__name__,
            "name": self.name,
            "value": int(self.value),
            "label": self.label,
        }


