# 4.8. Registry and utilities
# -----------------------------------------------------------------------------

VisualizationEnum: TypeAlias = Union[TextEnum, OrderedIntEnum]
EnumClass: TypeAlias = type[Union[TextEnum, OrderedIntEnum]]

_VISUALIZATION_ENUM_CLASSES: Final[Tuple[EnumClass, ...]] = (
    VisualizationProfile, MolecularRole, MolecularRepresentation,
    SelectionKind, SelectionOperator, InteractionFamily, InteractionStrength,
    ConfidenceLevel, InteractionRenderMode, LineStyle, VisualLayer,
    PlanOperation, SceneResetMode, VisibilityMode, SurfaceMode, ColorMode,
    MarkerShape, VirtualPointKind, ResidueDisplayMode, HotspotLevel,
    HotspotRenderMode, ScoreTarget, ScorePaletteKind, ScoreNormalization,
    PoseDisplayMode, PoseColorMode, ConsensusMetric, PersistenceLevel,
    ComplementarityMode, LabelKind, LabelAnchor, LabelCollisionMode,
    CameraMode, StandardView, FramingTarget, SnapshotFormat,
    SnapshotBackground, ImageFitMode, CommandExportFormat, ExecutionMode,
    BackendKind, BackendState, ChimeraXCommandPolicy, CommandStatus,
    LifecycleState, DockModelIntegrationMode, ValidationMode,
    ErrorHandlingMode, ValidationIssueLevel, OperationPriority, SortDirection,
)

VISUALIZATION_ENUM_REGISTRY: Final[Mapping[str, EnumClass]] = MappingProxyType(
    {enum_class.__name__: enum_class for enum_class in _VISUALIZATION_ENUM_CLASSES}
)


def enum_values(enum_class: type[Enum]) -> Tuple[Any, ...]:
    """Return enum values."""

    if not isinstance(enum_class, type) or not issubclass(enum_class, Enum):
        raise VisualizationValidationError(
            "Expected an Enum class.",
            field_name="enum_class",
            value=repr(enum_class),
            expected="Enum subclass",
        )
    return tuple(member.value for member in enum_class)


def enum_names(enum_class: type[Enum]) -> Tuple[str, ...]:
    """Return enum names."""

    return tuple(member.name for member in enum_class)


def enum_choices(enum_class: type[Enum]) -> Tuple[str, ...]:
    """Return serialized enum choices."""

    return tuple(str(value) for value in enum_values(enum_class))


def parse_visualization_enum(
    enum_class: EnumClass,
    value: Any,
    *,
    default: Any = None,
    strict: bool = True,
    field_name: Optional[str] = None,
) -> Optional[VisualizationEnum]:
    """Parse a registered enum type."""

    if not isinstance(enum_class, type) or not issubclass(
        enum_class, (TextEnum, OrderedIntEnum)
    ):
        raise VisualizationValidationError(
            "Expected a visualization enum class.",
            field_name="enum_class",
            value=repr(enum_class),
            expected="TextEnum or OrderedIntEnum subclass",
        )
    return enum_class.parse(  # type: ignore[return-value]
        value, default=default, strict=strict, field_name=field_name
    )


def coerce_enum_sequence(
    enum_class: EnumClass,
    values: Optional[Iterable[Any]],
    *,
    strict: bool = True,
    unique: bool = True,
    field_name: Optional[str] = None,
) -> Tuple[VisualizationEnum, ...]:
    """Parse a stable enum sequence."""

    if values is None:
        return ()
    if isinstance(values, (str, bytes, Enum)):
        values = (values,)
    parsed: List[VisualizationEnum] = []
    seen: Set[VisualizationEnum] = set()
    for index, value in enumerate(values):
        member = parse_visualization_enum(
            enum_class,
            value,
            strict=strict,
            field_name=f"{field_name or enum_class.__name__}[{index}]",
        )
        if member is None or (unique and member in seen):
            continue
        parsed.append(member)
        seen.add(member)
    return tuple(parsed)


def enum_member_to_dict(member: Enum) -> Dict[str, Any]:
    """Serialize an enum member."""

    if not isinstance(member, Enum):
        raise VisualizationValidationError(
            "Expected an enum member.",
            field_name="member",
            value=repr(member),
            expected="Enum instance",
        )
    return {
        "enum": type(member).__name__,
        "name": member.name,
        "value": member.value,
        "label": str(getattr(member, "label", member.name.title())),
    }


def enum_class_to_dict(enum_class: type[Enum]) -> Dict[str, Any]:
    """Serialize an enum definition."""

    return {
        "name": enum_class.__name__,
        "module": enum_class.__module__,
        "members": [enum_member_to_dict(member) for member in enum_class],
    }


def is_enum_value(enum_class: EnumClass, value: Any) -> bool:
    """Return whether a value is accepted."""

    try:
        return parse_visualization_enum(enum_class, value, strict=False) is not None
    except (TypeError, ValueError, VisualizationError):
        return False


def get_visualization_enum(name: str) -> EnumClass:
    """Return a registered enum by normalized name."""

    token = _normalize_enum_token(name)
    for enum_name, enum_class in VISUALIZATION_ENUM_REGISTRY.items():
        if token == _normalize_enum_token(enum_name):
            return enum_class
    raise VisualizationValidationError(
        f"Unknown visualization enum: {name!r}.",
        field_name="name",
        value=name,
        expected=", ".join(VISUALIZATION_ENUM_REGISTRY),
    )


def describe_visualization_enums() -> Dict[str, Dict[str, Any]]:
    """Describe all registered enums."""

    return {
        name: enum_class_to_dict(enum_class)
        for name, enum_class in VISUALIZATION_ENUM_REGISTRY.items()
    }


def validate_visualization_enums() -> Tuple[str, ...]:
    """Validate uniqueness and constant alignment."""

    issues: List[str] = []
    for enum_class in _VISUALIZATION_ENUM_CLASSES:
        values = enum_values(enum_class)
        if len(values) != len(set(values)):
            issues.append(f"{enum_class.__name__} contains duplicate values.")
    aligned = (
        (VisualizationProfile, VISUALIZATION_PROFILES),
        (MolecularRole, MOLECULAR_ROLES),
        (MolecularRepresentation, MOLECULAR_REPRESENTATIONS),
        (InteractionFamily, INTERACTION_FAMILIES),
        (InteractionStrength, INTERACTION_STRENGTHS),
        (VisualLayer, DEFAULT_LAYER_ORDER),
        (HotspotLevel, HOTSPOT_LEVELS),
        (LabelKind, LABEL_KINDS),
        (CameraMode, CAMERA_MODES),
        (StandardView, STANDARD_VIEWS),
        (SnapshotFormat, SNAPSHOT_FORMATS),
        (CommandExportFormat, COMMAND_EXPORT_FORMATS),
    )
    for enum_class, expected in aligned:
        actual_set, expected_set = set(enum_values(enum_class)), set(expected)
        if actual_set != expected_set:
            issues.append(
                f"{enum_class.__name__} mismatch: "
                f"missing={sorted(expected_set - actual_set)}, "
                f"extra={sorted(actual_set - expected_set)}."
            )
    return tuple(issues)


