# 5.1. Normalization helpers
# -----------------------------------------------------------------------------

_BOOL_TRUE: Final[FrozenSet[str]] = frozenset({"1", "true", "yes", "on", "show", "enabled"})
_BOOL_FALSE: Final[FrozenSet[str]] = frozenset({"0", "false", "no", "off", "hide", "disabled"})


def _coerce_bool(value: Any, *, field_name: str) -> bool:
    """Coerce a strict boolean."""

    if isinstance(value, bool):
        return value
    if isinstance(value, Real) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        token = value.strip().lower()
        if token in _BOOL_TRUE:
            return True
        if token in _BOOL_FALSE:
            return False
    raise VisualizationConfigurationError(
        f"Invalid boolean for {field_name}: {value!r}.",
        context={"field": field_name, "value": repr(value)},
    )


def _bounded_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> float:
    """Coerce a finite bounded float."""

    if isinstance(value, bool) or not isinstance(value, Real):
        raise VisualizationConfigurationError(
            f"Expected a number for {field_name}.",
            context={"field": field_name, "value": repr(value)},
        )
    result = float(value)
    if not math.isfinite(result):
        raise VisualizationConfigurationError(
            f"Expected a finite number for {field_name}.",
            context={"field": field_name, "value": repr(value)},
        )
    if minimum is not None and result < minimum:
        raise VisualizationConfigurationError(
            f"{field_name} must be >= {minimum}.",
            context={"field": field_name, "value": result},
        )
    if maximum is not None and result > maximum:
        raise VisualizationConfigurationError(
            f"{field_name} must be <= {maximum}.",
            context={"field": field_name, "value": result},
        )
    return result


def _bounded_int(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[int] = None,
    maximum: Optional[int] = None,
) -> int:
    """Coerce a bounded integer."""

    if isinstance(value, bool):
        raise VisualizationConfigurationError(
            f"Expected an integer for {field_name}.",
            context={"field": field_name, "value": repr(value)},
        )
    try:
        result = int(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise VisualizationConfigurationError(
            f"Expected an integer for {field_name}.",
            context={"field": field_name, "value": repr(value)},
            cause=exc,
        ) from exc
    if isinstance(value, Real) and float(value) != float(result):
        raise VisualizationConfigurationError(
            f"Expected an integral value for {field_name}.",
            context={"field": field_name, "value": repr(value)},
        )
    if minimum is not None and result < minimum:
        raise VisualizationConfigurationError(
            f"{field_name} must be >= {minimum}.",
            context={"field": field_name, "value": result},
        )
    if maximum is not None and result > maximum:
        raise VisualizationConfigurationError(
            f"{field_name} must be <= {maximum}.",
            context={"field": field_name, "value": result},
        )
    return result


def _clean_config_name(value: Any, *, field_name: str, maximum: int) -> str:
    """Normalize a bounded display name."""

    text = str(value).strip()
    if not text:
        raise VisualizationConfigurationError(
            f"{field_name} cannot be empty.", context={"field": field_name}
        )
    if len(text) > maximum:
        raise VisualizationConfigurationError(
            f"{field_name} exceeds {maximum} characters.",
            context={"field": field_name, "length": len(text)},
        )
    if not re.fullmatch(SAFE_GROUP_NAME_PATTERN, text):
        raise VisualizationConfigurationError(
            f"Unsafe characters in {field_name}.",
            context={"field": field_name, "value": text},
        )
    return text


def _normalize_color_channel(value: Any, *, field_name: str) -> int:
    """Convert one color channel to a byte."""

    channel = _bounded_float(value, field_name=field_name, minimum=0.0, maximum=255.0)
    if channel <= 1.0:
        channel *= 255.0
    return int(round(channel))


def normalize_color(value: ColorLike, *, field_name: str = "color") -> str:
    """Normalize a color to uppercase hexadecimal."""

    if isinstance(value, str):
        token = value.strip()
        alias = COLOR_ALIASES.get(token.lower())
        if alias:
            return alias.upper()
        if re.fullmatch(r"#[0-9A-Fa-f]{3}", token):
            return "#" + "".join(character * 2 for character in token[1:]).upper()
        if re.fullmatch(r"#[0-9A-Fa-f]{4}", token):
            return "#" + "".join(character * 2 for character in token[1:]).upper()
        if re.fullmatch(HEX_COLOR_PATTERN, token):
            return token.upper()
        match = re.fullmatch(
            r"rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)"
            r"(?:\s*,\s*([0-9.]+)\s*)?\)",
            token,
            flags=re.IGNORECASE,
        )
        if match:
            rgb = [
                int(round(_bounded_float(float(match.group(index)), field_name=f"{field_name}[{index - 1}]", minimum=0.0, maximum=255.0)))
                for index in (1, 2, 3)
            ]
            if match.group(4) is None:
                return "#" + "".join(f"{channel:02X}" for channel in rgb)
            alpha_value = float(match.group(4))
            alpha = _normalize_color_channel(alpha_value, field_name=f"{field_name}[3]")
            return "#" + "".join(f"{channel:02X}" for channel in (*rgb, alpha))
        else:
            raise VisualizationColorError(
                f"Unsupported color value: {value!r}.",
                context={"field": field_name, "value": value},
            )

    if isinstance(value, Mapping):
        lowered = {str(key).lower(): item for key, item in value.items()}
        if not {"r", "g", "b"}.issubset(lowered):
            raise VisualizationColorError(
                "Color mapping requires r, g and b channels.",
                context={"field": field_name, "keys": tuple(lowered)},
            )
        value = [lowered["r"], lowered["g"], lowered["b"]]
        if "a" in lowered:
            value.append(lowered["a"])

    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        channels = list(value)
        if len(channels) not in (3, 4):
            raise VisualizationColorError(
                "Color sequences require three or four channels.",
                context={"field": field_name, "length": len(channels)},
            )
        normalized = [
            _normalize_color_channel(channel, field_name=f"{field_name}[{index}]")
            for index, channel in enumerate(channels)
        ]
        return "#" + "".join(f"{channel:02X}" for channel in normalized)

    raise VisualizationColorError(
        f"Unsupported color value: {value!r}.",
        context={"field": field_name, "value": repr(value)},
    )


def color_to_rgba(value: ColorLike) -> RGBATuple:
    """Return normalized RGBA channels."""

    color = normalize_color(value)
    if len(color) == 7:
        color += "FF"
    channels = tuple(int(color[index:index + 2], 16) / 255.0 for index in range(1, 9, 2))
    return channels  # type: ignore[return-value]


def color_with_opacity(value: ColorLike, opacity: Number) -> str:
    """Apply an alpha channel."""

    color = normalize_color(value)[:7]
    alpha = round(_bounded_float(opacity, field_name="opacity", minimum=0.0, maximum=1.0) * 255)
    return f"{color}{alpha:02X}"


def blend_colors(first: ColorLike, second: ColorLike, fraction: Number = 0.5) -> str:
    """Blend two colors in RGB space."""

    position = _bounded_float(fraction, field_name="fraction", minimum=0.0, maximum=1.0)
    left = color_to_rgba(first)
    right = color_to_rgba(second)
    channels = tuple(left[index] + (right[index] - left[index]) * position for index in range(4))
    return normalize_color(channels)


def contrast_color(value: ColorLike) -> str:
    """Return black or white for readable contrast."""

    red, green, blue, _ = color_to_rgba(value)
    luminance = 0.2126 * red + 0.7152 * green + 0.0722 * blue
    return COLOR_BLACK if luminance > 0.55 else COLOR_WHITE


def _normalize_color_mapping(
    values: Mapping[Any, ColorLike],
    *,
    enum_class: Optional[EnumClass] = None,
    field_name: str,
) -> Mapping[Any, str]:
    """Normalize color-map keys and values."""

    normalized: Dict[Any, str] = {}
    for key, color in values.items():
        parsed_key: Any = key
        if enum_class is not None:
            parsed_key = parse_visualization_enum(
                enum_class, key, field_name=f"{field_name}.key"
            )
        normalized[parsed_key] = normalize_color(color, field_name=f"{field_name}[{key}]")
    return MappingProxyType(normalized)


def _normalize_float_mapping(
    values: Mapping[Any, Number],
    *,
    enum_class: Optional[EnumClass] = None,
    field_name: str,
    minimum: float = 0.0,
) -> Mapping[Any, float]:
    """Normalize a numeric map."""

    normalized: Dict[Any, float] = {}
    for key, number in values.items():
        parsed_key: Any = key
        if enum_class is not None:
            parsed_key = parse_visualization_enum(
                enum_class, key, field_name=f"{field_name}.key"
            )
        normalized[parsed_key] = _bounded_float(
            number, field_name=f"{field_name}[{key}]", minimum=minimum
        )
    return MappingProxyType(normalized)


def _coerce_vector3(value: VectorLike, *, field_name: str, normalize: bool = False) -> Vector3D:
    """Coerce a three-dimensional vector."""

    if isinstance(value, Mapping):
        lowered = {str(key).lower(): item for key, item in value.items()}
        value = (lowered.get("x"), lowered.get("y"), lowered.get("z"))
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)) or len(value) != 3:
        raise VisualizationCoordinateError(
            f"{field_name} requires three coordinates.",
            context={"field": field_name, "value": repr(value)},
        )
    vector = tuple(
        _bounded_float(component, field_name=f"{field_name}[{index}]")
        for index, component in enumerate(value)
    )
    if normalize:
        magnitude = math.sqrt(sum(component * component for component in vector))
        if magnitude <= VISUALIZATION_COORDINATE_EPSILON:
            raise VisualizationCoordinateError(
                f"{field_name} cannot be a zero vector.", context={"field": field_name}
            )
        vector = tuple(component / magnitude for component in vector)
    return vector  # type: ignore[return-value]


# 5.2. Serialization mixin
# -----------------------------------------------------------------------------


def _config_value_to_dict(value: Any) -> Any:
    """Convert configuration values to JSON-safe data."""

    if isinstance(value, Enum):
        return value.value
    if is_dataclass(value):
        return {
            item.name: _config_value_to_dict(getattr(value, item.name))
            for item in fields(value)
            if not item.name.startswith("_")
        }
    if isinstance(value, Mapping):
        return {
            str(key.value if isinstance(key, Enum) else key): _config_value_to_dict(item)
            for key, item in value.items()
        }
    if isinstance(value, (tuple, list, set, frozenset)):
        return [_config_value_to_dict(item) for item in value]
    if isinstance(value, Path):
        return str(value)
    return value


class VisualConfigMixin:
    """Shared immutable-config helpers."""

    def to_dict(self) -> Dict[str, Any]:
        """Serialize the configuration."""

        return _config_value_to_dict(self)

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        """Serialize the configuration as JSON."""

        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False, sort_keys=True)

    def copy_with(self: ConfigT, **changes: Any) -> ConfigT:
        """Return a modified copy."""

        return replace(self, **changes)


