        object.__setattr__(self, "bond_radius", _bounded_float(self.bond_radius, field_name="bond_radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
        object.__setattr__(self, "ball_scale", _bounded_float(self.ball_scale, field_name="ball_scale", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
