        object.__setattr__(self, "complementarity_mode", ComplementarityMode.parse(self.complementarity_mode, field_name="complementarity_mode"))
        object.__setattr__(self, "complementarity_set_size", _bounded_int(self.complementarity_set_size, field_name="complementarity_set_size", minimum=1, maximum=MAX_VISUAL_ELEMENTS))
        object.__setattr__(self, "pose_colors", tuple(normalize_color(color, field_name="pose_colors") for color in self.pose_colors))
