@dataclass(frozen=True)
class LabelStyleConfig(VisualConfigMixin):
    """Label rendering defaults."""

    enabled: bool = DEFAULT_SHOW_LABELS
    kinds: Tuple[LabelKind, ...] = (LabelKind.RESIDUE, LabelKind.INTERACTION)
    anchor: LabelAnchor = LabelAnchor.POINT
    collision: LabelCollisionMode = LabelCollisionMode.AUTO
    font: str = DEFAULT_LABEL_FONT
    font_size: int = DEFAULT_LABEL_FONT_SIZE
    color: str = DEFAULT_LABEL_COLOR
    opacity: float = DEFAULT_LABEL_OPACITY
    offset: Vector3D = DEFAULT_LABEL_OFFSET
    distance_template: str = DEFAULT_LABEL_DISTANCE_TEMPLATE
    score_template: str = DEFAULT_LABEL_SCORE_TEMPLATE
    residue_template: str = DEFAULT_LABEL_RESIDUE_TEMPLATE
    max_labels: int = 250

    def __post_init__(self) -> None:
        object.__setattr__(self, "enabled", _coerce_bool(self.enabled, field_name="enabled"))
        object.__setattr__(self, "kinds", tuple(coerce_enum_sequence(LabelKind, self.kinds, field_name="kinds")))
        object.__setattr__(self, "anchor", LabelAnchor.parse(self.anchor, field_name="anchor"))
        object.__setattr__(self, "collision", LabelCollisionMode.parse(self.collision, field_name="collision"))
        font = str(self.font).strip()
        if not font:
            raise VisualizationConfigurationError("Label font cannot be empty.")
        object.__setattr__(self, "font", font)
        object.__setattr__(self, "font_size", _bounded_int(self.font_size, field_name="font_size", minimum=1, maximum=512))
        object.__setattr__(self, "color", normalize_color(self.color, field_name="color"))
        object.__setattr__(self, "opacity", _bounded_float(self.opacity, field_name="opacity", minimum=0.0, maximum=1.0))
        object.__setattr__(self, "offset", _coerce_vector3(self.offset, field_name="offset"))
        for name in ("distance_template", "score_template", "residue_template"):
            text = str(getattr(self, name))
            if len(text) > MAX_LABEL_TEXT_LENGTH:
                raise VisualizationConfigurationError(f"{name} exceeds the label limit.")
            object.__setattr__(self, name, text)
        object.__setattr__(self, "max_labels", _bounded_int(self.max_labels, field_name="max_labels", minimum=0, maximum=MAX_VISUAL_ELEMENTS))


@dataclass(frozen=True)
class CameraStyleConfig(VisualConfigMixin):
    """Camera and framing defaults."""

    mode: CameraMode = CameraMode.ORTHOGRAPHIC
    view: StandardView = StandardView.AUTO
    framing_target: FramingTarget = FramingTarget.INTERACTIONS
    field_of_view: float = DEFAULT_CAMERA_FIELD_OF_VIEW
    padding: float = DEFAULT_CAMERA_PADDING
    zoom: float = DEFAULT_CAMERA_ZOOM
    direction: Vector3D = DEFAULT_CAMERA_DIRECTION
    up: Vector3D = DEFAULT_CAMERA_UP
    center_of_rotation: bool = True
    clip: bool = False

    def __post_init__(self) -> None:
        object.__setattr__(self, "mode", CameraMode.parse(self.mode, field_name="mode"))
        object.__setattr__(self, "view", StandardView.parse(self.view, field_name="view"))
        object.__setattr__(self, "framing_target", FramingTarget.parse(self.framing_target, field_name="framing_target"))
        object.__setattr__(self, "field_of_view", _bounded_float(self.field_of_view, field_name="field_of_view", minimum=1.0, maximum=179.0))
        object.__setattr__(self, "padding", _bounded_float(self.padding, field_name="padding", minimum=0.0, maximum=10.0))
        object.__setattr__(self, "zoom", _bounded_float(self.zoom, field_name="zoom", minimum=VISUALIZATION_EPSILON, maximum=1000.0))
        object.__setattr__(self, "direction", _coerce_vector3(self.direction, field_name="direction", normalize=True))
        object.__setattr__(self, "up", _coerce_vector3(self.up, field_name="up", normalize=True))
        dot = sum(left * right for left, right in zip(self.direction, self.up))
        if abs(dot) > 1.0 - VISUALIZATION_COORDINATE_EPSILON:
            raise VisualizationConfigurationError("Camera direction and up vectors cannot be parallel.")
        object.__setattr__(self, "center_of_rotation", _coerce_bool(self.center_of_rotation, field_name="center_of_rotation"))
        object.__setattr__(self, "clip", _coerce_bool(self.clip, field_name="clip"))


# 5.6. Snapshot, scene and backend settings
# -----------------------------------------------------------------------------

@dataclass(frozen=True)
class SnapshotStyleConfig(VisualConfigMixin):
    """Snapshot output defaults."""

    format: SnapshotFormat = SnapshotFormat.PNG
    width: int = DEFAULT_SNAPSHOT_WIDTH
    height: int = DEFAULT_SNAPSHOT_HEIGHT
    supersample: int = DEFAULT_SNAPSHOT_SUPERSAMPLE
    quality: int = DEFAULT_SNAPSHOT_QUALITY
    dpi: int = DEFAULT_SNAPSHOT_DPI
    background: SnapshotBackground = SnapshotBackground.OPAQUE
    fit_mode: ImageFitMode = ImageFitMode.CONTAIN
    transparent: bool = DEFAULT_SNAPSHOT_TRANSPARENT
    filename: str = DEFAULT_SNAPSHOT_FILENAME

    def __post_init__(self) -> None:
        object.__setattr__(self, "format", SnapshotFormat.parse(self.format, field_name="format"))
        object.__setattr__(self, "width", _bounded_int(self.width, field_name="width", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION))
        object.__setattr__(self, "height", _bounded_int(self.height, field_name="height", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION))
        object.__setattr__(self, "supersample", _bounded_int(self.supersample, field_name="supersample", minimum=1, maximum=16))
        object.__setattr__(self, "quality", _bounded_int(self.quality, field_name="quality", minimum=1, maximum=100))
        object.__setattr__(self, "dpi", _bounded_int(self.dpi, field_name="dpi", minimum=1, maximum=2400))
        object.__setattr__(self, "background", SnapshotBackground.parse(self.background, field_name="background"))
        object.__setattr__(self, "fit_mode", ImageFitMode.parse(self.fit_mode, field_name="fit_mode"))
        object.__setattr__(self, "transparent", _coerce_bool(self.transparent, field_name="transparent"))
        filename = Path(str(self.filename).strip()).name
        if not filename:
            raise VisualizationConfigurationError("Snapshot filename cannot be empty.")
        expected = self.format.extension
        if Path(filename).suffix.lower() not in {expected, ".jpg" if expected == ".jpeg" else expected}:
            filename = str(Path(filename).with_suffix(expected))
        object.__setattr__(self, "filename", filename)

    @property
    def pixel_count(self) -> int:
        """Return output pixels before supersampling."""

        return self.width * self.height


@dataclass(frozen=True)
class SceneStyleConfig(VisualConfigMixin):
    """Global scene defaults."""

    reset_mode: SceneResetMode = SceneResetMode.VISUALIZATION
    background: str = DEFAULT_BACKGROUND_COLOR
    foreground: str = DEFAULT_FOREGROUND_COLOR
    clear_selection: bool = DEFAULT_CLEAR_SELECTION
    hide_nonfocus_atoms: bool = DEFAULT_HIDE_NONFOCUS_ATOMS
    hide_solvent: bool = DEFAULT_HIDE_SOLVENT
    hide_ions: bool = DEFAULT_HIDE_IONS
    hide_hydrogens: bool = DEFAULT_HIDE_HYDROGENS
    show_receptor: bool = DEFAULT_SHOW_RECEPTOR
    show_ligand: bool = DEFAULT_SHOW_LIGAND
    show_interactions: bool = DEFAULT_SHOW_INTERACTIONS
    show_residues: bool = DEFAULT_SHOW_RESIDUES
    focus_distance: float = DEFAULT_FOCUS_DISTANCE
    context_distance: float = DEFAULT_CONTEXT_DISTANCE
    lighting: str = DEFAULT_CHIMERAX_LIGHTING
    silhouettes: bool = DEFAULT_CHIMERAX_SILHOUETTES
    layer_order: Tuple[VisualLayer, ...] = tuple(VisualLayer.parse(layer) for layer in DEFAULT_LAYER_ORDER)

    def __post_init__(self) -> None:
        object.__setattr__(self, "reset_mode", SceneResetMode.parse(self.reset_mode, field_name="reset_mode"))
        object.__setattr__(self, "background", normalize_color(self.background, field_name="background"))
        object.__setattr__(self, "foreground", normalize_color(self.foreground, field_name="foreground"))
        for name in (
            "clear_selection", "hide_nonfocus_atoms", "hide_solvent", "hide_ions",
            "hide_hydrogens", "show_receptor", "show_ligand", "show_interactions",
            "show_residues", "silhouettes",
        ):
            object.__setattr__(self, name, _coerce_bool(getattr(self, name), field_name=name))
        object.__setattr__(self, "focus_distance", _bounded_float(self.focus_distance, field_name="focus_distance", minimum=0.0, maximum=MAX_RADIUS))
        object.__setattr__(self, "context_distance", _bounded_float(self.context_distance, field_name="context_distance", minimum=0.0, maximum=MAX_RADIUS))
        if self.context_distance < self.focus_distance:
            raise VisualizationConfigurationError("Context distance must be >= focus distance.")
        lighting = str(self.lighting).strip().lower()
        if not lighting:
            raise VisualizationConfigurationError("Lighting mode cannot be empty.")
        object.__setattr__(self, "lighting", lighting)
        layers = tuple(coerce_enum_sequence(VisualLayer, self.layer_order, field_name="layer_order"))
        if not layers:
            raise VisualizationConfigurationError("Scene layer order cannot be empty.")
        object.__setattr__(self, "layer_order", layers)


@dataclass(frozen=True)
class BackendConfig(VisualConfigMixin):
    """Backend and execution defaults."""

    kind: BackendKind = BackendKind.CHIMERAX
    execution_mode: ExecutionMode = ExecutionMode.DEFERRED
    validation_mode: ValidationMode = ValidationMode.NORMAL
    error_handling: ErrorHandlingMode = ErrorHandlingMode.RAISE
    command_policy: ChimeraXCommandPolicy = ChimeraXCommandPolicy.SAFE
    wait_frames: int = DEFAULT_CHIMERAX_WAIT_FRAMES
    log_commands: bool = DEFAULT_CHIMERAX_LOG_COMMANDS
    batch_size: int = DEFAULT_COMMAND_BATCH_SIZE
    max_command_length: int = DEFAULT_COMMAND_MAX_LENGTH

    def __post_init__(self) -> None:
        object.__setattr__(self, "kind", BackendKind.parse(self.kind, field_name="kind"))
        object.__setattr__(self, "execution_mode", ExecutionMode.parse(self.execution_mode, field_name="execution_mode"))
        object.__setattr__(self, "validation_mode", ValidationMode.parse(self.validation_mode, field_name="validation_mode"))
        object.__setattr__(self, "error_handling", ErrorHandlingMode.parse(self.error_handling, field_name="error_handling"))
        object.__setattr__(self, "command_policy", ChimeraXCommandPolicy.parse(self.command_policy, field_name="command_policy"))
        object.__setattr__(self, "wait_frames", _bounded_int(self.wait_frames, field_name="wait_frames", minimum=0, maximum=100000))
        object.__setattr__(self, "log_commands", _coerce_bool(self.log_commands, field_name="log_commands"))
        object.__setattr__(self, "batch_size", _bounded_int(self.batch_size, field_name="batch_size", minimum=1, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "max_command_length", _bounded_int(self.max_command_length, field_name="max_command_length", minimum=1, maximum=MAX_SELECTION_LENGTH))


# 5.7. Aggregate configuration
# -----------------------------------------------------------------------------


def _default_molecular_styles() -> Mapping[MolecularRole, MolecularStyleConfig]:
    """Build default role styles."""

    styles = {
        MolecularRole.RECEPTOR: MolecularStyleConfig(MolecularRole.RECEPTOR, MolecularRepresentation.parse(DEFAULT_RECEPTOR_REPRESENTATION), DEFAULT_RECEPTOR_COLOR),
        MolecularRole.LIGAND: MolecularStyleConfig(MolecularRole.LIGAND, MolecularRepresentation.parse(DEFAULT_LIGAND_REPRESENTATION), DEFAULT_LIGAND_COLOR),
        MolecularRole.COFACTOR: MolecularStyleConfig(MolecularRole.COFACTOR, MolecularRepresentation.parse(DEFAULT_COFACTOR_REPRESENTATION), DEFAULT_COFACTOR_COLOR),
        MolecularRole.SOLVENT: MolecularStyleConfig(MolecularRole.SOLVENT, MolecularRepresentation.parse(DEFAULT_SOLVENT_REPRESENTATION), DEFAULT_SOLVENT_COLOR, opacity=0.45, visible=not DEFAULT_HIDE_SOLVENT),
        MolecularRole.ION: MolecularStyleConfig(MolecularRole.ION, MolecularRepresentation.parse(DEFAULT_ION_REPRESENTATION), DEFAULT_ION_COLOR, visible=not DEFAULT_HIDE_IONS),
    }
    return MappingProxyType(styles)


def _normalize_molecular_styles(values: Mapping[Any, Any]) -> Mapping[MolecularRole, MolecularStyleConfig]:
    """Normalize role-style mappings."""

    normalized: Dict[MolecularRole, MolecularStyleConfig] = {}
    for key, value in values.items():
        role = MolecularRole.parse(key, field_name="molecular_styles.key")
        if isinstance(value, MolecularStyleConfig):
            style = value if value.role is role else value.copy_with(role=role)
        elif isinstance(value, Mapping):
            style = MolecularStyleConfig(role=role, **dict(value))
        else:
            raise VisualizationConfigurationError(
                "Molecular styles must be MolecularStyleConfig instances or mappings.",
                context={"role": role.value, "value": repr(value)},
            )
        normalized[role] = style
    return MappingProxyType(normalized)


@dataclass(frozen=True)
class VisualizationConfig(VisualConfigMixin):
    """Complete visualization configuration."""

    name: str = DEFAULT_VISUALIZATION_NAME
    scene_name: str = DEFAULT_SCENE_NAME
    profile: VisualizationProfile = VisualizationProfile.PUBLICATION
    palette: ColorPaletteConfig = field(default_factory=ColorPaletteConfig)
    molecular_styles: Mapping[MolecularRole, MolecularStyleConfig] = field(default_factory=_default_molecular_styles)
    interactions: InteractionStyleConfig = field(default_factory=InteractionStyleConfig)
    hotspots: HotspotStyleConfig = field(default_factory=HotspotStyleConfig)
    scoring: ScoreStyleConfig = field(default_factory=ScoreStyleConfig)
    multipose: MultiposeStyleConfig = field(default_factory=MultiposeStyleConfig)
    labels: LabelStyleConfig = field(default_factory=LabelStyleConfig)
    camera: CameraStyleConfig = field(default_factory=CameraStyleConfig)
    snapshot: SnapshotStyleConfig = field(default_factory=SnapshotStyleConfig)
    scene: SceneStyleConfig = field(default_factory=SceneStyleConfig)
    backend: BackendConfig = field(default_factory=BackendConfig)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", _clean_config_name(self.name, field_name="name", maximum=MAX_VISUALIZATION_NAME_LENGTH))
        object.__setattr__(self, "scene_name", _clean_config_name(self.scene_name, field_name="scene_name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "profile", VisualizationProfile.parse(self.profile, field_name="profile"))
        object.__setattr__(self, "palette", _coerce_config_object(ColorPaletteConfig, self.palette, "palette"))
        object.__setattr__(self, "molecular_styles", _normalize_molecular_styles(self.molecular_styles))
        object.__setattr__(self, "interactions", _coerce_config_object(InteractionStyleConfig, self.interactions, "interactions"))
        object.__setattr__(self, "hotspots", _coerce_config_object(HotspotStyleConfig, self.hotspots, "hotspots"))
        object.__setattr__(self, "scoring", _coerce_config_object(ScoreStyleConfig, self.scoring, "scoring"))
        object.__setattr__(self, "multipose", _coerce_config_object(MultiposeStyleConfig, self.multipose, "multipose"))
        object.__setattr__(self, "labels", _coerce_config_object(LabelStyleConfig, self.labels, "labels"))
        object.__setattr__(self, "camera", _coerce_config_object(CameraStyleConfig, self.camera, "camera"))
        object.__setattr__(self, "snapshot", _coerce_config_object(SnapshotStyleConfig, self.snapshot, "snapshot"))
        object.__setattr__(self, "scene", _coerce_config_object(SceneStyleConfig, self.scene, "scene"))
        object.__setattr__(self, "backend", _coerce_config_object(BackendConfig, self.backend, "backend"))
        metadata = dict(self.metadata or {})
        metadata.setdefault("schema", VISUALIZATION_SCHEMA_NAME)
        metadata.setdefault("schema_version", VISUALIZATION_SCHEMA_VERSION)
        object.__setattr__(self, "metadata", MappingProxyType(metadata))

    def style_for(self, role: Any) -> MolecularStyleConfig:
        """Resolve a molecular role style."""

        parsed = MolecularRole.parse(role, default=MolecularRole.UNKNOWN, strict=False)
        style = self.molecular_styles.get(parsed)
        if style is not None:
            return style
        return MolecularStyleConfig(
            parsed,
            MolecularRepresentation.STICKS,
            self.palette.color_for_role(parsed),
        )

    def fingerprint(self) -> str:
        """Return a stable configuration digest."""

        payload = json.dumps(self.to_dict(), ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        return sha256(payload.encode(VISUALIZATION_TEXT_ENCODING)).hexdigest()


_CONFIG_TYPES: Final[Tuple[type, ...]] = (
    MolecularStyleConfig,
    ColorPaletteConfig,
    InteractionStyleConfig,
    HotspotStyleConfig,
    ScoreStyleConfig,
    MultiposeStyleConfig,
    LabelStyleConfig,
    CameraStyleConfig,
    SnapshotStyleConfig,
    SceneStyleConfig,
    BackendConfig,
    VisualizationConfig,
)


def _coerce_config_object(config_class: type[ConfigT], value: Any, field_name: str) -> ConfigT:
    """Coerce a nested configuration object."""

    if isinstance(value, config_class):
        return value
    if isinstance(value, Mapping):
        try:
            return config_class(**dict(value))
        except VisualizationError:
            raise
        except Exception as exc:
            raise VisualizationConfigurationError(
                f"Invalid {field_name} configuration.",
                context={"field": field_name},
                cause=exc,
            ) from exc
    raise VisualizationConfigurationError(
        f"Invalid {field_name} configuration type.",
        context={"field": field_name, "value": type(value).__name__},
    )


