def build_visualization_config(
    profile: Any = DEFAULT_VISUALIZATION_PROFILE,
    *,
    name: str = DEFAULT_VISUALIZATION_NAME,
    scene_name: str = DEFAULT_SCENE_NAME,
    overrides: Optional[Mapping[str, Any]] = None,
) -> VisualizationConfig:
    """Build a profile-based visualization configuration."""

    parsed = VisualizationProfile.parse(profile, field_name="profile")
    preset = _PROFILE_OVERRIDES[parsed]
    palette = ColorPaletteConfig()
    styles = dict(_default_molecular_styles())
    styles[MolecularRole.RECEPTOR] = styles[MolecularRole.RECEPTOR].copy_with(
        representation=preset["receptor_representation"]
    )
    styles[MolecularRole.LIGAND] = styles[MolecularRole.LIGAND].copy_with(
        representation=preset["ligand_representation"]
    )
    width, height = preset["snapshot_size"]
    config_value = VisualizationConfig(
        name=name,
        scene_name=scene_name,
        profile=parsed,
        palette=palette,
        molecular_styles=styles,
        interactions=InteractionStyleConfig(max_count=preset["max_interactions"]),
        hotspots=HotspotStyleConfig(enabled=preset["hotspots"]),
        scoring=ScoreStyleConfig(enabled=preset["scoring"]),
        labels=LabelStyleConfig(enabled=preset["labels"], font_size=28 if parsed is VisualizationProfile.PRESENTATION else DEFAULT_LABEL_FONT_SIZE),
        snapshot=SnapshotStyleConfig(width=width, height=height),
        scene=SceneStyleConfig(show_residues=preset["show_residues"]),
    )
    return merge_visualization_config(config_value, overrides) if overrides else config_value


def visualization_config_from_mapping(values: Mapping[str, Any]) -> VisualizationConfig:
    """Build a configuration from nested mapping data."""

    if not isinstance(values, Mapping):
        raise VisualizationConfigurationError("Visualization configuration must be a mapping.")
    data = dict(values)
    profile = data.pop("profile", DEFAULT_VISUALIZATION_PROFILE)
    base = build_visualization_config(
        profile,
        name=data.pop("name", DEFAULT_VISUALIZATION_NAME),
        scene_name=data.pop("scene_name", DEFAULT_SCENE_NAME),
    )
    return merge_visualization_config(base, data)


def merge_visualization_config(
    base: VisualizationConfig,
    overrides: Optional[Mapping[str, Any]],
) -> VisualizationConfig:
    """Merge shallow and nested configuration overrides."""

    if overrides is None:
        return base
    if not isinstance(base, VisualizationConfig):
        raise VisualizationConfigurationError("Base must be VisualizationConfig.")
    if not isinstance(overrides, Mapping):
        raise VisualizationConfigurationError("Configuration overrides must be a mapping.")

    changes: Dict[str, Any] = {}
    field_names = {item.name for item in fields(VisualizationConfig)}
    for key, value in overrides.items():
        if key not in field_names:
            raise VisualizationConfigurationError(
                f"Unknown visualization configuration field: {key!r}.",
                context={"field": key},
            )
        current = getattr(base, key)
        if is_dataclass(current) and isinstance(value, Mapping):
            allowed = {item.name for item in fields(current)}
            unknown = set(value) - allowed
            if unknown:
                raise VisualizationConfigurationError(
                    f"Unknown fields for {key}: {sorted(unknown)}.",
                    context={"field": key, "unknown": sorted(unknown)},
                )
            changes[key] = replace(current, **dict(value))
        elif key == "molecular_styles" and isinstance(value, Mapping):
            styles = dict(base.molecular_styles)
            for role_key, role_value in value.items():
                role = MolecularRole.parse(role_key, field_name="molecular_styles.key")
                current_style = styles.get(role)
                if current_style is not None and isinstance(role_value, Mapping):
                    styles[role] = replace(current_style, **dict(role_value))
                else:
                    styles[role] = role_value
            changes[key] = styles
        elif key == "metadata" and isinstance(value, Mapping):
            metadata = dict(base.metadata)
            metadata.update(value)
            changes[key] = metadata
        else:
            changes[key] = value
    return replace(base, **changes)


def resolve_visualization_config(value: Any = None, *, profile: Any = None) -> VisualizationConfig:
    """Resolve configuration-like input."""

    if value is None:
        return build_visualization_config(profile or DEFAULT_VISUALIZATION_PROFILE)
    if isinstance(value, VisualizationConfig):
        if profile is None:
            return value
        return build_visualization_config(profile, overrides=value.to_dict())
    if isinstance(value, Mapping):
        data = dict(value)
        if profile is not None:
            data["profile"] = profile
        return visualization_config_from_mapping(data)
    if isinstance(value, (str, VisualizationProfile)) and profile is None:
        return build_visualization_config(value)
    raise VisualizationConfigurationError(
        "Unsupported visualization configuration input.",
        context={"value": type(value).__name__},
    )


# 5.9. Validation and introspection
# -----------------------------------------------------------------------------


def validate_visualization_config(
    config_value: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[str, ...]:
    """Validate cross-field configuration constraints."""

    issues: List[str] = []
    try:
        resolved = resolve_visualization_config(config_value)
    except VisualizationError as exc:
        if raise_on_error:
            raise
        return (str(exc),)

    required_roles = {MolecularRole.RECEPTOR, MolecularRole.LIGAND}
    missing_roles = required_roles - set(resolved.molecular_styles)
    if missing_roles:
        issues.append("Missing molecular styles: " + ", ".join(sorted(role.value for role in missing_roles)))
    if resolved.scene.show_interactions and resolved.interactions.max_count == 0:
        issues.append("Interactions are enabled but max_count is zero.")
    if resolved.hotspots.enabled and resolved.hotspots.max_count == 0:
        issues.append("Hotspots are enabled but max_count is zero.")
    if resolved.labels.enabled and resolved.labels.max_labels == 0:
        issues.append("Labels are enabled but max_labels is zero.")
    if resolved.snapshot.transparent and resolved.snapshot.format is SnapshotFormat.JPEG:
        issues.append("JPEG snapshots do not support transparency.")
    if resolved.backend.execution_mode is ExecutionMode.IMMEDIATE and resolved.backend.kind is BackendKind.NONE:
        issues.append("Immediate execution requires an active backend.")
    if resolved.multipose.complementarity_set_size > resolved.multipose.max_visible_poses:
        issues.append("Complementarity set size exceeds max_visible_poses.")

    if issues and raise_on_error:
        raise VisualizationValidationError(
            "Invalid visualization configuration.",
            field_name="config",
            value=resolved.to_dict(),
            expected="; ".join(issues),
        )
    return tuple(issues)


def visualization_config_to_dict(config_value: Any) -> Dict[str, Any]:
    """Serialize configuration-like input."""

    return resolve_visualization_config(config_value).to_dict()


def visualization_config_to_json(config_value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize configuration-like input as JSON."""

    return json.dumps(
        visualization_config_to_dict(config_value),
        indent=indent,
        ensure_ascii=False,
        sort_keys=True,
    )


def visualization_config_fingerprint(config_value: Any) -> str:
    """Return a stable configuration digest."""

    return resolve_visualization_config(config_value).fingerprint()


def describe_visualization_profile(profile: Any) -> Dict[str, Any]:
    """Describe a named visual profile."""

    parsed = VisualizationProfile.parse(profile, field_name="profile")
    config_value = build_visualization_config(parsed)
    return {
        "profile": parsed.value,
        "overrides": _config_value_to_dict(_PROFILE_OVERRIDES[parsed]),
        "fingerprint": config_value.fingerprint(),
        "config": config_value.to_dict(),
    }


DEFAULT_VISUALIZATION_CONFIG: Final[VisualizationConfig] = build_visualization_config()
VISUALIZATION_PROFILE_CONFIGS: Final[Mapping[VisualizationProfile, VisualizationConfig]] = MappingProxyType(
    {profile: build_visualization_config(profile) for profile in VisualizationProfile}
)


