# 6.1. Generic normalization
# -----------------------------------------------------------------------------

_MISSING_SPEC_VALUE: Final[object] = object()
_SPEC_UNSAFE_TEXT_PATTERN: Final[re.Pattern[str]] = re.compile(r"[;\r\n\x00]")
_ELEMENT_PATTERN: Final[re.Pattern[str]] = re.compile(r"^[A-Z][a-z]?$|^\*$")
_RESIDUE_TOKEN_PATTERN: Final[re.Pattern[str]] = re.compile(r"^-?[0-9]+[A-Za-z]?$|^[A-Za-z0-9_.+\-]+$")


def _object_value(
    source: Any,
    *names: str,
    default: Any = None,
    allow_callable: bool = False,
) -> Any:
    """Read the first available mapping key or attribute."""

    if source is None:
        return default
    for name in names:
        value = _MISSING_SPEC_VALUE
        if isinstance(source, Mapping) and name in source:
            value = source[name]
        else:
            try:
                value = getattr(source, name)
            except (AttributeError, TypeError):
                continue
        if value is _MISSING_SPEC_VALUE:
            continue
        if callable(value):
            if not allow_callable:
                continue
            try:
                value = value()
            except TypeError:
                continue
        if value is not None:
            return value
    return default


def _clean_spec_text(
    value: Any,
    *,
    field_name: str,
    allow_none: bool = True,
    max_length: int = MAX_VISUALIZATION_NAME_LENGTH,
) -> Optional[str]:
    """Normalize a command-safe molecular token."""

    if value is None:
        if allow_none:
            return None
        raise VisualizationSpecificationError(
            f"{field_name} is required.",
            context={"field": field_name},
        )
    text = str(value).strip()
    if not text:
        if allow_none:
            return None
        raise VisualizationSpecificationError(
            f"{field_name} cannot be empty.",
            context={"field": field_name},
        )
    if len(text) > max_length:
        raise VisualizationLimitError(
            f"{field_name} exceeds {max_length} characters.",
            context={"field": field_name, "length": len(text), "limit": max_length},
        )
    if _SPEC_UNSAFE_TEXT_PATTERN.search(text):
        raise VisualizationSpecificationError(
            f"{field_name} contains unsafe characters.",
            context={"field": field_name, "value": text},
        )
    return text


def _optional_spec_int(value: Any, *, field_name: str, minimum: Optional[int] = None) -> Optional[int]:
    """Normalize an optional integer."""

    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    if isinstance(value, bool):
        raise VisualizationSpecificationError(
            f"{field_name} must be an integer.",
            context={"field": field_name, "value": value},
        )
    try:
        result = int(value)
    except (TypeError, ValueError) as exc:
        raise VisualizationSpecificationError(
            f"{field_name} must be an integer.",
            context={"field": field_name, "value": value},
            cause=exc,
        ) from exc
    if minimum is not None and result < minimum:
        raise VisualizationSpecificationError(
            f"{field_name} must be at least {minimum}.",
            context={"field": field_name, "value": result, "minimum": minimum},
        )
    return result


def _optional_spec_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> Optional[float]:
    """Normalize an optional finite float."""

    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    if isinstance(value, bool):
        raise VisualizationSpecificationError(
            f"{field_name} must be numeric.",
            context={"field": field_name, "value": value},
        )
    try:
        result = float(value)
    except (TypeError, ValueError) as exc:
        raise VisualizationSpecificationError(
            f"{field_name} must be numeric.",
            context={"field": field_name, "value": value},
            cause=exc,
        ) from exc
    if not math.isfinite(result):
        raise VisualizationSpecificationError(
            f"{field_name} must be finite.",
            context={"field": field_name, "value": value},
        )
    if minimum is not None and result < minimum:
        raise VisualizationSpecificationError(
            f"{field_name} must be at least {minimum}.",
            context={"field": field_name, "value": result, "minimum": minimum},
        )
    if maximum is not None and result > maximum:
        raise VisualizationSpecificationError(
            f"{field_name} must not exceed {maximum}.",
            context={"field": field_name, "value": result, "maximum": maximum},
        )
    return result


def normalize_point3d(
    value: Any,
    *,
    field_name: str = "coordinate",
    allow_none: bool = False,
) -> Optional[Point3D]:
    """Normalize a finite Cartesian point."""

    if value is None:
        if allow_none:
            return None
        raise VisualizationCoordinateError(
            f"{field_name} is required.",
            context={"field": field_name},
        )

    candidate = value
    if isinstance(candidate, Mapping):
        if all(axis in candidate for axis in ("x", "y", "z")):
            candidate = (candidate["x"], candidate["y"], candidate["z"])
        elif "coordinate" in candidate:
            candidate = candidate["coordinate"]
        elif "coord" in candidate:
            candidate = candidate["coord"]
    elif not isinstance(candidate, (str, bytes, Sequence)):
        xyz = tuple(_object_value(candidate, axis, default=_MISSING_SPEC_VALUE) for axis in ("x", "y", "z"))
        if all(item is not _MISSING_SPEC_VALUE for item in xyz):
            candidate = xyz
        else:
            nested = _object_value(candidate, "scene_coord", "coord", "coordinate", default=_MISSING_SPEC_VALUE)
            if nested is not _MISSING_SPEC_VALUE:
                candidate = nested

    if NUMPY_AVAILABLE and isinstance(candidate, np.ndarray):
        candidate = candidate.reshape(-1).tolist()
    try:
        components = tuple(float(component) for component in candidate)
    except (TypeError, ValueError) as exc:
        raise VisualizationCoordinateError(
            f"{field_name} must contain three numeric values.",
            context={"field": field_name, "value": repr(value)},
            cause=exc,
        ) from exc
    if len(components) != 3 or not all(math.isfinite(component) for component in components):
        raise VisualizationCoordinateError(
            f"{field_name} must contain three finite values.",
            context={"field": field_name, "value": components},
        )
    return components[0], components[1], components[2]


def normalize_vector3d(
    value: Any,
    *,
    field_name: str = "vector",
    allow_none: bool = False,
    unit: bool = False,
) -> Optional[Vector3D]:
    """Normalize a finite vector, optionally to unit length."""

    vector = normalize_point3d(value, field_name=field_name, allow_none=allow_none)
    if vector is None or not unit:
        return vector
    norm = math.sqrt(sum(component * component for component in vector))
    if norm <= VISUALIZATION_COORDINATE_EPSILON:
        raise VisualizationGeometryError(
            f"{field_name} cannot be a zero vector.",
            context={"field": field_name, "value": vector},
        )
    return tuple(component / norm for component in vector)  # type: ignore[return-value]


def _normalize_element(value: Any) -> Optional[str]:
    """Normalize an element symbol."""

    if value is None:
        return None
    raw = _object_value(value, "name", "symbol", default=value)
    text = str(raw).strip()
    if not text:
        return None
    normalized = "*" if text == "*" else text[0].upper() + text[1:].lower()
    if not _ELEMENT_PATTERN.fullmatch(normalized):
        raise VisualizationSpecificationError(
            "Invalid element symbol.",
            context={"field": "element", "value": text},
        )
    return normalized


def _normalize_residue_number(value: Any) -> Optional[str]:
    """Normalize a residue identifier."""

    if value is None:
        return None
    text = _clean_spec_text(value, field_name="residue_number")
    if text is not None and not _RESIDUE_TOKEN_PATTERN.fullmatch(text):
        raise VisualizationSpecificationError(
            "Invalid residue number.",
            context={"field": "residue_number", "value": text},
        )
    return text


def _normalize_model_id(value: Any) -> Optional[str]:
    """Normalize scalar or hierarchical model identifiers."""

    if value is None:
        return None
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        parts = [str(part).strip() for part in value if str(part).strip()]
        value = ".".join(parts)
    text = _clean_spec_text(value, field_name="model_id")
    if text and text.startswith(SELECTION_MODEL_PREFIX):
        text = text[len(SELECTION_MODEL_PREFIX):]
    return text or None


def _normalize_spec_metadata(value: Any) -> Mapping[str, Any]:
    """Return a shallow immutable metadata mapping."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise VisualizationSpecificationError(
            "metadata must be a mapping.",
            context={"value_type": type(value).__name__},
        )
    return MappingProxyType({str(key): item for key, item in value.items()})


def _spec_data(value: Any) -> Any:
    """Convert specification values to JSON-compatible data."""

    if isinstance(value, Enum):
        return value.value
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Mapping):
        return {str(key): _spec_data(item) for key, item in value.items()}
    if is_dataclass(value):
        return {
            item.name: _spec_data(getattr(value, item.name))
            for item in fields(value)
            if not item.name.startswith("_")
        }
    if isinstance(value, (tuple, list, set, frozenset)):
        return [_spec_data(item) for item in value]
    if NUMPY_AVAILABLE and isinstance(value, np.generic):
        return value.item()
    return value


def _spec_fingerprint(value: Any) -> str:
    """Return a stable specification digest."""

    payload = json.dumps(_spec_data(value), ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return sha256(payload.encode("utf-8")).hexdigest()


# 6.2. Base specification behavior
# -----------------------------------------------------------------------------

class MolecularSpecMixin:
    """Shared serialization and update helpers."""

    def to_dict(self) -> Dict[str, Any]:
        return _spec_data(self)

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        return json.dumps(self.to_dict(), ensure_ascii=False, sort_keys=True, indent=indent)

    def fingerprint(self) -> str:
        return _spec_fingerprint(self)

    def updated(self: SpecT, **changes: Any) -> SpecT:
        if not is_dataclass(self):
            raise VisualizationSpecificationError("updated() requires a dataclass specification.")
        return replace(self, **changes)


@dataclass(frozen=True, slots=True)
class MolecularPathSpec(MolecularSpecMixin):
    """Hierarchical molecular identity."""

    model_id: Optional[str] = None
    chain_id: Optional[str] = None
    residue_number: Optional[str] = None
    insertion_code: Optional[str] = None
    residue_name: Optional[str] = None
    atom_name: Optional[str] = None
    alt_loc: Optional[str] = None
    source_id: Optional[str] = None
    role: MolecularRole = MolecularRole.UNKNOWN
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "model_id", _normalize_model_id(self.model_id))
        object.__setattr__(self, "chain_id", _clean_spec_text(self.chain_id, field_name="chain_id"))
        object.__setattr__(self, "residue_number", _normalize_residue_number(self.residue_number))
        object.__setattr__(self, "insertion_code", _clean_spec_text(self.insertion_code, field_name="insertion_code", max_length=8))
        object.__setattr__(self, "residue_name", _clean_spec_text(self.residue_name, field_name="residue_name", max_length=16))
        object.__setattr__(self, "atom_name", _clean_spec_text(self.atom_name, field_name="atom_name", max_length=32))
        object.__setattr__(self, "alt_loc", _clean_spec_text(self.alt_loc, field_name="alt_loc", max_length=8))
        object.__setattr__(self, "source_id", _clean_spec_text(self.source_id, field_name="source_id"))
        object.__setattr__(self, "role", MolecularRole.parse(self.role, default=MolecularRole.UNKNOWN))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))
        if self.atom_name and self.residue_number is None:
            raise VisualizationSpecificationError(
                "An atom path requires a residue number.",
                context={"atom_name": self.atom_name},
            )
        if self.residue_number is not None and self.chain_id is None and self.model_id is None:
            # Unqualified residue paths are valid for portable plans.
            return

    @property
    def depth(self) -> SelectionKind:
        if self.atom_name:
            return SelectionKind.ATOM
        if self.residue_number:
            return SelectionKind.RESIDUE
        if self.chain_id:
            return SelectionKind.CHAIN
        if self.model_id:
            return SelectionKind.MODEL
        return SelectionKind.ALL

    @property
    def residue_key(self) -> Tuple[Optional[str], Optional[str], Optional[str], Optional[str]]:
        return self.model_id, self.chain_id, self.residue_number, self.insertion_code

    @property
    def atom_key(self) -> Tuple[Optional[str], Optional[str], Optional[str], Optional[str], Optional[str], Optional[str]]:
        return (*self.residue_key, self.atom_name, self.alt_loc)

    @property
    def label(self) -> str:
        chunks: List[str] = []
        if self.residue_name:
            chunks.append(self.residue_name)
        if self.residue_number:
            chunks.append(f"{self.residue_number}{self.insertion_code or ''}")
        residue = "".join(chunks)
        if self.chain_id:
            residue = f"{residue}/{self.chain_id}" if residue else self.chain_id
        if self.atom_name:
            residue = f"{residue}@{self.atom_name}" if residue else self.atom_name
        if self.model_id:
            residue = f"#{self.model_id}:{residue}" if residue else f"#{self.model_id}"
        return residue or self.source_id or "all"

    def parent(self) -> "MolecularPathSpec":
        if self.atom_name:
            return replace(self, atom_name=None, alt_loc=None)
        if self.residue_number:
            return replace(self, residue_number=None, insertion_code=None, residue_name=None)
        if self.chain_id:
            return replace(self, chain_id=None)
        if self.model_id:
            return replace(self, model_id=None)
        return self

    def with_atom(self, atom_name: str, *, alt_loc: Optional[str] = None) -> "MolecularPathSpec":
        if self.residue_number is None:
            raise VisualizationSpecificationError("with_atom() requires a residue path.")
        return replace(self, atom_name=atom_name, alt_loc=alt_loc)


# 6.3. Atom, residue, chain and model specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class AtomSpec(MolecularSpecMixin):
    """Portable atom specification."""

    path: MolecularPathSpec
    serial_number: Optional[int] = None
    element: Optional[str] = None
    coordinate: Optional[Point3D] = None
    formal_charge: Optional[float] = None
    partial_charge: Optional[float] = None
    occupancy: Optional[float] = None
    bfactor: Optional[float] = None
    aromatic: Optional[bool] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        path = coerce_molecular_path(self.path)
        if not path.atom_name:
            raise VisualizationSpecificationError("AtomSpec.path requires atom_name.")
        object.__setattr__(self, "path", path)
        object.__setattr__(self, "serial_number", _optional_spec_int(self.serial_number, field_name="serial_number", minimum=0))
        object.__setattr__(self, "element", _normalize_element(self.element))
        object.__setattr__(self, "coordinate", normalize_point3d(self.coordinate, allow_none=True))
        object.__setattr__(self, "formal_charge", _optional_spec_float(self.formal_charge, field_name="formal_charge"))
        object.__setattr__(self, "partial_charge", _optional_spec_float(self.partial_charge, field_name="partial_charge"))
        object.__setattr__(self, "occupancy", _optional_spec_float(self.occupancy, field_name="occupancy", minimum=0.0))
        object.__setattr__(self, "bfactor", _optional_spec_float(self.bfactor, field_name="bfactor"))
        object.__setattr__(self, "aromatic", None if self.aromatic is None else bool(self.aromatic))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def atom_name(self) -> str:
        return self.path.atom_name or ""

    @property
    def residue_path(self) -> MolecularPathSpec:
        return self.path.parent()

    @property
    def key(self) -> Tuple[Any, ...]:
        return self.path.atom_key


@dataclass(frozen=True, slots=True)
class ResidueSpec(MolecularSpecMixin):
    """Portable residue specification."""

    path: MolecularPathSpec
    atom_names: Tuple[str, ...] = ()
    center: Optional[Point3D] = None
    polymer_type: Optional[str] = None
    one_letter_code: Optional[str] = None
    hetero: Optional[bool] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        path = coerce_molecular_path(self.path)
        if path.residue_number is None:
            raise VisualizationSpecificationError("ResidueSpec.path requires residue_number.")
        if path.atom_name:
            path = path.parent()
        atom_names = tuple(dict.fromkeys(
            item for item in (
                _clean_spec_text(name, field_name="atom_name", allow_none=False, max_length=32)
                for name in self.atom_names
            ) if item is not None
        ))
        object.__setattr__(self, "path", path)
        object.__setattr__(self, "atom_names", atom_names)
        object.__setattr__(self, "center", normalize_point3d(self.center, field_name="center", allow_none=True))
        object.__setattr__(self, "polymer_type", _clean_spec_text(self.polymer_type, field_name="polymer_type"))
        object.__setattr__(self, "one_letter_code", _clean_spec_text(self.one_letter_code, field_name="one_letter_code", max_length=4))
        object.__setattr__(self, "hetero", None if self.hetero is None else bool(self.hetero))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def key(self) -> Tuple[Any, ...]:
        return self.path.residue_key

    def atom_path(self, atom_name: str, *, alt_loc: Optional[str] = None) -> MolecularPathSpec:
        return self.path.with_atom(atom_name, alt_loc=alt_loc)


@dataclass(frozen=True, slots=True)
class ChainSpec(MolecularSpecMixin):
    """Portable chain specification."""

    path: MolecularPathSpec
    residue_keys: Tuple[Tuple[Optional[str], Optional[str], Optional[str], Optional[str]], ...] = ()
    polymer_type: Optional[str] = None
    sequence: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        path = coerce_molecular_path(self.path)
        if path.chain_id is None:
            raise VisualizationSpecificationError("ChainSpec.path requires chain_id.")
        while path.residue_number is not None or path.atom_name is not None:
            path = path.parent()
        keys = tuple(tuple(item) for item in self.residue_keys)
        object.__setattr__(self, "path", path)
        object.__setattr__(self, "residue_keys", keys)
        object.__setattr__(self, "polymer_type", _clean_spec_text(self.polymer_type, field_name="polymer_type"))
        object.__setattr__(self, "sequence", None if self.sequence is None else str(self.sequence).strip())
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def key(self) -> Tuple[Optional[str], Optional[str]]:
        return self.path.model_id, self.path.chain_id


@dataclass(frozen=True, slots=True)
class ModelSpec(MolecularSpecMixin):
    """Portable molecular-model specification."""

    model_id: str
    name: Optional[str] = None
    role: MolecularRole = MolecularRole.UNKNOWN
    source_path: Optional[Path] = None
    chain_ids: Tuple[str, ...] = ()
    visible: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        model_id = _normalize_model_id(self.model_id)
        if not model_id:
            raise VisualizationSpecificationError("model_id is required.")
        chain_ids = tuple(dict.fromkeys(
            item for item in (
                _clean_spec_text(chain, field_name="chain_id", allow_none=False)
                for chain in self.chain_ids
            ) if item is not None
        ))
        source_path = None if self.source_path is None else Path(self.source_path).expanduser()
        object.__setattr__(self, "model_id", model_id)
        object.__setattr__(self, "name", _clean_spec_text(self.name, field_name="name"))
        object.__setattr__(self, "role", MolecularRole.parse(self.role, default=MolecularRole.UNKNOWN))
        object.__setattr__(self, "source_path", source_path)
        object.__setattr__(self, "chain_ids", chain_ids)
        object.__setattr__(self, "visible", bool(self.visible))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def path(self) -> MolecularPathSpec:
        return MolecularPathSpec(model_id=self.model_id, role=self.role, source_id=self.name)


# 6.4. Molecular groups and poses
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class MolecularGroupSpec(MolecularSpecMixin):
    """Chemical or visual atom group."""

    group_id: str
    kind: str
    atoms: Tuple[AtomSpec, ...] = ()
    center: Optional[Point3D] = None
    normal: Optional[Vector3D] = None
    charge: Optional[float] = None
    role: MolecularRole = MolecularRole.UNKNOWN
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        group_id = _clean_spec_text(self.group_id, field_name="group_id", allow_none=False)
        kind = _clean_spec_text(self.kind, field_name="kind", allow_none=False)
        atoms = tuple(coerce_atom_spec(atom) for atom in self.atoms)
        if not atoms and self.center is None:
            raise VisualizationSpecificationError(
                "A molecular group requires atoms or a center.",
                context={"group_id": group_id},
            )
        object.__setattr__(self, "group_id", group_id or "group")
        object.__setattr__(self, "kind", kind or "unknown")
        object.__setattr__(self, "atoms", atoms)
        object.__setattr__(self, "center", normalize_point3d(self.center, field_name="center", allow_none=True))
        object.__setattr__(self, "normal", normalize_vector3d(self.normal, field_name="normal", allow_none=True, unit=True))
        object.__setattr__(self, "charge", _optional_spec_float(self.charge, field_name="charge"))
        object.__setattr__(self, "role", MolecularRole.parse(self.role, default=MolecularRole.UNKNOWN))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def paths(self) -> Tuple[MolecularPathSpec, ...]:
        return tuple(atom.path for atom in self.atoms)

    @property
    def effective_center(self) -> Optional[Point3D]:
        if self.center is not None:
            return self.center
        coordinates = [atom.coordinate for atom in self.atoms if atom.coordinate is not None]
        if not coordinates:
            return None
        count = float(len(coordinates))
        return tuple(sum(point[index] for point in coordinates) / count for index in range(3))  # type: ignore[return-value]


@dataclass(frozen=True, slots=True)
class MolecularObjectSpec(MolecularSpecMixin):
    """Named molecular object or logical selection."""

    object_id: str
    name: Optional[str] = None
    role: MolecularRole = MolecularRole.UNKNOWN
    models: Tuple[ModelSpec, ...] = ()
    paths: Tuple[MolecularPathSpec, ...] = ()
    source_path: Optional[Path] = None
    score: Optional[float] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object_id = _clean_spec_text(self.object_id, field_name="object_id", allow_none=False)
        models = tuple(coerce_model_spec(model, role=self.role) for model in self.models)
        paths = tuple(dict.fromkeys(coerce_molecular_path(path, role=self.role) for path in self.paths))
        source_path = None if self.source_path is None else Path(self.source_path).expanduser()
        role = MolecularRole.parse(self.role, default=MolecularRole.UNKNOWN)
        object.__setattr__(self, "object_id", object_id or "object")
        object.__setattr__(self, "name", _clean_spec_text(self.name, field_name="name"))
        object.__setattr__(self, "role", role)
        object.__setattr__(self, "models", models)
        object.__setattr__(self, "paths", paths)
        object.__setattr__(self, "source_path", source_path)
        object.__setattr__(self, "score", _optional_spec_float(self.score, field_name="score"))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def model_ids(self) -> Tuple[str, ...]:
        explicit = [model.model_id for model in self.models]
        inferred = [path.model_id for path in self.paths if path.model_id]
        return tuple(dict.fromkeys([*explicit, *inferred]))

    @property
    def primary_model(self) -> Optional[ModelSpec]:
        return self.models[0] if self.models else None


@dataclass(frozen=True, slots=True)
class PoseSpec(MolecularSpecMixin):
    """Ligand-pose identity and external scores."""

    pose_id: str
    index: int = 0
    rank: Optional[int] = None
    ligand: Optional[MolecularObjectSpec] = None
    model_id: Optional[str] = None
    affinity: Optional[float] = None
    score: Optional[float] = None
    rmsd_lower_bound: Optional[float] = None
    rmsd_upper_bound: Optional[float] = None
    source_path: Optional[Path] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        pose_id = _clean_spec_text(self.pose_id, field_name="pose_id", allow_none=False)
        ligand = None if self.ligand is None else coerce_molecular_object_spec(self.ligand, role=MolecularRole.LIGAND)
        model_id = _normalize_model_id(self.model_id)
        if model_id is None and ligand is not None and ligand.model_ids:
            model_id = ligand.model_ids[0]
        object.__setattr__(self, "pose_id", pose_id or "pose")
        object.__setattr__(self, "index", _optional_spec_int(self.index, field_name="index", minimum=0) or 0)
        object.__setattr__(self, "rank", _optional_spec_int(self.rank, field_name="rank", minimum=1))
        object.__setattr__(self, "ligand", ligand)
        object.__setattr__(self, "model_id", model_id)
        object.__setattr__(self, "affinity", _optional_spec_float(self.affinity, field_name="affinity"))
        object.__setattr__(self, "score", _optional_spec_float(self.score, field_name="score"))
        object.__setattr__(self, "rmsd_lower_bound", _optional_spec_float(self.rmsd_lower_bound, field_name="rmsd_lower_bound", minimum=0.0))
        object.__setattr__(self, "rmsd_upper_bound", _optional_spec_float(self.rmsd_upper_bound, field_name="rmsd_upper_bound", minimum=0.0))
        object.__setattr__(self, "source_path", None if self.source_path is None else Path(self.source_path).expanduser())
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))
        if (
            self.rmsd_lower_bound is not None
            and self.rmsd_upper_bound is not None
            and self.rmsd_lower_bound > self.rmsd_upper_bound
        ):
            raise VisualizationSpecificationError("rmsd_lower_bound cannot exceed rmsd_upper_bound.")


# 6.5. Structure and bundle specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class StructureSpec(MolecularSpecMixin):
    """Normalized molecular structure inventory."""

    structure_id: str
    models: Tuple[ModelSpec, ...] = ()
    chains: Tuple[ChainSpec, ...] = ()
    residues: Tuple[ResidueSpec, ...] = ()
    atoms: Tuple[AtomSpec, ...] = ()
    groups: Tuple[MolecularGroupSpec, ...] = ()
    poses: Tuple[PoseSpec, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        structure_id = _clean_spec_text(self.structure_id, field_name="structure_id", allow_none=False)
        models = tuple(coerce_model_spec(value) for value in self.models)
        chains = tuple(coerce_chain_spec(value) for value in self.chains)
        residues = tuple(coerce_residue_spec(value) for value in self.residues)
        atoms = tuple(coerce_atom_spec(value) for value in self.atoms)
        groups = tuple(value if isinstance(value, MolecularGroupSpec) else MolecularGroupSpec(**value) for value in self.groups)
        poses = tuple(coerce_pose_spec(value) for value in self.poses)
        _ensure_unique_specs(models, key=lambda item: item.model_id, label="model")
        _ensure_unique_specs(chains, key=lambda item: item.key, label="chain")
        _ensure_unique_specs(residues, key=lambda item: item.key, label="residue")
        _ensure_unique_specs(atoms, key=lambda item: item.key, label="atom")
        _ensure_unique_specs(groups, key=lambda item: item.group_id, label="group")
        _ensure_unique_specs(poses, key=lambda item: item.pose_id, label="pose")
        object.__setattr__(self, "structure_id", structure_id or "structure")
        object.__setattr__(self, "models", models)
        object.__setattr__(self, "chains", chains)
        object.__setattr__(self, "residues", residues)
        object.__setattr__(self, "atoms", atoms)
        object.__setattr__(self, "groups", groups)
        object.__setattr__(self, "poses", poses)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def atoms_for_residue(self, residue: Any) -> Tuple[AtomSpec, ...]:
        residue_spec = coerce_residue_spec(residue)
        return tuple(atom for atom in self.atoms if atom.path.residue_key == residue_spec.key)

    def residues_for_chain(self, chain: Any) -> Tuple[ResidueSpec, ...]:
        chain_spec = coerce_chain_spec(chain)
        return tuple(
            residue for residue in self.residues
            if (residue.path.model_id, residue.path.chain_id) == chain_spec.key
        )

    def model_by_id(self, model_id: Any) -> Optional[ModelSpec]:
        normalized = _normalize_model_id(model_id)
        return next((model for model in self.models if model.model_id == normalized), None)


@dataclass(frozen=True, slots=True)
class MolecularSpecificationBundle(MolecularSpecMixin):
    """Receptor, ligand and auxiliary molecular inputs."""

    receptor: Optional[MolecularObjectSpec] = None
    ligands: Tuple[MolecularObjectSpec, ...] = ()
    cofactors: Tuple[MolecularObjectSpec, ...] = ()
    solvent: Tuple[MolecularObjectSpec, ...] = ()
    ions: Tuple[MolecularObjectSpec, ...] = ()
    poses: Tuple[PoseSpec, ...] = ()
    structure: Optional[StructureSpec] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        receptor = None if self.receptor is None else coerce_molecular_object_spec(self.receptor, role=MolecularRole.RECEPTOR)
        ligands = tuple(coerce_molecular_object_spec(item, role=MolecularRole.LIGAND) for item in self.ligands)
        cofactors = tuple(coerce_molecular_object_spec(item, role=MolecularRole.COFACTOR) for item in self.cofactors)
        solvent = tuple(coerce_molecular_object_spec(item, role=MolecularRole.SOLVENT) for item in self.solvent)
        ions = tuple(coerce_molecular_object_spec(item, role=MolecularRole.ION) for item in self.ions)
        poses = tuple(coerce_pose_spec(item) for item in self.poses)
        structure = self.structure
        if structure is not None and not isinstance(structure, StructureSpec):
            structure = StructureSpec(**structure)
        _ensure_unique_specs(ligands, key=lambda item: item.object_id, label="ligand")
        _ensure_unique_specs(poses, key=lambda item: item.pose_id, label="pose")
        object.__setattr__(self, "receptor", receptor)
        object.__setattr__(self, "ligands", ligands)
        object.__setattr__(self, "cofactors", cofactors)
        object.__setattr__(self, "solvent", solvent)
        object.__setattr__(self, "ions", ions)
        object.__setattr__(self, "poses", poses)
        object.__setattr__(self, "structure", structure)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def objects(self) -> Tuple[MolecularObjectSpec, ...]:
        receptor = () if self.receptor is None else (self.receptor,)
        return (*receptor, *self.ligands, *self.cofactors, *self.solvent, *self.ions)

    def objects_by_role(self, role: Any) -> Tuple[MolecularObjectSpec, ...]:
        parsed = MolecularRole.parse(role, default=MolecularRole.UNKNOWN)
        return tuple(item for item in self.objects if item.role is parsed)


# 6.6. Coercion from mappings and molecular objects
# -----------------------------------------------------------------------------

def infer_molecular_role(value: Any, *, default: Any = MolecularRole.UNKNOWN) -> MolecularRole:
    """Infer a role from explicit fields and common molecular flags."""

    explicit = _object_value(value, "role", "molecular_role", "object_role")
    parsed = MolecularRole.parse(explicit, strict=False)
    if parsed is not None:
        return parsed
    if bool(_object_value(value, "is_ligand", "ligand", default=False)):
        return MolecularRole.LIGAND
    if bool(_object_value(value, "is_solvent", "is_water", default=False)):
        return MolecularRole.SOLVENT
    if bool(_object_value(value, "is_ion", "ion", default=False)):
        return MolecularRole.ION
    if bool(_object_value(value, "is_receptor", "is_protein", default=False)):
        return MolecularRole.RECEPTOR
    return MolecularRole.parse(default, default=MolecularRole.UNKNOWN)


def coerce_molecular_path(value: Any, *, role: Any = None) -> MolecularPathSpec:
    """Convert path-like input to MolecularPathSpec."""

    if isinstance(value, MolecularPathSpec):
        if role is None:
            return value
        parsed = MolecularRole.parse(role, default=value.role)
        return value if value.role is parsed else replace(value, role=parsed)
    if isinstance(value, AtomSpec):
        return coerce_molecular_path(value.path, role=role)
    if isinstance(value, ResidueSpec):
        return coerce_molecular_path(value.path, role=role)
    if isinstance(value, ChainSpec):
        return coerce_molecular_path(value.path, role=role)
    if isinstance(value, ModelSpec):
        return coerce_molecular_path(value.path, role=role)
    if isinstance(value, str):
        return MolecularPathSpec(source_id=value, role=MolecularRole.parse(role, default=MolecularRole.UNKNOWN))

    residue = _object_value(value, "residue")
    chain = _object_value(value, "chain")
    model = _object_value(value, "structure", "model")
    if residue is not None:
        chain = _object_value(residue, "chain", default=chain)
        model = _object_value(residue, "structure", "model", default=model)

    model_id = _object_value(value, "model_id", "structure_id")
    if model_id is None and model is not None:
        model_id = _object_value(model, "id_string", "id", "model_id")
    chain_id = _object_value(value, "chain_id")
    if chain_id is None and chain is not None:
        chain_id = _object_value(chain, "chain_id", "id", "name")
    if chain_id is None and residue is not None:
        chain_id = _object_value(residue, "chain_id")
    residue_number = _object_value(value, "residue_number", "resid", "residue_id")
    residue_name = _object_value(value, "residue_name", "resname")
    insertion_code = _object_value(value, "insertion_code", "icode")
    if residue is not None:
        residue_number = _object_value(residue, "number", "residue_number", "id", default=residue_number)
        residue_name = _object_value(residue, "name", "residue_name", default=residue_name)
        insertion_code = _object_value(residue, "insertion_code", "icode", default=insertion_code)
    atom_name = _object_value(value, "atom_name")
    if atom_name is None and residue is not None:
        atom_name = _object_value(value, "name")
    alt_loc = _object_value(value, "alt_loc", "altloc")
    source_id = _object_value(value, "source_id", "identifier", "uid")
    resolved_role = infer_molecular_role(value, default=role or MolecularRole.UNKNOWN)
    metadata = _object_value(value, "metadata", default={})
    return MolecularPathSpec(
        model_id=model_id,
        chain_id=chain_id,
        residue_number=residue_number,
        insertion_code=insertion_code,
        residue_name=residue_name,
        atom_name=atom_name,
        alt_loc=alt_loc,
        source_id=source_id,
        role=resolved_role,
        metadata=metadata,
    )


def coerce_atom_spec(value: Any, *, role: Any = None) -> AtomSpec:
    """Convert atom-like input to AtomSpec."""

    if isinstance(value, AtomSpec):
        return value if role is None else replace(value, path=coerce_molecular_path(value.path, role=role))
    if isinstance(value, Mapping) and "path" in value:
        payload = dict(value)
        payload["path"] = coerce_molecular_path(payload["path"], role=role)
        return AtomSpec(**payload)
    path = coerce_molecular_path(value, role=role)
    if not path.atom_name:
        atom_name = _object_value(value, "name", "atom_name")
        path = replace(path, atom_name=atom_name)
    coordinate = _object_value(value, "scene_coord", "coord", "coordinate")
    element = _object_value(value, "element", "element_name")
    return AtomSpec(
        path=path,
        serial_number=_object_value(value, "serial_number", "serial", "index"),
        element=element,
        coordinate=coordinate,
        formal_charge=_object_value(value, "formal_charge", "charge"),
        partial_charge=_object_value(value, "partial_charge"),
        occupancy=_object_value(value, "occupancy"),
        bfactor=_object_value(value, "bfactor", "b_factor"),
        aromatic=_object_value(value, "aromatic", "is_aromatic"),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_residue_spec(value: Any, *, role: Any = None) -> ResidueSpec:
    """Convert residue-like input to ResidueSpec."""

    if isinstance(value, ResidueSpec):
        return value if role is None else replace(value, path=coerce_molecular_path(value.path, role=role))
    if isinstance(value, Mapping) and "path" in value:
        payload = dict(value)
        payload["path"] = coerce_molecular_path(payload["path"], role=role)
        return ResidueSpec(**payload)
    path = coerce_molecular_path(value, role=role)
    if path.atom_name:
        path = path.parent()
    atoms = _object_value(value, "atoms", default=()) or ()
    atom_names = tuple(
        str(_object_value(atom, "name", "atom_name", default=atom)).strip()
        for atom in atoms
        if str(_object_value(atom, "name", "atom_name", default=atom)).strip()
    )
    return ResidueSpec(
        path=path,
        atom_names=atom_names,
        center=_object_value(value, "center", "centroid"),
        polymer_type=_object_value(value, "polymer_type", "type"),
        one_letter_code=_object_value(value, "one_letter_code", "code"),
        hetero=_object_value(value, "hetero", "is_hetero"),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_chain_spec(value: Any, *, role: Any = None) -> ChainSpec:
    """Convert chain-like input to ChainSpec."""

    if isinstance(value, ChainSpec):
        return value if role is None else replace(value, path=coerce_molecular_path(value.path, role=role))
    if isinstance(value, Mapping) and "path" in value:
        payload = dict(value)
        payload["path"] = coerce_molecular_path(payload["path"], role=role)
        return ChainSpec(**payload)
    path = coerce_molecular_path(value, role=role)
    residues = _object_value(value, "residues", default=()) or ()
    keys = tuple(coerce_residue_spec(residue, role=path.role).key for residue in residues)
    return ChainSpec(
        path=path,
        residue_keys=keys,
        polymer_type=_object_value(value, "polymer_type", "type"),
        sequence=_object_value(value, "sequence", "characters"),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_model_spec(value: Any, *, role: Any = None) -> ModelSpec:
    """Convert model-like input to ModelSpec."""

    if isinstance(value, ModelSpec):
        return value if role is None else replace(value, role=MolecularRole.parse(role, default=value.role))
    if isinstance(value, Mapping) and "model_id" in value:
        payload = dict(value)
        if role is not None:
            payload["role"] = role
        return ModelSpec(**payload)
    model_id = _object_value(value, "id_string", "model_id", "id")
    chains = _object_value(value, "chains", default=()) or ()
    chain_ids = tuple(
        str(_object_value(chain, "chain_id", "id", "name", default=chain)).strip()
        for chain in chains
        if str(_object_value(chain, "chain_id", "id", "name", default=chain)).strip()
    )
    return ModelSpec(
        model_id=model_id,
        name=_object_value(value, "name", "display_name"),
        role=infer_molecular_role(value, default=role or MolecularRole.UNKNOWN),
        source_path=_object_value(value, "source_path", "filename", "path"),
        chain_ids=chain_ids,
        visible=_object_value(value, "visible", "display", default=True),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_molecular_object_spec(value: Any, *, role: Any = None) -> MolecularObjectSpec:
    """Convert object-like input to MolecularObjectSpec."""

    parsed_role = infer_molecular_role(value, default=role or MolecularRole.UNKNOWN)
    if isinstance(value, MolecularObjectSpec):
        return value if role is None else replace(value, role=parsed_role)
    if isinstance(value, ModelSpec):
        return MolecularObjectSpec(
            object_id=value.name or value.model_id,
            name=value.name,
            role=parsed_role,
            models=(coerce_model_spec(value, role=parsed_role),),
            source_path=value.source_path,
        )
    if isinstance(value, Mapping) and "object_id" in value:
        payload = dict(value)
        if role is not None:
            payload["role"] = parsed_role
        return MolecularObjectSpec(**payload)
    object_id = _object_value(value, "object_id", "identifier", "name", "id_string", "id")
    models_raw = _object_value(value, "models", default=()) or ()
    if not models_raw and _object_value(value, "model_id", "id_string", "id") is not None:
        models_raw = (value,)
    paths_raw = _object_value(value, "paths", "molecular_paths", default=()) or ()
    return MolecularObjectSpec(
        object_id=object_id,
        name=_object_value(value, "name", "display_name"),
        role=parsed_role,
        models=tuple(coerce_model_spec(model, role=parsed_role) for model in models_raw),
        paths=tuple(coerce_molecular_path(path, role=parsed_role) for path in paths_raw),
        source_path=_object_value(value, "source_path", "filename", "path"),
        score=_object_value(value, "score", "total_score"),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_pose_spec(value: Any, *, index: Optional[int] = None) -> PoseSpec:
    """Convert pose-like input to PoseSpec."""

    if isinstance(value, PoseSpec):
        return value if index is None else replace(value, index=index)
    if isinstance(value, Mapping) and "pose_id" in value:
        payload = dict(value)
        if index is not None:
            payload["index"] = index
        return PoseSpec(**payload)
    pose_index = index if index is not None else _object_value(value, "index", "pose_index", default=0)
    pose_id = _object_value(value, "pose_id", "identifier", "name", default=f"pose_{int(pose_index) + 1}")
    ligand_raw = _object_value(value, "ligand", "molecule", "model")
    ligand = None if ligand_raw is None else coerce_molecular_object_spec(ligand_raw, role=MolecularRole.LIGAND)
    return PoseSpec(
        pose_id=pose_id,
        index=pose_index,
        rank=_object_value(value, "rank"),
        ligand=ligand,
        model_id=_object_value(value, "model_id", "id_string"),
        affinity=_object_value(value, "affinity", "docking_affinity", "vina_score"),
        score=_object_value(value, "score", "total_score"),
        rmsd_lower_bound=_object_value(value, "rmsd_lower_bound", "rmsd_lb"),
        rmsd_upper_bound=_object_value(value, "rmsd_upper_bound", "rmsd_ub"),
        source_path=_object_value(value, "source_path", "filename", "path"),
        metadata=_object_value(value, "metadata", default={}),
    )


def _ensure_unique_specs(values: Sequence[Any], *, key: Callable[[Any], Any], label: str) -> None:
    """Reject duplicate specification identities."""

    seen: Set[Any] = set()
    duplicates: List[Any] = []
    for value in values:
        identity = key(value)
        if identity in seen:
            duplicates.append(identity)
        seen.add(identity)
    if duplicates:
        raise VisualizationSpecificationError(
            f"Duplicate {label} specifications.",
            context={"duplicates": [repr(item) for item in duplicates]},
        )


def coerce_atom_specs(values: Optional[Iterable[Any]], *, role: Any = None) -> Tuple[AtomSpec, ...]:
    """Normalize an atom collection."""

    return tuple(coerce_atom_spec(value, role=role) for value in (values or ()))


def coerce_residue_specs(values: Optional[Iterable[Any]], *, role: Any = None) -> Tuple[ResidueSpec, ...]:
    """Normalize a residue collection."""

    return tuple(coerce_residue_spec(value, role=role) for value in (values or ()))


def coerce_pose_specs(values: Optional[Iterable[Any]]) -> Tuple[PoseSpec, ...]:
    """Normalize a pose collection with stable fallback indices."""

    return tuple(coerce_pose_spec(value, index=index) for index, value in enumerate(values or ()))


# 6.7. Validation, indexing and serialization
# -----------------------------------------------------------------------------

def validate_molecular_path(path: Any) -> Tuple[str, ...]:
    """Return non-fatal path consistency issues."""

    spec = coerce_molecular_path(path)
    issues: List[str] = []
    if spec.insertion_code and spec.residue_number is None:
        issues.append("insertion_code requires residue_number")
    if spec.residue_name and spec.residue_number is None:
        issues.append("residue_name requires residue_number")
    if spec.alt_loc and spec.atom_name is None:
        issues.append("alt_loc requires atom_name")
    return tuple(issues)


def validate_structure_spec(structure: Any) -> Tuple[str, ...]:
    """Return referential consistency issues."""

    spec = structure if isinstance(structure, StructureSpec) else StructureSpec(**structure)
    issues: List[str] = []
    model_ids = {model.model_id for model in spec.models}
    chain_keys = {chain.key for chain in spec.chains}
    residue_keys = {residue.key for residue in spec.residues}
    for chain in spec.chains:
        if model_ids and chain.path.model_id not in model_ids:
            issues.append(f"chain {chain.path.label} references an unknown model")
    for residue in spec.residues:
        key = (residue.path.model_id, residue.path.chain_id)
        if chain_keys and key not in chain_keys:
            issues.append(f"residue {residue.path.label} references an unknown chain")
    for atom in spec.atoms:
        if residue_keys and atom.path.residue_key not in residue_keys:
            issues.append(f"atom {atom.path.label} references an unknown residue")
    for pose in spec.poses:
        if pose.model_id and model_ids and pose.model_id not in model_ids:
            issues.append(f"pose {pose.pose_id} references an unknown model")
    return tuple(issues)


def molecular_spec_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize a molecular specification."""

    if not isinstance(value, MolecularSpecMixin) and not is_dataclass(value):
        raise VisualizationSerializationError(
            "Expected a molecular specification.",
            context={"value_type": type(value).__name__},
        )
    data = _spec_data(value)
    if not isinstance(data, dict):
        raise VisualizationSerializationError("Specification serialization did not produce a mapping.")
    return data


def molecular_spec_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize a molecular specification as JSON."""

    return json.dumps(molecular_spec_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


def molecular_spec_fingerprint(value: Any) -> str:
    """Return a stable molecular-specification digest."""

    return _spec_fingerprint(value)


def index_atom_specs(values: Iterable[Any]) -> Mapping[Tuple[Any, ...], AtomSpec]:
    """Index atoms by hierarchical identity."""

    atoms = tuple(coerce_atom_spec(value) for value in values)
    _ensure_unique_specs(atoms, key=lambda item: item.key, label="atom")
    return MappingProxyType({atom.key: atom for atom in atoms})


def index_residue_specs(values: Iterable[Any]) -> Mapping[Tuple[Any, ...], ResidueSpec]:
    """Index residues by hierarchical identity."""

    residues = tuple(coerce_residue_spec(value) for value in values)
    _ensure_unique_specs(residues, key=lambda item: item.key, label="residue")
    return MappingProxyType({residue.key: residue for residue in residues})


def group_atoms_by_residue(values: Iterable[Any]) -> Mapping[Tuple[Any, ...], Tuple[AtomSpec, ...]]:
    """Group normalized atoms by residue identity."""

    grouped: Dict[Tuple[Any, ...], List[AtomSpec]] = defaultdict(list)
    for value in values:
        atom = coerce_atom_spec(value)
        grouped[atom.path.residue_key].append(atom)
    return MappingProxyType({key: tuple(items) for key, items in grouped.items()})


def describe_molecular_spec(value: Any) -> Dict[str, Any]:
    """Return a compact specification summary."""

    data = molecular_spec_to_dict(value)
    summary: Dict[str, Any] = {
        "type": type(value).__name__,
        "fingerprint": molecular_spec_fingerprint(value),
        "fields": tuple(data),
    }
    if isinstance(value, StructureSpec):
        summary["counts"] = {
            "models": len(value.models),
            "chains": len(value.chains),
            "residues": len(value.residues),
            "atoms": len(value.atoms),
            "groups": len(value.groups),
            "poses": len(value.poses),
        }
        summary["issues"] = validate_structure_spec(value)
    elif isinstance(value, MolecularSpecificationBundle):
        summary["counts"] = {
            "objects": len(value.objects),
            "ligands": len(value.ligands),
            "poses": len(value.poses),
        }
    return summary


