# 7.1. Selection helpers
# -----------------------------------------------------------------------------

_SELECTION_CONTROL_PATTERN: Final[re.Pattern[str]] = re.compile(r"[\r\n\x00-\x08\x0b\x0c\x0e-\x1f]")
_SELECTION_NAME_PATTERN: Final[re.Pattern[str]] = re.compile(SELECTION_SAFE_NAME_PATTERN)
_SELECTION_MODEL_RE: Final[re.Pattern[str]] = re.compile(SELECTION_MODEL_PATTERN)
_SELECTION_RESIDUE_RE: Final[re.Pattern[str]] = re.compile(SELECTION_RESIDUE_PATTERN)
_SELECTION_ATOM_RE: Final[re.Pattern[str]] = re.compile(SELECTION_ATOM_PATTERN)
_SELECTION_FORBIDDEN_COMMAND_CHARS: Final[FrozenSet[str]] = frozenset({";"})


def _selection_error(message: str, *, value: Any = None, **context: Any) -> VisualizationSelectionError:
    """Build a contextual selection error."""

    details = dict(context)
    if value is not None:
        details["value"] = value
    return VisualizationSelectionError(message, context=details)


def _normalize_selection_text(
    value: Any,
    *,
    field_name: str = "selection",
    allow_empty: bool = False,
    allow_command_separator: bool = False,
) -> str:
    """Normalize and safety-check selection text."""

    if value is None:
        if allow_empty:
            return ""
        raise _selection_error(f"{field_name} is required.", value=value)
    text = str(value).strip()
    if not text:
        if allow_empty:
            return ""
        raise _selection_error(f"{field_name} cannot be empty.", value=value)
    if len(text) > MAX_SELECTION_LENGTH:
        raise _selection_error(
            f"{field_name} exceeds the maximum length.",
            value=text[:160],
            length=len(text),
            maximum=MAX_SELECTION_LENGTH,
        )
    if _SELECTION_CONTROL_PATTERN.search(text):
        raise _selection_error(f"{field_name} contains control characters.", value=text[:160])
    if not allow_command_separator and any(char in text for char in _SELECTION_FORBIDDEN_COMMAND_CHARS):
        raise _selection_error(f"{field_name} contains a command separator.", value=text[:160])
    return text


def _normalize_selection_name(value: Any, *, field_name: str = "name") -> str:
    """Normalize a portable named-selection identifier."""

    text = _normalize_selection_text(value, field_name=field_name)
    if not _SELECTION_NAME_PATTERN.fullmatch(text):
        raise _selection_error(
            f"{field_name} contains unsupported characters.",
            value=text,
            expected=SELECTION_SAFE_NAME_PATTERN,
        )
    return text


def _normalize_selection_sources(values: Iterable[Any]) -> Tuple[str, ...]:
    """Return unique non-empty source identifiers."""

    output: List[str] = []
    seen: Set[str] = set()
    for value in values:
        if value is None:
            continue
        text = str(value).strip()
        if text and text not in seen:
            output.append(text)
            seen.add(text)
    return tuple(output)


def _selection_component(
    value: Any,
    *,
    field_name: str,
    pattern: re.Pattern[str],
    strict: bool = True,
) -> Optional[str]:
    """Normalize one hierarchical atomspec component."""

    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    if _SELECTION_CONTROL_PATTERN.search(text) or ";" in text:
        raise _selection_error(f"Unsafe {field_name} component.", value=text)
    if pattern.fullmatch(text):
        return text
    if strict:
        raise _selection_error(
            f"Unsupported {field_name} component.",
            value=text,
            expected=pattern.pattern,
        )
    return None


def _balanced_selection_parentheses(expression: str) -> bool:
    """Return whether parentheses are balanced."""

    depth = 0
    for char in expression:
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0


def _wrapped_selection(expression: str) -> str:
    """Wrap compound expressions once."""

    text = expression.strip()
    if not text:
        return text
    if text.startswith("(") and text.endswith(")") and _balanced_selection_parentheses(text[1:-1]):
        return text
    if any(token in text for token in (" | ", " & ")):
        return f"({text})"
    return text


def infer_selection_kind(expression: Any) -> SelectionKind:
    """Infer the most specific selection kind from text."""

    text = _normalize_selection_text(expression, allow_empty=True)
    lowered = text.lower()
    if not text or lowered in EMPTY_SELECTION_TOKENS or lowered == SELECTION_NONE:
        return SelectionKind.NONE
    if lowered == SELECTION_ALL:
        return SelectionKind.ALL
    if lowered == SELECTION_CURRENT:
        return SelectionKind.CURRENT
    if any(operator in text for operator in (SELECTION_COMBINE_OPERATOR, SELECTION_INTERSECT_OPERATOR, SELECTION_NEGATE_OPERATOR)):
        return SelectionKind.CUSTOM
    if SELECTION_ATOM_PREFIX in text:
        return SelectionKind.ATOM
    if SELECTION_RESIDUE_PREFIX in text:
        return SelectionKind.RESIDUE
    if SELECTION_CHAIN_PREFIX in text:
        return SelectionKind.CHAIN
    if text.startswith(SELECTION_MODEL_PREFIX):
        return SelectionKind.MODEL
    return SelectionKind.ATOMSPEC


def validate_selection_expression(expression: Any, *, strict: bool = False) -> Tuple[str, ...]:
    """Return portable syntax and safety issues."""

    issues: List[str] = []
    try:
        text = _normalize_selection_text(expression, allow_empty=True)
    except VisualizationSelectionError as exc:
        issues.append(str(exc))
        if strict:
            raise
        return tuple(issues)
    if not text:
        issues.append("Selection expression is empty.")
    if text and not _balanced_selection_parentheses(text):
        issues.append("Selection parentheses are unbalanced.")
    if text.endswith((SELECTION_COMBINE_OPERATOR, SELECTION_INTERSECT_OPERATOR, SELECTION_NEGATE_OPERATOR)):
        issues.append("Selection expression ends with an operator.")
    if strict and issues:
        raise _selection_error("Invalid selection expression.", value=text, issues=issues)
    return tuple(issues)


# 7.2. Selection specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class MolecularSelection(MolecularSpecMixin):
    """Backend-neutral molecular selection."""

    expression: str
    kind: SelectionKind = SelectionKind.ATOMSPEC
    paths: Tuple[MolecularPathSpec, ...] = ()
    source_ids: Tuple[str, ...] = ()
    label: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        expression = _normalize_selection_text(self.expression, allow_empty=True)
        if not expression:
            expression = SELECTION_NONE
        kind = SelectionKind.parse(self.kind, default=infer_selection_kind(expression))
        paths = tuple(dict.fromkeys(coerce_molecular_path(path) for path in self.paths))
        source_ids = _normalize_selection_sources(self.source_ids)
        label = _clean_spec_text(self.label, field_name="label")
        metadata = _normalize_spec_metadata(self.metadata)
        issues = validate_selection_expression(expression)
        if issues:
            raise _selection_error("Invalid molecular selection.", value=expression, issues=issues)
        object.__setattr__(self, "expression", expression)
        object.__setattr__(self, "kind", kind)
        object.__setattr__(self, "paths", paths)
        object.__setattr__(self, "source_ids", source_ids)
        object.__setattr__(self, "label", label)
        object.__setattr__(self, "metadata", metadata)

    @classmethod
    def all(cls, *, label: Optional[str] = None) -> "MolecularSelection":
        return cls(SELECTION_ALL, SelectionKind.ALL, label=label)

    @classmethod
    def none(cls, *, label: Optional[str] = None) -> "MolecularSelection":
        return cls(SELECTION_NONE, SelectionKind.NONE, label=label)

    @classmethod
    def current(cls, *, label: Optional[str] = None) -> "MolecularSelection":
        return cls(SELECTION_CURRENT, SelectionKind.CURRENT, label=label)

    @property
    def is_all(self) -> bool:
        return self.expression.lower() == SELECTION_ALL

    @property
    def is_none(self) -> bool:
        return self.expression.lower() in {SELECTION_NONE, *EMPTY_SELECTION_TOKENS}

    @property
    def is_current(self) -> bool:
        return self.expression.lower() == SELECTION_CURRENT

    @property
    def is_compound(self) -> bool:
        return any(token in self.expression for token in (" | ", " & ", "~("))

    def command_argument(self, *, blank_all: bool = False) -> str:
        if blank_all and self.is_all:
            return ""
        return self.expression

    def with_label(self, label: Optional[str]) -> "MolecularSelection":
        return replace(self, label=label)

    def __bool__(self) -> bool:
        return not self.is_none

    def __or__(self, other: Any) -> "MolecularSelection":
        return selection_union(self, other)

    def __and__(self, other: Any) -> "MolecularSelection":
        return selection_intersection(self, other)

    def __sub__(self, other: Any) -> "MolecularSelection":
        return selection_difference(self, other)

    def __invert__(self) -> "MolecularSelection":
        return selection_negation(self)


@dataclass(frozen=True, slots=True)
class NamedSelectionSpec(MolecularSpecMixin):
    """Named selection and lifecycle metadata."""

    name: str
    selection: MolecularSelection
    description: Optional[str] = None
    persistent: bool = False
    replace_existing: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", _normalize_selection_name(self.name))
        object.__setattr__(self, "selection", coerce_selection(self.selection))
        object.__setattr__(self, "description", _clean_spec_text(self.description, field_name="description", max_length=1024))
        object.__setattr__(self, "persistent", bool(self.persistent))
        object.__setattr__(self, "replace_existing", bool(self.replace_existing))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))


@dataclass(frozen=True, slots=True)
class SelectionCollection(MolecularSpecMixin):
    """Ordered unique selections."""

    selections: Tuple[MolecularSelection, ...] = ()
    label: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        normalized: List[MolecularSelection] = []
        seen: Set[str] = set()
        for value in self.selections:
            selection = coerce_selection(value)
            if selection.expression not in seen:
                normalized.append(selection)
                seen.add(selection.expression)
        object.__setattr__(self, "selections", tuple(normalized))
        object.__setattr__(self, "label", _clean_spec_text(self.label, field_name="label"))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def combined(self) -> MolecularSelection:
        return selection_union(*self.selections)

    def by_kind(self, kind: Any) -> Tuple[MolecularSelection, ...]:
        parsed = SelectionKind.parse(kind)
        return tuple(item for item in self.selections if item.kind is parsed)


@dataclass(frozen=True, slots=True)
class MolecularSelectionBundle(MolecularSpecMixin):
    """Role-specific selections for a molecular scene."""

    receptor: MolecularSelection = field(default_factory=MolecularSelection.none)
    ligands: MolecularSelection = field(default_factory=MolecularSelection.none)
    cofactors: MolecularSelection = field(default_factory=MolecularSelection.none)
    solvent: MolecularSelection = field(default_factory=MolecularSelection.none)
    ions: MolecularSelection = field(default_factory=MolecularSelection.none)
    poses: Mapping[str, MolecularSelection] = field(default_factory=dict, compare=False, hash=False)
    named: Tuple[NamedSelectionSpec, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        pose_map = {
            str(key): coerce_selection(value)
            for key, value in dict(self.poses).items()
        }
        named = tuple(
            value if isinstance(value, NamedSelectionSpec) else NamedSelectionSpec(**value)
            for value in self.named
        )
        names = [value.name for value in named]
        if len(names) != len(set(names)):
            raise _selection_error("Named selection identifiers must be unique.", names=names)
        object.__setattr__(self, "receptor", coerce_selection(self.receptor))
        object.__setattr__(self, "ligands", coerce_selection(self.ligands))
        object.__setattr__(self, "cofactors", coerce_selection(self.cofactors))
        object.__setattr__(self, "solvent", coerce_selection(self.solvent))
        object.__setattr__(self, "ions", coerce_selection(self.ions))
        object.__setattr__(self, "poses", MappingProxyType(pose_map))
        object.__setattr__(self, "named", named)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def all_molecules(self) -> MolecularSelection:
        return selection_union(self.receptor, self.ligands, self.cofactors, self.solvent, self.ions)

    @property
    def all_poses(self) -> MolecularSelection:
        return selection_union(*self.poses.values())

    def for_role(self, role: Any) -> MolecularSelection:
        parsed = MolecularRole.parse(role, default=MolecularRole.UNKNOWN)
        mapping = {
            MolecularRole.RECEPTOR: self.receptor,
            MolecularRole.LIGAND: self.ligands,
            MolecularRole.COFACTOR: self.cofactors,
            MolecularRole.SOLVENT: self.solvent,
            MolecularRole.ION: self.ions,
        }
        return mapping.get(parsed, MolecularSelection.none())


SelectionInput: TypeAlias = Union[
    MolecularSelection,
    MolecularPathSpec,
    AtomSpec,
    ResidueSpec,
    ChainSpec,
    ModelSpec,
    MolecularGroupSpec,
    MolecularObjectSpec,
    PoseSpec,
    StructureSpec,
    MolecularSpecificationBundle,
    str,
    Mapping[str, Any],
    Sequence[Any],
    Any,
]


# 7.3. Hierarchical atomspec rendering
# -----------------------------------------------------------------------------

def molecular_path_to_selection(
    value: Any,
    *,
    include_residue_name: bool = False,
    include_alt_loc: bool = False,
    strict_components: bool = True,
) -> MolecularSelection:
    """Convert a molecular path to a ChimeraX-compatible atomspec."""

    path = coerce_molecular_path(value)
    model_id = _selection_component(
        path.model_id,
        field_name="model_id",
        pattern=re.compile(r"^[0-9]+(?:\.[0-9]+)*$"),
        strict=strict_components,
    )
    chain_id = _selection_component(
        path.chain_id,
        field_name="chain_id",
        pattern=_SELECTION_NAME_PATTERN,
        strict=strict_components,
    )
    residue_number = _selection_component(
        path.residue_number,
        field_name="residue_number",
        pattern=_SELECTION_RESIDUE_RE,
        strict=strict_components,
    )
    residue_name = _selection_component(
        path.residue_name,
        field_name="residue_name",
        pattern=_SELECTION_NAME_PATTERN,
        strict=strict_components,
    )
    atom_name = _selection_component(
        path.atom_name,
        field_name="atom_name",
        pattern=_SELECTION_ATOM_RE,
        strict=strict_components,
    )
    alt_loc = _selection_component(
        path.alt_loc,
        field_name="alt_loc",
        pattern=_SELECTION_NAME_PATTERN,
        strict=strict_components,
    )

    chunks: List[str] = []
    if model_id:
        chunks.append(f"{SELECTION_MODEL_PREFIX}{model_id}")
    if chain_id:
        chunks.append(f"{SELECTION_CHAIN_PREFIX}{chain_id}")
    residue_token = residue_number
    if residue_token and path.insertion_code:
        insertion = _selection_component(
            path.insertion_code,
            field_name="insertion_code",
            pattern=_SELECTION_NAME_PATTERN,
            strict=strict_components,
        )
        residue_token = f"{residue_token}{insertion or ''}"
    if include_residue_name and residue_name and residue_token is None:
        residue_token = residue_name
    if residue_token:
        chunks.append(f"{SELECTION_RESIDUE_PREFIX}{residue_token}")
    if atom_name:
        atom_token = atom_name
        if include_alt_loc and alt_loc:
            atom_token = f"{atom_token}.{alt_loc}"
        chunks.append(f"{SELECTION_ATOM_PREFIX}{atom_token}")

    expression = "".join(chunks) or SELECTION_ALL
    return MolecularSelection(
        expression=expression,
        kind=path.depth,
        paths=(path,),
        source_ids=(path.source_id,) if path.source_id else (),
        label=path.label,
    )


def atom_spec_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert an atom specification."""

    atom = coerce_atom_spec(value)
    selection = molecular_path_to_selection(atom.path, **kwargs)
    source_ids = (*selection.source_ids, atom.serial_number)
    return replace(selection, source_ids=_normalize_selection_sources(source_ids))


def residue_spec_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a residue specification."""

    residue = coerce_residue_spec(value)
    return molecular_path_to_selection(residue.path, **kwargs)


def chain_spec_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a chain specification."""

    chain = coerce_chain_spec(value)
    return molecular_path_to_selection(chain.path, **kwargs)


def model_spec_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a model specification."""

    model = coerce_model_spec(value)
    return molecular_path_to_selection(model.path, **kwargs)


def simplify_molecular_paths(values: Iterable[Any]) -> Tuple[MolecularPathSpec, ...]:
    """Deduplicate paths and remove descendants of selected parents."""

    paths = tuple(dict.fromkeys(coerce_molecular_path(value) for value in values))
    ordered = sorted(paths, key=lambda item: (tuple(member.value for member in SelectionKind).index(item.depth.value), item.label))
    kept: List[MolecularPathSpec] = []
    for path in ordered:
        if any(_path_contains(parent, path) for parent in kept):
            continue
        kept.append(path)
    return tuple(kept)


def _path_contains(parent: MolecularPathSpec, child: MolecularPathSpec) -> bool:
    """Return whether a path selects another path."""

    fields_to_compare = (
        "model_id",
        "chain_id",
        "residue_number",
        "insertion_code",
        "atom_name",
        "alt_loc",
    )
    for name in fields_to_compare:
        parent_value = getattr(parent, name)
        child_value = getattr(child, name)
        if parent_value is not None and parent_value != child_value:
            return False
    return True


def molecular_paths_to_selection(
    values: Iterable[Any],
    *,
    simplify: bool = True,
    **kwargs: Any,
) -> MolecularSelection:
    """Convert multiple paths to one union selection."""

    paths = tuple(coerce_molecular_path(value) for value in values)
    if simplify:
        paths = simplify_molecular_paths(paths)
    selections = tuple(molecular_path_to_selection(path, **kwargs) for path in paths)
    combined = selection_union(*selections)
    return replace(combined, paths=paths)


# 7.4. Molecular-object conversion
# -----------------------------------------------------------------------------

def molecular_group_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a functional or geometric molecular group."""

    group = value if isinstance(value, MolecularGroupSpec) else MolecularGroupSpec(**value)
    selection = molecular_paths_to_selection((atom.path for atom in group.atoms), **kwargs)
    return replace(selection, source_ids=(group.group_id,), label=group.label or group.group_id)


def molecular_object_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a receptor, ligand or auxiliary object."""

    molecular_object = coerce_molecular_object_spec(value)
    if molecular_object.paths:
        selection = molecular_paths_to_selection(molecular_object.paths, **kwargs)
    elif molecular_object.models:
        selection = selection_union(*(model_spec_to_selection(model, **kwargs) for model in molecular_object.models))
    else:
        selection = MolecularSelection.none()
    return replace(
        selection,
        source_ids=_normalize_selection_sources((*selection.source_ids, molecular_object.object_id)),
        label=molecular_object.name or molecular_object.object_id,
        metadata={**dict(selection.metadata), "role": molecular_object.role.value},
    )


def pose_spec_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert a ligand pose."""

    pose = coerce_pose_spec(value)
    if pose.ligand is not None:
        selection = molecular_object_to_selection(pose.ligand, **kwargs)
    elif pose.model_id:
        selection = molecular_path_to_selection(MolecularPathSpec(model_id=pose.model_id, role=MolecularRole.LIGAND), **kwargs)
    else:
        selection = MolecularSelection.none()
    return replace(
        selection,
        source_ids=_normalize_selection_sources((*selection.source_ids, pose.pose_id)),
        label=pose.pose_id,
        metadata={**dict(selection.metadata), "pose_id": pose.pose_id, "rank": pose.rank},
    )


def structure_spec_to_selection(
    value: Any,
    *,
    prefer_models: bool = True,
    **kwargs: Any,
) -> MolecularSelection:
    """Convert a normalized structure inventory."""

    structure = value if isinstance(value, StructureSpec) else StructureSpec(**value)
    if prefer_models and structure.models:
        selection = selection_union(*(model_spec_to_selection(model, **kwargs) for model in structure.models))
    elif structure.atoms:
        selection = molecular_paths_to_selection((atom.path for atom in structure.atoms), **kwargs)
    elif structure.residues:
        selection = molecular_paths_to_selection((residue.path for residue in structure.residues), **kwargs)
    elif structure.chains:
        selection = molecular_paths_to_selection((chain.path for chain in structure.chains), **kwargs)
    else:
        selection = MolecularSelection.none()
    return replace(selection, source_ids=(structure.structure_id,), label=structure.structure_id)


def specification_bundle_to_selection(value: Any, **kwargs: Any) -> MolecularSelection:
    """Convert all molecular objects in a specification bundle."""

    bundle = value if isinstance(value, MolecularSpecificationBundle) else MolecularSpecificationBundle(**value)
    return selection_union(*(molecular_object_to_selection(item, **kwargs) for item in bundle.objects))


def selection_for_role(value: Any, role: Any, **kwargs: Any) -> MolecularSelection:
    """Select all objects with a molecular role."""

    bundle = value if isinstance(value, MolecularSpecificationBundle) else MolecularSpecificationBundle(**value)
    objects = bundle.objects_by_role(role)
    return selection_union(*(molecular_object_to_selection(item, **kwargs) for item in objects))


def build_molecular_selection_bundle(
    value: Any,
    *,
    name_prefix: Optional[str] = None,
    include_named: bool = True,
    **kwargs: Any,
) -> MolecularSelectionBundle:
    """Build role and pose selections from molecular specifications."""

    bundle = value if isinstance(value, MolecularSpecificationBundle) else MolecularSpecificationBundle(**value)
    receptor = MolecularSelection.none() if bundle.receptor is None else molecular_object_to_selection(bundle.receptor, **kwargs)
    ligands = selection_union(*(molecular_object_to_selection(item, **kwargs) for item in bundle.ligands))
    cofactors = selection_union(*(molecular_object_to_selection(item, **kwargs) for item in bundle.cofactors))
    solvent = selection_union(*(molecular_object_to_selection(item, **kwargs) for item in bundle.solvent))
    ions = selection_union(*(molecular_object_to_selection(item, **kwargs) for item in bundle.ions))
    poses = {pose.pose_id: pose_spec_to_selection(pose, **kwargs) for pose in bundle.poses}
    named: List[NamedSelectionSpec] = []
    if include_named:
        prefix = "" if name_prefix is None else f"{_normalize_selection_name(name_prefix)}_"
        role_items = (
            ("receptor", receptor),
            ("ligands", ligands),
            ("cofactors", cofactors),
            ("solvent", solvent),
            ("ions", ions),
        )
        named.extend(
            NamedSelectionSpec(f"{prefix}{name}", selection)
            for name, selection in role_items
            if selection
        )
        named.extend(
            NamedSelectionSpec(f"{prefix}pose_{_normalize_selection_name(pose_id)}", selection)
            for pose_id, selection in poses.items()
            if selection
        )
    return MolecularSelectionBundle(
        receptor=receptor,
        ligands=ligands,
        cofactors=cofactors,
        solvent=solvent,
        ions=ions,
        poses=poses,
        named=tuple(named),
        metadata={"source": "MolecularSpecificationBundle"},
    )


# 7.5. Generic coercion
# -----------------------------------------------------------------------------

def _object_atomspec(value: Any) -> Optional[str]:
    """Read an atomspec-like attribute without backend imports."""

    for name in ("atomspec", "atom_spec", "spec", "selection"):
        candidate = _object_value(value, name)
        if isinstance(candidate, str) and candidate.strip():
            return candidate.strip()
    return None


def coerce_selection(
    value: Any,
    *,
    strict: bool = True,
    default: Any = None,
    **kwargs: Any,
) -> MolecularSelection:
    """Convert strings, specifications, mappings and objects to a selection."""

    try:
        if isinstance(value, MolecularSelection):
            return value
        if value is None:
            if default is not None:
                return coerce_selection(default, strict=strict, **kwargs)
            return MolecularSelection.none()
        if isinstance(value, str):
            expression = _normalize_selection_text(value, allow_empty=True)
            if not expression:
                return MolecularSelection.none()
            return MolecularSelection(expression, infer_selection_kind(expression))
        if isinstance(value, MolecularPathSpec):
            return molecular_path_to_selection(value, **kwargs)
        if isinstance(value, AtomSpec):
            return atom_spec_to_selection(value, **kwargs)
        if isinstance(value, ResidueSpec):
            return residue_spec_to_selection(value, **kwargs)
        if isinstance(value, ChainSpec):
            return chain_spec_to_selection(value, **kwargs)
        if isinstance(value, ModelSpec):
            return model_spec_to_selection(value, **kwargs)
        if isinstance(value, MolecularGroupSpec):
            return molecular_group_to_selection(value, **kwargs)
        if isinstance(value, MolecularObjectSpec):
            return molecular_object_to_selection(value, **kwargs)
        if isinstance(value, PoseSpec):
            return pose_spec_to_selection(value, **kwargs)
        if isinstance(value, StructureSpec):
            return structure_spec_to_selection(value, **kwargs)
        if isinstance(value, MolecularSpecificationBundle):
            return specification_bundle_to_selection(value, **kwargs)
        if isinstance(value, Mapping):
            expression = value.get("expression", value.get("atomspec", value.get("selection")))
            if expression is not None:
                return MolecularSelection(
                    expression=str(expression),
                    kind=value.get("kind", infer_selection_kind(expression)),
                    paths=tuple(coerce_molecular_path(path) for path in value.get("paths", ())),
                    source_ids=tuple(value.get("source_ids", ())),
                    label=value.get("label"),
                    metadata=value.get("metadata", {}),
                )
            if "pose_id" in value and any(key in value for key in ("ligand", "model_id")):
                return pose_spec_to_selection(value, **kwargs)
            if "object_id" in value:
                return molecular_object_to_selection(value, **kwargs)
            if "group_id" in value:
                return molecular_group_to_selection(value, **kwargs)
            if any(key in value for key in ("atom_name", "residue_number", "chain_id", "model_id")):
                return molecular_path_to_selection(value, **kwargs)
        atomspec = _object_atomspec(value)
        if atomspec:
            return MolecularSelection(
                expression=atomspec,
                kind=infer_selection_kind(atomspec),
                source_ids=_normalize_selection_sources((_object_value(value, "id", "name"),)),
            )
        path = _object_value(value, "path")
        if path is not None:
            return molecular_path_to_selection(path, **kwargs)
        if isinstance(value, Iterable) and not isinstance(value, (bytes, bytearray)):
            return selection_union(*(coerce_selection(item, strict=strict, **kwargs) for item in value))
        path_fields = ("model_id", "chain_id", "residue_number", "residue_name", "atom_name")
        if any(_object_value(value, name) is not None for name in path_fields):
            return molecular_path_to_selection(value, **kwargs)
        raise _selection_error(
            "Unsupported selection input.",
            value_type=type(value).__name__,
        )
    except (VisualizationError, TypeError, ValueError, AttributeError) as exc:
        if strict:
            if isinstance(exc, VisualizationSelectionError):
                raise
            raise _selection_error(
                "Could not convert value to a molecular selection.",
                value_type=type(value).__name__,
                cause=str(exc),
            ) from exc
        return MolecularSelection.none()


def coerce_selections(values: Iterable[Any], *, strict: bool = True, **kwargs: Any) -> Tuple[MolecularSelection, ...]:
    """Normalize a sequence of selections."""

    return tuple(coerce_selection(value, strict=strict, **kwargs) for value in values)


# 7.6. Logical composition
# -----------------------------------------------------------------------------

def _unique_selections(values: Iterable[Any]) -> Tuple[MolecularSelection, ...]:
    """Normalize and deduplicate expressions."""

    selections: List[MolecularSelection] = []
    seen: Set[str] = set()
    for value in values:
        selection = coerce_selection(value)
        if selection.expression not in seen:
            selections.append(selection)
            seen.add(selection.expression)
    return tuple(selections)


def selection_union(*values: Any) -> MolecularSelection:
    """Return the logical union of selections."""

    selections = _unique_selections(values)
    if any(selection.is_all for selection in selections):
        return MolecularSelection.all()
    selections = tuple(selection for selection in selections if not selection.is_none)
    if not selections:
        return MolecularSelection.none()
    if len(selections) == 1:
        return selections[0]
    expression = f" {SELECTION_COMBINE_OPERATOR} ".join(_wrapped_selection(item.expression) for item in selections)
    return MolecularSelection(
        expression,
        SelectionKind.CUSTOM,
        paths=tuple(dict.fromkeys(path for item in selections for path in item.paths)),
        source_ids=_normalize_selection_sources(source for item in selections for source in item.source_ids),
        metadata={"operator": SelectionOperator.UNION.value, "count": len(selections)},
    )


def selection_intersection(*values: Any) -> MolecularSelection:
    """Return the logical intersection of selections."""

    selections = _unique_selections(values)
    if not selections or any(selection.is_none for selection in selections):
        return MolecularSelection.none()
    selections = tuple(selection for selection in selections if not selection.is_all)
    if not selections:
        return MolecularSelection.all()
    if len(selections) == 1:
        return selections[0]
    expression = f" {SELECTION_INTERSECT_OPERATOR} ".join(_wrapped_selection(item.expression) for item in selections)
    return MolecularSelection(
        expression,
        SelectionKind.CUSTOM,
        source_ids=_normalize_selection_sources(source for item in selections for source in item.source_ids),
        metadata={"operator": SelectionOperator.INTERSECTION.value, "count": len(selections)},
    )


def selection_negation(value: Any) -> MolecularSelection:
    """Return the logical complement of a selection."""

    selection = coerce_selection(value)
    if selection.is_all:
        return MolecularSelection.none()
    if selection.is_none:
        return MolecularSelection.all()
    expression = f"{SELECTION_NEGATE_OPERATOR}{_wrapped_selection(selection.expression)}"
    return MolecularSelection(
        expression,
        SelectionKind.CUSTOM,
        source_ids=selection.source_ids,
        metadata={"operator": SelectionOperator.NEGATION.value},
    )


def selection_difference(value: Any, *excluded: Any) -> MolecularSelection:
    """Subtract selections from a base selection."""

    base = coerce_selection(value)
    if base.is_none:
        return base
    exclusion = selection_union(*excluded)
    if exclusion.is_none:
        return base
    if exclusion.is_all:
        return MolecularSelection.none()
    expression = (
        f"{_wrapped_selection(base.expression)} {SELECTION_INTERSECT_OPERATOR} "
        f"{SELECTION_NEGATE_OPERATOR}{_wrapped_selection(exclusion.expression)}"
    )
    return MolecularSelection(
        expression,
        SelectionKind.CUSTOM,
        source_ids=_normalize_selection_sources((*base.source_ids, *exclusion.source_ids)),
        metadata={"operator": SelectionOperator.DIFFERENCE.value},
    )


def combine_selections(operator: Any, *values: Any) -> MolecularSelection:
    """Compose selections with a normalized operator."""

    parsed = SelectionOperator.parse(operator)
    if parsed is SelectionOperator.UNION:
        return selection_union(*values)
    if parsed is SelectionOperator.INTERSECTION:
        return selection_intersection(*values)
    if parsed is SelectionOperator.NEGATION:
        if len(values) != 1:
            raise _selection_error("Negation requires exactly one selection.", count=len(values))
        return selection_negation(values[0])
    if not values:
        return MolecularSelection.none()
    return selection_difference(values[0], *values[1:])


# 7.7. Selection partitioning and inspection
# -----------------------------------------------------------------------------

def partition_selection(
    values: Iterable[Any],
    *,
    maximum_length: int = DEFAULT_COMMAND_MAX_LENGTH,
) -> Tuple[MolecularSelection, ...]:
    """Partition union terms without exceeding a command-size limit."""

    if isinstance(maximum_length, bool) or not isinstance(maximum_length, int) or maximum_length < 1:
        raise _selection_error("maximum_length must be a positive integer.", value=maximum_length)
    maximum_length = min(maximum_length, MAX_SELECTION_LENGTH)
    selections = tuple(item for item in _unique_selections(values) if not item.is_none)
    if not selections:
        return (MolecularSelection.none(),)
    chunks: List[MolecularSelection] = []
    current: List[MolecularSelection] = []
    for selection in selections:
        if len(selection.expression) > maximum_length:
            raise _selection_error(
                "A selection term exceeds maximum_length.",
                value=selection.expression[:160],
                length=len(selection.expression),
                maximum=maximum_length,
            )
        candidate = selection_union(*current, selection)
        if current and len(candidate.expression) > maximum_length:
            chunks.append(selection_union(*current))
            current = [selection]
        else:
            current.append(selection)
    if current:
        chunks.append(selection_union(*current))
    return tuple(chunks)


def selection_contains(container: Any, candidate: Any) -> bool:
    """Return a conservative containment result."""

    outer = coerce_selection(container)
    inner = coerce_selection(candidate)
    if outer.is_all or inner.is_none or outer.expression == inner.expression:
        return True
    if outer.is_none:
        return False
    if outer.paths and inner.paths:
        return all(any(_path_contains(parent, path) for parent in outer.paths) for path in inner.paths)
    return False


def selection_equivalent(left: Any, right: Any) -> bool:
    """Compare normalized expressions and path identities."""

    first = coerce_selection(left)
    second = coerce_selection(right)
    if first.expression == second.expression:
        return True
    return bool(first.paths and second.paths and set(first.paths) == set(second.paths))


def selection_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize a normalized selection."""

    return coerce_selection(value).to_dict()


def selection_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize a normalized selection as JSON."""

    return json.dumps(selection_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


def selection_fingerprint(value: Any) -> str:
    """Return a stable selection digest."""

    return coerce_selection(value).fingerprint()


def describe_selection(value: Any) -> Dict[str, Any]:
    """Return a compact selection summary."""

    selection = coerce_selection(value)
    return {
        "expression": selection.expression,
        "kind": selection.kind.value,
        "label": selection.label,
        "path_count": len(selection.paths),
        "source_count": len(selection.source_ids),
        "is_all": selection.is_all,
        "is_none": selection.is_none,
        "is_current": selection.is_current,
        "is_compound": selection.is_compound,
        "length": len(selection.expression),
        "fingerprint": selection.fingerprint(),
        "issues": validate_selection_expression(selection.expression),
    }


