def _interaction_text(value: Any, *, field_name: str, maximum: int = 256) -> Optional[str]:
    """Normalize optional interaction text."""

    return _clean_spec_text(value, field_name=field_name, max_length=maximum)


def _interaction_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> Optional[float]:
    """Normalize an optional interaction number."""

    return _optional_spec_float(value, field_name=field_name, minimum=minimum, maximum=maximum)


@dataclass(frozen=True, slots=True)
class InteractionEndpointSpec(MolecularSpecMixin):
    """One visual interaction endpoint."""

    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    point: Optional[Point3D] = None
    path: Optional[MolecularPathSpec] = None
    label: Optional[str] = None
    role: MolecularRole = MolecularRole.UNKNOWN
    source_id: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        requested_role = MolecularRole.parse(self.role, default=MolecularRole.UNKNOWN)
        path_role = None if requested_role is MolecularRole.UNKNOWN else requested_role
        path = None if self.path is None else coerce_molecular_path(self.path, role=path_role)
        selection = coerce_selection(self.selection)
        if selection.is_none and path is not None:
            selection = molecular_path_to_selection(path)
        point = normalize_point3d(self.point, field_name="point", allow_none=True)
        if selection.is_none and point is None:
            raise VisualizationInteractionError("An interaction endpoint requires a selection or point.")
        role = path.role if requested_role is MolecularRole.UNKNOWN and path else requested_role
        object.__setattr__(self, "selection", selection)
        object.__setattr__(self, "point", point)
        object.__setattr__(self, "path", path)
        object.__setattr__(self, "label", _interaction_text(self.label, field_name="label"))
        object.__setattr__(self, "role", role)
        object.__setattr__(self, "source_id", _interaction_text(self.source_id, field_name="source_id"))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def effective_label(self) -> str:
        return self.label or (self.path.label if self.path else self.selection.label) or self.selection.expression

    @property
    def residue_key(self) -> Optional[Tuple[Any, ...]]:
        return None if self.path is None else self.path.residue_key

    @property
    def key(self) -> Tuple[Any, ...]:
        if self.path is not None:
            return ("path", *self.path.atom_key)
        if not self.selection.is_none:
            return ("selection", self.selection.expression)
        return ("point", *(self.point or ()))


@dataclass(frozen=True, slots=True)
class InteractionStyleSpec(MolecularSpecMixin):
    """Resolved interaction appearance."""

    family: InteractionFamily = InteractionFamily.UNKNOWN
    render_mode: InteractionRenderMode = InteractionRenderMode.PSEUDOBOND
    line_style: LineStyle = LineStyle.DASHED
    color: Optional[str] = None
    radius: float = DEFAULT_INTERACTION_RADIUS
    opacity: float = DEFAULT_INTERACTION_OPACITY
    dash_count: int = DEFAULT_INTERACTION_DASH_COUNT
    group_name: str = DEFAULT_PSEUDOBOND_GROUP
    visible: bool = True
    show_distance: bool = False
    show_label: bool = False

    def __post_init__(self) -> None:
        family = InteractionFamily.parse(self.family, default=InteractionFamily.UNKNOWN)
        render_mode = InteractionRenderMode.parse(self.render_mode, default=InteractionRenderMode.PSEUDOBOND)
        object.__setattr__(self, "family", family)
        object.__setattr__(self, "render_mode", render_mode)
        object.__setattr__(self, "line_style", LineStyle.parse(self.line_style, default=LineStyle.DASHED))
        object.__setattr__(self, "color", normalize_color(self.color or family.default_color))
        object.__setattr__(self, "radius", _bounded_float(self.radius, field_name="radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
        object.__setattr__(self, "opacity", _bounded_float(self.opacity, field_name="opacity", minimum=0.0, maximum=1.0))
        object.__setattr__(self, "dash_count", _bounded_int(self.dash_count, field_name="dash_count", minimum=0, maximum=1000))
        object.__setattr__(self, "group_name", _clean_config_name(self.group_name, field_name="group_name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "visible", bool(self.visible) and render_mode is not InteractionRenderMode.HIDDEN)
        object.__setattr__(self, "show_distance", bool(self.show_distance))
        object.__setattr__(self, "show_label", bool(self.show_label))


# 8.2. Interaction specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class VisualInteractionSpec(MolecularSpecMixin):
    """Backend-neutral visual interaction."""

    interaction_id: str
    family: InteractionFamily
    source: InteractionEndpointSpec
    target: InteractionEndpointSpec
    subtype: Optional[str] = None
    strength: InteractionStrength = InteractionStrength.UNKNOWN
    confidence: ConfidenceLevel = ConfidenceLevel.UNKNOWN
    distance: Optional[float] = None
    angle: Optional[float] = None
    offset: Optional[float] = None
    score: Optional[float] = None
    pose_id: Optional[str] = None
    label: Optional[str] = None
    style: Optional[InteractionStyleSpec] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        family = InteractionFamily.parse(self.family, default=InteractionFamily.UNKNOWN)
        source = coerce_interaction_endpoint(self.source)
        target = coerce_interaction_endpoint(self.target)
        style = self.style
        if style is None:
            style = resolve_interaction_style(family, strength=self.strength, confidence=self.confidence)
        elif not isinstance(style, InteractionStyleSpec):
            style = resolve_interaction_style(family, overrides=style, strength=self.strength, confidence=self.confidence)
        elif style.family is not family:
            style = replace(style, family=family)
        distance = _interaction_float(self.distance, field_name="distance", minimum=0.0)
        if distance is None and source.point is not None and target.point is not None:
            distance = math.dist(source.point, target.point)
        object.__setattr__(self, "interaction_id", _clean_config_name(self.interaction_id, field_name="interaction_id", maximum=MAX_VISUALIZATION_NAME_LENGTH))
        object.__setattr__(self, "family", family)
        object.__setattr__(self, "source", source)
        object.__setattr__(self, "target", target)
        object.__setattr__(self, "subtype", _interaction_text(self.subtype, field_name="subtype"))
        object.__setattr__(self, "strength", InteractionStrength.parse(self.strength, default=InteractionStrength.UNKNOWN))
        object.__setattr__(self, "confidence", ConfidenceLevel.parse(self.confidence, default=ConfidenceLevel.UNKNOWN))
        object.__setattr__(self, "distance", distance)
        object.__setattr__(self, "angle", _interaction_float(self.angle, field_name="angle", minimum=0.0, maximum=360.0))
        object.__setattr__(self, "offset", _interaction_float(self.offset, field_name="offset", minimum=0.0))
        object.__setattr__(self, "score", _interaction_float(self.score, field_name="score"))
        object.__setattr__(self, "pose_id", _interaction_text(self.pose_id, field_name="pose_id"))
        object.__setattr__(self, "label", _interaction_text(self.label, field_name="label", maximum=MAX_LABEL_TEXT_LENGTH))
        object.__setattr__(self, "style", style)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def midpoint(self) -> Optional[Point3D]:
        if self.source.point is None or self.target.point is None:
            return None
        return tuple((left + right) / 2.0 for left, right in zip(self.source.point, self.target.point))  # type: ignore[return-value]

    @property
    def direction(self) -> Optional[Vector3D]:
        if self.source.point is None or self.target.point is None:
            return None
        delta = tuple(right - left for left, right in zip(self.source.point, self.target.point))
        norm = math.sqrt(sum(value * value for value in delta))
        if norm <= VISUALIZATION_COORDINATE_EPSILON:
            return None
        return tuple(value / norm for value in delta)  # type: ignore[return-value]

    @property
    def residue_pair(self) -> Tuple[Optional[Tuple[Any, ...]], Optional[Tuple[Any, ...]]]:
        return self.source.residue_key, self.target.residue_key

    @property
    def selections(self) -> Tuple[MolecularSelection, MolecularSelection]:
        return self.source.selection, self.target.selection

    @property
    def visible(self) -> bool:
        return bool(self.style and self.style.visible)


@dataclass(frozen=True, slots=True)
class VisualInteractionCollection(MolecularSpecMixin):
    """Ordered visual interaction set."""

    interactions: Tuple[VisualInteractionSpec, ...] = ()
    name: str = DEFAULT_PSEUDOBOND_GROUP
    pose_id: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        values = tuple(coerce_visual_interaction(item, index=index) for index, item in enumerate(self.interactions))
        identifiers = [item.interaction_id for item in values]
        if len(identifiers) != len(set(identifiers)):
            raise VisualizationInteractionError("Interaction identifiers must be unique.", context={"duplicates": [key for key, count in Counter(identifiers).items() if count > 1]})
        object.__setattr__(self, "interactions", values)
        object.__setattr__(self, "name", _clean_config_name(self.name, field_name="name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "pose_id", _interaction_text(self.pose_id, field_name="pose_id"))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def by_family(self, family: Any) -> Tuple[VisualInteractionSpec, ...]:
        parsed = InteractionFamily.parse(family, default=InteractionFamily.UNKNOWN)
        return tuple(item for item in self.interactions if item.family is parsed)

    def by_pose(self, pose_id: Any) -> Tuple[VisualInteractionSpec, ...]:
        token = str(pose_id)
        return tuple(item for item in self.interactions if item.pose_id == token)

    @property
    def visible(self) -> Tuple[VisualInteractionSpec, ...]:
        return tuple(item for item in self.interactions if item.visible)

    @property
    def families(self) -> Mapping[InteractionFamily, Tuple[VisualInteractionSpec, ...]]:
        return MappingProxyType(group_visual_interactions(self.interactions))

    @property
    def involved_selection(self) -> MolecularSelection:
        selections = [endpoint for item in self.interactions for endpoint in item.selections if not endpoint.is_none]
        return selection_union(*selections)


# 8.3. Inference and endpoint conversion
# -----------------------------------------------------------------------------

def _normalized_interaction_token(value: Any) -> str:
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", str(value or ""))
    return re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")


def infer_interaction_family(value: Any, *, default: Any = InteractionFamily.UNKNOWN) -> InteractionFamily:
    """Infer an interaction family."""

    explicit = _object_value(value, "family", "interaction_family", "interaction_type", "type", "kind", "category")
    parsed = InteractionFamily.parse(explicit, strict=False)
    if parsed is not None:
        return parsed
    tokens = [explicit, type(value).__name__, type(value).__module__]
    for candidate in tokens:
        token = _normalized_interaction_token(candidate)
        for hint, family in _INTERACTION_FAMILY_HINTS:
            if hint in token:
                return family
    return InteractionFamily.parse(default, default=InteractionFamily.UNKNOWN)


def infer_interaction_strength(value: Any, *, default: Any = InteractionStrength.UNKNOWN) -> InteractionStrength:
    """Infer a qualitative strength."""

    raw = _object_value(value, "strength", "strength_class", "quality", "classification")
    parsed = InteractionStrength.parse(raw, strict=False)
    if parsed is not None:
        return parsed
    token = _normalized_interaction_token(raw)
    mapping = {
        "optimal": InteractionStrength.STRONG,
        "favorable": InteractionStrength.MODERATE,
        "accepted": InteractionStrength.MODERATE,
        "marginal": InteractionStrength.BORDERLINE,
        "rejected": InteractionStrength.WEAK,
    }
    return mapping.get(token, InteractionStrength.parse(default, default=InteractionStrength.UNKNOWN))


def infer_interaction_confidence(value: Any, *, default: Any = ConfidenceLevel.UNKNOWN) -> ConfidenceLevel:
    """Infer a confidence level."""

    raw = _object_value(value, "confidence", "confidence_level", "certainty")
    return ConfidenceLevel.parse(raw, default=default, strict=False) or ConfidenceLevel.UNKNOWN


def _path_from_endpoint(value: Any, role: Any) -> Optional[MolecularPathSpec]:
    if isinstance(value, MolecularPathSpec):
        return coerce_molecular_path(value, role=role)
    if isinstance(value, (AtomSpec, ResidueSpec, ChainSpec, ModelSpec)):
        return coerce_molecular_path(value, role=role)
    try:
        path = coerce_molecular_path(value, role=role)
    except (VisualizationError, TypeError, ValueError, AttributeError):
        return None
    return path if path.depth is not SelectionKind.ALL else None


def coerce_interaction_endpoint(
    value: Any,
    *,
    role: Any = None,
    label: Optional[str] = None,
) -> InteractionEndpointSpec:
    """Convert an atom, group, selection or point to an endpoint."""

    if isinstance(value, InteractionEndpointSpec):
        changes: Dict[str, Any] = {}
        if role is not None:
            changes["role"] = role
        if label is not None:
            changes["label"] = label
        return value if not changes else replace(value, **changes)

    parsed_role = infer_molecular_role(value, default=role or MolecularRole.UNKNOWN)
    selection = MolecularSelection.none()
    point: Any = None
    path: Optional[MolecularPathSpec] = None
    source_id = _object_value(value, "source_id", "identifier", "uid", "id")
    endpoint_label = label or _object_value(value, "label", "display_name")
    metadata = _object_value(value, "metadata", default={}) or {}

    if isinstance(value, AtomSpec):
        path, point, selection = value.path, value.coordinate, atom_spec_to_selection(value)
    elif isinstance(value, ResidueSpec):
        path, point, selection = value.path, value.center, residue_spec_to_selection(value)
    elif isinstance(value, MolecularGroupSpec):
        point = value.effective_center
        selection = molecular_paths_to_selection(value.paths) if value.paths else MolecularSelection.none()
        if not selection.is_none:
            selection = replace(selection, source_ids=(value.group_id,), label=value.group_id)
        source_id = source_id or value.group_id
        endpoint_label = endpoint_label or value.group_id
    elif isinstance(value, MolecularPathSpec):
        path, selection = value, molecular_path_to_selection(value)
    elif isinstance(value, MolecularSelection):
        selection = value
    elif isinstance(value, str):
        selection = coerce_selection(value)
    elif isinstance(value, Mapping):
        raw_selection = value.get("selection", value.get("atomspec"))
        raw_path = value.get("path")
        path = None if raw_path is None else coerce_molecular_path(raw_path, role=parsed_role)
        if raw_selection is not None:
            selection = coerce_selection(raw_selection)
        elif path is not None:
            selection = molecular_path_to_selection(path)
        point = value.get("point", value.get("coordinate", value.get("center", value.get("centroid"))))
    else:
        raw_selection = _object_value(value, "selection", "atomspec")
        if raw_selection is not None:
            selection = coerce_selection(raw_selection)
        path = _path_from_endpoint(value, parsed_role)
        if selection.is_none and path is not None:
            selection = molecular_path_to_selection(path)
        point = _object_value(value, "point", "scene_coord", "coord", "coordinate", "center", "centroid")

    return InteractionEndpointSpec(
        selection=selection,
        point=point,
        path=path,
        label=endpoint_label,
        role=parsed_role,
        source_id=source_id,
        metadata=metadata,
    )


def _interaction_pair(value: Any) -> Tuple[Any, Any]:
    for first_name, second_name in _INTERACTION_PAIR_FIELDS:
        first = _object_value(value, first_name, default=_MISSING_SPEC_VALUE)
        second = _object_value(value, second_name, default=_MISSING_SPEC_VALUE)
        if first is not _MISSING_SPEC_VALUE and second is not _MISSING_SPEC_VALUE:
            return first, second
    participants = _object_value(value, "participants", "endpoints", "atoms", "groups")
    if isinstance(participants, Sequence) and not isinstance(participants, (str, bytes)) and len(participants) >= 2:
        return participants[0], participants[1]
    raise VisualizationInteractionError(
        "Interaction endpoints were not found.",
        context={"value_type": type(value).__name__},
    )


# 8.4. Style and interaction conversion
# -----------------------------------------------------------------------------

def resolve_interaction_style(
    family: Any,
    *,
    config_value: Any = None,
    strength: Any = None,
    confidence: Any = None,
    overrides: Any = None,
) -> InteractionStyleSpec:
    """Resolve final interaction appearance."""

    parsed_family = InteractionFamily.parse(family, default=InteractionFamily.UNKNOWN)
    config_obj = resolve_visualization_config(config_value)
    base = config_obj.interactions
    payload: Dict[str, Any] = {
        "family": parsed_family,
        "render_mode": base.render_mode,
        "line_style": base.line_style,
        "color": base.color_for(parsed_family, config_obj.palette),
        "radius": base.radius_for(parsed_family, strength),
        "opacity": base.opacity_for(strength, confidence),
        "dash_count": base.dash_count,
        "group_name": f"{base.group_name} — {parsed_family.label}",
        "visible": True,
    }
    if isinstance(overrides, InteractionStyleSpec):
        payload.update(overrides.to_dict())
    elif isinstance(overrides, Mapping):
        payload.update({key: value for key, value in overrides.items() if key in _INTERACTION_STYLE_FIELDS})
    elif overrides is not None:
        payload.update({
            key: getattr(overrides, key)
            for key in _INTERACTION_STYLE_FIELDS
            if hasattr(overrides, key)
        })
    payload["family"] = parsed_family
    return InteractionStyleSpec(**payload)


def _interaction_identifier(
    family: InteractionFamily,
    source: InteractionEndpointSpec,
    target: InteractionEndpointSpec,
    *,
    explicit: Any = None,
    index: int = 0,
) -> str:
    if explicit is not None and str(explicit).strip():
        return str(explicit).strip()
    payload = repr((family.value, source.key, target.key, index)).encode("utf-8")
    return f"{family.value}_{sha256(payload).hexdigest()[:12]}"


def coerce_visual_interaction(
    value: Any,
    *,
    index: int = 0,
    config_value: Any = None,
    pose_id: Optional[str] = None,
) -> VisualInteractionSpec:
    """Convert an analysis result to a visual interaction."""

    if isinstance(value, VisualInteractionSpec):
        changes: Dict[str, Any] = {}
        if pose_id is not None and value.pose_id is None:
            changes["pose_id"] = pose_id
        if config_value is not None:
            changes["style"] = resolve_interaction_style(
                value.family,
                config_value=config_value,
                strength=value.strength,
                confidence=value.confidence,
                overrides=value.style,
            )
        return value if not changes else replace(value, **changes)

    family = infer_interaction_family(value)
    strength = infer_interaction_strength(value)
    confidence = infer_interaction_confidence(value)
    source_raw, target_raw = _interaction_pair(value)
    source = coerce_interaction_endpoint(source_raw)
    target = coerce_interaction_endpoint(target_raw)
    style_raw = _object_value(value, "visual_style", "style")
    style = resolve_interaction_style(
        family,
        config_value=config_value,
        strength=strength,
        confidence=confidence,
        overrides=style_raw,
    )
    explicit_id = _object_value(value, "interaction_id", "identifier", "uid", "id")
    resolved_pose = pose_id or _object_value(value, "pose_id", "pose", "model_id")
    return VisualInteractionSpec(
        interaction_id=_interaction_identifier(family, source, target, explicit=explicit_id, index=index),
        family=family,
        source=source,
        target=target,
        subtype=_object_value(value, "subtype", "geometry", "interaction_subtype", "classification"),
        strength=strength,
        confidence=confidence,
        distance=_object_value(value, "distance", "centroid_distance", "minimum_distance", "min_distance"),
        angle=_object_value(value, "angle", "plane_angle", "donor_angle", "orientation_angle"),
        offset=_object_value(value, "offset", "lateral_offset", "radial_offset"),
        score=_object_value(value, "score", "interaction_score", "quality_score"),
        pose_id=resolved_pose,
        label=_object_value(value, "label", "description"),
        style=style,
        metadata=_object_value(value, "metadata", default={}) or {},
    )


def _looks_like_interaction_mapping(value: Mapping[str, Any]) -> bool:
    keys = {str(key) for key in value}
    if keys & {"family", "interaction_family", "interaction_type", "source", "target"}:
        return True
    return any(first in keys and second in keys for first, second in _INTERACTION_PAIR_FIELDS)


def _iter_interaction_values(values: Any) -> Iterator[Any]:
    if values is None:
        return
    if isinstance(values, VisualInteractionCollection):
        yield from values.interactions
        return
    if isinstance(values, Mapping) and not _looks_like_interaction_mapping(values):
        for item in values.values():
            if isinstance(item, Iterable) and not isinstance(item, (str, bytes, Mapping)):
                yield from item
            else:
                yield item
        return
    if isinstance(values, Iterable) and not isinstance(values, (str, bytes, Mapping, VisualInteractionSpec)):
        yield from values
        return
    yield values


# 8.5. Collections, filtering and summaries
# -----------------------------------------------------------------------------

def interaction_visual_key(value: Any, *, directed: bool = False) -> Tuple[Any, ...]:
    """Return a display-level identity key."""

    item = coerce_visual_interaction(value)
    endpoints = (item.source.key, item.target.key)
    if not directed:
        endpoints = tuple(sorted(endpoints, key=repr))  # type: ignore[assignment]
    return item.family.value, item.subtype, *endpoints, item.pose_id


def deduplicate_visual_interactions(
    values: Iterable[Any],
    *,
    directed: bool = False,
) -> Tuple[VisualInteractionSpec, ...]:
    """Remove duplicate interaction segments."""

    result: List[VisualInteractionSpec] = []
    seen: Set[Tuple[Any, ...]] = set()
    for index, value in enumerate(values):
        item = coerce_visual_interaction(value, index=index)
        key = interaction_visual_key(item, directed=directed)
        if key not in seen:
            result.append(item)
            seen.add(key)
    return tuple(result)


def sort_visual_interactions(
    values: Iterable[Any],
    *,
    descending: bool = True,
) -> Tuple[VisualInteractionSpec, ...]:
    """Sort by strength, score and distance."""

    strength_rank = {
        InteractionStrength.STRONG: 4,
        InteractionStrength.MODERATE: 3,
        InteractionStrength.WEAK: 2,
        InteractionStrength.BORDERLINE: 1,
        InteractionStrength.UNKNOWN: 0,
    }
    items = tuple(coerce_visual_interaction(value, index=index) for index, value in enumerate(values))
    return tuple(sorted(
        items,
        key=lambda item: (
            strength_rank[item.strength],
            item.score if item.score is not None else -math.inf,
            -(item.distance if item.distance is not None else math.inf),
        ),
        reverse=descending,
    ))


def filter_visual_interactions(
    values: Iterable[Any],
    *,
    families: Optional[Iterable[Any]] = None,
    strengths: Optional[Iterable[Any]] = None,
    pose_id: Optional[str] = None,
    visible_only: bool = False,
) -> Tuple[VisualInteractionSpec, ...]:
    """Filter visual interactions."""

    family_set = None if families is None else {InteractionFamily.parse(item) for item in families}
    strength_set = None if strengths is None else {InteractionStrength.parse(item) for item in strengths}
    result: List[VisualInteractionSpec] = []
    for index, value in enumerate(values):
        item = coerce_visual_interaction(value, index=index)
        if family_set is not None and item.family not in family_set:
            continue
        if strength_set is not None and item.strength not in strength_set:
            continue
        if pose_id is not None and item.pose_id != str(pose_id):
            continue
        if visible_only and not item.visible:
            continue
        result.append(item)
    return tuple(result)


def group_visual_interactions(
    values: Iterable[Any],
) -> Dict[InteractionFamily, Tuple[VisualInteractionSpec, ...]]:
    """Group interactions by family."""

    grouped: Dict[InteractionFamily, List[VisualInteractionSpec]] = defaultdict(list)
    for index, value in enumerate(values):
        item = coerce_visual_interaction(value, index=index)
        grouped[item.family].append(item)
    return {family: tuple(items) for family, items in grouped.items()}


def build_visual_interactions(
    values: Any,
    *,
    config_value: Any = None,
    pose_id: Optional[str] = None,
    deduplicate: bool = True,
    sort: bool = False,
    limit: Optional[int] = None,
    name: Optional[str] = None,
) -> VisualInteractionCollection:
    """Build a normalized visual interaction collection."""

    config_obj = resolve_visualization_config(config_value)
    items = tuple(
        coerce_visual_interaction(value, index=index, config_value=config_obj, pose_id=pose_id)
        for index, value in enumerate(_iter_interaction_values(values))
    )
    if deduplicate:
        items = deduplicate_visual_interactions(items)
    if sort:
        items = sort_visual_interactions(items)
    maximum = config_obj.interactions.max_count if limit is None else _bounded_int(limit, field_name="limit", minimum=0, maximum=MAX_VISUAL_ELEMENTS)
    items = items[:maximum]
    return VisualInteractionCollection(
        interactions=items,
        name=name or config_obj.interactions.group_name,
        pose_id=pose_id,
    )


def summarize_visual_interactions(values: Any) -> Dict[str, Any]:
    """Return compact interaction counts and ranges."""

    collection = values if isinstance(values, VisualInteractionCollection) else build_visual_interactions(values)
    distances = [item.distance for item in collection.interactions if item.distance is not None]
    scores = [item.score for item in collection.interactions if item.score is not None]
    return {
        "total": len(collection.interactions),
        "visible": len(collection.visible),
        "families": dict(Counter(item.family.value for item in collection.interactions)),
        "strengths": dict(Counter(item.strength.value for item in collection.interactions)),
        "poses": dict(Counter(item.pose_id or "unassigned" for item in collection.interactions)),
        "distance_min": min(distances) if distances else None,
        "distance_max": max(distances) if distances else None,
        "score_min": min(scores) if scores else None,
        "score_max": max(scores) if scores else None,
        "involved_selection": collection.involved_selection.expression,
        "fingerprint": collection.fingerprint(),
    }


def interaction_visual_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize one visual interaction."""

    return coerce_visual_interaction(value).to_dict()


def interaction_visual_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize one visual interaction as JSON."""

    return json.dumps(interaction_visual_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


def interaction_visual_fingerprint(value: Any) -> str:
    """Return a stable visual interaction digest."""

    return coerce_visual_interaction(value).fingerprint()


