# =============================================================================
# Section 9 — Visualization plans
# =============================================================================

# 9.1. Helpers
# -----------------------------------------------------------------------------

_PLAN_ID_PATTERN: Final[re.Pattern[str]] = re.compile(r"^[A-Za-z][A-Za-z0-9_.:-]{0,127}$")
_PLAN_TAG_PATTERN: Final[re.Pattern[str]] = re.compile(r"^[A-Za-z0-9_.:-]{1,64}$")
_PLAN_MAX_ACTIONS: Final[int] = 10000


def _plan_text(
    value: Any,
    *,
    field_name: str,
    required: bool = False,
    maximum: int = 256,
) -> Optional[str]:
    """Normalize plan text."""

    if value is None:
        if required:
            raise VisualizationPlanError(f"{field_name} is required.")
        return None
    text = str(value).strip()
    if required and not text:
        raise VisualizationPlanError(f"{field_name} cannot be empty.")
    if len(text) > maximum:
        raise VisualizationPlanError(
            f"{field_name} exceeds {maximum} characters.",
            context={"field": field_name, "length": len(text)},
        )
    return text or None


def _plan_identifier(value: Any, *, field_name: str) -> str:
    """Normalize a plan identifier."""

    text = _plan_text(value, field_name=field_name, required=True, maximum=128)
    assert text is not None
    if not _PLAN_ID_PATTERN.fullmatch(text):
        raise VisualizationPlanError(
            f"Invalid {field_name}: {text!r}.",
            context={"field": field_name, "value": text},
        )
    return text


def _plan_tags(values: Any) -> Tuple[str, ...]:
    """Normalize unique plan tags."""

    if values is None:
        return ()
    if isinstance(values, str):
        values = (values,)
    tags: List[str] = []
    for value in values:
        tag = str(value).strip().lower()
        if not _PLAN_TAG_PATTERN.fullmatch(tag):
            raise VisualizationPlanError(f"Invalid plan tag: {value!r}.")
        if tag not in tags:
            tags.append(tag)
    return tuple(tags)


def _plan_mapping(value: Any, *, field_name: str) -> Mapping[str, Any]:
    """Freeze a shallow plan mapping."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise VisualizationPlanError(f"{field_name} must be a mapping.")
    return MappingProxyType({str(key): item for key, item in value.items()})


def _action_dependencies(values: Any) -> Tuple[str, ...]:
    """Normalize action dependencies."""

    if values is None:
        return ()
    if isinstance(values, str):
        values = (values,)
    normalized: List[str] = []
    for value in values:
        identifier = _plan_identifier(value, field_name="dependency")
        if identifier not in normalized:
            normalized.append(identifier)
    return tuple(normalized)


def _action_sort_key(
    action: "VisualizationAction",
    positions: Optional[Mapping[str, int]] = None,
) -> Tuple[int, int, int, str]:
    """Return a stable action sort key."""

    position = positions.get(action.action_id, 0) if positions else 0
    return (action.layer.priority, -int(action.priority), position, action.action_id)


def _generated_action_id(
    operation: Any,
    *,
    layer: Any = None,
    index: int = 0,
) -> str:
    """Build a deterministic action identifier."""

    operation_value = PlanOperation.parse(operation, default=PlanOperation.CUSTOM)
    layer_value = VisualLayer.parse(layer, default=_default_layer_for_operation(operation_value))
    return f"{layer_value.value}:{operation_value.value}:{int(index):04d}"


def _default_layer_for_operation(operation: Any) -> VisualLayer:
    """Return the default layer for an operation."""

    operation_value = PlanOperation.parse(operation, default=PlanOperation.CUSTOM)
    mapping = {
        PlanOperation.PREPARE_SCENE: VisualLayer.BACKGROUND,
        PlanOperation.SHOW_RECEPTOR: VisualLayer.RECEPTOR,
        PlanOperation.SHOW_LIGAND: VisualLayer.LIGAND,
        PlanOperation.SHOW_INTERACTIONS: VisualLayer.INTERACTIONS,
        PlanOperation.SHOW_MARKERS: VisualLayer.MARKERS,
        PlanOperation.SHOW_RESIDUES: VisualLayer.RECEPTOR_FOCUS,
        PlanOperation.SHOW_HOTSPOTS: VisualLayer.HOTSPOTS,
        PlanOperation.APPLY_SCORING: VisualLayer.RECEPTOR_FOCUS,
        PlanOperation.SHOW_MULTIPOSE: VisualLayer.LIGAND,
        PlanOperation.SHOW_LABELS: VisualLayer.LABELS,
        PlanOperation.SET_CAMERA: VisualLayer.CAMERA,
        PlanOperation.SAVE_SNAPSHOT: VisualLayer.SNAPSHOT,
        PlanOperation.EXPORT_COMMANDS: VisualLayer.SNAPSHOT,
    }
    return mapping.get(operation_value, VisualLayer.INTERACTIONS)


# 9.2. Plan models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PlanValidationIssue(MolecularSpecMixin):
    """One plan validation issue."""

    level: ValidationIssueLevel
    code: str
    message: str
    action_id: Optional[str] = None
    context: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "level", ValidationIssueLevel.parse(self.level, default=ValidationIssueLevel.ERROR))
        object.__setattr__(self, "code", _plan_identifier(self.code, field_name="issue code"))
        object.__setattr__(self, "message", _plan_text(self.message, field_name="message", required=True, maximum=2048))
        object.__setattr__(self, "action_id", None if self.action_id is None else _plan_identifier(self.action_id, field_name="action_id"))
        object.__setattr__(self, "context", _plan_mapping(self.context, field_name="context"))


@dataclass(frozen=True, slots=True)
class VisualizationAction(MolecularSpecMixin):
    """Backend-neutral visualization operation."""

    action_id: str
    operation: PlanOperation
    layer: VisualLayer
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    parameters: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)
    depends_on: Tuple[str, ...] = ()
    priority: OperationPriority = OperationPriority.NORMAL
    enabled: bool = True
    optional: bool = False
    description: Optional[str] = None
    tags: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        action_id = _plan_identifier(self.action_id, field_name="action_id")
        operation = PlanOperation.parse(self.operation, default=PlanOperation.CUSTOM)
        layer = VisualLayer.parse(self.layer, default=_default_layer_for_operation(operation))
        dependencies = _action_dependencies(self.depends_on)
        if action_id in dependencies:
            raise VisualizationPlanError(
                "An action cannot depend on itself.",
                context={"action_id": action_id},
            )
        object.__setattr__(self, "action_id", action_id)
        object.__setattr__(self, "operation", operation)
        object.__setattr__(self, "layer", layer)
        object.__setattr__(self, "selection", coerce_selection(self.selection))
        object.__setattr__(self, "parameters", _plan_mapping(self.parameters, field_name="parameters"))
        object.__setattr__(self, "depends_on", dependencies)
        object.__setattr__(self, "priority", OperationPriority.parse(self.priority, default=OperationPriority.NORMAL))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "description", _plan_text(self.description, field_name="description", maximum=2048))
        object.__setattr__(self, "tags", _plan_tags(self.tags))
        object.__setattr__(self, "metadata", _plan_mapping(self.metadata, field_name="metadata"))

    @property
    def executable(self) -> bool:
        return self.enabled and self.operation is not PlanOperation.CUSTOM

    def with_dependency(self, *action_ids: str) -> "VisualizationAction":
        return replace(self, depends_on=_action_dependencies((*self.depends_on, *action_ids)))

    def without_dependency(self, *action_ids: str) -> "VisualizationAction":
        removed = set(_action_dependencies(action_ids))
        return replace(self, depends_on=tuple(item for item in self.depends_on if item not in removed))


@dataclass(frozen=True, slots=True)
class VisualizationPlan(MolecularSpecMixin):
    """Ordered backend-neutral visualization plan."""

    plan_id: str
    name: str
    actions: Tuple[VisualizationAction, ...] = ()
    profile: VisualizationProfile = VisualizationProfile.ANALYSIS
    state: LifecycleState = LifecycleState.PLANNED
    execution_mode: ExecutionMode = ExecutionMode.DEFERRED
    description: Optional[str] = None
    created_at: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        actions = tuple(coerce_visualization_action(value, index=index) for index, value in enumerate(self.actions))
        if len(actions) > _PLAN_MAX_ACTIONS:
            raise VisualizationLimitError(
                f"A plan cannot exceed {_PLAN_MAX_ACTIONS} actions.",
                context={"action_count": len(actions)},
            )
        identifiers = [action.action_id for action in actions]
        duplicates = sorted(identifier for identifier, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationPlanError(
                "Plan action identifiers must be unique.",
                context={"duplicates": duplicates},
            )
        created_at = self.created_at
        if created_at is None:
            created_at = datetime.now(timezone.utc).isoformat()
        else:
            created_at = _plan_text(created_at, field_name="created_at", required=True, maximum=128)
        object.__setattr__(self, "plan_id", _plan_identifier(self.plan_id, field_name="plan_id"))
        object.__setattr__(self, "name", _plan_text(self.name, field_name="name", required=True, maximum=256))
        object.__setattr__(self, "actions", actions)
        object.__setattr__(self, "profile", VisualizationProfile.parse(self.profile, default=VisualizationProfile.ANALYSIS))
        object.__setattr__(self, "state", LifecycleState.parse(self.state, default=LifecycleState.PLANNED))
        object.__setattr__(self, "execution_mode", ExecutionMode.parse(self.execution_mode, default=ExecutionMode.DEFERRED))
        object.__setattr__(self, "description", _plan_text(self.description, field_name="description", maximum=2048))
        object.__setattr__(self, "created_at", created_at)
        object.__setattr__(self, "metadata", _plan_mapping(self.metadata, field_name="metadata"))

    @property
    def action_map(self) -> Mapping[str, VisualizationAction]:
        return MappingProxyType({action.action_id: action for action in self.actions})

    @property
    def active_actions(self) -> Tuple[VisualizationAction, ...]:
        return tuple(action for action in self.actions if action.enabled)

    @property
    def layers(self) -> Tuple[VisualLayer, ...]:
        return tuple(dict.fromkeys(action.layer for action in self.actions))

    @property
    def operations(self) -> Tuple[PlanOperation, ...]:
        return tuple(dict.fromkeys(action.operation for action in self.actions))

    def get(self, action_id: str) -> VisualizationAction:
        identifier = _plan_identifier(action_id, field_name="action_id")
        try:
            return self.action_map[identifier]
        except KeyError as exc:
            raise VisualizationPlanError(
                f"Unknown plan action: {identifier!r}.",
                context={"plan_id": self.plan_id, "action_id": identifier},
            ) from exc

    def ordered(self, *, enabled_only: bool = False) -> Tuple[VisualizationAction, ...]:
        return resolve_plan_order(self, enabled_only=enabled_only)

    def validate(self, *, raise_on_error: bool = False) -> Tuple[PlanValidationIssue, ...]:
        return validate_visualization_plan(self, raise_on_error=raise_on_error)

    def with_actions(self, actions: Iterable[Any]) -> "VisualizationPlan":
        return replace(self, actions=tuple(actions))


# 9.3. Coercion and construction
# -----------------------------------------------------------------------------

def coerce_visualization_action(
    value: Any,
    *,
    index: int = 0,
    default_operation: Any = PlanOperation.CUSTOM,
) -> VisualizationAction:
    """Coerce one plan action."""

    if isinstance(value, VisualizationAction):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
    else:
        data = {
            name: getattr(value, name)
            for name in (
                "action_id", "operation", "layer", "selection", "parameters",
                "depends_on", "priority", "enabled", "optional", "description",
                "tags", "metadata",
            )
            if hasattr(value, name)
        }
    operation = data.get("operation", default_operation)
    layer = data.get("layer", _default_layer_for_operation(operation))
    data.setdefault("action_id", _generated_action_id(operation, layer=layer, index=index))
    data.setdefault("operation", operation)
    data.setdefault("layer", layer)
    data.setdefault("selection", MolecularSelection.none())
    return VisualizationAction(**data)


def build_visualization_action(
    operation: Any,
    *,
    action_id: Optional[str] = None,
    layer: Any = None,
    selection: Any = None,
    parameters: Optional[Mapping[str, Any]] = None,
    depends_on: Iterable[str] = (),
    priority: Any = OperationPriority.NORMAL,
    enabled: bool = True,
    optional: bool = False,
    description: Optional[str] = None,
    tags: Iterable[str] = (),
    metadata: Optional[Mapping[str, Any]] = None,
    index: int = 0,
) -> VisualizationAction:
    """Build one normalized action."""

    operation_value = PlanOperation.parse(operation, default=PlanOperation.CUSTOM)
    layer_value = VisualLayer.parse(layer, default=_default_layer_for_operation(operation_value))
    return VisualizationAction(
        action_id=action_id or _generated_action_id(operation_value, layer=layer_value, index=index),
        operation=operation_value,
        layer=layer_value,
        selection=MolecularSelection.none() if selection is None else coerce_selection(selection),
        parameters=parameters or {},
        depends_on=tuple(depends_on),
        priority=priority,
        enabled=enabled,
        optional=optional,
        description=description,
        tags=tuple(tags),
        metadata=metadata or {},
    )


def coerce_visualization_plan(value: Any, *, name: str = "Visualization plan") -> VisualizationPlan:
    """Coerce a visualization plan."""

    if isinstance(value, VisualizationPlan):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("plan_id", "visualization-plan")
        data.setdefault("name", name)
        return VisualizationPlan(**data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return build_visualization_plan(value, name=name)
    if hasattr(value, "actions"):
        return VisualizationPlan(
            plan_id=getattr(value, "plan_id", "visualization-plan"),
            name=getattr(value, "name", name),
            actions=tuple(getattr(value, "actions")),
            profile=getattr(value, "profile", VisualizationProfile.ANALYSIS),
            state=getattr(value, "state", LifecycleState.PLANNED),
            execution_mode=getattr(value, "execution_mode", ExecutionMode.DEFERRED),
            description=getattr(value, "description", None),
            metadata=getattr(value, "metadata", {}),
        )
    raise VisualizationPlanError(
        f"Cannot coerce {type(value).__name__} to VisualizationPlan."
    )


def build_visualization_plan(
    actions: Iterable[Any] = (),
    *,
    plan_id: str = "visualization-plan",
    name: str = "Visualization plan",
    profile: Any = VisualizationProfile.ANALYSIS,
    execution_mode: Any = ExecutionMode.DEFERRED,
    description: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    validate: bool = True,
    order: bool = True,
) -> VisualizationPlan:
    """Build and optionally order a plan."""

    plan = VisualizationPlan(
        plan_id=plan_id,
        name=name,
        actions=tuple(coerce_visualization_action(value, index=index) for index, value in enumerate(actions)),
        profile=profile,
        execution_mode=execution_mode,
        description=description,
        metadata=metadata or {},
    )
    if validate:
        validate_visualization_plan(plan, raise_on_error=True)
    if order:
        plan = replace(plan, actions=resolve_plan_order(plan))
    return plan


class VisualizationPlanBuilder:
    """Mutable helper for incremental plan construction."""

    def __init__(
        self,
        *,
        plan_id: str = "visualization-plan",
        name: str = "Visualization plan",
        profile: Any = VisualizationProfile.ANALYSIS,
        execution_mode: Any = ExecutionMode.DEFERRED,
        description: Optional[str] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.plan_id = _plan_identifier(plan_id, field_name="plan_id")
        self.name = _plan_text(name, field_name="name", required=True, maximum=256) or name
        self.profile = VisualizationProfile.parse(profile, default=VisualizationProfile.ANALYSIS)
        self.execution_mode = ExecutionMode.parse(execution_mode, default=ExecutionMode.DEFERRED)
        self.description = description
        self.metadata = dict(metadata or {})
        self._actions: List[VisualizationAction] = []

    @property
    def actions(self) -> Tuple[VisualizationAction, ...]:
        return tuple(self._actions)

    def add(self, action: Any = None, /, **kwargs: Any) -> VisualizationAction:
        if action is None:
            if "operation" not in kwargs:
                raise VisualizationPlanError("operation is required when action is omitted.")
            operation = kwargs.pop("operation")
            action_value = build_visualization_action(operation, index=len(self._actions), **kwargs)
        elif kwargs:
            action_value = replace(coerce_visualization_action(action, index=len(self._actions)), **kwargs)
        else:
            action_value = coerce_visualization_action(action, index=len(self._actions))
        if any(item.action_id == action_value.action_id for item in self._actions):
            raise VisualizationPlanError(f"Duplicate action identifier: {action_value.action_id!r}.")
        self._actions.append(action_value)
        return action_value

    def extend(self, actions: Iterable[Any]) -> "VisualizationPlanBuilder":
        for action in actions:
            self.add(action)
        return self

    def depend(self, action_id: str, *dependencies: str) -> "VisualizationPlanBuilder":
        identifier = _plan_identifier(action_id, field_name="action_id")
        for index, action in enumerate(self._actions):
            if action.action_id == identifier:
                self._actions[index] = action.with_dependency(*dependencies)
                return self
        raise VisualizationPlanError(f"Unknown action: {identifier!r}.")

    def build(self, *, validate: bool = True, order: bool = True) -> VisualizationPlan:
        return build_visualization_plan(
            self._actions,
            plan_id=self.plan_id,
            name=self.name,
            profile=self.profile,
            execution_mode=self.execution_mode,
            description=self.description,
            metadata=self.metadata,
            validate=validate,
            order=order,
        )


# 9.4. Validation and ordering
# -----------------------------------------------------------------------------

def validate_visualization_action(action: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate one plan action."""

    value = coerce_visualization_action(action)
    issues: List[PlanValidationIssue] = []
    if value.enabled and value.operation is PlanOperation.CUSTOM and not value.parameters:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "custom_action_empty",
            "Enabled custom action has no parameters.",
            value.action_id,
        ))
    if value.operation is not PlanOperation.PREPARE_SCENE and value.selection.is_none:
        selection_optional = {
            PlanOperation.SET_CAMERA,
            PlanOperation.SAVE_SNAPSHOT,
            PlanOperation.EXPORT_COMMANDS,
            PlanOperation.SHOW_LABELS,
        }
        if value.operation not in selection_optional:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.INFO,
                "selection_empty",
                "Action has no explicit molecular selection.",
                value.action_id,
            ))
    return tuple(issues)


def validate_visualization_plan(
    plan: Any,
    *,
    raise_on_error: bool = False,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate identifiers, dependencies and cycles."""

    value = coerce_visualization_plan(plan)
    issues: List[PlanValidationIssue] = []
    action_map = value.action_map
    for action in value.actions:
        issues.extend(validate_visualization_action(action))
        for dependency in action.depends_on:
            if dependency not in action_map:
                issues.append(PlanValidationIssue(
                    ValidationIssueLevel.ERROR,
                    "dependency_missing",
                    f"Dependency {dependency!r} does not exist.",
                    action.action_id,
                    {"dependency": dependency},
                ))
            elif not action_map[dependency].enabled and action.enabled:
                issues.append(PlanValidationIssue(
                    ValidationIssueLevel.WARNING,
                    "dependency_disabled",
                    f"Dependency {dependency!r} is disabled.",
                    action.action_id,
                    {"dependency": dependency},
                ))
    try:
        resolve_plan_order(value)
    except VisualizationPlanError as exc:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "dependency_cycle",
            str(exc),
            context=exc.context,
        ))
    errors = [issue for issue in issues if issue.level >= ValidationIssueLevel.ERROR]
    if errors and raise_on_error:
        raise VisualizationPlanError(
            "Visualization plan validation failed.",
            context={"plan_id": value.plan_id, "issues": [issue.to_dict() for issue in errors]},
        )
    return tuple(issues)


def resolve_plan_order(
    plan: Any,
    *,
    enabled_only: bool = False,
) -> Tuple[VisualizationAction, ...]:
    """Topologically order plan actions."""

    value = coerce_visualization_plan(plan)
    actions = tuple(action for action in value.actions if action.enabled or not enabled_only)
    action_map = {action.action_id: action for action in actions}
    positions = {action.action_id: index for index, action in enumerate(actions)}
    incoming: Dict[str, Set[str]] = {
        action.action_id: {dependency for dependency in action.depends_on if dependency in action_map}
        for action in actions
    }
    outgoing: Dict[str, Set[str]] = {identifier: set() for identifier in action_map}
    for identifier, dependencies in incoming.items():
        for dependency in dependencies:
            outgoing[dependency].add(identifier)
    ready = sorted(
        (action_map[identifier] for identifier, dependencies in incoming.items() if not dependencies),
        key=lambda action: _action_sort_key(action, positions),
    )
    ordered: List[VisualizationAction] = []
    while ready:
        action = ready.pop(0)
        ordered.append(action)
        for dependent in sorted(outgoing[action.action_id]):
            incoming[dependent].discard(action.action_id)
            if not incoming[dependent] and action_map[dependent] not in ordered and action_map[dependent] not in ready:
                ready.append(action_map[dependent])
        ready.sort(key=lambda item: _action_sort_key(item, positions))
    if len(ordered) != len(actions):
        unresolved = sorted(identifier for identifier, dependencies in incoming.items() if dependencies)
        raise VisualizationPlanError(
            "Visualization plan contains a dependency cycle.",
            context={"plan_id": value.plan_id, "unresolved": unresolved},
        )
    return tuple(ordered)


# 9.5. Plan operations
# -----------------------------------------------------------------------------

def merge_visualization_plans(
    *plans: Any,
    plan_id: str = "merged-visualization-plan",
    name: str = "Merged visualization plan",
    replace_duplicates: bool = False,
    validate: bool = True,
) -> VisualizationPlan:
    """Merge plans while preserving dependencies."""

    normalized = tuple(coerce_visualization_plan(plan) for plan in plans)
    merged: Dict[str, VisualizationAction] = {}
    for plan in normalized:
        for action in plan.actions:
            if action.action_id in merged and not replace_duplicates:
                raise VisualizationPlanError(
                    f"Duplicate action identifier while merging: {action.action_id!r}."
                )
            merged[action.action_id] = action
    profile = normalized[0].profile if normalized else VisualizationProfile.ANALYSIS
    execution_mode = normalized[0].execution_mode if normalized else ExecutionMode.DEFERRED
    return build_visualization_plan(
        merged.values(),
        plan_id=plan_id,
        name=name,
        profile=profile,
        execution_mode=execution_mode,
        metadata={"source_plan_ids": [plan.plan_id for plan in normalized]},
        validate=validate,
    )


def filter_visualization_plan(
    plan: Any,
    *,
    operations: Optional[Iterable[Any]] = None,
    layers: Optional[Iterable[Any]] = None,
    tags: Optional[Iterable[str]] = None,
    enabled: Optional[bool] = None,
    include_dependencies: bool = True,
) -> VisualizationPlan:
    """Filter actions and optionally retain dependencies."""

    value = coerce_visualization_plan(plan)
    operation_set = None if operations is None else set(coerce_enum_sequence(PlanOperation, operations))
    layer_set = None if layers is None else set(coerce_enum_sequence(VisualLayer, layers))
    tag_set = None if tags is None else set(_plan_tags(tags))
    selected = {
        action.action_id
        for action in value.actions
        if (operation_set is None or action.operation in operation_set)
        and (layer_set is None or action.layer in layer_set)
        and (tag_set is None or bool(tag_set.intersection(action.tags)))
        and (enabled is None or action.enabled is enabled)
    }
    if include_dependencies:
        action_map = value.action_map
        pending = list(selected)
        while pending:
            identifier = pending.pop()
            for dependency in action_map[identifier].depends_on:
                if dependency in action_map and dependency not in selected:
                    selected.add(dependency)
                    pending.append(dependency)
    return replace(value, actions=tuple(action for action in value.actions if action.action_id in selected))


def build_standard_visualization_plan(
    selections: Any,
    interactions: Any = None,
    *,
    config_value: Any = None,
    plan_id: str = "dockanalyzer-visualization",
    name: str = "DockAnalyzer visualization",
) -> VisualizationPlan:
    """Build the standard receptor-ligand-interaction plan."""

    config_obj = resolve_visualization_config(config_value)
    bundle = selections if isinstance(selections, MolecularSelectionBundle) else build_molecular_selection_bundle(selections)
    interaction_collection = build_visual_interactions(interactions or (), config_value=config_obj)
    builder = VisualizationPlanBuilder(
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        metadata={
            "config_fingerprint": config_obj.fingerprint(),
            "interaction_fingerprint": interaction_collection.fingerprint(),
        },
    )
    scene = builder.add(operation=PlanOperation.PREPARE_SCENE, action_id="scene:prepare", layer=VisualLayer.BACKGROUND)
    if bundle.receptor:
        builder.add(
            operation=PlanOperation.SHOW_RECEPTOR,
            action_id="receptor:show",
            selection=bundle.receptor,
            depends_on=(scene.action_id,),
            tags=("receptor",),
        )
    if bundle.ligands:
        builder.add(
            operation=PlanOperation.SHOW_LIGAND,
            action_id="ligand:show",
            selection=bundle.ligands,
            depends_on=(scene.action_id,),
            tags=("ligand",),
        )
    if interaction_collection.interactions:
        dependencies = tuple(
            identifier for identifier in ("receptor:show", "ligand:show")
            if any(action.action_id == identifier for action in builder.actions)
        ) or (scene.action_id,)
        builder.add(
            operation=PlanOperation.SHOW_INTERACTIONS,
            action_id="interactions:show",
            selection=interaction_collection.involved_selection,
            depends_on=dependencies,
            parameters={
                "interaction_count": len(interaction_collection.interactions),
                "interaction_fingerprint": interaction_collection.fingerprint(),
            },
            tags=("interactions",),
        )
    return builder.build()


# 9.6. Serialization and summaries
# -----------------------------------------------------------------------------

def summarize_visualization_plan(plan: Any) -> Dict[str, Any]:
    """Return compact plan statistics."""

    value = coerce_visualization_plan(plan)
    issues = validate_visualization_plan(value)
    ordered = resolve_plan_order(value)
    return {
        "plan_id": value.plan_id,
        "name": value.name,
        "state": value.state.value,
        "execution_mode": value.execution_mode.value,
        "action_count": len(value.actions),
        "enabled_count": len(value.active_actions),
        "operations": dict(Counter(action.operation.value for action in value.actions)),
        "layers": dict(Counter(action.layer.value for action in value.actions)),
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "ordered_action_ids": [action.action_id for action in ordered],
        "fingerprint": value.fingerprint(),
    }


def visualization_plan_to_dict(plan: Any) -> Dict[str, Any]:
    """Serialize a visualization plan."""

    return coerce_visualization_plan(plan).to_dict()


def visualization_plan_to_json(plan: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize a visualization plan as JSON."""

    return json.dumps(visualization_plan_to_dict(plan), ensure_ascii=False, sort_keys=True, indent=indent)


def visualization_plan_fingerprint(plan: Any) -> str:
    """Return a stable plan digest."""

    return coerce_visualization_plan(plan).fingerprint()


