def _scene_step_name(value: Any) -> str:
    text = re.sub(r"[^a-z0-9_]+", "_", str(value).strip().lower()).strip("_")
    if not text:
        raise VisualizationSceneError("Scene preparation step cannot be empty.")
    return text


def _coerce_scene_selection_bundle(value: Any) -> MolecularSelectionBundle:
    if value is None:
        return MolecularSelectionBundle()
    if isinstance(value, MolecularSelectionBundle):
        return value
    if isinstance(value, MolecularSpecificationBundle):
        return build_molecular_selection_bundle(value)
    if isinstance(value, Mapping):
        data = dict(value)
        try:
            return MolecularSelectionBundle(**data)
        except (TypeError, VisualizationError):
            try:
                return build_molecular_selection_bundle(MolecularSpecificationBundle(**data))
            except Exception as exc:
                raise VisualizationSceneError(
                    "Cannot build scene selections from mapping.",
                    cause=exc,
                ) from exc
    return MolecularSelectionBundle(receptor=coerce_selection(value))


@dataclass(frozen=True, slots=True)
class ScenePreparationStep(MolecularSpecMixin):
    """One backend-neutral scene setup step."""

    step_id: str
    kind: str
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    parameters: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)
    depends_on: Tuple[str, ...] = ()
    priority: OperationPriority = OperationPriority.NORMAL
    enabled: bool = True
    optional: bool = False
    description: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "step_id", _plan_identifier(self.step_id, field_name="step_id"))
        object.__setattr__(self, "kind", _scene_step_name(self.kind))
        object.__setattr__(self, "selection", coerce_selection(self.selection))
        object.__setattr__(self, "parameters", _plan_mapping(self.parameters, field_name="parameters"))
        object.__setattr__(self, "depends_on", _action_dependencies(self.depends_on))
        object.__setattr__(self, "priority", OperationPriority.parse(self.priority, default=OperationPriority.NORMAL))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "description", _plan_text(self.description, field_name="description", maximum=1024))
        object.__setattr__(self, "metadata", _plan_mapping(self.metadata, field_name="metadata"))
        if self.step_id in self.depends_on:
            raise VisualizationSceneError(
                "A scene step cannot depend on itself.",
                context={"step_id": self.step_id},
            )

    def to_action(self, *, scene_name: Optional[str] = None) -> VisualizationAction:
        parameters = dict(self.parameters)
        parameters.setdefault("scene_step", self.kind)
        if scene_name:
            parameters.setdefault("scene_name", scene_name)
        return build_visualization_action(
            PlanOperation.PREPARE_SCENE,
            action_id=self.step_id,
            layer=VisualLayer.BACKGROUND,
            selection=self.selection,
            parameters=parameters,
            depends_on=self.depends_on,
            priority=self.priority,
            enabled=self.enabled,
            optional=self.optional,
            description=self.description,
            tags=("scene", "preparation", self.kind),
            metadata=self.metadata,
        )


@dataclass(frozen=True, slots=True)
class ScenePreparationSpec(MolecularSpecMixin):
    """Normalized scene setup configuration."""

    scene_name: str = DEFAULT_SCENE_NAME
    selections: MolecularSelectionBundle = field(default_factory=MolecularSelectionBundle)
    reset_mode: SceneResetMode = SceneResetMode.VISUALIZATION
    background: str = DEFAULT_BACKGROUND_COLOR
    foreground: str = DEFAULT_FOREGROUND_COLOR
    clear_selection: bool = DEFAULT_CLEAR_SELECTION
    hide_nonfocus_atoms: bool = DEFAULT_HIDE_NONFOCUS_ATOMS
    hide_solvent: bool = DEFAULT_HIDE_SOLVENT
    hide_ions: bool = DEFAULT_HIDE_IONS
    hide_hydrogens: bool = DEFAULT_HIDE_HYDROGENS
    focus_distance: float = DEFAULT_FOCUS_DISTANCE
    context_distance: float = DEFAULT_CONTEXT_DISTANCE
    lighting: str = DEFAULT_CHIMERAX_LIGHTING
    silhouettes: bool = DEFAULT_CHIMERAX_SILHOUETTES
    preserve_models: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "scene_name", _clean_config_name(self.scene_name, field_name="scene_name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "selections", _coerce_scene_selection_bundle(self.selections))
        object.__setattr__(self, "reset_mode", SceneResetMode.parse(self.reset_mode, default=SceneResetMode.VISUALIZATION))
        object.__setattr__(self, "background", normalize_color(self.background, field_name="background"))
        object.__setattr__(self, "foreground", normalize_color(self.foreground, field_name="foreground"))
        for name in (
            "clear_selection", "hide_nonfocus_atoms", "hide_solvent", "hide_ions",
            "hide_hydrogens", "silhouettes", "preserve_models",
        ):
            object.__setattr__(self, name, _coerce_bool(getattr(self, name), field_name=name))
        object.__setattr__(self, "focus_distance", _bounded_float(self.focus_distance, field_name="focus_distance", minimum=0.0, maximum=MAX_RADIUS))
        object.__setattr__(self, "context_distance", _bounded_float(self.context_distance, field_name="context_distance", minimum=0.0, maximum=MAX_RADIUS))
        if self.context_distance < self.focus_distance:
            raise VisualizationSceneError("Context distance must be >= focus distance.")
        lighting = str(self.lighting).strip().lower()
        if not lighting:
            raise VisualizationSceneError("Lighting mode cannot be empty.")
        object.__setattr__(self, "lighting", lighting)
        object.__setattr__(self, "metadata", _plan_mapping(self.metadata, field_name="metadata"))

    @property
    def all_molecules(self) -> MolecularSelection:
        return self.selections.all_molecules

    @property
    def focus_selection(self) -> MolecularSelection:
        focus = selection_union(self.selections.ligands, self.selections.cofactors, self.selections.all_poses)
        return focus if focus else self.selections.receptor


# 10.2. Construction
# -----------------------------------------------------------------------------

def build_scene_preparation_spec(
    config_value: Any = None,
    molecular_input: Any = None,
    *,
    selections: Any = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> ScenePreparationSpec:
    """Build scene preparation from visual settings."""

    visual = resolve_visualization_config(config_value)
    selection_source = selections if selections is not None else molecular_input
    selection_bundle = _coerce_scene_selection_bundle(selection_source)
    scene = visual.scene
    data: Dict[str, Any] = {
        "scene_name": visual.scene_name,
        "selections": selection_bundle,
        "reset_mode": scene.reset_mode,
        "background": scene.background,
        "foreground": scene.foreground,
        "clear_selection": scene.clear_selection,
        "hide_nonfocus_atoms": scene.hide_nonfocus_atoms,
        "hide_solvent": scene.hide_solvent,
        "hide_ions": scene.hide_ions,
        "hide_hydrogens": scene.hide_hydrogens,
        "focus_distance": scene.focus_distance,
        "context_distance": scene.context_distance,
        "lighting": scene.lighting,
        "silhouettes": scene.silhouettes,
        "metadata": {
            "profile": visual.profile.value,
            "config_fingerprint": visual.fingerprint(),
        },
    }
    if overrides:
        unknown = set(overrides) - {item.name for item in fields(ScenePreparationSpec)}
        if unknown:
            raise VisualizationSceneError(
                "Unknown scene preparation fields.",
                context={"unknown": sorted(unknown)},
            )
        data.update(dict(overrides))
    return ScenePreparationSpec(**data)


def coerce_scene_preparation_spec(
    value: Any = None,
    *,
    config_value: Any = None,
    molecular_input: Any = None,
) -> ScenePreparationSpec:
    """Coerce scene preparation input."""

    if isinstance(value, ScenePreparationSpec):
        return value
    if value is None:
        return build_scene_preparation_spec(config_value, molecular_input)
    if isinstance(value, Mapping):
        return ScenePreparationSpec(**dict(value))
    if isinstance(value, VisualizationConfig) or isinstance(value, (str, VisualizationProfile)):
        return build_scene_preparation_spec(value, molecular_input)
    raise VisualizationSceneError(
        f"Cannot coerce {type(value).__name__} to ScenePreparationSpec."
    )


def _scene_step(
    kind: str,
    *,
    selection: Any = None,
    parameters: Optional[Mapping[str, Any]] = None,
    dependency: Optional[str] = None,
    priority: Any = OperationPriority.NORMAL,
    optional: bool = False,
    final: bool = False,
) -> ScenePreparationStep:
    identifier = "scene:prepare" if final else f"scene:{kind}"
    return ScenePreparationStep(
        step_id=identifier,
        kind=kind,
        selection=MolecularSelection.none() if selection is None else selection,
        parameters=parameters or {},
        depends_on=() if dependency is None else (dependency,),
        priority=priority,
        optional=optional,
    )


def build_scene_preparation_steps(value: Any) -> Tuple[ScenePreparationStep, ...]:
    """Create ordered scene setup steps."""

    spec = coerce_scene_preparation_spec(value)
    steps: List[ScenePreparationStep] = []
    previous: Optional[str] = None

    def add(kind: str, **kwargs: Any) -> None:
        nonlocal previous
        step = _scene_step(kind, dependency=previous, **kwargs)
        steps.append(step)
        previous = step.step_id

    if spec.reset_mode is not SceneResetMode.NONE:
        add(
            _SCENE_STEP_RESET,
            parameters={"mode": spec.reset_mode.value, "preserve_models": spec.preserve_models},
            priority=OperationPriority.CRITICAL,
        )
    add(
        _SCENE_STEP_BACKGROUND,
        parameters={"background": spec.background, "foreground": spec.foreground},
        priority=OperationPriority.HIGH,
    )
    add(_SCENE_STEP_LIGHTING, parameters={"mode": spec.lighting}, priority=OperationPriority.HIGH)
    add(_SCENE_STEP_SILHOUETTES, parameters={"enabled": spec.silhouettes})
    if spec.clear_selection:
        add(_SCENE_STEP_CLEAR_SELECTION, parameters={"clear": True})
    if spec.hide_solvent and spec.selections.solvent:
        add(_SCENE_STEP_HIDE_SOLVENT, selection=spec.selections.solvent, parameters={"hide": True})
    if spec.hide_ions and spec.selections.ions:
        add(_SCENE_STEP_HIDE_IONS, selection=spec.selections.ions, parameters={"hide": True})
    if spec.hide_hydrogens:
        target = spec.all_molecules if spec.all_molecules else MolecularSelection.all()
        add(_SCENE_STEP_HIDE_HYDROGENS, selection=target, parameters={"element": "H", "hide": True})
    if spec.hide_nonfocus_atoms and spec.all_molecules and spec.focus_selection:
        add(
            _SCENE_STEP_HIDE_NONFOCUS,
            selection=spec.all_molecules,
            parameters={
                "focus_selection": spec.focus_selection.expression,
                "focus_distance": spec.focus_distance,
                "context_distance": spec.context_distance,
                "hide": True,
            },
            optional=True,
        )
    steps.append(_scene_step(
        _SCENE_STEP_FINALIZE,
        parameters={"scene_name": spec.scene_name, "ready": True},
        dependency=previous,
        priority=OperationPriority.HIGH,
        final=True,
    ))
    return tuple(steps)


# 10.3. Plans
# -----------------------------------------------------------------------------

def scene_preparation_steps_to_actions(
    steps: Iterable[Any],
    *,
    scene_name: Optional[str] = None,
) -> Tuple[VisualizationAction, ...]:
    """Convert preparation steps to plan actions."""

    normalized = tuple(
        step if isinstance(step, ScenePreparationStep) else ScenePreparationStep(**dict(step))
        for step in steps
    )
    identifiers = [step.step_id for step in normalized]
    duplicates = sorted(name for name, count in Counter(identifiers).items() if count > 1)
    if duplicates:
        raise VisualizationSceneError(
            "Scene preparation step identifiers must be unique.",
            context={"duplicates": duplicates},
        )
    return tuple(step.to_action(scene_name=scene_name) for step in normalized)


def build_scene_preparation_plan(
    value: Any = None,
    *,
    config_value: Any = None,
    molecular_input: Any = None,
    plan_id: str = "scene-preparation",
    name: str = "Scene preparation",
    execution_mode: Any = ExecutionMode.DEFERRED,
) -> VisualizationPlan:
    """Build a standalone scene preparation plan."""

    spec = coerce_scene_preparation_spec(
        value,
        config_value=config_value,
        molecular_input=molecular_input,
    )
    actions = scene_preparation_steps_to_actions(
        build_scene_preparation_steps(spec),
        scene_name=spec.scene_name,
    )
    return build_visualization_plan(
        actions,
        plan_id=plan_id,
        name=name,
        profile=spec.metadata.get("profile", VisualizationProfile.ANALYSIS),
        execution_mode=execution_mode,
        metadata={
            "scene_name": spec.scene_name,
            "preparation_fingerprint": spec.fingerprint(),
        },
    )


def attach_scene_preparation(
    plan: Any,
    preparation: Any = None,
    *,
    config_value: Any = None,
    molecular_input: Any = None,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach scene setup before a visualization plan."""

    base = coerce_visualization_plan(plan)
    if not replace_existing and any(
        action.operation is PlanOperation.PREPARE_SCENE for action in base.actions
    ):
        raise VisualizationSceneError(
            "Plan already contains scene preparation.",
            hint="Use replace_existing=True to replace it.",
        )
    prep = build_scene_preparation_plan(
        preparation,
        config_value=config_value,
        molecular_input=molecular_input,
        plan_id=f"{base.plan_id}-scene",
    )
    retained = tuple(
        action for action in base.actions
        if not (replace_existing and action.operation is PlanOperation.PREPARE_SCENE)
    )
    prep_ids = {action.action_id for action in prep.actions}
    adjusted: List[VisualizationAction] = []
    for action in retained:
        dependencies = tuple(
            dependency for dependency in action.depends_on
            if dependency not in {"scene:prepare"} or "scene:prepare" in prep_ids
        )
        if action.operation is not PlanOperation.PREPARE_SCENE and not dependencies:
            dependencies = ("scene:prepare",)
        adjusted.append(replace(action, depends_on=dependencies))
    return build_visualization_plan(
        (*prep.actions, *adjusted),
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "scene_preparation": prep.metadata},
    )


def prepare_visualization_scene(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    plan: Any = None,
) -> VisualizationPlan:
    """Create or attach scene preparation."""

    if plan is None:
        return build_scene_preparation_plan(
            config_value=config_value,
            molecular_input=molecular_input,
        )
    return attach_scene_preparation(
        plan,
        config_value=config_value,
        molecular_input=molecular_input,
    )


# 10.4. Validation and summaries
# -----------------------------------------------------------------------------

def validate_scene_preparation(value: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate scene setup semantics."""

    spec = coerce_scene_preparation_spec(value)
    issues: List[PlanValidationIssue] = []
    if spec.hide_nonfocus_atoms and not spec.focus_selection:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "scene_focus_missing",
            "Nonfocus hiding is enabled without a focus selection.",
        ))
    if spec.hide_solvent and not spec.selections.solvent:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "scene_solvent_missing",
            "Solvent hiding is enabled without a solvent selection.",
        ))
    if spec.hide_ions and not spec.selections.ions:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "scene_ions_missing",
            "Ion hiding is enabled without an ion selection.",
        ))
    if spec.reset_mode is SceneResetMode.FULL and spec.preserve_models:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "scene_full_reset_preserve_models",
            "Full reset and model preservation may conflict in some backends.",
        ))
    return tuple(issues)


def summarize_scene_preparation(value: Any) -> Dict[str, Any]:
    """Return compact scene setup statistics."""

    spec = coerce_scene_preparation_spec(value)
    steps = build_scene_preparation_steps(spec)
    issues = validate_scene_preparation(spec)
    return {
        "scene_name": spec.scene_name,
        "reset_mode": spec.reset_mode.value,
        "step_count": len(steps),
        "steps": [step.kind for step in steps],
        "molecular_selection": spec.all_molecules.expression,
        "focus_selection": spec.focus_selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def scene_preparation_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize scene preparation."""

    return coerce_scene_preparation_spec(value).to_dict()


def scene_preparation_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize scene preparation as JSON."""

    return json.dumps(scene_preparation_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


# 10.5. Public API
# -----------------------------------------------------------------------------

_SECTION_10_PUBLIC_NAMES: Final[Tuple[str, ...]] = (
    "ScenePreparationStep",
    "ScenePreparationSpec",
    "build_scene_preparation_spec",
    "coerce_scene_preparation_spec",
    "build_scene_preparation_steps",
    "scene_preparation_steps_to_actions",
    "build_scene_preparation_plan",
    "attach_scene_preparation",
    "prepare_visualization_scene",
    "validate_scene_preparation",
    "summarize_scene_preparation",
    "scene_preparation_to_dict",
    "scene_preparation_to_json",
)
_register_public_names(_SECTION_10_PUBLIC_NAMES)

