# =============================================================================
# Section 11 — Receptor visualization
# =============================================================================

# 11.1. Models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ReceptorVisualizationSpec(MolecularSpecMixin):
    """Backend-neutral receptor display specification."""

    receptor: MolecularSelection
    style: MolecularStyleConfig
    focus_selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    focus_source: MolecularSelection = field(default_factory=MolecularSelection.none)
    context_selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    context_source: MolecularSelection = field(default_factory=MolecularSelection.none)
    focus_representation: MolecularRepresentation = MolecularRepresentation.STICKS
    context_representation: MolecularRepresentation = MolecularRepresentation.CARTOON
    focus_color: str = DEFAULT_HIGHLIGHT_COLOR
    context_color: Optional[str] = None
    surface_overlay: bool = False
    surface_color: str = DEFAULT_RECEPTOR_SURFACE_COLOR
    surface_opacity: float = DEFAULT_SURFACE_OPACITY
    focus_distance: float = DEFAULT_FOCUS_DISTANCE
    context_distance: float = DEFAULT_CONTEXT_DISTANCE
    show_focus: bool = True
    show_context: bool = False
    show_sidechains: bool = True
    enabled: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        style = self.style
        if isinstance(style, Mapping):
            style = MolecularStyleConfig(**dict(style))
        if not isinstance(style, MolecularStyleConfig):
            raise VisualizationConfigurationError("Receptor style must be MolecularStyleConfig or a mapping.")
        if style.role is not MolecularRole.RECEPTOR:
            style = replace(style, role=MolecularRole.RECEPTOR)
        focus_distance = _bounded_float(
            self.focus_distance,
            field_name="focus_distance",
            minimum=0.0,
            maximum=MAX_RADIUS,
        )
        context_distance = _bounded_float(
            self.context_distance,
            field_name="context_distance",
            minimum=0.0,
            maximum=MAX_RADIUS,
        )
        if context_distance < focus_distance:
            raise VisualizationConfigurationError("Receptor context distance must be >= focus distance.")
        context_color = None
        if self.context_color is not None:
            context_color = normalize_color(self.context_color, field_name="context_color")
        object.__setattr__(self, "receptor", coerce_selection(self.receptor))
        object.__setattr__(self, "style", style)
        object.__setattr__(self, "focus_selection", coerce_selection(self.focus_selection))
        object.__setattr__(self, "focus_source", coerce_selection(self.focus_source))
        object.__setattr__(self, "context_selection", coerce_selection(self.context_selection))
        object.__setattr__(self, "context_source", coerce_selection(self.context_source))
        object.__setattr__(self, "focus_representation", MolecularRepresentation.parse(self.focus_representation))
        object.__setattr__(self, "context_representation", MolecularRepresentation.parse(self.context_representation))
        object.__setattr__(self, "focus_color", normalize_color(self.focus_color, field_name="focus_color"))
        object.__setattr__(self, "context_color", context_color)
        object.__setattr__(self, "surface_overlay", bool(self.surface_overlay))
        object.__setattr__(self, "surface_color", normalize_color(self.surface_color, field_name="surface_color"))
        object.__setattr__(self, "surface_opacity", _bounded_float(
            self.surface_opacity,
            field_name="surface_opacity",
            minimum=0.0,
            maximum=1.0,
        ))
        object.__setattr__(self, "focus_distance", focus_distance)
        object.__setattr__(self, "context_distance", context_distance)
        object.__setattr__(self, "show_focus", bool(self.show_focus))
        object.__setattr__(self, "show_context", bool(self.show_context))
        object.__setattr__(self, "show_sidechains", bool(self.show_sidechains))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def effective_focus(self) -> MolecularSelection:
        """Return an explicit focus selection when available."""

        if self.focus_selection:
            return selection_intersection(self.receptor, self.focus_selection)
        return self.receptor

    @property
    def effective_context(self) -> MolecularSelection:
        """Return an explicit context selection when available."""

        if self.context_selection:
            return selection_intersection(self.receptor, self.context_selection)
        return self.receptor

    @property
    def has_focus_rule(self) -> bool:
        return bool(self.focus_selection or self.focus_source)

    @property
    def has_context_rule(self) -> bool:
        return bool(self.context_selection or self.context_source)


# 11.2. Input resolution
# -----------------------------------------------------------------------------

def _receptor_selection_bundle(value: Any) -> Optional[MolecularSelectionBundle]:
    """Resolve role selections when possible."""

    if value is None:
        return None
    if isinstance(value, MolecularSelectionBundle):
        return value
    if isinstance(value, MolecularSpecificationBundle):
        return build_molecular_selection_bundle(value, include_named=False)
    if isinstance(value, Mapping):
        data = dict(value)
        if any(key in data for key in ("ligands", "cofactors", "solvent", "ions", "poses", "structure")):
            try:
                return build_molecular_selection_bundle(data, include_named=False)
            except VisualizationError:
                pass
        if "receptor" in data:
            poses = {
                str(key): coerce_selection(item)
                for key, item in dict(data.get("poses", {})).items()
            }
            return MolecularSelectionBundle(
                receptor=coerce_selection(data.get("receptor")),
                ligands=coerce_selection(data.get("ligands")),
                cofactors=coerce_selection(data.get("cofactors")),
                solvent=coerce_selection(data.get("solvent")),
                ions=coerce_selection(data.get("ions")),
                poses=poses,
                metadata={"source": "mapping"},
            )
    return None


def _receptor_selection(value: Any) -> MolecularSelection:
    """Resolve a receptor selection from common inputs."""

    if value is None:
        return MolecularSelection.none()
    bundle = _receptor_selection_bundle(value)
    if bundle is not None:
        return bundle.receptor
    if isinstance(value, MolecularObjectSpec):
        return molecular_object_to_selection(value)
    return coerce_selection(value)


def _receptor_focus_source(value: Any) -> MolecularSelection:
    """Resolve the default receptor-zone source."""

    bundle = _receptor_selection_bundle(value)
    if bundle is None:
        return MolecularSelection.none()
    return selection_union(bundle.ligands, bundle.all_poses, bundle.cofactors)


def build_receptor_visualization_spec(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    receptor: Any = None,
    focus_selection: Any = None,
    focus_source: Any = None,
    context_selection: Any = None,
    context_source: Any = None,
    representation: Any = None,
    focus_representation: Any = None,
    context_representation: Any = None,
    color: Any = None,
    focus_color: Any = None,
    context_color: Any = None,
    opacity: Optional[float] = None,
    surface_overlay: Optional[bool] = None,
    surface_color: Any = None,
    surface_opacity: Optional[float] = None,
    focus_distance: Optional[float] = None,
    context_distance: Optional[float] = None,
    show_focus: Optional[bool] = None,
    show_context: bool = False,
    show_sidechains: bool = True,
    enabled: Optional[bool] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> ReceptorVisualizationSpec:
    """Build a receptor display specification."""

    config_obj = resolve_visualization_config(config_value)
    style = config_obj.style_for(MolecularRole.RECEPTOR)
    changes: Dict[str, Any] = {}
    if representation is not None:
        changes["representation"] = MolecularRepresentation.parse(representation)
    if color is not None:
        changes["color"] = normalize_color(color, field_name="color")
    if opacity is not None:
        changes["opacity"] = opacity
    if changes:
        style = replace(style, **changes)
    receptor_selection = _receptor_selection(receptor if receptor is not None else molecular_input)
    default_source = _receptor_focus_source(molecular_input)
    source = default_source if focus_source is None else coerce_selection(focus_source)
    context_source_value = source if context_source is None else coerce_selection(context_source)
    focus_enabled = config_obj.scene.show_residues if show_focus is None else bool(show_focus)
    receptor_enabled = config_obj.scene.show_receptor and style.visible if enabled is None else bool(enabled)
    overlay = False if surface_overlay is None else bool(surface_overlay)
    return ReceptorVisualizationSpec(
        receptor=receptor_selection,
        style=style,
        focus_selection=coerce_selection(focus_selection),
        focus_source=source,
        context_selection=coerce_selection(context_selection),
        context_source=context_source_value,
        focus_representation=(
            MolecularRepresentation.STICKS
            if focus_representation is None
            else MolecularRepresentation.parse(focus_representation)
        ),
        context_representation=(
            MolecularRepresentation.CARTOON
            if context_representation is None
            else MolecularRepresentation.parse(context_representation)
        ),
        focus_color=config_obj.palette.highlight if focus_color is None else focus_color,
        context_color=context_color,
        surface_overlay=overlay,
        surface_color=DEFAULT_RECEPTOR_SURFACE_COLOR if surface_color is None else surface_color,
        surface_opacity=style.surface_opacity if surface_opacity is None else surface_opacity,
        focus_distance=config_obj.scene.focus_distance if focus_distance is None else focus_distance,
        context_distance=config_obj.scene.context_distance if context_distance is None else context_distance,
        show_focus=focus_enabled,
        show_context=show_context,
        show_sidechains=show_sidechains,
        enabled=receptor_enabled,
        metadata={
            "profile": config_obj.profile.value,
            "config_fingerprint": config_obj.fingerprint(),
            **dict(metadata or {}),
        },
    )


def coerce_receptor_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> ReceptorVisualizationSpec:
    """Coerce receptor display input."""

    if isinstance(value, ReceptorVisualizationSpec):
        return value
    if isinstance(value, Mapping) and "style" in value and "receptor" in value:
        return ReceptorVisualizationSpec(**dict(value))
    return build_receptor_visualization_spec(value, config_value=config_value)


# 11.3. Plan actions
# -----------------------------------------------------------------------------

def _receptor_style_parameters(style: MolecularStyleConfig) -> Dict[str, Any]:
    """Return backend-neutral receptor style parameters."""

    return {
        "representation": style.representation.value,
        "color": style.color,
        "color_mode": style.color_mode.value,
        "opacity": style.opacity,
        "stick_radius": style.stick_radius,
        "bond_radius": style.bond_radius,
        "ball_scale": style.ball_scale,
        "surface_opacity": style.surface_opacity,
        "show_hydrogens": style.show_hydrogens,
    }


def _receptor_zone_parameters(
    *,
    component: str,
    representation: MolecularRepresentation,
    color: Optional[str],
    source: MolecularSelection,
    distance: float,
    show_sidechains: bool,
) -> Dict[str, Any]:
    """Return focus or context parameters."""

    return {
        "component": component,
        "representation": representation.value,
        "color": color,
        "zone_source": source.expression if source else None,
        "zone_distance": distance,
        "zone_scope": "residue",
        "show_sidechains": show_sidechains,
    }


def build_receptor_visualization_actions(
    value: Any,
    *,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert receptor display data to plan actions."""

    spec = coerce_receptor_visualization_spec(value)
    dependencies = _action_dependencies(depends_on)
    actions: List[VisualizationAction] = [
        VisualizationAction(
            action_id="receptor:base",
            operation=PlanOperation.SHOW_RECEPTOR,
            layer=VisualLayer.RECEPTOR,
            selection=spec.receptor,
            parameters={"component": "base", **_receptor_style_parameters(spec.style)},
            depends_on=dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            description="Render the receptor base representation.",
            tags=("receptor", "base"),
            metadata=spec.metadata,
        )
    ]
    if spec.surface_overlay:
        actions.append(VisualizationAction(
            action_id="receptor:surface",
            operation=PlanOperation.SHOW_RECEPTOR,
            layer=VisualLayer.RECEPTOR,
            selection=spec.receptor,
            parameters={
                "component": "surface",
                "representation": MolecularRepresentation.SURFACE.value,
                "color": spec.surface_color,
                "opacity": spec.surface_opacity,
            },
            depends_on=("receptor:base",),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Render a receptor surface overlay.",
            tags=("receptor", "surface"),
        ))
    if spec.show_context:
        actions.append(VisualizationAction(
            action_id="receptor:context",
            operation=PlanOperation.SHOW_RECEPTOR,
            layer=VisualLayer.RECEPTOR_FOCUS,
            selection=spec.effective_context,
            parameters=_receptor_zone_parameters(
                component="context",
                representation=spec.context_representation,
                color=spec.context_color,
                source=spec.context_source,
                distance=spec.context_distance,
                show_sidechains=False,
            ),
            depends_on=("receptor:base",),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled and spec.has_context_rule,
            optional=True,
            description="Render receptor context around the focus source.",
            tags=("receptor", "context"),
        ))
    if spec.show_focus:
        focus_dependency = "receptor:context" if spec.show_context else "receptor:base"
        actions.append(VisualizationAction(
            action_id="receptor:focus",
            operation=PlanOperation.SHOW_RECEPTOR,
            layer=VisualLayer.RECEPTOR_FOCUS,
            selection=spec.effective_focus,
            parameters=_receptor_zone_parameters(
                component="focus",
                representation=spec.focus_representation,
                color=spec.focus_color,
                source=spec.focus_source,
                distance=spec.focus_distance,
                show_sidechains=spec.show_sidechains,
            ),
            depends_on=(focus_dependency,),
            priority=OperationPriority.HIGH,
            enabled=spec.enabled and spec.has_focus_rule,
            optional=True,
            description="Render receptor residues near the focus source.",
            tags=("receptor", "focus"),
        ))
    return tuple(actions)


def build_receptor_visualization_plan(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    spec: Any = None,
    plan_id: str = "receptor-visualization",
    name: str = "Receptor visualization",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Build a standalone receptor plan."""

    receptor_spec = (
        coerce_receptor_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_receptor_visualization_spec(
            molecular_input,
            config_value=config_value,
            **spec_overrides,
        )
    )
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_receptor_visualization_actions(receptor_spec),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display the receptor and its local binding context.",
        metadata={
            "receptor_spec": receptor_spec.to_dict(),
            **dict(metadata or {}),
        },
    )


def attach_receptor_visualization(
    plan: Any,
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    spec: Any = None,
    replace_existing: bool = True,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Attach receptor actions to an existing plan."""

    base = coerce_visualization_plan(plan)
    receptor_spec = (
        coerce_receptor_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_receptor_visualization_spec(
            molecular_input,
            config_value=config_value,
            **spec_overrides,
        )
    )
    dependency = ("scene:prepare",) if "scene:prepare" in base.action_map else ()
    incoming = {action.action_id: action for action in build_receptor_visualization_actions(
        receptor_spec,
        depends_on=dependency,
    )}
    actions: List[VisualizationAction] = []
    for action in base.actions:
        replacement = incoming.pop(action.action_id, None)
        if replacement is not None:
            if not replace_existing:
                raise VisualizationPlanError(f"Receptor action already exists: {action.action_id!r}.")
            actions.append(replacement)
        else:
            actions.append(action)
    actions.extend(incoming.values())
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "receptor_visualization": receptor_spec.to_dict()},
    )


def visualize_receptor(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach receptor visualization."""

    if plan is None:
        return build_receptor_visualization_plan(
            molecular_input,
            config_value=config_value,
            **kwargs,
        )
    return attach_receptor_visualization(
        plan,
        molecular_input,
        config_value=config_value,
        **kwargs,
    )


# 11.4. Validation and serialization
# -----------------------------------------------------------------------------

def validate_receptor_visualization(value: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate receptor display semantics."""

    spec = coerce_receptor_visualization_spec(value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and spec.receptor.is_none:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "receptor_selection_missing",
            "Receptor visualization requires a receptor selection.",
            "receptor:base",
        ))
    if spec.show_focus and not spec.has_focus_rule:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "receptor_focus_missing",
            "Receptor focus is enabled without a focus selection or source.",
            "receptor:focus",
        ))
    if spec.show_context and not spec.has_context_rule:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "receptor_context_missing",
            "Receptor context is enabled without a context selection or source.",
            "receptor:context",
        ))
    if spec.surface_overlay and spec.style.representation is MolecularRepresentation.SURFACE:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "receptor_surface_redundant",
            "The base representation and overlay are both surfaces.",
            "receptor:surface",
        ))
    if not spec.style.visible and spec.enabled:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "receptor_style_hidden",
            "The receptor is enabled but its molecular style is hidden.",
            "receptor:base",
        ))
    return tuple(issues)


def summarize_receptor_visualization(value: Any) -> Dict[str, Any]:
    """Return compact receptor display statistics."""

    spec = coerce_receptor_visualization_spec(value)
    actions = build_receptor_visualization_actions(spec)
    issues = validate_receptor_visualization(spec)
    return {
        "enabled": spec.enabled,
        "receptor_selection": spec.receptor.expression,
        "representation": spec.style.representation.value,
        "focus_enabled": spec.show_focus,
        "focus_rule": spec.has_focus_rule,
        "context_enabled": spec.show_context,
        "context_rule": spec.has_context_rule,
        "surface_overlay": spec.surface_overlay,
        "action_count": len(actions),
        "active_action_count": sum(action.enabled for action in actions),
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def receptor_visualization_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize receptor visualization."""

    return coerce_receptor_visualization_spec(value).to_dict()


def receptor_visualization_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize receptor visualization as JSON."""

    return json.dumps(
        receptor_visualization_to_dict(value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


