# =============================================================================
# Section 12 — Ligand visualization
# =============================================================================

# 12.1. Models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class LigandVisualizationSpec(MolecularSpecMixin):
    """Backend-neutral ligand display specification."""

    ligand: MolecularSelection
    style: MolecularStyleConfig
    poses: Mapping[str, MolecularSelection] = field(default_factory=dict, compare=False, hash=False)
    active_pose_id: Optional[str] = None
    cofactors: MolecularSelection = field(default_factory=MolecularSelection.none)
    cofactor_style: MolecularStyleConfig = field(
        default_factory=lambda: MolecularStyleConfig(
            MolecularRole.COFACTOR,
            MolecularRepresentation.parse(DEFAULT_COFACTOR_REPRESENTATION),
            DEFAULT_COFACTOR_COLOR,
        )
    )
    display_mode: PoseDisplayMode = PoseDisplayMode.ACTIVE
    color_mode: PoseColorMode = PoseColorMode.POSE
    pose_colors: Tuple[str, ...] = POSE_PALETTE
    active_opacity: float = DEFAULT_POSE_OPACITY
    inactive_opacity: float = DEFAULT_INACTIVE_POSE_OPACITY
    max_visible_poses: int = DEFAULT_MAX_VISIBLE_POSES
    group_name: str = DEFAULT_POSE_GROUP_NAME
    show_reference: bool = True
    show_cofactors: bool = True
    enabled: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        style = self.style
        if isinstance(style, Mapping):
            style = MolecularStyleConfig(**dict(style))
        if not isinstance(style, MolecularStyleConfig):
            raise VisualizationConfigurationError("Ligand style must be MolecularStyleConfig or a mapping.")
        if style.role is not MolecularRole.LIGAND:
            style = replace(style, role=MolecularRole.LIGAND)
        cofactor_style = self.cofactor_style
        if isinstance(cofactor_style, Mapping):
            cofactor_style = MolecularStyleConfig(**dict(cofactor_style))
        if not isinstance(cofactor_style, MolecularStyleConfig):
            raise VisualizationConfigurationError("Cofactor style must be MolecularStyleConfig or a mapping.")
        if cofactor_style.role is not MolecularRole.COFACTOR:
            cofactor_style = replace(cofactor_style, role=MolecularRole.COFACTOR)
        pose_map: Dict[str, MolecularSelection] = {}
        for raw_id, raw_selection in dict(self.poses).items():
            pose_id = _clean_spec_text(raw_id, field_name="pose_id", allow_none=False)
            if not pose_id:
                raise VisualizationSpecificationError("Pose identifiers cannot be empty.")
            if pose_id in pose_map:
                raise VisualizationSpecificationError("Pose identifiers must be unique.")
            pose_map[pose_id] = coerce_selection(raw_selection)
        active_pose_id = _clean_spec_text(self.active_pose_id, field_name="active_pose_id")
        if active_pose_id is None and pose_map:
            active_pose_id = next(iter(pose_map))
        if active_pose_id is not None and active_pose_id not in pose_map:
            raise VisualizationSpecificationError(
                "The active pose is not present in the pose map.",
                context={"active_pose_id": active_pose_id, "pose_ids": list(pose_map)},
            )
        colors = tuple(normalize_color(color, field_name="pose_colors") for color in self.pose_colors)
        if not colors:
            raise VisualizationConfigurationError("Pose colors cannot be empty.")
        object.__setattr__(self, "ligand", coerce_selection(self.ligand))
        object.__setattr__(self, "style", style)
        object.__setattr__(self, "poses", MappingProxyType(pose_map))
        object.__setattr__(self, "active_pose_id", active_pose_id)
        object.__setattr__(self, "cofactors", coerce_selection(self.cofactors))
        object.__setattr__(self, "cofactor_style", cofactor_style)
        object.__setattr__(self, "display_mode", PoseDisplayMode.parse(self.display_mode))
        object.__setattr__(self, "color_mode", PoseColorMode.parse(self.color_mode))
        object.__setattr__(self, "pose_colors", colors)
        object.__setattr__(self, "active_opacity", _bounded_float(
            self.active_opacity,
            field_name="active_opacity",
            minimum=0.0,
            maximum=1.0,
        ))
        object.__setattr__(self, "inactive_opacity", _bounded_float(
            self.inactive_opacity,
            field_name="inactive_opacity",
            minimum=0.0,
            maximum=1.0,
        ))
        object.__setattr__(self, "max_visible_poses", _bounded_int(
            self.max_visible_poses,
            field_name="max_visible_poses",
            minimum=1,
            maximum=MAX_VISUAL_ELEMENTS,
        ))
        object.__setattr__(self, "group_name", _clean_config_name(
            self.group_name,
            field_name="group_name",
            maximum=MAX_GROUP_NAME_LENGTH,
        ))
        object.__setattr__(self, "show_reference", bool(self.show_reference))
        object.__setattr__(self, "show_cofactors", bool(self.show_cofactors))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def pose_ids(self) -> Tuple[str, ...]:
        return tuple(self.poses)

    @property
    def active_selection(self) -> MolecularSelection:
        if self.active_pose_id is None:
            return MolecularSelection.none()
        return self.poses[self.active_pose_id]

    @property
    def visible_pose_ids(self) -> Tuple[str, ...]:
        ids = self.pose_ids
        if not ids:
            return ()
        if self.display_mode is PoseDisplayMode.ACTIVE:
            return () if self.active_pose_id is None else (self.active_pose_id,)
        ordered = list(ids)
        if self.active_pose_id in ordered:
            ordered.remove(self.active_pose_id)
            ordered.insert(0, self.active_pose_id)
        return tuple(ordered[: self.max_visible_poses])

    @property
    def combined_selection(self) -> MolecularSelection:
        return selection_union(self.ligand, *self.poses.values(), self.cofactors)

    def color_for_pose(self, pose_id: str) -> str:
        if self.color_mode is PoseColorMode.SINGLE:
            return self.style.color
        index = self.pose_ids.index(pose_id)
        return self.pose_colors[index % len(self.pose_colors)]


# 12.2. Input resolution
# -----------------------------------------------------------------------------

def _ligand_selection_bundle(value: Any) -> Optional[MolecularSelectionBundle]:
    """Resolve role selections when possible."""

    if value is None:
        return None
    if isinstance(value, MolecularSelectionBundle):
        return value
    if isinstance(value, MolecularSpecificationBundle):
        return build_molecular_selection_bundle(value, include_named=False)
    if isinstance(value, Mapping):
        data = dict(value)
        if any(key in data for key in ("receptor", "ligands", "cofactors", "solvent", "ions", "poses", "structure")):
            try:
                return build_molecular_selection_bundle(data, include_named=False)
            except VisualizationError:
                poses = _coerce_ligand_pose_map(data.get("poses"))
                return MolecularSelectionBundle(
                    receptor=coerce_selection(data.get("receptor")),
                    ligands=coerce_selection(data.get("ligands")),
                    cofactors=coerce_selection(data.get("cofactors")),
                    solvent=coerce_selection(data.get("solvent")),
                    ions=coerce_selection(data.get("ions")),
                    poses=poses,
                    metadata={"source": "mapping"},
                )
    return None


def _coerce_ligand_pose_map(value: Any) -> Dict[str, MolecularSelection]:
    """Normalize pose inputs to an ordered selection map."""

    if value is None:
        return {}
    if isinstance(value, MolecularSelectionBundle):
        return dict(value.poses)
    if isinstance(value, MolecularSpecificationBundle):
        return dict(build_molecular_selection_bundle(value, include_named=False).poses)
    if isinstance(value, PoseSpec):
        return {value.pose_id: pose_spec_to_selection(value)}
    if isinstance(value, Mapping):
        data = dict(value)
        if "pose_id" in data:
            pose = coerce_pose_spec(data)
            return {pose.pose_id: pose_spec_to_selection(pose)}
        if "poses" in data and (
            set(data) == {"poses"}
            or any(key in data for key in ("receptor", "ligands", "cofactors", "solvent", "ions", "structure"))
        ):
            return _coerce_ligand_pose_map(data.get("poses"))
        return {str(key): coerce_selection(item) for key, item in data.items()}
    if isinstance(value, (str, MolecularSelection)):
        return {"pose_1": coerce_selection(value)}
    if isinstance(value, Iterable):
        result: Dict[str, MolecularSelection] = {}
        for index, item in enumerate(value):
            if isinstance(item, PoseSpec) or (isinstance(item, Mapping) and "pose_id" in item):
                pose = coerce_pose_spec(item, index=index)
                result[pose.pose_id] = pose_spec_to_selection(pose)
            else:
                pose_id = _object_value(item, "pose_id", "identifier", "name", default=f"pose_{index + 1}")
                result[str(pose_id)] = coerce_selection(item)
        return result
    raise VisualizationSpecificationError(
        "Unsupported pose collection.",
        context={"type": type(value).__name__},
    )


def _resolve_active_pose_id(
    poses: Mapping[str, MolecularSelection],
    *,
    active_pose_id: Optional[str],
    active_pose_index: Optional[int],
) -> Optional[str]:
    """Resolve an active pose by id or index."""

    ids = tuple(poses)
    if not ids:
        return None
    if active_pose_id is not None:
        text = _clean_spec_text(active_pose_id, field_name="active_pose_id", allow_none=False)
        if text not in poses:
            raise VisualizationSpecificationError(
                "Unknown active pose identifier.",
                context={"active_pose_id": text, "pose_ids": list(ids)},
            )
        return text
    index = 0 if active_pose_index is None else _bounded_int(
        active_pose_index,
        field_name="active_pose_index",
        minimum=0,
    )
    return ids[min(index, len(ids) - 1)]


def build_ligand_visualization_spec(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    ligand: Any = None,
    poses: Any = None,
    active_pose_id: Optional[str] = None,
    active_pose_index: Optional[int] = None,
    cofactors: Any = None,
    representation: Any = None,
    color: Any = None,
    color_mode: Any = None,
    opacity: Optional[float] = None,
    display_mode: Any = None,
    pose_color_mode: Any = None,
    pose_colors: Optional[Iterable[Any]] = None,
    active_opacity: Optional[float] = None,
    inactive_opacity: Optional[float] = None,
    max_visible_poses: Optional[int] = None,
    show_reference: bool = True,
    show_cofactors: bool = True,
    enabled: Optional[bool] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> LigandVisualizationSpec:
    """Build a ligand display specification."""

    config_obj = resolve_visualization_config(config_value)
    bundle = _ligand_selection_bundle(molecular_input)
    style = config_obj.style_for(MolecularRole.LIGAND)
    style_changes: Dict[str, Any] = {}
    if representation is not None:
        style_changes["representation"] = MolecularRepresentation.parse(representation)
    if color is not None:
        style_changes["color"] = normalize_color(color, field_name="color")
    if color_mode is not None:
        style_changes["color_mode"] = ColorMode.parse(color_mode)
    if opacity is not None:
        style_changes["opacity"] = opacity
    if style_changes:
        style = replace(style, **style_changes)
    ligand_selection = (
        coerce_selection(ligand)
        if ligand is not None
        else bundle.ligands if bundle is not None else coerce_selection(molecular_input)
    )
    pose_map = (
        _coerce_ligand_pose_map(poses)
        if poses is not None
        else dict(bundle.poses) if bundle is not None else {}
    )
    cofactor_selection = (
        coerce_selection(cofactors)
        if cofactors is not None
        else bundle.cofactors if bundle is not None else MolecularSelection.none()
    )
    multipose = config_obj.multipose
    active_id = _resolve_active_pose_id(
        pose_map,
        active_pose_id=active_pose_id,
        active_pose_index=multipose.active_pose_index if active_pose_index is None else active_pose_index,
    )
    ligand_enabled = config_obj.scene.show_ligand and style.visible if enabled is None else bool(enabled)
    return LigandVisualizationSpec(
        ligand=ligand_selection,
        style=style,
        poses=pose_map,
        active_pose_id=active_id,
        cofactors=cofactor_selection,
        cofactor_style=config_obj.style_for(MolecularRole.COFACTOR),
        display_mode=multipose.display_mode if display_mode is None else display_mode,
        color_mode=multipose.color_mode if pose_color_mode is None else pose_color_mode,
        pose_colors=multipose.pose_colors if pose_colors is None else tuple(pose_colors),
        active_opacity=multipose.active_opacity if active_opacity is None else active_opacity,
        inactive_opacity=multipose.inactive_opacity if inactive_opacity is None else inactive_opacity,
        max_visible_poses=multipose.max_visible_poses if max_visible_poses is None else max_visible_poses,
        group_name=multipose.group_name,
        show_reference=show_reference,
        show_cofactors=show_cofactors,
        enabled=ligand_enabled,
        metadata={
            "profile": config_obj.profile.value,
            "config_fingerprint": config_obj.fingerprint(),
            **dict(metadata or {}),
        },
    )


def coerce_ligand_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> LigandVisualizationSpec:
    """Coerce ligand display input."""

    if isinstance(value, LigandVisualizationSpec):
        return value
    if isinstance(value, Mapping) and "style" in value and "ligand" in value:
        return LigandVisualizationSpec(**dict(value))
    return build_ligand_visualization_spec(value, config_value=config_value)


# 12.3. Plan actions
# -----------------------------------------------------------------------------

def _ligand_style_parameters(style: MolecularStyleConfig) -> Dict[str, Any]:
    """Return backend-neutral ligand style parameters."""

    return {
        "representation": style.representation.value,
        "color": style.color,
        "color_mode": style.color_mode.value,
        "opacity": style.opacity,
        "stick_radius": style.stick_radius,
        "bond_radius": style.bond_radius,
        "ball_scale": style.ball_scale,
        "surface_opacity": style.surface_opacity,
        "show_hydrogens": style.show_hydrogens,
    }


def build_ligand_visualization_actions(
    value: Any,
    *,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert ligand display data to plan actions."""

    spec = coerce_ligand_visualization_spec(value)
    dependencies = _action_dependencies(depends_on)
    actions: List[VisualizationAction] = []
    if spec.show_reference:
        actions.append(VisualizationAction(
            action_id="ligand:base",
            operation=PlanOperation.SHOW_LIGAND,
            layer=VisualLayer.LIGAND,
            selection=spec.ligand,
            parameters={"component": "reference", **_ligand_style_parameters(spec.style)},
            depends_on=dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled and bool(spec.ligand),
            optional=bool(spec.poses),
            description="Render the reference ligand.",
            tags=("ligand", "reference"),
            metadata=spec.metadata,
        ))
    for index, pose_id in enumerate(spec.visible_pose_ids):
        active = pose_id == spec.active_pose_id
        actions.append(VisualizationAction(
            action_id=f"ligand:pose:{index:04d}",
            operation=PlanOperation.SHOW_LIGAND,
            layer=VisualLayer.LIGAND,
            selection=spec.poses[pose_id],
            parameters={
                "component": "pose",
                "pose_id": pose_id,
                "active": active,
                "group_name": spec.group_name,
                "display_mode": spec.display_mode.value,
                "pose_color_mode": spec.color_mode.value,
                "color": spec.color_for_pose(pose_id),
                "opacity": spec.active_opacity if active else spec.inactive_opacity,
                **{
                    key: value
                    for key, value in _ligand_style_parameters(spec.style).items()
                    if key not in {"color", "opacity"}
                },
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH if active else OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=not active,
            description="Render a ligand pose.",
            tags=("ligand", "pose", "active" if active else "inactive"),
            metadata={"pose_id": pose_id},
        ))
    if spec.show_cofactors:
        actions.append(VisualizationAction(
            action_id="ligand:cofactors",
            operation=PlanOperation.SHOW_LIGAND,
            layer=VisualLayer.LIGAND,
            selection=spec.cofactors,
            parameters={"component": "cofactors", **_ligand_style_parameters(spec.cofactor_style)},
            depends_on=dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled and bool(spec.cofactors),
            optional=True,
            description="Render ligand-associated cofactors.",
            tags=("ligand", "cofactor"),
        ))
    return tuple(actions)


def build_ligand_visualization_plan(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    spec: Any = None,
    plan_id: str = "ligand-visualization",
    name: str = "Ligand visualization",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Build a standalone ligand plan."""

    ligand_spec = (
        coerce_ligand_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_ligand_visualization_spec(
            molecular_input,
            config_value=config_value,
            **spec_overrides,
        )
    )
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_ligand_visualization_actions(ligand_spec),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display the ligand, selected poses and cofactors.",
        metadata={"ligand_spec": ligand_spec.to_dict(), **dict(metadata or {})},
    )


def attach_ligand_visualization(
    plan: Any,
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    spec: Any = None,
    replace_existing: bool = True,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Attach ligand actions to an existing plan."""

    base = coerce_visualization_plan(plan)
    ligand_spec = (
        coerce_ligand_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_ligand_visualization_spec(
            molecular_input,
            config_value=config_value,
            **spec_overrides,
        )
    )
    dependencies = ("scene:prepare",) if "scene:prepare" in base.action_map else ()
    incoming = build_ligand_visualization_actions(ligand_spec, depends_on=dependencies)
    existing = tuple(action for action in base.actions if action.action_id.startswith("ligand:"))
    if existing and not replace_existing:
        raise VisualizationPlanError("Ligand visualization actions already exist.")
    actions = [action for action in base.actions if not action.action_id.startswith("ligand:")]
    actions.extend(incoming)
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "ligand_visualization": ligand_spec.to_dict()},
    )


def visualize_ligand(
    molecular_input: Any = None,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach ligand visualization."""

    if plan is None:
        return build_ligand_visualization_plan(
            molecular_input,
            config_value=config_value,
            **kwargs,
        )
    return attach_ligand_visualization(
        plan,
        molecular_input,
        config_value=config_value,
        **kwargs,
    )


# 12.4. Validation and serialization
# -----------------------------------------------------------------------------

def validate_ligand_visualization(value: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate ligand display semantics."""

    spec = coerce_ligand_visualization_spec(value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.ligand and not spec.poses:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "ligand_selection_missing",
            "Ligand visualization requires a ligand or pose selection.",
            "ligand:base",
        ))
    if spec.show_reference and not spec.ligand:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "ligand_reference_missing",
            "Reference-ligand display is enabled without a reference selection.",
            "ligand:base",
        ))
    if spec.show_cofactors and not spec.cofactors:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "ligand_cofactors_missing",
            "Cofactor display is enabled without a cofactor selection.",
            "ligand:cofactors",
        ))
    if len(spec.poses) > spec.max_visible_poses and spec.display_mode is not PoseDisplayMode.ACTIVE:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "ligand_pose_limit",
            "The pose collection exceeds the visible-pose limit.",
            "ligand:poses",
        ))
    if spec.inactive_opacity > spec.active_opacity:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "ligand_pose_opacity",
            "Inactive poses are more opaque than the active pose.",
            "ligand:poses",
        ))
    if spec.enabled and not spec.style.visible:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "ligand_style_hidden",
            "Ligand visualization is enabled but its style is hidden.",
            "ligand:base",
        ))
    return tuple(issues)


def summarize_ligand_visualization(value: Any) -> Dict[str, Any]:
    """Return compact ligand display statistics."""

    spec = coerce_ligand_visualization_spec(value)
    actions = build_ligand_visualization_actions(spec)
    issues = validate_ligand_visualization(spec)
    return {
        "enabled": spec.enabled,
        "ligand_selection": spec.ligand.expression,
        "representation": spec.style.representation.value,
        "pose_count": len(spec.poses),
        "visible_pose_count": len(spec.visible_pose_ids),
        "active_pose_id": spec.active_pose_id,
        "display_mode": spec.display_mode.value,
        "color_mode": spec.color_mode.value,
        "cofactors_enabled": spec.show_cofactors,
        "action_count": len(actions),
        "active_action_count": sum(action.enabled for action in actions),
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def ligand_visualization_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize ligand visualization."""

    return coerce_ligand_visualization_spec(value).to_dict()


def ligand_visualization_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize ligand visualization as JSON."""

    return json.dumps(
        ligand_visualization_to_dict(value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


