# =============================================================================
# Section 13 — Interaction visualization
# =============================================================================

_INTERACTION_PLAN_PREFIX: Final[str] = "interactions:"
_INTERACTION_BATCH_LIMIT: Final[int] = 2048


# 13.1. Display specification
# -----------------------------------------------------------------------------


def _coerce_interaction_collection(
    value: Any,
    *,
    config_value: Any = None,
    pose_id: Optional[str] = None,
) -> VisualInteractionCollection:
    """Coerce interaction display data."""

    if isinstance(value, VisualInteractionCollection):
        return value
    if isinstance(value, Mapping) and "interactions" in value:
        return VisualInteractionCollection(
            interactions=tuple(value.get("interactions") or ()),
            name=value.get("name") or DEFAULT_PSEUDOBOND_GROUP,
            pose_id=value.get("pose_id", pose_id),
            metadata=value.get("metadata") or {},
        )
    return build_visual_interactions(value, config_value=config_value, pose_id=pose_id)


def _interaction_family_tuple(values: Any) -> Tuple[InteractionFamily, ...]:
    """Normalize interaction families."""

    if values is None:
        return ()
    if isinstance(values, (str, InteractionFamily)):
        values = (values,)
    result: List[InteractionFamily] = []
    for value in values:
        parsed = InteractionFamily.parse(value, default=InteractionFamily.UNKNOWN)
        if parsed not in result:
            result.append(parsed)
    return tuple(result)


def _interaction_strength_tuple(values: Any) -> Tuple[InteractionStrength, ...]:
    """Normalize interaction strengths."""

    if values is None:
        return ()
    if isinstance(values, (str, InteractionStrength)):
        values = (values,)
    result: List[InteractionStrength] = []
    for value in values:
        parsed = InteractionStrength.parse(value, default=InteractionStrength.UNKNOWN)
        if parsed not in result:
            result.append(parsed)
    return tuple(result)


@dataclass(frozen=True, slots=True)
class InteractionVisualizationSpec(MolecularSpecMixin):
    """Interaction display configuration."""

    collection: VisualInteractionCollection = field(default_factory=VisualInteractionCollection)
    enabled: bool = True
    families: Tuple[InteractionFamily, ...] = ()
    strengths: Tuple[InteractionStrength, ...] = ()
    pose_id: Optional[str] = None
    visible_only: bool = True
    group_by_family: bool = True
    group_by_style: bool = True
    sort_interactions: bool = True
    max_count: int = DEFAULT_INTERACTION_MAX_COUNT
    max_batch_size: int = _INTERACTION_BATCH_LIMIT
    show_distances: bool = False
    show_labels: bool = False
    highlight_endpoints: bool = False
    endpoint_representation: MolecularRepresentation = MolecularRepresentation.STICKS
    endpoint_color: Optional[str] = None
    group_prefix: str = DEFAULT_PSEUDOBOND_GROUP
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = _coerce_interaction_collection(self.collection, pose_id=self.pose_id)
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "families", _interaction_family_tuple(self.families))
        object.__setattr__(self, "strengths", _interaction_strength_tuple(self.strengths))
        object.__setattr__(self, "pose_id", _interaction_text(self.pose_id, field_name="pose_id"))
        object.__setattr__(self, "visible_only", bool(self.visible_only))
        object.__setattr__(self, "group_by_family", bool(self.group_by_family))
        object.__setattr__(self, "group_by_style", bool(self.group_by_style))
        object.__setattr__(self, "sort_interactions", bool(self.sort_interactions))
        object.__setattr__(self, "max_count", _bounded_int(
            self.max_count,
            field_name="max_count",
            minimum=0,
            maximum=MAX_VISUAL_ELEMENTS,
        ))
        object.__setattr__(self, "max_batch_size", _bounded_int(
            self.max_batch_size,
            field_name="max_batch_size",
            minimum=1,
            maximum=MAX_VISUAL_ELEMENTS,
        ))
        object.__setattr__(self, "show_distances", bool(self.show_distances))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "highlight_endpoints", bool(self.highlight_endpoints))
        object.__setattr__(self, "endpoint_representation", MolecularRepresentation.parse(
            self.endpoint_representation,
            default=MolecularRepresentation.STICKS,
        ))
        object.__setattr__(self, "endpoint_color", None if self.endpoint_color is None else normalize_color(self.endpoint_color))
        object.__setattr__(self, "group_prefix", _clean_config_name(
            self.group_prefix,
            field_name="group_prefix",
            maximum=MAX_GROUP_NAME_LENGTH,
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[VisualInteractionSpec, ...]:
        values = filter_visual_interactions(
            self.collection.interactions,
            families=self.families or None,
            strengths=self.strengths or None,
            pose_id=self.pose_id,
            visible_only=self.visible_only,
        )
        if self.sort_interactions:
            values = sort_visual_interactions(values)
        return values[:self.max_count]

    @property
    def visible_count(self) -> int:
        return len(self.selected)

    @property
    def involved_selection(self) -> MolecularSelection:
        selections = [
            endpoint
            for interaction in self.selected
            for endpoint in interaction.selections
            if not endpoint.is_none
        ]
        return selection_union(*selections)


@dataclass(frozen=True, slots=True)
class InteractionRenderBatch(MolecularSpecMixin):
    """One backend render batch."""

    batch_id: str
    family: InteractionFamily
    render_mode: InteractionRenderMode
    line_style: LineStyle
    color: str
    radius: float
    opacity: float
    dash_count: int
    group_name: str
    interactions: Tuple[VisualInteractionSpec, ...]
    show_distances: bool = False
    show_labels: bool = False

    def __post_init__(self) -> None:
        items = tuple(coerce_visual_interaction(item, index=index) for index, item in enumerate(self.interactions))
        if not items:
            raise VisualizationInteractionError("An interaction batch cannot be empty.")
        family = InteractionFamily.parse(self.family, default=items[0].family)
        object.__setattr__(self, "batch_id", _plan_identifier(self.batch_id, field_name="batch_id"))
        object.__setattr__(self, "family", family)
        object.__setattr__(self, "render_mode", InteractionRenderMode.parse(self.render_mode, default=InteractionRenderMode.PSEUDOBOND))
        object.__setattr__(self, "line_style", LineStyle.parse(self.line_style, default=LineStyle.DASHED))
        object.__setattr__(self, "color", normalize_color(self.color))
        object.__setattr__(self, "radius", _bounded_float(self.radius, field_name="radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
        object.__setattr__(self, "opacity", _bounded_float(self.opacity, field_name="opacity", minimum=0.0, maximum=1.0))
        object.__setattr__(self, "dash_count", _bounded_int(self.dash_count, field_name="dash_count", minimum=0, maximum=1000))
        object.__setattr__(self, "group_name", _clean_config_name(self.group_name, field_name="group_name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "interactions", items)
        object.__setattr__(self, "show_distances", bool(self.show_distances))
        object.__setattr__(self, "show_labels", bool(self.show_labels))

    @property
    def involved_selection(self) -> MolecularSelection:
        selections = [
            endpoint
            for interaction in self.interactions
            for endpoint in interaction.selections
            if not endpoint.is_none
        ]
        return selection_union(*selections)


# 13.2. Construction and batching
# -----------------------------------------------------------------------------


def build_interaction_visualization_spec(
    values: Any,
    *,
    config_value: Any = None,
    pose_id: Optional[str] = None,
    families: Optional[Iterable[Any]] = None,
    strengths: Optional[Iterable[Any]] = None,
    **overrides: Any,
) -> InteractionVisualizationSpec:
    """Build interaction display settings."""

    config_obj = resolve_visualization_config(config_value)
    collection = _coerce_interaction_collection(values, config_value=config_obj, pose_id=pose_id)
    defaults: Dict[str, Any] = {
        "collection": collection,
        "enabled": config_obj.scene.show_interactions,
        "families": tuple(families or ()),
        "strengths": tuple(strengths or ()),
        "pose_id": pose_id,
        "max_count": config_obj.interactions.max_count,
        "show_distances": False,
        "show_labels": False,
        "group_prefix": config_obj.interactions.group_name,
    }
    defaults.update(overrides)
    return InteractionVisualizationSpec(**defaults)


def coerce_interaction_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> InteractionVisualizationSpec:
    """Coerce interaction display settings."""

    if isinstance(value, InteractionVisualizationSpec):
        return value
    if isinstance(value, Mapping) and "collection" in value:
        data = dict(value)
        data["collection"] = _coerce_interaction_collection(data["collection"], config_value=config_value)
        return InteractionVisualizationSpec(**data)
    return build_interaction_visualization_spec(value, config_value=config_value)


def _interaction_batch_key(
    item: VisualInteractionSpec,
    spec: InteractionVisualizationSpec,
) -> Tuple[Any, ...]:
    style = item.style or resolve_interaction_style(item.family)
    family = item.family if spec.group_by_family else InteractionFamily.UNKNOWN
    if spec.group_by_style:
        return (
            family,
            style.render_mode,
            style.line_style,
            style.color,
            style.radius,
            style.opacity,
            style.dash_count,
            style.group_name,
        )
    return (family, style.render_mode)


def _interaction_batch_token(value: Any) -> str:
    token = _normalized_interaction_token(value) or "unknown"
    return token[:64]


def build_interaction_render_batches(
    value: Any,
) -> Tuple[InteractionRenderBatch, ...]:
    """Group interactions into efficient render batches."""

    spec = coerce_interaction_visualization_spec(value)
    grouped: Dict[Tuple[Any, ...], List[VisualInteractionSpec]] = defaultdict(list)
    for item in spec.selected:
        grouped[_interaction_batch_key(item, spec)].append(item)

    batches: List[InteractionRenderBatch] = []
    for group_index, (key, items) in enumerate(grouped.items()):
        family = key[0]
        first_style = items[0].style or resolve_interaction_style(items[0].family)
        for chunk_index in range(0, len(items), spec.max_batch_size):
            chunk = tuple(items[chunk_index:chunk_index + spec.max_batch_size])
            suffix = chunk_index // spec.max_batch_size + 1
            batch_id = f"interactions:{_interaction_batch_token(family.value)}:{group_index + 1}:{suffix}"
            group_name = f"{spec.group_prefix}-{family.value}-{group_index + 1}-{suffix}"
            batches.append(InteractionRenderBatch(
                batch_id=batch_id,
                family=family,
                render_mode=first_style.render_mode,
                line_style=first_style.line_style,
                color=first_style.color or family.default_color,
                radius=first_style.radius,
                opacity=first_style.opacity,
                dash_count=first_style.dash_count,
                group_name=group_name,
                interactions=chunk,
                show_distances=spec.show_distances or first_style.show_distance,
                show_labels=spec.show_labels or first_style.show_label,
            ))
    return tuple(batches)


def _interaction_endpoint_payload(endpoint: InteractionEndpointSpec) -> Dict[str, Any]:
    """Serialize one render endpoint."""

    return {
        "selection": endpoint.selection.expression or None,
        "selection_kind": endpoint.selection.kind.value,
        "point": endpoint.point,
        "label": endpoint.effective_label or None,
        "role": endpoint.role.value,
        "source_id": endpoint.source_id,
    }


def _interaction_segment_payload(item: VisualInteractionSpec) -> Dict[str, Any]:
    """Serialize one interaction segment."""

    return {
        "interaction_id": item.interaction_id,
        "family": item.family.value,
        "subtype": item.subtype,
        "source": _interaction_endpoint_payload(item.source),
        "target": _interaction_endpoint_payload(item.target),
        "distance": item.distance,
        "angle": item.angle,
        "offset": item.offset,
        "score": item.score,
        "strength": item.strength.value,
        "confidence": item.confidence.value,
        "pose_id": item.pose_id,
        "label": item.label,
    }


def interaction_batch_parameters(value: Any) -> Dict[str, Any]:
    """Return backend-neutral batch parameters."""

    batch = value if isinstance(value, InteractionRenderBatch) else InteractionRenderBatch(**dict(value))
    return {
        "component": "interaction_batch",
        "family": batch.family.value,
        "render_mode": batch.render_mode.value,
        "line_style": batch.line_style.value,
        "color": batch.color,
        "radius": batch.radius,
        "opacity": batch.opacity,
        "dash_count": batch.dash_count,
        "group_name": batch.group_name,
        "show_distances": batch.show_distances,
        "show_labels": batch.show_labels,
        "segments": [_interaction_segment_payload(item) for item in batch.interactions],
    }


# 13.3. Plan integration
# -----------------------------------------------------------------------------


def build_interaction_visualization_actions(
    value: Any,
    *,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert interaction display data to plan actions."""

    spec = coerce_interaction_visualization_spec(value)
    dependencies = _action_dependencies(depends_on)
    batches = build_interaction_render_batches(spec)
    actions: List[VisualizationAction] = []
    for batch in batches:
        actions.append(VisualizationAction(
            action_id=batch.batch_id,
            operation=PlanOperation.SHOW_INTERACTIONS,
            layer=VisualLayer.INTERACTIONS,
            selection=batch.involved_selection,
            parameters=interaction_batch_parameters(batch),
            depends_on=dependencies,
            priority=OperationPriority.HIGH,
            enabled=spec.enabled and bool(batch.interactions),
            description=f"Render {batch.family.label} interactions.",
            tags=("interactions", batch.family.value, batch.render_mode.value),
            metadata={"interaction_ids": tuple(item.interaction_id for item in batch.interactions)},
        ))
    if spec.highlight_endpoints and spec.involved_selection:
        batch_dependencies = tuple(batch.batch_id for batch in batches)
        actions.append(VisualizationAction(
            action_id="interactions:endpoints",
            operation=PlanOperation.SHOW_RESIDUES,
            layer=VisualLayer.RECEPTOR_FOCUS,
            selection=spec.involved_selection,
            parameters={
                "component": "interaction_endpoints",
                "representation": spec.endpoint_representation.value,
                "color": spec.endpoint_color,
            },
            depends_on=batch_dependencies or dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Highlight interaction endpoints.",
            tags=("interactions", "endpoints"),
        ))
    return tuple(actions)


def build_interaction_visualization_plan(
    values: Any,
    *,
    config_value: Any = None,
    spec: Any = None,
    plan_id: str = "interaction-visualization",
    name: str = "Interaction visualization",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Build a standalone interaction plan."""

    display_spec = (
        coerce_interaction_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_interaction_visualization_spec(values, config_value=config_value, **spec_overrides)
    )
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_interaction_visualization_actions(display_spec),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display normalized molecular interactions.",
        metadata={"interaction_spec": display_spec.to_dict(), **dict(metadata or {})},
    )


def _interaction_plan_dependencies(plan: VisualizationPlan) -> Tuple[str, ...]:
    """Resolve existing scene dependencies."""

    preferred = ("ligand:base", "receptor:focus", "receptor:base", "scene:prepare")
    return tuple(action_id for action_id in preferred if action_id in plan.action_map)


def attach_interaction_visualization(
    plan: Any,
    values: Any,
    *,
    config_value: Any = None,
    spec: Any = None,
    replace_existing: bool = True,
    **spec_overrides: Any,
) -> VisualizationPlan:
    """Attach interaction actions to a plan."""

    base = coerce_visualization_plan(plan)
    display_spec = (
        coerce_interaction_visualization_spec(spec, config_value=config_value)
        if spec is not None
        else build_interaction_visualization_spec(values, config_value=config_value, **spec_overrides)
    )
    existing = tuple(action for action in base.actions if action.action_id.startswith(_INTERACTION_PLAN_PREFIX))
    if existing and not replace_existing:
        raise VisualizationPlanError("Interaction visualization actions already exist.")
    actions = [action for action in base.actions if not action.action_id.startswith(_INTERACTION_PLAN_PREFIX)]
    actions.extend(build_interaction_visualization_actions(
        display_spec,
        depends_on=_interaction_plan_dependencies(base),
    ))
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "interaction_visualization": display_spec.to_dict()},
    )


def visualize_interactions(
    values: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach interaction visualization."""

    if plan is None:
        return build_interaction_visualization_plan(values, config_value=config_value, **kwargs)
    return attach_interaction_visualization(plan, values, config_value=config_value, **kwargs)


# 13.4. Validation and serialization
# -----------------------------------------------------------------------------


def validate_interaction_visualization(value: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate interaction display semantics."""

    spec = coerce_interaction_visualization_spec(value)
    issues: List[PlanValidationIssue] = []
    selected = spec.selected
    if spec.enabled and not spec.collection.interactions:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "interaction_collection_empty",
            "Interaction visualization requires at least one interaction.",
            "interactions",
        ))
    elif spec.enabled and not selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "interaction_filter_empty",
            "Interaction filters removed all interactions.",
            "interactions",
        ))
    if len(spec.collection.interactions) > spec.max_count:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "interaction_limit_applied",
            "The interaction collection exceeds the display limit.",
            "interactions",
            {"available": len(spec.collection.interactions), "displayed": len(selected)},
        ))
    unsupported = [item.interaction_id for item in selected if item.style and item.style.render_mode is InteractionRenderMode.HIDDEN]
    if unsupported and not spec.visible_only:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "interaction_hidden_styles",
            "Hidden interaction styles are included in the display specification.",
            "interactions",
            {"interaction_ids": tuple(unsupported)},
        ))
    incomplete = [
        item.interaction_id
        for item in selected
        if item.source.selection.is_none and item.source.point is None
        or item.target.selection.is_none and item.target.point is None
    ]
    if incomplete:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "interaction_endpoint_incomplete",
            "One or more interactions have incomplete endpoints.",
            "interactions",
            {"interaction_ids": tuple(incomplete)},
        ))
    return tuple(issues)


def summarize_interaction_visualization(value: Any) -> Dict[str, Any]:
    """Return compact interaction display statistics."""

    spec = coerce_interaction_visualization_spec(value)
    batches = build_interaction_render_batches(spec)
    issues = validate_interaction_visualization(spec)
    selected = spec.selected
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.interactions),
        "displayed_count": len(selected),
        "batch_count": len(batches),
        "families": dict(Counter(item.family.value for item in selected)),
        "strengths": dict(Counter(item.strength.value for item in selected)),
        "render_modes": dict(Counter(batch.render_mode.value for batch in batches)),
        "pose_id": spec.pose_id,
        "show_distances": spec.show_distances,
        "show_labels": spec.show_labels,
        "highlight_endpoints": spec.highlight_endpoints,
        "involved_selection": spec.involved_selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def interaction_visualization_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize interaction visualization."""

    return coerce_interaction_visualization_spec(value).to_dict()


def interaction_visualization_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize interaction visualization as JSON."""

    return json.dumps(
        interaction_visualization_to_dict(value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


