# 14.1. Geometry helpers
# -----------------------------------------------------------------------------

_VIRTUAL_POINT_PLAN_PREFIX: Final[str] = "markers:virtual:"
_DEFAULT_VIRTUAL_POINT_RADIUS: Final[float] = 0.25
_DEFAULT_NORMAL_LENGTH: Final[float] = 1.5


def vector_add(left: Any, right: Any) -> Vector3D:
    """Add two vectors."""

    a = normalize_vector3d(left, field_name="left")
    b = normalize_vector3d(right, field_name="right")
    return tuple(a[index] + b[index] for index in range(3))  # type: ignore[return-value]


def vector_subtract(left: Any, right: Any) -> Vector3D:
    """Subtract two vectors."""

    a = normalize_vector3d(left, field_name="left")
    b = normalize_vector3d(right, field_name="right")
    return tuple(a[index] - b[index] for index in range(3))  # type: ignore[return-value]


def vector_scale(value: Any, factor: Number) -> Vector3D:
    """Scale a vector."""

    vector = normalize_vector3d(value)
    scalar = float(factor)
    if not math.isfinite(scalar):
        raise VisualizationGeometryError("Vector scale must be finite.")
    return tuple(component * scalar for component in vector)  # type: ignore[return-value]


def vector_dot(left: Any, right: Any) -> float:
    """Return a dot product."""

    a = normalize_vector3d(left, field_name="left")
    b = normalize_vector3d(right, field_name="right")
    return float(sum(a[index] * b[index] for index in range(3)))


def vector_cross(left: Any, right: Any) -> Vector3D:
    """Return a cross product."""

    a = normalize_vector3d(left, field_name="left")
    b = normalize_vector3d(right, field_name="right")
    return (
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    )


def vector_norm(value: Any) -> float:
    """Return vector magnitude."""

    vector = normalize_vector3d(value)
    return math.sqrt(sum(component * component for component in vector))


def unit_vector(value: Any) -> Vector3D:
    """Return a unit vector."""

    return normalize_vector3d(value, unit=True)  # type: ignore[return-value]


def point_distance(left: Any, right: Any) -> float:
    """Return Cartesian distance."""

    return vector_norm(vector_subtract(left, right))


def midpoint(left: Any, right: Any) -> Point3D:
    """Return the midpoint of two points."""

    a = normalize_point3d(left, field_name="left")
    b = normalize_point3d(right, field_name="right")
    return tuple((a[index] + b[index]) / 2.0 for index in range(3))  # type: ignore[return-value]


def centroid(points: Iterable[Any], *, weights: Optional[Iterable[Number]] = None) -> Point3D:
    """Return a weighted centroid."""

    normalized = tuple(normalize_point3d(point) for point in points)
    if not normalized:
        raise VisualizationGeometryError("A centroid requires at least one point.")
    if weights is None:
        coefficients = (1.0,) * len(normalized)
    else:
        coefficients = tuple(float(value) for value in weights)
        if len(coefficients) != len(normalized):
            raise VisualizationGeometryError("Centroid weights must match the point count.")
        if not all(math.isfinite(value) and value >= 0.0 for value in coefficients):
            raise VisualizationGeometryError("Centroid weights must be finite and non-negative.")
    total = sum(coefficients)
    if total <= VISUALIZATION_EPSILON:
        raise VisualizationGeometryError("Centroid weights cannot sum to zero.")
    return tuple(
        sum(point[index] * weight for point, weight in zip(normalized, coefficients)) / total
        for index in range(3)
    )  # type: ignore[return-value]


def fit_plane_normal(points: Iterable[Any]) -> Vector3D:
    """Fit a plane normal to three or more points."""

    normalized = tuple(normalize_point3d(point) for point in points)
    if len(normalized) < 3:
        raise VisualizationGeometryError("Plane fitting requires at least three points.")
    center = centroid(normalized)
    centered = tuple(vector_subtract(point, center) for point in normalized)
    if NUMPY_AVAILABLE:
        matrix = np.asarray(centered, dtype=float)
        covariance = matrix.T @ matrix
        values, vectors = np.linalg.eigh(covariance)
        normal = tuple(float(value) for value in vectors[:, int(np.argmin(values))])
        return unit_vector(normal)
    best: Optional[Vector3D] = None
    best_norm = 0.0
    for index, left in enumerate(centered[:-1]):
        for right in centered[index + 1:]:
            candidate = vector_cross(left, right)
            magnitude = vector_norm(candidate)
            if magnitude > best_norm:
                best = candidate
                best_norm = magnitude
    if best is None or best_norm <= VISUALIZATION_COORDINATE_EPSILON:
        raise VisualizationGeometryError("Plane points are collinear.")
    return unit_vector(best)


def project_point_to_plane(point: Any, plane_point: Any, normal: Any) -> Point3D:
    """Project a point onto a plane."""

    target = normalize_point3d(point)
    origin = normalize_point3d(plane_point, field_name="plane_point")
    direction = unit_vector(normal)
    offset = vector_dot(vector_subtract(target, origin), direction)
    return vector_subtract(target, vector_scale(direction, offset))


def point_along_vector(point: Any, vector: Any, distance: Number) -> Point3D:
    """Move a point along a vector."""

    origin = normalize_point3d(point)
    return vector_add(origin, vector_scale(unit_vector(vector), distance))


# 14.2. Virtual-point models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class VirtualPointSpec(MolecularSpecMixin):
    """Backend-neutral geometric marker."""

    point_id: str
    coordinate: Point3D
    kind: VirtualPointKind = VirtualPointKind.CUSTOM
    source_selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    normal: Optional[Vector3D] = None
    label: Optional[str] = None
    role: MolecularRole = MolecularRole.MARKER
    color: Optional[str] = None
    radius: float = _DEFAULT_VIRTUAL_POINT_RADIUS
    opacity: float = 1.0
    shape: MarkerShape = MarkerShape.SPHERE
    pose_id: Optional[str] = None
    family: Optional[InteractionFamily] = None
    source_ids: Tuple[str, ...] = ()
    visible: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        family = None if self.family is None else InteractionFamily.parse(self.family, default=InteractionFamily.UNKNOWN)
        default_color = family.default_color if family is not None else ROLE_COLORS[ROLE_MARKER]
        source_ids = tuple(dict.fromkeys(str(value).strip() for value in self.source_ids if str(value).strip()))
        object.__setattr__(self, "point_id", _plan_identifier(self.point_id, field_name="point_id"))
        object.__setattr__(self, "coordinate", normalize_point3d(self.coordinate))
        object.__setattr__(self, "kind", VirtualPointKind.parse(self.kind, default=VirtualPointKind.CUSTOM))
        object.__setattr__(self, "source_selection", coerce_selection(self.source_selection))
        object.__setattr__(self, "normal", normalize_vector3d(self.normal, allow_none=True, unit=True))
        object.__setattr__(self, "label", _interaction_text(self.label, field_name="label"))
        object.__setattr__(self, "role", MolecularRole.parse(self.role, default=MolecularRole.MARKER))
        object.__setattr__(self, "color", normalize_color(self.color or default_color))
        object.__setattr__(self, "radius", _bounded_float(self.radius, field_name="radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
        object.__setattr__(self, "opacity", _bounded_float(self.opacity, field_name="opacity", minimum=0.0, maximum=1.0))
        object.__setattr__(self, "shape", MarkerShape.parse(self.shape, default=MarkerShape.SPHERE))
        object.__setattr__(self, "pose_id", _interaction_text(self.pose_id, field_name="pose_id"))
        object.__setattr__(self, "family", family)
        object.__setattr__(self, "source_ids", source_ids)
        object.__setattr__(self, "visible", bool(self.visible))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def key(self) -> Tuple[Any, ...]:
        rounded = tuple(round(value, DEFAULT_COORDINATE_PRECISION) for value in self.coordinate)
        return self.kind.value, rounded, self.pose_id

    def normal_endpoint(self, length: Number = _DEFAULT_NORMAL_LENGTH) -> Optional[Point3D]:
        return None if self.normal is None else point_along_vector(self.coordinate, self.normal, length)

    def translated(self, vector: Any) -> "VirtualPointSpec":
        return replace(self, coordinate=vector_add(self.coordinate, vector))


@dataclass(frozen=True, slots=True)
class VirtualPointCollection(MolecularSpecMixin):
    """Ordered virtual-point set."""

    points: Tuple[VirtualPointSpec, ...] = ()
    name: str = DEFAULT_MARKER_MODEL_NAME
    model_name: str = DEFAULT_MARKER_MODEL_NAME
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        points = tuple(coerce_virtual_point_spec(value, index=index) for index, value in enumerate(self.points))
        if len(points) > MAX_VIRTUAL_POINTS:
            raise VisualizationLimitError(
                f"Virtual-point collections cannot exceed {MAX_VIRTUAL_POINTS} entries.",
                context={"point_count": len(points)},
            )
        identifiers = [point.point_id for point in points]
        duplicates = sorted(identifier for identifier, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Virtual-point identifiers must be unique.",
                context={"duplicates": duplicates},
            )
        object.__setattr__(self, "points", points)
        object.__setattr__(self, "name", _clean_config_name(self.name, field_name="name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "model_name", _clean_config_name(self.model_name, field_name="model_name", maximum=MAX_GROUP_NAME_LENGTH))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def visible(self) -> Tuple[VirtualPointSpec, ...]:
        return tuple(point for point in self.points if point.visible)

    @property
    def center(self) -> Optional[Point3D]:
        return None if not self.points else centroid(point.coordinate for point in self.points)

    @property
    def bounds(self) -> Optional[Bounds3D]:
        if not self.points:
            return None
        coordinates = tuple(point.coordinate for point in self.points)
        low = tuple(min(point[index] for point in coordinates) for index in range(3))
        high = tuple(max(point[index] for point in coordinates) for index in range(3))
        return low, high  # type: ignore[return-value]

    @property
    def source_selection(self) -> MolecularSelection:
        return selection_union(*(point.source_selection for point in self.points if not point.source_selection.is_none))

    def by_kind(self, kind: Any) -> Tuple[VirtualPointSpec, ...]:
        parsed = VirtualPointKind.parse(kind, default=VirtualPointKind.CUSTOM)
        return tuple(point for point in self.points if point.kind is parsed)

    def by_pose(self, pose_id: Any) -> Tuple[VirtualPointSpec, ...]:
        token = str(pose_id)
        return tuple(point for point in self.points if point.pose_id == token)


@dataclass(frozen=True, slots=True)
class VirtualPointVisualizationSpec(MolecularSpecMixin):
    """Virtual-point display configuration."""

    collection: VirtualPointCollection
    enabled: bool = True
    show_labels: bool = False
    show_normals: bool = False
    normal_length: float = _DEFAULT_NORMAL_LENGTH
    group_by_kind: bool = True
    max_count: int = MAX_VIRTUAL_POINTS
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "collection", coerce_virtual_point_collection(self.collection))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "show_normals", bool(self.show_normals))
        object.__setattr__(self, "normal_length", _bounded_float(self.normal_length, field_name="normal_length", minimum=MIN_RADIUS, maximum=MAX_RADIUS))
        object.__setattr__(self, "group_by_kind", bool(self.group_by_kind))
        object.__setattr__(self, "max_count", _bounded_int(self.max_count, field_name="max_count", minimum=0, maximum=MAX_VIRTUAL_POINTS))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[VirtualPointSpec, ...]:
        return self.collection.visible[:self.max_count]


# 14.3. Conversion and generation
# -----------------------------------------------------------------------------

def coerce_virtual_point_spec(
    value: Any,
    *,
    index: int = 0,
    kind: Any = VirtualPointKind.CUSTOM,
) -> VirtualPointSpec:
    """Coerce a virtual point."""

    if isinstance(value, VirtualPointSpec):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("point_id", f"point:{index + 1}")
        data.setdefault("kind", kind)
        if "coordinate" not in data:
            data["coordinate"] = data.pop("point", data.pop("center", data.pop("centroid", None)))
        return VirtualPointSpec(**data)
    try:
        coordinate = normalize_point3d(value)
    except VisualizationError:
        coordinate = normalize_point3d(_object_value(value, "coordinate", "point", "center", "centroid"))
    return VirtualPointSpec(
        point_id=str(_object_value(value, "point_id", "id", "name", default=f"point:{index + 1}")),
        coordinate=coordinate,
        kind=_object_value(value, "kind", "point_kind", default=kind),
        normal=_object_value(value, "normal", "normal_vector"),
        label=_object_value(value, "label", "name"),
        pose_id=_object_value(value, "pose_id", "pose"),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_virtual_point_collection(value: Any) -> VirtualPointCollection:
    """Coerce a virtual-point collection."""

    if isinstance(value, VirtualPointCollection):
        return value
    if value is None:
        return VirtualPointCollection()
    if isinstance(value, Mapping):
        data = dict(value)
        if "points" not in data:
            data = {"points": (data,)}
        return VirtualPointCollection(**data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return VirtualPointCollection(points=tuple(value))
    points = _object_value(value, "points", "virtual_points", "centroids", default=None)
    if points is not None:
        return VirtualPointCollection(
            points=tuple(points),
            name=_object_value(value, "name", default=DEFAULT_MARKER_MODEL_NAME),
            model_name=_object_value(value, "model_name", default=DEFAULT_MARKER_MODEL_NAME),
            metadata=_object_value(value, "metadata", default={}),
        )
    return VirtualPointCollection(points=(coerce_virtual_point_spec(value),))


def _group_virtual_kind(value: Any) -> VirtualPointKind:
    token = _normalized_interaction_token(_object_value(value, "kind", "type", "group_type", default=""))
    if "aromatic" in token or "ring" in token:
        return VirtualPointKind.AROMATIC_CENTROID
    if "charge" in token or "cation" in token or "anion" in token:
        return VirtualPointKind.CHARGE_CENTER
    if "amide" in token:
        return VirtualPointKind.AMIDE_CENTER
    return VirtualPointKind.ATOM_GROUP


def virtual_point_from_group(
    value: Any,
    *,
    point_id: Optional[str] = None,
    kind: Any = None,
    color: Optional[ColorLike] = None,
    radius: float = _DEFAULT_VIRTUAL_POINT_RADIUS,
) -> VirtualPointSpec:
    """Create a point from a molecular group."""

    group = value if isinstance(value, MolecularGroupSpec) else MolecularGroupSpec(**value)
    center = group.effective_center
    if center is None:
        raise VisualizationCoordinateError(
            "The molecular group has no usable coordinates.",
            context={"group_id": group.group_id},
        )
    selection = molecular_group_to_selection(group) if group.atoms else MolecularSelection.none()
    return VirtualPointSpec(
        point_id=point_id or f"group:{group.group_id}",
        coordinate=center,
        kind=kind or _group_virtual_kind(group),
        source_selection=selection,
        normal=group.normal,
        label=group.group_id,
        role=group.role if group.role is not MolecularRole.UNKNOWN else MolecularRole.MARKER,
        color=color,
        radius=radius,
        source_ids=(group.group_id,),
        metadata={"group_kind": group.kind, "charge": group.charge, **dict(group.metadata)},
    )


def _endpoint_point(value: InteractionEndpointSpec) -> Optional[Point3D]:
    if value.point is not None:
        return value.point
    for key in ("coordinate", "center", "centroid", "scene_coord"):
        if key in value.metadata:
            try:
                return normalize_point3d(value.metadata[key])
            except VisualizationError:
                pass
    return None


def virtual_point_from_interaction(
    value: Any,
    *,
    point_id: Optional[str] = None,
    include_normal: bool = True,
) -> VirtualPointSpec:
    """Create an interaction midpoint."""

    interaction = coerce_visual_interaction(value)
    source = _endpoint_point(interaction.source)
    target = _endpoint_point(interaction.target)
    if source is None or target is None:
        raise VisualizationCoordinateError(
            "Interaction midpoint generation requires endpoint coordinates.",
            context={"interaction_id": interaction.interaction_id},
        )
    direction = unit_vector(vector_subtract(target, source)) if include_normal and point_distance(source, target) > VISUALIZATION_COORDINATE_EPSILON else None
    return VirtualPointSpec(
        point_id=point_id or f"interaction:{interaction.interaction_id}",
        coordinate=midpoint(source, target),
        kind=VirtualPointKind.INTERACTION_MIDPOINT,
        source_selection=selection_union(interaction.source.selection, interaction.target.selection),
        normal=direction,
        label=interaction.label or interaction.interaction_id,
        family=interaction.family,
        pose_id=interaction.pose_id,
        source_ids=(interaction.interaction_id,),
        metadata={"distance": interaction.distance, "score": interaction.score},
    )


def deduplicate_virtual_points(
    values: Iterable[Any],
    *,
    tolerance: float = VISUALIZATION_COORDINATE_EPSILON,
) -> Tuple[VirtualPointSpec, ...]:
    """Remove spatially equivalent points."""

    threshold = _bounded_float(tolerance, field_name="tolerance", minimum=0.0, maximum=MAX_RADIUS)
    result: List[VirtualPointSpec] = []
    for index, value in enumerate(values):
        point = coerce_virtual_point_spec(value, index=index)
        duplicate = next((
            existing for existing in result
            if existing.kind is point.kind
            and existing.pose_id == point.pose_id
            and point_distance(existing.coordinate, point.coordinate) <= threshold
        ), None)
        if duplicate is None:
            result.append(point)
    return tuple(result)


def build_virtual_point_collection(
    values: Iterable[Any] = (),
    *,
    groups: Iterable[Any] = (),
    interactions: Iterable[Any] = (),
    name: str = DEFAULT_MARKER_MODEL_NAME,
    model_name: str = DEFAULT_MARKER_MODEL_NAME,
    deduplicate: bool = True,
    strict: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> VirtualPointCollection:
    """Build points from direct values and molecular geometry."""

    points: List[VirtualPointSpec] = [coerce_virtual_point_spec(value, index=index) for index, value in enumerate(values)]
    for group in groups:
        try:
            points.append(virtual_point_from_group(group))
        except VisualizationError:
            if strict:
                raise
    for interaction in interactions:
        try:
            points.append(virtual_point_from_interaction(interaction))
        except VisualizationError:
            if strict:
                raise
    normalized = deduplicate_virtual_points(points) if deduplicate else tuple(points)
    return VirtualPointCollection(
        points=normalized,
        name=name,
        model_name=model_name,
        metadata=metadata or {},
    )


def coerce_virtual_point_visualization_spec(value: Any) -> VirtualPointVisualizationSpec:
    """Coerce virtual-point display settings."""

    if isinstance(value, VirtualPointVisualizationSpec):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        collection = data.pop("collection", data.pop("points", ()))
        return VirtualPointVisualizationSpec(collection=coerce_virtual_point_collection(collection), **data)
    return VirtualPointVisualizationSpec(collection=coerce_virtual_point_collection(value))


# 14.4. Planning
# -----------------------------------------------------------------------------

def _virtual_point_payload(point: VirtualPointSpec, spec: VirtualPointVisualizationSpec) -> Dict[str, Any]:
    normal_endpoint = point.normal_endpoint(spec.normal_length) if spec.show_normals else None
    return {
        "point_id": point.point_id,
        "coordinate": point.coordinate,
        "kind": point.kind.value,
        "label": point.label if spec.show_labels else None,
        "normal": point.normal,
        "normal_endpoint": normal_endpoint,
        "color": point.color,
        "radius": point.radius,
        "opacity": point.opacity,
        "shape": point.shape.value,
        "pose_id": point.pose_id,
        "family": None if point.family is None else point.family.value,
        "source_ids": point.source_ids,
        "metadata": dict(point.metadata),
    }


def build_virtual_point_actions(
    value: Any,
    *,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert virtual points to marker actions."""

    spec = coerce_virtual_point_visualization_spec(value)
    if not spec.enabled or not spec.selected:
        return ()
    groups: Dict[str, List[VirtualPointSpec]] = defaultdict(list)
    for point in spec.selected:
        key = point.kind.value if spec.group_by_kind else "all"
        groups[key].append(point)
    dependencies = _action_dependencies(depends_on)
    actions: List[VisualizationAction] = []
    for index, (group_name, points) in enumerate(sorted(groups.items())):
        action_id = f"{_VIRTUAL_POINT_PLAN_PREFIX}{group_name}"
        actions.append(VisualizationAction(
            action_id=action_id,
            operation=PlanOperation.SHOW_MARKERS,
            layer=VisualLayer.MARKERS,
            selection=selection_union(*(point.source_selection for point in points if not point.source_selection.is_none)),
            parameters={
                "model_name": spec.collection.model_name,
                "group": group_name,
                "points": tuple(_virtual_point_payload(point, spec) for point in points),
                "show_labels": spec.show_labels,
                "show_normals": spec.show_normals,
                "normal_length": spec.normal_length,
            },
            depends_on=dependencies,
            priority=OperationPriority.NORMAL,
            description=f"Display {group_name} virtual points.",
            tags=("virtual_points", "markers", group_name),
            metadata={"point_count": len(points), "batch_index": index},
        ))
    return tuple(actions)


def build_virtual_point_plan(
    value: Any,
    *,
    plan_id: str = "virtual-points",
    name: str = "Centroids and virtual points",
    profile: Any = VisualizationProfile.ANALYSIS,
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
) -> VisualizationPlan:
    """Build a standalone virtual-point plan."""

    spec = coerce_virtual_point_visualization_spec(value)
    return build_visualization_plan(
        build_virtual_point_actions(spec),
        plan_id=plan_id,
        name=name,
        profile=profile,
        execution_mode=execution_mode,
        description="Display centroids and generated geometric markers.",
        metadata={"virtual_point_spec": spec.to_dict(), **dict(metadata or {})},
    )


def _virtual_point_dependencies(plan: VisualizationPlan) -> Tuple[str, ...]:
    preferred = ("scene:prepare", "receptor:base", "receptor:focus", "ligand:base")
    dependencies = [action_id for action_id in preferred if action_id in plan.action_map]
    interaction_actions = [
        action.action_id for action in plan.actions
        if action.action_id.startswith("interactions:")
    ]
    return tuple(dict.fromkeys((*dependencies, *interaction_actions)))


def attach_virtual_points(
    plan: Any,
    value: Any,
    *,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach virtual-point actions to a plan."""

    base = coerce_visualization_plan(plan)
    spec = coerce_virtual_point_visualization_spec(value)
    existing = tuple(action for action in base.actions if action.action_id.startswith(_VIRTUAL_POINT_PLAN_PREFIX))
    if existing and not replace_existing:
        raise VisualizationPlanError("Virtual-point actions already exist.")
    actions = [action for action in base.actions if not action.action_id.startswith(_VIRTUAL_POINT_PLAN_PREFIX)]
    actions.extend(build_virtual_point_actions(spec, depends_on=_virtual_point_dependencies(base)))
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "virtual_points": spec.to_dict()},
    )


def visualize_virtual_points(
    value: Any,
    *,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach virtual-point visualization."""

    spec = coerce_virtual_point_visualization_spec(value)
    if kwargs:
        spec = replace(spec, **kwargs)
    return build_virtual_point_plan(spec) if plan is None else attach_virtual_points(plan, spec)


# 14.5. Validation and serialization
# -----------------------------------------------------------------------------

def validate_virtual_points(value: Any) -> Tuple[PlanValidationIssue, ...]:
    """Validate virtual-point display semantics."""

    spec = coerce_virtual_point_visualization_spec(value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.collection.points:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "virtual_points_empty",
            "No virtual points are available for display.",
            "virtual_points",
        ))
    if len(spec.collection.points) > spec.max_count:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "virtual_point_limit_applied",
            "The virtual-point collection exceeds the display limit.",
            "virtual_points",
            {"available": len(spec.collection.points), "displayed": len(spec.selected)},
        ))
    normal_count = sum(point.normal is not None for point in spec.selected)
    if spec.show_normals and normal_count == 0 and spec.selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "virtual_normals_missing",
            "Normal-vector display is enabled but no point defines a normal.",
            "virtual_points",
        ))
    return tuple(issues)


def summarize_virtual_points(value: Any) -> Dict[str, Any]:
    """Return compact virtual-point statistics."""

    spec = coerce_virtual_point_visualization_spec(value)
    points = spec.selected
    issues = validate_virtual_points(spec)
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.points),
        "displayed_count": len(points),
        "kinds": dict(Counter(point.kind.value for point in points)),
        "poses": dict(Counter(point.pose_id or "unassigned" for point in points)),
        "normal_count": sum(point.normal is not None for point in points),
        "label_count": sum(bool(point.label) for point in points),
        "center": spec.collection.center,
        "bounds": spec.collection.bounds,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def virtual_points_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize virtual-point visualization."""

    return coerce_virtual_point_visualization_spec(value).to_dict()


def virtual_points_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize virtual-point visualization as JSON."""

    return json.dumps(virtual_points_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


