# =============================================================================
# Section 15 — Involved residues
# =============================================================================

_RESIDUE_MAX_COUNT: Final[int] = 2000
_RESIDUE_DEFAULT_LIMIT: Final[int] = 250
_RESIDUE_SCORE_EPSILON: Final[float] = 1.0e-12
_RESIDUE_STRENGTH_WEIGHTS: Final[Mapping[InteractionStrength, float]] = MappingProxyType({
    InteractionStrength.STRONG: 1.00,
    InteractionStrength.MODERATE: 0.70,
    InteractionStrength.WEAK: 0.40,
    InteractionStrength.BORDERLINE: 0.20,
    InteractionStrength.UNKNOWN: 0.50,
})


def _residue_path(value: Any) -> MolecularPathSpec:
    """Return a residue-level path."""

    path = coerce_molecular_path(value)
    if path.atom_name:
        path = path.parent()
    if path.residue_number is None:
        raise VisualizationSpecificationError("A residue path requires residue_number.")
    return path


def _residue_id(path: MolecularPathSpec) -> str:
    """Build a stable residue identifier."""

    parts = (
        path.model_id or "*",
        path.chain_id or "*",
        f"{path.residue_number or '*'}{path.insertion_code or ''}",
    )
    return ":".join(parts)


def _residue_float(value: Any, *, field_name: str, minimum: Optional[float] = None) -> Optional[float]:
    """Normalize an optional residue metric."""

    return _optional_spec_float(value, field_name=field_name, minimum=minimum)


def _residue_families(values: Iterable[Any]) -> Tuple[InteractionFamily, ...]:
    """Normalize interaction families."""

    return tuple(dict.fromkeys(
        InteractionFamily.parse(value, default=InteractionFamily.UNKNOWN)
        for value in values
    ))


def _residue_texts(values: Iterable[Any], *, field_name: str) -> Tuple[str, ...]:
    """Normalize identifier sequences."""

    output: List[str] = []
    for value in values:
        text = _clean_spec_text(value, field_name=field_name, max_length=MAX_VISUALIZATION_NAME_LENGTH)
        if text and text not in output:
            output.append(text)
    return tuple(output)


def _stable_palette_color(value: str, palette: Sequence[str] = POSE_PALETTE) -> str:
    """Resolve a stable categorical color."""

    colors = tuple(normalize_color(color) for color in palette) or (DEFAULT_MISSING_COLOR,)
    digest = sha256(value.encode(VISUALIZATION_TEXT_ENCODING)).digest()
    return colors[int.from_bytes(digest[:4], "big") % len(colors)]


@dataclass(frozen=True, slots=True)
class InvolvedResidueSpec(MolecularSpecMixin):
    """One residue participating in visual interactions."""

    residue_id: str
    residue: ResidueSpec
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    families: Tuple[InteractionFamily, ...] = ()
    interaction_ids: Tuple[str, ...] = ()
    pose_ids: Tuple[str, ...] = ()
    interaction_count: int = 0
    score: Optional[float] = None
    frequency: float = 0.0
    rank: Optional[int] = None
    color: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        residue = coerce_residue_spec(self.residue)
        selection = coerce_selection(self.selection, strict=False)
        if selection.is_none:
            selection = residue_spec_to_selection(residue)
        interaction_ids = _residue_texts(self.interaction_ids, field_name="interaction_id")
        pose_ids = _residue_texts(self.pose_ids, field_name="pose_id")
        count = _bounded_int(
            self.interaction_count or len(interaction_ids),
            field_name="interaction_count",
            minimum=0,
            maximum=MAX_VISUAL_ELEMENTS,
        )
        rank = None if self.rank is None else _bounded_int(
            self.rank, field_name="rank", minimum=1, maximum=MAX_VISUAL_ELEMENTS
        )
        object.__setattr__(self, "residue_id", _clean_config_name(
            self.residue_id or _residue_id(residue.path),
            field_name="residue_id",
            maximum=MAX_VISUALIZATION_NAME_LENGTH,
        ))
        object.__setattr__(self, "residue", residue)
        object.__setattr__(self, "selection", selection)
        object.__setattr__(self, "families", _residue_families(self.families))
        object.__setattr__(self, "interaction_ids", interaction_ids)
        object.__setattr__(self, "pose_ids", pose_ids)
        object.__setattr__(self, "interaction_count", count)
        object.__setattr__(self, "score", _residue_float(self.score, field_name="score"))
        object.__setattr__(self, "frequency", _bounded_float(
            self.frequency, field_name="frequency", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "rank", rank)
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def path(self) -> MolecularPathSpec:
        return self.residue.path

    @property
    def label(self) -> str:
        return self.residue.path.label or self.residue_id

    @property
    def predominant_family(self) -> InteractionFamily:
        counts = self.metadata.get("family_counts", {})
        if isinstance(counts, Mapping) and counts:
            key = max(counts, key=lambda item: (counts[item], str(item)))
            return InteractionFamily.parse(key, default=InteractionFamily.UNKNOWN)
        return self.families[0] if self.families else InteractionFamily.UNKNOWN

    @property
    def effective_score(self) -> float:
        if self.score is not None:
            return self.score
        return float(self.interaction_count)

    @property
    def key(self) -> Tuple[Any, ...]:
        return self.residue.key


@dataclass(frozen=True, slots=True)
class InvolvedResidueCollection(MolecularSpecMixin):
    """Validated involved-residue collection."""

    residues: Tuple[InvolvedResidueSpec, ...] = ()
    pose_count: int = 0
    source_interaction_count: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        residues = tuple(coerce_involved_residue_spec(value) for value in self.residues)
        identifiers = [item.residue_id for item in residues]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Involved residue identifiers must be unique.",
                context={"duplicates": duplicates},
            )
        if len(residues) > _RESIDUE_MAX_COUNT:
            raise VisualizationLimitError(
                f"Involved residue collections cannot exceed {_RESIDUE_MAX_COUNT} entries."
            )
        object.__setattr__(self, "residues", residues)
        object.__setattr__(self, "pose_count", _bounded_int(
            self.pose_count, field_name="pose_count", minimum=0, maximum=MAX_VISUAL_ELEMENTS
        ))
        object.__setattr__(self, "source_interaction_count", _bounded_int(
            self.source_interaction_count,
            field_name="source_interaction_count",
            minimum=0,
            maximum=MAX_VISUAL_ELEMENTS,
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def __len__(self) -> int:
        return len(self.residues)

    def __iter__(self) -> Iterator[InvolvedResidueSpec]:
        return iter(self.residues)

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.residues)) if self.residues else MolecularSelection.none()

    @property
    def family_counts(self) -> Mapping[str, int]:
        return MappingProxyType(dict(Counter(
            family.value for residue in self.residues for family in residue.families
        )))

    @property
    def pose_counts(self) -> Mapping[str, int]:
        return MappingProxyType(dict(Counter(
            pose_id for residue in self.residues for pose_id in residue.pose_ids
        )))

    def top(self, limit: int = 10) -> Tuple[InvolvedResidueSpec, ...]:
        count = _bounded_int(limit, field_name="limit", minimum=0, maximum=_RESIDUE_MAX_COUNT)
        return tuple(sorted(
            self.residues,
            key=lambda item: (
                item.rank if item.rank is not None else MAX_VISUAL_ELEMENTS,
                -item.effective_score,
                -item.frequency,
                item.residue_id,
            ),
        )[:count])

    def for_family(self, family: Any) -> Tuple[InvolvedResidueSpec, ...]:
        parsed = InteractionFamily.parse(family, default=InteractionFamily.UNKNOWN)
        return tuple(item for item in self.residues if parsed in item.families)

    def for_pose(self, pose_id: Any) -> Tuple[InvolvedResidueSpec, ...]:
        text = str(pose_id).strip()
        return tuple(item for item in self.residues if text in item.pose_ids)


@dataclass(frozen=True, slots=True)
class InvolvedResidueVisualizationSpec(MolecularSpecMixin):
    """Involved-residue display settings."""

    collection: InvolvedResidueCollection = field(default_factory=InvolvedResidueCollection)
    display_mode: ResidueDisplayMode = ResidueDisplayMode.INVOLVED
    representation: MolecularRepresentation = MolecularRepresentation.STICKS
    color_mode: ColorMode = ColorMode.INTERACTION
    fixed_color: str = DEFAULT_RECEPTOR_COLOR
    opacity: float = 1.0
    stick_radius: float = DEFAULT_STICK_RADIUS
    show_sidechains: bool = True
    show_backbone: bool = False
    show_labels: bool = False
    label_template: str = "{label}"
    min_frequency: float = 0.0
    min_score: Optional[float] = None
    max_residues: int = _RESIDUE_DEFAULT_LIMIT
    enabled: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = coerce_involved_residue_collection(self.collection)
        template = str(self.label_template or "{label}").strip()
        if len(template) > MAX_LABEL_TEXT_LENGTH:
            raise VisualizationSpecificationError("Residue label template is too long.")
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "display_mode", ResidueDisplayMode.parse(
            self.display_mode, default=ResidueDisplayMode.INVOLVED
        ))
        object.__setattr__(self, "representation", MolecularRepresentation.parse(
            self.representation, default=MolecularRepresentation.STICKS
        ))
        object.__setattr__(self, "color_mode", ColorMode.parse(
            self.color_mode, default=ColorMode.INTERACTION
        ))
        object.__setattr__(self, "fixed_color", normalize_color(self.fixed_color))
        object.__setattr__(self, "opacity", _bounded_float(
            self.opacity, field_name="opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "stick_radius", _bounded_float(
            self.stick_radius, field_name="stick_radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS
        ))
        object.__setattr__(self, "show_sidechains", bool(self.show_sidechains))
        object.__setattr__(self, "show_backbone", bool(self.show_backbone))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "label_template", template)
        object.__setattr__(self, "min_frequency", _bounded_float(
            self.min_frequency, field_name="min_frequency", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "min_score", _residue_float(self.min_score, field_name="min_score"))
        object.__setattr__(self, "max_residues", _bounded_int(
            self.max_residues, field_name="max_residues", minimum=1, maximum=_RESIDUE_MAX_COUNT
        ))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[InvolvedResidueSpec, ...]:
        values = [
            item for item in self.collection.residues
            if item.frequency + _RESIDUE_SCORE_EPSILON >= self.min_frequency
            and (self.min_score is None or item.effective_score + _RESIDUE_SCORE_EPSILON >= self.min_score)
        ]
        values.sort(key=lambda item: (
            item.rank if item.rank is not None else MAX_VISUAL_ELEMENTS,
            -item.effective_score,
            -item.frequency,
            item.residue_id,
        ))
        return tuple(values[:self.max_residues])

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.selected)) if self.selected else MolecularSelection.none()


# 15.2. Coercion and extraction
# -----------------------------------------------------------------------------

def coerce_involved_residue_spec(value: Any) -> InvolvedResidueSpec:
    """Coerce an involved-residue specification."""

    if isinstance(value, InvolvedResidueSpec):
        return value
    if isinstance(value, Mapping):
        payload = dict(value)
        residue_value = payload.get("residue", payload.get("path", value))
        residue = coerce_residue_spec(residue_value)
        return InvolvedResidueSpec(
            residue_id=payload.get("residue_id", _residue_id(residue.path)),
            residue=residue,
            selection=payload.get("selection", MolecularSelection.none()),
            families=tuple(payload.get("families", ())),
            interaction_ids=tuple(payload.get("interaction_ids", ())),
            pose_ids=tuple(payload.get("pose_ids", ())),
            interaction_count=payload.get("interaction_count", 0),
            score=payload.get("score"),
            frequency=payload.get("frequency", 0.0),
            rank=payload.get("rank"),
            color=payload.get("color"),
            metadata=payload.get("metadata", {}),
        )
    residue = coerce_residue_spec(value)
    return InvolvedResidueSpec(_residue_id(residue.path), residue)


def coerce_involved_residue_collection(value: Any) -> InvolvedResidueCollection:
    """Coerce an involved-residue collection."""

    if isinstance(value, InvolvedResidueCollection):
        return value
    if value is None:
        return InvolvedResidueCollection()
    if isinstance(value, Mapping):
        if "residues" in value:
            return InvolvedResidueCollection(
                residues=tuple(value.get("residues", ())),
                pose_count=value.get("pose_count", 0),
                source_interaction_count=value.get("source_interaction_count", 0),
                metadata=value.get("metadata", {}),
            )
        value = tuple(value.values())
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        return InvolvedResidueCollection(tuple(coerce_involved_residue_spec(item) for item in value))
    return InvolvedResidueCollection((coerce_involved_residue_spec(value),))


def _endpoint_residue(endpoint: InteractionEndpointSpec) -> Optional[ResidueSpec]:
    """Extract a residue from an interaction endpoint."""

    if endpoint.path is not None and endpoint.path.residue_number is not None:
        return ResidueSpec(path=_residue_path(endpoint.path), center=endpoint.point)
    for path in endpoint.selection.paths:
        if path.residue_number is not None:
            return ResidueSpec(path=_residue_path(path), center=endpoint.point)
    return None


def _include_endpoint_role(
    endpoint: InteractionEndpointSpec,
    *,
    include_roles: FrozenSet[MolecularRole],
    include_ligand: bool,
) -> bool:
    """Return whether an endpoint should contribute a residue."""

    role = endpoint.role
    if role is MolecularRole.UNKNOWN and endpoint.path is not None:
        role = endpoint.path.role
    if role is MolecularRole.LIGAND and not include_ligand:
        return False
    return not include_roles or role in include_roles


def _interaction_residue_contribution(interaction: VisualInteractionSpec) -> float:
    """Return one interaction contribution."""

    if interaction.score is not None and math.isfinite(interaction.score):
        return float(interaction.score)
    return _RESIDUE_STRENGTH_WEIGHTS.get(interaction.strength, 0.50)


def build_involved_residue_collection(
    interactions: Any,
    *,
    include_roles: Iterable[Any] = (MolecularRole.RECEPTOR, MolecularRole.UNKNOWN),
    include_ligand: bool = False,
    pose_count: Optional[int] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> InvolvedResidueCollection:
    """Aggregate residues from visual interactions."""

    collection = interactions if isinstance(interactions, VisualInteractionCollection) else build_visual_interactions(interactions)
    roles = frozenset(MolecularRole.parse(role, default=MolecularRole.UNKNOWN) for role in include_roles)
    accumulators: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    observed_poses = {item.pose_id for item in collection.interactions if item.pose_id}
    total_poses = len(observed_poses) if pose_count is None else _bounded_int(
        pose_count, field_name="pose_count", minimum=0, maximum=MAX_VISUAL_ELEMENTS
    )
    for interaction in collection.interactions:
        for endpoint in (interaction.source, interaction.target):
            if not _include_endpoint_role(endpoint, include_roles=roles, include_ligand=include_ligand):
                continue
            residue = _endpoint_residue(endpoint)
            if residue is None:
                continue
            key = residue.key
            item = accumulators.setdefault(key, {
                "residue": residue,
                "families": [],
                "interaction_ids": [],
                "pose_ids": [],
                "score": 0.0,
                "family_counts": Counter(),
            })
            if interaction.family not in item["families"]:
                item["families"].append(interaction.family)
            if interaction.interaction_id not in item["interaction_ids"]:
                item["interaction_ids"].append(interaction.interaction_id)
                item["score"] += _interaction_residue_contribution(interaction)
                item["family_counts"][interaction.family.value] += 1
            if interaction.pose_id and interaction.pose_id not in item["pose_ids"]:
                item["pose_ids"].append(interaction.pose_id)
    residues: List[InvolvedResidueSpec] = []
    ranked = sorted(
        accumulators.values(),
        key=lambda item: (-float(item["score"]), -len(item["interaction_ids"]), _residue_id(item["residue"].path)),
    )
    for rank, item in enumerate(ranked, start=1):
        frequency = len(item["pose_ids"]) / total_poses if total_poses else (1.0 if item["interaction_ids"] else 0.0)
        residues.append(InvolvedResidueSpec(
            residue_id=_residue_id(item["residue"].path),
            residue=item["residue"],
            families=tuple(item["families"]),
            interaction_ids=tuple(item["interaction_ids"]),
            pose_ids=tuple(item["pose_ids"]),
            interaction_count=len(item["interaction_ids"]),
            score=float(item["score"]),
            frequency=frequency,
            rank=rank,
            metadata={"family_counts": dict(item["family_counts"])},
        ))
    return InvolvedResidueCollection(
        residues=tuple(residues),
        pose_count=total_poses,
        source_interaction_count=len(collection.interactions),
        metadata={
            "include_roles": tuple(role.value for role in roles),
            "include_ligand": include_ligand,
            **dict(metadata or {}),
        },
    )


def coerce_involved_residue_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> InvolvedResidueVisualizationSpec:
    """Coerce involved-residue display input."""

    if isinstance(value, InvolvedResidueVisualizationSpec):
        return value
    config_obj = resolve_visualization_config(config_value)
    receptor_style = config_obj.style_for(MolecularRole.RECEPTOR)
    defaults = {
        "representation": MolecularRepresentation.parse(DEFAULT_RECEPTOR_FOCUS_REPRESENTATION),
        "fixed_color": receptor_style.color,
        "stick_radius": receptor_style.stick_radius,
        "enabled": config_obj.scene.show_residues,
        "show_labels": config_obj.labels.enabled and LabelKind.RESIDUE in config_obj.labels.kinds,
        "metadata": {
            "profile": config_obj.profile.value,
            "config_fingerprint": config_obj.fingerprint(),
        },
    }
    if isinstance(value, Mapping) and "collection" in value:
        payload = {**defaults, **dict(value)}
        payload["collection"] = coerce_involved_residue_collection(payload["collection"])
        return InvolvedResidueVisualizationSpec(**payload)
    is_interaction_input = isinstance(value, (VisualInteractionCollection, VisualInteractionSpec))
    if not is_interaction_input and isinstance(value, Sequence) and value:
        first = value[0]
        is_interaction_input = isinstance(first, VisualInteractionSpec) or (
            isinstance(first, Mapping)
            and any(key in first for key in ("interaction_id", "family", "source", "target"))
        )
    collection = (
        build_involved_residue_collection(value)
        if is_interaction_input
        else coerce_involved_residue_collection(value)
    )
    return InvolvedResidueVisualizationSpec(collection=collection, **defaults)


# 15.3. Styling and plans
# -----------------------------------------------------------------------------

def _metric_color(value: float, minimum: float, maximum: float, palette: Sequence[str]) -> str:
    """Map a metric to a palette."""

    colors = tuple(normalize_color(color) for color in palette) or (DEFAULT_MISSING_COLOR,)
    if len(colors) == 1 or maximum - minimum <= _RESIDUE_SCORE_EPSILON:
        return colors[-1]
    position = max(0.0, min(1.0, (value - minimum) / (maximum - minimum)))
    scaled = position * (len(colors) - 1)
    lower = int(math.floor(scaled))
    upper = int(math.ceil(scaled))
    return colors[lower] if lower == upper else blend_colors(colors[lower], colors[upper], scaled - lower)


def residue_visual_color(
    residue: Any,
    *,
    spec: Any,
    palette: Sequence[str] = DEFAULT_SCORE_PALETTE,
) -> str:
    """Resolve one involved-residue color."""

    item = coerce_involved_residue_spec(residue)
    display = coerce_involved_residue_visualization_spec(spec)
    if item.color:
        return item.color
    if display.color_mode is ColorMode.FIXED:
        return display.fixed_color
    if display.color_mode in {ColorMode.INTERACTION, ColorMode.STRENGTH}:
        return item.predominant_family.default_color
    if display.color_mode is ColorMode.CHAIN:
        return _stable_palette_color(item.path.chain_id or "unknown")
    selected = display.selected
    if display.color_mode is ColorMode.FREQUENCY:
        return _metric_color(item.frequency, 0.0, 1.0, palette)
    if display.color_mode is ColorMode.SCORE:
        values = [entry.effective_score for entry in selected] or [item.effective_score]
        return _metric_color(item.effective_score, min(values), max(values), palette)
    return display.fixed_color


def _residue_label(item: InvolvedResidueSpec, template: str) -> str:
    """Format one residue label."""

    values = {
        "label": item.label,
        "residue_id": item.residue_id,
        "name": item.path.residue_name or "",
        "number": item.path.residue_number or "",
        "chain": item.path.chain_id or "",
        "count": item.interaction_count,
        "score": item.effective_score,
        "frequency": item.frequency,
        "family": item.predominant_family.label,
    }
    try:
        return template.format(**values)[:MAX_LABEL_TEXT_LENGTH]
    except (KeyError, ValueError, IndexError) as exc:
        raise VisualizationSpecificationError(
            "Invalid residue label template.", context={"template": template, "cause": str(exc)}
        ) from exc


def build_involved_residue_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert involved residues to plan actions."""

    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    config_obj = resolve_visualization_config(config_value)
    selected = spec.selected
    dependencies = _action_dependencies(depends_on)
    payload = tuple({
        "residue_id": item.residue_id,
        "selection": item.selection.expression,
        "label": item.label,
        "color": residue_visual_color(item, spec=spec, palette=config_obj.scoring.palette),
        "families": tuple(family.value for family in item.families),
        "interaction_count": item.interaction_count,
        "score": item.score,
        "frequency": item.frequency,
        "rank": item.rank,
    } for item in selected)
    actions: List[VisualizationAction] = [VisualizationAction(
        action_id="residues:involved",
        operation=PlanOperation.SHOW_RESIDUES,
        layer=VisualLayer.RECEPTOR_FOCUS,
        selection=spec.selection,
        parameters={
            "component": "involved_residues",
            "display_mode": spec.display_mode.value,
            "representation": spec.representation.value,
            "color_mode": spec.color_mode.value,
            "fixed_color": spec.fixed_color,
            "opacity": spec.opacity,
            "stick_radius": spec.stick_radius,
            "show_sidechains": spec.show_sidechains,
            "show_backbone": spec.show_backbone,
            "residues": payload,
        },
        depends_on=dependencies,
        priority=OperationPriority.HIGH,
        enabled=spec.enabled and bool(selected),
        optional=True,
        description="Render residues involved in ligand interactions.",
        tags=("residues", "involved", "receptor"),
        metadata=spec.metadata,
    )]
    if spec.show_labels and selected:
        actions.append(VisualizationAction(
            action_id="residues:labels",
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=spec.selection,
            parameters={
                "component": "involved_residue_labels",
                "labels": tuple({
                    "selection": item.selection.expression,
                    "text": _residue_label(item, spec.label_template),
                    "residue_id": item.residue_id,
                } for item in selected),
                "label_template": spec.label_template,
            },
            depends_on=("residues:involved",),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Label involved residues.",
            tags=("residues", "labels"),
        ))
    return tuple(actions)


def build_involved_residue_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "involved-residues",
    name: str = "Involved residues",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
) -> VisualizationPlan:
    """Build a standalone involved-residue plan."""

    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_involved_residue_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display receptor residues participating in interactions.",
        metadata={"involved_residues": spec.to_dict(), **dict(metadata or {})},
    )


def attach_involved_residues(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach involved-residue actions to a plan."""

    base = coerce_visualization_plan(plan)
    action_ids = {action.action_id for action in base.actions}
    interaction_dependencies = tuple(
        action.action_id for action in base.actions
        if action.operation is PlanOperation.SHOW_INTERACTIONS and action.enabled
    )
    preferred = ("ligand:base", "receptor:focus", "receptor:base", "scene:prepare")
    fallback = next((action_id for action_id in preferred if action_id in action_ids), None)
    dependencies = interaction_dependencies or ((fallback,) if fallback else ())
    incoming = {action.action_id: action for action in build_involved_residue_actions(
        value,
        config_value=config_value,
        depends_on=dependencies,
    )}
    actions: List[VisualizationAction] = []
    for action in base.actions:
        replacement = incoming.pop(action.action_id, None)
        if replacement is None:
            actions.append(action)
        elif replace_existing:
            actions.append(replacement)
        else:
            raise VisualizationPlanError(f"Residue action already exists: {action.action_id!r}.")
    actions.extend(incoming.values())
    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "involved_residues": spec.to_dict()},
    )


def visualize_involved_residues(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach involved-residue visualization."""

    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    if kwargs:
        spec = replace(spec, **kwargs)
    return (
        build_involved_residue_plan(spec, config_value=config_value)
        if plan is None
        else attach_involved_residues(plan, spec, config_value=config_value)
    )


# 15.4. Validation and serialization
# -----------------------------------------------------------------------------

def validate_involved_residues(value: Any, *, config_value: Any = None) -> Tuple[PlanValidationIssue, ...]:
    """Validate involved-residue display semantics."""

    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.collection.residues:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "involved_residues_empty",
            "No involved residues are available for display.",
            "residues:involved",
        ))
    if len(spec.collection.residues) > spec.max_residues:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "involved_residue_limit_applied",
            "The involved-residue display limit was applied.",
            "residues:involved",
            {"available": len(spec.collection.residues), "displayed": len(spec.selected)},
        ))
    if spec.min_frequency > 0.0 and spec.collection.pose_count == 0:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "involved_residue_frequency_without_poses",
            "Frequency filtering is enabled without a pose count.",
            "residues:involved",
        ))
    if spec.show_labels and not spec.selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "involved_residue_labels_empty",
            "Residue labels are enabled but no residues pass the filters.",
            "residues:labels",
        ))
    return tuple(issues)


def summarize_involved_residues(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Return compact involved-residue statistics."""

    spec = coerce_involved_residue_visualization_spec(value, config_value=config_value)
    selected = spec.selected
    issues = validate_involved_residues(spec, config_value=config_value)
    scores = [item.effective_score for item in selected]
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.residues),
        "displayed_count": len(selected),
        "interaction_count": spec.collection.source_interaction_count,
        "pose_count": spec.collection.pose_count,
        "families": dict(Counter(family.value for item in selected for family in item.families)),
        "chains": dict(Counter(item.path.chain_id or "unassigned" for item in selected)),
        "mean_score": sum(scores) / len(scores) if scores else None,
        "max_score": max(scores) if scores else None,
        "persistent_count": sum(item.frequency >= DEFAULT_PERSISTENCE_FREQUENCY for item in selected),
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def involved_residues_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize involved-residue visualization."""

    return coerce_involved_residue_visualization_spec(value, config_value=config_value).to_dict()


def involved_residues_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize involved-residue visualization as JSON."""

    return json.dumps(
        involved_residues_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


