# =============================================================================
# 16. Hotspots
# =============================================================================

_HOTSPOT_CLUSTER_DISTANCE: Final[float] = 5.0
_HOTSPOT_MIN_RESIDUES: Final[int] = 2
_HOTSPOT_MAX_RESIDUES: Final[int] = 2000
_HOTSPOT_EPSILON: Final[float] = 1.0e-9


def _hotspot_float(value: Any, *, field_name: str, default: float = 0.0) -> float:
    """Normalize one hotspot metric."""

    if value is None:
        return default
    try:
        result = float(value)
    except (TypeError, ValueError) as exc:
        raise VisualizationSpecificationError(
            f"{field_name} must be numeric.", context={"value": value}
        ) from exc
    if not math.isfinite(result):
        raise VisualizationSpecificationError(
            f"{field_name} must be finite.", context={"value": value}
        )
    return result


def _hotspot_center(residue: InvolvedResidueSpec) -> Optional[Point3D]:
    """Return a residue center when available."""

    if residue.residue.center is not None:
        return residue.residue.center
    value = residue.metadata.get("center")
    try:
        return normalize_point3d(value, field_name="center", allow_none=True)
    except VisualizationError:
        return None


def _hotspot_families(values: Iterable[Any]) -> Tuple[InteractionFamily, ...]:
    """Normalize hotspot families."""

    parsed = [InteractionFamily.parse(value, default=InteractionFamily.UNKNOWN) for value in values]
    return tuple(dict.fromkeys(parsed))


def _hotspot_level(value: float) -> HotspotLevel:
    """Map normalized intensity to a level."""

    if value >= 0.75:
        return HotspotLevel.CRITICAL
    if value >= 0.50:
        return HotspotLevel.HIGH
    if value >= 0.25:
        return HotspotLevel.MEDIUM
    return HotspotLevel.LOW


def _hotspot_sequence_number(residue: InvolvedResidueSpec) -> Optional[int]:
    """Return a sortable residue number."""

    match = re.match(r"^[+-]?\d+", residue.path.residue_number or "")
    return int(match.group(0)) if match else None


def _hotspot_components(
    residues: Sequence[InvolvedResidueSpec],
    *,
    distance_cutoff: float,
) -> Tuple[Tuple[int, ...], ...]:
    """Cluster residues by geometry or sequence."""

    size = len(residues)
    parent = list(range(size))

    def find(index: int) -> int:
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left: int, right: int) -> None:
        left_root, right_root = find(left), find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    centers = [_hotspot_center(item) for item in residues]
    sequence_numbers = [_hotspot_sequence_number(item) for item in residues]
    for left in range(size):
        for right in range(left + 1, size):
            left_path, right_path = residues[left].path, residues[right].path
            if left_path.model_id != right_path.model_id:
                continue
            if centers[left] is not None and centers[right] is not None:
                if point_distance(centers[left], centers[right]) <= distance_cutoff:
                    union(left, right)
                continue
            if left_path.chain_id != right_path.chain_id:
                continue
            left_number, right_number = sequence_numbers[left], sequence_numbers[right]
            if left_number is not None and right_number is not None and abs(left_number - right_number) <= 2:
                union(left, right)
    groups: Dict[int, List[int]] = defaultdict(list)
    for index in range(size):
        groups[find(index)].append(index)
    return tuple(tuple(indices) for indices in groups.values())


@dataclass(frozen=True, slots=True)
class HotspotSpec(MolecularSpecMixin):
    """Aggregated receptor hotspot."""

    hotspot_id: str
    residues: Tuple[InvolvedResidueSpec, ...]
    center: Optional[Point3D] = None
    radius: float = DEFAULT_HOTSPOT_RADIUS
    families: Tuple[InteractionFamily, ...] = ()
    interaction_ids: Tuple[str, ...] = ()
    pose_ids: Tuple[str, ...] = ()
    score: float = 0.0
    frequency: float = 0.0
    density: float = 0.0
    intensity: float = 0.0
    level: HotspotLevel = HotspotLevel.LOW
    rank: Optional[int] = None
    color: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        residues = tuple(coerce_involved_residue_spec(value) for value in self.residues)
        if not residues:
            raise VisualizationSpecificationError("A hotspot requires at least one residue.")
        keys = [item.key for item in residues]
        if len(keys) != len(set(keys)):
            raise VisualizationSpecificationError("Hotspot residues must be unique.")
        center = normalize_point3d(self.center, field_name="center", allow_none=True)
        centers = [_hotspot_center(item) for item in residues]
        available = [item for item in centers if item is not None]
        if center is None and available:
            center = centroid(available)
        families = self.families or tuple(
            family for residue in residues for family in residue.families
        )
        interaction_ids = self.interaction_ids or tuple(
            interaction_id for residue in residues for interaction_id in residue.interaction_ids
        )
        pose_ids = self.pose_ids or tuple(
            pose_id for residue in residues for pose_id in residue.pose_ids
        )
        rank = None if self.rank is None else _bounded_int(
            self.rank, field_name="rank", minimum=1, maximum=DEFAULT_HOTSPOT_MAX_COUNT
        )
        object.__setattr__(self, "hotspot_id", _clean_config_name(
            self.hotspot_id, field_name="hotspot_id", maximum=MAX_VISUALIZATION_NAME_LENGTH
        ))
        object.__setattr__(self, "residues", residues)
        object.__setattr__(self, "center", center)
        object.__setattr__(self, "radius", _bounded_float(
            self.radius, field_name="radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS
        ))
        object.__setattr__(self, "families", _hotspot_families(families))
        object.__setattr__(self, "interaction_ids", tuple(dict.fromkeys(map(str, interaction_ids))))
        object.__setattr__(self, "pose_ids", tuple(dict.fromkeys(map(str, pose_ids))))
        object.__setattr__(self, "score", _hotspot_float(self.score, field_name="score"))
        object.__setattr__(self, "frequency", _bounded_float(
            self.frequency, field_name="frequency", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "density", _hotspot_float(
            self.density, field_name="density"
        ))
        object.__setattr__(self, "intensity", _bounded_float(
            self.intensity, field_name="intensity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "level", HotspotLevel.parse(
            self.level, default=HotspotLevel.LOW
        ))
        object.__setattr__(self, "rank", rank)
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.residues))

    @property
    def residue_ids(self) -> Tuple[str, ...]:
        return tuple(item.residue_id for item in self.residues)

    @property
    def residue_count(self) -> int:
        return len(self.residues)

    @property
    def interaction_count(self) -> int:
        return len(self.interaction_ids)

    @property
    def predominant_family(self) -> InteractionFamily:
        counts = Counter(
            family for residue in self.residues for family in residue.families
        )
        return counts.most_common(1)[0][0] if counts else InteractionFamily.UNKNOWN

    @property
    def label(self) -> str:
        return f"Hotspot {self.rank or self.hotspot_id}"


@dataclass(frozen=True, slots=True)
class HotspotCollection(MolecularSpecMixin):
    """Validated hotspot collection."""

    hotspots: Tuple[HotspotSpec, ...] = ()
    pose_count: int = 0
    source_residue_count: int = 0
    source_interaction_count: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        hotspots = tuple(coerce_hotspot_spec(value) for value in self.hotspots)
        identifiers = [item.hotspot_id for item in hotspots]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Hotspot identifiers must be unique.", context={"duplicates": duplicates}
            )
        if len(hotspots) > DEFAULT_HOTSPOT_MAX_COUNT:
            raise VisualizationLimitError(
                f"Hotspot collections cannot exceed {DEFAULT_HOTSPOT_MAX_COUNT} entries."
            )
        object.__setattr__(self, "hotspots", hotspots)
        object.__setattr__(self, "pose_count", _bounded_int(
            self.pose_count, field_name="pose_count", minimum=0, maximum=MAX_VISUAL_ELEMENTS
        ))
        object.__setattr__(self, "source_residue_count", _bounded_int(
            self.source_residue_count,
            field_name="source_residue_count",
            minimum=0,
            maximum=_HOTSPOT_MAX_RESIDUES,
        ))
        object.__setattr__(self, "source_interaction_count", _bounded_int(
            self.source_interaction_count,
            field_name="source_interaction_count",
            minimum=0,
            maximum=MAX_VISUAL_ELEMENTS,
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def __len__(self) -> int:
        return len(self.hotspots)

    def __iter__(self) -> Iterator[HotspotSpec]:
        return iter(self.hotspots)

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.hotspots)) if self.hotspots else MolecularSelection.none()

    @property
    def level_counts(self) -> Mapping[str, int]:
        return MappingProxyType(dict(Counter(item.level.value for item in self.hotspots)))

    def top(self, limit: int = 10) -> Tuple[HotspotSpec, ...]:
        count = _bounded_int(limit, field_name="limit", minimum=0, maximum=DEFAULT_HOTSPOT_MAX_COUNT)
        return tuple(sorted(
            self.hotspots,
            key=lambda item: (
                item.rank if item.rank is not None else MAX_VISUAL_ELEMENTS,
                -item.intensity,
                -item.score,
                item.hotspot_id,
            ),
        )[:count])

    def for_level(self, level: Any) -> Tuple[HotspotSpec, ...]:
        parsed = HotspotLevel.parse(level, default=HotspotLevel.LOW)
        return tuple(item for item in self.hotspots if item.level is parsed)

    def for_pose(self, pose_id: Any) -> Tuple[HotspotSpec, ...]:
        text = str(pose_id).strip()
        return tuple(item for item in self.hotspots if text in item.pose_ids)


@dataclass(frozen=True, slots=True)
class HotspotVisualizationSpec(MolecularSpecMixin):
    """Hotspot display settings."""

    collection: HotspotCollection = field(default_factory=HotspotCollection)
    render_mode: HotspotRenderMode = HotspotRenderMode.COMBINED
    color_mode: ColorMode = ColorMode.FREQUENCY
    fixed_color: str = DEFAULT_HOTSPOT_COLOR
    opacity: float = DEFAULT_HOTSPOT_OPACITY
    radius_scale: float = 1.0
    min_frequency: float = DEFAULT_HOTSPOT_MIN_FREQUENCY
    min_score: Optional[float] = None
    min_residues: int = _HOTSPOT_MIN_RESIDUES
    max_hotspots: int = DEFAULT_HOTSPOT_MAX_COUNT
    show_labels: bool = False
    label_template: str = "{label}"
    enabled: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        template = str(self.label_template or "{label}").strip()
        if len(template) > MAX_LABEL_TEXT_LENGTH:
            raise VisualizationSpecificationError("Hotspot label template is too long.")
        object.__setattr__(self, "collection", coerce_hotspot_collection(self.collection))
        object.__setattr__(self, "render_mode", HotspotRenderMode.parse(
            self.render_mode, default=HotspotRenderMode.COMBINED
        ))
        object.__setattr__(self, "color_mode", ColorMode.parse(
            self.color_mode, default=ColorMode.FREQUENCY
        ))
        object.__setattr__(self, "fixed_color", normalize_color(self.fixed_color))
        object.__setattr__(self, "opacity", _bounded_float(
            self.opacity, field_name="opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "radius_scale", _bounded_float(
            self.radius_scale, field_name="radius_scale", minimum=0.01, maximum=10.0
        ))
        object.__setattr__(self, "min_frequency", _bounded_float(
            self.min_frequency, field_name="min_frequency", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "min_score", None if self.min_score is None else _hotspot_float(
            self.min_score, field_name="min_score"
        ))
        object.__setattr__(self, "min_residues", _bounded_int(
            self.min_residues, field_name="min_residues", minimum=1, maximum=_HOTSPOT_MAX_RESIDUES
        ))
        object.__setattr__(self, "max_hotspots", _bounded_int(
            self.max_hotspots,
            field_name="max_hotspots",
            minimum=1,
            maximum=DEFAULT_HOTSPOT_MAX_COUNT,
        ))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "label_template", template)
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[HotspotSpec, ...]:
        values = [
            item for item in self.collection.hotspots
            if item.frequency + _HOTSPOT_EPSILON >= self.min_frequency
            and item.residue_count >= self.min_residues
            and (self.min_score is None or item.score + _HOTSPOT_EPSILON >= self.min_score)
        ]
        values.sort(key=lambda item: (
            item.rank if item.rank is not None else MAX_VISUAL_ELEMENTS,
            -item.intensity,
            -item.score,
            item.hotspot_id,
        ))
        return tuple(values[:self.max_hotspots])

    @property
    def selection(self) -> MolecularSelection:
        selected = self.selected
        return selection_union(*(item.selection for item in selected)) if selected else MolecularSelection.none()


# 16.2. Coercion and clustering
# -----------------------------------------------------------------------------

def coerce_hotspot_spec(value: Any, *, index: int = 0) -> HotspotSpec:
    """Coerce one hotspot specification."""

    if isinstance(value, HotspotSpec):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("hotspot_id", f"hotspot-{index + 1}")
        return HotspotSpec(**data)
    residues = getattr(value, "residues", None)
    if residues is not None:
        return HotspotSpec(
            hotspot_id=getattr(value, "hotspot_id", getattr(value, "id", f"hotspot-{index + 1}")),
            residues=tuple(residues),
            center=getattr(value, "center", None),
            radius=getattr(value, "radius", DEFAULT_HOTSPOT_RADIUS),
            score=getattr(value, "score", 0.0),
            frequency=getattr(value, "frequency", 0.0),
            level=getattr(value, "level", HotspotLevel.LOW),
            metadata=getattr(value, "metadata", {}),
        )
    raise VisualizationSpecificationError(
        "Cannot coerce hotspot specification.", context={"type": type(value).__name__}
    )


def coerce_hotspot_collection(value: Any) -> HotspotCollection:
    """Coerce a hotspot collection."""

    if isinstance(value, HotspotCollection):
        return value
    if value is None:
        return HotspotCollection()
    if isinstance(value, Mapping):
        return HotspotCollection(**dict(value))
    if isinstance(value, HotspotSpec):
        return HotspotCollection(hotspots=(value,), source_residue_count=value.residue_count)
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        hotspots = tuple(coerce_hotspot_spec(item, index=index) for index, item in enumerate(value))
        return HotspotCollection(
            hotspots=hotspots,
            source_residue_count=len({residue.key for item in hotspots for residue in item.residues}),
            source_interaction_count=len({identifier for item in hotspots for identifier in item.interaction_ids}),
        )
    raise VisualizationSpecificationError(
        "Cannot coerce hotspot collection.", context={"type": type(value).__name__}
    )


def _coerce_hotspot_residues(value: Any, *, pose_count: Optional[int] = None) -> InvolvedResidueCollection:
    """Resolve involved residues for hotspot clustering."""

    if isinstance(value, InvolvedResidueCollection):
        return value
    if isinstance(value, InvolvedResidueVisualizationSpec):
        return value.collection
    if isinstance(value, Mapping) and "residues" in value:
        try:
            return coerce_involved_residue_collection(value)
        except VisualizationError:
            pass
    return build_involved_residue_collection(value, pose_count=pose_count)


def build_hotspot_collection(
    value: Any,
    *,
    distance_cutoff: float = _HOTSPOT_CLUSTER_DISTANCE,
    min_residues: int = _HOTSPOT_MIN_RESIDUES,
    allow_singletons: bool = False,
    pose_count: Optional[int] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> HotspotCollection:
    """Cluster involved residues into hotspots."""

    if isinstance(value, HotspotCollection):
        return value
    residues = _coerce_hotspot_residues(value, pose_count=pose_count)
    cutoff = _bounded_float(
        distance_cutoff, field_name="distance_cutoff", minimum=0.1, maximum=100.0
    )
    minimum = _bounded_int(
        min_residues, field_name="min_residues", minimum=1, maximum=_HOTSPOT_MAX_RESIDUES
    )
    ordered = tuple(residues.residues[:_HOTSPOT_MAX_RESIDUES])
    components = _hotspot_components(ordered, distance_cutoff=cutoff)
    raw: List[HotspotSpec] = []
    for indices in components:
        members = tuple(ordered[index] for index in indices)
        if len(members) < minimum and not allow_singletons:
            continue
        centers = [center for center in (_hotspot_center(item) for item in members) if center is not None]
        center = centroid(centers) if centers else None
        radius = DEFAULT_HOTSPOT_RADIUS
        if center is not None and centers:
            radius = min(MAX_RADIUS, max(DEFAULT_HOTSPOT_RADIUS, max(point_distance(center, item) for item in centers) + 1.0))
        interaction_ids = tuple(dict.fromkeys(
            identifier for item in members for identifier in item.interaction_ids
        ))
        pose_ids = tuple(dict.fromkeys(
            pose_id for item in members for pose_id in item.pose_ids
        ))
        total_poses = residues.pose_count
        frequency = len(pose_ids) / total_poses if total_poses else max(
            (item.frequency for item in members), default=0.0
        )
        score = sum(item.effective_score for item in members)
        density = len(interaction_ids) / max(len(members), 1)
        raw.append(HotspotSpec(
            hotspot_id=f"hotspot-{len(raw) + 1}",
            residues=members,
            center=center,
            radius=radius,
            interaction_ids=interaction_ids,
            pose_ids=pose_ids,
            score=score,
            frequency=min(1.0, frequency),
            density=density,
            metadata={"distance_cutoff": cutoff},
        ))
    max_score = max((max(item.score, 0.0) for item in raw), default=0.0)
    max_density = max((max(item.density, 0.0) for item in raw), default=0.0)
    ranked: List[HotspotSpec] = []
    scored: List[Tuple[float, HotspotSpec]] = []
    for item in raw:
        score_norm = max(item.score, 0.0) / max_score if max_score > _HOTSPOT_EPSILON else 0.0
        density_norm = max(item.density, 0.0) / max_density if max_density > _HOTSPOT_EPSILON else 0.0
        intensity = min(1.0, 0.45 * item.frequency + 0.35 * score_norm + 0.20 * density_norm)
        scored.append((intensity, replace(item, intensity=intensity, level=_hotspot_level(intensity))))
    scored.sort(key=lambda pair: (-pair[0], -pair[1].score, -pair[1].residue_count, pair[1].hotspot_id))
    for rank, (_, item) in enumerate(scored, start=1):
        ranked.append(replace(item, rank=rank, hotspot_id=f"hotspot-{rank}"))
    return HotspotCollection(
        hotspots=tuple(ranked),
        pose_count=residues.pose_count,
        source_residue_count=len(residues.residues),
        source_interaction_count=residues.source_interaction_count,
        metadata={"distance_cutoff": cutoff, "min_residues": minimum, **dict(metadata or {})},
    )


def coerce_hotspot_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> HotspotVisualizationSpec:
    """Coerce hotspot display settings."""

    config_obj = resolve_visualization_config(config_value)
    defaults = config_obj.hotspots
    base = {
        "render_mode": defaults.render_mode,
        "fixed_color": defaults.color_for(HotspotLevel.MEDIUM),
        "opacity": defaults.opacity,
        "min_frequency": defaults.min_frequency,
        "max_hotspots": max(1, defaults.max_count),
        "show_labels": defaults.show_labels,
        "enabled": defaults.enabled,
    }
    if isinstance(value, HotspotVisualizationSpec):
        return value
    if isinstance(value, Mapping) and "collection" in value:
        return HotspotVisualizationSpec(**{**base, **dict(value)})
    if isinstance(value, HotspotCollection):
        return HotspotVisualizationSpec(collection=value, **base)
    try:
        collection = coerce_hotspot_collection(value)
    except VisualizationError:
        collection = build_hotspot_collection(value)
    return HotspotVisualizationSpec(collection=collection, **base)


# 16.3. Visual planning
# -----------------------------------------------------------------------------

def hotspot_visual_color(
    hotspot: Any,
    *,
    spec: Any,
    config_value: Any = None,
) -> str:
    """Resolve one hotspot color."""

    item = coerce_hotspot_spec(hotspot)
    display = coerce_hotspot_visualization_spec(spec, config_value=config_value)
    config_obj = resolve_visualization_config(config_value)
    if item.color:
        return item.color
    if display.color_mode is ColorMode.FIXED:
        return display.fixed_color
    if display.color_mode in {ColorMode.INTERACTION, ColorMode.STRENGTH}:
        return item.predominant_family.default_color
    if display.color_mode is ColorMode.CLUSTER:
        return _stable_palette_color(item.hotspot_id)
    if display.color_mode is ColorMode.SCORE:
        values = [entry.score for entry in display.selected] or [item.score]
        return _metric_color(item.score, min(values), max(values), config_obj.scoring.palette)
    if display.color_mode is ColorMode.FREQUENCY:
        return _metric_color(item.frequency, 0.0, 1.0, config_obj.scoring.palette)
    return config_obj.hotspots.color_for(item.level)


def _hotspot_label(item: HotspotSpec, template: str) -> str:
    """Format one hotspot label."""

    values = {
        "label": item.label,
        "hotspot_id": item.hotspot_id,
        "rank": item.rank or "",
        "level": item.level.value,
        "residue_count": item.residue_count,
        "interaction_count": item.interaction_count,
        "score": item.score,
        "frequency": item.frequency,
        "family": item.predominant_family.label,
    }
    try:
        return template.format(**values)[:MAX_LABEL_TEXT_LENGTH]
    except (KeyError, ValueError, IndexError) as exc:
        raise VisualizationSpecificationError(
            "Invalid hotspot label template.", context={"template": template, "cause": str(exc)}
        ) from exc


def _hotspot_payload(
    spec: HotspotVisualizationSpec,
    *,
    config_value: Any = None,
) -> Tuple[Dict[str, Any], ...]:
    """Build hotspot action payload."""

    return tuple({
        "hotspot_id": item.hotspot_id,
        "rank": item.rank,
        "level": item.level.value,
        "center": item.center,
        "radius": min(MAX_RADIUS, item.radius * spec.radius_scale),
        "selection": item.selection.expression,
        "residue_ids": item.residue_ids,
        "interaction_ids": item.interaction_ids,
        "pose_ids": item.pose_ids,
        "families": tuple(family.value for family in item.families),
        "predominant_family": item.predominant_family.value,
        "residue_count": item.residue_count,
        "interaction_count": item.interaction_count,
        "score": item.score,
        "frequency": item.frequency,
        "density": item.density,
        "intensity": item.intensity,
        "color": hotspot_visual_color(item, spec=spec, config_value=config_value),
    } for item in spec.selected)


def build_hotspot_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert hotspots to plan actions."""

    spec = coerce_hotspot_visualization_spec(value, config_value=config_value)
    selected = spec.selected
    dependencies = _action_dependencies(depends_on)
    payload = _hotspot_payload(spec, config_value=config_value)
    actions: List[VisualizationAction] = []
    mode = spec.render_mode
    if mode in {HotspotRenderMode.RESIDUES, HotspotRenderMode.COMBINED}:
        actions.append(VisualizationAction(
            action_id="hotspots:residues",
            operation=PlanOperation.SHOW_HOTSPOTS,
            layer=VisualLayer.HOTSPOTS,
            selection=spec.selection,
            parameters={
                "component": "hotspots",
                "render_mode": "residues",
                "color_mode": spec.color_mode.value,
                "opacity": spec.opacity,
                "hotspots": payload,
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH,
            enabled=spec.enabled and bool(selected),
            optional=True,
            tags=("hotspots", "residues"),
        ))
    if mode in {HotspotRenderMode.MARKERS, HotspotRenderMode.SPHERES, HotspotRenderMode.COMBINED}:
        marker_payload = tuple(item for item in payload if item["center"] is not None)
        marker_dependencies = tuple(action.action_id for action in actions) or dependencies
        actions.append(VisualizationAction(
            action_id="hotspots:markers",
            operation=PlanOperation.SHOW_HOTSPOTS,
            layer=VisualLayer.HOTSPOTS,
            parameters={
                "component": "hotspots",
                "render_mode": "spheres" if mode is HotspotRenderMode.SPHERES else "markers",
                "opacity": spec.opacity,
                "hotspots": marker_payload,
            },
            depends_on=marker_dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled and bool(marker_payload),
            optional=True,
            tags=("hotspots", "markers"),
        ))
    if mode in {HotspotRenderMode.SURFACE, HotspotRenderMode.COMBINED}:
        surface_dependencies = tuple(action.action_id for action in actions) or dependencies
        actions.append(VisualizationAction(
            action_id="hotspots:surface",
            operation=PlanOperation.SHOW_HOTSPOTS,
            layer=VisualLayer.HOTSPOTS,
            selection=spec.selection,
            parameters={
                "component": "hotspots",
                "render_mode": "surface",
                "color_mode": spec.color_mode.value,
                "opacity": spec.opacity,
                "hotspots": payload,
            },
            depends_on=surface_dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled and bool(selected),
            optional=True,
            tags=("hotspots", "surface"),
        ))
    if spec.show_labels:
        label_dependencies = tuple(action.action_id for action in actions) or dependencies
        labels = tuple({
            "hotspot_id": item.hotspot_id,
            "center": item.center,
            "selection": item.selection.expression,
            "text": _hotspot_label(item, spec.label_template),
            "color": hotspot_visual_color(item, spec=spec, config_value=config_value),
        } for item in selected)
        actions.append(VisualizationAction(
            action_id="hotspots:labels",
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=spec.selection,
            parameters={"component": "hotspots", "labels": labels},
            depends_on=label_dependencies,
            priority=OperationPriority.LOW,
            enabled=spec.enabled and bool(labels),
            optional=True,
            tags=("hotspots", "labels"),
        ))
    return tuple(actions)


def build_hotspot_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "hotspot-visualization",
    name: str = "Hotspot visualization",
) -> VisualizationPlan:
    """Build a standalone hotspot plan."""

    config_obj = resolve_visualization_config(config_value)
    spec = coerce_hotspot_visualization_spec(value, config_value=config_obj)
    return build_visualization_plan(
        build_hotspot_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        description="Visualize receptor hotspots.",
        metadata={"hotspots": spec.to_dict()},
    )


def attach_hotspots(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach hotspot actions to a plan."""

    base = coerce_visualization_plan(plan)
    action_ids = {action.action_id for action in base.actions}
    preferred_prefixes = ("residues:", "interactions:")
    dependencies = tuple(
        action.action_id for action in base.actions
        if action.enabled and action.action_id.startswith(preferred_prefixes)
    )
    if not dependencies:
        fallback = next((
            action_id for action_id in ("ligand:base", "receptor:focus", "receptor:base", "scene:prepare")
            if action_id in action_ids
        ), None)
        dependencies = (fallback,) if fallback else ()
    incoming = {action.action_id: action for action in build_hotspot_actions(
        value, config_value=config_value, depends_on=dependencies
    )}
    actions: List[VisualizationAction] = []
    for action in base.actions:
        replacement = incoming.pop(action.action_id, None)
        if replacement is None:
            actions.append(action)
        elif replace_existing:
            actions.append(replacement)
        else:
            raise VisualizationPlanError(f"Hotspot action already exists: {action.action_id!r}.")
    actions.extend(incoming.values())
    spec = coerce_hotspot_visualization_spec(value, config_value=config_value)
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "hotspots": spec.to_dict()},
    )


def visualize_hotspots(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach hotspot visualization."""

    spec = coerce_hotspot_visualization_spec(value, config_value=config_value)
    if kwargs:
        spec = replace(spec, **kwargs)
    return (
        build_hotspot_plan(spec, config_value=config_value)
        if plan is None
        else attach_hotspots(plan, spec, config_value=config_value)
    )


# 16.4. Validation and serialization
# -----------------------------------------------------------------------------

def validate_hotspots(value: Any, *, config_value: Any = None) -> Tuple[PlanValidationIssue, ...]:
    """Validate hotspot display semantics."""

    spec = coerce_hotspot_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.collection.hotspots:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "hotspots_empty",
            "No hotspots are available for display.",
            "hotspots",
        ))
    if len(spec.collection.hotspots) > spec.max_hotspots:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "hotspot_limit_applied",
            "The hotspot display limit was applied.",
            "hotspots",
            {"available": len(spec.collection.hotspots), "displayed": len(spec.selected)},
        ))
    if spec.min_frequency > 0.0 and spec.collection.pose_count == 0:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "hotspot_frequency_without_poses",
            "Frequency filtering is enabled without a pose count.",
            "hotspots",
        ))
    missing_centers = sum(item.center is None for item in spec.selected)
    if missing_centers and spec.render_mode in {
        HotspotRenderMode.MARKERS, HotspotRenderMode.SPHERES, HotspotRenderMode.COMBINED
    }:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "hotspot_centers_missing",
            "Some hotspots cannot be rendered as spatial markers.",
            "hotspots:markers",
            {"count": missing_centers},
        ))
    if spec.show_labels and not spec.selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "hotspot_labels_empty",
            "Hotspot labels are enabled but no hotspots pass the filters.",
            "hotspots:labels",
        ))
    return tuple(issues)


def summarize_hotspots(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Return compact hotspot statistics."""

    spec = coerce_hotspot_visualization_spec(value, config_value=config_value)
    selected = spec.selected
    issues = validate_hotspots(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.hotspots),
        "displayed_count": len(selected),
        "source_residue_count": spec.collection.source_residue_count,
        "source_interaction_count": spec.collection.source_interaction_count,
        "pose_count": spec.collection.pose_count,
        "levels": dict(Counter(item.level.value for item in selected)),
        "families": dict(Counter(item.predominant_family.value for item in selected)),
        "mean_score": sum(item.score for item in selected) / len(selected) if selected else None,
        "max_score": max((item.score for item in selected), default=None),
        "mean_frequency": sum(item.frequency for item in selected) / len(selected) if selected else None,
        "persistent_count": sum(item.frequency >= DEFAULT_PERSISTENCE_FREQUENCY for item in selected),
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def hotspots_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize hotspot visualization."""

    return coerce_hotspot_visualization_spec(value, config_value=config_value).to_dict()


def hotspots_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize hotspot visualization as JSON."""

    return json.dumps(
        hotspots_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


