# 17.1. Constants and helpers
# -----------------------------------------------------------------------------

_SCORE_RADIUS_MIN: Final[float] = 0.08
_SCORE_RADIUS_MAX: Final[float] = 0.32
_SCORE_OPACITY_MIN: Final[float] = 0.35
_SCORE_OPACITY_MAX: Final[float] = 1.0
_SCORE_LABEL_TEMPLATE: Final[str] = "{label}: {score:.3f}"
_SCORE_GROUP_NAME: Final[str] = "DockAnalyzer scores"
_SCORE_MAX_ITEMS: Final[int] = MAX_VISUAL_ELEMENTS
_SCORE_TARGET_LAYERS: Final[Mapping[ScoreTarget, VisualLayer]] = MappingProxyType({
    ScoreTarget.INTERACTION: VisualLayer.INTERACTIONS,
    ScoreTarget.RESIDUE: VisualLayer.RECEPTOR_FOCUS,
    ScoreTarget.POSE: VisualLayer.LIGAND,
    ScoreTarget.HOTSPOT: VisualLayer.HOTSPOTS,
    ScoreTarget.MODEL: VisualLayer.RECEPTOR,
})
_SCORE_TARGET_PREFIXES: Final[Mapping[ScoreTarget, Tuple[str, ...]]] = MappingProxyType({
    ScoreTarget.INTERACTION: ("interactions:",),
    ScoreTarget.RESIDUE: ("residues:", "receptor:"),
    ScoreTarget.POSE: ("ligand:",),
    ScoreTarget.HOTSPOT: ("hotspots:",),
    ScoreTarget.MODEL: ("receptor:",),
})


def _score_float(value: Any, *, field_name: str = "score", allow_none: bool = True) -> Optional[float]:
    """Normalize a finite score."""

    if value is None or (isinstance(value, str) and not value.strip()):
        if allow_none:
            return None
        raise VisualizationSpecificationError(f"{field_name} is required.")
    if isinstance(value, bool):
        raise VisualizationSpecificationError(f"{field_name} must be numeric.")
    try:
        result = float(value)
    except (TypeError, ValueError) as exc:
        raise VisualizationSpecificationError(f"{field_name} must be numeric.", cause=exc) from exc
    if not math.isfinite(result):
        raise VisualizationSpecificationError(f"{field_name} must be finite.")
    return result


def _score_values(values: Iterable[Any]) -> Tuple[Optional[float], ...]:
    return tuple(_score_float(value) for value in values)


def _score_quantile(values: Sequence[float], fraction: float) -> float:
    ordered = sorted(values)
    if not ordered:
        return 0.0
    position = max(0.0, min(1.0, fraction)) * (len(ordered) - 1)
    lower, upper = int(math.floor(position)), int(math.ceil(position))
    if lower == upper:
        return ordered[lower]
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)


def _score_statistics(values: Sequence[float]) -> Dict[str, Optional[float]]:
    if not values:
        return {key: None for key in ("minimum", "maximum", "mean", "median", "q1", "q3", "std")}
    mean_value = sum(values) / len(values)
    variance = sum((value - mean_value) ** 2 for value in values) / len(values)
    return {
        "minimum": min(values),
        "maximum": max(values),
        "mean": mean_value,
        "median": _score_quantile(values, 0.5),
        "q1": _score_quantile(values, 0.25),
        "q3": _score_quantile(values, 0.75),
        "std": math.sqrt(variance),
    }


def _score_rank_positions(values: Sequence[float]) -> Tuple[float, ...]:
    if len(values) <= 1:
        return tuple(0.5 for _ in values)
    indexed = sorted(enumerate(values), key=lambda item: (item[1], item[0]))
    result = [0.0] * len(values)
    start = 0
    while start < len(indexed):
        end = start + 1
        while end < len(indexed) and indexed[end][1] == indexed[start][1]:
            end += 1
        average_rank = (start + end - 1) / 2.0
        position = average_rank / (len(indexed) - 1)
        for offset in range(start, end):
            result[indexed[offset][0]] = position
        start = end
    return tuple(result)


def normalize_visual_scores(
    values: Iterable[Any],
    *,
    method: Any = ScoreNormalization.SYMMETRIC,
    minimum: Optional[float] = None,
    center: Optional[float] = None,
    maximum: Optional[float] = None,
    clamp: bool = True,
) -> Tuple[Optional[float], ...]:
    """Normalize scores to zero-to-one positions."""

    parsed = ScoreNormalization.parse(method, default=ScoreNormalization.SYMMETRIC)
    raw = _score_values(values)
    valid = [value for value in raw if value is not None]
    if not valid:
        return tuple(None for _ in raw)
    result_map: Dict[int, float] = {}
    valid_indices = [index for index, value in enumerate(raw) if value is not None]
    if parsed is ScoreNormalization.RANK:
        positions = _score_rank_positions(valid)
    elif parsed in {ScoreNormalization.Z_SCORE, ScoreNormalization.ROBUST}:
        if parsed is ScoreNormalization.Z_SCORE:
            location = sum(valid) / len(valid)
            scale = math.sqrt(sum((value - location) ** 2 for value in valid) / len(valid))
        else:
            location = _score_quantile(valid, 0.5)
            deviations = [abs(value - location) for value in valid]
            scale = 1.4826 * _score_quantile(deviations, 0.5)
        if scale <= VISUALIZATION_SCORE_EPSILON:
            positions = tuple(0.5 for _ in valid)
        else:
            positions = tuple(0.5 * (1.0 + math.erf(((value - location) / scale) / math.sqrt(2.0))) for value in valid)
    elif parsed is ScoreNormalization.MIN_MAX:
        lower = min(valid) if minimum is None else _score_float(minimum, field_name="minimum", allow_none=False)
        upper = max(valid) if maximum is None else _score_float(maximum, field_name="maximum", allow_none=False)
        span = max(upper - lower, VISUALIZATION_SCORE_EPSILON)
        positions = tuple((value - lower) / span for value in valid)
    else:
        pivot = 0.0 if center is None else _score_float(center, field_name="center", allow_none=False)
        if parsed is ScoreNormalization.SYMMETRIC:
            span = max(
                [abs(value - pivot) for value in valid]
                + ([] if minimum is None else [abs(float(minimum) - pivot)])
                + ([] if maximum is None else [abs(float(maximum) - pivot)])
                + [VISUALIZATION_SCORE_EPSILON]
            )
            positions = tuple(0.5 + 0.5 * (value - pivot) / span for value in valid)
        else:
            lower = min(valid) if minimum is None else _score_float(minimum, field_name="minimum", allow_none=False)
            upper = max(valid) if maximum is None else _score_float(maximum, field_name="maximum", allow_none=False)
            span = max(upper - lower, VISUALIZATION_SCORE_EPSILON)
            positions = tuple((value - lower) / span for value in valid)
    for index, position in zip(valid_indices, positions):
        result_map[index] = max(0.0, min(1.0, position)) if clamp else position
    return tuple(result_map.get(index) for index in range(len(raw)))


def _score_palette_color(position: Optional[float], palette: Sequence[Any], missing_color: Any) -> str:
    colors = tuple(normalize_color(value) for value in palette)
    if position is None or not colors:
        return normalize_color(missing_color)
    if len(colors) == 1:
        return colors[0]
    scaled = max(0.0, min(1.0, position)) * (len(colors) - 1)
    lower, upper = int(math.floor(scaled)), int(math.ceil(scaled))
    if lower == upper:
        return colors[lower]
    return blend_colors(colors[lower], colors[upper], scaled - lower)


def _score_scaled(position: Optional[float], minimum: float, maximum: float, fallback: float) -> float:
    return fallback if position is None else minimum + (maximum - minimum) * max(0.0, min(1.0, position))


def _score_selection(value: Any, target: ScoreTarget) -> MolecularSelection:
    if isinstance(value, VisualInteractionSpec):
        selections = tuple(item for item in value.selections if not item.is_none)
        return selection_union(*selections) if selections else MolecularSelection.none()
    if isinstance(value, InvolvedResidueSpec):
        return value.selection
    if isinstance(value, HotspotSpec):
        return value.selection
    if isinstance(value, PoseSpec):
        return pose_spec_to_selection(value)
    if isinstance(value, ModelSpec):
        return model_spec_to_selection(value)
    explicit = _object_value(value, "selection", "atomspec", "atom_spec")
    if explicit is not None:
        return coerce_selection(explicit, strict=False)
    if target is ScoreTarget.POSE:
        try:
            return pose_spec_to_selection(value)
        except VisualizationError:
            return MolecularSelection.none()
    return MolecularSelection.none()


def _score_identifier(value: Any, target: ScoreTarget, index: int) -> str:
    fields_by_target = {
        ScoreTarget.INTERACTION: ("interaction_id", "id", "identifier", "name"),
        ScoreTarget.RESIDUE: ("residue_id", "id", "identifier", "label"),
        ScoreTarget.POSE: ("pose_id", "id", "identifier", "name"),
        ScoreTarget.HOTSPOT: ("hotspot_id", "id", "identifier", "name"),
        ScoreTarget.MODEL: ("model_id", "id", "identifier", "name"),
    }
    raw = _object_value(value, *fields_by_target[target])
    return _clean_config_name(
        str(raw or f"{target.value}_{index + 1}"),
        field_name="item_id",
        maximum=MAX_VISUALIZATION_NAME_LENGTH,
    )


def _score_label(value: Any, item_id: str) -> str:
    raw = _object_value(value, "label", "name", "title")
    return str(raw).strip() if raw not in (None, "") else item_id


def _score_target(value: Any, default: Any = None) -> ScoreTarget:
    explicit = _object_value(value, "target", "score_target", "object_type", "kind")
    parsed = ScoreTarget.parse(explicit, strict=False)
    if parsed is not None:
        return parsed
    if isinstance(value, VisualInteractionSpec):
        return ScoreTarget.INTERACTION
    if isinstance(value, InvolvedResidueSpec):
        return ScoreTarget.RESIDUE
    if isinstance(value, PoseSpec):
        return ScoreTarget.POSE
    if isinstance(value, HotspotSpec):
        return ScoreTarget.HOTSPOT
    if isinstance(value, ModelSpec):
        return ScoreTarget.MODEL
    return ScoreTarget.parse(default, default=ScoreTarget.RESIDUE)


# 17.2. Score specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class VisualScoreItem(MolecularSpecMixin):
    """One scored visual object."""

    item_id: str
    target: ScoreTarget
    score: Optional[float]
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    normalized_score: Optional[float] = None
    color: Optional[str] = None
    radius: Optional[float] = None
    opacity: Optional[float] = None
    rank: Optional[int] = None
    label: Optional[str] = None
    pose_id: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        normalized = _score_float(self.normalized_score, field_name="normalized_score")
        if normalized is not None and not 0.0 <= normalized <= 1.0:
            raise VisualizationSpecificationError("normalized_score must be between zero and one.")
        radius = _score_float(self.radius, field_name="radius")
        opacity = _score_float(self.opacity, field_name="opacity")
        if radius is not None and not MIN_RADIUS <= radius <= MAX_RADIUS:
            raise VisualizationSpecificationError("radius is outside the supported range.")
        if opacity is not None and not 0.0 <= opacity <= 1.0:
            raise VisualizationSpecificationError("opacity must be between zero and one.")
        rank = None if self.rank is None else _bounded_int(
            self.rank, field_name="rank", minimum=1, maximum=_SCORE_MAX_ITEMS
        )
        object.__setattr__(self, "item_id", _clean_config_name(
            self.item_id, field_name="item_id", maximum=MAX_VISUALIZATION_NAME_LENGTH
        ))
        object.__setattr__(self, "target", ScoreTarget.parse(self.target, default=ScoreTarget.RESIDUE))
        object.__setattr__(self, "score", _score_float(self.score))
        object.__setattr__(self, "selection", coerce_selection(self.selection, strict=False))
        object.__setattr__(self, "normalized_score", normalized)
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "radius", radius)
        object.__setattr__(self, "opacity", opacity)
        object.__setattr__(self, "rank", rank)
        object.__setattr__(self, "label", _interaction_text(self.label, field_name="label"))
        object.__setattr__(self, "pose_id", _interaction_text(self.pose_id, field_name="pose_id"))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def key(self) -> Tuple[str, str]:
        return self.target.value, self.item_id

    @property
    def missing(self) -> bool:
        return self.score is None


@dataclass(frozen=True, slots=True)
class VisualScoreCollection(MolecularSpecMixin):
    """Normalized score collection."""

    items: Tuple[VisualScoreItem, ...] = ()
    normalization: ScoreNormalization = ScoreNormalization.SYMMETRIC
    source_count: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        items = tuple(coerce_visual_score_item(value, index=index) for index, value in enumerate(self.items))
        keys = [item.key for item in items]
        duplicates = sorted(key for key, count in Counter(keys).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Visual score keys must be unique.", context={"duplicates": duplicates}
            )
        if len(items) > _SCORE_MAX_ITEMS:
            raise VisualizationLimitError(f"Visual scoring cannot exceed {_SCORE_MAX_ITEMS} items.")
        object.__setattr__(self, "items", items)
        object.__setattr__(self, "normalization", ScoreNormalization.parse(
            self.normalization, default=ScoreNormalization.SYMMETRIC
        ))
        object.__setattr__(self, "source_count", _bounded_int(
            self.source_count or len(items), field_name="source_count", minimum=0, maximum=_SCORE_MAX_ITEMS
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def __len__(self) -> int:
        return len(self.items)

    def __iter__(self) -> Iterator[VisualScoreItem]:
        return iter(self.items)

    def by_target(self, target: Any) -> Tuple[VisualScoreItem, ...]:
        parsed = ScoreTarget.parse(target, default=ScoreTarget.RESIDUE)
        return tuple(item for item in self.items if item.target is parsed)

    @property
    def targets(self) -> Tuple[ScoreTarget, ...]:
        return tuple(dict.fromkeys(item.target for item in self.items))

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.items if not item.selection.is_none)
        return selection_union(*selections) if selections else MolecularSelection.none()

    @property
    def scores(self) -> Tuple[float, ...]:
        return tuple(item.score for item in self.items if item.score is not None)


@dataclass(frozen=True, slots=True)
class VisualScoringSpec(MolecularSpecMixin):
    """Visual score mapping and display options."""

    collection: VisualScoreCollection
    enabled: bool = True
    targets: Tuple[ScoreTarget, ...] = ()
    palette_kind: ScorePaletteKind = ScorePaletteKind.DIVERGING
    normalization: ScoreNormalization = ScoreNormalization.SYMMETRIC
    palette: Tuple[str, ...] = DEFAULT_SCORE_PALETTE
    minimum: Optional[float] = None
    center: float = DEFAULT_SCORE_CENTER
    maximum: Optional[float] = None
    clamp: bool = True
    apply_color: bool = True
    apply_radius: bool = False
    apply_opacity: bool = False
    show_labels: bool = False
    radius_range: Tuple[float, float] = (_SCORE_RADIUS_MIN, _SCORE_RADIUS_MAX)
    opacity_range: Tuple[float, float] = (_SCORE_OPACITY_MIN, _SCORE_OPACITY_MAX)
    max_items: int = MAX_VISUAL_ELEMENTS
    missing_color: str = DEFAULT_MISSING_COLOR
    label_template: str = _SCORE_LABEL_TEMPLATE
    group_name: str = _SCORE_GROUP_NAME
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = coerce_visual_score_collection(self.collection)
        targets = tuple(dict.fromkeys(
            ScoreTarget.parse(value, default=ScoreTarget.RESIDUE) for value in self.targets
        )) or collection.targets
        radius_range = tuple(_score_float(value, field_name="radius_range", allow_none=False) for value in self.radius_range)
        opacity_range = tuple(_score_float(value, field_name="opacity_range", allow_none=False) for value in self.opacity_range)
        if len(radius_range) != 2 or not MIN_RADIUS <= radius_range[0] <= radius_range[1] <= MAX_RADIUS:
            raise VisualizationConfigurationError("radius_range is invalid.")
        if len(opacity_range) != 2 or not 0.0 <= opacity_range[0] <= opacity_range[1] <= 1.0:
            raise VisualizationConfigurationError("opacity_range is invalid.")
        palette = tuple(normalize_color(value) for value in self.palette)
        if not palette:
            raise VisualizationConfigurationError("Visual scoring requires a palette.")
        minimum = _score_float(self.minimum, field_name="minimum")
        maximum = _score_float(self.maximum, field_name="maximum")
        center = _score_float(self.center, field_name="center", allow_none=False)
        if minimum is not None and maximum is not None and minimum >= maximum:
            raise VisualizationConfigurationError("minimum must be lower than maximum.")
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "targets", targets)
        object.__setattr__(self, "palette_kind", ScorePaletteKind.parse(
            self.palette_kind, default=ScorePaletteKind.DIVERGING
        ))
        object.__setattr__(self, "normalization", ScoreNormalization.parse(
            self.normalization, default=collection.normalization
        ))
        object.__setattr__(self, "palette", palette)
        object.__setattr__(self, "minimum", minimum)
        object.__setattr__(self, "center", center)
        object.__setattr__(self, "maximum", maximum)
        object.__setattr__(self, "clamp", bool(self.clamp))
        object.__setattr__(self, "apply_color", bool(self.apply_color))
        object.__setattr__(self, "apply_radius", bool(self.apply_radius))
        object.__setattr__(self, "apply_opacity", bool(self.apply_opacity))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "radius_range", radius_range)
        object.__setattr__(self, "opacity_range", opacity_range)
        object.__setattr__(self, "max_items", _bounded_int(
            self.max_items, field_name="max_items", minimum=0, maximum=_SCORE_MAX_ITEMS
        ))
        object.__setattr__(self, "missing_color", normalize_color(self.missing_color))
        object.__setattr__(self, "label_template", _plan_text(
            self.label_template, field_name="label_template", required=True, maximum=512
        ))
        object.__setattr__(self, "group_name", _clean_config_name(
            self.group_name, field_name="group_name", maximum=MAX_GROUP_NAME_LENGTH
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[VisualScoreItem, ...]:
        items = [item for item in self.collection.items if item.target in self.targets]
        items.sort(key=lambda item: (
            item.score is None,
            -(item.normalized_score if item.normalized_score is not None else -1.0),
            item.rank or _SCORE_MAX_ITEMS,
            item.item_id,
        ))
        return tuple(items[:self.max_items])

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.selected if not item.selection.is_none)
        return selection_union(*selections) if selections else MolecularSelection.none()


# 17.3. Coercion and collection building
# -----------------------------------------------------------------------------

def coerce_visual_score_item(
    value: Any,
    *,
    index: int = 0,
    target: Any = None,
) -> VisualScoreItem:
    """Coerce one score item."""

    if isinstance(value, VisualScoreItem):
        return value
    parsed_target = _score_target(value, target)
    item_id = _score_identifier(value, parsed_target, index)
    if isinstance(value, Mapping):
        allowed = {
            "item_id", "target", "score", "selection", "normalized_score",
            "color", "radius", "opacity", "rank", "label", "pose_id", "metadata",
        }
        data = {key: item for key, item in value.items() if key in allowed}
        data.setdefault("item_id", item_id)
        data.setdefault("target", parsed_target)
        data.setdefault("score", _object_value(value, "score", "total_score", "visual_score", "value", "affinity"))
        data.setdefault("selection", _score_selection(value, parsed_target))
        data.setdefault("label", _score_label(value, item_id))
        return VisualScoreItem(**data)
    score = _object_value(value, "score", "total_score", "visual_score", "value", "affinity")
    rank = _object_value(value, "rank", "ranking")
    pose_id = _object_value(value, "pose_id")
    metadata = _object_value(value, "metadata", default={})
    return VisualScoreItem(
        item_id=item_id,
        target=parsed_target,
        score=score,
        selection=_score_selection(value, parsed_target),
        rank=rank,
        label=_score_label(value, item_id),
        pose_id=pose_id,
        metadata=metadata if isinstance(metadata, Mapping) else {},
    )


def _score_source_items(value: Any, target: Any = None) -> Tuple[Tuple[Any, Optional[ScoreTarget]], ...]:
    explicit = ScoreTarget.parse(target, strict=False)
    if isinstance(value, VisualScoreCollection):
        return tuple((item, item.target) for item in value.items)
    if isinstance(value, VisualScoringSpec):
        return tuple((item, item.target) for item in value.collection.items)
    if isinstance(value, VisualInteractionCollection):
        return tuple((item, ScoreTarget.INTERACTION) for item in value.interactions)
    if isinstance(value, InvolvedResidueCollection):
        return tuple((item, ScoreTarget.RESIDUE) for item in value.residues)
    if isinstance(value, HotspotCollection):
        return tuple((item, ScoreTarget.HOTSPOT) for item in value.hotspots)
    if isinstance(value, MolecularSpecificationBundle):
        return tuple((item, ScoreTarget.POSE) for item in value.poses)
    if isinstance(value, StructureSpec):
        return tuple((item, ScoreTarget.POSE) for item in value.poses)
    if isinstance(value, Mapping):
        grouped: List[Tuple[Any, Optional[ScoreTarget]]] = []
        keys = {
            "interactions": ScoreTarget.INTERACTION,
            "residues": ScoreTarget.RESIDUE,
            "poses": ScoreTarget.POSE,
            "hotspots": ScoreTarget.HOTSPOT,
            "models": ScoreTarget.MODEL,
        }
        for key, key_target in keys.items():
            group = value.get(key)
            if group is None:
                continue
            members = group.values() if isinstance(group, Mapping) else group
            if isinstance(members, Iterable) and not isinstance(members, (str, bytes)):
                grouped.extend((item, key_target) for item in members)
        if grouped:
            return tuple(grouped)
        return ((value, explicit),)
    for name, key_target in (
        ("interactions", ScoreTarget.INTERACTION),
        ("residues", ScoreTarget.RESIDUE),
        ("poses", ScoreTarget.POSE),
        ("pose_scores", ScoreTarget.POSE),
        ("hotspots", ScoreTarget.HOTSPOT),
        ("models", ScoreTarget.MODEL),
    ):
        group = getattr(value, name, None)
        if group is not None:
            members = group.values() if isinstance(group, Mapping) else group
            if isinstance(members, Iterable) and not isinstance(members, (str, bytes)):
                return tuple((item, key_target) for item in members)
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, Mapping)):
        return tuple((item, explicit) for item in value)
    return ((value, explicit),)


def build_visual_score_collection(
    value: Any,
    *,
    target: Any = None,
    normalization: Any = ScoreNormalization.SYMMETRIC,
    minimum: Optional[float] = None,
    center: float = DEFAULT_SCORE_CENTER,
    maximum: Optional[float] = None,
    clamp: bool = True,
) -> VisualScoreCollection:
    """Build and normalize visual scores."""

    if isinstance(value, VisualScoreCollection):
        items = value.items
    elif isinstance(value, VisualScoringSpec):
        items = value.collection.items
    else:
        items = tuple(
            coerce_visual_score_item(item, index=index, target=item_target or target)
            for index, (item, item_target) in enumerate(_score_source_items(value, target))
        )
    method = ScoreNormalization.parse(normalization, default=ScoreNormalization.SYMMETRIC)
    positions = normalize_visual_scores(
        (item.score for item in items),
        method=method,
        minimum=minimum,
        center=center,
        maximum=maximum,
        clamp=clamp,
    )
    valid_order = sorted(
        (item for item in items if item.score is not None),
        key=lambda item: (-float(item.score), item.item_id),
    )
    ranks = {item.key: index + 1 for index, item in enumerate(valid_order)}
    normalized = tuple(
        replace(item, normalized_score=position, rank=item.rank or ranks.get(item.key))
        for item, position in zip(items, positions)
    )
    scores = [item.score for item in normalized if item.score is not None]
    return VisualScoreCollection(
        normalized,
        normalization=method,
        source_count=len(items),
        metadata={"statistics": _score_statistics(scores)},
    )


def coerce_visual_score_collection(value: Any, **kwargs: Any) -> VisualScoreCollection:
    """Coerce a score collection."""

    if isinstance(value, VisualScoreCollection) and not kwargs:
        return value
    if isinstance(value, Mapping) and "items" in value and not kwargs:
        return VisualScoreCollection(**value)
    return build_visual_score_collection(value, **kwargs)


def coerce_visual_scoring_spec(value: Any, *, config_value: Any = None, **overrides: Any) -> VisualScoringSpec:
    """Coerce visual scoring options."""

    config_obj = resolve_visualization_config(config_value)
    style = config_obj.scoring
    if isinstance(value, VisualScoringSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping) and "collection" in value:
        data = dict(value)
        data.update(overrides)
        return VisualScoringSpec(**data)
    source_normalization = (
        value.normalization if isinstance(value, VisualScoreCollection) else style.normalization
    )
    options = {
        "enabled": style.enabled or bool(value),
        "palette_kind": style.palette_kind,
        "normalization": source_normalization,
        "palette": style.palette,
        "minimum": style.minimum,
        "center": style.center,
        "maximum": style.maximum,
        "clamp": style.clamp,
        "missing_color": style.missing_color,
    }
    options.update(overrides)
    collection = build_visual_score_collection(
        value,
        normalization=options["normalization"],
        minimum=options.get("minimum"),
        center=options.get("center", DEFAULT_SCORE_CENTER),
        maximum=options.get("maximum"),
        clamp=options.get("clamp", True),
    )
    return VisualScoringSpec(collection=collection, **options)


# 17.4. Styling and planning
# -----------------------------------------------------------------------------

def style_visual_scores(value: Any, *, config_value: Any = None, **overrides: Any) -> VisualScoringSpec:
    """Apply score colors and scales."""

    spec = coerce_visual_scoring_spec(value, config_value=config_value, **overrides)
    items: List[VisualScoreItem] = []
    for item in spec.collection.items:
        position = item.normalized_score
        color = item.color or _score_palette_color(position, spec.palette, spec.missing_color)
        radius = item.radius or _score_scaled(position, *spec.radius_range, sum(spec.radius_range) / 2.0)
        opacity = item.opacity or _score_scaled(position, *spec.opacity_range, spec.opacity_range[0])
        items.append(replace(item, color=color, radius=radius, opacity=opacity))
    return replace(spec, collection=replace(spec.collection, items=tuple(items)))


def _score_action_items(spec: VisualScoringSpec, target: ScoreTarget) -> List[Dict[str, Any]]:
    output: List[Dict[str, Any]] = []
    for item in spec.selected:
        if item.target is not target:
            continue
        label = item.label or item.item_id
        label_text = None
        if spec.show_labels:
            try:
                label_text = spec.label_template.format(
                    id=item.item_id,
                    label=label,
                    score=item.score if item.score is not None else float("nan"),
                    normalized=item.normalized_score if item.normalized_score is not None else float("nan"),
                    rank=item.rank or 0,
                    target=item.target.value,
                )
            except (KeyError, ValueError) as exc:
                raise VisualizationConfigurationError("Invalid score label template.", cause=exc) from exc
        output.append({
            "id": item.item_id,
            "selection": item.selection.expression,
            "score": item.score,
            "normalized_score": item.normalized_score,
            "rank": item.rank,
            "color": item.color if spec.apply_color else None,
            "radius": item.radius if spec.apply_radius else None,
            "opacity": item.opacity if spec.apply_opacity else None,
            "label": label_text,
            "pose_id": item.pose_id,
        })
    return output


def build_scoring_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
    **overrides: Any,
) -> Tuple[VisualizationAction, ...]:
    """Build score-mapping actions."""

    spec = style_visual_scores(value, config_value=config_value, **overrides)
    if not spec.enabled:
        return ()
    dependencies = _action_dependencies(depends_on)
    actions: List[VisualizationAction] = []
    for target in spec.targets:
        entries = _score_action_items(spec, target)
        if not entries:
            continue
        selections = tuple(
            item.selection for item in spec.selected
            if item.target is target and not item.selection.is_none
        )
        actions.append(VisualizationAction(
            action_id=f"scoring:{target.value}",
            operation=PlanOperation.APPLY_SCORING,
            layer=_SCORE_TARGET_LAYERS[target],
            selection=selection_union(*selections) if selections else MolecularSelection.none(),
            parameters={
                "target": target.value,
                "palette_kind": spec.palette_kind.value,
                "normalization": spec.normalization.value,
                "apply_color": spec.apply_color,
                "apply_radius": spec.apply_radius,
                "apply_opacity": spec.apply_opacity,
                "show_labels": spec.show_labels,
                "group_name": spec.group_name,
                "items": entries,
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH,
            optional=True,
            description=f"Map scores onto {target.value} visuals.",
            tags=("scoring", target.value),
        ))
    return tuple(actions)


def build_scoring_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "visual-scoring",
    name: str = "Visual scoring",
    **overrides: Any,
) -> VisualizationPlan:
    """Build a standalone score plan."""

    config_obj = resolve_visualization_config(config_value)
    spec = style_visual_scores(value, config_value=config_obj, **overrides)
    return build_visualization_plan(
        build_scoring_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        description="Score-driven molecular styling.",
        metadata={"scoring": spec.to_dict()},
    )


def attach_scoring(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
    **overrides: Any,
) -> VisualizationPlan:
    """Attach score actions to a plan."""

    base = coerce_visualization_plan(plan)
    spec = style_visual_scores(value, config_value=config_value, **overrides)
    dependencies: List[str] = []
    for target in spec.targets:
        prefixes = _SCORE_TARGET_PREFIXES[target]
        dependencies.extend(
            action.action_id for action in base.actions
            if action.enabled and action.action_id.startswith(prefixes)
        )
    if not dependencies:
        fallback = next((
            action.action_id for action in reversed(base.actions)
            if action.enabled and action.action_id != "scene:prepare"
        ), None)
        dependencies = [fallback or "scene:prepare"] if base.actions else []
    incoming = {
        action.action_id: action for action in build_scoring_actions(
            spec, config_value=config_value, depends_on=tuple(dict.fromkeys(dependencies))
        )
    }
    actions: List[VisualizationAction] = []
    for action in base.actions:
        replacement = incoming.pop(action.action_id, None)
        if replacement is None:
            actions.append(action)
        elif replace_existing:
            actions.append(replacement)
        else:
            raise VisualizationPlanError(f"Scoring action already exists: {action.action_id!r}.")
    actions.extend(incoming.values())
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "scoring": spec.to_dict()},
    )


def visualize_scoring(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **overrides: Any,
) -> VisualizationPlan:
    """Create or attach visual scoring."""

    return (
        build_scoring_plan(value, config_value=config_value, **overrides)
        if plan is None
        else attach_scoring(plan, value, config_value=config_value, **overrides)
    )


# 17.5. Validation and serialization
# -----------------------------------------------------------------------------

def validate_visual_scoring(value: Any, *, config_value: Any = None) -> Tuple[PlanValidationIssue, ...]:
    """Validate visual scoring semantics."""

    spec = style_visual_scores(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    selected = spec.selected
    if spec.enabled and not selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "scoring_empty",
            "No scored objects are available for display.",
            "scoring",
        ))
    missing = sum(item.score is None for item in selected)
    if missing:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "scoring_missing_values",
            "Some visual objects have no score.",
            "scoring",
            {"count": missing},
        ))
    unselected = sum(item.selection.is_none for item in selected)
    if unselected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "scoring_missing_selections",
            "Some scored objects have no molecular selection.",
            "scoring",
            {"count": unselected},
        ))
    scores = [item.score for item in selected if item.score is not None]
    if len(scores) > 1 and max(scores) - min(scores) <= VISUALIZATION_SCORE_EPSILON:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "scoring_zero_variance",
            "All available scores are equal.",
            "scoring",
        ))
    if len(spec.collection.items) > spec.max_items:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "scoring_limit_applied",
            "The visual score item limit was applied.",
            "scoring",
            {"available": len(spec.collection.items), "displayed": len(selected)},
        ))
    if not any((spec.apply_color, spec.apply_radius, spec.apply_opacity, spec.show_labels)):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "scoring_no_effect",
            "Visual scoring has no enabled display effect.",
            "scoring",
        ))
    return tuple(issues)


def summarize_visual_scoring(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Return compact score statistics."""

    spec = style_visual_scores(value, config_value=config_value)
    selected = spec.selected
    scores = [item.score for item in selected if item.score is not None]
    issues = validate_visual_scoring(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.items),
        "displayed_count": len(selected),
        "targets": dict(Counter(item.target.value for item in selected)),
        "normalization": spec.normalization.value,
        "palette_kind": spec.palette_kind.value,
        "statistics": _score_statistics(scores),
        "missing_count": sum(item.score is None for item in selected),
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def scoring_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize visual scoring."""

    return style_visual_scores(value, config_value=config_value).to_dict()


def scoring_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize visual scoring as JSON."""

    return json.dumps(
        scoring_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


