# =============================================================================
# Section 18 — Multipose visualization
# =============================================================================

# 18.1. Constants and helpers
# -----------------------------------------------------------------------------

_MULTIPOSE_GROUP_ACTION: Final[str] = "multipose:group"
_MULTIPOSE_ALIGN_ACTION: Final[str] = "multipose:align"
_MULTIPOSE_SEQUENCE_ACTION: Final[str] = "multipose:sequence"
_MULTIPOSE_LABEL_ACTION: Final[str] = "multipose:labels"
_MULTIPOSE_INTERACTION_ACTION: Final[str] = "multipose:interactions"
_MULTIPOSE_ACTION_PREFIX: Final[str] = "multipose:"
_MULTIPOSE_DEFAULT_DELAY: Final[float] = 0.75
_MULTIPOSE_MIN_DELAY: Final[float] = 0.05
_MULTIPOSE_MAX_DELAY: Final[float] = 60.0
_MULTIPOSE_MAX_POSES: Final[int] = min(MAX_VISUAL_ELEMENTS, 1000)
_MULTIPOSE_LABEL_TEMPLATE: Final[str] = "{pose_id} | rank {rank} | score {score}"


def _multipose_text(
    value: Any,
    *,
    field_name: str,
    required: bool = False,
    maximum: int = 256,
) -> Optional[str]:
    """Normalize multipose text."""

    return _plan_text(value, field_name=field_name, required=required, maximum=maximum)


def _multipose_float(
    value: Any,
    *,
    field_name: str,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> Optional[float]:
    """Normalize a finite multipose metric."""

    result = _score_float(value, field_name=field_name)
    if result is None:
        return None
    if minimum is not None and result < minimum:
        raise VisualizationSpecificationError(f"{field_name} must be at least {minimum}.")
    if maximum is not None and result > maximum:
        raise VisualizationSpecificationError(f"{field_name} must not exceed {maximum}.")
    return result


def _multipose_identifiers(values: Any, *, field_name: str) -> Tuple[str, ...]:
    """Normalize unique identifiers."""

    if values is None:
        return ()
    if isinstance(values, str):
        values = (values,)
    result: List[str] = []
    for value in values:
        text = _multipose_text(value, field_name=field_name, required=True, maximum=128)
        assert text is not None
        if text not in result:
            result.append(text)
    return tuple(result)


def _multipose_action_suffix(value: Any, *, index: int) -> str:
    """Return a safe action suffix."""

    text = re.sub(r"[^A-Za-z0-9_.:-]+", "-", str(value).strip()).strip("-.:_")
    if not text:
        text = "pose"
    return f"{index + 1}:{text[:80]}"


def _multipose_metadata(value: Any) -> Mapping[str, Any]:
    """Freeze metadata."""

    return _normalize_spec_metadata(value)


def _pose_model_id(value: Any) -> Optional[str]:
    """Resolve a pose model identifier."""

    model_id = _object_value(value, "model_id", "model", "structure_id")
    if model_id is not None and not isinstance(model_id, str):
        model_id = _object_value(model_id, "id_string", "id", "model_id", default=model_id)
    try:
        return _normalize_model_id(model_id)
    except VisualizationError:
        return None


def _pose_selection(value: Any, *, pose_id: str) -> MolecularSelection:
    """Resolve a pose selection."""

    if isinstance(value, PoseVisualSpec):
        return value.selection
    if isinstance(value, PoseSpec):
        return pose_spec_to_selection(value)
    if isinstance(value, Mapping):
        for key in ("selection", "atomspec", "atom_spec", "ligand"):
            if key in value and value[key] is not None:
                try:
                    return coerce_selection(value[key]).with_label(pose_id)
                except VisualizationError:
                    pass
        model_id = value.get("model_id")
        if model_id is not None:
            return coerce_selection(MolecularPathSpec(model_id=str(model_id), role=MolecularRole.LIGAND)).with_label(pose_id)
    try:
        selection = coerce_selection(value)
    except VisualizationError:
        model_id = _pose_model_id(value)
        selection = MolecularSelection.none() if model_id is None else coerce_selection(
            MolecularPathSpec(model_id=model_id, role=MolecularRole.LIGAND)
        )
    return selection.with_label(pose_id)


def _pose_rank_key(item: "PoseVisualSpec") -> Tuple[Any, ...]:
    """Return a stable best-first pose key."""

    rank = item.rank if item.rank is not None else _MULTIPOSE_MAX_POSES + item.index + 1
    score = item.score if item.score is not None else -math.inf
    affinity = item.affinity if item.affinity is not None else math.inf
    return rank, -score, affinity, item.index, item.pose_id


def _pose_cluster_key(value: Any) -> Optional[str]:
    """Resolve a cluster identifier."""

    cluster = _object_value(value, "cluster_id", "cluster", "cluster_name")
    if cluster is None:
        metadata = _object_value(value, "metadata", default={})
        if isinstance(metadata, Mapping):
            cluster = metadata.get("cluster_id", metadata.get("cluster"))
    return _multipose_text(cluster, field_name="cluster_id", maximum=128)


def _pose_metadata_flag(item: "PoseVisualSpec", *keys: str) -> bool:
    """Read a boolean metadata flag."""

    for key in keys:
        value = item.metadata.get(key)
        if isinstance(value, bool):
            return value
        if isinstance(value, Real) and not isinstance(value, bool):
            return bool(value)
        if isinstance(value, str) and value.strip().lower() in {"1", "true", "yes", "on", "selected"}:
            return True
    return False


def _pose_score_map(value: Any) -> Mapping[str, VisualScoreItem]:
    """Resolve pose score items by identifier."""

    if value is None:
        return MappingProxyType({})
    if isinstance(value, Mapping) and value and not any(
        key in value for key in ("items", "collection", "poses", "interactions", "residues", "hotspots", "models")
    ):
        simple: Dict[str, VisualScoreItem] = {}
        for index, (pose_id, raw) in enumerate(value.items()):
            if isinstance(raw, Mapping):
                item = coerce_visual_score_item(
                    {"item_id": str(pose_id), "pose_id": str(pose_id), "target": ScoreTarget.POSE, **dict(raw)},
                    index=index,
                    target=ScoreTarget.POSE,
                )
            else:
                item = VisualScoreItem(
                    item_id=str(pose_id),
                    pose_id=str(pose_id),
                    target=ScoreTarget.POSE,
                    score=raw,
                )
            simple[str(pose_id)] = item
        return MappingProxyType(simple)
    try:
        collection = coerce_visual_score_collection(value)
    except VisualizationError:
        return MappingProxyType({})
    result: Dict[str, VisualScoreItem] = {}
    for item in collection.items:
        if item.target is not ScoreTarget.POSE:
            continue
        result[item.pose_id or item.item_id] = item
        result.setdefault(item.item_id, item)
    return MappingProxyType(result)


def _pose_interaction_map(value: Any) -> Mapping[str, Tuple[str, ...]]:
    """Group interaction identifiers by pose."""

    if value is None:
        return MappingProxyType({})
    try:
        collection = value if isinstance(value, VisualInteractionCollection) else build_visual_interactions(value)
    except VisualizationError:
        return MappingProxyType({})
    grouped: Dict[str, List[str]] = defaultdict(list)
    for item in collection.interactions:
        if item.pose_id is not None:
            grouped[item.pose_id].append(item.interaction_id)
    return MappingProxyType({key: tuple(dict.fromkeys(items)) for key, items in grouped.items()})


def _pose_source_items(value: Any) -> Tuple[Any, ...]:
    """Return pose-like source items."""

    if value is None:
        return ()
    if isinstance(value, MultiposeVisualizationSpec):
        return value.collection.poses
    if isinstance(value, PoseVisualCollection):
        return value.poses
    if isinstance(value, LigandVisualizationSpec):
        return tuple(
            {
                "pose_id": pose_id,
                "selection": selection,
                "index": index,
                "active": pose_id == value.active_pose_id,
            }
            for index, (pose_id, selection) in enumerate(value.poses.items())
        )
    if isinstance(value, MolecularSpecificationBundle):
        return tuple(value.poses)
    if isinstance(value, StructureSpec):
        return tuple(value.poses)
    if isinstance(value, MolecularSelectionBundle):
        return tuple(
            {"pose_id": pose_id, "selection": selection, "index": index}
            for index, (pose_id, selection) in enumerate(value.poses.items())
        )
    if isinstance(value, PoseSpec):
        return (value,)
    if isinstance(value, Mapping):
        if "collection" in value and isinstance(value.get("collection"), Mapping):
            return _pose_source_items(value["collection"])
        if "poses" in value:
            return _pose_source_items(value["poses"])
        if "pose_id" in value:
            return (value,)
        return tuple(
            {"pose_id": str(key), "selection": item, "index": index}
            if not isinstance(item, Mapping)
            else {"pose_id": str(key), "index": index, **dict(item)}
            for index, (key, item) in enumerate(value.items())
        )
    for name in ("poses", "pose_results", "pose_scores"):
        items = getattr(value, name, None)
        if items is not None:
            return _pose_source_items(items)
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes)):
        return tuple(value)
    return (value,)


# 18.2. Models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseVisualSpec(MolecularSpecMixin):
    """One visualized docking pose."""

    pose_id: str
    selection: MolecularSelection
    index: int = 0
    rank: Optional[int] = None
    score: Optional[float] = None
    affinity: Optional[float] = None
    rmsd: Optional[float] = None
    cluster_id: Optional[str] = None
    color: Optional[str] = None
    opacity: float = DEFAULT_INACTIVE_POSE_OPACITY
    representation: MolecularRepresentation = MolecularRepresentation.STICKS
    active: bool = False
    reference: bool = False
    visible: bool = True
    interaction_ids: Tuple[str, ...] = ()
    label: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        pose_id = _multipose_text(self.pose_id, field_name="pose_id", required=True, maximum=128)
        assert pose_id is not None
        object.__setattr__(self, "pose_id", pose_id)
        object.__setattr__(self, "selection", coerce_selection(self.selection).with_label(pose_id))
        object.__setattr__(self, "index", _bounded_int(
            self.index, field_name="index", minimum=0, maximum=_MULTIPOSE_MAX_POSES
        ))
        object.__setattr__(self, "rank", _optional_spec_int(self.rank, field_name="rank", minimum=1))
        object.__setattr__(self, "score", _multipose_float(self.score, field_name="score"))
        object.__setattr__(self, "affinity", _multipose_float(self.affinity, field_name="affinity"))
        object.__setattr__(self, "rmsd", _multipose_float(self.rmsd, field_name="rmsd", minimum=0.0))
        object.__setattr__(self, "cluster_id", _multipose_text(
            self.cluster_id, field_name="cluster_id", maximum=128
        ))
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "opacity", _bounded_float(
            self.opacity, field_name="opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "representation", MolecularRepresentation.parse(
            self.representation, default=MolecularRepresentation.STICKS
        ))
        object.__setattr__(self, "active", bool(self.active))
        object.__setattr__(self, "reference", bool(self.reference))
        object.__setattr__(self, "visible", bool(self.visible))
        object.__setattr__(self, "interaction_ids", _multipose_identifiers(
            self.interaction_ids, field_name="interaction_id"
        ))
        object.__setattr__(self, "label", _multipose_text(self.label, field_name="label", maximum=512))
        object.__setattr__(self, "metadata", _multipose_metadata(self.metadata))

    @property
    def key(self) -> Tuple[str, int]:
        return self.pose_id, self.index

    @property
    def quality_value(self) -> Optional[float]:
        if self.score is not None:
            return self.score
        if self.affinity is not None:
            return -self.affinity
        return None


@dataclass(frozen=True, slots=True)
class PoseVisualCollection(MolecularSpecMixin):
    """Ordered unique visual poses."""

    poses: Tuple[PoseVisualSpec, ...] = ()
    active_pose_id: Optional[str] = None
    reference_pose_id: Optional[str] = None
    source_count: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        poses = tuple(coerce_pose_visual_spec(item, index=index) for index, item in enumerate(self.poses))
        ids = [item.pose_id for item in poses]
        duplicates = sorted(key for key, count in Counter(ids).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Pose identifiers must be unique.", context={"duplicates": duplicates}
            )
        active_pose_id = _multipose_text(self.active_pose_id, field_name="active_pose_id", maximum=128)
        reference_pose_id = _multipose_text(
            self.reference_pose_id, field_name="reference_pose_id", maximum=128
        )
        active_items = [item.pose_id for item in poses if item.active]
        reference_items = [item.pose_id for item in poses if item.reference]
        if active_pose_id is None and active_items:
            active_pose_id = active_items[0]
        if reference_pose_id is None and reference_items:
            reference_pose_id = reference_items[0]
        if active_pose_id is None and poses:
            active_pose_id = min(poses, key=_pose_rank_key).pose_id
        if reference_pose_id is None:
            reference_pose_id = active_pose_id
        for field_name, pose_id in (
            ("active_pose_id", active_pose_id),
            ("reference_pose_id", reference_pose_id),
        ):
            if pose_id is not None and pose_id not in ids:
                raise VisualizationSpecificationError(
                    f"Unknown {field_name}.", context={field_name: pose_id, "pose_ids": ids}
                )
        normalized = tuple(
            replace(
                item,
                active=item.pose_id == active_pose_id,
                reference=item.pose_id == reference_pose_id,
            )
            for item in poses
        )
        object.__setattr__(self, "poses", normalized)
        object.__setattr__(self, "active_pose_id", active_pose_id)
        object.__setattr__(self, "reference_pose_id", reference_pose_id)
        object.__setattr__(self, "source_count", _bounded_int(
            self.source_count or len(poses), field_name="source_count", minimum=0
        ))
        object.__setattr__(self, "metadata", _multipose_metadata(self.metadata))

    @property
    def by_id(self) -> Mapping[str, PoseVisualSpec]:
        return MappingProxyType({item.pose_id: item for item in self.poses})

    @property
    def active_pose(self) -> Optional[PoseVisualSpec]:
        return None if self.active_pose_id is None else self.by_id[self.active_pose_id]

    @property
    def reference_pose(self) -> Optional[PoseVisualSpec]:
        return None if self.reference_pose_id is None else self.by_id[self.reference_pose_id]

    @property
    def ranked(self) -> Tuple[PoseVisualSpec, ...]:
        return tuple(sorted(self.poses, key=_pose_rank_key))

    @property
    def visible(self) -> Tuple[PoseVisualSpec, ...]:
        return tuple(item for item in self.ranked if item.visible and not item.selection.is_none)

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.visible)
        return selection_union(*selections) if selections else MolecularSelection.none()

    @property
    def cluster_count(self) -> int:
        return len({item.cluster_id for item in self.poses if item.cluster_id is not None})


@dataclass(frozen=True, slots=True)
class MultiposeFrameSpec(MolecularSpecMixin):
    """One sequential multipose frame."""

    frame_index: int
    pose_ids: Tuple[str, ...]
    selection: MolecularSelection
    duration: float = _MULTIPOSE_DEFAULT_DELAY
    label: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        pose_ids = _multipose_identifiers(self.pose_ids, field_name="pose_id")
        if not pose_ids:
            raise VisualizationSpecificationError("A multipose frame requires a pose.")
        object.__setattr__(self, "frame_index", _bounded_int(
            self.frame_index, field_name="frame_index", minimum=0, maximum=_MULTIPOSE_MAX_POSES
        ))
        object.__setattr__(self, "pose_ids", pose_ids)
        object.__setattr__(self, "selection", coerce_selection(self.selection))
        object.__setattr__(self, "duration", _bounded_float(
            self.duration,
            field_name="duration",
            minimum=_MULTIPOSE_MIN_DELAY,
            maximum=_MULTIPOSE_MAX_DELAY,
        ))
        object.__setattr__(self, "label", _multipose_text(self.label, field_name="label", maximum=512))
        object.__setattr__(self, "metadata", _multipose_metadata(self.metadata))


@dataclass(frozen=True, slots=True)
class MultiposeVisualizationSpec(MolecularSpecMixin):
    """Multipose display plan input."""

    collection: PoseVisualCollection
    display_mode: PoseDisplayMode = PoseDisplayMode.OVERLAY
    color_mode: PoseColorMode = PoseColorMode.POSE
    representation: MolecularRepresentation = MolecularRepresentation.STICKS
    pose_colors: Tuple[str, ...] = POSE_PALETTE
    single_color: str = DEFAULT_LIGAND_COLOR
    active_opacity: float = DEFAULT_POSE_OPACITY
    inactive_opacity: float = DEFAULT_INACTIVE_POSE_OPACITY
    max_visible_poses: int = DEFAULT_MAX_VISIBLE_POSES
    align_to_reference: bool = True
    show_labels: bool = False
    show_interactions: bool = True
    synchronize_interactions: bool = True
    sequential_delay: float = _MULTIPOSE_DEFAULT_DELAY
    loop_sequence: bool = False
    group_name: str = DEFAULT_POSE_GROUP_NAME
    enabled: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = self.collection
        if isinstance(collection, Mapping):
            collection = PoseVisualCollection(**dict(collection))
        if not isinstance(collection, PoseVisualCollection):
            collection = build_pose_visual_collection(collection)
        colors = tuple(normalize_color(value) for value in self.pose_colors)
        if not colors:
            raise VisualizationConfigurationError("Multipose visualization requires pose colors.")
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "display_mode", PoseDisplayMode.parse(
            self.display_mode, default=PoseDisplayMode.OVERLAY
        ))
        object.__setattr__(self, "color_mode", PoseColorMode.parse(
            self.color_mode, default=PoseColorMode.POSE
        ))
        object.__setattr__(self, "representation", MolecularRepresentation.parse(
            self.representation, default=MolecularRepresentation.STICKS
        ))
        object.__setattr__(self, "pose_colors", colors)
        object.__setattr__(self, "single_color", normalize_color(self.single_color))
        object.__setattr__(self, "active_opacity", _bounded_float(
            self.active_opacity, field_name="active_opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "inactive_opacity", _bounded_float(
            self.inactive_opacity, field_name="inactive_opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "max_visible_poses", _bounded_int(
            self.max_visible_poses,
            field_name="max_visible_poses",
            minimum=1,
            maximum=_MULTIPOSE_MAX_POSES,
        ))
        object.__setattr__(self, "align_to_reference", bool(self.align_to_reference))
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "show_interactions", bool(self.show_interactions))
        object.__setattr__(self, "synchronize_interactions", bool(self.synchronize_interactions))
        object.__setattr__(self, "sequential_delay", _bounded_float(
            self.sequential_delay,
            field_name="sequential_delay",
            minimum=_MULTIPOSE_MIN_DELAY,
            maximum=_MULTIPOSE_MAX_DELAY,
        ))
        object.__setattr__(self, "loop_sequence", bool(self.loop_sequence))
        object.__setattr__(self, "group_name", _clean_config_name(
            self.group_name, field_name="group_name", maximum=MAX_GROUP_NAME_LENGTH
        ))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "metadata", _multipose_metadata(self.metadata))

    @property
    def selected_poses(self) -> Tuple[PoseVisualSpec, ...]:
        poses = list(self.collection.visible)
        active = self.collection.active_pose
        if self.display_mode is PoseDisplayMode.ACTIVE:
            return () if active is None or not active.visible else (active,)
        if self.display_mode is PoseDisplayMode.CONSENSUS:
            selected = [item for item in poses if _pose_metadata_flag(
                item, "consensus", "consensus_selected", "persistent"
            )]
            poses = selected or poses
        elif self.display_mode is PoseDisplayMode.COMPLEMENTARY:
            selected = [item for item in poses if _pose_metadata_flag(
                item, "complementary", "complementary_selected", "selected_set"
            )]
            poses = selected or poses
        elif active is not None and active in poses:
            poses.remove(active)
            poses.insert(0, active)
        return tuple(poses[:self.max_visible_poses])

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.selected_poses)
        return selection_union(*selections) if selections else MolecularSelection.none()

    @property
    def frames(self) -> Tuple[MultiposeFrameSpec, ...]:
        if self.display_mode is not PoseDisplayMode.SEQUENTIAL:
            return ()
        return tuple(
            MultiposeFrameSpec(
                frame_index=index,
                pose_ids=(item.pose_id,),
                selection=item.selection,
                duration=self.sequential_delay,
                label=item.label or item.pose_id,
                metadata={"rank": item.rank, "score": item.score, "affinity": item.affinity},
            )
            for index, item in enumerate(self.selected_poses)
        )


# 18.3. Coercion and styling
# -----------------------------------------------------------------------------

def coerce_pose_visual_spec(
    value: Any,
    *,
    index: int = 0,
    active_pose_id: Optional[str] = None,
    reference_pose_id: Optional[str] = None,
    score_item: Optional[VisualScoreItem] = None,
    interaction_ids: Iterable[str] = (),
) -> PoseVisualSpec:
    """Coerce one visual pose."""

    if isinstance(value, PoseVisualSpec):
        changes: Dict[str, Any] = {}
        if score_item is not None:
            changes.update(score=score_item.score, rank=value.rank or score_item.rank)
        if interaction_ids:
            changes["interaction_ids"] = tuple(dict.fromkeys((*value.interaction_ids, *interaction_ids)))
        return replace(value, **changes) if changes else value
    pose_id = _object_value(value, "pose_id", "id", "identifier", "name", default=f"pose_{index + 1}")
    pose_id = _multipose_text(pose_id, field_name="pose_id", required=True, maximum=128)
    assert pose_id is not None
    metadata = _object_value(value, "metadata", default={})
    if not isinstance(metadata, Mapping):
        metadata = {}
    score = _object_value(value, "score", "total_score", "visual_score")
    rank = _object_value(value, "rank", "ranking")
    if score_item is not None:
        score = score_item.score if score_item.score is not None else score
        rank = rank or score_item.rank
    rmsd = _object_value(value, "rmsd", "rmsd_lower_bound", "rmsd_lb")
    color = _object_value(value, "color")
    opacity = _object_value(value, "opacity", default=DEFAULT_INACTIVE_POSE_OPACITY)
    representation = _object_value(value, "representation", default=MolecularRepresentation.STICKS)
    explicit_interactions = _object_value(value, "interaction_ids", default=())
    return PoseVisualSpec(
        pose_id=pose_id,
        selection=_pose_selection(value, pose_id=pose_id),
        index=_object_value(value, "index", "pose_index", default=index),
        rank=rank,
        score=score,
        affinity=_object_value(value, "affinity", "binding_affinity", "docking_affinity"),
        rmsd=rmsd,
        cluster_id=_pose_cluster_key(value),
        color=color,
        opacity=opacity,
        representation=representation,
        active=bool(_object_value(value, "active", "is_active", default=pose_id == active_pose_id)),
        reference=bool(_object_value(
            value, "reference", "is_reference", default=pose_id == reference_pose_id
        )),
        visible=bool(_object_value(value, "visible", "enabled", default=True)),
        interaction_ids=tuple(dict.fromkeys((*_multipose_identifiers(
            explicit_interactions, field_name="interaction_id"
        ), *interaction_ids))),
        label=_object_value(value, "label", "name", default=pose_id),
        metadata=metadata,
    )


def build_pose_visual_collection(
    value: Any,
    *,
    active_pose_id: Optional[str] = None,
    reference_pose_id: Optional[str] = None,
    scores: Any = None,
    interactions: Any = None,
    deduplicate: bool = True,
) -> PoseVisualCollection:
    """Build a normalized pose collection."""

    if isinstance(value, PoseVisualCollection) and all(
        item is None for item in (active_pose_id, reference_pose_id, scores, interactions)
    ):
        return value
    score_map = _pose_score_map(scores)
    interaction_map = _pose_interaction_map(interactions)
    source = _pose_source_items(value)
    poses: List[PoseVisualSpec] = []
    seen: Set[str] = set()
    inferred_active = active_pose_id
    inferred_reference = reference_pose_id
    if isinstance(value, LigandVisualizationSpec):
        inferred_active = inferred_active or value.active_pose_id
    if isinstance(value, Mapping):
        inferred_active = inferred_active or value.get("active_pose_id")
        inferred_reference = inferred_reference or value.get("reference_pose_id")
    for index, item in enumerate(source):
        pose_id = _object_value(item, "pose_id", "id", "identifier", "name", default=f"pose_{index + 1}")
        pose_id = str(pose_id)
        if deduplicate and pose_id in seen:
            continue
        score_item = score_map.get(pose_id)
        pose = coerce_pose_visual_spec(
            item,
            index=index,
            active_pose_id=inferred_active,
            reference_pose_id=inferred_reference,
            score_item=score_item,
            interaction_ids=interaction_map.get(pose_id, ()),
        )
        poses.append(pose)
        seen.add(pose.pose_id)
    return PoseVisualCollection(
        poses=tuple(poses),
        active_pose_id=inferred_active,
        reference_pose_id=inferred_reference,
        source_count=len(source),
        metadata={"deduplicated": max(0, len(source) - len(poses))},
    )


def coerce_pose_visual_collection(value: Any, **kwargs: Any) -> PoseVisualCollection:
    """Coerce a visual pose collection."""

    if isinstance(value, PoseVisualCollection) and not kwargs:
        return value
    if isinstance(value, Mapping) and "poses" in value and set(value).issubset({
        "poses", "active_pose_id", "reference_pose_id", "source_count", "metadata"
    }) and not kwargs:
        return PoseVisualCollection(**dict(value))
    return build_pose_visual_collection(value, **kwargs)


def _multipose_palette_color(
    position: Optional[float],
    palette: Sequence[str],
    *,
    missing_color: str,
) -> str:
    """Interpolate one palette position."""

    if position is None:
        return missing_color
    if len(palette) == 1:
        return palette[0]
    scaled = max(0.0, min(1.0, position)) * (len(palette) - 1)
    lower, upper = int(math.floor(scaled)), int(math.ceil(scaled))
    if lower == upper:
        return palette[lower]
    return blend_colors(palette[lower], palette[upper], scaled - lower)


def _multipose_color(
    item: PoseVisualSpec,
    *,
    index: int,
    collection: PoseVisualCollection,
    color_mode: PoseColorMode,
    pose_colors: Tuple[str, ...],
    single_color: str,
    score_style: ScoreStyleConfig,
    score_position: Optional[float] = None,
) -> str:
    """Resolve one pose color."""

    if item.color is not None:
        return item.color
    if color_mode is PoseColorMode.SINGLE:
        return single_color
    if color_mode is PoseColorMode.SCORE:
        return _multipose_palette_color(
            score_position, score_style.palette, missing_color=score_style.missing_color
        )
    if color_mode is PoseColorMode.RANK:
        count = max(1, len(collection.poses) - 1)
        rank_index = max(0, (item.rank or index + 1) - 1)
        palette_index = round(min(1.0, rank_index / count) * (len(pose_colors) - 1))
        return pose_colors[palette_index]
    if color_mode is PoseColorMode.CLUSTER:
        key = item.cluster_id or item.pose_id
        palette_index = int(sha256(key.encode("utf-8")).hexdigest()[:8], 16) % len(pose_colors)
        return pose_colors[palette_index]
    return pose_colors[index % len(pose_colors)]


def build_multipose_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    scores: Any = None,
    interactions: Any = None,
    active_pose_id: Optional[str] = None,
    reference_pose_id: Optional[str] = None,
    display_mode: Any = None,
    color_mode: Any = None,
    representation: Any = None,
    pose_colors: Optional[Iterable[Any]] = None,
    single_color: Any = None,
    active_opacity: Optional[float] = None,
    inactive_opacity: Optional[float] = None,
    max_visible_poses: Optional[int] = None,
    align_to_reference: bool = True,
    show_labels: Optional[bool] = None,
    show_interactions: bool = True,
    synchronize_interactions: bool = True,
    sequential_delay: float = _MULTIPOSE_DEFAULT_DELAY,
    loop_sequence: bool = False,
    group_name: Optional[str] = None,
    enabled: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> MultiposeVisualizationSpec:
    """Build a styled multipose specification."""

    config_obj = resolve_visualization_config(config_value)
    style = config_obj.multipose
    collection = build_pose_visual_collection(
        value,
        active_pose_id=active_pose_id,
        reference_pose_id=reference_pose_id,
        scores=scores,
        interactions=interactions,
    )
    resolved_colors = tuple(pose_colors) if pose_colors is not None else style.pose_colors
    resolved_mode = PoseDisplayMode.parse(display_mode, default=style.display_mode)
    resolved_color_mode = PoseColorMode.parse(color_mode, default=style.color_mode)
    resolved_representation = MolecularRepresentation.parse(
        representation, default=config_obj.style_for(MolecularRole.LIGAND).representation
    )
    active_alpha = style.active_opacity if active_opacity is None else active_opacity
    inactive_alpha = style.inactive_opacity if inactive_opacity is None else inactive_opacity
    limit = style.max_visible_poses if max_visible_poses is None else max_visible_poses
    label_state = config_obj.labels.enabled if show_labels is None else show_labels
    preliminary = MultiposeVisualizationSpec(
        collection=collection,
        display_mode=resolved_mode,
        color_mode=resolved_color_mode,
        representation=resolved_representation,
        pose_colors=tuple(resolved_colors),
        single_color=single_color or config_obj.style_for(MolecularRole.LIGAND).color,
        active_opacity=active_alpha,
        inactive_opacity=inactive_alpha,
        max_visible_poses=limit,
        align_to_reference=align_to_reference,
        show_labels=label_state,
        show_interactions=show_interactions,
        synchronize_interactions=synchronize_interactions,
        sequential_delay=sequential_delay,
        loop_sequence=loop_sequence,
        group_name=group_name or style.group_name,
        enabled=enabled,
        metadata=metadata or {},
    )
    score_positions = normalize_visual_scores(
        (item.quality_value for item in preliminary.collection.poses),
        method=ScoreNormalization.MIN_MAX,
    )
    styled: List[PoseVisualSpec] = []
    for index, (item, score_position) in enumerate(zip(preliminary.collection.poses, score_positions)):
        styled.append(replace(
            item,
            color=_multipose_color(
                item,
                index=index,
                collection=preliminary.collection,
                color_mode=preliminary.color_mode,
                pose_colors=preliminary.pose_colors,
                single_color=preliminary.single_color,
                score_style=config_obj.scoring,
                score_position=score_position,
            ),
            opacity=preliminary.active_opacity if item.active else preliminary.inactive_opacity,
            representation=preliminary.representation,
        ))
    return replace(preliminary, collection=replace(preliminary.collection, poses=tuple(styled)))


def coerce_multipose_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    **overrides: Any,
) -> MultiposeVisualizationSpec:
    """Coerce multipose display options."""

    if isinstance(value, MultiposeVisualizationSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping) and "collection" in value:
        data = dict(value)
        data.update(overrides)
        return MultiposeVisualizationSpec(**data)
    return build_multipose_visualization_spec(value, config_value=config_value, **overrides)


# 18.4. Actions and plans
# -----------------------------------------------------------------------------

def _multipose_pose_parameters(item: PoseVisualSpec, spec: MultiposeVisualizationSpec) -> Dict[str, Any]:
    """Return one pose action payload."""

    return {
        "component": "multipose_pose",
        "pose_id": item.pose_id,
        "index": item.index,
        "rank": item.rank,
        "score": item.score,
        "affinity": item.affinity,
        "rmsd": item.rmsd,
        "cluster_id": item.cluster_id,
        "representation": item.representation.value,
        "color": item.color,
        "opacity": item.opacity,
        "active": item.active,
        "reference": item.reference,
        "group_name": spec.group_name,
        "visible": spec.display_mode is not PoseDisplayMode.SEQUENTIAL or item.active,
    }


def _multipose_dependencies(plan: VisualizationPlan) -> Tuple[str, ...]:
    """Resolve existing molecular dependencies."""

    preferred = ("ligand:base", "receptor:focus", "receptor:base", "scene:prepare")
    return tuple(action_id for action_id in preferred if action_id in plan.action_map)


def build_multipose_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert multipose data to plan actions."""

    spec = coerce_multipose_visualization_spec(value, config_value=config_value)
    dependencies = _action_dependencies(depends_on)
    selected = spec.selected_poses
    actions: List[VisualizationAction] = []
    pose_action_ids: List[str] = []
    if spec.align_to_reference and len(selected) > 1 and spec.collection.reference_pose is not None:
        actions.append(VisualizationAction(
            action_id=_MULTIPOSE_ALIGN_ACTION,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=spec.selection,
            parameters={
                "component": "multipose_alignment",
                "reference_pose_id": spec.collection.reference_pose_id,
                "mobile_pose_ids": tuple(
                    item.pose_id for item in selected if not item.reference
                ),
                "method": "matchmaker",
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH,
            enabled=spec.enabled,
            optional=True,
            description="Align visible poses to the reference pose.",
            tags=("multipose", "alignment"),
        ))
    base_dependencies = (_MULTIPOSE_ALIGN_ACTION,) if any(
        action.action_id == _MULTIPOSE_ALIGN_ACTION for action in actions
    ) else dependencies
    for pose_index, item in enumerate(selected):
        action_id = f"multipose:pose:{_multipose_action_suffix(item.pose_id, index=pose_index)}"
        pose_action_ids.append(action_id)
        actions.append(VisualizationAction(
            action_id=action_id,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=item.selection,
            parameters=_multipose_pose_parameters(item, spec),
            depends_on=base_dependencies,
            priority=OperationPriority.HIGH if item.active else OperationPriority.NORMAL,
            enabled=spec.enabled and item.visible,
            description=f"Display docking pose {item.pose_id}.",
            tags=("multipose", "pose", "active" if item.active else "alternate"),
            metadata={"interaction_ids": item.interaction_ids},
        ))
    if pose_action_ids:
        actions.append(VisualizationAction(
            action_id=_MULTIPOSE_GROUP_ACTION,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=spec.selection,
            parameters={
                "component": "multipose_group",
                "group_name": spec.group_name,
                "pose_ids": tuple(item.pose_id for item in selected),
                "display_mode": spec.display_mode.value,
                "color_mode": spec.color_mode.value,
                "active_pose_id": spec.collection.active_pose_id,
                "reference_pose_id": spec.collection.reference_pose_id,
            },
            depends_on=tuple(pose_action_ids),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Group displayed docking poses.",
            tags=("multipose", "group"),
        ))
    if spec.frames:
        actions.append(VisualizationAction(
            action_id=_MULTIPOSE_SEQUENCE_ACTION,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=spec.selection,
            parameters={
                "component": "multipose_sequence",
                "frames": tuple(frame.to_dict() for frame in spec.frames),
                "loop": spec.loop_sequence,
                "hide_other_poses": True,
            },
            depends_on=tuple(pose_action_ids),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Create the sequential pose display.",
            tags=("multipose", "sequence"),
        ))
    if spec.show_interactions and any(item.interaction_ids for item in selected):
        actions.append(VisualizationAction(
            action_id=_MULTIPOSE_INTERACTION_ACTION,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.INTERACTIONS,
            selection=spec.selection,
            parameters={
                "component": "multipose_interactions",
                "pose_interactions": {
                    item.pose_id: item.interaction_ids for item in selected if item.interaction_ids
                },
                "synchronize": spec.synchronize_interactions,
                "display_mode": spec.display_mode.value,
            },
            depends_on=tuple(pose_action_ids),
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Synchronize interactions with displayed poses.",
            tags=("multipose", "interactions"),
        ))
    if spec.show_labels and selected:
        actions.append(VisualizationAction(
            action_id=_MULTIPOSE_LABEL_ACTION,
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=spec.selection,
            parameters={
                "component": "multipose_labels",
                "template": _MULTIPOSE_LABEL_TEMPLATE,
                "labels": tuple({
                    "pose_id": item.pose_id,
                    "selection": item.selection.expression,
                    "label": item.label or item.pose_id,
                    "rank": item.rank,
                    "score": item.score,
                    "affinity": item.affinity,
                    "color": item.color,
                } for item in selected),
            },
            depends_on=tuple(pose_action_ids),
            priority=OperationPriority.LOW,
            enabled=spec.enabled,
            optional=True,
            description="Label displayed docking poses.",
            tags=("multipose", "labels"),
        ))
    return tuple(actions)


def build_multipose_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "multipose-visualization",
    name: str = "Multipose visualization",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **overrides: Any,
) -> VisualizationPlan:
    """Build a standalone multipose plan."""

    spec = build_multipose_visualization_spec(value, config_value=config_value, **overrides)
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_multipose_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display and compare docking poses.",
        metadata={"multipose": spec.to_dict(), **dict(metadata or {})},
    )


def attach_multipose(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
    **overrides: Any,
) -> VisualizationPlan:
    """Attach multipose actions to a plan."""

    base = coerce_visualization_plan(plan)
    spec = build_multipose_visualization_spec(value, config_value=config_value, **overrides)
    incoming = tuple(build_multipose_actions(
        spec,
        config_value=config_value,
        depends_on=_multipose_dependencies(base),
    ))
    existing = tuple(
        action for action in base.actions
        if action.action_id.startswith(_MULTIPOSE_ACTION_PREFIX)
    )
    if existing and not replace_existing:
        raise VisualizationPlanError("Multipose visualization actions already exist.")
    actions = [
        action for action in base.actions
        if not action.action_id.startswith(_MULTIPOSE_ACTION_PREFIX)
    ]
    actions.extend(incoming)
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "multipose": spec.to_dict()},
    )


def visualize_multipose(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **overrides: Any,
) -> VisualizationPlan:
    """Create or attach multipose visualization."""

    return (
        build_multipose_plan(value, config_value=config_value, **overrides)
        if plan is None
        else attach_multipose(plan, value, config_value=config_value, **overrides)
    )


# 18.5. Validation and serialization
# -----------------------------------------------------------------------------

def validate_multipose_visualization(
    value: Any,
    *,
    config_value: Any = None,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate multipose display semantics."""

    spec = coerce_multipose_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    selected = spec.selected_poses
    if spec.enabled and not spec.collection.poses:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "multipose_empty",
            "Multipose visualization requires at least one pose.",
            "multipose",
        ))
    elif spec.enabled and not selected:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "multipose_filter_empty",
            "No pose remains visible after multipose filtering.",
            "multipose",
        ))
    missing_selections = sum(item.selection.is_none for item in selected)
    if missing_selections:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "multipose_missing_selections",
            "Some visible poses have no molecular selection.",
            "multipose",
            {"count": missing_selections},
        ))
    if len(spec.collection.visible) > spec.max_visible_poses:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "multipose_limit_applied",
            "The visible pose limit was applied.",
            "multipose",
            {"available": len(spec.collection.visible), "displayed": len(selected)},
        ))
    if spec.align_to_reference and len(selected) > 1 and spec.collection.reference_pose is None:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "multipose_reference_missing",
            "Pose alignment requires a reference pose.",
            "multipose",
        ))
    if spec.color_mode is PoseColorMode.SCORE and not any(
        item.quality_value is not None for item in selected
    ):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "multipose_scores_missing",
            "Score coloring was requested but no pose scores are available.",
            "multipose",
        ))
    if spec.color_mode is PoseColorMode.CLUSTER and not any(item.cluster_id for item in selected):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "multipose_clusters_missing",
            "Cluster coloring has no cluster identifiers.",
            "multipose",
        ))
    if spec.display_mode in {PoseDisplayMode.CONSENSUS, PoseDisplayMode.COMPLEMENTARY} and selected:
        expected_keys = (
            ("consensus", "consensus_selected", "persistent")
            if spec.display_mode is PoseDisplayMode.CONSENSUS
            else ("complementary", "complementary_selected", "selected_set")
        )
        if not any(_pose_metadata_flag(item, *expected_keys) for item in spec.collection.visible):
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.INFO,
                "multipose_mode_fallback",
                "The requested multipose subset was unavailable; ranked poses were used.",
                "multipose",
                {"display_mode": spec.display_mode.value},
            ))
    return tuple(issues)


def summarize_multipose_visualization(
    value: Any,
    *,
    config_value: Any = None,
) -> Dict[str, Any]:
    """Return compact multipose statistics."""

    spec = coerce_multipose_visualization_spec(value, config_value=config_value)
    selected = spec.selected_poses
    scores = [item.score for item in selected if item.score is not None]
    affinities = [item.affinity for item in selected if item.affinity is not None]
    rmsd_values = [item.rmsd for item in selected if item.rmsd is not None]
    issues = validate_multipose_visualization(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "available_count": len(spec.collection.poses),
        "visible_count": len(spec.collection.visible),
        "displayed_count": len(selected),
        "display_mode": spec.display_mode.value,
        "color_mode": spec.color_mode.value,
        "active_pose_id": spec.collection.active_pose_id,
        "reference_pose_id": spec.collection.reference_pose_id,
        "pose_ids": tuple(item.pose_id for item in selected),
        "cluster_count": spec.collection.cluster_count,
        "score_statistics": _score_statistics(scores),
        "affinity_statistics": _score_statistics(affinities),
        "rmsd_statistics": _score_statistics(rmsd_values),
        "frame_count": len(spec.frames),
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def multipose_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize multipose visualization."""

    return coerce_multipose_visualization_spec(value, config_value=config_value).to_dict()


def multipose_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize multipose visualization as JSON."""

    return json.dumps(
        multipose_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


