# =============================================================================
# Section 19. Consensus and persistence
# =============================================================================

# 19.1. Constants and helpers
# -----------------------------------------------------------------------------

_CONSENSUS_SCHEMA_VERSION: Final[str] = "1.0"
_CONSENSUS_MAX_ITEMS: Final[int] = MAX_VISUAL_ELEMENTS
_CONSENSUS_CORE_FREQUENCY: Final[float] = 0.80
_CONSENSUS_LABEL_TEMPLATE: Final[str] = "{label} ({frequency:.0%})"
_CONSENSUS_DEFAULT_LEVELS: Final[Tuple[PersistenceLevel, ...]] = (
    PersistenceLevel.OCCASIONAL,
    PersistenceLevel.PERSISTENT,
    PersistenceLevel.CORE,
)


def _consensus_text(
    value: Any,
    *,
    field_name: str,
    required: bool = False,
    maximum: int = MAX_VISUALIZATION_NAME_LENGTH,
) -> Optional[str]:
    """Normalize consensus text."""

    if value is None:
        if required:
            raise VisualizationSpecificationError(f"{field_name} is required.")
        return None
    text = str(value).strip()
    if not text:
        if required:
            raise VisualizationSpecificationError(f"{field_name} is required.")
        return None
    if len(text) > maximum:
        raise VisualizationLimitError(f"{field_name} cannot exceed {maximum} characters.")
    if any(character in text for character in ("\x00", "\r", "\n")):
        raise VisualizationSpecificationError(f"{field_name} contains control characters.")
    return text


def _consensus_float(
    value: Any,
    *,
    field_name: str,
    default: float = 0.0,
    minimum: Optional[float] = None,
    maximum: Optional[float] = None,
) -> float:
    """Normalize a finite consensus metric."""

    if value is None:
        number = float(default)
    elif isinstance(value, bool) or not isinstance(value, Real):
        raise VisualizationSpecificationError(f"{field_name} must be numeric.")
    else:
        number = float(value)
    if not math.isfinite(number):
        raise VisualizationSpecificationError(f"{field_name} must be finite.")
    if minimum is not None and number < minimum:
        raise VisualizationSpecificationError(f"{field_name} must be at least {minimum}.")
    if maximum is not None and number > maximum:
        raise VisualizationSpecificationError(f"{field_name} cannot exceed {maximum}.")
    return number


def _consensus_identifiers(value: Any, *, field_name: str) -> Tuple[str, ...]:
    """Normalize unique identifiers."""

    if value is None:
        return ()
    values = (value,) if isinstance(value, (str, bytes)) else tuple(value)
    result: List[str] = []
    for item in values:
        text = _consensus_text(item, field_name=field_name, required=True, maximum=256)
        assert text is not None
        if text not in result:
            result.append(text)
    return tuple(result)


def _consensus_metadata(value: Any) -> Mapping[str, Any]:
    """Normalize consensus metadata."""

    return _normalize_spec_metadata(value)


def _consensus_level_order(level: PersistenceLevel) -> int:
    return {
        PersistenceLevel.TRANSIENT: 0,
        PersistenceLevel.OCCASIONAL: 1,
        PersistenceLevel.PERSISTENT: 2,
        PersistenceLevel.CORE: 3,
    }[level]


def classify_persistence(
    frequency: Any,
    *,
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY,
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY,
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY,
) -> PersistenceLevel:
    """Classify cross-pose persistence."""

    value = _consensus_float(
        frequency, field_name="frequency", minimum=0.0, maximum=1.0
    )
    persistence = _consensus_float(
        persistence_threshold,
        field_name="persistence_threshold",
        minimum=0.0,
        maximum=1.0,
    )
    consensus = _consensus_float(
        consensus_threshold,
        field_name="consensus_threshold",
        minimum=0.0,
        maximum=1.0,
    )
    core = _consensus_float(
        core_threshold, field_name="core_threshold", minimum=0.0, maximum=1.0
    )
    if not persistence <= consensus <= core:
        raise VisualizationConfigurationError(
            "Persistence thresholds must satisfy persistence <= consensus <= core."
        )
    if value >= core:
        return PersistenceLevel.CORE
    if value >= consensus:
        return PersistenceLevel.PERSISTENT
    if value >= persistence:
        return PersistenceLevel.OCCASIONAL
    return PersistenceLevel.TRANSIENT


def _consensus_metric_value(
    metric: ConsensusMetric,
    *,
    frequency: float,
    weighted_frequency: float,
    mean_score: Optional[float],
    support: float,
) -> float:
    if metric is ConsensusMetric.WEIGHTED_FREQUENCY:
        return weighted_frequency
    if metric is ConsensusMetric.SCORE:
        return 0.0 if mean_score is None else mean_score
    if metric is ConsensusMetric.SUPPORT:
        return support
    return frequency


def _consensus_endpoint_key(endpoint: InteractionEndpointSpec) -> Tuple[Any, ...]:
    if endpoint.residue_key is not None:
        return ("residue", *endpoint.residue_key)
    if not endpoint.selection.is_none:
        return ("selection", endpoint.selection.expression)
    if endpoint.point is not None:
        return ("point", *(round(value, 3) for value in endpoint.point))
    return ("unknown", endpoint.source_id or endpoint.effective_label)


def _consensus_interaction_key(item: VisualInteractionSpec) -> Tuple[Any, ...]:
    endpoints = sorted(
        (_consensus_endpoint_key(item.source), _consensus_endpoint_key(item.target)),
        key=repr,
    )
    return (
        item.family.value,
        item.subtype or "",
        tuple(endpoints),
    )


def _consensus_residue_key(item: InvolvedResidueSpec) -> Tuple[Any, ...]:
    return ("residue", *item.key)


def _consensus_hotspot_key(item: HotspotSpec) -> Tuple[Any, ...]:
    return (
        "hotspot",
        tuple(sorted(item.residue_ids)),
        tuple(sorted(family.value for family in item.families)),
    )


def _consensus_source_mapping(
    value: Any,
    *,
    collection_keys: Tuple[str, ...],
) -> Tuple[Tuple[str, Any], ...]:
    """Return pose-labeled source collections."""

    if isinstance(value, Mapping):
        if any(key in value for key in collection_keys):
            pose_id = str(value.get("pose_id") or value.get("source_pose_id") or "pose_1")
            return ((pose_id, value),)
        if "collection" in value:
            pose_id = str(value.get("pose_id") or "pose_1")
            return ((pose_id, value["collection"]),)
        pairs: List[Tuple[str, Any]] = []
        for key, item in value.items():
            if key in {"metadata", "pose_count", "source_count", "metric"}:
                continue
            pairs.append((str(key), item))
        if pairs:
            return tuple(pairs)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        pairs = []
        for index, item in enumerate(value):
            pose_id = _object_value(item, "pose_id", "source_pose_id") or f"pose_{index + 1}"
            pairs.append((str(pose_id), item))
        return tuple(pairs)
    pose_id = _object_value(value, "pose_id", "source_pose_id") or "pose_1"
    return ((str(pose_id), value),)


def _consensus_pose_weights(
    pose_ids: Sequence[str],
    value: Optional[Mapping[str, Any]],
) -> Mapping[str, float]:
    weights: Dict[str, float] = {}
    supplied = value or {}
    for pose_id in pose_ids:
        raw = supplied.get(pose_id, 1.0)
        weights[pose_id] = _consensus_float(
            raw, field_name=f"pose_weights[{pose_id}]", minimum=0.0
        )
    if weights and sum(weights.values()) <= VISUALIZATION_SCORE_EPSILON:
        raise VisualizationConfigurationError("At least one pose weight must be positive.")
    return MappingProxyType(weights)


def _consensus_label_from_interaction(item: VisualInteractionSpec) -> str:
    source = item.source.label or item.source.source_id or item.source.effective_label
    target = item.target.label or item.target.source_id or item.target.effective_label
    return f"{item.family.value}: {source}–{target}"


# 19.2. Consensus models
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ConsensusItemSpec(MolecularSpecMixin):
    """One cross-pose consensus element."""

    consensus_id: str
    target: ScoreTarget
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    source_ids: Tuple[str, ...] = ()
    pose_ids: Tuple[str, ...] = ()
    family: InteractionFamily = InteractionFamily.UNKNOWN
    occurrence_count: int = 0
    pose_count: int = 0
    frequency: float = 0.0
    weighted_frequency: float = 0.0
    support: float = 0.0
    mean_score: Optional[float] = None
    metric_value: float = 0.0
    persistence: PersistenceLevel = PersistenceLevel.TRANSIENT
    label: Optional[str] = None
    color: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        identifier = _consensus_text(
            self.consensus_id, field_name="consensus_id", required=True, maximum=256
        )
        assert identifier is not None
        source_ids = _consensus_identifiers(self.source_ids, field_name="source_id")
        pose_ids = _consensus_identifiers(self.pose_ids, field_name="pose_id")
        pose_count = _bounded_int(
            self.pose_count or len(pose_ids),
            field_name="pose_count",
            minimum=0,
            maximum=_CONSENSUS_MAX_ITEMS,
        )
        occurrence_count = _bounded_int(
            self.occurrence_count or len(source_ids),
            field_name="occurrence_count",
            minimum=0,
            maximum=_CONSENSUS_MAX_ITEMS,
        )
        object.__setattr__(self, "consensus_id", identifier)
        object.__setattr__(self, "target", ScoreTarget.parse(self.target, default=ScoreTarget.INTERACTION))
        object.__setattr__(self, "selection", coerce_selection(self.selection, strict=False))
        object.__setattr__(self, "source_ids", source_ids)
        object.__setattr__(self, "pose_ids", pose_ids)
        object.__setattr__(self, "family", InteractionFamily.parse(
            self.family, default=InteractionFamily.UNKNOWN
        ))
        object.__setattr__(self, "occurrence_count", occurrence_count)
        object.__setattr__(self, "pose_count", pose_count)
        object.__setattr__(self, "frequency", _consensus_float(
            self.frequency, field_name="frequency", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "weighted_frequency", _consensus_float(
            self.weighted_frequency,
            field_name="weighted_frequency",
            minimum=0.0,
            maximum=1.0,
        ))
        object.__setattr__(self, "support", _consensus_float(
            self.support, field_name="support", minimum=0.0
        ))
        object.__setattr__(self, "mean_score", None if self.mean_score is None else _consensus_float(
            self.mean_score, field_name="mean_score"
        ))
        object.__setattr__(self, "metric_value", _consensus_float(
            self.metric_value, field_name="metric_value"
        ))
        object.__setattr__(self, "persistence", PersistenceLevel.parse(
            self.persistence, default=PersistenceLevel.TRANSIENT
        ))
        object.__setattr__(self, "label", _consensus_text(
            self.label, field_name="label", maximum=MAX_LABEL_TEXT_LENGTH
        ))
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "metadata", _consensus_metadata(self.metadata))

    @property
    def persistent(self) -> bool:
        return self.persistence in {PersistenceLevel.PERSISTENT, PersistenceLevel.CORE}

    @property
    def core(self) -> bool:
        return self.persistence is PersistenceLevel.CORE


@dataclass(frozen=True, slots=True)
class ConsensusCollection(MolecularSpecMixin):
    """Validated cross-pose consensus collection."""

    items: Tuple[ConsensusItemSpec, ...] = ()
    metric: ConsensusMetric = ConsensusMetric.FREQUENCY
    pose_count: int = 0
    source_count: int = 0
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        items = tuple(coerce_consensus_item_spec(item) for item in self.items)
        identifiers = [item.consensus_id for item in items]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Consensus identifiers must be unique.", context={"duplicates": duplicates}
            )
        if len(items) > _CONSENSUS_MAX_ITEMS:
            raise VisualizationLimitError(
                f"Consensus collections cannot exceed {_CONSENSUS_MAX_ITEMS} entries."
            )
        persistence = _consensus_float(
            self.persistence_threshold,
            field_name="persistence_threshold",
            minimum=0.0,
            maximum=1.0,
        )
        consensus = _consensus_float(
            self.consensus_threshold,
            field_name="consensus_threshold",
            minimum=0.0,
            maximum=1.0,
        )
        core = _consensus_float(
            self.core_threshold, field_name="core_threshold", minimum=0.0, maximum=1.0
        )
        if not persistence <= consensus <= core:
            raise VisualizationConfigurationError(
                "Persistence thresholds must satisfy persistence <= consensus <= core."
            )
        object.__setattr__(self, "items", items)
        object.__setattr__(self, "metric", ConsensusMetric.parse(
            self.metric, default=ConsensusMetric.FREQUENCY
        ))
        object.__setattr__(self, "pose_count", _bounded_int(
            self.pose_count, field_name="pose_count", minimum=0, maximum=_CONSENSUS_MAX_ITEMS
        ))
        object.__setattr__(self, "source_count", _bounded_int(
            self.source_count, field_name="source_count", minimum=0, maximum=_CONSENSUS_MAX_ITEMS
        ))
        object.__setattr__(self, "persistence_threshold", persistence)
        object.__setattr__(self, "consensus_threshold", consensus)
        object.__setattr__(self, "core_threshold", core)
        object.__setattr__(self, "metadata", _consensus_metadata(self.metadata))

    def __len__(self) -> int:
        return len(self.items)

    def __iter__(self) -> Iterator[ConsensusItemSpec]:
        return iter(self.items)

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.items if not item.selection.is_none)
        return selection_union(*selections) if selections else MolecularSelection.none()

    @property
    def ranked(self) -> Tuple[ConsensusItemSpec, ...]:
        return tuple(sorted(
            self.items,
            key=lambda item: (
                -_consensus_level_order(item.persistence),
                -item.metric_value,
                -item.frequency,
                item.consensus_id,
            ),
        ))

    @property
    def persistent(self) -> Tuple[ConsensusItemSpec, ...]:
        return tuple(item for item in self.ranked if item.persistent)

    @property
    def core(self) -> Tuple[ConsensusItemSpec, ...]:
        return tuple(item for item in self.ranked if item.core)

    @property
    def level_counts(self) -> Mapping[str, int]:
        return MappingProxyType(dict(Counter(item.persistence.value for item in self.items)))

    @property
    def target_counts(self) -> Mapping[str, int]:
        return MappingProxyType(dict(Counter(item.target.value for item in self.items)))


@dataclass(frozen=True, slots=True)
class ConsensusPersistenceState(MolecularSpecMixin):
    """Serializable consensus state."""

    state_id: str
    collection: ConsensusCollection
    schema_version: str = _CONSENSUS_SCHEMA_VERSION
    created_at: Optional[str] = None
    updated_at: Optional[str] = None
    source_fingerprint: Optional[str] = None
    config_fingerprint: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        state_id = _consensus_text(
            self.state_id, field_name="state_id", required=True, maximum=256
        )
        assert state_id is not None
        collection = coerce_consensus_collection(self.collection)
        created_at = self.created_at or datetime.now(timezone.utc).isoformat()
        updated_at = self.updated_at or created_at
        object.__setattr__(self, "state_id", state_id)
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "schema_version", _consensus_text(
            self.schema_version,
            field_name="schema_version",
            required=True,
            maximum=32,
        ))
        object.__setattr__(self, "created_at", _consensus_text(
            created_at, field_name="created_at", required=True, maximum=128
        ))
        object.__setattr__(self, "updated_at", _consensus_text(
            updated_at, field_name="updated_at", required=True, maximum=128
        ))
        object.__setattr__(self, "source_fingerprint", _consensus_text(
            self.source_fingerprint, field_name="source_fingerprint", maximum=128
        ))
        object.__setattr__(self, "config_fingerprint", _consensus_text(
            self.config_fingerprint, field_name="config_fingerprint", maximum=128
        ))
        object.__setattr__(self, "metadata", _consensus_metadata(self.metadata))


@dataclass(frozen=True, slots=True)
class ConsensusStateDiff(MolecularSpecMixin):
    """Difference between two consensus states."""

    added_ids: Tuple[str, ...] = ()
    removed_ids: Tuple[str, ...] = ()
    changed_ids: Tuple[str, ...] = ()
    unchanged_ids: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "added_ids", _consensus_identifiers(
            self.added_ids, field_name="added_id"
        ))
        object.__setattr__(self, "removed_ids", _consensus_identifiers(
            self.removed_ids, field_name="removed_id"
        ))
        object.__setattr__(self, "changed_ids", _consensus_identifiers(
            self.changed_ids, field_name="changed_id"
        ))
        object.__setattr__(self, "unchanged_ids", _consensus_identifiers(
            self.unchanged_ids, field_name="unchanged_id"
        ))
        object.__setattr__(self, "metadata", _consensus_metadata(self.metadata))


# 19.3. Coercion and aggregation
# -----------------------------------------------------------------------------


def coerce_consensus_item_spec(value: Any) -> ConsensusItemSpec:
    """Convert a value to ConsensusItemSpec."""

    if isinstance(value, ConsensusItemSpec):
        return value
    if not isinstance(value, Mapping):
        raise VisualizationSpecificationError(
            "Consensus items must be mappings or ConsensusItemSpec instances."
        )
    payload = dict(value)
    payload["selection"] = coerce_selection(payload.get("selection"), strict=False)
    return ConsensusItemSpec(**payload)


def coerce_consensus_collection(value: Any) -> ConsensusCollection:
    """Convert a value to ConsensusCollection."""

    if isinstance(value, ConsensusCollection):
        return value
    if isinstance(value, ConsensusPersistenceState):
        return value.collection
    if isinstance(value, Mapping):
        payload = dict(value)
        if "collection" in payload and "items" not in payload:
            return coerce_consensus_collection(payload["collection"])
        payload["items"] = tuple(
            coerce_consensus_item_spec(item) for item in payload.get("items", ())
        )
        return ConsensusCollection(**payload)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return ConsensusCollection(items=tuple(coerce_consensus_item_spec(item) for item in value))
    raise VisualizationSpecificationError("Cannot convert value to ConsensusCollection.")


def _consensus_item_from_group(
    *,
    consensus_id: str,
    target: ScoreTarget,
    selection: MolecularSelection,
    source_ids: Sequence[str],
    pose_ids: Sequence[str],
    all_pose_ids: Sequence[str],
    pose_weights: Mapping[str, float],
    family: InteractionFamily,
    scores: Sequence[float],
    metric: ConsensusMetric,
    persistence_threshold: float,
    consensus_threshold: float,
    core_threshold: float,
    label: str,
    metadata: Mapping[str, Any],
) -> ConsensusItemSpec:
    unique_poses = tuple(dict.fromkeys(map(str, pose_ids)))
    total_pose_count = max(1, len(tuple(dict.fromkeys(map(str, all_pose_ids)))))
    frequency = min(1.0, len(unique_poses) / total_pose_count)
    total_weight = sum(pose_weights.get(pose_id, 1.0) for pose_id in all_pose_ids)
    supported_weight = sum(pose_weights.get(pose_id, 1.0) for pose_id in unique_poses)
    weighted_frequency = frequency if total_weight <= VISUALIZATION_SCORE_EPSILON else min(
        1.0, supported_weight / total_weight
    )
    mean_score = None if not scores else statistics.fmean(scores)
    support = float(len(unique_poses))
    metric_value = _consensus_metric_value(
        metric,
        frequency=frequency,
        weighted_frequency=weighted_frequency,
        mean_score=mean_score,
        support=support,
    )
    return ConsensusItemSpec(
        consensus_id=consensus_id,
        target=target,
        selection=selection,
        source_ids=tuple(dict.fromkeys(map(str, source_ids))),
        pose_ids=unique_poses,
        family=family,
        occurrence_count=len(source_ids),
        pose_count=total_pose_count,
        frequency=frequency,
        weighted_frequency=weighted_frequency,
        support=support,
        mean_score=mean_score,
        metric_value=metric_value,
        persistence=classify_persistence(
            frequency,
            persistence_threshold=persistence_threshold,
            consensus_threshold=consensus_threshold,
            core_threshold=core_threshold,
        ),
        label=label,
        metadata=metadata,
    )


def build_interaction_consensus(
    value: Any,
    *,
    metric: Any = ConsensusMetric.FREQUENCY,
    pose_weights: Optional[Mapping[str, Any]] = None,
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY,
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY,
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY,
) -> ConsensusCollection:
    """Aggregate visual interactions across poses."""

    parsed_metric = ConsensusMetric.parse(metric, default=ConsensusMetric.FREQUENCY)
    sources = _consensus_source_mapping(value, collection_keys=("interactions",))
    pose_ids = tuple(dict.fromkeys(pose_id for pose_id, _ in sources))
    observed_pose_ids = list(pose_ids)
    groups: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    source_count = 0
    for pose_id, source in sources:
        collection = _coerce_interaction_collection(source)
        source_count += len(collection.interactions)
        for item in collection.interactions:
            effective_pose = item.pose_id or pose_id
            observed_pose_ids.append(effective_pose)
            key = _consensus_interaction_key(item)
            bucket = groups.setdefault(key, {
                "items": [], "pose_ids": [], "scores": [], "selections": []
            })
            bucket["items"].append(item)
            bucket["pose_ids"].append(effective_pose)
            if item.score is not None:
                bucket["scores"].append(item.score)
            bucket["selections"].extend(selection for selection in item.selections if not selection.is_none)
    if len(sources) == 1 and sources[0][0] == "pose_1" and any(
        pose_id != "pose_1" for pose_id in observed_pose_ids
    ):
        observed_pose_ids = [pose_id for pose_id in observed_pose_ids if pose_id != "pose_1"]
    pose_ids = tuple(dict.fromkeys(observed_pose_ids))
    weights = _consensus_pose_weights(pose_ids, pose_weights)
    result: List[ConsensusItemSpec] = []
    for index, (key, bucket) in enumerate(sorted(groups.items(), key=lambda pair: repr(pair[0])), 1):
        representative: VisualInteractionSpec = bucket["items"][0]
        identifier = f"consensus:interaction:{index:04d}"
        result.append(_consensus_item_from_group(
            consensus_id=identifier,
            target=ScoreTarget.INTERACTION,
            selection=selection_union(*bucket["selections"]) if bucket["selections"] else MolecularSelection.none(),
            source_ids=[item.interaction_id for item in bucket["items"]],
            pose_ids=bucket["pose_ids"],
            all_pose_ids=pose_ids,
            pose_weights=weights,
            family=representative.family,
            scores=bucket["scores"],
            metric=parsed_metric,
            persistence_threshold=persistence_threshold,
            consensus_threshold=consensus_threshold,
            core_threshold=core_threshold,
            label=_consensus_label_from_interaction(representative),
            metadata={
                "key": key,
                "subtype": representative.subtype,
                "source_endpoint": representative.source.to_dict(),
                "target_endpoint": representative.target.to_dict(),
            },
        ))
    return ConsensusCollection(
        items=tuple(result),
        metric=parsed_metric,
        pose_count=len(pose_ids),
        source_count=source_count,
        persistence_threshold=persistence_threshold,
        consensus_threshold=consensus_threshold,
        core_threshold=core_threshold,
        metadata={"target": ScoreTarget.INTERACTION.value, "pose_weights": dict(weights)},
    )


def build_residue_consensus(
    value: Any,
    *,
    metric: Any = ConsensusMetric.FREQUENCY,
    pose_weights: Optional[Mapping[str, Any]] = None,
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY,
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY,
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY,
) -> ConsensusCollection:
    """Aggregate involved residues across poses."""

    parsed_metric = ConsensusMetric.parse(metric, default=ConsensusMetric.FREQUENCY)
    sources = _consensus_source_mapping(value, collection_keys=("residues",))
    pose_ids = tuple(dict.fromkeys(pose_id for pose_id, _ in sources))
    observed_pose_ids = list(pose_ids)
    groups: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    source_count = 0
    for pose_id, source in sources:
        collection = coerce_involved_residue_collection(source)
        source_count += len(collection.residues)
        for item in collection.residues:
            effective_poses = item.pose_ids or (pose_id,)
            observed_pose_ids.extend(effective_poses)
            key = _consensus_residue_key(item)
            bucket = groups.setdefault(key, {
                "items": [], "pose_ids": [], "scores": [], "selections": []
            })
            bucket["items"].append(item)
            bucket["pose_ids"].extend(effective_poses)
            if item.score is not None:
                bucket["scores"].append(item.score)
            if not item.selection.is_none:
                bucket["selections"].append(item.selection)
    if len(sources) == 1 and sources[0][0] == "pose_1" and any(
        pose_id != "pose_1" for pose_id in observed_pose_ids
    ):
        observed_pose_ids = [pose_id for pose_id in observed_pose_ids if pose_id != "pose_1"]
    pose_ids = tuple(dict.fromkeys(observed_pose_ids))
    weights = _consensus_pose_weights(pose_ids, pose_weights)
    result: List[ConsensusItemSpec] = []
    for index, (key, bucket) in enumerate(sorted(groups.items(), key=lambda pair: repr(pair[0])), 1):
        representative: InvolvedResidueSpec = bucket["items"][0]
        families = Counter(
            family for item in bucket["items"] for family in item.families
        )
        family = families.most_common(1)[0][0] if families else InteractionFamily.UNKNOWN
        result.append(_consensus_item_from_group(
            consensus_id=f"consensus:residue:{index:04d}",
            target=ScoreTarget.RESIDUE,
            selection=selection_union(*bucket["selections"]) if bucket["selections"] else representative.selection,
            source_ids=[item.residue_id for item in bucket["items"]],
            pose_ids=bucket["pose_ids"],
            all_pose_ids=pose_ids,
            pose_weights=weights,
            family=family,
            scores=bucket["scores"],
            metric=parsed_metric,
            persistence_threshold=persistence_threshold,
            consensus_threshold=consensus_threshold,
            core_threshold=core_threshold,
            label=representative.label,
            metadata={
                "key": key,
                "residue": representative.residue.to_dict(),
                "families": tuple(sorted(item.value for item in families)),
            },
        ))
    return ConsensusCollection(
        items=tuple(result),
        metric=parsed_metric,
        pose_count=len(pose_ids),
        source_count=source_count,
        persistence_threshold=persistence_threshold,
        consensus_threshold=consensus_threshold,
        core_threshold=core_threshold,
        metadata={"target": ScoreTarget.RESIDUE.value, "pose_weights": dict(weights)},
    )


def build_hotspot_consensus(
    value: Any,
    *,
    metric: Any = ConsensusMetric.FREQUENCY,
    pose_weights: Optional[Mapping[str, Any]] = None,
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY,
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY,
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY,
) -> ConsensusCollection:
    """Aggregate hotspots across poses."""

    parsed_metric = ConsensusMetric.parse(metric, default=ConsensusMetric.FREQUENCY)
    sources = _consensus_source_mapping(value, collection_keys=("hotspots",))
    pose_ids = tuple(dict.fromkeys(pose_id for pose_id, _ in sources))
    observed_pose_ids = list(pose_ids)
    groups: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    source_count = 0
    for pose_id, source in sources:
        collection = coerce_hotspot_collection(source)
        source_count += len(collection.hotspots)
        for item in collection.hotspots:
            effective_poses = item.pose_ids or (pose_id,)
            observed_pose_ids.extend(effective_poses)
            key = _consensus_hotspot_key(item)
            bucket = groups.setdefault(key, {
                "items": [], "pose_ids": [], "scores": [], "selections": []
            })
            bucket["items"].append(item)
            bucket["pose_ids"].extend(effective_poses)
            bucket["scores"].append(item.score)
            if not item.selection.is_none:
                bucket["selections"].append(item.selection)
    if len(sources) == 1 and sources[0][0] == "pose_1" and any(
        pose_id != "pose_1" for pose_id in observed_pose_ids
    ):
        observed_pose_ids = [pose_id for pose_id in observed_pose_ids if pose_id != "pose_1"]
    pose_ids = tuple(dict.fromkeys(observed_pose_ids))
    weights = _consensus_pose_weights(pose_ids, pose_weights)
    result: List[ConsensusItemSpec] = []
    for index, (key, bucket) in enumerate(sorted(groups.items(), key=lambda pair: repr(pair[0])), 1):
        representative: HotspotSpec = bucket["items"][0]
        result.append(_consensus_item_from_group(
            consensus_id=f"consensus:hotspot:{index:04d}",
            target=ScoreTarget.HOTSPOT,
            selection=selection_union(*bucket["selections"]) if bucket["selections"] else representative.selection,
            source_ids=[item.hotspot_id for item in bucket["items"]],
            pose_ids=bucket["pose_ids"],
            all_pose_ids=pose_ids,
            pose_weights=weights,
            family=representative.predominant_family,
            scores=bucket["scores"],
            metric=parsed_metric,
            persistence_threshold=persistence_threshold,
            consensus_threshold=consensus_threshold,
            core_threshold=core_threshold,
            label=representative.label,
            metadata={
                "key": key,
                "center": representative.center,
                "radius": representative.radius,
                "residue_ids": representative.residue_ids,
            },
        ))
    return ConsensusCollection(
        items=tuple(result),
        metric=parsed_metric,
        pose_count=len(pose_ids),
        source_count=source_count,
        persistence_threshold=persistence_threshold,
        consensus_threshold=consensus_threshold,
        core_threshold=core_threshold,
        metadata={"target": ScoreTarget.HOTSPOT.value, "pose_weights": dict(weights)},
    )


def infer_consensus_target(value: Any) -> ScoreTarget:
    """Infer a consensus source target."""

    if isinstance(value, (HotspotSpec, HotspotCollection)):
        return ScoreTarget.HOTSPOT
    if isinstance(value, (InvolvedResidueSpec, InvolvedResidueCollection)):
        return ScoreTarget.RESIDUE
    if isinstance(value, Mapping):
        keys = set(map(str, value.keys()))
        if "hotspots" in keys:
            return ScoreTarget.HOTSPOT
        if "residues" in keys:
            return ScoreTarget.RESIDUE
        for item in value.values():
            if isinstance(item, (HotspotSpec, HotspotCollection)):
                return ScoreTarget.HOTSPOT
            if isinstance(item, (InvolvedResidueSpec, InvolvedResidueCollection)):
                return ScoreTarget.RESIDUE
    return ScoreTarget.INTERACTION


def build_consensus_collection(
    value: Any,
    *,
    target: Any = None,
    metric: Any = ConsensusMetric.FREQUENCY,
    pose_weights: Optional[Mapping[str, Any]] = None,
    persistence_threshold: float = DEFAULT_PERSISTENCE_FREQUENCY,
    consensus_threshold: float = DEFAULT_CONSENSUS_FREQUENCY,
    core_threshold: float = _CONSENSUS_CORE_FREQUENCY,
) -> ConsensusCollection:
    """Build consensus for interactions, residues or hotspots."""

    if isinstance(value, (ConsensusCollection, ConsensusPersistenceState)):
        return coerce_consensus_collection(value)
    parsed_target = infer_consensus_target(value) if target is None else ScoreTarget.parse(
        target, default=ScoreTarget.INTERACTION
    )
    kwargs = {
        "metric": metric,
        "pose_weights": pose_weights,
        "persistence_threshold": persistence_threshold,
        "consensus_threshold": consensus_threshold,
        "core_threshold": core_threshold,
    }
    if parsed_target is ScoreTarget.RESIDUE:
        return build_residue_consensus(value, **kwargs)
    if parsed_target is ScoreTarget.HOTSPOT:
        return build_hotspot_consensus(value, **kwargs)
    return build_interaction_consensus(value, **kwargs)


# 19.4. State persistence
# -----------------------------------------------------------------------------


def create_consensus_state(
    value: Any,
    *,
    state_id: str = "visualization-consensus",
    config_value: Any = None,
    source_fingerprint: Optional[str] = None,
    metadata: Optional[Mapping[str, Any]] = None,
    **build_kwargs: Any,
) -> ConsensusPersistenceState:
    """Create a serializable consensus state."""

    config_obj = resolve_visualization_config(config_value)
    collection = build_consensus_collection(value, **build_kwargs)
    return ConsensusPersistenceState(
        state_id=state_id,
        collection=collection,
        source_fingerprint=source_fingerprint or collection.fingerprint(),
        config_fingerprint=config_obj.fingerprint(),
        metadata=metadata or {},
    )


def coerce_consensus_state(value: Any) -> ConsensusPersistenceState:
    """Convert a value to ConsensusPersistenceState."""

    if isinstance(value, ConsensusPersistenceState):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError as exc:
            raise VisualizationSerializationError("Invalid consensus-state JSON.") from exc
    if not isinstance(value, Mapping):
        raise VisualizationSpecificationError("Consensus state must be a mapping or JSON string.")
    payload = dict(value)
    payload["collection"] = coerce_consensus_collection(payload.get("collection", {}))
    return ConsensusPersistenceState(**payload)


def restore_consensus_state(value: Any) -> ConsensusPersistenceState:
    """Restore and validate a serialized consensus state."""

    state = coerce_consensus_state(value)
    if state.schema_version != _CONSENSUS_SCHEMA_VERSION:
        raise VisualizationSerializationError(
            "Unsupported consensus-state schema version.",
            context={
                "expected": _CONSENSUS_SCHEMA_VERSION,
                "received": state.schema_version,
            },
        )
    return state


def compare_consensus_states(left: Any, right: Any) -> ConsensusStateDiff:
    """Compare two persisted consensus states."""

    first = coerce_consensus_state(left)
    second = coerce_consensus_state(right)
    left_map = {item.consensus_id: item for item in first.collection.items}
    right_map = {item.consensus_id: item for item in second.collection.items}
    left_ids, right_ids = set(left_map), set(right_map)
    shared = left_ids & right_ids
    changed = sorted(
        item_id for item_id in shared
        if left_map[item_id].fingerprint() != right_map[item_id].fingerprint()
    )
    unchanged = sorted(shared - set(changed))
    return ConsensusStateDiff(
        added_ids=tuple(sorted(right_ids - left_ids)),
        removed_ids=tuple(sorted(left_ids - right_ids)),
        changed_ids=tuple(changed),
        unchanged_ids=tuple(unchanged),
        metadata={"left_state_id": first.state_id, "right_state_id": second.state_id},
    )


def merge_consensus_states(
    *values: Any,
    state_id: str = "merged-visualization-consensus",
) -> ConsensusPersistenceState:
    """Merge compatible persisted consensus states."""

    states = tuple(coerce_consensus_state(value) for value in values)
    if not states:
        raise VisualizationSpecificationError("At least one consensus state is required.")
    metric = states[0].collection.metric
    thresholds = (
        states[0].collection.persistence_threshold,
        states[0].collection.consensus_threshold,
        states[0].collection.core_threshold,
    )
    if any(state.collection.metric is not metric for state in states):
        raise VisualizationSpecificationError("Consensus states must use the same metric.")
    merged: Dict[str, ConsensusItemSpec] = {}
    for state in states:
        for item in state.collection.items:
            existing = merged.get(item.consensus_id)
            if existing is None or (
                _consensus_level_order(item.persistence), item.metric_value, item.frequency
            ) > (
                _consensus_level_order(existing.persistence), existing.metric_value, existing.frequency
            ):
                merged[item.consensus_id] = item
    collection = ConsensusCollection(
        items=tuple(merged.values()),
        metric=metric,
        pose_count=max(state.collection.pose_count for state in states),
        source_count=sum(state.collection.source_count for state in states),
        persistence_threshold=thresholds[0],
        consensus_threshold=thresholds[1],
        core_threshold=thresholds[2],
        metadata={"merged_state_ids": tuple(state.state_id for state in states)},
    )
    return ConsensusPersistenceState(
        state_id=state_id,
        collection=collection,
        source_fingerprint=sha256("|".join(
            state.source_fingerprint or state.fingerprint() for state in states
        ).encode(VISUALIZATION_TEXT_ENCODING)).hexdigest(),
        metadata={"merged_state_ids": tuple(state.state_id for state in states)},
    )


# 19.5. Visualization
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ConsensusVisualizationSpec(MolecularSpecMixin):
    """Consensus rendering configuration."""

    collection: ConsensusCollection
    enabled: bool = True
    levels: Tuple[PersistenceLevel, ...] = _CONSENSUS_DEFAULT_LEVELS
    max_items: int = MAX_VISUAL_ELEMENTS
    color_mode: ColorMode = ColorMode.FREQUENCY
    representation: MolecularRepresentation = MolecularRepresentation.STICKS
    opacity: float = DEFAULT_INTERACTION_OPACITY
    minimum_radius: float = MIN_RADIUS
    maximum_radius: float = DEFAULT_HOTSPOT_RADIUS
    show_labels: bool = False
    label_template: str = _CONSENSUS_LABEL_TEMPLATE
    fixed_color: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = coerce_consensus_collection(self.collection)
        levels = tuple(dict.fromkeys(
            PersistenceLevel.parse(level, default=PersistenceLevel.PERSISTENT)
            for level in self.levels
        ))
        if not levels:
            raise VisualizationConfigurationError("At least one persistence level is required.")
        minimum_radius = _bounded_float(
            self.minimum_radius, field_name="minimum_radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS
        )
        maximum_radius = _bounded_float(
            self.maximum_radius, field_name="maximum_radius", minimum=MIN_RADIUS, maximum=MAX_RADIUS
        )
        if minimum_radius > maximum_radius:
            raise VisualizationConfigurationError("minimum_radius cannot exceed maximum_radius.")
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "levels", levels)
        object.__setattr__(self, "max_items", _bounded_int(
            self.max_items, field_name="max_items", minimum=0, maximum=_CONSENSUS_MAX_ITEMS
        ))
        object.__setattr__(self, "color_mode", ColorMode.parse(
            self.color_mode, default=ColorMode.FREQUENCY
        ))
        object.__setattr__(self, "representation", MolecularRepresentation.parse(
            self.representation, default=MolecularRepresentation.STICKS
        ))
        object.__setattr__(self, "opacity", _bounded_float(
            self.opacity, field_name="opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "minimum_radius", minimum_radius)
        object.__setattr__(self, "maximum_radius", maximum_radius)
        object.__setattr__(self, "show_labels", bool(self.show_labels))
        object.__setattr__(self, "label_template", _consensus_text(
            self.label_template,
            field_name="label_template",
            required=True,
            maximum=MAX_LABEL_TEXT_LENGTH,
        ))
        object.__setattr__(self, "fixed_color", None if self.fixed_color is None else normalize_color(self.fixed_color))
        object.__setattr__(self, "metadata", _consensus_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[ConsensusItemSpec, ...]:
        allowed = set(self.levels)
        return tuple(item for item in self.collection.ranked if item.persistence in allowed)[:self.max_items]

    @property
    def selection(self) -> MolecularSelection:
        selections = tuple(item.selection for item in self.selected if not item.selection.is_none)
        return selection_union(*selections) if selections else MolecularSelection.none()


def build_consensus_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    **overrides: Any,
) -> ConsensusVisualizationSpec:
    """Build a consensus visualization specification."""

    config_obj = resolve_visualization_config(config_value)
    collection = build_consensus_collection(
        value,
        persistence_threshold=overrides.pop(
            "persistence_threshold", config_obj.multipose.persistence_frequency
        ),
        consensus_threshold=overrides.pop(
            "consensus_threshold", config_obj.multipose.consensus_frequency
        ),
        core_threshold=overrides.pop("core_threshold", _CONSENSUS_CORE_FREQUENCY),
        target=overrides.pop("target", None),
        metric=overrides.pop("metric", ConsensusMetric.FREQUENCY),
        pose_weights=overrides.pop("pose_weights", None),
    )
    defaults = {
        "collection": collection,
        "enabled": True,
        "levels": _CONSENSUS_DEFAULT_LEVELS,
        "max_items": min(_CONSENSUS_MAX_ITEMS, config_obj.multipose.max_visible_poses * 20),
        "color_mode": ColorMode.FREQUENCY,
        "opacity": config_obj.interactions.opacity,
        "show_labels": config_obj.labels.enabled,
    }
    defaults.update(overrides)
    return ConsensusVisualizationSpec(**defaults)


def coerce_consensus_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
) -> ConsensusVisualizationSpec:
    """Convert a value to ConsensusVisualizationSpec."""

    if isinstance(value, ConsensusVisualizationSpec):
        return value
    if isinstance(value, Mapping) and "collection" in value:
        payload = dict(value)
        payload["collection"] = coerce_consensus_collection(payload["collection"])
        return ConsensusVisualizationSpec(**payload)
    if isinstance(value, (ConsensusCollection, ConsensusPersistenceState)):
        return ConsensusVisualizationSpec(collection=coerce_consensus_collection(value))
    return build_consensus_visualization_spec(value, config_value=config_value)


def consensus_visual_color(
    item: Any,
    *,
    spec: Any,
    config_value: Any = None,
) -> str:
    """Resolve one consensus color."""

    member = coerce_consensus_item_spec(item)
    display = coerce_consensus_visualization_spec(spec, config_value=config_value)
    config_obj = resolve_visualization_config(config_value)
    if member.color:
        return member.color
    if display.color_mode is ColorMode.FIXED:
        return display.fixed_color or DEFAULT_MISSING_COLOR
    if display.color_mode is ColorMode.INTERACTION:
        return config_obj.palette.color_for(member.family)
    if display.color_mode is ColorMode.SCORE:
        scores = [value.mean_score for value in display.selected if value.mean_score is not None]
        if member.mean_score is None:
            return config_obj.scoring.missing_color
        minimum = min(scores) if scores else member.mean_score
        maximum = max(scores) if scores else member.mean_score
        return _metric_color(member.mean_score, minimum, maximum, config_obj.scoring.palette)
    return _score_palette_color(
        member.frequency,
        config_obj.scoring.palette,
        config_obj.scoring.missing_color,
    )


def _consensus_radius(item: ConsensusItemSpec, spec: ConsensusVisualizationSpec) -> float:
    return spec.minimum_radius + (
        spec.maximum_radius - spec.minimum_radius
    ) * max(0.0, min(1.0, item.frequency))


def _consensus_label(item: ConsensusItemSpec, template: str) -> str:
    values = {
        "id": item.consensus_id,
        "label": item.label or item.consensus_id,
        "target": item.target.value,
        "family": item.family.value,
        "frequency": item.frequency,
        "weighted_frequency": item.weighted_frequency,
        "score": 0.0 if item.mean_score is None else item.mean_score,
        "support": item.support,
        "persistence": item.persistence.value,
    }
    try:
        return template.format_map(values)
    except (KeyError, ValueError, AttributeError) as exc:
        raise VisualizationConfigurationError("Invalid consensus label template.") from exc


def _consensus_payload(
    spec: ConsensusVisualizationSpec,
    *,
    config_value: Any = None,
) -> Tuple[Dict[str, Any], ...]:
    return tuple({
        "consensus_id": item.consensus_id,
        "target": item.target.value,
        "selection": item.selection.expression,
        "source_ids": item.source_ids,
        "pose_ids": item.pose_ids,
        "family": item.family.value,
        "occurrence_count": item.occurrence_count,
        "pose_count": item.pose_count,
        "frequency": item.frequency,
        "weighted_frequency": item.weighted_frequency,
        "support": item.support,
        "mean_score": item.mean_score,
        "metric_value": item.metric_value,
        "persistence": item.persistence.value,
        "label": item.label,
        "color": consensus_visual_color(item, spec=spec, config_value=config_value),
        "radius": _consensus_radius(item, spec),
        "opacity": spec.opacity,
        "metadata": dict(item.metadata),
    } for item in spec.selected)


def _consensus_operation(target: ScoreTarget) -> Tuple[PlanOperation, VisualLayer]:
    if target is ScoreTarget.RESIDUE:
        return PlanOperation.SHOW_RESIDUES, VisualLayer.RESIDUES
    if target is ScoreTarget.HOTSPOT:
        return PlanOperation.SHOW_HOTSPOTS, VisualLayer.HOTSPOTS
    return PlanOperation.SHOW_INTERACTIONS, VisualLayer.INTERACTIONS


def build_consensus_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert consensus data to plan actions."""

    spec = coerce_consensus_visualization_spec(value, config_value=config_value)
    dependencies = _action_dependencies(depends_on)
    payload = _consensus_payload(spec, config_value=config_value)
    groups: Dict[ScoreTarget, List[Dict[str, Any]]] = defaultdict(list)
    for item, data in zip(spec.selected, payload):
        groups[item.target].append(data)
    actions: List[VisualizationAction] = []
    for target in (ScoreTarget.INTERACTION, ScoreTarget.RESIDUE, ScoreTarget.HOTSPOT):
        items = groups.get(target, [])
        if not items:
            continue
        operation, layer = _consensus_operation(target)
        actions.append(VisualizationAction(
            action_id=f"consensus:{target.value}",
            operation=operation,
            layer=layer,
            selection=selection_union(*(
                item.selection for item in spec.selected
                if item.target is target and not item.selection.is_none
            )),
            parameters={
                "component": "consensus",
                "target": target.value,
                "metric": spec.collection.metric.value,
                "color_mode": spec.color_mode.value,
                "representation": spec.representation.value,
                "items": tuple(items),
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH,
            enabled=spec.enabled,
            optional=True,
            tags=("consensus", target.value, "persistence"),
        ))
    if spec.show_labels and payload:
        label_dependencies = tuple(action.action_id for action in actions) or dependencies
        labels = tuple({
            "consensus_id": item.consensus_id,
            "selection": item.selection.expression,
            "text": _consensus_label(item, spec.label_template),
            "color": consensus_visual_color(item, spec=spec, config_value=config_value),
        } for item in spec.selected)
        actions.append(VisualizationAction(
            action_id="consensus:labels",
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=spec.selection,
            parameters={"component": "consensus", "labels": labels},
            depends_on=label_dependencies,
            priority=OperationPriority.LOW,
            enabled=spec.enabled,
            optional=True,
            tags=("consensus", "labels"),
        ))
    return tuple(actions)


def build_consensus_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "consensus-visualization",
    name: str = "Consensus visualization",
) -> VisualizationPlan:
    """Build a standalone consensus plan."""

    config_obj = resolve_visualization_config(config_value)
    spec = coerce_consensus_visualization_spec(value, config_value=config_obj)
    return build_visualization_plan(
        build_consensus_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        description="Visualize cross-pose consensus and persistence.",
        metadata={"consensus": spec.to_dict()},
    )


def attach_consensus(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach consensus actions to a plan."""

    base = coerce_visualization_plan(plan)
    action_ids = {action.action_id for action in base.actions}
    dependencies = tuple(
        action.action_id for action in base.actions
        if action.enabled and action.action_id.startswith(
            ("multipose:", "interactions:", "residues:", "hotspots:")
        )
    )
    if not dependencies:
        fallback = next((
            action_id for action_id in (
                "ligand:base", "receptor:focus", "receptor:base", "scene:prepare"
            ) if action_id in action_ids
        ), None)
        dependencies = (fallback,) if fallback else ()
    incoming = {action.action_id: action for action in build_consensus_actions(
        value, config_value=config_value, depends_on=dependencies
    )}
    actions: List[VisualizationAction] = []
    for action in base.actions:
        replacement = incoming.pop(action.action_id, None)
        if replacement is None:
            actions.append(action)
        elif replace_existing:
            actions.append(replacement)
        else:
            raise VisualizationPlanError(
                f"Consensus action already exists: {action.action_id!r}."
            )
    actions.extend(incoming.values())
    spec = coerce_consensus_visualization_spec(value, config_value=config_value)
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "consensus": spec.to_dict()},
    )


def visualize_consensus(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach consensus visualization."""

    spec = coerce_consensus_visualization_spec(value, config_value=config_value)
    if kwargs:
        spec = replace(spec, **kwargs)
    return (
        build_consensus_plan(spec, config_value=config_value)
        if plan is None
        else attach_consensus(plan, spec, config_value=config_value)
    )


# 19.6. Validation and serialization
# -----------------------------------------------------------------------------


def validate_consensus_visualization(
    value: Any,
    *,
    config_value: Any = None,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate consensus rendering semantics."""

    spec = coerce_consensus_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.collection.items:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "consensus_empty",
            "Consensus visualization contains no items.",
            "consensus",
        ))
    if spec.collection.pose_count < 2 and spec.collection.items:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "consensus_single_pose",
            "Consensus metrics are based on fewer than two poses.",
            "consensus",
            {"pose_count": spec.collection.pose_count},
        ))
    if spec.enabled and not spec.selected and spec.collection.items:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "consensus_filtered",
            "All consensus items were removed by persistence filters.",
            "consensus",
        ))
    if any(item.selection.is_none for item in spec.selected):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "consensus_selection_missing",
            "Some consensus items lack molecular selections.",
            "consensus",
        ))
    if spec.color_mode is ColorMode.SCORE and not any(
        item.mean_score is not None for item in spec.selected
    ):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "consensus_scores_missing",
            "Score coloring was requested but no consensus scores are available.",
            "consensus",
        ))
    return tuple(issues)


def summarize_consensus_visualization(
    value: Any,
    *,
    config_value: Any = None,
) -> Dict[str, Any]:
    """Return compact consensus statistics."""

    spec = coerce_consensus_visualization_spec(value, config_value=config_value)
    selected = spec.selected
    issues = validate_consensus_visualization(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "item_count": len(spec.collection.items),
        "selected_count": len(selected),
        "pose_count": spec.collection.pose_count,
        "source_count": spec.collection.source_count,
        "metric": spec.collection.metric.value,
        "levels": tuple(level.value for level in spec.levels),
        "level_counts": dict(spec.collection.level_counts),
        "target_counts": dict(spec.collection.target_counts),
        "persistent_count": len(spec.collection.persistent),
        "core_count": len(spec.collection.core),
        "mean_frequency": statistics.fmean(item.frequency for item in selected) if selected else 0.0,
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def consensus_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize consensus visualization."""

    return coerce_consensus_visualization_spec(value, config_value=config_value).to_dict()


def consensus_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize consensus visualization as JSON."""

    return json.dumps(
        consensus_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


def consensus_state_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize a consensus persistence state."""

    state = coerce_consensus_state(value)
    return json.dumps(
        state.to_dict(), ensure_ascii=False, sort_keys=True, indent=indent
    )


