# =============================================================================
# Section 20 — Complementarity
# =============================================================================

_COMPLEMENTARITY_ACTION_PREFIX: Final[str] = "complementarity:"
_COMPLEMENTARITY_SUMMARY_ACTION: Final[str] = "complementarity:summary"
_COMPLEMENTARITY_LABEL_ACTION: Final[str] = "complementarity:labels"
_COMPLEMENTARITY_MAX_EXACT_CANDIDATES: Final[int] = 18
_COMPLEMENTARITY_EPSILON: Final[float] = 1.0e-12
_COMPLEMENTARITY_DEFAULT_WEIGHTS: Final[Mapping[str, float]] = MappingProxyType({
    "residues": 0.40,
    "families": 0.20,
    "interaction_types": 0.20,
    "hotspots": 0.20,
})
_COMPLEMENTARITY_SHARED_COLOR: Final[str] = "#B0BEC5"
_COMPLEMENTARITY_UNIQUE_COLOR: Final[str] = "#FFB300"


def _complementarity_texts(values: Any, *, field_name: str) -> Tuple[str, ...]:
    """Normalize unique text identifiers."""

    if values is None:
        return ()
    if isinstance(values, (str, bytes)):
        values = (values,)
    output: List[str] = []
    for value in values:
        text = _clean_spec_text(
            value,
            field_name=field_name,
            max_length=MAX_VISUALIZATION_NAME_LENGTH,
        )
        if text and text not in output:
            output.append(text)
    return tuple(output)


def _complementarity_families(values: Any) -> Tuple[InteractionFamily, ...]:
    """Normalize interaction families."""

    if values is None:
        return ()
    if isinstance(values, (str, InteractionFamily)):
        values = (values,)
    return tuple(dict.fromkeys(
        InteractionFamily.parse(value, default=InteractionFamily.UNKNOWN)
        for value in values
    ))


def _complementarity_weights(value: Any = None) -> Mapping[str, float]:
    """Normalize coverage weights."""

    source = dict(_COMPLEMENTARITY_DEFAULT_WEIGHTS)
    if value is not None:
        if not isinstance(value, Mapping):
            raise VisualizationSpecificationError("Complementarity weights must be a mapping.")
        for key, raw in value.items():
            name = str(key).strip().lower()
            if name not in source:
                raise VisualizationSpecificationError(
                    "Unknown complementarity domain.", context={"domain": name}
                )
            source[name] = _bounded_float(
                raw, field_name=f"weights.{name}", minimum=0.0, maximum=1.0e6
            )
    total = sum(source.values())
    if total <= _COMPLEMENTARITY_EPSILON:
        raise VisualizationSpecificationError("At least one complementarity weight must be positive.")
    return MappingProxyType({key: weight / total for key, weight in source.items()})


def _complementarity_score(value: Any) -> Optional[float]:
    """Normalize an optional pose score."""

    return _optional_spec_float(value, field_name="score")


def _complementarity_residue_id(path: Optional[MolecularPathSpec]) -> Optional[str]:
    """Return a receptor residue identifier."""

    if path is None or path.residue_number is None:
        return None
    if path.role in {MolecularRole.LIGAND, MolecularRole.SOLVENT, MolecularRole.ION}:
        return None
    return _residue_id(path.parent() if path.atom_name else path)


def _complementarity_mapping_for_pose(value: Any, pose_id: str) -> Any:
    """Resolve pose-scoped source data."""

    if value is None:
        return None
    if isinstance(value, Mapping):
        if pose_id in value:
            return value[pose_id]
        for key in ("by_pose", "poses", "items"):
            nested = value.get(key)
            if isinstance(nested, Mapping) and pose_id in nested:
                return nested[pose_id]
    return value


@dataclass(frozen=True, slots=True)
class CoverageUniverseSpec(MolecularSpecMixin):
    """Joint feature universe."""

    residue_ids: Tuple[str, ...] = ()
    families: Tuple[InteractionFamily, ...] = ()
    interaction_types: Tuple[str, ...] = ()
    hotspot_ids: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "residue_ids", _complementarity_texts(
            self.residue_ids, field_name="residue_id"
        ))
        object.__setattr__(self, "families", _complementarity_families(self.families))
        object.__setattr__(self, "interaction_types", _complementarity_texts(
            self.interaction_types, field_name="interaction_type"
        ))
        object.__setattr__(self, "hotspot_ids", _complementarity_texts(
            self.hotspot_ids, field_name="hotspot_id"
        ))

    @property
    def counts(self) -> Mapping[str, int]:
        return MappingProxyType({
            "residues": len(self.residue_ids),
            "families": len(self.families),
            "interaction_types": len(self.interaction_types),
            "hotspots": len(self.hotspot_ids),
        })

    @property
    def total_count(self) -> int:
        return sum(self.counts.values())

    def domain(self, name: str) -> FrozenSet[Any]:
        aliases = {
            "residues": "residue_ids",
            "families": "families",
            "interaction_types": "interaction_types",
            "hotspots": "hotspot_ids",
        }
        attribute = aliases.get(name, name)
        if attribute not in {"residue_ids", "families", "interaction_types", "hotspot_ids"}:
            raise VisualizationSpecificationError(
                "Unknown coverage domain.", context={"domain": name}
            )
        return frozenset(getattr(self, attribute))


@dataclass(frozen=True, slots=True)
class PoseCoverageSpec(MolecularSpecMixin):
    """Feature coverage for one pose."""

    pose_id: str
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    residue_ids: Tuple[str, ...] = ()
    families: Tuple[InteractionFamily, ...] = ()
    interaction_types: Tuple[str, ...] = ()
    hotspot_ids: Tuple[str, ...] = ()
    interaction_ids: Tuple[str, ...] = ()
    score: Optional[float] = None
    affinity: Optional[float] = None
    rank: Optional[int] = None
    weight: float = 1.0
    color: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        pose_id = _clean_config_name(
            self.pose_id, field_name="pose_id", maximum=MAX_VISUALIZATION_NAME_LENGTH
        )
        rank = None if self.rank is None else _bounded_int(
            self.rank, field_name="rank", minimum=1, maximum=MAX_VISUAL_ELEMENTS
        )
        object.__setattr__(self, "pose_id", pose_id)
        object.__setattr__(self, "selection", coerce_selection(self.selection, strict=False))
        object.__setattr__(self, "residue_ids", _complementarity_texts(
            self.residue_ids, field_name="residue_id"
        ))
        object.__setattr__(self, "families", _complementarity_families(self.families))
        object.__setattr__(self, "interaction_types", _complementarity_texts(
            self.interaction_types, field_name="interaction_type"
        ))
        object.__setattr__(self, "hotspot_ids", _complementarity_texts(
            self.hotspot_ids, field_name="hotspot_id"
        ))
        object.__setattr__(self, "interaction_ids", _complementarity_texts(
            self.interaction_ids, field_name="interaction_id"
        ))
        object.__setattr__(self, "score", _complementarity_score(self.score))
        object.__setattr__(self, "affinity", _optional_spec_float(
            self.affinity, field_name="affinity"
        ))
        object.__setattr__(self, "rank", rank)
        object.__setattr__(self, "weight", _bounded_float(
            self.weight, field_name="weight", minimum=0.0, maximum=1.0e6
        ))
        object.__setattr__(self, "color", None if self.color is None else normalize_color(self.color))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def universe(self) -> CoverageUniverseSpec:
        return CoverageUniverseSpec(
            self.residue_ids, self.families, self.interaction_types, self.hotspot_ids
        )

    @property
    def feature_count(self) -> int:
        return self.universe.total_count

    def domain(self, name: str) -> FrozenSet[Any]:
        return self.universe.domain(name)


@dataclass(frozen=True, slots=True)
class PoseCoverageCollection(MolecularSpecMixin):
    """Validated pose-coverage collection."""

    poses: Tuple[PoseCoverageSpec, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        poses = tuple(coerce_pose_coverage_spec(value, index=index) for index, value in enumerate(self.poses))
        identifiers = [item.pose_id for item in poses]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Pose coverage identifiers must be unique.", context={"duplicates": duplicates}
            )
        object.__setattr__(self, "poses", poses)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    def __len__(self) -> int:
        return len(self.poses)

    def __iter__(self) -> Iterator[PoseCoverageSpec]:
        return iter(self.poses)

    @property
    def pose_ids(self) -> Tuple[str, ...]:
        return tuple(item.pose_id for item in self.poses)

    @property
    def pose_map(self) -> Mapping[str, PoseCoverageSpec]:
        return MappingProxyType({item.pose_id: item for item in self.poses})

    @property
    def universe(self) -> CoverageUniverseSpec:
        return CoverageUniverseSpec(
            residue_ids=tuple(dict.fromkeys(
                value for item in self.poses for value in item.residue_ids
            )),
            families=tuple(dict.fromkeys(
                value for item in self.poses for value in item.families
            )),
            interaction_types=tuple(dict.fromkeys(
                value for item in self.poses for value in item.interaction_types
            )),
            hotspot_ids=tuple(dict.fromkeys(
                value for item in self.poses for value in item.hotspot_ids
            )),
        )

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.poses)) if self.poses else MolecularSelection.none()


@dataclass(frozen=True, slots=True)
class ComplementarityStepSpec(MolecularSpecMixin):
    """One pose-set selection step."""

    index: int
    pose_id: str
    new_residue_ids: Tuple[str, ...] = ()
    new_families: Tuple[InteractionFamily, ...] = ()
    new_interaction_types: Tuple[str, ...] = ()
    new_hotspot_ids: Tuple[str, ...] = ()
    weighted_gain: float = 0.0
    marginal_fraction: float = 0.0
    cumulative_fraction: float = 0.0
    diversity_gain: float = 0.0
    objective_score: float = 0.0

    def __post_init__(self) -> None:
        object.__setattr__(self, "index", _bounded_int(
            self.index, field_name="index", minimum=1, maximum=MAX_VISUAL_ELEMENTS
        ))
        object.__setattr__(self, "pose_id", _clean_config_name(
            self.pose_id, field_name="pose_id", maximum=MAX_VISUALIZATION_NAME_LENGTH
        ))
        object.__setattr__(self, "new_residue_ids", _complementarity_texts(
            self.new_residue_ids, field_name="residue_id"
        ))
        object.__setattr__(self, "new_families", _complementarity_families(self.new_families))
        object.__setattr__(self, "new_interaction_types", _complementarity_texts(
            self.new_interaction_types, field_name="interaction_type"
        ))
        object.__setattr__(self, "new_hotspot_ids", _complementarity_texts(
            self.new_hotspot_ids, field_name="hotspot_id"
        ))
        for name in (
            "weighted_gain", "marginal_fraction", "cumulative_fraction",
            "diversity_gain", "objective_score",
        ):
            object.__setattr__(self, name, _bounded_float(
                getattr(self, name), field_name=name, minimum=0.0, maximum=1.0e6
            ))

    @property
    def new_feature_count(self) -> int:
        return sum((
            len(self.new_residue_ids), len(self.new_families),
            len(self.new_interaction_types), len(self.new_hotspot_ids),
        ))


@dataclass(frozen=True, slots=True)
class ComplementarityResult(MolecularSpecMixin):
    """Selected complementary pose set."""

    collection: PoseCoverageCollection = field(default_factory=PoseCoverageCollection)
    mode: ComplementarityMode = ComplementarityMode.GREEDY
    set_size: int = DEFAULT_COMPLEMENTARITY_SET_SIZE
    selected_pose_ids: Tuple[str, ...] = ()
    steps: Tuple[ComplementarityStepSpec, ...] = ()
    weights: Mapping[str, float] = field(default_factory=lambda: _COMPLEMENTARITY_DEFAULT_WEIGHTS)
    coverage: Mapping[str, float] = field(default_factory=dict)
    objective_score: float = 0.0
    exact: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = coerce_pose_coverage_collection(self.collection)
        selected = _complementarity_texts(self.selected_pose_ids, field_name="pose_id")
        missing = tuple(item for item in selected if item not in collection.pose_ids)
        if missing:
            raise VisualizationSpecificationError(
                "Selected complementary poses are not candidates.", context={"missing": missing}
            )
        steps = tuple(
            item if isinstance(item, ComplementarityStepSpec) else ComplementarityStepSpec(**dict(item))
            for item in self.steps
        )
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "mode", ComplementarityMode.parse(
            self.mode, default=ComplementarityMode.GREEDY
        ))
        object.__setattr__(self, "set_size", _bounded_int(
            self.set_size, field_name="set_size", minimum=1, maximum=MAX_VISUAL_ELEMENTS
        ))
        object.__setattr__(self, "selected_pose_ids", selected)
        object.__setattr__(self, "steps", steps)
        object.__setattr__(self, "weights", _complementarity_weights(self.weights))
        object.__setattr__(self, "coverage", MappingProxyType({
            str(key): _bounded_float(value, field_name=f"coverage.{key}", minimum=0.0, maximum=1.0)
            for key, value in dict(self.coverage).items()
        }))
        object.__setattr__(self, "objective_score", _bounded_float(
            self.objective_score, field_name="objective_score", minimum=0.0, maximum=1.0e6
        ))
        object.__setattr__(self, "exact", bool(self.exact))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def selected(self) -> Tuple[PoseCoverageSpec, ...]:
        pose_map = self.collection.pose_map
        return tuple(pose_map[pose_id] for pose_id in self.selected_pose_ids)

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.selected)) if self.selected else MolecularSelection.none()

    @property
    def coverage_fraction(self) -> float:
        return sum(self.weights.get(key, 0.0) * self.coverage.get(key, 0.0) for key in self.weights)


