def coerce_pose_coverage_spec(value: Any, *, index: int = 0) -> PoseCoverageSpec:
    """Coerce one pose coverage."""

    if isinstance(value, PoseCoverageSpec):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("pose_id", f"pose_{index + 1}")
        return PoseCoverageSpec(**data)
    if isinstance(value, PoseVisualSpec):
        return PoseCoverageSpec(
            pose_id=value.pose_id,
            selection=value.selection,
            score=value.score,
            affinity=value.affinity,
            rank=value.rank,
            color=value.color,
            interaction_ids=value.interaction_ids,
            metadata=value.metadata,
        )
    return PoseCoverageSpec(
        pose_id=_object_value(value, "pose_id", "id", "identifier", default=f"pose_{index + 1}"),
        selection=_object_value(value, "selection", "atomspec", default=MolecularSelection.none()),
        residue_ids=_object_value(value, "residue_ids", "residues", default=()),
        families=_object_value(value, "families", default=()),
        interaction_types=_object_value(value, "interaction_types", "types", default=()),
        hotspot_ids=_object_value(value, "hotspot_ids", "hotspots", default=()),
        interaction_ids=_object_value(value, "interaction_ids", default=()),
        score=_object_value(value, "score", default=None),
        affinity=_object_value(value, "affinity", "binding_affinity", default=None),
        rank=_object_value(value, "rank", default=None),
        color=_object_value(value, "color", default=None),
        metadata=_object_value(value, "metadata", default={}),
    )


def coerce_pose_coverage_collection(value: Any) -> PoseCoverageCollection:
    """Coerce pose coverage data."""

    if isinstance(value, PoseCoverageCollection):
        return value
    if isinstance(value, ComplementarityResult):
        return value.collection
    if isinstance(value, ComplementarityVisualizationSpec):
        return value.result.collection
    if value is None:
        return PoseCoverageCollection()
    if isinstance(value, Mapping):
        if "poses" in value and set(value).issubset({"poses", "metadata"}):
            return PoseCoverageCollection(**dict(value))
        poses = []
        for index, (pose_id, item) in enumerate(value.items()):
            if isinstance(item, Mapping):
                poses.append(coerce_pose_coverage_spec({"pose_id": pose_id, **dict(item)}, index=index))
            else:
                poses.append(coerce_pose_coverage_spec(item, index=index).updated(pose_id=str(pose_id)))
        return PoseCoverageCollection(tuple(poses))
    if isinstance(value, PoseCoverageSpec):
        return PoseCoverageCollection((value,))
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        return PoseCoverageCollection(tuple(
            coerce_pose_coverage_spec(item, index=index) for index, item in enumerate(value)
        ))
    try:
        visual = coerce_pose_visual_collection(value)
    except VisualizationError as exc:
        raise VisualizationSpecificationError(
            "Cannot coerce pose coverage collection.", context={"type": type(value).__name__}
        ) from exc
    return PoseCoverageCollection(tuple(coerce_pose_coverage_spec(item) for item in visual.poses))


def _coverage_interaction_features(
    value: Any,
    pose_id: str,
) -> Tuple[Tuple[str, ...], Tuple[InteractionFamily, ...], Tuple[str, ...], Tuple[str, ...]]:
    """Extract interaction-derived features."""

    source = _complementarity_mapping_for_pose(value, pose_id)
    if source is None:
        return (), (), (), ()
    collection = _coerce_interaction_collection(source, pose_id=pose_id)
    interactions = tuple(
        item for item in collection.interactions
        if item.pose_id in {None, pose_id} or collection.pose_id == pose_id
    )
    residue_ids: List[str] = []
    families: List[InteractionFamily] = []
    types: List[str] = []
    identifiers: List[str] = []
    for item in interactions:
        identifiers.append(item.interaction_id)
        families.append(item.family)
        types.append(item.subtype or item.family.value)
        for endpoint in (item.source, item.target):
            residue_id = _complementarity_residue_id(endpoint.path)
            if residue_id:
                residue_ids.append(residue_id)
    return (
        tuple(dict.fromkeys(residue_ids)),
        tuple(dict.fromkeys(families)),
        tuple(dict.fromkeys(types)),
        tuple(dict.fromkeys(identifiers)),
    )


def _coverage_residue_features(value: Any, pose_id: str) -> Tuple[str, ...]:
    """Extract pose-specific residue identifiers."""

    source = _complementarity_mapping_for_pose(value, pose_id)
    if source is None:
        return ()
    collection = coerce_involved_residue_collection(source)
    return tuple(dict.fromkeys(
        item.residue_id for item in collection.residues
        if not item.pose_ids or pose_id in item.pose_ids
    ))


def _coverage_hotspot_features(value: Any, pose_id: str) -> Tuple[str, ...]:
    """Extract pose-specific hotspot identifiers."""

    source = _complementarity_mapping_for_pose(value, pose_id)
    if source is None:
        return ()
    collection = coerce_hotspot_collection(source)
    return tuple(dict.fromkeys(
        item.hotspot_id for item in collection.hotspots
        if not item.pose_ids or pose_id in item.pose_ids
    ))


def build_pose_coverage_collection(
    value: Any,
    *,
    interactions: Any = None,
    residues: Any = None,
    hotspots: Any = None,
    scores: Any = None,
) -> PoseCoverageCollection:
    """Build feature coverage for all poses."""

    if isinstance(value, PoseCoverageCollection) and all(
        source is None for source in (interactions, residues, hotspots, scores)
    ):
        return value
    try:
        visual = coerce_pose_visual_collection(value, scores=scores, interactions=interactions)
        base = tuple(coerce_pose_coverage_spec(item, index=index) for index, item in enumerate(visual.poses))
    except (VisualizationError, TypeError, ValueError):
        base = coerce_pose_coverage_collection(value).poses
    score_map = _pose_score_map(scores)
    output: List[PoseCoverageSpec] = []
    for item in base:
        residue_ids, families, interaction_types, interaction_ids = _coverage_interaction_features(
            interactions, item.pose_id
        )
        residue_ids = tuple(dict.fromkeys((*item.residue_ids, *residue_ids, *_coverage_residue_features(
            residues, item.pose_id
        ))))
        hotspot_ids = tuple(dict.fromkeys((*item.hotspot_ids, *_coverage_hotspot_features(
            hotspots, item.pose_id
        ))))
        score_item = score_map.get(item.pose_id)
        output.append(replace(
            item,
            residue_ids=residue_ids,
            families=tuple(dict.fromkeys((*item.families, *families))),
            interaction_types=tuple(dict.fromkeys((*item.interaction_types, *interaction_types))),
            hotspot_ids=hotspot_ids,
            interaction_ids=tuple(dict.fromkeys((*item.interaction_ids, *interaction_ids))),
            score=item.score if item.score is not None else (score_item.score if score_item else None),
        ))
    return PoseCoverageCollection(
        tuple(output), metadata={"source_count": len(base)}
    )


def _coverage_union(poses: Iterable[PoseCoverageSpec]) -> CoverageUniverseSpec:
    """Return joint pose coverage."""

    values = tuple(poses)
    return CoverageUniverseSpec(
        residue_ids=tuple(dict.fromkeys(item for pose in values for item in pose.residue_ids)),
        families=tuple(dict.fromkeys(item for pose in values for item in pose.families)),
        interaction_types=tuple(dict.fromkeys(item for pose in values for item in pose.interaction_types)),
        hotspot_ids=tuple(dict.fromkeys(item for pose in values for item in pose.hotspot_ids)),
    )


def _coverage_fractions(
    covered: CoverageUniverseSpec,
    universe: CoverageUniverseSpec,
) -> Mapping[str, float]:
    """Return per-domain coverage fractions."""

    output: Dict[str, float] = {}
    for name in _COMPLEMENTARITY_DEFAULT_WEIGHTS:
        total = len(universe.domain(name))
        output[name] = 1.0 if total == 0 else len(covered.domain(name)) / total
    return MappingProxyType(output)


def _weighted_coverage_fraction(
    covered: CoverageUniverseSpec,
    universe: CoverageUniverseSpec,
    weights: Mapping[str, float],
) -> float:
    fractions = _coverage_fractions(covered, universe)
    return sum(weights[name] * fractions[name] for name in weights)


def pose_coverage_similarity(left: Any, right: Any) -> float:
    """Return weighted Jaccard similarity."""

    left_pose = coerce_pose_coverage_spec(left)
    right_pose = coerce_pose_coverage_spec(right)
    similarity = 0.0
    for name, weight in _COMPLEMENTARITY_DEFAULT_WEIGHTS.items():
        left_set, right_set = left_pose.domain(name), right_pose.domain(name)
        union = left_set | right_set
        overlap = 1.0 if not union else len(left_set & right_set) / len(union)
        similarity += weight * overlap
    return similarity


def pose_coverage_distance(left: Any, right: Any) -> float:
    """Return weighted Jaccard distance."""

    return 1.0 - pose_coverage_similarity(left, right)


def _normalized_candidate_scores(collection: PoseCoverageCollection) -> Mapping[str, float]:
    values = [item.score for item in collection.poses if item.score is not None]
    if not values:
        return MappingProxyType({item.pose_id: 0.0 for item in collection.poses})
    minimum, maximum = min(values), max(values)
    span = maximum - minimum
    return MappingProxyType({
        item.pose_id: 0.5 if item.score is None or span <= _COMPLEMENTARITY_EPSILON
        else (item.score - minimum) / span
        for item in collection.poses
    })


def _pose_set_objective(
    poses: Sequence[PoseCoverageSpec],
    *,
    universe: CoverageUniverseSpec,
    weights: Mapping[str, float],
    score_positions: Mapping[str, float],
    score_weight: float,
    diversity_weight: float,
) -> float:
    if not poses:
        return 0.0
    coverage = _weighted_coverage_fraction(_coverage_union(poses), universe, weights)
    score = statistics.fmean(score_positions.get(item.pose_id, 0.0) for item in poses)
    pairs = [
        pose_coverage_distance(left, right)
        for index, left in enumerate(poses)
        for right in poses[index + 1:]
    ]
    diversity = statistics.fmean(pairs) if pairs else 0.0
    return coverage + score_weight * score + diversity_weight * diversity


def _complementarity_steps(
    selected: Sequence[PoseCoverageSpec],
    *,
    universe: CoverageUniverseSpec,
    weights: Mapping[str, float],
    score_positions: Mapping[str, float],
    score_weight: float,
    diversity_weight: float,
) -> Tuple[ComplementarityStepSpec, ...]:
    """Build ordered marginal-gain steps."""

    previous = CoverageUniverseSpec()
    chosen: List[PoseCoverageSpec] = []
    steps: List[ComplementarityStepSpec] = []
    for index, pose in enumerate(selected, 1):
        current = _coverage_union((*chosen, pose))
        before = _weighted_coverage_fraction(previous, universe, weights)
        after = _weighted_coverage_fraction(current, universe, weights)
        diversity = statistics.fmean(
            pose_coverage_distance(pose, item) for item in chosen
        ) if chosen else 0.0
        steps.append(ComplementarityStepSpec(
            index=index,
            pose_id=pose.pose_id,
            new_residue_ids=tuple(sorted(pose.domain("residue_ids") - previous.domain("residue_ids"))),
            new_families=tuple(sorted(
                pose.domain("families") - previous.domain("families"), key=lambda item: item.value
            )),
            new_interaction_types=tuple(sorted(
                pose.domain("interaction_types") - previous.domain("interaction_types")
            )),
            new_hotspot_ids=tuple(sorted(
                pose.domain("hotspot_ids") - previous.domain("hotspot_ids")
            )),
            weighted_gain=max(0.0, after - before),
            marginal_fraction=max(0.0, after - before),
            cumulative_fraction=after,
            diversity_gain=diversity,
            objective_score=_pose_set_objective(
                (*chosen, pose), universe=universe, weights=weights,
                score_positions=score_positions, score_weight=score_weight,
                diversity_weight=diversity_weight,
            ),
        ))
        chosen.append(pose)
        previous = current
    return tuple(steps)


def _greedy_complementary_poses(
    collection: PoseCoverageCollection,
    *,
    set_size: int,
    universe: CoverageUniverseSpec,
    weights: Mapping[str, float],
    score_positions: Mapping[str, float],
    score_weight: float,
    diversity_weight: float,
) -> Tuple[PoseCoverageSpec, ...]:
    """Select a complementary set greedily."""

    remaining = list(collection.poses)
    selected: List[PoseCoverageSpec] = []
    while remaining and len(selected) < set_size:
        ranked = sorted(
            remaining,
            key=lambda pose: (
                -_pose_set_objective(
                    (*selected, pose), universe=universe, weights=weights,
                    score_positions=score_positions, score_weight=score_weight,
                    diversity_weight=diversity_weight,
                ),
                pose.rank if pose.rank is not None else MAX_VISUAL_ELEMENTS,
                -(pose.score if pose.score is not None else -math.inf),
                pose.pose_id,
            ),
        )
        selected.append(ranked[0])
        remaining.remove(ranked[0])
    return tuple(selected)


def select_complementary_poses(
    value: Any,
    *,
    mode: Any = ComplementarityMode.GREEDY,
    set_size: int = DEFAULT_COMPLEMENTARITY_SET_SIZE,
    weights: Any = None,
    selected_pose_ids: Iterable[Any] = (),
    score_weight: float = 0.05,
    diversity_weight: Optional[float] = None,
    interactions: Any = None,
    residues: Any = None,
    hotspots: Any = None,
    scores: Any = None,
) -> ComplementarityResult:
    """Select poses maximizing joint coverage."""

    collection = build_pose_coverage_collection(
        value, interactions=interactions, residues=residues, hotspots=hotspots, scores=scores
    )
    parsed_mode = ComplementarityMode.parse(mode, default=ComplementarityMode.GREEDY)
    count = min(_bounded_int(
        set_size, field_name="set_size", minimum=1, maximum=MAX_VISUAL_ELEMENTS
    ), max(1, len(collection)))
    normalized_weights = _complementarity_weights(weights)
    score_weight = _bounded_float(
        score_weight, field_name="score_weight", minimum=0.0, maximum=1.0e3
    )
    if parsed_mode is ComplementarityMode.COVERAGE:
        score_weight = 0.0
        diversity_weight = 0.0
    elif diversity_weight is None:
        diversity_weight = 0.20 if parsed_mode is ComplementarityMode.DIVERSE else 0.05
    diversity_weight = _bounded_float(
        diversity_weight, field_name="diversity_weight", minimum=0.0, maximum=1.0e3
    )
    universe = collection.universe
    score_positions = _normalized_candidate_scores(collection)
    exact = False
    requested = _complementarity_texts(selected_pose_ids, field_name="pose_id")
    pose_map = collection.pose_map
    if parsed_mode is ComplementarityMode.MANUAL:
        missing = tuple(item for item in requested if item not in pose_map)
        if missing:
            raise VisualizationSpecificationError(
                "Manual complementary poses are not candidates.", context={"missing": missing}
            )
        selected = tuple(pose_map[item] for item in requested[:count])
    elif parsed_mode is ComplementarityMode.OPTIMAL and len(collection) <= _COMPLEMENTARITY_MAX_EXACT_CANDIDATES:
        from itertools import combinations as _combinations

        candidate_sets = _combinations(collection.poses, count)
        selected = max(
            candidate_sets,
            key=lambda items: (
                _pose_set_objective(
                    items, universe=universe, weights=normalized_weights,
                    score_positions=score_positions, score_weight=score_weight,
                    diversity_weight=diversity_weight,
                ),
                tuple(item.pose_id for item in items),
            ),
            default=(),
        )
        exact = True
    else:
        selected = _greedy_complementary_poses(
            collection,
            set_size=count,
            universe=universe,
            weights=normalized_weights,
            score_positions=score_positions,
            score_weight=score_weight,
            diversity_weight=diversity_weight,
        )
    covered = _coverage_union(selected)
    coverage = _coverage_fractions(covered, universe)
    steps = _complementarity_steps(
        selected,
        universe=universe,
        weights=normalized_weights,
        score_positions=score_positions,
        score_weight=score_weight,
        diversity_weight=diversity_weight,
    )
    objective = _pose_set_objective(
        selected, universe=universe, weights=normalized_weights,
        score_positions=score_positions, score_weight=score_weight,
        diversity_weight=diversity_weight,
    )
    return ComplementarityResult(
        collection=collection,
        mode=parsed_mode,
        set_size=count,
        selected_pose_ids=tuple(item.pose_id for item in selected),
        steps=steps,
        weights=normalized_weights,
        coverage=coverage,
        objective_score=objective,
        exact=exact,
        metadata={
            "candidate_count": len(collection),
            "score_weight": score_weight,
            "diversity_weight": diversity_weight,
            "optimal_fallback": parsed_mode is ComplementarityMode.OPTIMAL and not exact,
        },
    )


def coerce_complementarity_result(value: Any) -> ComplementarityResult:
    """Coerce a complementarity result."""

    if isinstance(value, ComplementarityResult):
        return value
    if isinstance(value, ComplementarityVisualizationSpec):
        return value.result
    if isinstance(value, Mapping) and "collection" in value:
        return ComplementarityResult(**dict(value))
    return select_complementary_poses(value)


def build_complementarity_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    representation: Any = None,
    color_mode: Any = PoseColorMode.POSE,
    pose_colors: Optional[Iterable[Any]] = None,
    single_color: Any = None,
    active_opacity: Optional[float] = None,
    inactive_opacity: Optional[float] = None,
    shared_color: Any = _COMPLEMENTARITY_SHARED_COLOR,
    unique_color: Any = _COMPLEMENTARITY_UNIQUE_COLOR,
    show_labels: bool = True,
    show_coverage: bool = True,
    show_marginal_features: bool = True,
    group_name: str = "DockAnalyzer complementary poses",
    enabled: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
    **selection_options: Any,
) -> ComplementarityVisualizationSpec:
    """Build complementarity display settings."""

    if isinstance(value, ComplementarityVisualizationSpec) and not selection_options:
        return value
    config_obj = resolve_visualization_config(config_value)
    result = value if isinstance(value, ComplementarityResult) else select_complementary_poses(
        value, **selection_options
    )
    return ComplementarityVisualizationSpec(
        result=result,
        representation=MolecularRepresentation.parse(
            representation,
            default=config_obj.style_for(MolecularRole.LIGAND).representation,
        ),
        color_mode=PoseColorMode.parse(color_mode, default=PoseColorMode.POSE),
        pose_colors=tuple(pose_colors) if pose_colors is not None else config_obj.multipose.pose_colors,
        single_color=single_color or config_obj.style_for(MolecularRole.LIGAND).color,
        active_opacity=config_obj.multipose.active_opacity if active_opacity is None else active_opacity,
        inactive_opacity=config_obj.multipose.inactive_opacity if inactive_opacity is None else inactive_opacity,
        shared_color=shared_color,
        unique_color=unique_color,
        show_labels=show_labels,
        show_coverage=show_coverage,
        show_marginal_features=show_marginal_features,
        group_name=group_name,
        enabled=enabled,
        metadata=metadata or {},
    )


def coerce_complementarity_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    **overrides: Any,
) -> ComplementarityVisualizationSpec:
    """Coerce complementarity display settings."""

    if isinstance(value, ComplementarityVisualizationSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping) and "result" in value:
        spec = ComplementarityVisualizationSpec(**dict(value))
        return replace(spec, **overrides) if overrides else spec
    return build_complementarity_visualization_spec(
        value, config_value=config_value, **overrides
    )


def complementarity_pairwise_matrix(value: Any) -> Mapping[str, Mapping[str, float]]:
    """Return pairwise pose distances."""

    collection = coerce_pose_coverage_collection(value)
    return MappingProxyType({
        left.pose_id: MappingProxyType({
            right.pose_id: pose_coverage_distance(left, right)
            for right in collection.poses
        })
        for left in collection.poses
    })


def _complementarity_pose_color(
    pose: PoseCoverageSpec,
    *,
    index: int,
    spec: ComplementarityVisualizationSpec,
) -> str:
    if pose.color:
        return pose.color
    if spec.color_mode is PoseColorMode.SINGLE:
        return spec.single_color
    if spec.color_mode is PoseColorMode.SCORE:
        return _score_palette_color(
            _normalized_candidate_scores(spec.result.collection).get(pose.pose_id),
            resolve_visualization_config(None).scoring.palette,
            resolve_visualization_config(None).scoring.missing_color,
        )
    if spec.color_mode is PoseColorMode.RANK:
        rank = pose.rank or index + 1
        return spec.pose_colors[(rank - 1) % len(spec.pose_colors)]
    if spec.color_mode is PoseColorMode.CLUSTER:
        key = str(pose.metadata.get("cluster_id") or pose.pose_id)
        return _stable_palette_color(key, spec.pose_colors)
    return spec.pose_colors[index % len(spec.pose_colors)]


def _complementarity_dependencies(plan: VisualizationPlan) -> Tuple[str, ...]:
    """Resolve existing pose dependencies."""

    preferred = (
        _MULTIPOSE_GROUP_ACTION, "ligand:base", "receptor:focus",
        "receptor:base", "scene:prepare",
    )
    return tuple(action_id for action_id in preferred if action_id in plan.action_map)


def build_complementarity_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert complementarity to plan actions."""

    spec = coerce_complementarity_visualization_spec(value, config_value=config_value)
    dependencies = _action_dependencies(depends_on)
    steps = {item.pose_id: item for item in spec.result.steps}
    actions: List[VisualizationAction] = []
    pose_action_ids: List[str] = []
    selected = spec.result.selected
    for index, pose in enumerate(selected):
        step = steps.get(pose.pose_id)
        action_id = f"{_COMPLEMENTARITY_ACTION_PREFIX}pose:{_multipose_action_suffix(pose.pose_id, index=index)}"
        pose_action_ids.append(action_id)
        actions.append(VisualizationAction(
            action_id=action_id,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=pose.selection,
            parameters={
                "component": "complementary_pose",
                "pose_id": pose.pose_id,
                "selection_index": index + 1,
                "representation": spec.representation.value,
                "color": _complementarity_pose_color(pose, index=index, spec=spec),
                "opacity": spec.active_opacity if index == 0 else spec.inactive_opacity,
                "group_name": spec.group_name,
                "score": pose.score,
                "affinity": pose.affinity,
                "rank": pose.rank,
                "marginal": None if step is None else step.to_dict(),
                "show_marginal_features": spec.show_marginal_features,
                "unique_color": spec.unique_color,
                "shared_color": spec.shared_color,
            },
            depends_on=dependencies,
            priority=OperationPriority.HIGH if index == 0 else OperationPriority.NORMAL,
            enabled=spec.enabled and not pose.selection.is_none,
            optional=pose.selection.is_none,
            description=f"Display complementary pose {pose.pose_id}.",
            tags=("complementarity", "pose"),
        ))
    if spec.show_coverage:
        actions.append(VisualizationAction(
            action_id=_COMPLEMENTARITY_SUMMARY_ACTION,
            operation=PlanOperation.SHOW_MULTIPOSE,
            layer=VisualLayer.LIGAND,
            selection=spec.selection,
            parameters={
                "component": "complementarity_summary",
                "mode": spec.result.mode.value,
                "selected_pose_ids": spec.result.selected_pose_ids,
                "coverage": dict(spec.result.coverage),
                "coverage_fraction": spec.result.coverage_fraction,
                "objective_score": spec.result.objective_score,
                "weights": dict(spec.result.weights),
                "exact": spec.result.exact,
                "steps": tuple(item.to_dict() for item in spec.result.steps),
                "group_name": spec.group_name,
            },
            depends_on=tuple(pose_action_ids) or dependencies,
            priority=OperationPriority.NORMAL,
            enabled=spec.enabled,
            optional=True,
            description="Summarize complementary pose coverage.",
            tags=("complementarity", "coverage"),
        ))
    if spec.show_labels and selected:
        actions.append(VisualizationAction(
            action_id=_COMPLEMENTARITY_LABEL_ACTION,
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=spec.selection,
            parameters={
                "component": "complementarity_labels",
                "labels": tuple({
                    "pose_id": pose.pose_id,
                    "selection": pose.selection.expression,
                    "text": f"{index + 1}. {pose.pose_id}",
                    "gain": steps[pose.pose_id].weighted_gain if pose.pose_id in steps else 0.0,
                    "coverage": steps[pose.pose_id].cumulative_fraction if pose.pose_id in steps else 0.0,
                    "color": _complementarity_pose_color(pose, index=index, spec=spec),
                } for index, pose in enumerate(selected)),
            },
            depends_on=tuple(pose_action_ids),
            priority=OperationPriority.LOW,
            enabled=spec.enabled,
            optional=True,
            description="Label complementary poses.",
            tags=("complementarity", "labels"),
        ))
    return tuple(actions)


def build_complementarity_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "complementarity-visualization",
    name: str = "Complementarity visualization",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **overrides: Any,
) -> VisualizationPlan:
    """Build a standalone complementarity plan."""

    spec = coerce_complementarity_visualization_spec(
        value, config_value=config_value, **overrides
    )
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_complementarity_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display complementary docking poses and joint coverage.",
        metadata={"complementarity": spec.to_dict(), **dict(metadata or {})},
    )


def attach_complementarity(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
    **overrides: Any,
) -> VisualizationPlan:
    """Attach complementarity actions to a plan."""

    base = coerce_visualization_plan(plan)
    spec = coerce_complementarity_visualization_spec(
        value, config_value=config_value, **overrides
    )
    existing = tuple(
        action for action in base.actions
        if action.action_id.startswith(_COMPLEMENTARITY_ACTION_PREFIX)
    )
    if existing and not replace_existing:
        raise VisualizationPlanError("Complementarity actions already exist.")
    actions = [
        action for action in base.actions
        if not action.action_id.startswith(_COMPLEMENTARITY_ACTION_PREFIX)
    ]
    actions.extend(build_complementarity_actions(
        spec,
        config_value=config_value,
        depends_on=_complementarity_dependencies(base),
    ))
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "complementarity": spec.to_dict()},
    )


def visualize_complementarity(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach complementarity visualization."""

    return (
        build_complementarity_plan(value, config_value=config_value, **kwargs)
        if plan is None
        else attach_complementarity(plan, value, config_value=config_value, **kwargs)
    )


def validate_complementarity(
    value: Any,
    *,
    config_value: Any = None,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate complementarity semantics."""

    spec = coerce_complementarity_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    result = spec.result
    if spec.enabled and not result.collection.poses:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "complementarity_candidates_empty",
            "No poses are available for complementarity analysis.",
            _COMPLEMENTARITY_SUMMARY_ACTION,
        ))
    if spec.enabled and result.collection.poses and not result.selected_pose_ids:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "complementarity_selection_empty",
            "No complementary poses were selected.",
            _COMPLEMENTARITY_SUMMARY_ACTION,
        ))
    if result.collection.universe.total_count == 0:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "complementarity_features_empty",
            "Candidate poses have no coverage features.",
            _COMPLEMENTARITY_SUMMARY_ACTION,
        ))
    if result.mode is ComplementarityMode.OPTIMAL and not result.exact:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "complementarity_optimal_fallback",
            "Exact selection exceeded the candidate limit and used greedy selection.",
            _COMPLEMENTARITY_SUMMARY_ACTION,
        ))
    if any(item.selection.is_none for item in result.selected):
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "complementarity_selection_missing",
            "Some selected poses lack molecular selections.",
            "complementarity:pose",
        ))
    return tuple(issues)


def summarize_complementarity(
    value: Any,
    *,
    config_value: Any = None,
) -> Dict[str, Any]:
    """Return compact complementarity statistics."""

    spec = coerce_complementarity_visualization_spec(value, config_value=config_value)
    result = spec.result
    issues = validate_complementarity(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "mode": result.mode.value,
        "candidate_count": len(result.collection),
        "selected_count": len(result.selected_pose_ids),
        "selected_pose_ids": result.selected_pose_ids,
        "set_size": result.set_size,
        "coverage": dict(result.coverage),
        "coverage_fraction": result.coverage_fraction,
        "objective_score": result.objective_score,
        "exact": result.exact,
        "universe_counts": dict(result.collection.universe.counts),
        "marginal_gains": tuple(item.weighted_gain for item in result.steps),
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def complementarity_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize complementarity visualization."""

    return coerce_complementarity_visualization_spec(
        value, config_value=config_value
    ).to_dict()


def complementarity_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize complementarity visualization as JSON."""

    return json.dumps(
        complementarity_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


