# =============================================================================
# 21. Labels and annotations
# =============================================================================

_ANNOTATION_ACTION_PREFIX: Final[str] = "labels:"
_ANNOTATION_MOLECULAR_ACTION: Final[str] = "labels:molecular"
_ANNOTATION_POINT_ACTION: Final[str] = "labels:points"
_ANNOTATION_SCREEN_ACTION: Final[str] = "labels:screen"
_ANNOTATION_LEGEND_ACTION: Final[str] = "labels:legend"
_ANNOTATION_MAX_ITEMS: Final[int] = 5000
_ANNOTATION_MAX_LEGENDS: Final[int] = 32
_ANNOTATION_MAX_LEGEND_ENTRIES: Final[int] = 128
_ANNOTATION_SCREEN_POSITIONS: Final[Tuple[str, ...]] = (
    "top_left", "top_center", "top_right", "center_left", "center",
    "center_right", "bottom_left", "bottom_center", "bottom_right",
)
_ANNOTATION_LEGEND_POSITIONS: Final[Tuple[str, ...]] = (
    "top_left", "top_right", "bottom_left", "bottom_right",
)
_ANNOTATION_DEFAULT_GROUP: Final[str] = DEFAULT_LABEL_GROUP
_ANNOTATION_DEFAULT_BACKGROUND: Final[str] = COLOR_WHITE
_ANNOTATION_DEFAULT_BORDER: Final[str] = COLOR_GRAY
_ANNOTATION_DEFAULT_PADDING: Final[float] = 4.0
_ANNOTATION_DEFAULT_LINE_WIDTH: Final[float] = 1.0
_ANNOTATION_DEFAULT_OFFSET_STEP: Final[Point3D] = (0.0, 0.35, 0.0)


def _annotation_text(
    value: Any,
    *,
    field_name: str,
    required: bool = False,
    maximum: int = MAX_LABEL_TEXT_LENGTH,
) -> Optional[str]:
    """Normalize annotation text."""

    if value is None:
        if required:
            raise VisualizationSpecificationError(f"{field_name} is required.")
        return None
    text = str(value).strip()
    if not text:
        if required:
            raise VisualizationSpecificationError(f"{field_name} cannot be empty.")
        return None
    if any(ord(char) < 32 and char not in "\t\n" for char in text):
        raise VisualizationSpecificationError(f"{field_name} contains control characters.")
    if len(text) > maximum:
        raise VisualizationLimitError(
            f"{field_name} exceeds {maximum} characters.",
            context={"field": field_name, "length": len(text), "maximum": maximum},
        )
    return text


def _annotation_identifier(value: Any, *, field_name: str = "annotation_id") -> str:
    """Normalize a stable annotation identifier."""

    text = _annotation_text(value, field_name=field_name, required=True, maximum=256)
    assert text is not None
    cleaned = re.sub(r"[^A-Za-z0-9_.:-]+", "-", text).strip("-.:_")
    if not cleaned:
        raise VisualizationSpecificationError(f"{field_name} is invalid.")
    return cleaned


def _annotation_mapping(value: Any, *, field_name: str) -> Mapping[str, Any]:
    """Freeze annotation metadata."""

    if value is None:
        return MappingProxyType({})
    if not isinstance(value, Mapping):
        raise VisualizationSpecificationError(f"{field_name} must be a mapping.")
    return MappingProxyType(dict(value))


def _annotation_tags(values: Any) -> Tuple[str, ...]:
    """Normalize annotation tags."""

    if values is None:
        return ()
    if isinstance(values, str):
        values = (values,)
    tags: List[str] = []
    for value in values:
        text = _annotation_text(value, field_name="tag", maximum=128)
        if text and text not in tags:
            tags.append(text)
    return tuple(tags)


def _annotation_screen_position(value: Any) -> Optional[Tuple[float, float]]:
    """Normalize a relative screen coordinate."""

    if value is None:
        return None
    if isinstance(value, Mapping):
        value = (value.get("x"), value.get("y"))
    try:
        position = tuple(float(item) for item in value)
    except (TypeError, ValueError) as exc:
        raise VisualizationCoordinateError("screen_position must contain two values.", cause=exc) from exc
    if len(position) != 2 or not all(math.isfinite(item) for item in position):
        raise VisualizationCoordinateError("screen_position must contain two finite values.")
    if not all(0.0 <= item <= 1.0 for item in position):
        raise VisualizationCoordinateError("screen_position values must be between 0 and 1.")
    return position  # type: ignore[return-value]


def _annotation_offset(value: Any) -> Point3D:
    """Normalize a label offset."""

    point = normalize_point3d(value, field_name="offset")
    assert point is not None
    return point


def _annotation_format(template: str, values: Mapping[str, Any]) -> str:
    """Format a label without failing on missing fields."""

    class _SafeValues(dict):
        def __missing__(self, key: str) -> str:
            return "{" + key + "}"

    try:
        text = template.format_map(_SafeValues(values))
    except (ValueError, TypeError, KeyError, AttributeError) as exc:
        raise VisualizationSpecificationError(
            "Could not format annotation text.",
            context={"template": template},
            cause=exc,
        ) from exc
    return text[:MAX_LABEL_TEXT_LENGTH]


@dataclass(frozen=True, slots=True)
class AnnotationStyleSpec(MolecularSpecMixin):
    """Label appearance."""

    font: str = DEFAULT_LABEL_FONT
    font_size: int = DEFAULT_LABEL_FONT_SIZE
    color: str = DEFAULT_LABEL_COLOR
    opacity: float = DEFAULT_LABEL_OPACITY
    background_color: Optional[str] = None
    background_opacity: float = 0.0
    border_color: Optional[str] = None
    border_width: float = 0.0
    padding: float = _ANNOTATION_DEFAULT_PADDING
    offset: Point3D = DEFAULT_LABEL_OFFSET
    billboard: bool = True
    bold: bool = False
    italic: bool = False
    shadow: bool = False

    def __post_init__(self) -> None:
        font = _annotation_text(self.font, field_name="font", required=True, maximum=128)
        object.__setattr__(self, "font", font)
        object.__setattr__(self, "font_size", _bounded_int(
            self.font_size, field_name="font_size", minimum=1, maximum=512
        ))
        object.__setattr__(self, "color", normalize_color(self.color, field_name="color"))
        object.__setattr__(self, "opacity", _bounded_float(
            self.opacity, field_name="opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "background_color", None if self.background_color is None else normalize_color(
            self.background_color, field_name="background_color"
        ))
        object.__setattr__(self, "background_opacity", _bounded_float(
            self.background_opacity, field_name="background_opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "border_color", None if self.border_color is None else normalize_color(
            self.border_color, field_name="border_color"
        ))
        object.__setattr__(self, "border_width", _bounded_float(
            self.border_width, field_name="border_width", minimum=0.0, maximum=100.0
        ))
        object.__setattr__(self, "padding", _bounded_float(
            self.padding, field_name="padding", minimum=0.0, maximum=100.0
        ))
        object.__setattr__(self, "offset", _annotation_offset(self.offset))
        for name in ("billboard", "bold", "italic", "shadow"):
            object.__setattr__(self, name, bool(getattr(self, name)))

    @classmethod
    def from_config(cls, value: Any = None, **overrides: Any) -> "AnnotationStyleSpec":
        """Build style from visual configuration."""

        config_obj = resolve_visualization_config(value)
        labels = config_obj.labels
        data = {
            "font": labels.font,
            "font_size": labels.font_size,
            "color": labels.color,
            "opacity": labels.opacity,
            "offset": labels.offset,
        }
        data.update(overrides)
        return cls(**data)


@dataclass(frozen=True, slots=True)
class AnnotationTargetSpec(MolecularSpecMixin):
    """Label attachment target."""

    anchor: LabelAnchor = LabelAnchor.POINT
    selection: MolecularSelection = field(default_factory=MolecularSelection.none)
    point: Optional[Point3D] = None
    screen_position: Optional[Tuple[float, float]] = None
    screen_region: Optional[str] = None
    interaction_id: Optional[str] = None
    source_id: Optional[str] = None
    model_id: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        anchor = LabelAnchor.parse(self.anchor, default=LabelAnchor.POINT)
        selection = coerce_selection(self.selection, strict=False)
        point = normalize_point3d(self.point, field_name="point", allow_none=True)
        screen_position = _annotation_screen_position(self.screen_position)
        screen_region = _annotation_text(self.screen_region, field_name="screen_region", maximum=64)
        if screen_region and screen_region not in _ANNOTATION_SCREEN_POSITIONS:
            raise VisualizationSpecificationError(
                "Unsupported screen region.", context={"screen_region": screen_region}
            )
        interaction_id = _annotation_text(self.interaction_id, field_name="interaction_id", maximum=256)
        source_id = _annotation_text(self.source_id, field_name="source_id", maximum=256)
        model_id = _annotation_text(self.model_id, field_name="model_id", maximum=128)
        if anchor in (LabelAnchor.ATOM, LabelAnchor.RESIDUE, LabelAnchor.MODEL) and selection.is_none:
            raise VisualizationSpecificationError(f"{anchor.value} labels require a selection.")
        if anchor is LabelAnchor.SCREEN and screen_position is None and screen_region is None:
            raise VisualizationSpecificationError("Screen labels require a screen position or region.")
        if anchor is LabelAnchor.INTERACTION and not interaction_id and point is None and selection.is_none:
            raise VisualizationSpecificationError("Interaction labels require an interaction target.")
        if anchor is LabelAnchor.POINT and point is None and selection.is_none:
            raise VisualizationSpecificationError("Point labels require a point or selection.")
        object.__setattr__(self, "anchor", anchor)
        object.__setattr__(self, "selection", selection)
        object.__setattr__(self, "point", point)
        object.__setattr__(self, "screen_position", screen_position)
        object.__setattr__(self, "screen_region", screen_region)
        object.__setattr__(self, "interaction_id", interaction_id)
        object.__setattr__(self, "source_id", source_id)
        object.__setattr__(self, "model_id", model_id)
        object.__setattr__(self, "metadata", _annotation_mapping(self.metadata, field_name="metadata"))

    @property
    def key(self) -> Tuple[Any, ...]:
        """Return a collision key."""

        if self.anchor is LabelAnchor.SCREEN:
            return (self.anchor.value, self.screen_region, self.screen_position)
        if self.point is not None:
            return (self.anchor.value, *(round(item, 2) for item in self.point))
        if not self.selection.is_none:
            return (self.anchor.value, self.selection.expression)
        return (self.anchor.value, self.interaction_id, self.source_id, self.model_id)


@dataclass(frozen=True, slots=True)
class AnnotationSpec(MolecularSpecMixin):
    """One label or annotation."""

    annotation_id: str
    text: str
    kind: LabelKind = LabelKind.CUSTOM
    target: AnnotationTargetSpec = field(default_factory=AnnotationTargetSpec)
    style: AnnotationStyleSpec = field(default_factory=AnnotationStyleSpec)
    priority: OperationPriority = OperationPriority.NORMAL
    visible: bool = True
    group_name: str = _ANNOTATION_DEFAULT_GROUP
    tags: Tuple[str, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "annotation_id", _annotation_identifier(self.annotation_id))
        text = _annotation_text(self.text, field_name="text", required=True)
        object.__setattr__(self, "text", text)
        object.__setattr__(self, "kind", LabelKind.parse(self.kind, default=LabelKind.CUSTOM))
        object.__setattr__(self, "target", coerce_annotation_target(self.target))
        object.__setattr__(self, "style", coerce_annotation_style(self.style))
        object.__setattr__(self, "priority", OperationPriority.parse(
            self.priority, default=OperationPriority.NORMAL
        ))
        object.__setattr__(self, "visible", bool(self.visible))
        group_name = _annotation_text(
            self.group_name, field_name="group_name", required=True, maximum=MAX_GROUP_NAME_LENGTH
        )
        object.__setattr__(self, "group_name", group_name)
        object.__setattr__(self, "tags", _annotation_tags(self.tags))
        object.__setattr__(self, "metadata", _annotation_mapping(self.metadata, field_name="metadata"))

    @property
    def selection(self) -> MolecularSelection:
        return self.target.selection


@dataclass(frozen=True, slots=True)
class LegendEntrySpec(MolecularSpecMixin):
    """One legend row."""

    entry_id: str
    label: str
    color: str
    symbol: str = "line"
    value: Optional[str] = None
    order: int = 0
    visible: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "entry_id", _annotation_identifier(self.entry_id, field_name="entry_id"))
        object.__setattr__(self, "label", _annotation_text(
            self.label, field_name="label", required=True, maximum=256
        ))
        object.__setattr__(self, "color", normalize_color(self.color, field_name="color"))
        symbol = _annotation_text(self.symbol, field_name="symbol", required=True, maximum=64)
        object.__setattr__(self, "symbol", symbol)
        object.__setattr__(self, "value", _annotation_text(self.value, field_name="value", maximum=128))
        object.__setattr__(self, "order", int(self.order))
        object.__setattr__(self, "visible", bool(self.visible))
        object.__setattr__(self, "metadata", _annotation_mapping(self.metadata, field_name="metadata"))


@dataclass(frozen=True, slots=True)
class LegendSpec(MolecularSpecMixin):
    """Screen-space legend."""

    legend_id: str
    title: Optional[str] = None
    entries: Tuple[LegendEntrySpec, ...] = ()
    position: str = "bottom_right"
    columns: int = 1
    font: str = DEFAULT_LABEL_FONT
    font_size: int = DEFAULT_LABEL_FONT_SIZE
    color: str = DEFAULT_LABEL_COLOR
    background_color: str = _ANNOTATION_DEFAULT_BACKGROUND
    background_opacity: float = 0.85
    border_color: str = _ANNOTATION_DEFAULT_BORDER
    border_width: float = _ANNOTATION_DEFAULT_LINE_WIDTH
    padding: float = _ANNOTATION_DEFAULT_PADDING
    visible: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        entries = tuple(coerce_legend_entry(item, index=index) for index, item in enumerate(self.entries))
        if len(entries) > _ANNOTATION_MAX_LEGEND_ENTRIES:
            raise VisualizationLimitError("Legend entry limit exceeded.")
        identifiers = [item.entry_id for item in entries]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSpecificationError(
                "Legend entry identifiers must be unique.", context={"duplicates": duplicates}
            )
        position = str(self.position).strip().lower()
        if position not in _ANNOTATION_LEGEND_POSITIONS:
            raise VisualizationSpecificationError(
                "Unsupported legend position.", context={"position": self.position}
            )
        object.__setattr__(self, "legend_id", _annotation_identifier(self.legend_id, field_name="legend_id"))
        object.__setattr__(self, "title", _annotation_text(self.title, field_name="title", maximum=256))
        object.__setattr__(self, "entries", tuple(sorted(entries, key=lambda item: (item.order, item.label))))
        object.__setattr__(self, "position", position)
        object.__setattr__(self, "columns", _bounded_int(
            self.columns, field_name="columns", minimum=1, maximum=12
        ))
        object.__setattr__(self, "font", _annotation_text(
            self.font, field_name="font", required=True, maximum=128
        ))
        object.__setattr__(self, "font_size", _bounded_int(
            self.font_size, field_name="font_size", minimum=1, maximum=512
        ))
        object.__setattr__(self, "color", normalize_color(self.color, field_name="color"))
        object.__setattr__(self, "background_color", normalize_color(
            self.background_color, field_name="background_color"
        ))
        object.__setattr__(self, "background_opacity", _bounded_float(
            self.background_opacity, field_name="background_opacity", minimum=0.0, maximum=1.0
        ))
        object.__setattr__(self, "border_color", normalize_color(
            self.border_color, field_name="border_color"
        ))
        object.__setattr__(self, "border_width", _bounded_float(
            self.border_width, field_name="border_width", minimum=0.0, maximum=100.0
        ))
        object.__setattr__(self, "padding", _bounded_float(
            self.padding, field_name="padding", minimum=0.0, maximum=100.0
        ))
        object.__setattr__(self, "visible", bool(self.visible))
        object.__setattr__(self, "metadata", _annotation_mapping(self.metadata, field_name="metadata"))

    @property
    def visible_entries(self) -> Tuple[LegendEntrySpec, ...]:
        return tuple(item for item in self.entries if item.visible)


@dataclass(frozen=True, slots=True)
class AnnotationCollection(MolecularSpecMixin):
    """Immutable annotation set."""

    annotations: Tuple[AnnotationSpec, ...] = ()
    legends: Tuple[LegendSpec, ...] = ()
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        annotations = tuple(coerce_annotation_spec(item, index=index) for index, item in enumerate(self.annotations))
        legends = tuple(coerce_legend_spec(item, index=index) for index, item in enumerate(self.legends))
        if len(annotations) > _ANNOTATION_MAX_ITEMS:
            raise VisualizationLimitError("Annotation limit exceeded.")
        if len(legends) > _ANNOTATION_MAX_LEGENDS:
            raise VisualizationLimitError("Legend limit exceeded.")
        annotation_ids = [item.annotation_id for item in annotations]
        legend_ids = [item.legend_id for item in legends]
        duplicate_annotations = sorted(key for key, count in Counter(annotation_ids).items() if count > 1)
        duplicate_legends = sorted(key for key, count in Counter(legend_ids).items() if count > 1)
        if duplicate_annotations or duplicate_legends:
            raise VisualizationSpecificationError(
                "Annotation identifiers must be unique.",
                context={
                    "duplicate_annotations": duplicate_annotations,
                    "duplicate_legends": duplicate_legends,
                },
            )
        object.__setattr__(self, "annotations", annotations)
        object.__setattr__(self, "legends", legends)
        object.__setattr__(self, "metadata", _annotation_mapping(self.metadata, field_name="metadata"))

    def __len__(self) -> int:
        return len(self.annotations)

    def __iter__(self) -> Iterator[AnnotationSpec]:
        return iter(self.annotations)

    @property
    def visible(self) -> Tuple[AnnotationSpec, ...]:
        return tuple(item for item in self.annotations if item.visible)

    @property
    def selection(self) -> MolecularSelection:
        return selection_union(*(item.selection for item in self.visible))

    def by_kind(self, kind: Any) -> Tuple[AnnotationSpec, ...]:
        parsed = LabelKind.parse(kind, default=LabelKind.CUSTOM)
        return tuple(item for item in self.annotations if item.kind is parsed)

    def by_anchor(self, anchor: Any) -> Tuple[AnnotationSpec, ...]:
        parsed = LabelAnchor.parse(anchor, default=LabelAnchor.POINT)
        return tuple(item for item in self.annotations if item.target.anchor is parsed)

    def sorted(self) -> "AnnotationCollection":
        items = sorted(
            self.annotations,
            key=lambda item: (-int(item.priority), item.kind.value, item.annotation_id),
        )
        return replace(self, annotations=tuple(items))

    def limited(self, maximum: int) -> "AnnotationCollection":
        maximum = _bounded_int(maximum, field_name="maximum", minimum=0, maximum=_ANNOTATION_MAX_ITEMS)
        return replace(self, annotations=self.sorted().annotations[:maximum])


@dataclass(frozen=True, slots=True)
class AnnotationVisualizationSpec(MolecularSpecMixin):
    """Complete annotation display settings."""

    collection: AnnotationCollection = field(default_factory=AnnotationCollection)
    enabled: bool = True
    collision: LabelCollisionMode = LabelCollisionMode.AUTO
    max_labels: int = 250
    offset_step: Point3D = _ANNOTATION_DEFAULT_OFFSET_STEP
    show_legends: bool = True
    group_name: str = _ANNOTATION_DEFAULT_GROUP
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        collection = coerce_annotation_collection(self.collection)
        collision = LabelCollisionMode.parse(self.collision, default=LabelCollisionMode.AUTO)
        maximum = _bounded_int(
            self.max_labels, field_name="max_labels", minimum=0, maximum=_ANNOTATION_MAX_ITEMS
        )
        offset_step = _annotation_offset(self.offset_step)
        metadata = dict(_annotation_mapping(self.metadata, field_name="metadata"))
        collision_state = {"mode": collision.value, "offset_step": list(offset_step)}
        if metadata.get("_annotation_collision_state") != collision_state:
            collection = resolve_annotation_collisions(
                collection, mode=collision, offset_step=offset_step
            )
            metadata["_annotation_collision_state"] = collision_state
        collection = collection.limited(maximum)
        object.__setattr__(self, "collection", collection)
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "collision", collision)
        object.__setattr__(self, "max_labels", maximum)
        object.__setattr__(self, "offset_step", offset_step)
        object.__setattr__(self, "show_legends", bool(self.show_legends))
        object.__setattr__(self, "group_name", _annotation_text(
            self.group_name, field_name="group_name", required=True, maximum=MAX_GROUP_NAME_LENGTH
        ))
        object.__setattr__(self, "metadata", MappingProxyType(metadata))

    @property
    def annotations(self) -> Tuple[AnnotationSpec, ...]:
        return self.collection.visible

    @property
    def selection(self) -> MolecularSelection:
        return self.collection.selection


# 21.1. Coercion
# -----------------------------------------------------------------------------

def coerce_annotation_style(value: Any = None, *, config_value: Any = None, **overrides: Any) -> AnnotationStyleSpec:
    """Coerce label appearance."""

    if isinstance(value, AnnotationStyleSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, LabelStyleConfig):
        data = {
            "font": value.font,
            "font_size": value.font_size,
            "color": value.color,
            "opacity": value.opacity,
            "offset": value.offset,
        }
        data.update(overrides)
        return AnnotationStyleSpec(**data)
    if isinstance(value, Mapping):
        data = dict(value)
        data.update(overrides)
        return AnnotationStyleSpec(**data)
    if value is None:
        return AnnotationStyleSpec.from_config(config_value, **overrides)
    raise VisualizationSpecificationError("Unsupported annotation style input.")


def coerce_annotation_target(value: Any, *, anchor: Any = None, **overrides: Any) -> AnnotationTargetSpec:
    """Coerce an annotation target."""

    if isinstance(value, AnnotationTargetSpec):
        data = overrides
        if anchor is not None:
            data = {"anchor": anchor, **data}
        return replace(value, **data) if data else value
    if isinstance(value, Mapping):
        data = dict(value)
        if anchor is not None:
            data["anchor"] = anchor
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    if isinstance(value, VirtualPointSpec):
        data = {
            "anchor": LabelAnchor.POINT,
            "point": value.coordinate,
            "selection": value.source_selection,
            "source_id": value.point_id,
        }
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    if isinstance(value, VisualInteractionSpec):
        data = {
            "anchor": LabelAnchor.INTERACTION,
            "point": value.midpoint,
            "selection": selection_union(*value.selections),
            "interaction_id": value.interaction_id,
            "source_id": value.interaction_id,
        }
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    if isinstance(value, (MolecularSelection, MolecularPathSpec, AtomSpec, ResidueSpec, ModelSpec, PoseSpec)):
        path_anchor = LabelAnchor.RESIDUE
        if isinstance(value, MolecularPathSpec):
            path_anchor = (
                LabelAnchor.ATOM if value.atom_name else
                LabelAnchor.RESIDUE if value.residue_number is not None else
                LabelAnchor.MODEL if value.model_id else LabelAnchor.POINT
            )
        parsed_anchor = anchor or (
            LabelAnchor.ATOM if isinstance(value, AtomSpec) else
            path_anchor if isinstance(value, MolecularPathSpec) else
            LabelAnchor.RESIDUE if isinstance(value, ResidueSpec) else
            LabelAnchor.MODEL if isinstance(value, ModelSpec) else LabelAnchor.POINT
        )
        data = {"anchor": parsed_anchor, "selection": coerce_selection(value)}
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        data = {"anchor": anchor or LabelAnchor.POINT, "point": value}
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    if isinstance(value, str):
        data = {"anchor": anchor or LabelAnchor.POINT, "selection": coerce_selection(value)}
        data.update(overrides)
        return AnnotationTargetSpec(**data)
    raise VisualizationSpecificationError("Unsupported annotation target input.")


def coerce_annotation_spec(
    value: Any,
    *,
    index: int = 0,
    config_value: Any = None,
    **overrides: Any,
) -> AnnotationSpec:
    """Coerce one annotation."""

    if isinstance(value, AnnotationSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping):
        data = dict(value)
        data.update(overrides)
        return AnnotationSpec(**data)
    return annotation_from_source(value, index=index, config_value=config_value, **overrides)


def coerce_legend_entry(value: Any, *, index: int = 0, **overrides: Any) -> LegendEntrySpec:
    """Coerce one legend entry."""

    if isinstance(value, LegendEntrySpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("entry_id", f"entry-{index + 1}")
        data.setdefault("order", index)
        data.update(overrides)
        return LegendEntrySpec(**data)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        items = tuple(value)
        if len(items) < 2:
            raise VisualizationSpecificationError("Legend entries require label and color.")
        data = {
            "entry_id": f"entry-{index + 1}",
            "label": items[0],
            "color": items[1],
            "value": items[2] if len(items) > 2 else None,
            "order": index,
        }
        data.update(overrides)
        return LegendEntrySpec(**data)
    raise VisualizationSpecificationError("Unsupported legend entry input.")


def coerce_legend_spec(value: Any, *, index: int = 0, **overrides: Any) -> LegendSpec:
    """Coerce one legend."""

    if isinstance(value, LegendSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("legend_id", f"legend-{index + 1}")
        data.update(overrides)
        return LegendSpec(**data)
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        data = {
            "legend_id": f"legend-{index + 1}",
            "entries": tuple(value),
        }
        data.update(overrides)
        return LegendSpec(**data)
    raise VisualizationSpecificationError("Unsupported legend input.")


def coerce_annotation_collection(value: Any, *, config_value: Any = None) -> AnnotationCollection:
    """Coerce an annotation collection."""

    if isinstance(value, AnnotationCollection):
        return value
    if value is None:
        return AnnotationCollection()
    if isinstance(value, AnnotationVisualizationSpec):
        return value.collection
    if isinstance(value, Mapping):
        if "annotations" in value or "legends" in value:
            return AnnotationCollection(**dict(value))
        return AnnotationCollection((coerce_annotation_spec(value, config_value=config_value),))
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes, bytearray)):
        return build_annotation_collection(value, config_value=config_value)
    return AnnotationCollection((coerce_annotation_spec(value, config_value=config_value),))


def coerce_annotation_visualization_spec(
    value: Any,
    *,
    config_value: Any = None,
    **overrides: Any,
) -> AnnotationVisualizationSpec:
    """Coerce complete annotation settings."""

    if isinstance(value, AnnotationVisualizationSpec):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, Mapping) and "collection" in value:
        data = dict(value)
        data.update(overrides)
        return AnnotationVisualizationSpec(**data)
    config_obj = resolve_visualization_config(config_value)
    data = {
        "collection": coerce_annotation_collection(value, config_value=config_obj),
        "enabled": config_obj.labels.enabled,
        "collision": config_obj.labels.collision,
        "max_labels": config_obj.labels.max_labels,
        "offset_step": _ANNOTATION_DEFAULT_OFFSET_STEP,
    }
    data.update(overrides)
    return AnnotationVisualizationSpec(**data)


# 21.2. Source conversion
# -----------------------------------------------------------------------------

def _source_style_color(value: Any, fallback: str) -> str:
    """Read a source color."""

    style = _object_value(value, "style")
    color = _object_value(style, "color") if style is not None else None
    color = color or _object_value(value, "color")
    return normalize_color(color or fallback, field_name="color")


def _residue_annotation_values(value: InvolvedResidueSpec) -> Dict[str, Any]:
    path = value.path
    return {
        "label": value.label,
        "resname": path.residue_name or "RES",
        "resid": path.residue_number or "?",
        "chain": path.chain_id or "?",
        "score": value.score,
        "frequency": value.frequency,
        "count": value.interaction_count,
        "rank": value.rank,
    }


def annotation_from_source(
    value: Any,
    *,
    index: int = 0,
    config_value: Any = None,
    text: Optional[str] = None,
    kind: Any = None,
    style: Any = None,
    priority: Any = OperationPriority.NORMAL,
    **overrides: Any,
) -> AnnotationSpec:
    """Build an annotation from a visual object."""

    config_obj = resolve_visualization_config(config_value)
    base_style = coerce_annotation_style(style, config_value=config_obj)
    annotation_id = f"annotation-{index + 1}"
    target: AnnotationTargetSpec
    values: Dict[str, Any]
    default_kind = LabelKind.CUSTOM
    template = "{label}"

    if isinstance(value, VisualInteractionSpec):
        annotation_id = f"interaction-{value.interaction_id}"
        target = coerce_annotation_target(value)
        values = {
            "label": value.label or value.family.label,
            "family": value.family.label,
            "subtype": value.subtype or "",
            "distance": value.distance if value.distance is not None else 0.0,
            "score": value.score if value.score is not None else 0.0,
            "strength": value.strength.value,
        }
        default_kind = LabelKind.DISTANCE if value.distance is not None else LabelKind.INTERACTION
        template = config_obj.labels.distance_template if value.distance is not None else "{label}"
        base_style = replace(base_style, color=value.style.color)
    elif isinstance(value, InvolvedResidueSpec):
        annotation_id = f"residue-{value.residue_id}"
        target = AnnotationTargetSpec(
            anchor=LabelAnchor.RESIDUE,
            selection=value.selection,
            source_id=value.residue_id,
        )
        values = _residue_annotation_values(value)
        default_kind = LabelKind.RESIDUE
        template = config_obj.labels.residue_template
        base_style = replace(base_style, color=_source_style_color(value, base_style.color))
    elif isinstance(value, HotspotSpec):
        annotation_id = f"hotspot-{value.hotspot_id}"
        target = AnnotationTargetSpec(
            anchor=LabelAnchor.POINT if value.center is not None else LabelAnchor.RESIDUE,
            selection=value.selection,
            point=value.center,
            source_id=value.hotspot_id,
        )
        values = {
            "label": value.label or value.hotspot_id,
            "hotspot_id": value.hotspot_id,
            "score": value.score,
            "frequency": value.frequency,
            "density": value.density,
            "level": value.level.value,
            "rank": value.rank,
        }
        default_kind = LabelKind.HOTSPOT
        template = "{label} | {frequency:.0%}"
    elif isinstance(value, VisualScoreItem):
        annotation_id = f"score-{value.item_id}"
        target = AnnotationTargetSpec(
            anchor=LabelAnchor.POINT if value.metadata.get("coordinate") is not None else LabelAnchor.RESIDUE,
            selection=value.selection,
            point=normalize_point3d(value.metadata.get("coordinate"), allow_none=True),
            source_id=value.item_id,
        )
        values = {
            "label": value.label or value.item_id,
            "score": value.score,
            "normalized": value.normalized_score,
            "rank": value.rank,
        }
        default_kind = LabelKind.SCORE
        template = config_obj.labels.score_template
        base_style = replace(base_style, color=value.color or base_style.color)
    elif isinstance(value, (PoseVisualSpec, PoseSpec)):
        pose = value
        pose_id = pose.pose_id
        annotation_id = f"pose-{pose_id}"
        target = AnnotationTargetSpec(
            anchor=LabelAnchor.POINT,
            selection=pose.selection if isinstance(pose, PoseVisualSpec) else pose_spec_to_selection(pose),
            source_id=pose_id,
        )
        values = {
            "label": pose_id,
            "pose_id": pose_id,
            "score": getattr(pose, "score", None),
            "affinity": getattr(pose, "affinity", None),
            "rank": getattr(pose, "rank", None),
        }
        default_kind = LabelKind.POSE
        template = "{pose_id}"
        color = getattr(pose, "color", None)
        if color:
            base_style = replace(base_style, color=color)
    elif isinstance(value, VirtualPointSpec):
        annotation_id = f"point-{value.point_id}"
        target = coerce_annotation_target(value)
        values = {"label": value.label or value.point_id, "point_id": value.point_id}
        default_kind = LabelKind.CUSTOM
    elif isinstance(value, (AtomSpec, ResidueSpec, ModelSpec, MolecularPathSpec)):
        target = coerce_annotation_target(value)
        annotation_id = f"molecular-{index + 1}"
        label = getattr(value, "label", None) or annotation_id
        values = {"label": label}
        default_kind = LabelKind.ATOM if isinstance(value, AtomSpec) else LabelKind.RESIDUE
    else:
        atomspec = _object_atomspec(value)
        coordinate = _object_value(value, "coordinate", "coord", "centroid")
        label = _object_value(value, "label", "name", "id", default=f"Annotation {index + 1}")
        source_id = _object_value(value, "id", "source_id", default=annotation_id)
        target = AnnotationTargetSpec(
            anchor=LabelAnchor.POINT,
            selection=coerce_selection(atomspec, strict=False),
            point=normalize_point3d(coordinate, allow_none=True),
            source_id=str(source_id),
        )
        values = {"label": str(label)}

    rendered = text or _annotation_format(template, values)
    data = {
        "annotation_id": annotation_id,
        "text": rendered,
        "kind": kind or default_kind,
        "target": target,
        "style": base_style,
        "priority": priority,
        "metadata": {"source_type": type(value).__name__, "values": values},
    }
    data.update(overrides)
    return AnnotationSpec(**data)


def build_annotation_collection(
    values: Iterable[Any],
    *,
    config_value: Any = None,
    legends: Iterable[Any] = (),
    deduplicate: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> AnnotationCollection:
    """Build annotations from mixed visual sources."""

    annotations: List[AnnotationSpec] = []
    seen: Set[Tuple[str, Tuple[Any, ...]]] = set()
    used_ids: Set[str] = set()
    for index, value in enumerate(values):
        item = coerce_annotation_spec(value, index=index, config_value=config_value)
        key = (item.text, item.target.key)
        if deduplicate and key in seen:
            continue
        if item.annotation_id in used_ids:
            item = replace(item, annotation_id=f"{item.annotation_id}-{index + 1}")
        annotations.append(item)
        seen.add(key)
        used_ids.add(item.annotation_id)
    return AnnotationCollection(
        tuple(annotations),
        tuple(coerce_legend_spec(item, index=index) for index, item in enumerate(legends)),
        metadata or {},
    )


def build_interaction_legend(
    value: Any,
    *,
    legend_id: str = "interaction-families",
    title: str = "Interactions",
    position: str = "bottom_right",
    config_value: Any = None,
) -> LegendSpec:
    """Build an interaction-family legend."""

    collection = build_visual_interactions(value, config_value=config_value)
    families = tuple(sorted({item.family for item in collection.interactions}, key=lambda item: item.value))
    entries = tuple(LegendEntrySpec(
        entry_id=family.value,
        label=family.label,
        color=resolve_interaction_style(family, config_value=config_value).color,
        symbol="line",
        order=index,
    ) for index, family in enumerate(families))
    return LegendSpec(legend_id, title, entries, position=position)


def build_score_legend(
    *,
    palette: Optional[Sequence[Any]] = None,
    labels: Sequence[str] = ("Low", "Medium", "High"),
    legend_id: str = "score-scale",
    title: str = "Score",
    position: str = "bottom_left",
    config_value: Any = None,
) -> LegendSpec:
    """Build a compact score legend."""

    config_obj = resolve_visualization_config(config_value)
    colors = tuple(normalize_color(item, field_name="palette") for item in (palette or config_obj.scoring.palette))
    positions = (0.0, 0.5, 1.0)
    entries = tuple(LegendEntrySpec(
        entry_id=f"score-{index + 1}",
        label=str(label),
        color=_score_palette_color(position_value, colors, config_obj.scoring.missing_color),
        symbol="swatch",
        order=index,
    ) for index, (label, position_value) in enumerate(zip(labels, positions)))
    return LegendSpec(legend_id, title, entries, position=position)


# 21.3. Collision handling
# -----------------------------------------------------------------------------

def _offset_annotation(item: AnnotationSpec, index: int, step: Point3D) -> AnnotationSpec:
    """Offset one colliding annotation."""

    current = item.style.offset
    offset = tuple(current[axis] + step[axis] * index for axis in range(3))
    return replace(item, style=replace(item.style, offset=offset))


def resolve_annotation_collisions(
    value: Any,
    *,
    mode: Any = LabelCollisionMode.AUTO,
    offset_step: Any = _ANNOTATION_DEFAULT_OFFSET_STEP,
) -> AnnotationCollection:
    """Apply a deterministic collision policy."""

    collection = coerce_annotation_collection(value)
    parsed = LabelCollisionMode.parse(mode, default=LabelCollisionMode.AUTO)
    if parsed is LabelCollisionMode.ALLOW:
        return collection.sorted()
    step = _annotation_offset(offset_step)
    grouped: Dict[Tuple[Any, ...], List[AnnotationSpec]] = defaultdict(list)
    for item in collection.sorted().annotations:
        grouped[item.target.key].append(item)
    output: List[AnnotationSpec] = []
    for items in grouped.values():
        if len(items) == 1:
            output.extend(items)
        elif parsed is LabelCollisionMode.HIDE:
            output.append(items[0])
        else:
            output.extend(_offset_annotation(item, index, step) for index, item in enumerate(items))
    return replace(collection, annotations=tuple(output))


# 21.4. Plan integration
# -----------------------------------------------------------------------------

def _annotation_dependencies(plan: VisualizationPlan) -> Tuple[str, ...]:
    """Return available visual dependencies."""

    preferred_prefixes = (
        "complementarity:", "consensus:", "multipose:", "scoring:",
        "hotspots:", "residues:", "markers:", "interactions:",
        "ligand:", "receptor:", "scene:",
    )
    identifiers: List[str] = []
    for prefix in preferred_prefixes:
        matches = [
            action.action_id for action in plan.actions
            if action.enabled and action.action_id.startswith(prefix)
            and not action.action_id.startswith(_ANNOTATION_ACTION_PREFIX)
        ]
        if matches:
            identifiers.extend(matches[-8:])
    return _action_dependencies(identifiers)


def _annotation_payload(item: AnnotationSpec) -> Dict[str, Any]:
    """Return a backend-neutral label payload."""

    return {
        "annotation_id": item.annotation_id,
        "text": item.text,
        "kind": item.kind.value,
        "anchor": item.target.anchor.value,
        "selection": item.target.selection.expression,
        "point": item.target.point,
        "screen_position": item.target.screen_position,
        "screen_region": item.target.screen_region,
        "interaction_id": item.target.interaction_id,
        "source_id": item.target.source_id,
        "model_id": item.target.model_id,
        "style": item.style.to_dict(),
        "priority": item.priority.name.lower(),
        "group_name": item.group_name,
        "tags": item.tags,
    }


def build_annotation_actions(
    value: Any,
    *,
    config_value: Any = None,
    depends_on: Iterable[str] = (),
) -> Tuple[VisualizationAction, ...]:
    """Convert annotations to plan actions."""

    spec = coerce_annotation_visualization_spec(value, config_value=config_value)
    dependencies = _action_dependencies(depends_on)
    groups = {
        "molecular": tuple(item for item in spec.annotations if item.target.anchor in (
            LabelAnchor.ATOM, LabelAnchor.RESIDUE, LabelAnchor.MODEL
        )),
        "points": tuple(item for item in spec.annotations if item.target.anchor in (
            LabelAnchor.POINT, LabelAnchor.INTERACTION
        )),
        "screen": tuple(item for item in spec.annotations if item.target.anchor is LabelAnchor.SCREEN),
    }
    action_ids = {
        "molecular": _ANNOTATION_MOLECULAR_ACTION,
        "points": _ANNOTATION_POINT_ACTION,
        "screen": _ANNOTATION_SCREEN_ACTION,
    }
    actions: List[VisualizationAction] = []
    for component, items in groups.items():
        if not items:
            continue
        selection = selection_union(*(item.selection for item in items))
        actions.append(VisualizationAction(
            action_id=action_ids[component],
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=selection,
            parameters={
                "component": component,
                "group_name": spec.group_name,
                "collision": spec.collision.value,
                "annotations": tuple(_annotation_payload(item) for item in items),
            },
            depends_on=dependencies,
            priority=OperationPriority.LOW,
            enabled=spec.enabled,
            optional=selection.is_none or component == "screen",
            description=f"Display {component} annotations.",
            tags=("labels", component),
        ))
    visible_legends = tuple(legend for legend in spec.collection.legends if legend.visible)
    if spec.show_legends and visible_legends:
        actions.append(VisualizationAction(
            action_id=_ANNOTATION_LEGEND_ACTION,
            operation=PlanOperation.SHOW_LABELS,
            layer=VisualLayer.LABELS,
            selection=MolecularSelection.none(),
            parameters={
                "component": "legends",
                "legends": tuple(legend.to_dict() for legend in visible_legends),
            },
            depends_on=tuple(action.action_id for action in actions) or dependencies,
            priority=OperationPriority.LOW,
            enabled=spec.enabled,
            optional=True,
            description="Display annotation legends.",
            tags=("labels", "legend"),
        ))
    return tuple(actions)


def build_annotation_plan(
    value: Any,
    *,
    config_value: Any = None,
    plan_id: str = "annotation-visualization",
    name: str = "Labels and annotations",
    execution_mode: Any = ExecutionMode.DEFERRED,
    metadata: Optional[Mapping[str, Any]] = None,
    **overrides: Any,
) -> VisualizationPlan:
    """Build a standalone annotation plan."""

    spec = coerce_annotation_visualization_spec(value, config_value=config_value, **overrides)
    config_obj = resolve_visualization_config(config_value)
    return build_visualization_plan(
        build_annotation_actions(spec, config_value=config_obj),
        plan_id=plan_id,
        name=name,
        profile=config_obj.profile,
        execution_mode=execution_mode,
        description="Display molecular labels, callouts and legends.",
        metadata={"annotations": spec.to_dict(), **dict(metadata or {})},
    )


def attach_annotations(
    plan: Any,
    value: Any,
    *,
    config_value: Any = None,
    replace_existing: bool = True,
    **overrides: Any,
) -> VisualizationPlan:
    """Attach annotation actions to a plan."""

    base = coerce_visualization_plan(plan)
    spec = coerce_annotation_visualization_spec(value, config_value=config_value, **overrides)
    existing = tuple(
        action for action in base.actions
        if action.action_id.startswith(_ANNOTATION_ACTION_PREFIX)
    )
    if existing and not replace_existing:
        raise VisualizationPlanError("Annotation actions already exist.")
    actions = [
        action for action in base.actions
        if not action.action_id.startswith(_ANNOTATION_ACTION_PREFIX)
    ]
    actions.extend(build_annotation_actions(
        spec,
        config_value=config_value,
        depends_on=_annotation_dependencies(base),
    ))
    return build_visualization_plan(
        actions,
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "annotations": spec.to_dict()},
    )


def visualize_annotations(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    **kwargs: Any,
) -> VisualizationPlan:
    """Create or attach annotations."""

    return (
        build_annotation_plan(value, config_value=config_value, **kwargs)
        if plan is None
        else attach_annotations(plan, value, config_value=config_value, **kwargs)
    )


# 21.5. Validation and serialization
# -----------------------------------------------------------------------------

def validate_annotations(
    value: Any,
    *,
    config_value: Any = None,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate annotation semantics."""

    spec = coerce_annotation_visualization_spec(value, config_value=config_value)
    issues: List[PlanValidationIssue] = []
    if spec.enabled and not spec.collection.annotations and not spec.collection.legends:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "annotations_empty",
            "No annotations or legends are available.",
            _ANNOTATION_MOLECULAR_ACTION,
        ))
    hidden_count = len(spec.collection.annotations) - len(spec.annotations)
    if hidden_count:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "annotations_hidden",
            f"{hidden_count} annotations are hidden.",
            _ANNOTATION_MOLECULAR_ACTION,
        ))
    if len(spec.annotations) >= spec.max_labels and spec.max_labels > 0:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "annotations_limited",
            "The annotation collection reached the display limit.",
            _ANNOTATION_MOLECULAR_ACTION,
            {"max_labels": spec.max_labels},
        ))
    missing_targets = tuple(
        item.annotation_id for item in spec.annotations
        if item.target.selection.is_none and item.target.point is None
        and item.target.screen_position is None and item.target.screen_region is None
        and not item.target.interaction_id and not item.target.model_id
    )
    if missing_targets:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "annotation_targets_missing",
            "Some annotations have no usable target.",
            _ANNOTATION_POINT_ACTION,
            {"annotation_ids": missing_targets},
        ))
    empty_legends = tuple(
        legend.legend_id for legend in spec.collection.legends
        if legend.visible and not legend.visible_entries
    )
    if empty_legends:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "legends_empty",
            "Some visible legends have no visible entries.",
            _ANNOTATION_LEGEND_ACTION,
            {"legend_ids": empty_legends},
        ))
    return tuple(issues)


def summarize_annotations(
    value: Any,
    *,
    config_value: Any = None,
) -> Dict[str, Any]:
    """Return compact annotation statistics."""

    spec = coerce_annotation_visualization_spec(value, config_value=config_value)
    issues = validate_annotations(spec, config_value=config_value)
    return {
        "enabled": spec.enabled,
        "annotation_count": len(spec.collection.annotations),
        "visible_count": len(spec.annotations),
        "legend_count": len(spec.collection.legends),
        "kind_counts": dict(Counter(item.kind.value for item in spec.annotations)),
        "anchor_counts": dict(Counter(item.target.anchor.value for item in spec.annotations)),
        "collision": spec.collision.value,
        "max_labels": spec.max_labels,
        "selection": spec.selection.expression,
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": spec.fingerprint(),
    }


def annotations_to_dict(value: Any, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize annotation settings."""

    return coerce_annotation_visualization_spec(value, config_value=config_value).to_dict()


def annotations_to_json(
    value: Any,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize annotation settings as JSON."""

    return json.dumps(
        annotations_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


