# =============================================================================
# Section 23 — Snapshots and images
# =============================================================================

# 23.1. Internal constants and helpers
# -----------------------------------------------------------------------------

_SNAPSHOT_ACTION_PREFIX: Final[str] = "snapshot:"
_SNAPSHOT_DEFAULT_ID: Final[str] = "main"
_SNAPSHOT_MAX_REQUESTS: Final[int] = 2048
_SNAPSHOT_MAX_DELAY: Final[float] = 60.0
_SNAPSHOT_CROP_LENGTH: Final[int] = 4
_SNAPSHOT_ALLOWED_METADATA: Final[FrozenSet[str]] = frozenset(
    {"author", "description", "software", "source", "title"}
)
_IMAGE_RASTER_FORMATS: Final[FrozenSet[SnapshotFormat]] = frozenset(
    {SnapshotFormat.PNG, SnapshotFormat.JPEG, SnapshotFormat.TIFF, SnapshotFormat.WEBP}
)
_IMAGE_ALPHA_FORMATS: Final[FrozenSet[SnapshotFormat]] = frozenset(
    {SnapshotFormat.PNG, SnapshotFormat.TIFF, SnapshotFormat.WEBP}
)
_IMAGE_PIL_FORMATS: Final[Mapping[SnapshotFormat, str]] = MappingProxyType(
    {
        SnapshotFormat.PNG: "PNG",
        SnapshotFormat.JPEG: "JPEG",
        SnapshotFormat.TIFF: "TIFF",
        SnapshotFormat.WEBP: "WEBP",
    }
)


def _snapshot_identifier(value: Any, *, field_name: str = "snapshot_id") -> str:
    text = _clean_spec_text(value, field_name=field_name, allow_none=False, max_length=128)
    assert text is not None
    token = re.sub(r"[^A-Za-z0-9_.-]+", "_", text).strip("._-")
    if not token:
        raise VisualizationSnapshotError(
            f"{field_name} has no safe characters.",
            context={"value": text},
        )
    return token


def _snapshot_format(value: Any, *, filename: Any = None) -> SnapshotFormat:
    if value is not None:
        return SnapshotFormat.parse(value, field_name="format")
    suffix = Path(str(filename)).suffix.lower() if filename else ""
    aliases = {".jpg": "jpeg", ".jpeg": "jpeg", ".tif": "tiff", ".tiff": "tiff"}
    token = aliases.get(suffix, suffix.lstrip("."))
    return SnapshotFormat.parse(token or DEFAULT_SNAPSHOT_FORMAT, field_name="format")


def _snapshot_filename(
    value: Any,
    *,
    snapshot_id: str,
    format_value: SnapshotFormat,
    directory: Any = None,
) -> Path:
    raw = str(value or f"{snapshot_id}{format_value.extension}").strip()
    if not raw:
        raise VisualizationSnapshotError("Snapshot filename cannot be empty.")
    path = Path(raw).expanduser()
    if directory is not None:
        path = Path(directory).expanduser() / path.name
    if path.name in {"", ".", ".."}:
        raise VisualizationSnapshotError("Snapshot filename is invalid.", context={"filename": raw})
    expected = format_value.extension
    valid = {expected}
    if format_value is SnapshotFormat.JPEG:
        valid.add(".jpeg")
    if format_value is SnapshotFormat.TIFF:
        valid.add(".tif")
    if path.suffix.lower() not in valid:
        path = path.with_suffix(expected)
    return path


def _snapshot_size(value: Any, *, field_name: str = "size") -> Tuple[int, int]:
    if isinstance(value, Mapping):
        value = (value.get("width"), value.get("height"))
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)) or len(value) != 2:
        raise VisualizationImageError(
            f"{field_name} requires width and height.",
            context={"value": value},
        )
    return (
        _bounded_int(value[0], field_name=f"{field_name}.width", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION),
        _bounded_int(value[1], field_name=f"{field_name}.height", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION),
    )


def _snapshot_crop(value: Any) -> Optional[Tuple[int, int, int, int]]:
    if value is None:
        return None
    if isinstance(value, Mapping):
        value = (value.get("left", 0), value.get("top", 0), value.get("right"), value.get("bottom"))
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)) or len(value) != _SNAPSHOT_CROP_LENGTH:
        raise VisualizationImageError("crop requires left, top, right and bottom values.")
    crop = tuple(int(item) for item in value)
    if min(crop) < 0 or crop[2] <= crop[0] or crop[3] <= crop[1]:
        raise VisualizationImageError("crop bounds are invalid.", context={"crop": crop})
    return crop  # type: ignore[return-value]


def _snapshot_dependencies(plan: Optional[VisualizationPlan]) -> Tuple[str, ...]:
    if plan is None:
        return ()
    return tuple(
        action.action_id
        for action in plan.actions
        if action.enabled
        and action.layer is not VisualLayer.SNAPSHOT
        and action.operation not in {PlanOperation.SAVE_SNAPSHOT, PlanOperation.EXPORT_COMMANDS}
    )


def fit_image_dimensions(
    source_size: Sequence[int],
    target_size: Sequence[int],
    *,
    fit_mode: Any = ImageFitMode.CONTAIN,
    allow_upscale: bool = True,
) -> Tuple[int, int]:
    """Fit source dimensions into a target rectangle."""

    source_width, source_height = _snapshot_size(source_size, field_name="source_size")
    target_width, target_height = _snapshot_size(target_size, field_name="target_size")
    mode = ImageFitMode.parse(fit_mode, default=ImageFitMode.CONTAIN)
    if mode is ImageFitMode.STRETCH:
        return target_width, target_height
    if mode is ImageFitMode.NATIVE:
        return source_width, source_height
    scale_x = target_width / source_width
    scale_y = target_height / source_height
    scale = min(scale_x, scale_y) if mode is ImageFitMode.CONTAIN else max(scale_x, scale_y)
    if not allow_upscale:
        scale = min(scale, 1.0)
    return max(1, round(source_width * scale)), max(1, round(source_height * scale))


# 23.2. Image and snapshot specifications
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ImagePostprocessSpec(MolecularSpecMixin):
    """Optional raster post-processing."""

    enabled: bool = False
    trim: bool = False
    trim_tolerance: int = 0
    crop: Optional[Tuple[int, int, int, int]] = None
    size: Optional[Tuple[int, int]] = None
    fit_mode: ImageFitMode = ImageFitMode.CONTAIN
    allow_upscale: bool = True
    background: Optional[str] = None
    sharpen: bool = False
    optimize: bool = True
    preserve_metadata: bool = True
    output_format: Optional[SnapshotFormat] = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "trim", bool(self.trim))
        object.__setattr__(self, "trim_tolerance", _bounded_int(
            self.trim_tolerance, field_name="trim_tolerance", minimum=0, maximum=255
        ))
        object.__setattr__(self, "crop", _snapshot_crop(self.crop))
        object.__setattr__(self, "size", None if self.size is None else _snapshot_size(self.size))
        object.__setattr__(self, "fit_mode", ImageFitMode.parse(self.fit_mode, default=ImageFitMode.CONTAIN))
        object.__setattr__(self, "allow_upscale", bool(self.allow_upscale))
        object.__setattr__(self, "background", None if self.background is None else normalize_color(self.background))
        object.__setattr__(self, "sharpen", bool(self.sharpen))
        object.__setattr__(self, "optimize", bool(self.optimize))
        object.__setattr__(self, "preserve_metadata", bool(self.preserve_metadata))
        object.__setattr__(self, "output_format", None if self.output_format is None else SnapshotFormat.parse(self.output_format))
        if self.output_format is SnapshotFormat.SVG:
            raise VisualizationImageError("Raster post-processing cannot produce SVG output.")

    @property
    def active(self) -> bool:
        return self.enabled


@dataclass(frozen=True, slots=True)
class SnapshotRequestSpec(MolecularSpecMixin):
    """One backend-neutral snapshot request."""

    snapshot_id: str = _SNAPSHOT_DEFAULT_ID
    filename: PathLike = DEFAULT_SNAPSHOT_FILENAME
    format: SnapshotFormat = SnapshotFormat.PNG
    width: int = DEFAULT_SNAPSHOT_WIDTH
    height: int = DEFAULT_SNAPSHOT_HEIGHT
    supersample: int = DEFAULT_SNAPSHOT_SUPERSAMPLE
    quality: int = DEFAULT_SNAPSHOT_QUALITY
    dpi: int = DEFAULT_SNAPSHOT_DPI
    background: SnapshotBackground = SnapshotBackground.OPAQUE
    transparent: bool = DEFAULT_SNAPSHOT_TRANSPARENT
    fit_mode: ImageFitMode = ImageFitMode.CONTAIN
    view: StandardView = StandardView.AUTO
    camera: Optional[CameraStateSpec] = None
    postprocess: ImagePostprocessSpec = field(default_factory=ImagePostprocessSpec)
    overwrite: bool = False
    create_parents: bool = True
    wait_for_draw: bool = True
    delay: float = 0.0
    enabled: bool = True
    optional: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        snapshot_id = _snapshot_identifier(self.snapshot_id)
        format_value = _snapshot_format(self.format, filename=self.filename)
        filename = _snapshot_filename(self.filename, snapshot_id=snapshot_id, format_value=format_value)
        background = SnapshotBackground.parse(self.background, default=SnapshotBackground.OPAQUE)
        transparent = bool(self.transparent or background is SnapshotBackground.TRANSPARENT)
        if transparent and format_value not in _IMAGE_ALPHA_FORMATS and format_value is not SnapshotFormat.SVG:
            raise VisualizationSnapshotError(
                f"{format_value.value.upper()} does not support transparent output.",
                context={"snapshot_id": snapshot_id},
            )
        camera = None if self.camera is None else coerce_camera_state(self.camera)
        postprocess = coerce_image_postprocess_spec(self.postprocess)
        metadata = _normalize_spec_metadata(self.metadata)
        object.__setattr__(self, "snapshot_id", snapshot_id)
        object.__setattr__(self, "filename", filename)
        object.__setattr__(self, "format", format_value)
        object.__setattr__(self, "width", _bounded_int(self.width, field_name="width", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION))
        object.__setattr__(self, "height", _bounded_int(self.height, field_name="height", minimum=MIN_IMAGE_DIMENSION, maximum=MAX_IMAGE_DIMENSION))
        object.__setattr__(self, "supersample", _bounded_int(self.supersample, field_name="supersample", minimum=1, maximum=16))
        object.__setattr__(self, "quality", _bounded_int(self.quality, field_name="quality", minimum=1, maximum=100))
        object.__setattr__(self, "dpi", _bounded_int(self.dpi, field_name="dpi", minimum=1, maximum=2400))
        object.__setattr__(self, "background", background)
        object.__setattr__(self, "transparent", transparent)
        object.__setattr__(self, "fit_mode", ImageFitMode.parse(self.fit_mode, default=ImageFitMode.CONTAIN))
        object.__setattr__(self, "view", StandardView.parse(self.view, default=StandardView.AUTO))
        object.__setattr__(self, "camera", camera)
        object.__setattr__(self, "postprocess", postprocess)
        object.__setattr__(self, "overwrite", bool(self.overwrite))
        object.__setattr__(self, "create_parents", bool(self.create_parents))
        object.__setattr__(self, "wait_for_draw", bool(self.wait_for_draw))
        object.__setattr__(self, "delay", _bounded_float(self.delay, field_name="delay", minimum=0.0, maximum=_SNAPSHOT_MAX_DELAY))
        object.__setattr__(self, "enabled", bool(self.enabled))
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "metadata", metadata)

    @property
    def size(self) -> Tuple[int, int]:
        return self.width, self.height

    @property
    def render_size(self) -> Tuple[int, int]:
        return self.width * self.supersample, self.height * self.supersample

    @property
    def pixel_count(self) -> int:
        return self.render_size[0] * self.render_size[1]

    @property
    def output_path(self) -> Path:
        post_format = self.postprocess.output_format if self.postprocess.active else None
        return self.filename if post_format is None else self.filename.with_suffix(post_format.extension)


@dataclass(frozen=True, slots=True)
class SnapshotCollection(MolecularSpecMixin):
    """Ordered snapshot requests."""

    requests: Tuple[SnapshotRequestSpec, ...] = ()
    name: str = "snapshots"
    restore_camera: bool = True
    stop_on_error: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        requests = tuple(coerce_snapshot_request(item, index=index) for index, item in enumerate(self.requests))
        if len(requests) > _SNAPSHOT_MAX_REQUESTS:
            raise VisualizationLimitError(
                f"Snapshot collections cannot exceed {_SNAPSHOT_MAX_REQUESTS} requests.",
                context={"count": len(requests)},
            )
        identifiers = [item.snapshot_id for item in requests]
        duplicate_ids = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        paths = [str(item.output_path) for item in requests if item.enabled]
        duplicate_paths = sorted(key for key, count in Counter(paths).items() if count > 1)
        if duplicate_ids or duplicate_paths:
            raise VisualizationSnapshotError(
                "Snapshot identifiers and output paths must be unique.",
                context={"duplicate_ids": duplicate_ids, "duplicate_paths": duplicate_paths},
            )
        object.__setattr__(self, "requests", requests)
        object.__setattr__(self, "name", _snapshot_identifier(self.name, field_name="name"))
        object.__setattr__(self, "restore_camera", bool(self.restore_camera))
        object.__setattr__(self, "stop_on_error", bool(self.stop_on_error))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def enabled_requests(self) -> Tuple[SnapshotRequestSpec, ...]:
        return tuple(item for item in self.requests if item.enabled)

    @property
    def output_paths(self) -> Tuple[Path, ...]:
        return tuple(item.output_path for item in self.enabled_requests)


@dataclass(frozen=True, slots=True)
class ImageInfoSpec(MolecularSpecMixin):
    """Portable image metadata."""

    path: PathLike
    format: Optional[str] = None
    mode: Optional[str] = None
    width: Optional[int] = None
    height: Optional[int] = None
    has_alpha: bool = False
    frame_count: int = 1
    file_size: Optional[int] = None
    dpi: Optional[Tuple[float, float]] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        path = Path(self.path).expanduser()
        width = None if self.width is None else _bounded_int(self.width, field_name="width", minimum=1, maximum=MAX_IMAGE_DIMENSION * 16)
        height = None if self.height is None else _bounded_int(self.height, field_name="height", minimum=1, maximum=MAX_IMAGE_DIMENSION * 16)
        frame_count = _bounded_int(self.frame_count, field_name="frame_count", minimum=1, maximum=1_000_000)
        dpi = None
        if self.dpi is not None:
            if not isinstance(self.dpi, Sequence) or len(self.dpi) != 2:
                raise VisualizationImageError("dpi requires horizontal and vertical values.")
            dpi = (float(self.dpi[0]), float(self.dpi[1]))
        object.__setattr__(self, "path", path)
        object.__setattr__(self, "format", None if self.format is None else str(self.format).upper())
        object.__setattr__(self, "mode", None if self.mode is None else str(self.mode))
        object.__setattr__(self, "width", width)
        object.__setattr__(self, "height", height)
        object.__setattr__(self, "has_alpha", bool(self.has_alpha))
        object.__setattr__(self, "frame_count", frame_count)
        object.__setattr__(self, "file_size", None if self.file_size is None else max(0, int(self.file_size)))
        object.__setattr__(self, "dpi", dpi)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def size(self) -> Optional[Tuple[int, int]]:
        return None if self.width is None or self.height is None else (self.width, self.height)


@dataclass(frozen=True, slots=True)
class SnapshotResultSpec(MolecularSpecMixin):
    """Snapshot execution result."""

    snapshot_id: str
    path: PathLike
    success: bool = True
    image: Optional[ImageInfoSpec] = None
    duration: Optional[float] = None
    postprocessed: bool = False
    error: Optional[str] = None
    created_at: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        image = None if self.image is None else coerce_image_info(self.image)
        created_at = self.created_at or datetime.now(timezone.utc).isoformat()
        object.__setattr__(self, "snapshot_id", _snapshot_identifier(self.snapshot_id))
        object.__setattr__(self, "path", Path(self.path).expanduser())
        object.__setattr__(self, "success", bool(self.success))
        object.__setattr__(self, "image", image)
        object.__setattr__(self, "duration", None if self.duration is None else max(0.0, float(self.duration)))
        object.__setattr__(self, "postprocessed", bool(self.postprocessed))
        object.__setattr__(self, "error", _clean_spec_text(self.error, field_name="error", max_length=4096))
        object.__setattr__(self, "created_at", str(created_at))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))
        if self.success and self.error:
            raise VisualizationSnapshotError("Successful snapshot results cannot contain an error.")


@dataclass(frozen=True, slots=True)
class SnapshotManifestSpec(MolecularSpecMixin):
    """Serializable snapshot manifest."""

    collection_name: str
    results: Tuple[SnapshotResultSpec, ...] = ()
    created_at: Optional[str] = None
    visualization_fingerprint: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        results = tuple(coerce_snapshot_result(item) for item in self.results)
        identifiers = [item.snapshot_id for item in results]
        duplicates = sorted(key for key, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationSnapshotError("Snapshot result identifiers must be unique.", context={"duplicates": duplicates})
        object.__setattr__(self, "collection_name", _snapshot_identifier(self.collection_name, field_name="collection_name"))
        object.__setattr__(self, "results", results)
        object.__setattr__(self, "created_at", self.created_at or datetime.now(timezone.utc).isoformat())
        object.__setattr__(self, "visualization_fingerprint", _clean_spec_text(
            self.visualization_fingerprint, field_name="visualization_fingerprint", max_length=128
        ))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def successful(self) -> Tuple[SnapshotResultSpec, ...]:
        return tuple(item for item in self.results if item.success)

    @property
    def failed(self) -> Tuple[SnapshotResultSpec, ...]:
        return tuple(item for item in self.results if not item.success)


# 23.3. Coercion and construction
# -----------------------------------------------------------------------------

def coerce_image_postprocess_spec(value: Any = None) -> ImagePostprocessSpec:
    """Coerce image post-processing settings."""

    if value is None:
        return ImagePostprocessSpec()
    if isinstance(value, ImagePostprocessSpec):
        return value
    if isinstance(value, Mapping):
        data = dict(value)
        if "enabled" not in data:
            data["enabled"] = any(
                data.get(key) not in (None, False, (), [], {})
                for key in ("trim", "crop", "size", "background", "sharpen", "output_format")
            )
        return ImagePostprocessSpec(**data)
    data = {
        name: getattr(value, name)
        for name in (
            "enabled", "trim", "trim_tolerance", "crop", "size", "fit_mode",
            "allow_upscale", "background", "sharpen", "optimize",
            "preserve_metadata", "output_format",
        )
        if hasattr(value, name)
    }
    return ImagePostprocessSpec(**data)


def coerce_snapshot_request(
    value: Any = None,
    *,
    index: int = 0,
    config_value: Any = None,
    directory: Any = None,
) -> SnapshotRequestSpec:
    """Coerce one snapshot request."""

    config_obj = resolve_visualization_config(config_value)
    defaults = config_obj.snapshot
    if value is None:
        data: Dict[str, Any] = {}
    elif isinstance(value, SnapshotRequestSpec):
        if directory is None:
            return value
        return replace(value, filename=_snapshot_filename(
            value.filename, snapshot_id=value.snapshot_id, format_value=value.format, directory=directory
        ))
    elif isinstance(value, Mapping):
        data = dict(value)
    else:
        data = {
            name: getattr(value, name)
            for name in (
                "snapshot_id", "filename", "format", "width", "height",
                "supersample", "quality", "dpi", "background", "transparent",
                "fit_mode", "view", "camera", "postprocess", "overwrite",
                "create_parents", "wait_for_draw", "delay", "enabled", "optional",
                "metadata",
            )
            if hasattr(value, name)
        }
    data.setdefault("snapshot_id", _SNAPSHOT_DEFAULT_ID if index == 0 else f"snapshot_{index + 1}")
    data.setdefault("filename", defaults.filename if index == 0 else f"snapshot_{index + 1}{defaults.format.extension}")
    data.setdefault("format", defaults.format)
    data.setdefault("width", defaults.width)
    data.setdefault("height", defaults.height)
    data.setdefault("supersample", defaults.supersample)
    data.setdefault("quality", defaults.quality)
    data.setdefault("dpi", defaults.dpi)
    data.setdefault("background", defaults.background)
    data.setdefault("transparent", defaults.transparent)
    data.setdefault("fit_mode", defaults.fit_mode)
    format_value = _snapshot_format(data.get("format"), filename=data.get("filename"))
    data["format"] = format_value
    data["filename"] = _snapshot_filename(
        data.get("filename"),
        snapshot_id=_snapshot_identifier(data["snapshot_id"]),
        format_value=format_value,
        directory=directory,
    )
    return SnapshotRequestSpec(**data)


def _iter_snapshot_values(values: Any) -> Iterator[Any]:
    if values is None:
        return
    if isinstance(values, SnapshotCollection):
        yield from values.requests
        return
    if isinstance(values, Mapping) and "requests" in values:
        yield from values.get("requests", ())
        return
    if isinstance(values, Iterable) and not isinstance(values, (str, bytes, Mapping, SnapshotRequestSpec)):
        yield from values
        return
    yield values


def coerce_snapshot_collection(
    value: Any = None,
    *,
    config_value: Any = None,
    directory: Any = None,
    name: str = "snapshots",
) -> SnapshotCollection:
    """Coerce snapshot collection input."""

    if isinstance(value, SnapshotCollection) and directory is None:
        return value
    settings: Dict[str, Any] = {}
    values = value
    if isinstance(value, Mapping) and "requests" in value:
        settings = dict(value)
        values = settings.pop("requests", ())
    requests = tuple(
        coerce_snapshot_request(item, index=index, config_value=config_value, directory=directory)
        for index, item in enumerate(_iter_snapshot_values(values))
    )
    if not requests and value is None:
        requests = (coerce_snapshot_request(None, config_value=config_value, directory=directory),)
    settings.setdefault("name", name)
    settings["requests"] = requests
    return SnapshotCollection(**settings)


def build_view_snapshot_collection(
    views: Iterable[Any],
    *,
    directory: Any = None,
    prefix: str = "view",
    config_value: Any = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> SnapshotCollection:
    """Build one request per standard view."""

    config_obj = resolve_visualization_config(config_value)
    base = dict(overrides or {})
    requests: List[SnapshotRequestSpec] = []
    for index, value in enumerate(views):
        view = StandardView.parse(value, field_name=f"views[{index}]")
        snapshot_id = f"{_snapshot_identifier(prefix, field_name='prefix')}_{view.value}"
        data = {
            **base,
            "snapshot_id": snapshot_id,
            "filename": f"{snapshot_id}{_snapshot_format(base.get('format', config_obj.snapshot.format)).extension}",
            "view": view,
        }
        requests.append(coerce_snapshot_request(data, index=index, config_value=config_obj, directory=directory))
    return SnapshotCollection(requests=tuple(requests), name=f"{prefix}_views")


def build_pose_snapshot_collection(
    poses: Any,
    *,
    directory: Any = None,
    prefix: str = "pose",
    config_value: Any = None,
    overrides: Optional[Mapping[str, Any]] = None,
) -> SnapshotCollection:
    """Build one request per pose."""

    collection = coerce_pose_visual_collection(poses)
    config_obj = resolve_visualization_config(config_value)
    base = dict(overrides or {})
    requests: List[SnapshotRequestSpec] = []
    for index, pose in enumerate(collection.poses):
        token = _snapshot_identifier(pose.pose_id, field_name="pose_id")
        snapshot_id = f"{_snapshot_identifier(prefix, field_name='prefix')}_{token}"
        data = {
            **base,
            "snapshot_id": snapshot_id,
            "filename": f"{snapshot_id}{_snapshot_format(base.get('format', config_obj.snapshot.format)).extension}",
            "metadata": {**dict(base.get("metadata", {})), "pose_id": pose.pose_id, "rank": pose.rank},
        }
        requests.append(coerce_snapshot_request(data, index=index, config_value=config_obj, directory=directory))
    return SnapshotCollection(requests=tuple(requests), name=f"{prefix}_poses")


def coerce_image_info(value: Any) -> ImageInfoSpec:
    """Coerce image metadata."""

    if isinstance(value, ImageInfoSpec):
        return value
    if isinstance(value, Mapping):
        return ImageInfoSpec(**dict(value))
    if isinstance(value, (str, os.PathLike, Path)):
        return inspect_image_file(value)
    data = {
        name: getattr(value, name)
        for name in ("path", "format", "mode", "width", "height", "has_alpha", "frame_count", "file_size", "dpi", "metadata")
        if hasattr(value, name)
    }
    return ImageInfoSpec(**data)


def coerce_snapshot_result(value: Any) -> SnapshotResultSpec:
    """Coerce one snapshot result."""

    if isinstance(value, SnapshotResultSpec):
        return value
    if isinstance(value, Mapping):
        return SnapshotResultSpec(**dict(value))
    data = {
        name: getattr(value, name)
        for name in (
            "snapshot_id", "path", "success", "image", "duration",
            "postprocessed", "error", "created_at", "metadata",
        )
        if hasattr(value, name)
    }
    return SnapshotResultSpec(**data)


def create_snapshot_manifest(
    collection: Any,
    results: Iterable[Any],
    *,
    visualization: Any = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> SnapshotManifestSpec:
    """Create a result manifest."""

    resolved = coerce_snapshot_collection(collection)
    fingerprint = None
    if visualization is not None:
        fingerprint_method = getattr(visualization, "fingerprint", None)
        fingerprint = fingerprint_method() if callable(fingerprint_method) else _spec_fingerprint(visualization)
    return SnapshotManifestSpec(
        collection_name=resolved.name,
        results=tuple(coerce_snapshot_result(item) for item in results),
        visualization_fingerprint=fingerprint,
        metadata=metadata or {},
    )


# 23.4. Planning
# -----------------------------------------------------------------------------

def _snapshot_action_parameters(request: SnapshotRequestSpec) -> Dict[str, Any]:
    return {
        "snapshot_id": request.snapshot_id,
        "filename": str(request.filename),
        "format": request.format.value,
        "width": request.width,
        "height": request.height,
        "supersample": request.supersample,
        "quality": request.quality,
        "dpi": request.dpi,
        "background": request.background.value,
        "transparent": request.transparent,
        "fit_mode": request.fit_mode.value,
        "view": request.view.value,
        "camera": None if request.camera is None else request.camera.to_dict(),
        "postprocess": request.postprocess.to_dict(),
        "overwrite": request.overwrite,
        "create_parents": request.create_parents,
        "wait_for_draw": request.wait_for_draw,
        "delay": request.delay,
        "output_path": str(request.output_path),
    }


def build_snapshot_actions(
    value: Any = None,
    *,
    plan: Optional[VisualizationPlan] = None,
    config_value: Any = None,
    directory: Any = None,
) -> Tuple[VisualizationAction, ...]:
    """Build snapshot plan actions."""

    collection = coerce_snapshot_collection(value, config_value=config_value, directory=directory)
    base_dependencies = _snapshot_dependencies(plan)
    actions: List[VisualizationAction] = []
    previous: Optional[str] = None
    for index, request in enumerate(collection.enabled_requests):
        action_id = f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}"
        dependencies = base_dependencies
        if previous is not None:
            dependencies = (*dependencies, previous)
        actions.append(VisualizationAction(
            action_id=action_id,
            operation=PlanOperation.SAVE_SNAPSHOT,
            layer=VisualLayer.SNAPSHOT,
            parameters=_snapshot_action_parameters(request),
            depends_on=tuple(dict.fromkeys(dependencies)),
            priority=OperationPriority.LOW,
            enabled=True,
            optional=request.optional,
            description=f"Save snapshot {request.snapshot_id}.",
            tags=("snapshot", request.format.value, request.view.value),
            metadata={**dict(request.metadata), "collection": collection.name, "index": index},
        ))
        previous = action_id
    return tuple(actions)


def build_snapshot_plan(
    value: Any = None,
    *,
    config_value: Any = None,
    directory: Any = None,
    plan_id: str = "snapshot_plan",
    name: str = "Snapshots",
) -> VisualizationPlan:
    """Build a standalone snapshot plan."""

    config_obj = resolve_visualization_config(config_value)
    collection = coerce_snapshot_collection(value, config_value=config_obj, directory=directory)
    return VisualizationPlan(
        plan_id=plan_id,
        name=name,
        actions=build_snapshot_actions(collection, config_value=config_obj),
        profile=config_obj.profile,
        execution_mode=config_obj.backend.execution_mode,
        description="Capture configured visualization snapshots.",
        metadata={"snapshot_collection": collection.to_dict()},
    )


def attach_snapshots(
    plan: Any,
    value: Any = None,
    *,
    config_value: Any = None,
    directory: Any = None,
    replace_existing: bool = True,
) -> VisualizationPlan:
    """Attach snapshot actions to a plan."""

    resolved_plan = coerce_visualization_plan(plan)
    collection = coerce_snapshot_collection(value, config_value=config_value, directory=directory)
    retained = tuple(
        action for action in resolved_plan.actions
        if not replace_existing or action.operation is not PlanOperation.SAVE_SNAPSHOT
    )
    base = replace(resolved_plan, actions=retained)
    actions = build_snapshot_actions(collection, plan=base, config_value=config_value)
    metadata = dict(base.metadata)
    metadata["snapshot_collection"] = collection.to_dict()
    return replace(base, actions=(*retained, *actions), metadata=metadata)


# 23.5. Image inspection and post-processing
# -----------------------------------------------------------------------------

def _require_pillow(operation: str) -> None:
    if not PILLOW_AVAILABLE:
        raise VisualizationDependencyError("Pillow", operation=operation)


def inspect_image_file(path: PathLike, *, verify: bool = True) -> ImageInfoSpec:
    """Read raster image metadata."""

    _require_pillow("image inspection")
    source = Path(path).expanduser()
    if not source.is_file():
        raise VisualizationImageError("Image file does not exist.", context={"path": str(source)})
    try:
        with Image.open(source) as image:  # type: ignore[union-attr]
            image_format = image.format
            mode = image.mode
            width, height = image.size
            frame_count = int(getattr(image, "n_frames", 1))
            info = dict(image.info)
            dpi_raw = info.get("dpi")
            dpi = None
            if isinstance(dpi_raw, Sequence) and len(dpi_raw) >= 2:
                dpi = (float(dpi_raw[0]), float(dpi_raw[1]))
            has_alpha = "A" in mode or "transparency" in info
            safe_metadata = {
                key: value
                for key, value in info.items()
                if key in _SNAPSHOT_ALLOWED_METADATA and isinstance(value, (str, int, float, bool))
            }
            if verify:
                image.verify()
        return ImageInfoSpec(
            path=source,
            format=image_format,
            mode=mode,
            width=width,
            height=height,
            has_alpha=has_alpha,
            frame_count=frame_count,
            file_size=source.stat().st_size,
            dpi=dpi,
            metadata=safe_metadata,
        )
    except VisualizationError:
        raise
    except Exception as exc:
        raise VisualizationImageError(
            "Unable to inspect image file.",
            context={"path": str(source), "error": str(exc)},
        ) from exc


def _trim_image(image: Any, *, tolerance: int = 0) -> Any:
    from PIL import ImageChops

    background = Image.new(image.mode, image.size, image.getpixel((0, 0)))  # type: ignore[union-attr]
    difference = ImageChops.difference(image, background)
    if tolerance:
        difference = difference.point(lambda value: 0 if value <= tolerance else value)
    box = difference.getbbox()
    return image if box is None else image.crop(box)


def _fit_pillow_image(image: Any, size: Tuple[int, int], mode: ImageFitMode) -> Any:
    from PIL import ImageOps

    resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
    if mode is ImageFitMode.NATIVE:
        return image
    if mode is ImageFitMode.STRETCH:
        return image.resize(size, resample=resampling)
    if mode is ImageFitMode.COVER:
        return ImageOps.fit(image, size, method=resampling)
    image.thumbnail(size, resample=resampling)
    return image


def _flatten_image(image: Any, background: str) -> Any:
    rgba = image.convert("RGBA")
    color = normalize_color(background)
    rgb = tuple(int(color[index:index + 2], 16) for index in (1, 3, 5))
    base = Image.new("RGBA", rgba.size, (*rgb, 255))  # type: ignore[union-attr]
    base.alpha_composite(rgba)
    return base.convert("RGB")


def postprocess_image_file(
    source: PathLike,
    spec: Any,
    *,
    destination: Optional[PathLike] = None,
    overwrite: bool = False,
) -> ImageInfoSpec:
    """Apply configured raster post-processing."""

    _require_pillow("image post-processing")
    settings = coerce_image_postprocess_spec(spec)
    source_path = Path(source).expanduser()
    if not source_path.is_file():
        raise VisualizationImageError("Source image does not exist.", context={"path": str(source_path)})
    source_format = _snapshot_format(None, filename=source_path)
    if source_format not in _IMAGE_RASTER_FORMATS:
        raise VisualizationImageError("Post-processing requires a raster image.")
    output_format = settings.output_format or source_format
    if output_format not in _IMAGE_RASTER_FORMATS:
        raise VisualizationImageError("Output format is not supported by the raster processor.")
    target = Path(destination).expanduser() if destination is not None else source_path.with_suffix(output_format.extension)
    if target.exists() and target != source_path and not overwrite:
        raise VisualizationImageError("Destination image already exists.", context={"path": str(target)})
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary_path: Optional[Path] = None
    try:
        with Image.open(source_path) as opened:  # type: ignore[union-attr]
            image = opened.copy()
            source_info = dict(opened.info)
        if settings.trim:
            image = _trim_image(image, tolerance=settings.trim_tolerance)
        if settings.crop is not None:
            if settings.crop[2] > image.width or settings.crop[3] > image.height:
                raise VisualizationImageError(
                    "Crop bounds exceed image dimensions.",
                    context={"crop": settings.crop, "size": image.size},
                )
            image = image.crop(settings.crop)
        if settings.size is not None:
            desired = fit_image_dimensions(image.size, settings.size, fit_mode=settings.fit_mode, allow_upscale=settings.allow_upscale)
            image = _fit_pillow_image(image, desired, settings.fit_mode)
        if settings.background is not None:
            image = _flatten_image(image, settings.background)
        if settings.sharpen:
            from PIL import ImageFilter
            image = image.filter(ImageFilter.SHARPEN)
        if output_format is SnapshotFormat.JPEG and image.mode not in {"RGB", "L"}:
            image = _flatten_image(image, settings.background or DEFAULT_BACKGROUND_COLOR)
        save_options: Dict[str, Any] = {"format": _IMAGE_PIL_FORMATS[output_format]}
        if output_format in {SnapshotFormat.JPEG, SnapshotFormat.WEBP}:
            save_options["quality"] = DEFAULT_SNAPSHOT_QUALITY
        if output_format in {SnapshotFormat.PNG, SnapshotFormat.JPEG, SnapshotFormat.WEBP}:
            save_options["optimize"] = settings.optimize
        if settings.preserve_metadata and "dpi" in source_info:
            save_options["dpi"] = source_info["dpi"]
        with NamedTemporaryFile(
            dir=str(target.parent), prefix=f".{target.stem}.", suffix=target.suffix, delete=False
        ) as handle:
            temporary_path = Path(handle.name)
        image.save(temporary_path, **save_options)
        if target.exists() and target != source_path and not overwrite:
            raise VisualizationImageError("Destination image already exists.", context={"path": str(target)})
        os.replace(temporary_path, target)
        temporary_path = None
        return inspect_image_file(target)
    except VisualizationError:
        raise
    except Exception as exc:
        raise VisualizationImageError(
            "Image post-processing failed.",
            context={"source": str(source_path), "destination": str(target), "error": str(exc)},
        ) from exc
    finally:
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)


# 23.6. Validation, summaries and serialization
# -----------------------------------------------------------------------------

def validate_snapshot_request(
    value: Any,
    *,
    check_filesystem: bool = False,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate one snapshot request."""

    try:
        request = coerce_snapshot_request(value)
    except VisualizationError as exc:
        return (PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "snapshot_invalid",
            str(exc),
            None,
        ),)
    issues: List[PlanValidationIssue] = []
    if request.pixel_count > MAX_IMAGE_DIMENSION * MAX_IMAGE_DIMENSION * 16:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "snapshot_large_render",
            "Snapshot supersampling creates a very large render buffer.",
            f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
        ))
    if request.transparent and request.background is SnapshotBackground.OPAQUE:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "snapshot_transparency_overrides_background",
            "Transparent output overrides the opaque background policy.",
            f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
        ))
    if request.postprocess.active and request.format is SnapshotFormat.SVG:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.ERROR,
            "snapshot_svg_postprocess",
            "Raster post-processing cannot be applied to SVG snapshots.",
            f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
        ))
    if check_filesystem:
        parent = request.filename.parent
        if parent.exists() and not parent.is_dir():
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "snapshot_parent_not_directory",
                "Snapshot parent path is not a directory.",
                f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
            ))
        elif not parent.exists() and not request.create_parents:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "snapshot_parent_missing",
                "Snapshot parent directory does not exist.",
                f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
            ))
        if request.output_path.exists() and not request.overwrite:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "snapshot_output_exists",
                "Snapshot output already exists and overwrite is disabled.",
                f"{_SNAPSHOT_ACTION_PREFIX}{request.snapshot_id}",
            ))
    return tuple(issues)


def validate_snapshot_collection(
    value: Any,
    *,
    check_filesystem: bool = False,
    raise_on_error: bool = False,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate a snapshot collection."""

    try:
        collection = coerce_snapshot_collection(value)
    except VisualizationError as exc:
        issues = (PlanValidationIssue(ValidationIssueLevel.ERROR, "snapshot_collection_invalid", str(exc), None),)
        if raise_on_error:
            raise VisualizationSnapshotError(str(exc)) from exc
        return issues
    issues = tuple(
        issue
        for request in collection.requests
        for issue in validate_snapshot_request(request, check_filesystem=check_filesystem)
    )
    if not collection.enabled_requests:
        issues = (*issues, PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "snapshot_collection_empty",
            "Snapshot collection has no enabled requests.",
            None,
        ))
    if raise_on_error and any(issue.level is ValidationIssueLevel.ERROR for issue in issues):
        raise VisualizationSnapshotError(
            "Snapshot collection validation failed.",
            context={"issues": [issue.to_dict() for issue in issues]},
        )
    return issues


def summarize_snapshots(value: Any = None, *, config_value: Any = None) -> Dict[str, Any]:
    """Return compact snapshot statistics."""

    collection = coerce_snapshot_collection(value, config_value=config_value)
    enabled = collection.enabled_requests
    issues = validate_snapshot_collection(collection)
    return {
        "name": collection.name,
        "total": len(collection.requests),
        "enabled": len(enabled),
        "formats": dict(Counter(item.format.value for item in enabled)),
        "views": dict(Counter(item.view.value for item in enabled)),
        "transparent": sum(item.transparent for item in enabled),
        "postprocessed": sum(item.postprocess.active for item in enabled),
        "pixel_count": sum(item.pixel_count for item in enabled),
        "output_paths": [str(item.output_path) for item in enabled],
        "issue_levels": dict(Counter(issue.level.name.lower() for issue in issues)),
        "fingerprint": collection.fingerprint(),
    }


def summarize_snapshot_manifest(value: Any) -> Dict[str, Any]:
    """Return compact manifest statistics."""

    manifest = value if isinstance(value, SnapshotManifestSpec) else SnapshotManifestSpec(**dict(value))
    durations = [item.duration for item in manifest.results if item.duration is not None]
    return {
        "collection_name": manifest.collection_name,
        "total": len(manifest.results),
        "successful": len(manifest.successful),
        "failed": len(manifest.failed),
        "postprocessed": sum(item.postprocessed for item in manifest.results),
        "duration": sum(durations),
        "fingerprint": manifest.fingerprint(),
    }


def snapshots_to_dict(value: Any = None, *, config_value: Any = None) -> Dict[str, Any]:
    """Serialize snapshot settings."""

    return coerce_snapshot_collection(value, config_value=config_value).to_dict()


def snapshots_to_json(
    value: Any = None,
    *,
    config_value: Any = None,
    indent: Optional[int] = 2,
) -> str:
    """Serialize snapshot settings as JSON."""

    return json.dumps(
        snapshots_to_dict(value, config_value=config_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


