# 24.1. Models and helpers
# -----------------------------------------------------------------------------

_COMMAND_SCHEMA_VERSION: Final[str] = "1.0"
_COMMAND_SAFE_NAMES: Final[FrozenSet[str]] = frozenset({
    *CHIMERAX_COMMAND_NAMES,
    "2dlabels", "cartoon", "clip", "graphics", "key", "matchmaker",
    "marker", "size", "surface", "transparency", "windowsize",
})
_COMMAND_ID_PATTERN: Final[re.Pattern[str]] = re.compile(r"^[A-Za-z][A-Za-z0-9_.:-]{0,127}$")
_COMMAND_CONTROL_PATTERN: Final[re.Pattern[str]] = re.compile(COMMAND_UNSAFE_PATTERN)
_COMMAND_HEADER_TITLE: Final[str] = "DockAnalyzer visualization commands"
_COMMAND_EXPORT_ACTION_ID: Final[str] = "commands:export"
_COMMAND_MARKER_MODEL_BASE: Final[int] = 9000


def _command_identifier(value: Any, *, field_name: str = "command_id") -> str:
    text = str(value).strip()
    if not _COMMAND_ID_PATTERN.fullmatch(text):
        raise VisualizationCommandError(
            f"Invalid {field_name}.", context={field_name: text}
        )
    return text


def _command_text_value(value: Any, *, field_name: str = "command") -> str:
    text = str(value).strip()
    if not text:
        raise VisualizationCommandError(f"{field_name} cannot be empty.")
    if "\n" in text or "\r" in text or _COMMAND_CONTROL_PATTERN.search(text):
        raise VisualizationCommandError(
            f"{field_name} must be one safe line.", context={field_name: text}
        )
    return text


def _command_name(text: str) -> str:
    token = text.lstrip().split(maxsplit=1)[0].lower()
    return token[1:] if token.startswith("~") else token


def quote_chimerax_value(value: Any, *, always: bool = False) -> str:
    """Quote one ChimeraX argument."""

    text = str(value)
    unsafe = any(char.isspace() for char in text) or any(char in text for char in "'\";#")
    if not always and text and not unsafe:
        return text
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def format_chimerax_number(value: Any, *, precision: int = 6) -> str:
    """Format one finite number."""

    number = float(value)
    if not math.isfinite(number):
        raise VisualizationCommandError("Command numbers must be finite.")
    text = f"{number:.{precision}f}".rstrip("0").rstrip(".")
    return "0" if text in {"", "-0"} else text


def format_chimerax_point(value: Any) -> str:
    """Format one point specification."""

    point = normalize_point3d(value, field_name="point")
    return ",".join(format_chimerax_number(item) for item in point)


def format_chimerax_bool(value: Any) -> str:
    """Format one Boolean option."""

    return "true" if bool(value) else "false"


def format_chimerax_color(value: Any) -> str:
    """Format one color specification."""

    return normalize_color(value)


def format_chimerax_selection(value: Any, *, allow_none: bool = False) -> str:
    """Format one atom specification as a single ChimeraX command token."""

    selection = coerce_selection(value)
    if selection.is_none:
        if allow_none:
            return ""
        raise VisualizationCommandError("A command requires a molecular selection.")
    text = selection.expression.strip()
    if ";" in text or "\n" in text or "\r" in text or _COMMAND_CONTROL_PATTERN.search(text):
        raise VisualizationCommandError("Unsafe selection in command export.")
    # ChimeraX parses whitespace as command-argument separators.  Keep Boolean
    # atom-spec operators inside one token so compound selections such as
    # ``#2 | #3 | #4`` are emitted as ``#2|#3|#4`` rather than extra command
    # arguments. Parentheses and negation remain unchanged.
    return re.sub(r"\s*([|&])\s*", r"\1", text)


def _command_join(*parts: Any) -> str:
    return " ".join(str(part) for part in parts if part is not None and str(part) != "")


def _command_opacity_percent(value: Any) -> int:
    opacity = _bounded_float(value, field_name="opacity", minimum=0.0, maximum=1.0)
    return int(round((1.0 - opacity) * 100.0))


def validate_chimerax_command(
    value: Any,
    *,
    policy: Any = ChimeraXCommandPolicy.SAFE,
    maximum_length: int = DEFAULT_COMMAND_MAX_LENGTH,
) -> Tuple[str, ...]:
    """Return command safety issues."""

    issues: List[str] = []
    try:
        text = _command_text_value(value)
    except VisualizationError as exc:
        return (str(exc),)
    if text.lstrip().startswith(COMMAND_COMMENT_PREFIX):
        return ()
    mode = ChimeraXCommandPolicy.parse(policy, default=ChimeraXCommandPolicy.SAFE)
    maximum = _bounded_int(
        maximum_length,
        field_name="maximum_length",
        minimum=1,
        maximum=MAX_SELECTION_LENGTH,
    )
    if len(text) > maximum:
        issues.append(f"Command exceeds {maximum} characters.")
    if mode is not ChimeraXCommandPolicy.PERMISSIVE and COMMAND_SEPARATOR in text:
        issues.append("Command separators are not allowed.")
    if mode is ChimeraXCommandPolicy.STRICT and _command_name(text) not in _COMMAND_SAFE_NAMES:
        issues.append(f"Unsupported ChimeraX command: {_command_name(text)!r}.")
    return tuple(issues)


@dataclass(frozen=True, slots=True)
class CommandSpec(MolecularSpecMixin):
    """One exported command."""

    command_id: str
    text: str
    action_id: Optional[str] = None
    sequence: int = 0
    status: CommandStatus = CommandStatus.VALIDATED
    optional: bool = False
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        text = _command_text_value(self.text)
        object.__setattr__(self, "command_id", _command_identifier(self.command_id))
        object.__setattr__(self, "text", text)
        object.__setattr__(
            self,
            "action_id",
            None if self.action_id is None else _command_identifier(self.action_id, field_name="action_id"),
        )
        object.__setattr__(self, "sequence", _bounded_int(self.sequence, field_name="sequence", minimum=0, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "status", CommandStatus.parse(self.status, default=CommandStatus.VALIDATED))
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def name(self) -> str:
        return _command_name(self.text)

    @property
    def is_comment(self) -> bool:
        return self.text.lstrip().startswith(COMMAND_COMMENT_PREFIX)


@dataclass(frozen=True, slots=True)
class CommandBatchSpec(MolecularSpecMixin):
    """One ordered command batch."""

    batch_id: str
    commands: Tuple[CommandSpec, ...]
    index: int = 0
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        commands = tuple(
            item if isinstance(item, CommandSpec) else CommandSpec(**dict(item))
            for item in self.commands
        )
        object.__setattr__(self, "batch_id", _command_identifier(self.batch_id, field_name="batch_id"))
        object.__setattr__(self, "commands", commands)
        object.__setattr__(self, "index", _bounded_int(self.index, field_name="index", minimum=0, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def text(self) -> Tuple[str, ...]:
        return tuple(item.text for item in self.commands)


@dataclass(frozen=True, slots=True)
class CommandScriptSpec(MolecularSpecMixin):
    """Portable ChimeraX command script."""

    plan_id: str
    commands: Tuple[CommandSpec, ...]
    title: str = _COMMAND_HEADER_TITLE
    language: str = VISUALIZATION_COMMAND_LANGUAGE
    schema_version: str = _COMMAND_SCHEMA_VERSION
    generated_at: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        commands = tuple(
            item if isinstance(item, CommandSpec) else CommandSpec(**dict(item))
            for item in self.commands
        )
        identifiers = [item.command_id for item in commands]
        duplicates = sorted(name for name, count in Counter(identifiers).items() if count > 1)
        if duplicates:
            raise VisualizationCommandError(
                "Command identifiers must be unique.", context={"duplicates": duplicates}
            )
        generated = self.generated_at or datetime.now(timezone.utc).isoformat()
        object.__setattr__(self, "plan_id", _command_identifier(self.plan_id, field_name="plan_id"))
        object.__setattr__(self, "commands", commands)
        object.__setattr__(self, "title", _clean_spec_text(self.title, field_name="title", max_length=256) or _COMMAND_HEADER_TITLE)
        object.__setattr__(self, "language", _clean_spec_text(self.language, field_name="language", max_length=64) or VISUALIZATION_COMMAND_LANGUAGE)
        object.__setattr__(self, "schema_version", _clean_spec_text(self.schema_version, field_name="schema_version", max_length=32) or _COMMAND_SCHEMA_VERSION)
        object.__setattr__(self, "generated_at", _clean_spec_text(generated, field_name="generated_at", max_length=128))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def command_texts(self) -> Tuple[str, ...]:
        return tuple(item.text for item in self.commands)

    @property
    def action_ids(self) -> Tuple[str, ...]:
        return tuple(dict.fromkeys(item.action_id for item in self.commands if item.action_id))

    def fingerprint(self) -> str:
        return _spec_fingerprint({
            "plan_id": self.plan_id,
            "language": self.language,
            "schema_version": self.schema_version,
            "commands": self.command_texts,
        })


@dataclass(frozen=True, slots=True)
class CommandExportSpec(MolecularSpecMixin):
    """Command-export settings."""

    filename: Path = Path(DEFAULT_COMMAND_FILENAME)
    format: CommandExportFormat = CommandExportFormat.CHIMERAX
    newline: str = DEFAULT_COMMAND_NEWLINE
    encoding: str = "utf-8"
    include_header: bool = True
    include_comments: bool = True
    include_disabled: bool = False
    include_optional: bool = True
    include_waits: bool = True
    wait_frames: int = DEFAULT_CHIMERAX_WAIT_FRAMES
    batch_size: int = DEFAULT_COMMAND_BATCH_SIZE
    max_command_length: int = DEFAULT_COMMAND_MAX_LENGTH
    command_policy: ChimeraXCommandPolicy = ChimeraXCommandPolicy.SAFE
    overwrite: bool = True
    create_parents: bool = True
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        export_format = CommandExportFormat.parse(self.format, default=CommandExportFormat.CHIMERAX)
        path = Path(self.filename).expanduser()
        if path.suffix.lower() != export_format.extension:
            path = path.with_suffix(export_format.extension)
        if self.newline not in {"\n", "\r\n"}:
            raise VisualizationExportError("Command newline must be LF or CRLF.")
        encoding = str(self.encoding).strip().lower()
        if encoding not in {"utf-8", "utf-8-sig"}:
            raise VisualizationExportError("Command encoding must be UTF-8.")
        object.__setattr__(self, "filename", path)
        object.__setattr__(self, "format", export_format)
        object.__setattr__(self, "encoding", encoding)
        for name in (
            "include_header", "include_comments", "include_disabled", "include_optional",
            "include_waits", "overwrite", "create_parents",
        ):
            object.__setattr__(self, name, bool(getattr(self, name)))
        object.__setattr__(self, "wait_frames", _bounded_int(self.wait_frames, field_name="wait_frames", minimum=0, maximum=100000))
        object.__setattr__(self, "batch_size", _bounded_int(self.batch_size, field_name="batch_size", minimum=1, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "max_command_length", _bounded_int(self.max_command_length, field_name="max_command_length", minimum=1, maximum=MAX_SELECTION_LENGTH))
        object.__setattr__(self, "command_policy", ChimeraXCommandPolicy.parse(self.command_policy, default=ChimeraXCommandPolicy.SAFE))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))


@dataclass(frozen=True, slots=True)
class CommandExportResult(MolecularSpecMixin):
    """Completed command export."""

    path: Path
    format: CommandExportFormat
    command_count: int
    batch_count: int
    bytes_written: int
    script_fingerprint: str
    created_at: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", Path(self.path).expanduser())
        object.__setattr__(self, "format", CommandExportFormat.parse(self.format, default=CommandExportFormat.CHIMERAX))
        object.__setattr__(self, "command_count", _bounded_int(self.command_count, field_name="command_count", minimum=0, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "batch_count", _bounded_int(self.batch_count, field_name="batch_count", minimum=0, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "bytes_written", _bounded_int(self.bytes_written, field_name="bytes_written", minimum=0))
        object.__setattr__(self, "script_fingerprint", str(self.script_fingerprint))
        object.__setattr__(self, "created_at", self.created_at or datetime.now(timezone.utc).isoformat())
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))


# 24.2. Action rendering
# -----------------------------------------------------------------------------


def _command_from_text(
    text: str,
    *,
    action: VisualizationAction,
    sequence: int,
    suffix: int,
    metadata: Optional[Mapping[str, Any]] = None,
) -> CommandSpec:
    return CommandSpec(
        command_id=f"cmd:{sequence:06d}:{suffix:03d}",
        text=text,
        action_id=action.action_id,
        sequence=sequence,
        optional=action.optional,
        metadata=metadata or {},
    )


def _render_representation_commands(
    selection: str,
    parameters: Mapping[str, Any],
) -> List[str]:
    representation = MolecularRepresentation.parse(
        parameters.get("representation", REPRESENTATION_STICKS),
        default=MolecularRepresentation.STICKS,
    )
    commands: List[str] = []
    if representation is MolecularRepresentation.NONE:
        return [f"hide {selection}"]
    if representation in {MolecularRepresentation.CARTOON, MolecularRepresentation.RIBBON}:
        commands.append(f"cartoon {selection}")
        target = "r"
    elif representation is MolecularRepresentation.SURFACE:
        commands.append(f"surface {selection}")
        target = "s"
    else:
        commands.append(f"show {selection} atoms")
        target = "a"
        style = {
            MolecularRepresentation.STICKS: "stick",
            MolecularRepresentation.BALL_STICK: "ball",
            MolecularRepresentation.SPHERES: "sphere",
            MolecularRepresentation.WIREFRAME: "stick",
        }.get(representation)
        if style:
            commands.append(f"style {selection} {style}")
    color = parameters.get("color") or parameters.get("fixed_color")
    if color:
        commands.append(f"color {selection} {format_chimerax_color(color)} target {target}")
    opacity = parameters.get("opacity")
    if opacity is not None and float(opacity) < 1.0:
        commands.append(f"transparency {selection} {_command_opacity_percent(opacity)} target {target}")
    stick_radius = parameters.get("stick_radius") or parameters.get("radius")
    if stick_radius is not None and representation in {
        MolecularRepresentation.STICKS,
        MolecularRepresentation.BALL_STICK,
        MolecularRepresentation.WIREFRAME,
    }:
        commands.append(f"size {selection} stickRadius {format_chimerax_number(stick_radius)}")
    return commands


def _render_prepare_scene(action: VisualizationAction) -> List[str]:
    params = action.parameters
    component = str(params.get("component") or action.action_id.split(":")[-1]).lower()
    selection = format_chimerax_selection(action.selection, allow_none=True)
    if component == "reset":
        mode = str(params.get("mode", "display"))
        if mode == "full" and not params.get("preserve_models", True):
            return ["close all"]
        if mode in {"display", "visualization", "full"}:
            return ["hide all", "surface hidePatches all", "2dlabels delete all"]
        if mode == "selection":
            return ["select clear"]
    if component == "background":
        return [f"set bgColor {format_chimerax_color(params.get('background', DEFAULT_BACKGROUND_COLOR))}"]
    if component == "lighting":
        return [f"lighting {quote_chimerax_value(params.get('mode', DEFAULT_CHIMERAX_LIGHTING))}"]
    if component == "silhouettes":
        return [f"graphics silhouettes {format_chimerax_bool(params.get('enabled', True))}"]
    if component in {"clear_selection", "selection"}:
        return ["select clear"]
    if component in {"hide_solvent", "hide_ions", "hide_hydrogens"} and selection:
        if component == "hide_hydrogens":
            return [f"hide ({selection}) & element.H atoms"]
        return [f"hide {selection} atoms"]
    if component == "hide_nonfocus" and selection:
        focus = params.get("focus_selection")
        commands = [f"hide {selection} atoms"]
        if focus:
            commands.append(f"show {focus} atoms")
        return commands
    return []


def _render_molecular_action(action: VisualizationAction) -> List[str]:
    selection = format_chimerax_selection(action.selection, allow_none=True)
    params = action.parameters
    component = str(params.get("component", ""))
    if component in {"multipose_alignment"}:
        reference = params.get("reference_pose_id")
        mobiles = params.get("mobile_pose_ids", ())
        if not reference or not mobiles:
            return []
        return [
            f"matchmaker {quote_chimerax_value(mobile)} to {quote_chimerax_value(reference)}"
            for mobile in mobiles
        ]
    if component in {"multipose_group", "multipose_sequence", "multipose_interactions", "complementarity_summary"}:
        return []
    if not selection:
        return []
    commands = _render_representation_commands(selection, params)
    if params.get("visible") is False:
        commands.append(f"hide {selection}")
    return commands


def _endpoint_argument(
    value: Mapping[str, Any],
    *,
    prefer_selection: bool = True,
) -> Optional[str]:
    selection = value.get("selection")
    if prefer_selection and selection:
        return str(selection)
    point = value.get("point")
    if point is not None:
        return format_chimerax_point(point)
    if selection:
        return str(selection)
    return None


def _marker_model_spec(action: VisualizationAction, *, offset: int = 0) -> str:
    digest = int(sha256(action.action_id.encode("utf-8")).hexdigest()[:6], 16)
    return f"#{_COMMAND_MARKER_MODEL_BASE + (digest % 900)}.{offset + 1}"


def _render_interaction_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    segments = tuple(params.get("segments", ()))
    if not segments:
        return _render_molecular_action(action)
    commands: List[str] = []
    color = format_chimerax_color(color_with_opacity(
        params.get("color", INTERACTION_FAMILY_COLORS[INTERACTION_UNKNOWN]),
        params.get("opacity", DEFAULT_INTERACTION_OPACITY),
    ))
    radius = format_chimerax_number(params.get("radius", DEFAULT_INTERACTION_RADIUS))
    dashes = int(params.get("dash_count", DEFAULT_INTERACTION_DASH_COUNT))
    if str(params.get("line_style", LineStyle.DASHED.value)) == LineStyle.SOLID.value:
        dashes = 0
    group_name = quote_chimerax_value(params.get("group_name", DEFAULT_PSEUDOBOND_GROUP), always=True)
    show_distance = format_chimerax_bool(params.get("show_distances", False))
    for index, segment in enumerate(segments):
        source_data = segment.get("source", {})
        target_data = segment.get("target", {})
        source_is_atom = (
            bool(source_data.get("selection"))
            and source_data.get("selection_kind") == SelectionKind.ATOM.value
        )
        target_is_atom = (
            bool(target_data.get("selection"))
            and target_data.get("selection_kind") == SelectionKind.ATOM.value
        )
        use_atom_selections = source_is_atom and target_is_atom
        if not use_atom_selections and (
            source_data.get("point") is None
            or target_data.get("point") is None
        ):
            raise VisualizationCommandError(
                "Non-atomic interaction endpoints require explicit coordinates.",
                context={"interaction_id": segment.get("interaction_id")},
            )
        source = _endpoint_argument(
            source_data,
            prefer_selection=use_atom_selections,
        )
        target = _endpoint_argument(
            target_data,
            prefer_selection=use_atom_selections,
        )
        if not source or not target:
            raise VisualizationCommandError(
                "Interaction endpoints cannot be rendered.",
                context={"interaction_id": segment.get("interaction_id")},
            )
        if use_atom_selections:
            commands.append(
                _command_join(
                    "pbond", source, target,
                    "showDist", show_distance,
                    "color", color,
                    "radius", radius,
                    "dashes", dashes,
                    "name", group_name,
                )
            )
        else:
            label = segment.get("label") if params.get("show_labels") else None
            commands.append(
                _command_join(
                    "marker segment", _marker_model_spec(action, offset=index),
                    "position", source,
                    "toPosition", target,
                    "color", color,
                    "radius", radius,
                    "label", quote_chimerax_value(label, always=True) if label else None,
                )
            )
    return commands


def _render_marker_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    points = tuple(params.get("points", ()))
    commands: List[str] = []
    model = _marker_model_spec(action)
    for point in points:
        coordinate = point.get("coordinate")
        if coordinate is None:
            continue
        commands.append(_command_join(
            "marker", model,
            "position", format_chimerax_point(coordinate),
            "radius", format_chimerax_number(point.get("radius", MIN_RADIUS)),
            "color", format_chimerax_color(point.get("color", DEFAULT_HIGHLIGHT_COLOR)),
        ))
        normal_endpoint = point.get("normal_endpoint")
        if normal_endpoint is not None:
            commands.append(_command_join(
                "marker segment", model,
                "position", format_chimerax_point(coordinate),
                "toPosition", format_chimerax_point(normal_endpoint),
                "radius", format_chimerax_number(max(MIN_RADIUS, float(point.get("radius", MIN_RADIUS)) * 0.35)),
                "color", format_chimerax_color(point.get("color", DEFAULT_HIGHLIGHT_COLOR)),
            ))
    return commands


def _render_residue_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    residues = tuple(params.get("residues", ()))
    commands: List[str] = []
    if residues:
        for residue in residues:
            selection = residue.get("selection")
            if not selection:
                continue
            commands.extend(_render_representation_commands(str(selection), {
                "representation": params.get("representation", REPRESENTATION_STICKS),
                "color": residue.get("color", params.get("fixed_color", DEFAULT_HIGHLIGHT_COLOR)),
                "opacity": params.get("opacity", 1.0),
                "stick_radius": params.get("stick_radius"),
            }))
        return commands
    return _render_molecular_action(action)


def _render_hotspot_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    hotspots = tuple(params.get("hotspots", ()))
    mode = str(params.get("render_mode", "residues"))
    commands: List[str] = []
    if mode in {"markers", "spheres"}:
        model = _marker_model_spec(action)
        for hotspot in hotspots:
            center = hotspot.get("center")
            if center is None:
                continue
            commands.append(_command_join(
                "marker", model,
                "position", format_chimerax_point(center),
                "radius", format_chimerax_number(hotspot.get("radius", DEFAULT_HOTSPOT_RADIUS)),
                "color", format_chimerax_color(hotspot.get("color", DEFAULT_HOTSPOT_COLOR)),
            ))
        return commands
    for hotspot in hotspots:
        selection = hotspot.get("selection")
        if not selection:
            continue
        if mode == "surface":
            commands.append(_command_join(
                "surface", selection,
                "color", format_chimerax_color(hotspot.get("color", DEFAULT_HOTSPOT_COLOR)),
                "transparency", _command_opacity_percent(params.get("opacity", DEFAULT_HOTSPOT_OPACITY)),
            ))
        else:
            commands.extend(_render_representation_commands(str(selection), {
                "representation": REPRESENTATION_STICKS,
                "color": hotspot.get("color", DEFAULT_HOTSPOT_COLOR),
                "opacity": params.get("opacity", 1.0),
            }))
    return commands


def _render_scoring_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    commands: List[str] = []
    for item in params.get("items", ()):
        selection = item.get("selection")
        if not selection:
            continue
        if params.get("apply_color", True) and item.get("color"):
            commands.append(f"color {selection} {format_chimerax_color(item['color'])}")
        if params.get("apply_radius") and item.get("radius") is not None:
            commands.append(f"size {selection} stickRadius {format_chimerax_number(item['radius'])}")
        if params.get("apply_opacity") and item.get("opacity") is not None:
            commands.append(f"transparency {selection} {_command_opacity_percent(item['opacity'])}")
    return commands


def _annotation_style_options(style: Mapping[str, Any]) -> List[str]:
    options: List[str] = []
    if style.get("color"):
        options.extend(("color", format_chimerax_color(style["color"])))
    if style.get("background"):
        options.extend(("bgColor", format_chimerax_color(style["background"])))
    if style.get("font_size"):
        options.extend(("size", str(int(style["font_size"]))))
    if style.get("font"):
        options.extend(("font", quote_chimerax_value(style["font"], always=True)))
    if style.get("bold") is not None:
        options.extend(("bold", format_chimerax_bool(style["bold"])))
    if style.get("italic") is not None:
        options.extend(("italic", format_chimerax_bool(style["italic"])))
    return options


def _render_label_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    component = str(params.get("component", ""))
    commands: List[str] = []
    annotations = tuple(params.get("annotations", ()))
    if annotations:
        for item in annotations:
            text = quote_chimerax_value(item.get("text", ""), always=True)
            style = item.get("style", {})
            anchor = item.get("anchor")
            selection = item.get("selection")
            if anchor == LabelAnchor.SCREEN.value or item.get("screen_position") is not None:
                position = item.get("screen_position") or (0.5, 0.5)
                commands.append(_command_join(
                    "2dlabels text", text,
                    "xpos", format_chimerax_number(position[0]),
                    "ypos", format_chimerax_number(position[1]),
                    *_annotation_style_options(style),
                ))
            elif selection:
                commands.append(_command_join(
                    "label", selection,
                    "text", text,
                    "color", format_chimerax_color(style.get("color", DEFAULT_LABEL_COLOR)),
                    "height", format_chimerax_number(style.get("font_size", DEFAULT_LABEL_FONT_SIZE) / 10.0),
                ))
            elif item.get("point") is not None:
                model = _marker_model_spec(action, offset=len(commands))
                commands.append(_command_join(
                    "marker", model,
                    "position", format_chimerax_point(item["point"]),
                    "radius", format_chimerax_number(MIN_RADIUS),
                    "color", format_chimerax_color(style.get("color", DEFAULT_LABEL_COLOR)),
                ))
                commands.append(_command_join(
                    "label", model,
                    "text", text,
                    "color", format_chimerax_color(style.get("color", DEFAULT_LABEL_COLOR)),
                ))
        return commands
    labels = tuple(params.get("labels", ()))
    if labels:
        for item in labels:
            selection = item.get("selection")
            text = item.get("text") or item.get("label")
            if selection and text:
                commands.append(_command_join(
                    "label", selection,
                    "text", quote_chimerax_value(text, always=True),
                    "color", format_chimerax_color(item.get("color", DEFAULT_LABEL_COLOR)),
                ))
        return commands
    if component == "legends":
        for legend in params.get("legends", ()):
            title = legend.get("title") or legend.get("name") or "Legend"
            commands.append(_command_join(
                "2dlabels text", quote_chimerax_value(title, always=True),
                "xpos", "0.02", "ypos", "0.95",
                "color", format_chimerax_color(DEFAULT_LABEL_COLOR),
                "size", DEFAULT_LABEL_FONT_SIZE,
            ))
    return commands


def _render_camera_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    component = str(params.get("component", "framing"))
    if component == "clipping":
        if not params.get("enabled", True):
            return ["clip near off far off"]
        return [_command_join(
            "clip",
            "near", params.get("near") if params.get("near") is not None else "off",
            "far", params.get("far") if params.get("far") is not None else "off",
        )]
    commands: List[str] = []
    mode = str(params.get("mode", CAMERA_MODE_ORTHOGRAPHIC))
    commands.append(f"camera {'ortho' if mode == CAMERA_MODE_ORTHOGRAPHIC else 'mono'}")
    selection_value = params.get("selection") or action.selection
    selection = format_chimerax_selection(selection_value, allow_none=True)
    if params.get("fit", True) and selection:
        commands.append(f"view {selection} clip false")
    elif params.get("view") and params.get("view") != "auto":
        view = str(params["view"])
        turns = {
            "back": ("turn y 180",),
            "left": ("turn y -90",),
            "right": ("turn y 90",),
            "top": ("turn x 90",),
            "bottom": ("turn x -90",),
            "isometric": ("turn y 45", "turn x 30"),
        }
        commands.extend(turns.get(view, ()))
    zoom = params.get("zoom")
    if zoom is not None and float(zoom) != 1.0:
        commands.append(f"zoom {format_chimerax_number(zoom)}")
    center_value = params.get("center_of_rotation")
    if isinstance(center_value, bool):
        center = params.get("target") if center_value else None
    else:
        center = center_value if center_value is not None else params.get("target")
    if center is not None:
        commands.append(f"cofr {format_chimerax_point(center)}")
    wait_frames = int(params.get("wait_frames", 0) or 0)
    if params.get("animate") and wait_frames:
        commands.append(f"wait {wait_frames}")
    return commands


def _render_snapshot_action(action: VisualizationAction) -> List[str]:
    params = action.parameters
    commands: List[str] = []
    if params.get("wait_for_draw", True):
        commands.append(f"wait {max(1, int(params.get('delay', 0) or 0), DEFAULT_CHIMERAX_WAIT_FRAMES)}")
    path = params.get("output_path") or params.get("filename")
    if not path:
        raise VisualizationCommandError("Snapshot action has no output path.")
    try:
        path = Path(os.fspath(path)).expanduser().as_posix()
    except (TypeError, ValueError) as exc:
        raise VisualizationCommandError(
            "Snapshot action has an invalid output path."
        ) from exc
    commands.append(_command_join(
        "save", quote_chimerax_value(path, always=True),
        "format", params.get("format", DEFAULT_SNAPSHOT_FORMAT),
        "width", int(params.get("width", DEFAULT_SNAPSHOT_WIDTH)),
        "height", int(params.get("height", DEFAULT_SNAPSHOT_HEIGHT)),
        "supersample", int(params.get("supersample", DEFAULT_SNAPSHOT_SUPERSAMPLE)),
        "quality", int(params.get("quality", DEFAULT_SNAPSHOT_QUALITY)),
        "transparentBackground", format_chimerax_bool(params.get("transparent", False)),
    ))
    return commands


def _render_custom_action(action: VisualizationAction) -> List[str]:
    command = action.parameters.get("command")
    commands = action.parameters.get("commands")
    if command is not None:
        return [_command_text_value(command)]
    if commands is not None:
        return [_command_text_value(item) for item in commands]
    return []


_ACTION_COMMAND_RENDERERS: Final[Mapping[PlanOperation, Callable[[VisualizationAction], List[str]]]] = MappingProxyType({
    PlanOperation.PREPARE_SCENE: _render_prepare_scene,
    PlanOperation.SHOW_RECEPTOR: _render_molecular_action,
    PlanOperation.SHOW_LIGAND: _render_molecular_action,
    PlanOperation.SHOW_INTERACTIONS: _render_interaction_action,
    PlanOperation.SHOW_MARKERS: _render_marker_action,
    PlanOperation.SHOW_RESIDUES: _render_residue_action,
    PlanOperation.SHOW_HOTSPOTS: _render_hotspot_action,
    PlanOperation.APPLY_SCORING: _render_scoring_action,
    PlanOperation.SHOW_MULTIPOSE: _render_molecular_action,
    PlanOperation.SHOW_LABELS: _render_label_action,
    PlanOperation.SET_CAMERA: _render_camera_action,
    PlanOperation.SAVE_SNAPSHOT: _render_snapshot_action,
    PlanOperation.CUSTOM: _render_custom_action,
})


def render_action_commands(
    value: Any,
    *,
    sequence: int = 0,
    policy: Any = ChimeraXCommandPolicy.SAFE,
    maximum_length: int = DEFAULT_COMMAND_MAX_LENGTH,
    include_comment: bool = False,
) -> Tuple[CommandSpec, ...]:
    """Render one plan action."""

    action = coerce_visualization_action(value, index=sequence)
    if action.operation is PlanOperation.EXPORT_COMMANDS:
        return ()
    renderer = _ACTION_COMMAND_RENDERERS.get(action.operation)
    if renderer is None:
        raise VisualizationCommandError(
            "No command renderer is registered.", context={"operation": action.operation.value}
        )
    text_commands = renderer(action)
    commands: List[CommandSpec] = []
    suffix = 0
    if include_comment and action.description:
        comment = f"{COMMAND_COMMENT_PREFIX} {action.action_id}: {action.description}"
        commands.append(_command_from_text(comment, action=action, sequence=sequence, suffix=suffix))
        suffix += 1
    for text in text_commands:
        issues = validate_chimerax_command(text, policy=policy, maximum_length=maximum_length)
        if issues:
            raise VisualizationCommandError(
                "Generated command failed validation.",
                context={"action_id": action.action_id, "command": text, "issues": issues},
            )
        commands.append(_command_from_text(
            text,
            action=action,
            sequence=sequence,
            suffix=suffix,
            metadata={"operation": action.operation.value, "layer": action.layer.value},
        ))
        suffix += 1
    return tuple(commands)


# 24.3. Scripts and batching
# -----------------------------------------------------------------------------


def coerce_command_export_spec(value: Any = None, **overrides: Any) -> CommandExportSpec:
    """Coerce command-export settings."""

    if isinstance(value, CommandExportSpec):
        return replace(value, **overrides) if overrides else value
    if value is None:
        return CommandExportSpec(**overrides)
    if isinstance(value, (str, os.PathLike, Path)):
        return CommandExportSpec(filename=Path(value), **overrides)
    if isinstance(value, Mapping):
        return CommandExportSpec(**{**dict(value), **overrides})
    raise VisualizationExportError(
        f"Cannot coerce {type(value).__name__} to CommandExportSpec."
    )


def build_command_script(
    plan: Any,
    *,
    export: Any = None,
    title: Optional[str] = None,
) -> CommandScriptSpec:
    """Render a visualization plan as a command script."""

    visualization = coerce_visualization_plan(plan)
    settings = coerce_command_export_spec(export)
    issues = validate_visualization_plan(visualization)
    errors = tuple(issue for issue in issues if issue.level is ValidationIssueLevel.ERROR)
    if errors:
        raise VisualizationExportError(
            "Cannot export an invalid visualization plan.",
            context={"issues": [item.to_dict() for item in errors]},
        )
    commands: List[CommandSpec] = []
    for sequence, action in enumerate(visualization.ordered()):
        if not action.enabled and not settings.include_disabled:
            continue
        if action.optional and not settings.include_optional:
            continue
        commands.extend(render_action_commands(
            action,
            sequence=sequence,
            policy=settings.command_policy,
            maximum_length=settings.max_command_length,
            include_comment=settings.include_comments,
        ))
        if settings.include_waits and settings.wait_frames > 0 and action.enabled and action.operation not in {
            PlanOperation.SAVE_SNAPSHOT,
            PlanOperation.EXPORT_COMMANDS,
        }:
            wait_text = f"wait {settings.wait_frames}"
            commands.append(CommandSpec(
                command_id=f"cmd:{sequence:06d}:999",
                text=wait_text,
                action_id=action.action_id,
                sequence=sequence,
                optional=action.optional,
                metadata={"generated_wait": True},
            ))
    return CommandScriptSpec(
        plan_id=visualization.plan_id,
        commands=tuple(commands),
        title=title or visualization.name or _COMMAND_HEADER_TITLE,
        metadata={
            "profile": visualization.profile.value,
            "plan_fingerprint": visualization.fingerprint(),
            "export": settings.to_dict(),
        },
    )


def partition_command_script(
    value: Any,
    *,
    batch_size: int = DEFAULT_COMMAND_BATCH_SIZE,
) -> Tuple[CommandBatchSpec, ...]:
    """Split a command script into batches."""

    script = value if isinstance(value, CommandScriptSpec) else CommandScriptSpec(**dict(value))
    size = _bounded_int(batch_size, field_name="batch_size", minimum=1, maximum=MAX_VISUAL_COMMANDS)
    return tuple(
        CommandBatchSpec(
            batch_id=f"batch:{index // size + 1:04d}",
            commands=script.commands[index:index + size],
            index=index // size,
            metadata={"plan_id": script.plan_id},
        )
        for index in range(0, len(script.commands), size)
    )


def _command_header(script: CommandScriptSpec) -> Tuple[str, ...]:
    return (
        f"{COMMAND_COMMENT_PREFIX} {script.title}",
        f"{COMMAND_COMMENT_PREFIX} Plan: {script.plan_id}",
        f"{COMMAND_COMMENT_PREFIX} Generated: {script.generated_at}",
        f"{COMMAND_COMMENT_PREFIX} Fingerprint: {script.fingerprint()}",
    )


def render_command_script(
    value: Any,
    *,
    format: Any = CommandExportFormat.CHIMERAX,
    include_header: bool = True,
    newline: str = DEFAULT_COMMAND_NEWLINE,
) -> str:
    """Render a command script as text or JSON."""

    script = value if isinstance(value, CommandScriptSpec) else CommandScriptSpec(**dict(value))
    export_format = CommandExportFormat.parse(format, default=CommandExportFormat.CHIMERAX)
    if export_format is CommandExportFormat.JSON:
        return json.dumps(script.to_dict(), ensure_ascii=False, sort_keys=True, indent=2) + newline
    lines: List[str] = []
    if include_header:
        lines.extend(_command_header(script))
        lines.append("")
    lines.extend(script.command_texts)
    return newline.join(lines) + newline


# 24.4. File export and plan integration
# -----------------------------------------------------------------------------


def _atomic_write_command_text(
    path: Path,
    text: str,
    *,
    encoding: str,
    overwrite: bool,
    create_parents: bool,
) -> int:
    if path.exists() and not overwrite:
        raise VisualizationExportError(
            "Command file already exists.", context={"path": str(path)}
        )
    if create_parents:
        path.parent.mkdir(parents=True, exist_ok=True)
    elif not path.parent.exists():
        raise VisualizationExportError(
            "Command output directory does not exist.", context={"path": str(path.parent)}
        )
    temporary: Optional[Path] = None
    try:
        with NamedTemporaryFile(
            mode="w",
            encoding=encoding,
            newline="",
            dir=str(path.parent),
            prefix=f".{path.stem}.",
            suffix=path.suffix,
            delete=False,
        ) as handle:
            temporary = Path(handle.name)
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        if path.exists() and not overwrite:
            raise VisualizationExportError(
                "Command file already exists.", context={"path": str(path)}
            )
        os.replace(temporary, path)
        temporary = None
        return path.stat().st_size
    except VisualizationError:
        raise
    except Exception as exc:
        raise VisualizationExportError(
            "Command export failed.", context={"path": str(path), "error": str(exc)}
        ) from exc
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def export_visualization_commands(
    plan: Any,
    export: Any = None,
    **overrides: Any,
) -> CommandExportResult:
    """Export a visualization plan to a command file."""

    settings = coerce_command_export_spec(export, **overrides)
    script = build_command_script(plan, export=settings)
    text = render_command_script(
        script,
        format=settings.format,
        include_header=settings.include_header,
        newline=settings.newline,
    )
    bytes_written = _atomic_write_command_text(
        settings.filename,
        text,
        encoding=settings.encoding,
        overwrite=settings.overwrite,
        create_parents=settings.create_parents,
    )
    batches = partition_command_script(script, batch_size=settings.batch_size)
    return CommandExportResult(
        path=settings.filename,
        format=settings.format,
        command_count=len(script.commands),
        batch_count=len(batches),
        bytes_written=bytes_written,
        script_fingerprint=script.fingerprint(),
        metadata={"plan_id": script.plan_id},
    )


def build_command_export_action(
    value: Any = None,
    *,
    depends_on: Iterable[str] = (),
    **overrides: Any,
) -> VisualizationAction:
    """Build one deferred command-export action."""

    settings = coerce_command_export_spec(value, **overrides)
    return VisualizationAction(
        action_id=_COMMAND_EXPORT_ACTION_ID,
        operation=PlanOperation.EXPORT_COMMANDS,
        layer=VisualLayer.SNAPSHOT,
        parameters=settings.to_dict(),
        depends_on=_action_dependencies(depends_on),
        priority=OperationPriority.LOW,
        enabled=True,
        optional=False,
        description="Export the visualization plan as ChimeraX commands.",
        tags=("commands", "export", settings.format.value),
    )


def attach_command_export(
    plan: Any,
    value: Any = None,
    *,
    replace_existing: bool = True,
    **overrides: Any,
) -> VisualizationPlan:
    """Attach a deferred command-export action."""

    base = coerce_visualization_plan(plan)
    existing = tuple(action for action in base.actions if action.operation is PlanOperation.EXPORT_COMMANDS)
    if existing and not replace_existing:
        raise VisualizationExportError("Plan already contains command export.")
    retained = tuple(
        action for action in base.actions
        if not (replace_existing and action.operation is PlanOperation.EXPORT_COMMANDS)
    )
    dependencies = tuple(
        action.action_id for action in resolve_plan_order(replace(base, actions=retained), enabled_only=True)
        if action.operation is not PlanOperation.EXPORT_COMMANDS
    )
    export_action = build_command_export_action(value, depends_on=dependencies, **overrides)
    return build_visualization_plan(
        (*retained, export_action),
        plan_id=base.plan_id,
        name=base.name,
        profile=base.profile,
        execution_mode=base.execution_mode,
        description=base.description,
        metadata={**dict(base.metadata), "command_export": export_action.parameters},
    )


# 24.5. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_command_script(
    value: Any,
    *,
    policy: Any = ChimeraXCommandPolicy.SAFE,
    maximum_length: int = DEFAULT_COMMAND_MAX_LENGTH,
    raise_on_error: bool = False,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate a command script."""

    script = value if isinstance(value, CommandScriptSpec) else CommandScriptSpec(**dict(value))
    issues: List[PlanValidationIssue] = []
    for command in script.commands:
        for message in validate_chimerax_command(
            command.text,
            policy=policy,
            maximum_length=maximum_length,
        ):
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "command_invalid",
                message,
                command.action_id,
                {"command_id": command.command_id, "command": command.text},
            ))
    if not script.commands:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.WARNING,
            "command_script_empty",
            "Command script is empty.",
        ))
    if raise_on_error and any(issue.level is ValidationIssueLevel.ERROR for issue in issues):
        raise VisualizationCommandError(
            "Command script validation failed.",
            context={"issues": [item.to_dict() for item in issues]},
        )
    return tuple(issues)


def validate_command_export(
    value: Any = None,
    *,
    check_filesystem: bool = False,
    raise_on_error: bool = False,
    **overrides: Any,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate command-export settings."""

    settings = coerce_command_export_spec(value, **overrides)
    issues: List[PlanValidationIssue] = []
    if check_filesystem:
        if settings.filename.exists() and not settings.overwrite:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "command_output_exists",
                "Command output already exists.",
                context={"path": str(settings.filename)},
            ))
        if not settings.filename.parent.exists() and not settings.create_parents:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "command_parent_missing",
                "Command output directory does not exist.",
                context={"path": str(settings.filename.parent)},
            ))
    if settings.format is CommandExportFormat.JSON and settings.include_comments:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.INFO,
            "command_json_comments_metadata",
            "JSON exports store action descriptions as command entries.",
        ))
    if raise_on_error and any(issue.level is ValidationIssueLevel.ERROR for issue in issues):
        raise VisualizationExportError(
            "Command export validation failed.",
            context={"issues": [item.to_dict() for item in issues]},
        )
    return tuple(issues)


def summarize_command_script(value: Any) -> Dict[str, Any]:
    """Return compact command-script statistics."""

    script = value if isinstance(value, CommandScriptSpec) else CommandScriptSpec(**dict(value))
    return {
        "plan_id": script.plan_id,
        "command_count": len(script.commands),
        "action_count": len(script.action_ids),
        "command_names": dict(Counter(item.name for item in script.commands if not item.is_comment)),
        "comments": sum(item.is_comment for item in script.commands),
        "optional": sum(item.optional for item in script.commands),
        "fingerprint": script.fingerprint(),
    }


def summarize_command_export(value: Any) -> Dict[str, Any]:
    """Return compact export-result statistics."""

    result = value if isinstance(value, CommandExportResult) else CommandExportResult(**dict(value))
    return {
        "path": str(result.path),
        "format": result.format.value,
        "command_count": result.command_count,
        "batch_count": result.batch_count,
        "bytes_written": result.bytes_written,
        "script_fingerprint": result.script_fingerprint,
        "created_at": result.created_at,
    }


def command_script_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize a command script."""

    script = value if isinstance(value, CommandScriptSpec) else CommandScriptSpec(**dict(value))
    return script.to_dict()


def command_script_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize a command script as JSON."""

    return json.dumps(command_script_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


def command_export_to_dict(value: Any = None, **overrides: Any) -> Dict[str, Any]:
    """Serialize command-export settings."""

    return coerce_command_export_spec(value, **overrides).to_dict()


def command_export_to_json(
    value: Any = None,
    *,
    indent: Optional[int] = 2,
    **overrides: Any,
) -> str:
    """Serialize command-export settings as JSON."""

    return json.dumps(
        command_export_to_dict(value, **overrides),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


