# =============================================================================
# Section 25 — ChimeraX backend
# =============================================================================

from time import perf_counter

_CHIMERAX_BACKEND_SCHEMA_VERSION: Final[str] = "1.0"
_CHIMERAX_BACKEND_RESULT_LIMIT: Final[int] = 4096
_CHIMERAX_BACKEND_PLAN_ID: Final[str] = "runtime-plan"
_CHIMERAX_BACKEND_NAME: Final[str] = "ChimeraX"


def _backend_timestamp() -> str:
    return datetime.now(timezone.utc).isoformat()


def _backend_text(value: Any, *, maximum: int = _CHIMERAX_BACKEND_RESULT_LIMIT) -> str:
    try:
        text = repr(value)
    except Exception:
        text = f"<{type(value).__name__}>"
    text = " ".join(str(text).split())
    return text if len(text) <= maximum else f"{text[:maximum - 3]}..."


def _backend_session_name(session_value: Any) -> Optional[str]:
    if session_value is None:
        return None
    for name in ("name", "session_name", "title"):
        value = getattr(session_value, name, None)
        if value:
            return str(value)
    return type(session_value).__name__


def _backend_has_gui(session_value: Any) -> Optional[bool]:
    ui = getattr(session_value, "ui", None)
    if ui is None:
        return None
    for name in ("is_gui", "is_graphics", "has_gui"):
        value = getattr(ui, name, None)
        if value is not None:
            try:
                return bool(value() if callable(value) else value)
            except Exception:
                return None
    return None


def _backend_version(session_value: Any = None) -> Optional[str]:
    candidates = (
        getattr(_chimerax, "__version__", None) if _chimerax is not None else None,
        getattr(session_value, "version", None),
        getattr(getattr(session_value, "app_dirs", None), "version", None),
    )
    for value in candidates:
        if value:
            return str(value)
    return None


def _default_backend_logger() -> logging.Logger:
    """Return a silent standard-library logger without filesystem effects."""

    logger = logging.getLogger(f"DockAnalyzer.{_MODULE_NAME}")
    if not any(
        getattr(handler, "_dockanalyzer_visualization_null", False)
        for handler in logger.handlers
    ):
        handler = logging.NullHandler()
        handler._dockanalyzer_visualization_null = True  # type: ignore[attr-defined]
        logger.addHandler(handler)
    logger.propagate = False
    return logger


def _backend_logger(session_value: Any = None) -> Any:
    logger = getattr(session_value, "logger", None)
    return logger if logger is not None else _default_backend_logger()


def _emit_backend_log(level: str, message: str, *, session: Any = None) -> None:
    logger = _backend_logger(session)
    aliases = {
        "debug": ("debug", "status"),
        "info": ("info", "status"),
        "warning": ("warning", "warn"),
        "error": ("error",),
    }
    for name in aliases.get(level, (level,)):
        method = getattr(logger, name, None)
        if callable(method):
            try:
                method(message)
                return
            except Exception:
                continue


def _looks_like_chimerax_session(value: Any) -> bool:
    if value is None:
        return False
    module = type(value).__module__.lower()
    if module.startswith("chimerax"):
        return True
    return any(hasattr(value, name) for name in ("logger", "models", "main_view", "ui"))


def validate_chimerax_session(value: Any) -> Tuple[str, ...]:
    """Return ChimeraX session issues."""

    issues: List[str] = []
    if value is None:
        return ("ChimeraX session is missing.",)
    if not _looks_like_chimerax_session(value):
        issues.append("Object does not resemble a ChimeraX session.")
    if bool(getattr(value, "closed", False)):
        issues.append("ChimeraX session is closed.")
    return tuple(issues)


def resolve_chimerax_session(value: Any = None, *, required: bool = True) -> Any:
    """Resolve a ChimeraX session."""

    session_value = value
    if session_value is None:
        session_value = globals().get("session")
    if session_value is None and _chimerax is not None:
        session_value = getattr(_chimerax, "session", None)
    if session_value is None:
        try:
            import builtins

            session_value = getattr(builtins, "session", None)
        except Exception:
            session_value = None
    issues = validate_chimerax_session(session_value) if session_value is not None else ()
    if session_value is None or issues:
        if required:
            raise ChimeraXUnavailableError(
                "A usable ChimeraX session could not be resolved.",
                context={"issues": list(issues)},
            )
        return None
    return session_value


def resolve_chimerax_runner(value: Any = None, *, required: bool = True) -> Optional[Callable[..., Any]]:
    """Resolve the ChimeraX command runner."""

    if value is not None:
        if not callable(value):
            raise VisualizationBackendError("ChimeraX runner must be callable.")
        return value
    try:
        from chimerax.core.commands import run as command_runner
    except Exception as exc:
        if required:
            raise ChimeraXUnavailableError(
                "ChimeraX command runner is unavailable.",
                context={"error": str(exc)},
            ) from exc
        return None
    return command_runner


def _runner_supports_log(runner: Callable[..., Any]) -> bool:
    try:
        parameters = inspect.signature(runner).parameters.values()
    except (TypeError, ValueError):
        return False
    return any(item.name == "log" or item.kind is inspect.Parameter.VAR_KEYWORD for item in parameters)


def _invoke_chimerax_runner(
    runner: Callable[..., Any],
    session_value: Any,
    command: str,
    *,
    log_commands: bool,
) -> Any:
    if _runner_supports_log(runner):
        return runner(session_value, command, log=log_commands)
    return runner(session_value, command)


def coerce_backend_config(value: Any = None, **overrides: Any) -> BackendConfig:
    """Coerce backend settings."""

    if isinstance(value, BackendConfig):
        return replace(value, **overrides) if overrides else value
    if isinstance(value, VisualizationConfig):
        return replace(value.backend, **overrides) if overrides else value.backend
    if value is None:
        return BackendConfig(**overrides)
    if isinstance(value, Mapping):
        return BackendConfig(**{**dict(value), **overrides})
    raise VisualizationConfigurationError(
        f"Cannot coerce {type(value).__name__} to BackendConfig."
    )


def _runtime_command_policy(config_value: BackendConfig) -> ChimeraXCommandPolicy:
    if config_value.validation_mode is ValidationMode.STRICT:
        return ChimeraXCommandPolicy.STRICT
    if config_value.validation_mode in {ValidationMode.PERMISSIVE, ValidationMode.DISABLED}:
        return ChimeraXCommandPolicy.PERMISSIVE
    return config_value.command_policy


@dataclass(frozen=True, slots=True)
class ChimeraXBackendInfo(MolecularSpecMixin):
    """ChimeraX backend discovery result."""

    available: bool
    state: BackendState
    version: Optional[str] = None
    session_name: Optional[str] = None
    session_type: Optional[str] = None
    has_gui: Optional[bool] = None
    runner_name: Optional[str] = None
    reason: Optional[str] = None
    schema_version: str = _CHIMERAX_BACKEND_SCHEMA_VERSION
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "available", bool(self.available))
        object.__setattr__(self, "state", BackendState.parse(self.state, default=BackendState.UNAVAILABLE))
        for name in ("version", "session_name", "session_type", "runner_name", "reason"):
            value = getattr(self, name)
            object.__setattr__(self, name, None if value is None else str(value))
        object.__setattr__(self, "has_gui", None if self.has_gui is None else bool(self.has_gui))
        object.__setattr__(self, "schema_version", str(self.schema_version or _CHIMERAX_BACKEND_SCHEMA_VERSION))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))


def discover_chimerax_backend(
    session: Any = None,
    *,
    runner: Any = None,
) -> ChimeraXBackendInfo:
    """Inspect ChimeraX backend availability."""

    session_value = resolve_chimerax_session(session, required=False)
    runner_value = resolve_chimerax_runner(runner, required=False)
    session_issues = validate_chimerax_session(session_value) if session_value is not None else ("Session unavailable.",)
    available = session_value is not None and runner_value is not None and not session_issues
    reason = None
    if not available:
        parts = list(session_issues)
        if runner_value is None:
            parts.append("Command runner unavailable.")
        reason = " ".join(parts)
    return ChimeraXBackendInfo(
        available=available,
        state=BackendState.AVAILABLE if available else BackendState.UNAVAILABLE,
        version=_backend_version(session_value),
        session_name=_backend_session_name(session_value),
        session_type=None if session_value is None else f"{type(session_value).__module__}.{type(session_value).__name__}",
        has_gui=_backend_has_gui(session_value),
        runner_name=None if runner_value is None else getattr(runner_value, "__qualname__", getattr(runner_value, "__name__", type(runner_value).__name__)),
        reason=reason,
        metadata={"module_available": CHIMERAX_AVAILABLE},
    )


@dataclass(frozen=True, slots=True)
class CommandExecutionResult(MolecularSpecMixin):
    """Runtime result for one command."""

    command_id: str
    text: str
    status: CommandStatus
    action_id: Optional[str] = None
    sequence: int = 0
    optional: bool = False
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_ms: float = 0.0
    result_repr: Optional[str] = None
    error_type: Optional[str] = None
    error_message: Optional[str] = None
    error_data: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "command_id", _command_identifier(self.command_id))
        object.__setattr__(self, "text", _command_text_value(self.text))
        object.__setattr__(self, "status", CommandStatus.parse(self.status, default=CommandStatus.PENDING))
        object.__setattr__(self, "action_id", None if self.action_id is None else _command_identifier(self.action_id, field_name="action_id"))
        object.__setattr__(self, "sequence", _bounded_int(self.sequence, field_name="sequence", minimum=0, maximum=MAX_VISUAL_COMMANDS))
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "duration_ms", _bounded_float(self.duration_ms, field_name="duration_ms", minimum=0.0))
        for name in ("started_at", "finished_at", "result_repr", "error_type", "error_message"):
            value = getattr(self, name)
            object.__setattr__(self, name, None if value is None else str(value))
        object.__setattr__(self, "error_data", _normalize_spec_metadata(self.error_data))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def success(self) -> bool:
        return self.status in {CommandStatus.EXECUTED, CommandStatus.VALIDATED, CommandStatus.SKIPPED}

    @property
    def failed(self) -> bool:
        return self.status is CommandStatus.FAILED


@dataclass(frozen=True, slots=True)
class ActionExecutionResult(MolecularSpecMixin):
    """Runtime result for one plan action."""

    action_id: str
    operation: PlanOperation
    status: CommandStatus
    commands: Tuple[CommandExecutionResult, ...] = ()
    optional: bool = False
    duration_ms: float = 0.0
    error_message: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        commands = tuple(
            item if isinstance(item, CommandExecutionResult) else CommandExecutionResult(**dict(item))
            for item in self.commands
        )
        object.__setattr__(self, "action_id", _plan_identifier(self.action_id, field_name="action_id"))
        object.__setattr__(self, "operation", PlanOperation.parse(self.operation, default=PlanOperation.CUSTOM))
        object.__setattr__(self, "status", CommandStatus.parse(self.status, default=CommandStatus.PENDING))
        object.__setattr__(self, "commands", commands)
        object.__setattr__(self, "optional", bool(self.optional))
        object.__setattr__(self, "duration_ms", _bounded_float(self.duration_ms, field_name="duration_ms", minimum=0.0))
        object.__setattr__(self, "error_message", None if self.error_message is None else str(self.error_message))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def command_count(self) -> int:
        return len(self.commands)

    @property
    def failed_count(self) -> int:
        return sum(item.failed for item in self.commands)


@dataclass(frozen=True, slots=True)
class VisualizationExecutionResult(MolecularSpecMixin):
    """Runtime result for one visualization plan."""

    plan_id: str
    backend: BackendKind
    execution_mode: ExecutionMode
    state: LifecycleState
    actions: Tuple[ActionExecutionResult, ...] = ()
    started_at: Optional[str] = None
    finished_at: Optional[str] = None
    duration_ms: float = 0.0
    script_fingerprint: Optional[str] = None
    backend_info: Optional[ChimeraXBackendInfo] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        actions = tuple(
            item if isinstance(item, ActionExecutionResult) else ActionExecutionResult(**dict(item))
            for item in self.actions
        )
        info = self.backend_info
        if info is not None and not isinstance(info, ChimeraXBackendInfo):
            info = ChimeraXBackendInfo(**dict(info))
        object.__setattr__(self, "plan_id", _plan_identifier(self.plan_id, field_name="plan_id"))
        object.__setattr__(self, "backend", BackendKind.parse(self.backend, default=BackendKind.CHIMERAX))
        object.__setattr__(self, "execution_mode", ExecutionMode.parse(self.execution_mode, default=ExecutionMode.DEFERRED))
        object.__setattr__(self, "state", LifecycleState.parse(self.state, default=LifecycleState.PLANNED))
        object.__setattr__(self, "actions", actions)
        object.__setattr__(self, "duration_ms", _bounded_float(self.duration_ms, field_name="duration_ms", minimum=0.0))
        for name in ("started_at", "finished_at", "script_fingerprint"):
            value = getattr(self, name)
            object.__setattr__(self, name, None if value is None else str(value))
        object.__setattr__(self, "backend_info", info)
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))

    @property
    def commands(self) -> Tuple[CommandExecutionResult, ...]:
        return tuple(command for action in self.actions for command in action.commands)

    @property
    def command_count(self) -> int:
        return len(self.commands)

    @property
    def executed_count(self) -> int:
        return sum(item.status is CommandStatus.EXECUTED for item in self.commands)

    @property
    def failed_count(self) -> int:
        return sum(item.status is CommandStatus.FAILED for item in self.commands)

    @property
    def skipped_count(self) -> int:
        return sum(item.status is CommandStatus.SKIPPED for item in self.commands)

    @property
    def success(self) -> bool:
        return self.state is LifecycleState.COMPLETED and self.failed_count == 0

    def fingerprint(self) -> str:
        return _spec_fingerprint({
            "plan_id": self.plan_id,
            "backend": self.backend.value,
            "mode": self.execution_mode.value,
            "state": self.state.value,
            "script": self.script_fingerprint,
            "commands": [
                (item.command_id, item.status.value, item.error_type, item.error_message)
                for item in self.commands
            ],
        })


def coerce_command_spec(value: Any, *, index: int = 0) -> CommandSpec:
    """Coerce one executable command."""

    if isinstance(value, CommandSpec):
        return value
    if isinstance(value, str):
        return CommandSpec(command_id=f"runtime:{index:06d}", text=value, sequence=index)
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("command_id", f"runtime:{index:06d}")
        data.setdefault("sequence", index)
        return CommandSpec(**data)
    raise VisualizationCommandError(
        f"Cannot coerce {type(value).__name__} to CommandSpec."
    )


def _command_failure_result(
    command: CommandSpec,
    error: BaseException,
    *,
    started_at: str,
    started_clock: float,
) -> CommandExecutionResult:
    return CommandExecutionResult(
        command_id=command.command_id,
        text=command.text,
        action_id=command.action_id,
        sequence=command.sequence,
        optional=command.optional,
        status=CommandStatus.FAILED,
        started_at=started_at,
        finished_at=_backend_timestamp(),
        duration_ms=(perf_counter() - started_clock) * 1000.0,
        error_type=type(error).__name__,
        error_message=str(error),
        error_data=exception_to_dict(error, include_traceback=False),
        metadata=command.metadata,
    )


def _apply_backend_error_policy(
    error: BaseException,
    result: CommandExecutionResult,
    config_value: BackendConfig,
    *,
    session: Any = None,
    completed_commands: int = 0,
) -> None:
    message = f"ChimeraX command failed: {result.command_id}: {result.error_message}"
    _emit_backend_log("error", message, session=session)
    if result.optional:
        return
    if config_value.error_handling is ErrorHandlingMode.WARN:
        warnings.warn(message, VisualizationBackendWarning, stacklevel=3)
    elif config_value.error_handling is ErrorHandlingMode.RAISE:
        raise VisualizationExecutionError(
            message,
            command=result.text,
            command_index=result.sequence,
            completed_commands=completed_commands,
            context={"result": result.to_dict()},
        ) from error


def execute_chimerax_command(
    command: Any,
    *,
    session: Any = None,
    runner: Any = None,
    config: Any = None,
    mode: Any = None,
    index: int = 0,
    completed_commands: int = 0,
) -> CommandExecutionResult:
    """Execute or validate one ChimeraX command."""

    command_value = coerce_command_spec(command, index=index)
    config_value = coerce_backend_config(config)
    execution_mode = ExecutionMode.parse(mode, default=config_value.execution_mode)
    started_at = _backend_timestamp()
    started_clock = perf_counter()
    if command_value.is_comment:
        return CommandExecutionResult(
            command_id=command_value.command_id,
            text=command_value.text,
            action_id=command_value.action_id,
            sequence=command_value.sequence,
            optional=command_value.optional,
            status=CommandStatus.SKIPPED,
            started_at=started_at,
            finished_at=_backend_timestamp(),
            duration_ms=(perf_counter() - started_clock) * 1000.0,
            metadata={**dict(command_value.metadata), "comment": True},
        )
    if config_value.validation_mode is not ValidationMode.DISABLED:
        issues = validate_chimerax_command(
            command_value.text,
            policy=_runtime_command_policy(config_value),
            maximum_length=config_value.max_command_length,
        )
        if issues:
            error = VisualizationCommandError(
                "Runtime command validation failed.",
                command=command_value.text,
                command_index=command_value.sequence,
                context={"issues": list(issues)},
            )
            result = _command_failure_result(
                command_value, error, started_at=started_at, started_clock=started_clock
            )
            _apply_backend_error_policy(
                error,
                result,
                config_value,
                session=session,
                completed_commands=completed_commands,
            )
            return result
    passive_status = {
        ExecutionMode.DEFERRED: CommandStatus.PENDING,
        ExecutionMode.DRY_RUN: CommandStatus.VALIDATED,
        ExecutionMode.EXPORT_ONLY: CommandStatus.SKIPPED,
    }.get(execution_mode)
    if passive_status is not None:
        return CommandExecutionResult(
            command_id=command_value.command_id,
            text=command_value.text,
            action_id=command_value.action_id,
            sequence=command_value.sequence,
            optional=command_value.optional,
            status=passive_status,
            started_at=started_at,
            finished_at=_backend_timestamp(),
            duration_ms=(perf_counter() - started_clock) * 1000.0,
            metadata=command_value.metadata,
        )
    try:
        session_value = resolve_chimerax_session(session, required=True)
        runner_value = resolve_chimerax_runner(runner, required=True)
        if config_value.log_commands:
            _emit_backend_log("info", command_value.text, session=session_value)
        return_value = _invoke_chimerax_runner(
            runner_value,
            session_value,
            command_value.text,
            log_commands=config_value.log_commands,
        )
        return CommandExecutionResult(
            command_id=command_value.command_id,
            text=command_value.text,
            action_id=command_value.action_id,
            sequence=command_value.sequence,
            optional=command_value.optional,
            status=CommandStatus.EXECUTED,
            started_at=started_at,
            finished_at=_backend_timestamp(),
            duration_ms=(perf_counter() - started_clock) * 1000.0,
            result_repr=None if return_value is None else _backend_text(return_value),
            metadata=command_value.metadata,
        )
    except (VisualizationExecutionError, ChimeraXUnavailableError) as exc:
        if config_value.error_handling is ErrorHandlingMode.RAISE and not command_value.optional:
            raise
        result = _command_failure_result(
            command_value, exc, started_at=started_at, started_clock=started_clock
        )
        _apply_backend_error_policy(
            exc,
            result,
            config_value,
            session=session,
            completed_commands=completed_commands,
        )
        return result
    except Exception as exc:
        result = _command_failure_result(
            command_value, exc, started_at=started_at, started_clock=started_clock
        )
        _apply_backend_error_policy(
            exc,
            result,
            config_value,
            session=session,
            completed_commands=completed_commands,
        )
        return result


def _coerce_runtime_script(value: Any) -> CommandScriptSpec:
    if isinstance(value, CommandScriptSpec):
        return value
    if isinstance(value, VisualizationPlan):
        return build_command_script(value)
    if isinstance(value, Mapping):
        return CommandScriptSpec(**dict(value))
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        commands = tuple(coerce_command_spec(item, index=index) for index, item in enumerate(value))
        return CommandScriptSpec(plan_id=_CHIMERAX_BACKEND_PLAN_ID, commands=commands)
    raise VisualizationCommandError(
        f"Cannot coerce {type(value).__name__} to CommandScriptSpec."
    )


def execute_chimerax_script(
    script: Any,
    *,
    session: Any = None,
    runner: Any = None,
    config: Any = None,
    mode: Any = None,
) -> Tuple[CommandExecutionResult, ...]:
    """Execute or validate a ChimeraX command script."""

    script_value = _coerce_runtime_script(script)
    config_value = coerce_backend_config(config)
    execution_mode = ExecutionMode.parse(mode, default=config_value.execution_mode)
    results: List[CommandExecutionResult] = []
    for index, command in enumerate(script_value.commands):
        try:
            result = execute_chimerax_command(
                command,
                session=session,
                runner=runner,
                config=config_value,
                mode=execution_mode,
                index=index,
                completed_commands=sum(item.status is CommandStatus.EXECUTED for item in results),
            )
        except VisualizationExecutionError as exc:
            if exc.completed_commands == 0:
                exc.completed_commands = sum(item.status is CommandStatus.EXECUTED for item in results)
            raise
        results.append(result)
    return tuple(results)


def _status_for_command_group(commands: Sequence[CommandExecutionResult]) -> CommandStatus:
    statuses = {item.status for item in commands}
    if CommandStatus.FAILED in statuses:
        return CommandStatus.FAILED
    if CommandStatus.EXECUTED in statuses:
        return CommandStatus.EXECUTED
    if CommandStatus.VALIDATED in statuses:
        return CommandStatus.VALIDATED
    if CommandStatus.PENDING in statuses:
        return CommandStatus.PENDING
    return CommandStatus.SKIPPED


def _build_action_execution_results(
    plan: VisualizationPlan,
    commands: Sequence[CommandExecutionResult],
) -> Tuple[ActionExecutionResult, ...]:
    grouped: Dict[str, List[CommandExecutionResult]] = defaultdict(list)
    for command in commands:
        if command.action_id:
            grouped[command.action_id].append(command)
    results: List[ActionExecutionResult] = []
    for action in plan.ordered():
        action_commands = tuple(grouped.get(action.action_id, ()))
        status = _status_for_command_group(action_commands) if action_commands else CommandStatus.SKIPPED
        failures = [item.error_message for item in action_commands if item.failed and item.error_message]
        results.append(ActionExecutionResult(
            action_id=action.action_id,
            operation=action.operation,
            status=status,
            commands=action_commands,
            optional=action.optional,
            duration_ms=sum(item.duration_ms for item in action_commands),
            error_message="; ".join(failures) if failures else None,
            metadata={"layer": action.layer.value, "enabled": action.enabled},
        ))
    return tuple(results)


def _execution_state(
    mode: ExecutionMode,
    commands: Sequence[CommandExecutionResult],
) -> LifecycleState:
    if mode is ExecutionMode.DEFERRED:
        return LifecycleState.PLANNED
    if any(item.status is CommandStatus.FAILED for item in commands):
        return LifecycleState.FAILED
    return LifecycleState.COMPLETED


class ChimeraXBackend:
    """Stateful ChimeraX command backend."""

    def __init__(
        self,
        session: Any = None,
        *,
        config: Any = None,
        runner: Any = None,
        activate: bool = False,
    ) -> None:
        self._session = session
        self._runner = runner
        self._config = coerce_backend_config(config)
        self._state = BackendState.UNAVAILABLE
        if activate:
            self.activate()
        else:
            self._state = discover_chimerax_backend(session, runner=runner).state

    @property
    def session(self) -> Any:
        return self._session

    @property
    def runner(self) -> Any:
        return self._runner

    @property
    def config(self) -> BackendConfig:
        return self._config

    @property
    def state(self) -> BackendState:
        return self._state

    @property
    def info(self) -> ChimeraXBackendInfo:
        info = discover_chimerax_backend(self._session, runner=self._runner)
        return replace(info, state=self._state if self._state is not BackendState.CLOSED else BackendState.CLOSED)

    @property
    def available(self) -> bool:
        return self.info.available and self._state is not BackendState.CLOSED

    @property
    def active(self) -> bool:
        return self._state is BackendState.ACTIVE

    def activate(self, session: Any = None, *, runner: Any = None) -> "ChimeraXBackend":
        if self._state is BackendState.CLOSED:
            raise VisualizationStateError("Closed ChimeraX backend cannot be reactivated.")
        self._session = resolve_chimerax_session(session if session is not None else self._session)
        self._runner = resolve_chimerax_runner(runner if runner is not None else self._runner)
        self._state = BackendState.ACTIVE
        _emit_backend_log("debug", "ChimeraX backend activated.", session=self._session)
        return self

    def close(self) -> None:
        self._state = BackendState.CLOSED

    def execute_command(self, command: Any, *, mode: Any = None, index: int = 0) -> CommandExecutionResult:
        if self._state is BackendState.CLOSED:
            raise VisualizationStateError("ChimeraX backend is closed.")
        execution_mode = ExecutionMode.parse(mode, default=self._config.execution_mode)
        if execution_mode in {ExecutionMode.IMMEDIATE, ExecutionMode.BATCH} and not self.active:
            self.activate()
        return execute_chimerax_command(
            command,
            session=self._session,
            runner=self._runner,
            config=self._config,
            mode=execution_mode,
            index=index,
        )

    def execute_script(self, script: Any, *, mode: Any = None) -> Tuple[CommandExecutionResult, ...]:
        if self._state is BackendState.CLOSED:
            raise VisualizationStateError("ChimeraX backend is closed.")
        execution_mode = ExecutionMode.parse(mode, default=self._config.execution_mode)
        if execution_mode in {ExecutionMode.IMMEDIATE, ExecutionMode.BATCH} and not self.active:
            self.activate()
        results = execute_chimerax_script(
            script,
            session=self._session,
            runner=self._runner,
            config=self._config,
            mode=execution_mode,
        )
        if any(item.failed for item in results):
            self._state = BackendState.DEGRADED
        return results

    def execute_plan(self, plan: Any, *, mode: Any = None) -> VisualizationExecutionResult:
        return execute_visualization_plan(plan, backend=self, mode=mode)

    def __enter__(self) -> "ChimeraXBackend":
        if not self.active:
            self.activate()
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback_value: Any) -> None:
        self.close()


def create_chimerax_backend(
    session: Any = None,
    *,
    config: Any = None,
    runner: Any = None,
    activate: bool = False,
) -> ChimeraXBackend:
    """Create a ChimeraX backend."""

    return ChimeraXBackend(
        session,
        config=config,
        runner=runner,
        activate=activate,
    )


def _prepare_visualization_output_paths(plan: VisualizationPlan) -> None:
    """Prepare explicit snapshot destinations immediately before execution."""

    for action in plan.ordered():
        if not action.enabled or action.operation is not PlanOperation.SAVE_SNAPSHOT:
            continue
        raw_path = action.parameters.get("output_path") or action.parameters.get("filename")
        if not raw_path:
            raise VisualizationSnapshotError(
                "Snapshot action has no output path.",
                context={"action_id": action.action_id},
            )
        path = Path(os.fspath(raw_path)).expanduser()
        parent = path.parent
        if parent.exists() and not parent.is_dir():
            raise VisualizationSnapshotError(
                "Snapshot parent path is not a directory.",
                context={"action_id": action.action_id, "path": str(parent)},
            )
        if not parent.exists():
            if not bool(action.parameters.get("create_parents", True)):
                raise VisualizationSnapshotError(
                    "Snapshot parent directory does not exist.",
                    context={"action_id": action.action_id, "path": str(parent)},
                )
            try:
                parent.mkdir(parents=True, exist_ok=True)
            except OSError as exc:
                raise VisualizationSnapshotError(
                    "Unable to create snapshot parent directory.",
                    context={"action_id": action.action_id, "path": str(parent)},
                ) from exc
        if path.exists() and not bool(action.parameters.get("overwrite", False)):
            raise VisualizationSnapshotError(
                "Snapshot output already exists and overwrite is disabled.",
                context={"action_id": action.action_id, "path": str(path)},
            )


def execute_visualization_plan(
    plan: Any,
    *,
    session: Any = None,
    runner: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    config: Any = None,
    mode: Any = None,
) -> VisualizationExecutionResult:
    """Execute, validate or defer a visualization plan."""

    visualization = coerce_visualization_plan(plan)
    backend_value = backend
    config_value = backend_value.config if backend_value is not None and config is None else coerce_backend_config(config)
    execution_mode = ExecutionMode.parse(mode, default=visualization.execution_mode)
    if mode is None and visualization.execution_mode is ExecutionMode.DEFERRED:
        execution_mode = config_value.execution_mode
    started_at = _backend_timestamp()
    started_clock = perf_counter()
    if config_value.validation_mode is not ValidationMode.DISABLED:
        issues = validate_visualization_plan(visualization)
        errors = [item for item in issues if item.level >= ValidationIssueLevel.ERROR]
        if errors and config_value.validation_mode is not ValidationMode.PERMISSIVE:
            raise VisualizationExecutionError(
                "Cannot execute an invalid visualization plan.",
                context={"issues": [item.to_dict() for item in errors]},
            )
        if errors:
            warnings.warn(
                "Visualization plan contains validation errors; permissive execution continues.",
                VisualizationBackendWarning,
                stacklevel=2,
            )
    if execution_mode in {ExecutionMode.IMMEDIATE, ExecutionMode.BATCH}:
        _prepare_visualization_output_paths(visualization)
    export_settings = CommandExportSpec(
        filename=Path(DEFAULT_COMMAND_FILENAME),
        include_header=False,
        include_comments=False,
        include_disabled=False,
        include_optional=True,
        include_waits=config_value.wait_frames > 0,
        wait_frames=config_value.wait_frames,
        batch_size=config_value.batch_size,
        max_command_length=config_value.max_command_length,
        command_policy=_runtime_command_policy(config_value),
    )
    script = build_command_script(visualization, export=export_settings)
    if backend_value is None:
        backend_value = create_chimerax_backend(
            session,
            config=config_value,
            runner=runner,
            activate=False,
        )
    command_results = backend_value.execute_script(script, mode=execution_mode)
    action_results = _build_action_execution_results(visualization, command_results)
    state = _execution_state(execution_mode, command_results)
    return VisualizationExecutionResult(
        plan_id=visualization.plan_id,
        backend=BackendKind.CHIMERAX,
        execution_mode=execution_mode,
        state=state,
        actions=action_results,
        started_at=started_at,
        finished_at=_backend_timestamp(),
        duration_ms=(perf_counter() - started_clock) * 1000.0,
        script_fingerprint=script.fingerprint(),
        backend_info=backend_value.info,
        metadata={
            "plan_fingerprint": visualization.fingerprint(),
            "command_count": len(script.commands),
            "profile": visualization.profile.value,
        },
    )


def dry_run_visualization_plan(
    plan: Any,
    *,
    config: Any = None,
) -> VisualizationExecutionResult:
    """Validate a plan without ChimeraX."""

    settings = coerce_backend_config(
        config,
        execution_mode=ExecutionMode.DRY_RUN,
        kind=BackendKind.COMMAND,
    )
    return execute_visualization_plan(plan, config=settings, mode=ExecutionMode.DRY_RUN)


def validate_chimerax_backend(value: Any = None) -> Tuple[str, ...]:
    """Return backend validation issues."""

    if isinstance(value, ChimeraXBackend):
        info = value.info
    elif isinstance(value, ChimeraXBackendInfo):
        info = value
    else:
        info = discover_chimerax_backend(value)
    issues: List[str] = []
    if not info.available:
        issues.append(info.reason or "ChimeraX backend is unavailable.")
    if info.state is BackendState.CLOSED:
        issues.append("ChimeraX backend is closed.")
    return tuple(issues)


def summarize_chimerax_backend(value: Any = None) -> Dict[str, Any]:
    """Summarize backend availability."""

    if isinstance(value, ChimeraXBackend):
        info = value.info
    elif isinstance(value, ChimeraXBackendInfo):
        info = value
    else:
        info = discover_chimerax_backend(value)
    return {
        "available": info.available,
        "state": info.state.value,
        "version": info.version,
        "session": info.session_name,
        "has_gui": info.has_gui,
        "runner": info.runner_name,
        "reason": info.reason,
    }


def summarize_execution_result(value: Any) -> Dict[str, Any]:
    """Summarize plan execution."""

    result = value if isinstance(value, VisualizationExecutionResult) else VisualizationExecutionResult(**dict(value))
    return {
        "plan_id": result.plan_id,
        "backend": result.backend.value,
        "mode": result.execution_mode.value,
        "state": result.state.value,
        "success": result.success,
        "action_count": len(result.actions),
        "command_count": result.command_count,
        "executed": result.executed_count,
        "failed": result.failed_count,
        "skipped": result.skipped_count,
        "duration_ms": result.duration_ms,
        "fingerprint": result.fingerprint(),
    }


def execution_result_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize an execution result."""

    result = value if isinstance(value, VisualizationExecutionResult) else VisualizationExecutionResult(**dict(value))
    return result.to_dict()


def execution_result_to_json(value: Any, *, indent: Optional[int] = 2) -> str:
    """Serialize an execution result as JSON."""

    return json.dumps(execution_result_to_dict(value), ensure_ascii=False, sort_keys=True, indent=indent)


