# =============================================================================
# Section 26 — DockModel integration
# =============================================================================

_DOCK_MODEL_VISUALIZATION_SCHEMA_VERSION: Final[str] = "1.0"
_DOCK_MODEL_VISUALIZATION_ATTRIBUTE: Final[str] = "visualization"
_DOCK_MODEL_INTERACTION_FIELDS: Final[Tuple[Tuple[str, InteractionFamily], ...]] = (
    ("contacts", InteractionFamily.CONTACT),
    ("hbonds", InteractionFamily.HBOND),
    ("hydrogen_bonds", InteractionFamily.HBOND),
    ("hydrophobic", InteractionFamily.HYDROPHOBIC),
    ("hydrophobic_interactions", InteractionFamily.HYDROPHOBIC),
    ("pi", InteractionFamily.PI_STACKING),
    ("pi_interactions", InteractionFamily.PI_STACKING),
    ("saltbridge", InteractionFamily.SALT_BRIDGE),
    ("salt_bridges", InteractionFamily.SALT_BRIDGE),
)
_DOCK_MODEL_SCORE_FIELDS: Final[Tuple[str, ...]] = (
    "score", "total_score", "pose_score", "scoring", "scoring_result",
    "interaction_score", "residue_scores", "hotspot_scores",
)
_DOCK_MODEL_POSE_FIELDS: Final[Tuple[str, ...]] = (
    "poses", "docked_poses", "conformations", "conformers", "models",
)
_DOCK_MODEL_RECEPTOR_FIELDS: Final[Tuple[str, ...]] = (
    "receptor", "protein", "target", "receptor_model", "target_model",
)
_DOCK_MODEL_LIGAND_FIELDS: Final[Tuple[str, ...]] = (
    "ligand", "docked_ligand", "molecule", "compound", "ligand_model",
)


def _dock_model_timestamp() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dock_model_value(source: Any, *names: str, default: Any = None) -> Any:
    """Read a DockModel field."""

    return _object_value(source, *names, default=default, allow_callable=False)


def _dock_model_sequence(value: Any) -> Tuple[Any, ...]:
    """Normalize a model collection."""

    if value is None:
        return ()
    if isinstance(value, (str, bytes, Path)):
        return (value,)
    if isinstance(value, Mapping):
        single_keys = {
            "object_id", "pose_id", "interaction_id", "family", "source",
            "target", "path", "model_id", "residue_number", "atom_name",
        }
        return (value,) if single_keys.intersection(value) else tuple(value.values())
    try:
        return tuple(value)
    except TypeError:
        return (value,)


def _dock_model_mapping(value: Any) -> Dict[str, Any]:
    """Return public object fields."""

    if value is None:
        return {}
    if isinstance(value, Mapping):
        return dict(value)
    if is_dataclass(value):
        return {
            item.name: getattr(value, item.name)
            for item in fields(value)
            if not item.name.startswith("_")
        }
    try:
        return {
            name: item
            for name, item in vars(value).items()
            if not name.startswith("_")
        }
    except TypeError:
        return {}


def _dock_model_field_names(value: Any) -> Tuple[str, ...]:
    """List writable or declared fields."""

    if isinstance(value, Mapping):
        return tuple(str(name) for name in value)
    if is_dataclass(value):
        return tuple(item.name for item in fields(value))
    names = set(_dock_model_mapping(value))
    slots = getattr(type(value), "__slots__", ())
    if isinstance(slots, str):
        names.add(slots)
    else:
        names.update(str(name) for name in slots)
    return tuple(sorted(names))


def _dock_model_identifier(value: Any) -> str:
    """Resolve a stable DockModel identifier."""

    identifier = _dock_model_value(
        value,
        "model_id", "dock_id", "identifier", "name", "id", "title",
    )
    if identifier is None:
        receptor = _dock_model_value(value, *_DOCK_MODEL_RECEPTOR_FIELDS)
        ligand = _dock_model_value(value, *_DOCK_MODEL_LIGAND_FIELDS)
        parts = [
            _dock_model_value(receptor, "name", "id_string", "id"),
            _dock_model_value(ligand, "name", "id_string", "id"),
        ]
        identifier = "-".join(str(item) for item in parts if item is not None)
    text = str(identifier or f"dock-model-{id(value):x}").strip()
    return _plan_identifier(text, field_name="DockModel identifier")


def _dock_model_path_object(value: Any, *, role: MolecularRole, fallback: str) -> MolecularObjectSpec:
    """Coerce paths and molecular objects."""

    if isinstance(value, (str, os.PathLike, Path)):
        path = Path(value).expanduser()
        name = path.stem or fallback
        return MolecularObjectSpec(
            object_id=_plan_identifier(name, field_name="molecular object identifier"),
            name=name,
            role=role,
            source_path=path,
        )
    return coerce_molecular_object_spec(value, role=role)


def _dock_model_existing_state(value: Any, fields_value: "DockModelVisualizationFields") -> Optional[Any]:
    for name in (fields_value.state, _DOCK_MODEL_VISUALIZATION_ATTRIBUTE, "visualization_state"):
        candidate = _dock_model_value(value, name)
        if candidate is not None:
            return candidate
    return None


def _dock_model_score_mapping(value: Any) -> Mapping[str, Any]:
    """Extract score-like fields without importing scoring.py."""

    scores: Dict[str, Any] = {}
    for name in _DOCK_MODEL_SCORE_FIELDS:
        item = _dock_model_value(value, name)
        if item is not None:
            scores[name] = _spec_data(item)
    return MappingProxyType(scores)


def _dock_model_artifact_paths(
    *,
    snapshots: Optional[SnapshotManifestSpec] = None,
    commands: Optional[CommandExportResult] = None,
) -> Mapping[str, str]:
    """Collect generated artifact paths."""

    artifacts: Dict[str, str] = {}
    if snapshots is not None:
        for result in snapshots.results:
            artifacts[f"snapshot:{result.snapshot_id}"] = str(result.path)
    if commands is not None:
        artifacts["commands"] = str(commands.path)
    return MappingProxyType(artifacts)


@dataclass(frozen=True, slots=True)
class DockModelVisualizationFields(MolecularSpecMixin):
    """DockModel attribute names used by visualization."""

    state: str = "visualization"
    plan: str = "visualization_plan"
    config: str = "visualization_config"
    specification: str = "visualization_specification"
    interactions: str = "visualization_interactions"
    execution: str = "visualization_result"
    snapshots: str = "visualization_snapshots"
    commands: str = "visualization_commands"
    files: str = "files"
    metadata: str = "visualization_metadata"

    def __post_init__(self) -> None:
        values: List[str] = []
        for item in fields(self):
            name = _plan_identifier(getattr(self, item.name), field_name=item.name)
            object.__setattr__(self, item.name, name)
            values.append(name)
        duplicates = sorted(name for name, count in Counter(values).items() if count > 1)
        if duplicates:
            raise DockModelVisualizationError(
                "DockModel visualization field names must be unique.",
                context={"duplicates": duplicates},
            )


DEFAULT_DOCK_MODEL_VISUALIZATION_FIELDS: Final[DockModelVisualizationFields] = (
    DockModelVisualizationFields()
)


@dataclass(frozen=True, slots=True)
class DockModelVisualizationState(MolecularSpecMixin):
    """Serializable visualization state attached to a DockModel."""

    model_id: str
    config: VisualizationConfig
    specification: MolecularSpecificationBundle
    interactions: VisualInteractionCollection
    plan: VisualizationPlan
    scores: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)
    execution: Optional[VisualizationExecutionResult] = None
    snapshots: Optional[SnapshotManifestSpec] = None
    commands: Optional[CommandExportResult] = None
    artifacts: Mapping[str, str] = field(default_factory=dict, compare=False, hash=False, repr=False)
    schema_version: str = _DOCK_MODEL_VISUALIZATION_SCHEMA_VERSION
    created_at: Optional[str] = None
    updated_at: Optional[str] = None
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        config_obj = resolve_visualization_config(self.config)
        specification = (
            self.specification
            if isinstance(self.specification, MolecularSpecificationBundle)
            else MolecularSpecificationBundle(**dict(self.specification))
        )
        interactions = (
            self.interactions
            if isinstance(self.interactions, VisualInteractionCollection)
            else VisualInteractionCollection(**dict(self.interactions))
        )
        plan = coerce_visualization_plan(self.plan)
        execution = self.execution
        if execution is not None and not isinstance(execution, VisualizationExecutionResult):
            execution = VisualizationExecutionResult(**dict(execution))
        snapshots = self.snapshots
        if snapshots is not None and not isinstance(snapshots, SnapshotManifestSpec):
            snapshots = SnapshotManifestSpec(**dict(snapshots))
        commands = self.commands
        if commands is not None and not isinstance(commands, CommandExportResult):
            commands = CommandExportResult(**dict(commands))
        created_at = self.created_at or _dock_model_timestamp()
        updated_at = self.updated_at or created_at
        artifacts = dict(self.artifacts)
        artifacts.update(_dock_model_artifact_paths(snapshots=snapshots, commands=commands))
        object.__setattr__(self, "model_id", _plan_identifier(self.model_id, field_name="model_id"))
        object.__setattr__(self, "config", config_obj)
        object.__setattr__(self, "specification", specification)
        object.__setattr__(self, "interactions", interactions)
        object.__setattr__(self, "plan", plan)
        object.__setattr__(self, "scores", _normalize_spec_metadata(self.scores))
        object.__setattr__(self, "execution", execution)
        object.__setattr__(self, "snapshots", snapshots)
        object.__setattr__(self, "commands", commands)
        object.__setattr__(self, "artifacts", MappingProxyType({str(k): str(v) for k, v in artifacts.items()}))
        object.__setattr__(self, "schema_version", str(self.schema_version))
        object.__setattr__(self, "created_at", str(created_at))
        object.__setattr__(self, "updated_at", str(updated_at))
        object.__setattr__(self, "metadata", _normalize_spec_metadata(self.metadata))
        if self.schema_version != _DOCK_MODEL_VISUALIZATION_SCHEMA_VERSION:
            raise DockModelVisualizationError(
                "Unsupported DockModel visualization schema.",
                context={
                    "schema_version": self.schema_version,
                    "supported": _DOCK_MODEL_VISUALIZATION_SCHEMA_VERSION,
                },
            )

    @property
    def complete(self) -> bool:
        return bool(self.plan.actions) and bool(
            self.specification.objects or self.specification.poses
        )

    @property
    def executed(self) -> bool:
        return self.execution is not None

    @property
    def successful(self) -> Optional[bool]:
        return None if self.execution is None else self.execution.success


@dataclass(frozen=True, slots=True)
class DockModelVisualizationInspection(MolecularSpecMixin):
    """DockModel integration capabilities."""

    model_id: str
    object_type: str
    declared_fields: Tuple[str, ...]
    mutable_mapping: bool
    dataclass_instance: bool
    frozen_dataclass: bool
    dynamic_attributes: bool
    has_visualization: bool
    has_files: bool
    interaction_fields: Tuple[str, ...]
    score_fields: Tuple[str, ...]
    pose_fields: Tuple[str, ...]
    warnings: Tuple[str, ...] = ()


@dataclass(frozen=True, slots=True)
class DockModelVisualizationAttachment(MolecularSpecMixin):
    """Result of attaching visualization state."""

    model: Any = field(compare=False, hash=False, repr=False)
    state: DockModelVisualizationState
    mode: DockModelIntegrationMode
    attached_fields: Tuple[str, ...] = ()
    replaced_fields: Tuple[str, ...] = ()
    skipped_fields: Tuple[str, ...] = ()
    warnings: Tuple[str, ...] = ()
    mutated: bool = False

    def __post_init__(self) -> None:
        state = coerce_dock_model_visualization_state(self.state)
        object.__setattr__(self, "state", state)
        object.__setattr__(self, "mode", DockModelIntegrationMode.parse(self.mode, default=DockModelIntegrationMode.ATTACH))
        for name in ("attached_fields", "replaced_fields", "skipped_fields", "warnings"):
            object.__setattr__(self, name, tuple(str(item) for item in getattr(self, name)))
        object.__setattr__(self, "mutated", bool(self.mutated))

    def to_dict(self) -> Dict[str, Any]:
        data = MolecularSpecMixin.to_dict(self)
        data["model"] = {
            "type": type(self.model).__name__,
            "model_id": _dock_model_identifier(self.model),
        }
        return data

    def fingerprint(self) -> str:
        return _spec_fingerprint(self.to_dict())


@dataclass(frozen=True, slots=True)
class DockModelVisualizationRun(MolecularSpecMixin):
    """Plan, execution and attachment produced for a DockModel."""

    model: Any = field(compare=False, hash=False, repr=False)
    state: DockModelVisualizationState
    attachment: Optional[DockModelVisualizationAttachment] = None
    execution: Optional[VisualizationExecutionResult] = None
    issues: Tuple[PlanValidationIssue, ...] = ()
    warnings: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "state", coerce_dock_model_visualization_state(self.state))
        attachment = self.attachment
        if attachment is not None and not isinstance(attachment, DockModelVisualizationAttachment):
            attachment = DockModelVisualizationAttachment(**dict(attachment))
        execution = self.execution
        if execution is not None and not isinstance(execution, VisualizationExecutionResult):
            execution = VisualizationExecutionResult(**dict(execution))
        issues = tuple(
            item if isinstance(item, PlanValidationIssue) else PlanValidationIssue(**dict(item))
            for item in self.issues
        )
        object.__setattr__(self, "attachment", attachment)
        object.__setattr__(self, "execution", execution)
        object.__setattr__(self, "issues", issues)
        object.__setattr__(self, "warnings", tuple(str(item) for item in self.warnings))

    def to_dict(self) -> Dict[str, Any]:
        data = MolecularSpecMixin.to_dict(self)
        data["model"] = {
            "type": type(self.model).__name__,
            "model_id": _dock_model_identifier(self.model),
        }
        return data

    def fingerprint(self) -> str:
        return _spec_fingerprint(self.to_dict())


# 26.2. Inspection and extraction
# -----------------------------------------------------------------------------


def coerce_dock_model_visualization_fields(value: Any = None) -> DockModelVisualizationFields:
    """Coerce DockModel field settings."""

    if value is None:
        return DEFAULT_DOCK_MODEL_VISUALIZATION_FIELDS
    if isinstance(value, DockModelVisualizationFields):
        return value
    if isinstance(value, Mapping):
        return DockModelVisualizationFields(**dict(value))
    data = {
        item.name: getattr(value, item.name)
        for item in fields(DockModelVisualizationFields)
        if hasattr(value, item.name)
    }
    return DockModelVisualizationFields(**data)


def inspect_dock_model(
    value: Any,
    *,
    fields_value: Any = None,
) -> DockModelVisualizationInspection:
    """Inspect DockModel integration capabilities."""

    if value is None:
        raise DockModelVisualizationError("DockModel cannot be None.")
    field_spec = coerce_dock_model_visualization_fields(fields_value)
    declared = _dock_model_field_names(value)
    frozen = False
    if is_dataclass(value):
        params = getattr(type(value), "__dataclass_params__", None)
        frozen = bool(getattr(params, "frozen", False))
    dynamic = hasattr(value, "__dict__") and not frozen
    interactions = tuple(
        name for name, _family in _DOCK_MODEL_INTERACTION_FIELDS
        if _dock_model_value(value, name) is not None
    )
    scores = tuple(name for name in _DOCK_MODEL_SCORE_FIELDS if _dock_model_value(value, name) is not None)
    poses = tuple(name for name in _DOCK_MODEL_POSE_FIELDS if _dock_model_value(value, name) is not None)
    warnings_list: List[str] = []
    if not dynamic and not isinstance(value, MutableMapping) and not is_dataclass(value):
        warnings_list.append("DockModel does not expose a writable mapping or dynamic attributes.")
    return DockModelVisualizationInspection(
        model_id=_dock_model_identifier(value),
        object_type=type(value).__name__,
        declared_fields=declared,
        mutable_mapping=isinstance(value, MutableMapping),
        dataclass_instance=is_dataclass(value),
        frozen_dataclass=frozen,
        dynamic_attributes=dynamic,
        has_visualization=_dock_model_existing_state(value, field_spec) is not None,
        has_files=_dock_model_value(value, field_spec.files) is not None,
        interaction_fields=interactions,
        score_fields=scores,
        pose_fields=poses,
        warnings=tuple(warnings_list),
    )


def extract_dock_model_specification(value: Any) -> MolecularSpecificationBundle:
    """Extract molecular inputs from a DockModel-like object."""

    if isinstance(value, MolecularSpecificationBundle):
        return value
    existing = _dock_model_value(
        value,
        "visualization_specification", "molecular_specification", "specification_bundle",
    )
    if existing is not None:
        if isinstance(existing, MolecularSpecificationBundle):
            return existing
        if isinstance(existing, Mapping):
            return MolecularSpecificationBundle(**dict(existing))

    receptor_raw = _dock_model_value(value, *_DOCK_MODEL_RECEPTOR_FIELDS)
    ligand_raw = _dock_model_value(value, *_DOCK_MODEL_LIGAND_FIELDS)
    ligands_raw = _dock_model_value(value, "ligands", "docked_ligands")
    cofactors_raw = _dock_model_value(value, "cofactors", "cofactor")
    solvent_raw = _dock_model_value(value, "solvent", "waters", "water")
    ions_raw = _dock_model_value(value, "ions", "ion")
    poses_raw = _dock_model_value(value, *_DOCK_MODEL_POSE_FIELDS)
    structure_raw = _dock_model_value(value, "structure_spec", "molecular_structure")

    receptor = None
    if receptor_raw is not None:
        receptor = _dock_model_path_object(
            receptor_raw,
            role=MolecularRole.RECEPTOR,
            fallback="receptor",
        )
    ligand_values = list(_dock_model_sequence(ligands_raw))
    if ligand_raw is not None and not any(item is ligand_raw for item in ligand_values):
        ligand_values.insert(0, ligand_raw)
    ligands = tuple(
        _dock_model_path_object(item, role=MolecularRole.LIGAND, fallback=f"ligand-{index + 1}")
        for index, item in enumerate(ligand_values)
    )
    cofactors = tuple(
        _dock_model_path_object(item, role=MolecularRole.COFACTOR, fallback=f"cofactor-{index + 1}")
        for index, item in enumerate(_dock_model_sequence(cofactors_raw))
    )
    solvent = tuple(
        _dock_model_path_object(item, role=MolecularRole.SOLVENT, fallback=f"solvent-{index + 1}")
        for index, item in enumerate(_dock_model_sequence(solvent_raw))
    )
    ions = tuple(
        _dock_model_path_object(item, role=MolecularRole.ION, fallback=f"ion-{index + 1}")
        for index, item in enumerate(_dock_model_sequence(ions_raw))
    )
    poses: List[PoseSpec] = []
    for index, item in enumerate(_dock_model_sequence(poses_raw)):
        try:
            poses.append(coerce_pose_spec(item, index=index))
        except VisualizationError:
            continue
    structure = None
    if structure_raw is not None:
        if isinstance(structure_raw, StructureSpec):
            structure = structure_raw
        elif isinstance(structure_raw, Mapping):
            structure = StructureSpec(**dict(structure_raw))
    return MolecularSpecificationBundle(
        receptor=receptor,
        ligands=ligands,
        cofactors=cofactors,
        solvent=solvent,
        ions=ions,
        poses=tuple(poses),
        structure=structure,
        metadata={"source": type(value).__name__, "model_id": _dock_model_identifier(value)},
    )


def extract_dock_model_interactions(
    value: Any,
    *,
    config_value: Any = None,
) -> VisualInteractionCollection:
    """Extract all supported interaction families."""

    existing = _dock_model_value(value, "visualization_interactions")
    if existing is not None:
        if isinstance(existing, VisualInteractionCollection):
            return existing
        if isinstance(existing, Mapping) and "interactions" in existing:
            return VisualInteractionCollection(**dict(existing))
    combined: List[Any] = []
    generic = _dock_model_value(value, "interactions", "binding_interactions")
    combined.extend(_dock_model_sequence(generic))
    for name, family in _DOCK_MODEL_INTERACTION_FIELDS:
        items = _dock_model_value(value, name)
        for item in _dock_model_sequence(items):
            if isinstance(item, Mapping):
                payload = dict(item)
                payload.setdefault("family", family.value)
                combined.append(payload)
            elif _dock_model_value(item, "family", "interaction_family") is None:
                try:
                    source, target = _interaction_pair(item)
                except VisualizationError:
                    combined.append(item)
                else:
                    combined.append({
                        "family": family.value,
                        "source": source,
                        "target": target,
                        "distance": _dock_model_value(item, "distance", "minimum_distance"),
                        "score": _dock_model_value(item, "score", "interaction_score"),
                        "pose_id": _dock_model_value(item, "pose_id", "pose"),
                        "metadata": _dock_model_value(item, "metadata", default={}),
                    })
            else:
                combined.append(item)
    return build_visual_interactions(
        combined,
        config_value=config_value,
        name=f"{_dock_model_identifier(value)} interactions",
    )


def extract_dock_model_poses(value: Any) -> Tuple[PoseSpec, ...]:
    """Extract normalized docking poses."""

    specification = extract_dock_model_specification(value)
    if specification.poses:
        return specification.poses
    raw = _dock_model_value(value, *_DOCK_MODEL_POSE_FIELDS)
    return coerce_pose_specs(_dock_model_sequence(raw))


def extract_dock_model_files(value: Any, *, fields_value: Any = None) -> Mapping[str, Any]:
    """Normalize DockModel file references."""

    field_spec = coerce_dock_model_visualization_fields(fields_value)
    raw = _dock_model_value(value, field_spec.files)
    if raw is None:
        return MappingProxyType({})
    if isinstance(raw, Mapping):
        return MappingProxyType({str(key): item for key, item in raw.items()})
    return MappingProxyType({f"file:{index + 1}": item for index, item in enumerate(_dock_model_sequence(raw))})


# 26.3. State construction and merging
# -----------------------------------------------------------------------------


def coerce_dock_model_visualization_state(value: Any) -> DockModelVisualizationState:
    """Coerce a DockModel visualization state."""

    if isinstance(value, DockModelVisualizationState):
        return value
    if isinstance(value, Mapping):
        return DockModelVisualizationState(**dict(value))
    data = {
        item.name: getattr(value, item.name)
        for item in fields(DockModelVisualizationState)
        if hasattr(value, item.name)
    }
    return DockModelVisualizationState(**data)


def _build_dock_model_plan(
    model: Any,
    specification: MolecularSpecificationBundle,
    interactions: VisualInteractionCollection,
    config_obj: VisualizationConfig,
    *,
    include_camera: bool,
    include_multipose: bool,
) -> VisualizationPlan:
    plan = build_visualization_plan(
        (),
        plan_id=f"{_dock_model_identifier(model)}-visualization",
        name=f"{_dock_model_identifier(model)} visualization",
        profile=config_obj.profile,
        execution_mode=ExecutionMode.DEFERRED,
        metadata={"dock_model_id": _dock_model_identifier(model)},
    )
    plan = attach_scene_preparation(
        plan,
        config_value=config_obj,
        molecular_input=specification,
    )
    if specification.receptor is not None:
        plan = attach_receptor_visualization(
            plan,
            specification,
            config_value=config_obj,
        )
    if specification.ligands or specification.poses or specification.cofactors:
        plan = attach_ligand_visualization(
            plan,
            specification,
            config_value=config_obj,
        )
    if interactions.interactions:
        plan = attach_interaction_visualization(
            plan,
            interactions,
            config_value=config_obj,
        )
    if include_multipose and len(specification.poses) > 1:
        plan = attach_multipose(
            plan,
            specification.poses,
            config_value=config_obj,
        )
    if include_camera:
        framing_target = (
            FramingTarget.LIGAND
            if specification.ligands or specification.poses
            else FramingTarget.RECEPTOR
            if specification.receptor is not None
            else FramingTarget.ALL
        )
        plan = attach_camera(
            plan,
            sources=specification,
            selection_bundle=build_molecular_selection_bundle(specification),
            config_value=config_obj,
            framing_target=framing_target,
        )
        camera_actions = []
        for action in plan.actions:
            if action.action_id == "camera:frame":
                params = dict(action.parameters)
                params["center_of_rotation"] = params.get("target") or False
                action = replace(action, parameters=params)
            camera_actions.append(action)
        plan = replace(plan, actions=tuple(camera_actions))
    return plan


def build_dock_model_visualization_state(
    value: Any,
    *,
    config_value: Any = None,
    plan: Any = None,
    specification: Any = None,
    interactions: Any = None,
    execution: Any = None,
    snapshots: Any = None,
    commands: Any = None,
    include_camera: bool = True,
    include_multipose: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> DockModelVisualizationState:
    """Build a complete visualization state from a DockModel."""

    if value is None:
        raise DockModelVisualizationError("DockModel cannot be None.")
    config_obj = resolve_visualization_config(
        config_value or _dock_model_value(value, "visualization_config")
    )
    specification_obj = (
        extract_dock_model_specification(value)
        if specification is None
        else specification
    )
    if not isinstance(specification_obj, MolecularSpecificationBundle):
        specification_obj = MolecularSpecificationBundle(**dict(specification_obj))
    interaction_obj = (
        extract_dock_model_interactions(value, config_value=config_obj)
        if interactions is None
        else build_visual_interactions(interactions, config_value=config_obj)
    )
    plan_obj = (
        _build_dock_model_plan(
            value,
            specification_obj,
            interaction_obj,
            config_obj,
            include_camera=include_camera,
            include_multipose=include_multipose,
        )
        if plan is None
        else coerce_visualization_plan(plan)
    )
    execution_obj = execution
    if execution_obj is not None and not isinstance(execution_obj, VisualizationExecutionResult):
        execution_obj = VisualizationExecutionResult(**dict(execution_obj))
    snapshots_obj = snapshots
    if snapshots_obj is not None and not isinstance(snapshots_obj, SnapshotManifestSpec):
        snapshots_obj = SnapshotManifestSpec(**dict(snapshots_obj))
    commands_obj = commands
    if commands_obj is not None and not isinstance(commands_obj, CommandExportResult):
        commands_obj = CommandExportResult(**dict(commands_obj))
    return DockModelVisualizationState(
        model_id=_dock_model_identifier(value),
        config=config_obj,
        specification=specification_obj,
        interactions=interaction_obj,
        plan=plan_obj,
        scores=_dock_model_score_mapping(value),
        execution=execution_obj,
        snapshots=snapshots_obj,
        commands=commands_obj,
        artifacts=_dock_model_artifact_paths(snapshots=snapshots_obj, commands=commands_obj),
        metadata={
            "dock_model_type": type(value).__name__,
            "source_fields": list(_dock_model_field_names(value)),
            **dict(metadata or {}),
        },
    )


def merge_dock_model_visualization_states(
    base: Any,
    incoming: Any,
) -> DockModelVisualizationState:
    """Merge compatible visualization states."""

    left = coerce_dock_model_visualization_state(base)
    right = coerce_dock_model_visualization_state(incoming)
    if left.model_id != right.model_id:
        raise DockModelVisualizationError(
            "Cannot merge visualization states from different DockModels.",
            context={"left": left.model_id, "right": right.model_id},
        )
    interactions = VisualInteractionCollection(
        interactions=deduplicate_visual_interactions(
            (*left.interactions.interactions, *right.interactions.interactions)
        ),
        name=right.interactions.name or left.interactions.name,
        pose_id=right.interactions.pose_id or left.interactions.pose_id,
        metadata={**dict(left.interactions.metadata), **dict(right.interactions.metadata)},
    )
    specification = right.specification
    if not right.specification.objects and not right.specification.poses:
        specification = left.specification
    plan = right.plan if right.plan.actions else left.plan
    snapshots = right.snapshots or left.snapshots
    commands = right.commands or left.commands
    execution = right.execution or left.execution
    return DockModelVisualizationState(
        model_id=left.model_id,
        config=right.config,
        specification=specification,
        interactions=interactions,
        plan=plan,
        scores={**dict(left.scores), **dict(right.scores)},
        execution=execution,
        snapshots=snapshots,
        commands=commands,
        artifacts={**dict(left.artifacts), **dict(right.artifacts)},
        created_at=left.created_at,
        updated_at=_dock_model_timestamp(),
        metadata={**dict(left.metadata), **dict(right.metadata), "merged": True},
    )


# 26.4. Attachment and file tracking
# -----------------------------------------------------------------------------


def _dock_model_updates(
    state: DockModelVisualizationState,
    fields_value: DockModelVisualizationFields,
) -> Dict[str, Any]:
    return {
        fields_value.state: state,
        fields_value.plan: state.plan,
        fields_value.config: state.config,
        fields_value.specification: state.specification,
        fields_value.interactions: state.interactions,
        fields_value.execution: state.execution,
        fields_value.snapshots: state.snapshots,
        fields_value.commands: state.commands,
        fields_value.metadata: {
            "schema_version": state.schema_version,
            "fingerprint": state.fingerprint(),
            "updated_at": state.updated_at,
        },
    }


def _dock_model_assign(
    model: Any,
    updates: Mapping[str, Any],
) -> Tuple[Any, Tuple[str, ...], Tuple[str, ...]]:
    """Assign fields, replacing frozen dataclasses when possible."""

    applied: List[str] = []
    failed: List[str] = []
    if isinstance(model, MutableMapping):
        for name, value in updates.items():
            model[name] = value
            applied.append(name)
        return model, tuple(applied), ()

    declared = set(_dock_model_field_names(model))
    if is_dataclass(model):
        accepted = {name: item for name, item in updates.items() if name in declared}
        if accepted:
            try:
                model = replace(model, **accepted)
            except (TypeError, ValueError):
                pass
            else:
                applied.extend(accepted)
        for name in updates:
            if name not in applied:
                failed.append(name)
        if applied:
            return model, tuple(applied), tuple(failed)

    for name, value in updates.items():
        try:
            setattr(model, name, value)
        except (AttributeError, TypeError):
            failed.append(name)
        else:
            applied.append(name)
    return model, tuple(applied), tuple(failed)


def _dock_model_merge_files(
    model: Any,
    state: DockModelVisualizationState,
    fields_value: DockModelVisualizationFields,
) -> Tuple[Any, bool, Optional[str]]:
    if not state.artifacts:
        return model, False, None
    current = _dock_model_value(model, fields_value.files)
    if isinstance(current, Mapping) or current is None:
        merged: Any = dict(current or {})
        merged.update(state.artifacts)
    else:
        merged_list = list(_dock_model_sequence(current))
        for path in state.artifacts.values():
            if path not in merged_list:
                merged_list.append(path)
        merged = merged_list
    updated_model, applied, failed = _dock_model_assign(model, {fields_value.files: merged})
    if applied:
        return updated_model, True, None
    return model, False, f"Could not update DockModel field {fields_value.files!r}."


def attach_visualization_to_dock_model(
    model: Any,
    state: Any,
    *,
    mode: Any = DockModelIntegrationMode.ATTACH,
    fields_value: Any = None,
    update_files: bool = True,
    strict: bool = False,
) -> DockModelVisualizationAttachment:
    """Attach visualization state to a DockModel-like object."""

    if model is None:
        raise DockModelVisualizationError("DockModel cannot be None.")
    parsed_mode = DockModelIntegrationMode.parse(mode, default=DockModelIntegrationMode.ATTACH)
    field_spec = coerce_dock_model_visualization_fields(fields_value)
    incoming = coerce_dock_model_visualization_state(state)
    warnings_list: List[str] = []
    if parsed_mode is DockModelIntegrationMode.READ_ONLY:
        return DockModelVisualizationAttachment(
            model=model,
            state=incoming,
            mode=parsed_mode,
            skipped_fields=tuple(_dock_model_updates(incoming, field_spec)),
            warnings=("Read-only integration did not modify DockModel.",),
            mutated=False,
        )

    existing_raw = _dock_model_existing_state(model, field_spec)
    existing = None
    if existing_raw is not None:
        try:
            existing = coerce_dock_model_visualization_state(existing_raw)
        except (TypeError, ValueError, VisualizationError) as exc:
            warnings_list.append(f"Existing visualization state was ignored: {exc}")
    if parsed_mode is DockModelIntegrationMode.ATTACH and existing is not None:
        return DockModelVisualizationAttachment(
            model=model,
            state=existing,
            mode=parsed_mode,
            skipped_fields=tuple(_dock_model_updates(incoming, field_spec)),
            warnings=("DockModel already contains visualization state.",),
            mutated=False,
        )
    if parsed_mode is DockModelIntegrationMode.MERGE and existing is not None:
        incoming = merge_dock_model_visualization_states(existing, incoming)

    updates = _dock_model_updates(incoming, field_spec)
    current_values = {name: _dock_model_value(model, name) for name in updates}
    updated_model, attached, failed = _dock_model_assign(model, updates)
    replaced = tuple(name for name in attached if current_values.get(name) is not None)
    if failed:
        message = f"Could not attach DockModel fields: {', '.join(failed)}."
        if strict:
            raise DockModelVisualizationError(message, context={"fields": failed})
        warnings_list.append(message)
    if update_files:
        updated_model, files_changed, files_warning = _dock_model_merge_files(
            updated_model,
            incoming,
            field_spec,
        )
        if files_changed and field_spec.files not in attached:
            attached = (*attached, field_spec.files)
        if files_warning:
            warnings_list.append(files_warning)
    return DockModelVisualizationAttachment(
        model=updated_model,
        state=incoming,
        mode=parsed_mode,
        attached_fields=attached,
        replaced_fields=replaced,
        skipped_fields=failed,
        warnings=tuple(warnings_list),
        mutated=bool(attached),
    )


def get_dock_model_visualization(
    model: Any,
    *,
    fields_value: Any = None,
    required: bool = False,
) -> Optional[DockModelVisualizationState]:
    """Read attached visualization state."""

    field_spec = coerce_dock_model_visualization_fields(fields_value)
    value = _dock_model_existing_state(model, field_spec)
    if value is None:
        if required:
            raise DockModelVisualizationError("DockModel has no attached visualization state.")
        return None
    return coerce_dock_model_visualization_state(value)


def detach_visualization_from_dock_model(
    model: Any,
    *,
    fields_value: Any = None,
    clear_files: bool = False,
    strict: bool = False,
) -> Any:
    """Clear visualization fields from a DockModel."""

    field_spec = coerce_dock_model_visualization_fields(fields_value)
    names = (
        field_spec.state, field_spec.plan, field_spec.config,
        field_spec.specification, field_spec.interactions,
        field_spec.execution, field_spec.snapshots, field_spec.commands,
        field_spec.metadata,
    )
    updates = {name: None for name in names}
    updated_model, _applied, failed = _dock_model_assign(model, updates)
    if clear_files:
        files_raw = _dock_model_value(updated_model, field_spec.files)
        if isinstance(files_raw, Mapping):
            retained = {
                key: item for key, item in files_raw.items()
                if not str(key).startswith("snapshot:") and str(key) != "commands"
            }
            updated_model, _extra, files_failed = _dock_model_assign(
                updated_model,
                {field_spec.files: retained},
            )
            failed = (*failed, *files_failed)
    if failed and strict:
        raise DockModelVisualizationError(
            "Could not clear all DockModel visualization fields.",
            context={"fields": failed},
        )
    return updated_model


# 26.5. Integrated planning and execution
# -----------------------------------------------------------------------------


def visualize_dock_model(
    model: Any,
    *,
    config_value: Any = None,
    integration_mode: Any = DockModelIntegrationMode.ATTACH,
    execution_mode: Any = ExecutionMode.DEFERRED,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    fields_value: Any = None,
    include_camera: bool = True,
    include_multipose: bool = True,
    validate: bool = True,
    strict: bool = False,
    attach: bool = True,
    metadata: Optional[Mapping[str, Any]] = None,
) -> DockModelVisualizationRun:
    """Plan, optionally execute, and attach DockModel visualization."""

    state = build_dock_model_visualization_state(
        model,
        config_value=config_value,
        include_camera=include_camera,
        include_multipose=include_multipose,
        metadata=metadata,
    )
    plan = replace(
        state.plan,
        execution_mode=ExecutionMode.parse(execution_mode, default=ExecutionMode.DEFERRED),
    )
    issues = validate_visualization_plan(plan) if validate else ()
    errors = tuple(issue for issue in issues if issue.level >= ValidationIssueLevel.ERROR)
    if errors and strict:
        raise DockModelVisualizationError(
            "DockModel visualization plan validation failed.",
            context={"issues": [item.to_dict() for item in errors]},
        )
    execution = None
    parsed_execution = plan.execution_mode
    if parsed_execution in {
        ExecutionMode.IMMEDIATE,
        ExecutionMode.BATCH,
        ExecutionMode.DRY_RUN,
        ExecutionMode.EXPORT_ONLY,
    }:
        execution = execute_visualization_plan(
            plan,
            session=session,
            backend=backend,
            mode=parsed_execution,
        )
    state = replace(
        state,
        plan=plan,
        execution=execution,
        updated_at=_dock_model_timestamp(),
    )
    attachment = None
    updated_model = model
    warnings_list: List[str] = []
    if attach:
        attachment = attach_visualization_to_dock_model(
            model,
            state,
            mode=integration_mode,
            fields_value=fields_value,
            strict=strict,
        )
        updated_model = attachment.model
        warnings_list.extend(attachment.warnings)
    return DockModelVisualizationRun(
        model=updated_model,
        state=state,
        attachment=attachment,
        execution=execution,
        issues=issues,
        warnings=tuple(warnings_list),
    )


def visualize_dock_models(
    models: Iterable[Any],
    *,
    config_value: Any = None,
    integration_mode: Any = DockModelIntegrationMode.ATTACH,
    execution_mode: Any = ExecutionMode.DEFERRED,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    fields_value: Any = None,
    strict: bool = False,
    attach: bool = True,
) -> Tuple[DockModelVisualizationRun, ...]:
    """Visualize several DockModels independently."""

    results: List[DockModelVisualizationRun] = []
    errors: List[BaseException] = []
    for model in models:
        try:
            results.append(visualize_dock_model(
                model,
                config_value=config_value,
                integration_mode=integration_mode,
                execution_mode=execution_mode,
                session=session,
                backend=backend,
                fields_value=fields_value,
                strict=strict,
                attach=attach,
            ))
        except Exception as exc:
            if strict:
                raise
            errors.append(exc)
    if errors and not results:
        raise VisualizationErrorGroup(
            "All DockModel visualizations failed.",
            errors=errors,
        )
    return tuple(results)


def update_dock_model_visualization(
    model: Any,
    *,
    config_value: Any = None,
    rebuild_plan: bool = True,
    mode: Any = DockModelIntegrationMode.REPLACE,
    fields_value: Any = None,
    strict: bool = False,
) -> DockModelVisualizationAttachment:
    """Refresh an attached DockModel visualization state."""

    current = get_dock_model_visualization(model, fields_value=fields_value)
    incoming = build_dock_model_visualization_state(
        model,
        config_value=config_value or (current.config if current else None),
        plan=None if rebuild_plan else (current.plan if current else None),
        execution=current.execution if current else None,
        snapshots=current.snapshots if current else None,
        commands=current.commands if current else None,
        metadata={"refreshed": True},
    )
    return attach_visualization_to_dock_model(
        model,
        incoming,
        mode=mode,
        fields_value=fields_value,
        strict=strict,
    )


# 26.6. Validation, summaries and serialization
# -----------------------------------------------------------------------------


def validate_dock_model_visualization(
    model: Any,
    state: Any = None,
    *,
    fields_value: Any = None,
    raise_on_error: bool = False,
) -> Tuple[PlanValidationIssue, ...]:
    """Validate DockModel integration and state."""

    issues: List[PlanValidationIssue] = []
    try:
        inspection = inspect_dock_model(model, fields_value=fields_value)
    except VisualizationError as exc:
        issues.append(PlanValidationIssue(
            ValidationIssueLevel.FATAL,
            "dock_model_invalid",
            str(exc),
        ))
        inspection = None
    if inspection is not None:
        for message in inspection.warnings:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.WARNING,
                "dock_model_capability",
                message,
            ))
    state_obj = state
    if state_obj is None and inspection is not None and inspection.has_visualization:
        state_obj = get_dock_model_visualization(model, fields_value=fields_value)
    if state_obj is not None:
        try:
            normalized = coerce_dock_model_visualization_state(state_obj)
        except (TypeError, ValueError, VisualizationError) as exc:
            issues.append(PlanValidationIssue(
                ValidationIssueLevel.ERROR,
                "dock_model_state_invalid",
                str(exc),
            ))
        else:
            if inspection is not None and normalized.model_id != inspection.model_id:
                issues.append(PlanValidationIssue(
                    ValidationIssueLevel.ERROR,
                    "dock_model_state_mismatch",
                    "Visualization state belongs to another DockModel.",
                    context={"model": inspection.model_id, "state": normalized.model_id},
                ))
            issues.extend(validate_visualization_plan(normalized.plan))
            if not normalized.specification.objects and not normalized.specification.poses:
                issues.append(PlanValidationIssue(
                    ValidationIssueLevel.WARNING,
                    "dock_model_specification_empty",
                    "DockModel visualization has no molecular objects or poses.",
                ))
    if raise_on_error and any(issue.level >= ValidationIssueLevel.ERROR for issue in issues):
        raise DockModelVisualizationError(
            "DockModel visualization validation failed.",
            context={"issues": [item.to_dict() for item in issues]},
        )
    return tuple(issues)


def summarize_dock_model_visualization(
    model: Any,
    state: Any = None,
    *,
    fields_value: Any = None,
) -> Dict[str, Any]:
    """Return a compact DockModel visualization summary."""

    inspection = inspect_dock_model(model, fields_value=fields_value)
    state_obj = state
    if state_obj is None:
        state_obj = get_dock_model_visualization(model, fields_value=fields_value)
    summary: Dict[str, Any] = {
        "model_id": inspection.model_id,
        "object_type": inspection.object_type,
        "has_visualization": state_obj is not None,
        "interaction_fields": inspection.interaction_fields,
        "score_fields": inspection.score_fields,
        "pose_fields": inspection.pose_fields,
        "warnings": inspection.warnings,
    }
    if state_obj is not None:
        normalized = coerce_dock_model_visualization_state(state_obj)
        summary.update({
            "profile": normalized.config.profile.value,
            "objects": len(normalized.specification.objects),
            "poses": len(normalized.specification.poses),
            "interactions": len(normalized.interactions.interactions),
            "actions": len(normalized.plan.actions),
            "executed": normalized.executed,
            "successful": normalized.successful,
            "artifacts": dict(normalized.artifacts),
            "fingerprint": normalized.fingerprint(),
        })
    return summary


def dock_model_visualization_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize DockModel visualization state."""

    return coerce_dock_model_visualization_state(value).to_dict()


def dock_model_visualization_to_json(
    value: Any,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize DockModel visualization state as JSON."""

    return json.dumps(
        dock_model_visualization_to_dict(value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


