_CONVENIENCE_SCHEMA_VERSION: Final[str] = "1.0"
_CONVENIENCE_DEFAULT_NAME: Final[str] = "DockAnalyzer visualization"
_CONVENIENCE_LAYER_NAMES: Final[Tuple[str, ...]] = (
    "scene",
    "receptor",
    "ligand",
    "interactions",
    "virtual_points",
    "residues",
    "hotspots",
    "scoring",
    "multipose",
    "consensus",
    "complementarity",
    "annotations",
    "camera",
)
_CONVENIENCE_LAYER_PRESETS: Final[Mapping[str, Tuple[str, ...]]] = MappingProxyType({
    "minimal": ("scene", "receptor", "ligand", "camera"),
    "standard": ("scene", "receptor", "ligand", "interactions", "residues", "camera"),
    "analysis": (
        "scene", "receptor", "ligand", "interactions", "virtual_points",
        "residues", "hotspots", "scoring", "multipose", "camera",
    ),
    "publication": (
        "scene", "receptor", "ligand", "interactions", "residues",
        "hotspots", "scoring", "multipose", "annotations", "camera",
    ),
    "all": _CONVENIENCE_LAYER_NAMES,
})


def _convenience_bool(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, str):
        text = value.strip().lower()
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
    return bool(value)


def _convenience_source_id(value: Any) -> str:
    try:
        return _dock_model_identifier(value)
    except Exception:
        name = _object_value(value, "name", "id", "identifier")
        return _plan_identifier(name or f"source-{id(value):x}", field_name="source identifier")


def _convenience_source_summary(value: Any) -> Dict[str, Any]:
    return {
        "type": type(value).__name__,
        "source_id": _convenience_source_id(value),
    }


def _convenience_metadata(value: Optional[Mapping[str, Any]]) -> Mapping[str, Any]:
    data = dict(value or {})
    data.setdefault("schema", "dockanalyzer.visualization.convenience")
    data.setdefault("schema_version", _CONVENIENCE_SCHEMA_VERSION)
    return MappingProxyType(data)


@dataclass(frozen=True, slots=True)
class VisualizationLayers(MolecularSpecMixin):
    """Enabled high-level visualization layers."""

    scene: bool = True
    receptor: bool = True
    ligand: bool = True
    interactions: bool = True
    virtual_points: bool = False
    residues: bool = True
    hotspots: bool = False
    scoring: bool = False
    multipose: bool = True
    consensus: bool = False
    complementarity: bool = False
    annotations: bool = False
    camera: bool = True

    def __post_init__(self) -> None:
        for item in fields(self):
            object.__setattr__(self, item.name, bool(getattr(self, item.name)))

    @property
    def enabled(self) -> Tuple[str, ...]:
        return tuple(name for name in _CONVENIENCE_LAYER_NAMES if getattr(self, name))

    @property
    def disabled(self) -> Tuple[str, ...]:
        return tuple(name for name in _CONVENIENCE_LAYER_NAMES if not getattr(self, name))

    def with_layers(self, *names: str, enabled: bool = True) -> "VisualizationLayers":
        updates = {name: bool(enabled) for name in names}
        unknown = sorted(set(updates).difference(_CONVENIENCE_LAYER_NAMES))
        if unknown:
            raise VisualizationConfigurationError(
                "Unknown visualization layers.",
                context={"layers": unknown},
            )
        return replace(self, **updates)


@dataclass(frozen=True, slots=True)
class VisualizationRequest:
    """One high-level visualization request."""

    source: Any = field(compare=False, hash=False, repr=False)
    config: VisualizationConfig = field(default_factory=VisualizationConfig)
    layers: VisualizationLayers = field(default_factory=VisualizationLayers)
    execution_mode: ExecutionMode = ExecutionMode.DEFERRED
    integration_mode: DockModelIntegrationMode = DockModelIntegrationMode.ATTACH
    snapshots: Optional[SnapshotCollection] = None
    command_export: Optional[CommandExportSpec] = None
    attach: bool = True
    validate: bool = True
    strict: bool = False
    name: str = _CONVENIENCE_DEFAULT_NAME
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        if self.source is None:
            raise VisualizationSpecificationError("Visualization source is required.")
        config_obj = resolve_visualization_config(self.config)
        layers_obj = coerce_visualization_layers(self.layers, profile=config_obj.profile)
        snapshots_obj = None if self.snapshots is None else coerce_snapshot_collection(
            self.snapshots,
            config_value=config_obj,
        )
        export_obj = None if self.command_export is None else coerce_command_export_spec(
            self.command_export,
        )
        object.__setattr__(self, "config", config_obj)
        object.__setattr__(self, "layers", layers_obj)
        object.__setattr__(self, "execution_mode", ExecutionMode.parse(
            self.execution_mode,
            default=ExecutionMode.DEFERRED,
        ))
        object.__setattr__(self, "integration_mode", DockModelIntegrationMode.parse(
            self.integration_mode,
            default=DockModelIntegrationMode.ATTACH,
        ))
        object.__setattr__(self, "snapshots", snapshots_obj)
        object.__setattr__(self, "command_export", export_obj)
        object.__setattr__(self, "attach", bool(self.attach))
        object.__setattr__(self, "validate", bool(self.validate))
        object.__setattr__(self, "strict", bool(self.strict))
        object.__setattr__(self, "name", _plan_text(
            self.name,
            field_name="visualization request name",
            required=True,
            maximum=256,
        ) or _CONVENIENCE_DEFAULT_NAME)
        object.__setattr__(self, "metadata", _convenience_metadata(self.metadata))

    @property
    def source_id(self) -> str:
        return _convenience_source_id(self.source)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "source": _convenience_source_summary(self.source),
            "config": self.config.to_dict(),
            "layers": self.layers.to_dict(),
            "execution_mode": self.execution_mode.value,
            "integration_mode": self.integration_mode.value,
            "snapshots": None if self.snapshots is None else self.snapshots.to_dict(),
            "command_export": None if self.command_export is None else self.command_export.to_dict(),
            "attach": self.attach,
            "validate": self.validate,
            "strict": self.strict,
            "name": self.name,
            "metadata": dict(self.metadata),
        }

    def fingerprint(self) -> str:
        return _spec_fingerprint(self.to_dict())


@dataclass(frozen=True, slots=True)
class VisualizationOutcome:
    """Result returned by the convenience interface."""

    request: VisualizationRequest
    state: DockModelVisualizationState
    model: Any = field(default=None, compare=False, hash=False, repr=False)
    execution: Optional[VisualizationExecutionResult] = None
    attachment: Optional[DockModelVisualizationAttachment] = None
    commands: Optional[CommandExportResult] = None
    snapshots: Optional[SnapshotManifestSpec] = None
    issues: Tuple[PlanValidationIssue, ...] = ()
    warnings: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        request_obj = coerce_visualization_request(self.request)
        state_obj = coerce_dock_model_visualization_state(self.state)
        execution_obj = self.execution
        if execution_obj is not None and not isinstance(execution_obj, VisualizationExecutionResult):
            execution_obj = VisualizationExecutionResult(**dict(execution_obj))
        attachment_obj = self.attachment
        if attachment_obj is not None and not isinstance(attachment_obj, DockModelVisualizationAttachment):
            attachment_obj = DockModelVisualizationAttachment(**dict(attachment_obj))
        commands_obj = self.commands
        if commands_obj is not None and not isinstance(commands_obj, CommandExportResult):
            commands_obj = CommandExportResult(**dict(commands_obj))
        snapshots_obj = self.snapshots
        if snapshots_obj is not None and not isinstance(snapshots_obj, SnapshotManifestSpec):
            snapshots_obj = SnapshotManifestSpec(**dict(snapshots_obj))
        issues = tuple(
            item if isinstance(item, PlanValidationIssue) else PlanValidationIssue(**dict(item))
            for item in self.issues
        )
        object.__setattr__(self, "request", request_obj)
        object.__setattr__(self, "state", state_obj)
        object.__setattr__(self, "execution", execution_obj)
        object.__setattr__(self, "attachment", attachment_obj)
        object.__setattr__(self, "commands", commands_obj)
        object.__setattr__(self, "snapshots", snapshots_obj)
        object.__setattr__(self, "issues", issues)
        object.__setattr__(self, "warnings", tuple(str(item) for item in self.warnings))
        if self.model is None:
            object.__setattr__(self, "model", request_obj.source)

    @property
    def plan(self) -> VisualizationPlan:
        return self.state.plan

    @property
    def successful(self) -> bool:
        if any(issue.level >= ValidationIssueLevel.ERROR for issue in self.issues):
            return False
        if self.execution is not None and not self.execution.success:
            return False
        return True

    @property
    def artifacts(self) -> Mapping[str, str]:
        return self.state.artifacts

    def to_dict(self) -> Dict[str, Any]:
        return {
            "request": self.request.to_dict(),
            "state": self.state.to_dict(),
            "model": _convenience_source_summary(self.model),
            "execution": None if self.execution is None else self.execution.to_dict(),
            "attachment": None if self.attachment is None else self.attachment.to_dict(),
            "commands": None if self.commands is None else self.commands.to_dict(),
            "snapshots": None if self.snapshots is None else self.snapshots.to_dict(),
            "issues": [item.to_dict() for item in self.issues],
            "warnings": list(self.warnings),
            "successful": self.successful,
            "artifacts": dict(self.artifacts),
        }

    def fingerprint(self) -> str:
        return _spec_fingerprint(self.to_dict())


# 27.1. Request coercion
# -----------------------------------------------------------------------------


def coerce_visualization_layers(
    value: Any = None,
    *,
    profile: Any = None,
) -> VisualizationLayers:
    """Coerce layer presets, names or mappings."""

    if isinstance(value, VisualizationLayers):
        return value
    profile_value = VisualizationProfile.parse(
        profile,
        default=VisualizationProfile.ANALYSIS,
        strict=False,
    )
    default_preset = profile_value.value if profile_value.value in _CONVENIENCE_LAYER_PRESETS else "analysis"
    if value is None:
        value = default_preset
    if isinstance(value, str):
        key = value.strip().lower().replace("-", "_").replace(" ", "_")
        names = _CONVENIENCE_LAYER_PRESETS.get(key)
        if names is None:
            if key not in _CONVENIENCE_LAYER_NAMES:
                raise VisualizationConfigurationError(
                    f"Unknown visualization layer preset: {value!r}.",
                    context={"available": sorted((*_CONVENIENCE_LAYER_PRESETS, *_CONVENIENCE_LAYER_NAMES))},
                )
            names = (key,)
        enabled = set(names)
        return VisualizationLayers(**{
            name: name in enabled for name in _CONVENIENCE_LAYER_NAMES
        })
    if isinstance(value, Mapping):
        data = {str(key): _convenience_bool(item) for key, item in value.items()}
        unknown = sorted(set(data).difference(_CONVENIENCE_LAYER_NAMES))
        if unknown:
            raise VisualizationConfigurationError(
                "Unknown visualization layers.",
                context={"layers": unknown},
            )
        base = coerce_visualization_layers(default_preset, profile=profile_value)
        return replace(base, **data)
    if isinstance(value, Iterable):
        names = {str(item).strip().lower().replace("-", "_") for item in value}
        unknown = sorted(names.difference(_CONVENIENCE_LAYER_NAMES))
        if unknown:
            raise VisualizationConfigurationError(
                "Unknown visualization layers.",
                context={"layers": unknown},
            )
        return VisualizationLayers(**{
            name: name in names for name in _CONVENIENCE_LAYER_NAMES
        })
    raise VisualizationConfigurationError(
        f"Cannot coerce {type(value).__name__} to VisualizationLayers."
    )


def build_visualization_request(
    source: Any,
    *,
    config_value: Any = None,
    profile: Any = None,
    layers: Any = None,
    execution_mode: Any = ExecutionMode.DEFERRED,
    integration_mode: Any = DockModelIntegrationMode.ATTACH,
    snapshots: Any = None,
    command_export: Any = None,
    attach: bool = True,
    validate: bool = True,
    strict: bool = False,
    name: str = _CONVENIENCE_DEFAULT_NAME,
    metadata: Optional[Mapping[str, Any]] = None,
) -> VisualizationRequest:
    """Build a normalized visualization request."""

    config_obj = resolve_visualization_config(config_value, profile=profile)
    return VisualizationRequest(
        source=source,
        config=config_obj,
        layers=coerce_visualization_layers(layers, profile=config_obj.profile),
        execution_mode=execution_mode,
        integration_mode=integration_mode,
        snapshots=None if snapshots is None else coerce_snapshot_collection(
            snapshots,
            config_value=config_obj,
        ),
        command_export=None if command_export is None else coerce_command_export_spec(
            command_export,
        ),
        attach=attach,
        validate=validate,
        strict=strict,
        name=name,
        metadata=metadata or {},
    )


def coerce_visualization_request(
    value: Any,
    *,
    source: Any = None,
    **overrides: Any,
) -> VisualizationRequest:
    """Coerce a request or source object."""

    if isinstance(value, VisualizationRequest):
        if not overrides and source is None:
            return value
        data = {
            "source": value.source if source is None else source,
            "config": value.config,
            "layers": value.layers,
            "execution_mode": value.execution_mode,
            "integration_mode": value.integration_mode,
            "snapshots": value.snapshots,
            "command_export": value.command_export,
            "attach": value.attach,
            "validate": value.validate,
            "strict": value.strict,
            "name": value.name,
            "metadata": value.metadata,
        }
        data.update(overrides)
        return VisualizationRequest(**data)
    if isinstance(value, Mapping) and "source" in value:
        data = dict(value)
        if source is not None:
            data["source"] = source
        data.update(overrides)
        if "config_value" in data and "config" not in data:
            data["config"] = data.pop("config_value")
        return build_visualization_request(
            data.pop("source"),
            config_value=data.pop("config", None),
            **data,
        )
    actual_source = value if source is None else source
    return build_visualization_request(actual_source, **overrides)


# 27.2. Plan assembly
# -----------------------------------------------------------------------------


def _convenience_try(
    label: str,
    operation: Callable[[], Any],
    *,
    strict: bool,
    warnings_list: List[str],
    fallback: Any,
) -> Any:
    try:
        return operation()
    except (TypeError, ValueError, VisualizationError) as exc:
        if strict:
            raise
        warnings_list.append(f"{label} was skipped: {exc}")
        return fallback


def _convenience_empty_plan(request: VisualizationRequest) -> VisualizationPlan:
    return build_visualization_plan(
        (),
        plan_id=f"{request.source_id}-visualization",
        name=request.name,
        profile=request.config.profile,
        execution_mode=request.execution_mode,
        metadata={"source_id": request.source_id, **dict(request.metadata)},
        validate=False,
        order=False,
    )


def _convenience_pose_count(state: DockModelVisualizationState) -> int:
    pose_ids = {pose.pose_id for pose in state.specification.poses}
    pose_ids.update(
        item.pose_id for item in state.interactions.interactions if item.pose_id
    )
    return len(pose_ids)


def _convenience_groups(state: DockModelVisualizationState) -> Tuple[MolecularGroupSpec, ...]:
    structure = state.specification.structure
    return () if structure is None else structure.groups


def _convenience_pose_scores(state: DockModelVisualizationState) -> Mapping[str, Any]:
    scores: Dict[str, Any] = {
        pose.pose_id: pose.score
        for pose in state.specification.poses
        if pose.score is not None
    }
    for key in ("pose_scores", "scores_by_pose", "poses"):
        value = state.scores.get(key)
        if isinstance(value, Mapping):
            for pose_id, item in value.items():
                if isinstance(item, Mapping):
                    score = item.get("score", item.get("total_score"))
                else:
                    score = item
                if score is not None:
                    scores[str(pose_id)] = score
    return MappingProxyType(scores)


def _build_convenience_plan(
    request: VisualizationRequest,
    state: DockModelVisualizationState,
) -> Tuple[VisualizationPlan, Mapping[str, Any], Tuple[str, ...]]:
    layers = request.layers
    config_obj = request.config
    warnings_list: List[str] = []
    context: Dict[str, Any] = {}
    if layers.scene:
        plan = _convenience_try(
            "Scene preparation",
            lambda: build_scene_preparation_plan(
                config_value=config_obj,
                molecular_input=state.specification,
                plan_id=f"{request.source_id}-scene",
                name=request.name,
                execution_mode=request.execution_mode,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=_convenience_empty_plan(request),
        )
    else:
        plan = _convenience_empty_plan(request)

    if layers.receptor and state.specification.receptor is not None:
        plan = _convenience_try(
            "Receptor visualization",
            lambda: attach_receptor_visualization(
                plan,
                state.specification,
                config_value=config_obj,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )
    if layers.ligand and (state.specification.ligands or state.specification.poses):
        plan = _convenience_try(
            "Ligand visualization",
            lambda: attach_ligand_visualization(
                plan,
                state.specification,
                config_value=config_obj,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )
    if layers.interactions and state.interactions.interactions:
        plan = _convenience_try(
            "Interaction visualization",
            lambda: attach_interaction_visualization(
                plan,
                state.interactions,
                config_value=config_obj,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )

    if layers.virtual_points and (state.interactions.interactions or _convenience_groups(state)):
        virtual_points = _convenience_try(
            "Virtual-point construction",
            lambda: build_virtual_point_collection(
                groups=_convenience_groups(state),
                interactions=state.interactions.interactions,
                strict=request.strict,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if virtual_points is not None and virtual_points.points:
            context["virtual_points"] = virtual_points
            plan = _convenience_try(
                "Virtual-point visualization",
                lambda: attach_virtual_points(plan, virtual_points),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=plan,
            )

    pose_count = _convenience_pose_count(state)
    residues = None
    if (layers.residues or layers.hotspots or layers.annotations) and state.interactions.interactions:
        residues = _convenience_try(
            "Involved-residue construction",
            lambda: build_involved_residue_collection(
                state.interactions,
                pose_count=pose_count or None,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if residues is not None:
            context["residues"] = residues
            if layers.residues and residues.residues:
                plan = _convenience_try(
                    "Involved-residue visualization",
                    lambda: attach_involved_residues(
                        plan,
                        residues,
                        config_value=config_obj,
                    ),
                    strict=request.strict,
                    warnings_list=warnings_list,
                    fallback=plan,
                )

    hotspots = None
    if layers.hotspots and residues is not None and residues.residues:
        hotspots = _convenience_try(
            "Hotspot construction",
            lambda: build_hotspot_collection(
                residues,
                pose_count=pose_count or None,
                allow_singletons=True,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if hotspots is not None and hotspots.hotspots:
            context["hotspots"] = hotspots
            plan = _convenience_try(
                "Hotspot visualization",
                lambda: attach_hotspots(plan, hotspots, config_value=config_obj),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=plan,
            )

    visual_scores = None
    if layers.scoring and state.scores:
        visual_scores = _convenience_try(
            "Visual-score construction",
            lambda: build_visual_score_collection(state.scores),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if visual_scores is not None and visual_scores.items:
            context["scores"] = visual_scores
            plan = _convenience_try(
                "Visual scoring",
                lambda: attach_scoring(plan, visual_scores, config_value=config_obj),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=plan,
            )

    if layers.multipose and len(state.specification.poses) > 1:
        plan = _convenience_try(
            "Multipose visualization",
            lambda: attach_multipose(
                plan,
                state.specification.poses,
                config_value=config_obj,
                scores=_convenience_pose_scores(state),
                interactions=state.interactions,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )

    consensus = None
    if layers.consensus and pose_count > 1 and state.interactions.interactions:
        consensus = _convenience_try(
            "Consensus construction",
            lambda: build_consensus_collection(state.interactions),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if consensus is not None and consensus.items:
            context["consensus"] = consensus
            plan = _convenience_try(
                "Consensus visualization",
                lambda: attach_consensus(plan, consensus, config_value=config_obj),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=plan,
            )

    complementarity = None
    if layers.complementarity and len(state.specification.poses) > 1:
        complementarity = _convenience_try(
            "Complementarity selection",
            lambda: select_complementary_poses(
                state.specification.poses,
                interactions=state.interactions,
                residues=residues,
                hotspots=hotspots,
                scores=_convenience_pose_scores(state),
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        if complementarity is not None and complementarity.selected_pose_ids:
            context["complementarity"] = complementarity
            plan = _convenience_try(
                "Complementarity visualization",
                lambda: attach_complementarity(
                    plan,
                    complementarity,
                    config_value=config_obj,
                ),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=plan,
            )

    if layers.annotations:
        annotation_values: List[Any] = []
        annotation_values.extend(state.interactions.interactions)
        if residues is not None:
            annotation_values.extend(
                item for item in residues.residues if not item.selection.is_none
            )
        if hotspots is not None:
            annotation_values.extend(
                item for item in hotspots.hotspots
                if item.center is not None or not item.selection.is_none
            )
        if visual_scores is not None:
            annotation_values.extend(
                item for item in visual_scores.items
                if not item.selection.is_none or item.metadata.get("coordinate") is not None
            )
        if not annotation_values:
            annotation_values.extend(state.specification.poses)
        if annotation_values:
            annotations = _convenience_try(
                "Annotation construction",
                lambda: build_annotation_collection(
                    annotation_values,
                    config_value=config_obj,
                ),
                strict=request.strict,
                warnings_list=warnings_list,
                fallback=None,
            )
            if annotations is not None and (annotations.annotations or annotations.legends):
                context["annotations"] = annotations
                plan = _convenience_try(
                    "Annotation visualization",
                    lambda: attach_annotations(
                        plan,
                        annotations,
                        config_value=config_obj,
                    ),
                    strict=request.strict,
                    warnings_list=warnings_list,
                    fallback=plan,
                )

    if layers.camera:
        selection_bundle = _convenience_try(
            "Selection conversion",
            lambda: build_molecular_selection_bundle(state.specification),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=None,
        )
        camera_sources = tuple(
            item for item in (
                state.specification,
                state.interactions,
                residues,
                hotspots,
                context.get("virtual_points"),
            ) if item is not None
        )
        plan = _convenience_try(
            "Camera framing",
            lambda: attach_camera(
                plan,
                config_value=config_obj,
                selection_bundle=selection_bundle,
                sources=camera_sources,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )

    if request.snapshots is not None and request.snapshots.enabled_requests:
        plan = _convenience_try(
            "Snapshot planning",
            lambda: attach_snapshots(
                plan,
                request.snapshots,
                config_value=config_obj,
            ),
            strict=request.strict,
            warnings_list=warnings_list,
            fallback=plan,
        )

    plan = build_visualization_plan(
        plan.actions,
        plan_id=f"{request.source_id}-visualization",
        name=request.name,
        profile=config_obj.profile,
        execution_mode=request.execution_mode,
        metadata={
            "source_id": request.source_id,
            "layers": request.layers.enabled,
            **dict(request.metadata),
        },
        validate=request.validate,
        order=True,
    )
    return plan, MappingProxyType(context), tuple(warnings_list)


def plan_visualization(
    value: Any,
    **request_overrides: Any,
) -> DockModelVisualizationState:
    """Build a complete high-level visualization state."""

    request = coerce_visualization_request(value, **request_overrides)
    base_state = build_dock_model_visualization_state(
        request.source,
        config_value=request.config,
        include_camera=False,
        include_multipose=False,
        metadata={"convenience_api": True, **dict(request.metadata)},
    )
    plan, context, warnings_list = _build_convenience_plan(request, base_state)
    metadata = dict(base_state.metadata)
    metadata.update({
        "convenience_api": True,
        "layers": request.layers.enabled,
        "context": tuple(context),
        "warnings": warnings_list,
    })
    return replace(
        base_state,
        plan=plan,
        metadata=metadata,
        updated_at=_dock_model_timestamp(),
    )


# 27.3. Execution, export and attachment
# -----------------------------------------------------------------------------


def _convenience_snapshot_manifest(
    collection: Optional[SnapshotCollection],
    state: DockModelVisualizationState,
) -> Optional[SnapshotManifestSpec]:
    if collection is None:
        return None
    results: List[SnapshotResultSpec] = []
    for request in collection.enabled_requests:
        path = request.output_path
        if not path.is_file():
            continue
        image = None
        try:
            image = inspect_image_file(path)
        except (OSError, VisualizationError):
            image = None
        results.append(SnapshotResultSpec(
            snapshot_id=request.snapshot_id,
            path=path,
            success=True,
            image=image,
        ))
    if not results:
        return None
    return create_snapshot_manifest(
        collection,
        results,
        visualization=state,
        metadata={"discovered": True},
    )


def run_visualization(
    value: Any,
    *,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    fields_value: Any = None,
    **request_overrides: Any,
) -> VisualizationOutcome:
    """Plan, execute, export and optionally attach a visualization."""

    request = coerce_visualization_request(value, **request_overrides)
    state = plan_visualization(request)
    issues = validate_visualization_plan(state.plan) if request.validate else ()
    errors = tuple(issue for issue in issues if issue.level >= ValidationIssueLevel.ERROR)
    if errors and request.strict:
        raise VisualizationPlanError(
            "Visualization plan validation failed.",
            context={"issues": [item.to_dict() for item in errors]},
        )

    execution = None
    if request.execution_mode is not ExecutionMode.DEFERRED:
        execution = execute_visualization_plan(
            state.plan,
            session=session,
            backend=backend,
            mode=request.execution_mode,
        )

    commands = None
    if request.command_export is not None:
        commands = export_visualization_commands(state.plan, request.command_export)

    snapshots = None
    if request.execution_mode in {ExecutionMode.IMMEDIATE, ExecutionMode.BATCH}:
        snapshots = _convenience_snapshot_manifest(request.snapshots, state)

    state = replace(
        state,
        execution=execution,
        commands=commands,
        snapshots=snapshots,
        updated_at=_dock_model_timestamp(),
    )
    attachment = None
    model = request.source
    warnings_list = list(state.metadata.get("warnings", ()))
    if request.attach:
        attachment = attach_visualization_to_dock_model(
            request.source,
            state,
            mode=request.integration_mode,
            fields_value=fields_value,
            strict=request.strict,
        )
        model = attachment.model
        warnings_list.extend(attachment.warnings)
    return VisualizationOutcome(
        request=request,
        state=state,
        model=model,
        execution=execution,
        attachment=attachment,
        commands=commands,
        snapshots=snapshots,
        issues=issues,
        warnings=tuple(warnings_list),
    )


def preview_visualization(
    value: Any,
    *,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    **request_overrides: Any,
) -> VisualizationOutcome:
    """Dry-run a visualization without modifying the source."""

    request_overrides.update({
        "execution_mode": ExecutionMode.DRY_RUN,
        "attach": False,
    })
    return run_visualization(
        value,
        session=session,
        backend=backend,
        **request_overrides,
    )


def visualize(
    value: Any,
    *,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    fields_value: Any = None,
    **request_overrides: Any,
) -> VisualizationOutcome:
    """Run the default high-level visualization workflow."""

    return run_visualization(
        value,
        session=session,
        backend=backend,
        fields_value=fields_value,
        **request_overrides,
    )


def visualize_many(
    values: Iterable[Any],
    *,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    fields_value: Any = None,
    strict: bool = False,
    **request_overrides: Any,
) -> Tuple[VisualizationOutcome, ...]:
    """Run the convenience workflow for several sources."""

    outcomes: List[VisualizationOutcome] = []
    errors: List[BaseException] = []
    for value in values:
        try:
            outcomes.append(run_visualization(
                value,
                session=session,
                backend=backend,
                fields_value=fields_value,
                strict=strict,
                **request_overrides,
            ))
        except Exception as exc:
            if strict:
                raise
            errors.append(exc)
    if errors and not outcomes:
        raise VisualizationErrorGroup(
            "All visualization requests failed.",
            errors=errors,
        )
    return tuple(outcomes)


def export_visualization(
    value: Any,
    export: Any = None,
    *,
    filename: Optional[PathLike] = None,
    **request_overrides: Any,
) -> CommandExportResult:
    """Build and export a reproducible command script."""

    state = plan_visualization(value, **request_overrides)
    if export is None:
        export = {}
    if filename is not None:
        if isinstance(export, CommandExportSpec):
            export = replace(export, filename=Path(filename))
        else:
            export = {**dict(export), "filename": Path(filename)}
    return export_visualization_commands(state.plan, export)


def snapshot_visualization(
    value: Any,
    snapshots: Any,
    *,
    session: Any = None,
    backend: Optional[ChimeraXBackend] = None,
    execution_mode: Any = ExecutionMode.IMMEDIATE,
    **request_overrides: Any,
) -> VisualizationOutcome:
    """Run a visualization with one or more snapshots."""

    request_overrides.update({
        "snapshots": snapshots,
        "execution_mode": execution_mode,
    })
    return run_visualization(
        value,
        session=session,
        backend=backend,
        **request_overrides,
    )


def attach_visualization(
    model: Any,
    value: Any = None,
    *,
    mode: Any = DockModelIntegrationMode.ATTACH,
    fields_value: Any = None,
    strict: bool = False,
    **request_overrides: Any,
) -> DockModelVisualizationAttachment:
    """Attach a planned state to a DockModel."""

    state = plan_visualization(model, **request_overrides) if value is None else (
        value.state if isinstance(value, VisualizationOutcome) else coerce_dock_model_visualization_state(value)
    )
    return attach_visualization_to_dock_model(
        model,
        state,
        mode=mode,
        fields_value=fields_value,
        strict=strict,
    )


def detach_visualization(
    model: Any,
    *,
    fields_value: Any = None,
    clear_files: bool = False,
    strict: bool = False,
) -> Any:
    """Remove attached visualization data."""

    return detach_visualization_from_dock_model(
        model,
        fields_value=fields_value,
        clear_files=clear_files,
        strict=strict,
    )


# 27.4. Accessors and summaries
# -----------------------------------------------------------------------------


def get_visualization_state(
    value: Any,
    *,
    fields_value: Any = None,
    required: bool = False,
) -> Optional[DockModelVisualizationState]:
    """Resolve a state from common visualization objects."""

    if isinstance(value, DockModelVisualizationState):
        return value
    if isinstance(value, VisualizationOutcome):
        return value.state
    if isinstance(value, DockModelVisualizationRun):
        return value.state
    if isinstance(value, DockModelVisualizationAttachment):
        return value.state
    if isinstance(value, VisualizationRequest):
        return plan_visualization(value)
    return get_dock_model_visualization(
        value,
        fields_value=fields_value,
        required=required,
    )


def get_visualization_plan(
    value: Any,
    *,
    fields_value: Any = None,
) -> VisualizationPlan:
    """Resolve a plan from common visualization objects."""

    if isinstance(value, VisualizationPlan):
        return value
    if isinstance(value, VisualizationRequest):
        return plan_visualization(value).plan
    state = get_visualization_state(value, fields_value=fields_value)
    if state is not None:
        return state.plan
    return coerce_visualization_plan(value)


def get_visualization_artifacts(
    value: Any,
    *,
    fields_value: Any = None,
) -> Mapping[str, str]:
    """Return generated visualization artifact paths."""

    if isinstance(value, VisualizationOutcome):
        return value.artifacts
    state = get_visualization_state(value, fields_value=fields_value)
    return MappingProxyType({}) if state is None else state.artifacts


def summarize_visualization(
    value: Any,
    *,
    fields_value: Any = None,
) -> Dict[str, Any]:
    """Return a compact summary for any high-level value."""

    if isinstance(value, VisualizationRequest):
        return {
            "source_id": value.source_id,
            "profile": value.config.profile.value,
            "layers": value.layers.enabled,
            "execution_mode": value.execution_mode.value,
            "integration_mode": value.integration_mode.value,
            "snapshots": 0 if value.snapshots is None else len(value.snapshots.enabled_requests),
            "command_export": value.command_export is not None,
            "fingerprint": value.fingerprint(),
        }
    if isinstance(value, VisualizationOutcome):
        return {
            "source_id": value.request.source_id,
            "successful": value.successful,
            "actions": len(value.plan.actions),
            "issues": len(value.issues),
            "warnings": len(value.warnings),
            "executed": value.execution is not None,
            "commands": None if value.commands is None else str(value.commands.path),
            "snapshots": 0 if value.snapshots is None else len(value.snapshots.results),
            "artifacts": dict(value.artifacts),
            "fingerprint": value.fingerprint(),
        }
    if isinstance(value, VisualizationPlan):
        return summarize_visualization_plan(value)
    state = get_visualization_state(value, fields_value=fields_value)
    if state is not None:
        return {
            "model_id": state.model_id,
            "profile": state.config.profile.value,
            "layers": tuple(state.metadata.get("layers", ())),
            "objects": len(state.specification.objects),
            "poses": len(state.specification.poses),
            "interactions": len(state.interactions.interactions),
            "actions": len(state.plan.actions),
            "executed": state.executed,
            "successful": state.successful,
            "artifacts": dict(state.artifacts),
            "fingerprint": state.fingerprint(),
        }
    return summarize_dock_model_visualization(value, fields_value=fields_value)


def available_visualization_profiles() -> Mapping[str, Mapping[str, Any]]:
    """Describe built-in profiles and convenience layers."""

    return MappingProxyType({
        profile.value: MappingProxyType({
            "description": describe_visualization_profile(profile),
            "layers": coerce_visualization_layers(None, profile=profile).enabled,
        })
        for profile in VisualizationProfile
    })


def convenience_visualization_to_dict(value: Any) -> Dict[str, Any]:
    """Serialize a request, outcome or state."""

    if isinstance(value, VisualizationRequest):
        return value.to_dict()
    if isinstance(value, VisualizationOutcome):
        return value.to_dict()
    if isinstance(value, DockModelVisualizationState):
        return value.to_dict()
    raise VisualizationSerializationError(
        f"Cannot serialize {type(value).__name__} as convenience visualization data."
    )


def convenience_visualization_to_json(
    value: Any,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize convenience-interface data as JSON."""

    return json.dumps(
        convenience_visualization_to_dict(value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


# 27.5. Stateful facade
# -----------------------------------------------------------------------------


class VisualizationFacade:
    """Reusable facade for high-level visualization workflows."""

    def __init__(
        self,
        *,
        config_value: Any = None,
        profile: Any = None,
        session: Any = None,
        backend: Optional[ChimeraXBackend] = None,
        fields_value: Any = None,
    ) -> None:
        self.config = resolve_visualization_config(config_value, profile=profile)
        self.session = session
        self.backend = backend
        self.fields = coerce_dock_model_visualization_fields(fields_value)

    def request(self, source: Any, **overrides: Any) -> VisualizationRequest:
        overrides.setdefault("config_value", self.config)
        return build_visualization_request(source, **overrides)

    def plan(self, source: Any, **overrides: Any) -> DockModelVisualizationState:
        return plan_visualization(self.request(source, **overrides))

    def preview(self, source: Any, **overrides: Any) -> VisualizationOutcome:
        return preview_visualization(
            self.request(source, **overrides),
            session=self.session,
            backend=self.backend,
        )

    def run(self, source: Any, **overrides: Any) -> VisualizationOutcome:
        return run_visualization(
            self.request(source, **overrides),
            session=self.session,
            backend=self.backend,
            fields_value=self.fields,
        )

    def export(
        self,
        source: Any,
        export: Any = None,
        *,
        filename: Optional[PathLike] = None,
        **overrides: Any,
    ) -> CommandExportResult:
        return export_visualization(
            self.request(source, **overrides),
            export,
            filename=filename,
        )

    def snapshots(
        self,
        source: Any,
        snapshots: Any,
        **overrides: Any,
    ) -> VisualizationOutcome:
        return snapshot_visualization(
            self.request(source, **overrides),
            snapshots,
            session=self.session,
            backend=self.backend,
        )

    def many(self, values: Iterable[Any], **overrides: Any) -> Tuple[VisualizationOutcome, ...]:
        return visualize_many(
            values,
            session=self.session,
            backend=self.backend,
            fields_value=self.fields,
            config_value=self.config,
            **overrides,
        )

    def detach(self, model: Any, *, clear_files: bool = False, strict: bool = False) -> Any:
        return detach_visualization(
            model,
            fields_value=self.fields,
            clear_files=clear_files,
            strict=strict,
        )

    def summary(self, value: Any) -> Dict[str, Any]:
        return summarize_visualization(value, fields_value=self.fields)


