# =============================================================================
# Section 28 — Validation and permissive mode
# =============================================================================

_VALIDATION_SCHEMA_VERSION: Final[str] = "1.0"
_DEFAULT_VALIDATION_MAX_ISSUES: Final[int] = 1000
_DEFAULT_VALIDATION_MAX_DEPTH: Final[int] = 8
_VALIDATION_FATAL_CODES: Final[FrozenSet[str]] = frozenset({
    "validator_crashed", "coercion_failed", "serialization_failed",
})


def _validation_text(
    value: Any,
    *,
    field_name: str,
    required: bool = False,
    maximum: int = 2048,
) -> Optional[str]:
    """Normalize bounded validation text."""

    if value is None:
        if required:
            raise VisualizationValidationError(f"{field_name} is required.")
        return None
    text = str(value).strip()
    if required and not text:
        raise VisualizationValidationError(f"{field_name} cannot be empty.")
    if len(text) > maximum:
        text = text[: maximum - 1] + "…"
    return text or None


def _validation_path(value: Any) -> str:
    """Normalize a diagnostic path."""

    text = str(value or "$").strip() or "$"
    if any(ord(character) < 32 for character in text):
        raise VisualizationValidationError("Validation paths cannot contain control characters.")
    return text[:1024]


def _validation_data(value: Any) -> Any:
    """Return JSON-safe validation data."""

    try:
        converted = _spec_data(value)
        json.dumps(converted, ensure_ascii=False, sort_keys=True)
        return converted
    except (TypeError, ValueError, OverflowError, RecursionError):
        return {
            "type": type(value).__name__,
            "repr": repr(value)[:2048],
        }


@dataclass(frozen=True, slots=True)
class VisualizationValidationPolicy(MolecularSpecMixin):
    """Validation and recovery policy."""

    mode: ValidationMode = ValidationMode.NORMAL
    error_handling: ErrorHandlingMode = ErrorHandlingMode.COLLECT
    minimum_level: ValidationIssueLevel = ValidationIssueLevel.INFO
    max_issues: int = _DEFAULT_VALIDATION_MAX_ISSUES
    max_depth: int = _DEFAULT_VALIDATION_MAX_DEPTH
    auto_correct: bool = False
    allow_partial: bool = True
    allow_unknown_types: bool = True
    recursive: bool = True
    validate_serialization: bool = True
    drop_missing_dependencies: bool = True
    disable_invalid_actions: bool = True
    break_dependency_cycles: bool = True
    emit_warnings: bool = False
    stop_on_fatal: bool = True

    def __post_init__(self) -> None:
        object.__setattr__(self, "mode", ValidationMode.parse(self.mode, default=ValidationMode.NORMAL))
        object.__setattr__(self, "error_handling", ErrorHandlingMode.parse(self.error_handling, default=ErrorHandlingMode.COLLECT))
        object.__setattr__(self, "minimum_level", ValidationIssueLevel.parse(self.minimum_level, default=ValidationIssueLevel.INFO))
        object.__setattr__(self, "max_issues", _bounded_int(self.max_issues, field_name="max_issues", minimum=1, maximum=100000))
        object.__setattr__(self, "max_depth", _bounded_int(self.max_depth, field_name="max_depth", minimum=0, maximum=64))
        for name in (
            "auto_correct", "allow_partial", "allow_unknown_types", "recursive",
            "validate_serialization", "drop_missing_dependencies",
            "disable_invalid_actions", "break_dependency_cycles",
            "emit_warnings", "stop_on_fatal",
        ):
            object.__setattr__(self, name, _coerce_bool(getattr(self, name), field_name=name))

    @classmethod
    def strict(cls, **overrides: Any) -> "VisualizationValidationPolicy":
        """Return a strict policy."""

        values = {
            "mode": ValidationMode.STRICT,
            "error_handling": ErrorHandlingMode.RAISE,
            "auto_correct": False,
            "allow_partial": False,
            "allow_unknown_types": False,
            "emit_warnings": False,
        }
        values.update(overrides)
        return cls(**values)

    @classmethod
    def permissive(cls, **overrides: Any) -> "VisualizationValidationPolicy":
        """Return a recovery-oriented policy."""

        values = {
            "mode": ValidationMode.PERMISSIVE,
            "error_handling": ErrorHandlingMode.COLLECT,
            "auto_correct": True,
            "allow_partial": True,
            "allow_unknown_types": True,
            "emit_warnings": True,
        }
        values.update(overrides)
        return cls(**values)


@dataclass(frozen=True, slots=True)
class VisualizationValidationIssue(MolecularSpecMixin):
    """One normalized validation issue."""

    level: ValidationIssueLevel
    code: str
    message: str
    path: str = "$"
    action_id: Optional[str] = None
    recoverable: bool = True
    corrected: bool = False
    correction: Optional[str] = None
    context: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "level", ValidationIssueLevel.parse(self.level, default=ValidationIssueLevel.ERROR))
        object.__setattr__(self, "code", _plan_identifier(self.code, field_name="validation code"))
        object.__setattr__(self, "message", _validation_text(self.message, field_name="message", required=True) or "Validation issue")
        object.__setattr__(self, "path", _validation_path(self.path))
        object.__setattr__(self, "action_id", None if self.action_id is None else _plan_identifier(self.action_id, field_name="action_id"))
        object.__setattr__(self, "recoverable", bool(self.recoverable))
        object.__setattr__(self, "corrected", bool(self.corrected))
        object.__setattr__(self, "correction", _validation_text(self.correction, field_name="correction"))
        object.__setattr__(self, "context", _plan_mapping(self.context, field_name="context"))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "level": self.level.value,
            "code": self.code,
            "message": self.message,
            "path": self.path,
            "action_id": self.action_id,
            "recoverable": self.recoverable,
            "corrected": self.corrected,
            "correction": self.correction,
            "context": _validation_data(self.context),
        }

    @property
    def is_error(self) -> bool:
        return self.level >= ValidationIssueLevel.ERROR

    @property
    def is_fatal(self) -> bool:
        return self.level >= ValidationIssueLevel.FATAL


@dataclass(frozen=True, slots=True)
class VisualizationCorrection(MolecularSpecMixin):
    """One applied permissive correction."""

    code: str
    message: str
    path: str = "$"
    action_id: Optional[str] = None
    before: Any = None
    after: Any = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "code", _plan_identifier(self.code, field_name="correction code"))
        object.__setattr__(self, "message", _validation_text(self.message, field_name="message", required=True) or "Correction applied")
        object.__setattr__(self, "path", _validation_path(self.path))
        object.__setattr__(self, "action_id", None if self.action_id is None else _plan_identifier(self.action_id, field_name="action_id"))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "code": self.code,
            "message": self.message,
            "path": self.path,
            "action_id": self.action_id,
            "before": _validation_data(self.before),
            "after": _validation_data(self.after),
        }


@dataclass(frozen=True, slots=True)
class VisualizationValidationReport(MolecularSpecMixin):
    """Validation outcome and applied corrections."""

    subject_type: str
    mode: ValidationMode
    issues: Tuple[VisualizationValidationIssue, ...] = ()
    corrections: Tuple[VisualizationCorrection, ...] = ()
    checked_count: int = 1
    skipped_count: int = 0
    duration_ms: float = 0.0
    schema_version: str = _VALIDATION_SCHEMA_VERSION
    metadata: Mapping[str, Any] = field(default_factory=dict, compare=False, hash=False, repr=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "subject_type", _validation_text(self.subject_type, field_name="subject_type", required=True, maximum=256) or "unknown")
        object.__setattr__(self, "mode", ValidationMode.parse(self.mode, default=ValidationMode.NORMAL))
        object.__setattr__(self, "issues", tuple(coerce_validation_issue(item) for item in self.issues))
        object.__setattr__(self, "corrections", tuple(coerce_visualization_correction(item) for item in self.corrections))
        object.__setattr__(self, "checked_count", _bounded_int(self.checked_count, field_name="checked_count", minimum=0, maximum=100000000))
        object.__setattr__(self, "skipped_count", _bounded_int(self.skipped_count, field_name="skipped_count", minimum=0, maximum=100000000))
        object.__setattr__(self, "duration_ms", _bounded_float(self.duration_ms, field_name="duration_ms", minimum=0.0))
        object.__setattr__(self, "schema_version", _validation_text(self.schema_version, field_name="schema_version", required=True, maximum=32) or _VALIDATION_SCHEMA_VERSION)
        object.__setattr__(self, "metadata", _plan_mapping(self.metadata, field_name="metadata"))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "subject_type": self.subject_type,
            "mode": self.mode.value,
            "issues": [issue.to_dict() for issue in self.issues],
            "corrections": [correction.to_dict() for correction in self.corrections],
            "checked_count": self.checked_count,
            "skipped_count": self.skipped_count,
            "duration_ms": self.duration_ms,
            "schema_version": self.schema_version,
            "metadata": _validation_data(self.metadata),
        }

    @property
    def errors(self) -> Tuple[VisualizationValidationIssue, ...]:
        return tuple(issue for issue in self.issues if issue.level >= ValidationIssueLevel.ERROR)

    @property
    def warnings(self) -> Tuple[VisualizationValidationIssue, ...]:
        return tuple(issue for issue in self.issues if issue.level is ValidationIssueLevel.WARNING)

    @property
    def fatals(self) -> Tuple[VisualizationValidationIssue, ...]:
        return tuple(issue for issue in self.issues if issue.level >= ValidationIssueLevel.FATAL)

    @property
    def valid(self) -> bool:
        return not self.errors

    @property
    def accepted(self) -> bool:
        return self.valid or (self.mode is ValidationMode.PERMISSIVE and not self.fatals)

    @property
    def corrected(self) -> bool:
        return bool(self.corrections)

    @property
    def highest_level(self) -> Optional[ValidationIssueLevel]:
        return max((issue.level for issue in self.issues), default=None)

    def count_by_level(self) -> Mapping[str, int]:
        counts = Counter(issue.level.name.lower() for issue in self.issues)
        return MappingProxyType(dict(sorted(counts.items())))

    def count_by_code(self) -> Mapping[str, int]:
        return MappingProxyType(dict(sorted(Counter(issue.code for issue in self.issues).items())))

    def raise_for_errors(self) -> None:
        if self.errors:
            raise VisualizationValidationError(
                "Visualization validation failed.",
                field_name="validation",
                expected="No error-level issues.",
                context={"report": self.to_dict()},
            )


@dataclass(frozen=True, slots=True)
class VisualizationValidationResult:
    """Validated value and report."""

    value: Any
    report: VisualizationValidationReport

    @property
    def valid(self) -> bool:
        return self.report.valid

    @property
    def accepted(self) -> bool:
        return self.report.accepted

    def to_dict(self, *, include_value: bool = True) -> Dict[str, Any]:
        payload = {"report": self.report.to_dict()}
        if include_value:
            payload["value"] = _validation_data(self.value)
        return payload

    def to_json(self, *, indent: Optional[int] = 2, include_value: bool = True) -> str:
        return json.dumps(self.to_dict(include_value=include_value), ensure_ascii=False, sort_keys=True, indent=indent)

    def fingerprint(self) -> str:
        payload = json.dumps(self.to_dict(), ensure_ascii=True, sort_keys=True, separators=(",", ":"))
        return sha256(payload.encode(VISUALIZATION_TEXT_ENCODING)).hexdigest()


@dataclass(frozen=True, slots=True)
class PermissiveCallResult:
    """Value or fallback returned by a guarded call."""

    value: Any = None
    error: Optional[VisualizationError] = None
    used_fallback: bool = False

    @property
    def success(self) -> bool:
        return self.error is None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "success": self.success,
            "used_fallback": self.used_fallback,
            "value": _validation_data(self.value),
            "error": None if self.error is None else self.error.to_dict(),
        }


ValidationFunction: TypeAlias = Callable[[Any, Mapping[str, Any]], Iterable[Any]]
CorrectionFunction: TypeAlias = Callable[
    [Any, VisualizationValidationPolicy, Mapping[str, Any]],
    Tuple[Any, Tuple[VisualizationCorrection, ...]],
]


@dataclass(frozen=True, slots=True)
class VisualizationValidatorEntry:
    """Registered validator and optional corrector."""

    name: str
    value_type: type
    validator: ValidationFunction
    corrector: Optional[CorrectionFunction] = None


class VisualizationValidatorRegistry:
    """Type-based validator registry."""

    def __init__(self) -> None:
        self._entries: Dict[type, VisualizationValidatorEntry] = {}

    def register(
        self,
        value_type: type,
        validator: ValidationFunction,
        *,
        corrector: Optional[CorrectionFunction] = None,
        name: Optional[str] = None,
        replace_existing: bool = False,
    ) -> VisualizationValidatorEntry:
        if not isinstance(value_type, type):
            raise VisualizationValidationError("value_type must be a type.")
        if not callable(validator):
            raise VisualizationValidationError("validator must be callable.")
        if corrector is not None and not callable(corrector):
            raise VisualizationValidationError("corrector must be callable.")
        if value_type in self._entries and not replace_existing:
            raise VisualizationValidationError(
                f"A validator is already registered for {value_type.__name__}."
            )
        entry = VisualizationValidatorEntry(
            _validation_text(name or value_type.__name__, field_name="name", required=True, maximum=128) or value_type.__name__,
            value_type,
            validator,
            corrector,
        )
        self._entries[value_type] = entry
        return entry

    def unregister(self, value_type: type) -> Optional[VisualizationValidatorEntry]:
        return self._entries.pop(value_type, None)

    def resolve(self, value: Any) -> Optional[VisualizationValidatorEntry]:
        for value_type in type(value).__mro__:
            entry = self._entries.get(value_type)
            if entry is not None:
                return entry
        return None

    def entries(self) -> Tuple[VisualizationValidatorEntry, ...]:
        return tuple(sorted(self._entries.values(), key=lambda item: item.name.lower()))

    def copy(self) -> "VisualizationValidatorRegistry":
        registry = type(self)()
        registry._entries.update(self._entries)
        return registry


class VisualizationIssueCollector:
    """Mutable issue collector for custom workflows."""

    def __init__(
        self,
        policy: Any = None,
        *,
        subject_type: str = "custom",
    ) -> None:
        self.policy = coerce_validation_policy(policy)
        self.subject_type = str(subject_type)
        self.issues: List[VisualizationValidationIssue] = []
        self.corrections: List[VisualizationCorrection] = []
        self.checked_count = 0
        self.skipped_count = 0

    def add(self, issue: Any, *, path: str = "$") -> VisualizationValidationIssue:
        normalized = coerce_validation_issue(issue, path=path)
        if normalized.level >= self.policy.minimum_level and len(self.issues) < self.policy.max_issues:
            self.issues.append(normalized)
            if self.policy.emit_warnings and normalized.level is ValidationIssueLevel.WARNING:
                emit_visualization_warning(normalized.message, category=VisualizationDataWarning, stacklevel=3)
        return normalized

    def extend(self, issues: Iterable[Any], *, path: str = "$") -> None:
        for issue in issues:
            self.add(issue, path=path)
            if len(self.issues) >= self.policy.max_issues:
                break

    def correct(self, correction: Any) -> VisualizationCorrection:
        normalized = coerce_visualization_correction(correction)
        self.corrections.append(normalized)
        if self.policy.emit_warnings:
            emit_visualization_warning(normalized.message, category=VisualizationFallbackWarning, stacklevel=3)
        return normalized

    @contextmanager
    def capture(
        self,
        *,
        path: str = "$",
        code: str = "validation_exception",
        level: Any = ValidationIssueLevel.ERROR,
    ) -> Iterator[None]:
        try:
            yield
        except Exception as exc:
            self.add(VisualizationValidationIssue(
                level=level,
                code=code,
                message=str(exc) or type(exc).__name__,
                path=path,
                recoverable=not isinstance(exc, (KeyboardInterrupt, SystemExit, MemoryError)),
                context={"exception_type": type(exc).__name__},
            ))
            if self.policy.error_handling is ErrorHandlingMode.RAISE:
                raise

    def report(self, *, duration_ms: float = 0.0, metadata: Optional[Mapping[str, Any]] = None) -> VisualizationValidationReport:
        return VisualizationValidationReport(
            subject_type=self.subject_type,
            mode=self.policy.mode,
            issues=tuple(self.issues),
            corrections=tuple(self.corrections),
            checked_count=self.checked_count,
            skipped_count=self.skipped_count,
            duration_ms=duration_ms,
            metadata=metadata or {},
        )


def coerce_validation_policy(value: Any = None, **overrides: Any) -> VisualizationValidationPolicy:
    """Coerce validation policy input."""

    if value is None:
        policy = VisualizationValidationPolicy()
    elif isinstance(value, VisualizationValidationPolicy):
        policy = value
    elif isinstance(value, ValidationMode):
        policy = VisualizationValidationPolicy(mode=value)
    elif isinstance(value, str):
        mode = ValidationMode.parse(value, default=ValidationMode.NORMAL)
        policy = VisualizationValidationPolicy.permissive() if mode is ValidationMode.PERMISSIVE else (
            VisualizationValidationPolicy.strict() if mode is ValidationMode.STRICT else VisualizationValidationPolicy(mode=mode)
        )
    elif isinstance(value, Mapping):
        policy = VisualizationValidationPolicy(**dict(value))
    else:
        raise VisualizationValidationError(
            "Unsupported validation policy input.",
            value=type(value).__name__,
        )
    return replace(policy, **overrides) if overrides else policy


def coerce_validation_issue(value: Any, *, path: str = "$") -> VisualizationValidationIssue:
    """Coerce one diagnostic issue."""

    if isinstance(value, VisualizationValidationIssue):
        return value if value.path != "$" or path == "$" else replace(value, path=path)
    if isinstance(value, PlanValidationIssue):
        return VisualizationValidationIssue(
            level=value.level,
            code=value.code,
            message=value.message,
            path=path,
            action_id=value.action_id,
            context=value.context,
        )
    if isinstance(value, VisualizationError):
        level = ValidationIssueLevel.FATAL if value.severity == ERROR_SEVERITY_FATAL else ValidationIssueLevel.ERROR
        return VisualizationValidationIssue(
            level=level,
            code=value.code,
            message=value.message,
            path=path,
            recoverable=value.recoverable,
            context=value.context,
        )
    if isinstance(value, BaseException):
        return coerce_validation_issue(wrap_visualization_error(value), path=path)
    if isinstance(value, Mapping):
        data = dict(value)
        data.setdefault("path", path)
        return VisualizationValidationIssue(**data)
    return VisualizationValidationIssue(
        level=ValidationIssueLevel.WARNING,
        code="validation_message",
        message=str(value),
        path=path,
    )


def coerce_visualization_correction(value: Any) -> VisualizationCorrection:
    """Coerce one correction record."""

    if isinstance(value, VisualizationCorrection):
        return value
    if isinstance(value, Mapping):
        return VisualizationCorrection(**dict(value))
    raise VisualizationValidationError(
        "Unsupported visualization correction.",
        value=type(value).__name__,
    )


def _string_issues(values: Iterable[str], *, code: str, path: str = "$") -> Tuple[VisualizationValidationIssue, ...]:
    return tuple(
        VisualizationValidationIssue(
            ValidationIssueLevel.ERROR,
            code,
            str(message),
            path=path,
        )
        for message in values
    )


def _adapt_plan_validator(function: Callable[..., Iterable[Any]]) -> ValidationFunction:
    def validator(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
        config_value = context.get("config_value")
        try:
            signature = inspect.signature(function)
            if "config_value" in signature.parameters:
                return function(value, config_value=config_value)
        except (TypeError, ValueError):
            pass
        return function(value)
    return validator


def _validate_config_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return _string_issues(validate_visualization_config(value), code="config_invalid", path="$.config")


def _validate_path_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return _string_issues(validate_molecular_path(value), code="molecular_path_invalid")


def _validate_structure_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return _string_issues(validate_structure_spec(value), code="structure_invalid")


def _validate_selection_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    expression = value.expression if isinstance(value, MolecularSelection) else value
    return _string_issues(validate_selection_expression(expression, strict=False), code="selection_invalid")


def _validate_script_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return validate_command_script(value)


def _validate_export_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return validate_command_export(value)


def _validate_backend_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    return _string_issues(validate_chimerax_backend(value), code="backend_invalid")


def _validate_state_entry(value: Any, context: Mapping[str, Any]) -> Iterable[Any]:
    state = coerce_dock_model_visualization_state(value)
    issues: List[Any] = list(validate_visualization_plan(state.plan))
    if not state.specification.objects and not state.specification.poses:
        issues.append(VisualizationValidationIssue(
            ValidationIssueLevel.WARNING,
            "dock_model_specification_empty",
            "Visualization state has no molecular objects or poses.",
            path="$.specification",
        ))
    return issues


def _find_plan_cycle(actions: Sequence[VisualizationAction]) -> Optional[Tuple[str, str]]:
    graph = {action.action_id: tuple(action.depends_on) for action in actions}
    state: Dict[str, int] = {}

    def visit(node: str) -> Optional[Tuple[str, str]]:
        state[node] = 1
        for dependency in graph.get(node, ()):
            if dependency not in graph:
                continue
            if state.get(dependency, 0) == 1:
                return node, dependency
            if state.get(dependency, 0) == 0:
                edge = visit(dependency)
                if edge is not None:
                    return edge
        state[node] = 2
        return None

    for action in actions:
        if state.get(action.action_id, 0) == 0:
            edge = visit(action.action_id)
            if edge is not None:
                return edge
    return None


def repair_visualization_plan(
    plan: Any,
    policy: Any = None,
) -> Tuple[VisualizationPlan, Tuple[VisualizationCorrection, ...]]:
    """Apply deterministic safe plan repairs."""

    policy_value = coerce_validation_policy(policy or VisualizationValidationPolicy.permissive())
    value = coerce_visualization_plan(plan)
    actions = list(value.actions)
    corrections: List[VisualizationCorrection] = []
    known = {action.action_id for action in actions}

    if policy_value.drop_missing_dependencies:
        updated: List[VisualizationAction] = []
        for action in actions:
            dependencies = tuple(item for item in action.depends_on if item in known)
            if dependencies != action.depends_on:
                corrections.append(VisualizationCorrection(
                    "drop_missing_dependencies",
                    "Removed missing action dependencies.",
                    path=f"$.actions[{action.action_id}].depends_on",
                    action_id=action.action_id,
                    before=action.depends_on,
                    after=dependencies,
                ))
                action = replace(action, depends_on=dependencies)
            updated.append(action)
        actions = updated

    if policy_value.disable_invalid_actions:
        action_map = {action.action_id: action for action in actions}
        updated = []
        for action in actions:
            disabled = tuple(item for item in action.depends_on if not action_map[item].enabled)
            if action.enabled and disabled:
                corrections.append(VisualizationCorrection(
                    "disable_unmet_action",
                    "Disabled an action with disabled prerequisites.",
                    path=f"$.actions[{action.action_id}].enabled",
                    action_id=action.action_id,
                    before=True,
                    after=False,
                ))
                action = replace(action, enabled=False)
            updated.append(action)
        actions = updated

    if policy_value.break_dependency_cycles:
        for _ in range(len(actions)):
            edge = _find_plan_cycle(actions)
            if edge is None:
                break
            action_id, dependency = edge
            updated = []
            for action in actions:
                if action.action_id == action_id:
                    dependencies = tuple(item for item in action.depends_on if item != dependency)
                    corrections.append(VisualizationCorrection(
                        "break_dependency_cycle",
                        "Removed one dependency edge to break a cycle.",
                        path=f"$.actions[{action_id}].depends_on",
                        action_id=action_id,
                        before=action.depends_on,
                        after=dependencies,
                    ))
                    action = replace(action, depends_on=dependencies)
                updated.append(action)
            actions = updated

    repaired = replace(value, actions=tuple(actions))
    try:
        repaired = replace(repaired, actions=resolve_plan_order(repaired))
    except VisualizationPlanError:
        pass
    return repaired, tuple(corrections)


def repair_visualization_config(
    config_value: Any,
    policy: Any = None,
) -> Tuple[VisualizationConfig, Tuple[VisualizationCorrection, ...]]:
    """Repair safe cross-field configuration conflicts."""

    value = resolve_visualization_config(config_value)
    corrections: List[VisualizationCorrection] = []
    snapshot = value.snapshot
    backend = value.backend
    multipose = value.multipose
    scene = value.scene

    if snapshot.transparent and snapshot.format is SnapshotFormat.JPEG:
        repaired = snapshot.copy_with(format=SnapshotFormat.PNG, filename=str(Path(snapshot.filename).with_suffix(".png")))
        corrections.append(VisualizationCorrection(
            "replace_transparent_jpeg",
            "Changed transparent JPEG output to PNG.",
            path="$.snapshot.format",
            before=snapshot.to_dict(),
            after=repaired.to_dict(),
        ))
        snapshot = repaired
    if backend.execution_mode is ExecutionMode.IMMEDIATE and backend.kind is BackendKind.NONE:
        repaired = backend.copy_with(execution_mode=ExecutionMode.DEFERRED)
        corrections.append(VisualizationCorrection(
            "defer_missing_backend",
            "Changed immediate execution to deferred because no backend is configured.",
            path="$.backend.execution_mode",
            before=backend.execution_mode.value,
            after=repaired.execution_mode.value,
        ))
        backend = repaired
    if multipose.complementarity_set_size > multipose.max_visible_poses:
        repaired = multipose.copy_with(complementarity_set_size=multipose.max_visible_poses)
        corrections.append(VisualizationCorrection(
            "clamp_complementarity_size",
            "Clamped complementarity set size to the visible-pose limit.",
            path="$.multipose.complementarity_set_size",
            before=multipose.complementarity_set_size,
            after=repaired.complementarity_set_size,
        ))
        multipose = repaired
    if scene.show_interactions and value.interactions.max_count == 0:
        repaired = scene.copy_with(show_interactions=False)
        corrections.append(VisualizationCorrection(
            "disable_empty_interactions",
            "Disabled interaction display because max_count is zero.",
            path="$.scene.show_interactions",
            before=True,
            after=False,
        ))
        scene = repaired
    return value.copy_with(snapshot=snapshot, backend=backend, multipose=multipose, scene=scene), tuple(corrections)


def _correct_plan_entry(
    value: Any,
    policy: VisualizationValidationPolicy,
    context: Mapping[str, Any],
) -> Tuple[Any, Tuple[VisualizationCorrection, ...]]:
    return repair_visualization_plan(value, policy)


def _correct_config_entry(
    value: Any,
    policy: VisualizationValidationPolicy,
    context: Mapping[str, Any],
) -> Tuple[Any, Tuple[VisualizationCorrection, ...]]:
    return repair_visualization_config(value, policy)


def _register_builtin_visualization_validators(registry: VisualizationValidatorRegistry) -> None:
    entries: Tuple[Tuple[type, ValidationFunction, Optional[CorrectionFunction]], ...] = (
        (VisualizationConfig, _validate_config_entry, _correct_config_entry),
        (MolecularPathSpec, _validate_path_entry, None),
        (StructureSpec, _validate_structure_entry, None),
        (MolecularSelection, _validate_selection_entry, None),
        (VisualizationAction, _adapt_plan_validator(validate_visualization_action), None),
        (VisualizationPlan, _adapt_plan_validator(validate_visualization_plan), _correct_plan_entry),
        (ScenePreparationSpec, _adapt_plan_validator(validate_scene_preparation), None),
        (ReceptorVisualizationSpec, _adapt_plan_validator(validate_receptor_visualization), None),
        (LigandVisualizationSpec, _adapt_plan_validator(validate_ligand_visualization), None),
        (InteractionVisualizationSpec, _adapt_plan_validator(validate_interaction_visualization), None),
        (VirtualPointVisualizationSpec, _adapt_plan_validator(validate_virtual_points), None),
        (InvolvedResidueVisualizationSpec, _adapt_plan_validator(validate_involved_residues), None),
        (HotspotVisualizationSpec, _adapt_plan_validator(validate_hotspots), None),
        (VisualScoringSpec, _adapt_plan_validator(validate_visual_scoring), None),
        (MultiposeVisualizationSpec, _adapt_plan_validator(validate_multipose_visualization), None),
        (ConsensusVisualizationSpec, _adapt_plan_validator(validate_consensus_visualization), None),
        (ComplementarityVisualizationSpec, _adapt_plan_validator(validate_complementarity), None),
        (AnnotationVisualizationSpec, _adapt_plan_validator(validate_annotations), None),
        (CameraFramingSpec, _adapt_plan_validator(validate_camera_framing), None),
        (SnapshotRequestSpec, _adapt_plan_validator(validate_snapshot_request), None),
        (SnapshotCollection, _adapt_plan_validator(validate_snapshot_collection), None),
        (CommandScriptSpec, _validate_script_entry, None),
        (CommandExportSpec, _validate_export_entry, None),
        (ChimeraXBackend, _validate_backend_entry, None),
        (DockModelVisualizationState, _validate_state_entry, None),
    )
    for value_type, validator, corrector in entries:
        registry.register(value_type, validator, corrector=corrector)


VISUALIZATION_VALIDATOR_REGISTRY: Final[VisualizationValidatorRegistry] = VisualizationValidatorRegistry()
_register_builtin_visualization_validators(VISUALIZATION_VALIDATOR_REGISTRY)


def register_visualization_validator(
    value_type: type,
    validator: ValidationFunction,
    *,
    corrector: Optional[CorrectionFunction] = None,
    name: Optional[str] = None,
    replace_existing: bool = False,
) -> VisualizationValidatorEntry:
    """Register a custom validator."""

    return VISUALIZATION_VALIDATOR_REGISTRY.register(
        value_type,
        validator,
        corrector=corrector,
        name=name,
        replace_existing=replace_existing,
    )


def _validate_serialization(value: Any) -> Tuple[VisualizationValidationIssue, ...]:
    try:
        json.dumps(_spec_data(value), ensure_ascii=False, sort_keys=True)
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        return (VisualizationValidationIssue(
            ValidationIssueLevel.ERROR,
            "serialization_failed",
            f"Value is not JSON serializable: {exc}",
            recoverable=True,
            context={"value_type": type(value).__name__},
        ),)
    return ()


def _recursive_children(value: Any) -> Iterator[Tuple[str, Any, Any]]:
    if isinstance(value, Mapping):
        for key, item in value.items():
            yield f"[{key!r}]", key, item
    elif isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        for index, item in enumerate(value):
            yield f"[{index}]", index, item


def validate_visualization(
    value: Any,
    policy: Any = None,
    *,
    registry: Optional[VisualizationValidatorRegistry] = None,
    config_value: Any = None,
    path: str = "$",
    _depth: int = 0,
) -> VisualizationValidationResult:
    """Validate and optionally repair one visualization value."""

    started = datetime.now(timezone.utc)
    policy_value = coerce_validation_policy(policy)
    registry_value = registry or VISUALIZATION_VALIDATOR_REGISTRY
    collector = VisualizationIssueCollector(policy_value, subject_type=type(value).__name__)
    collector.checked_count = 1
    normalized = value
    context = MappingProxyType({"config_value": config_value, "path": path})

    if policy_value.mode is ValidationMode.DISABLED:
        collector.skipped_count = 1
        return VisualizationValidationResult(value, collector.report(metadata={"disabled": True}))

    entry = registry_value.resolve(value)
    if entry is not None:
        if policy_value.auto_correct and entry.corrector is not None:
            try:
                normalized, corrections = entry.corrector(value, policy_value, context)
                for correction in corrections:
                    collector.correct(correction)
            except Exception as exc:
                collector.add(VisualizationValidationIssue(
                    ValidationIssueLevel.ERROR,
                    "correction_failed",
                    str(exc) or type(exc).__name__,
                    path=path,
                    context={"validator": entry.name, "exception_type": type(exc).__name__},
                ))
        try:
            collector.extend(entry.validator(normalized, context), path=path)
        except Exception as exc:
            collector.add(VisualizationValidationIssue(
                ValidationIssueLevel.FATAL,
                "validator_crashed",
                str(exc) or type(exc).__name__,
                path=path,
                recoverable=False,
                context={"validator": entry.name, "exception_type": type(exc).__name__},
            ))
    elif policy_value.recursive and _depth < policy_value.max_depth and isinstance(value, (Mapping, Sequence)) and not isinstance(value, (str, bytes, bytearray)):
        mapping_items = dict(value) if isinstance(value, Mapping) else None
        sequence_items = list(value) if mapping_items is None else None
        changed = False
        for suffix, key, child in _recursive_children(value):
            result = validate_visualization(
                child,
                policy_value,
                registry=registry_value,
                config_value=config_value,
                path=f"{path}{suffix}",
                _depth=_depth + 1,
            )
            collector.extend(result.report.issues)
            collector.corrections.extend(result.report.corrections)
            collector.checked_count += result.report.checked_count
            collector.skipped_count += result.report.skipped_count
            if result.value is not child:
                changed = True
                if mapping_items is not None:
                    mapping_items[key] = result.value
                elif sequence_items is not None:
                    sequence_items[int(key)] = result.value
            if policy_value.stop_on_fatal and result.report.fatals:
                break
        if changed:
            if mapping_items is not None:
                normalized = mapping_items
            elif isinstance(value, tuple):
                normalized = tuple(sequence_items or ())
            else:
                normalized = sequence_items or []
    elif not policy_value.allow_unknown_types:
        collector.add(VisualizationValidationIssue(
            ValidationIssueLevel.ERROR,
            "validator_unavailable",
            f"No validator is registered for {type(value).__name__}.",
            path=path,
            recoverable=True,
        ))

    if policy_value.validate_serialization and len(collector.issues) < policy_value.max_issues:
        collector.extend(_validate_serialization(normalized), path=path)

    elapsed = (datetime.now(timezone.utc) - started).total_seconds() * 1000.0
    report = collector.report(
        duration_ms=elapsed,
        metadata={"path": path, "validator": None if entry is None else entry.name},
    )
    _apply_validation_policy(report, policy_value)
    return VisualizationValidationResult(normalized, report)


def _apply_validation_policy(
    report: VisualizationValidationReport,
    policy: VisualizationValidationPolicy,
) -> None:
    if policy.error_handling is ErrorHandlingMode.RAISE and report.errors:
        report.raise_for_errors()
    if policy.error_handling is ErrorHandlingMode.WARN:
        for issue in report.errors:
            emit_visualization_warning(issue.message, category=VisualizationDataWarning, stacklevel=3)


def validate_visualizations(
    values: Iterable[Any],
    policy: Any = None,
    *,
    registry: Optional[VisualizationValidatorRegistry] = None,
    config_value: Any = None,
) -> Tuple[VisualizationValidationResult, ...]:
    """Validate multiple values."""

    policy_value = coerce_validation_policy(policy)
    results: List[VisualizationValidationResult] = []
    for index, value in enumerate(values):
        result = validate_visualization(
            value,
            policy_value,
            registry=registry,
            config_value=config_value,
            path=f"$[{index}]",
        )
        results.append(result)
        if policy_value.stop_on_fatal and result.report.fatals:
            break
    return tuple(results)


def is_visualization_valid(value: Any, policy: Any = None, **kwargs: Any) -> bool:
    """Return whether validation produced no errors."""

    try:
        return validate_visualization(value, coerce_validation_policy(policy, error_handling=ErrorHandlingMode.COLLECT), **kwargs).report.valid
    except VisualizationError:
        return False


def validate_visualization_or_raise(value: Any, policy: Any = None, **kwargs: Any) -> Any:
    """Validate and return the normalized value or raise."""

    policy_value = coerce_validation_policy(policy or VisualizationValidationPolicy.strict(), error_handling=ErrorHandlingMode.RAISE)
    return validate_visualization(value, policy_value, **kwargs).value


def permissive_visualization_call(
    function: Callable[..., T],
    *args: Any,
    fallback: Any = None,
    policy: Any = None,
    context: Optional[Mapping[str, Any]] = None,
    **kwargs: Any,
) -> PermissiveCallResult:
    """Execute a callable and return a safe fallback on failure."""

    policy_value = coerce_validation_policy(policy or VisualizationValidationPolicy.permissive())
    try:
        return PermissiveCallResult(function(*args, **kwargs))
    except Exception as exc:
        wrapped = wrap_visualization_error(
            exc,
            context=context,
            recoverable=True,
            severity=ERROR_SEVERITY_WARNING if policy_value.mode is ValidationMode.PERMISSIVE else ERROR_SEVERITY_ERROR,
        )
        if policy_value.error_handling is ErrorHandlingMode.RAISE:
            raise wrapped from exc
        if policy_value.error_handling is ErrorHandlingMode.WARN or policy_value.emit_warnings:
            emit_visualization_warning(str(wrapped), category=VisualizationFallbackWarning, stacklevel=2)
        fallback_value = fallback() if callable(fallback) else fallback
        return PermissiveCallResult(fallback_value, wrapped, True)


def summarize_validation(value: Any) -> Dict[str, Any]:
    """Return a compact validation summary."""

    report = value.report if isinstance(value, VisualizationValidationResult) else value
    if not isinstance(report, VisualizationValidationReport):
        report = validate_visualization(value).report
    return {
        "subject_type": report.subject_type,
        "mode": report.mode.value,
        "valid": report.valid,
        "accepted": report.accepted,
        "corrected": report.corrected,
        "issue_count": len(report.issues),
        "correction_count": len(report.corrections),
        "checked_count": report.checked_count,
        "skipped_count": report.skipped_count,
        "highest_level": None if report.highest_level is None else report.highest_level.name.lower(),
        "by_level": dict(report.count_by_level()),
        "by_code": dict(report.count_by_code()),
        "duration_ms": report.duration_ms,
    }


def validation_to_dict(value: Any, *, include_value: bool = True) -> Dict[str, Any]:
    """Serialize validation data."""

    if isinstance(value, VisualizationValidationResult):
        return value.to_dict(include_value=include_value)
    if isinstance(value, VisualizationValidationReport):
        return value.to_dict()
    if isinstance(value, VisualizationValidationIssue):
        return value.to_dict()
    if isinstance(value, VisualizationCorrection):
        return value.to_dict()
    return validate_visualization(value).to_dict(include_value=include_value)


def validation_to_json(
    value: Any,
    *,
    indent: Optional[int] = 2,
    include_value: bool = True,
) -> str:
    """Serialize validation data as JSON."""

    return json.dumps(
        validation_to_dict(value, include_value=include_value),
        ensure_ascii=False,
        sort_keys=True,
        indent=indent,
    )


def describe_visualization_validators(
    registry: Optional[VisualizationValidatorRegistry] = None,
) -> Tuple[Dict[str, Any], ...]:
    """Describe registered validators."""

    return tuple({
        "name": entry.name,
        "type": entry.value_type.__name__,
        "module": entry.value_type.__module__,
        "has_corrector": entry.corrector is not None,
    } for entry in (registry or VISUALIZATION_VALIDATOR_REGISTRY).entries())


