"""Runtime inspection, API inventory and capability diagnostics."""


@dataclass(frozen=True, slots=True)
class PublicSymbolInfo:
    """Describe one public symbol."""

    name: str
    kind: str
    module: str
    qualified_name: str
    signature: Optional[str] = None
    bases: Tuple[str, ...] = ()
    fields: Tuple[str, ...] = ()
    enum_values: Tuple[str, ...] = ()
    doc_summary: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "kind": self.kind,
            "module": self.module,
            "qualified_name": self.qualified_name,
            "signature": self.signature,
            "bases": list(self.bases),
            "fields": list(self.fields),
            "enum_values": list(self.enum_values),
            "doc_summary": self.doc_summary,
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "PublicSymbolInfo":
        return cls(
            name=str(data.get("name", "")),
            kind=str(data.get("kind", "unknown")),
            module=str(data.get("module", "")),
            qualified_name=str(data.get("qualified_name", data.get("name", ""))),
            signature=_optional_text(data.get("signature")),
            bases=tuple(str(item) for item in data.get("bases", ())),
            fields=tuple(str(item) for item in data.get("fields", ())),
            enum_values=tuple(str(item) for item in data.get("enum_values", ())),
            doc_summary=_optional_text(data.get("doc_summary")),
        )


