@dataclass(frozen=True, slots=True)
class VisualizationModuleInfo:
    """Describe the visualization module."""

    name: str
    description: str
    version: str
    author: str
    license: str
    status: str
    file: Optional[str]
    python_version: str
    platform: str
    optimized: int
    public_count: int
    symbol_counts: Mapping[str, int]
    capabilities: Tuple[ModuleCapabilityInfo, ...]
    sections: Tuple[int, ...]
    generated_at: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description,
            "version": self.version,
            "author": self.author,
            "license": self.license,
            "status": self.status,
            "file": self.file,
            "python_version": self.python_version,
            "platform": self.platform,
            "optimized": self.optimized,
            "public_count": self.public_count,
            "symbol_counts": dict(self.symbol_counts),
            "capabilities": [item.to_dict() for item in self.capabilities],
            "sections": list(self.sections),
            "generated_at": self.generated_at,
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "VisualizationModuleInfo":
        return cls(
            name=str(data.get("name", _MODULE_NAME)),
            description=str(data.get("description", _MODULE_DESCRIPTION)),
            version=str(data.get("version", __version__)),
            author=str(data.get("author", __author__)),
            license=str(data.get("license", __license__)),
            status=str(data.get("status", __status__)),
            file=_optional_text(data.get("file")),
            python_version=str(data.get("python_version", platform.python_version())),
            platform=str(data.get("platform", platform.platform())),
            optimized=int(data.get("optimized", sys.flags.optimize)),
            public_count=int(data.get("public_count", 0)),
            symbol_counts=MappingProxyType({
                str(key): int(value)
                for key, value in dict(data.get("symbol_counts", {})).items()
            }),
            capabilities=tuple(
                ModuleCapabilityInfo.from_dict(item)
                for item in data.get("capabilities", ())
                if isinstance(item, Mapping)
            ),
            sections=tuple(int(item) for item in data.get("sections", ())),
            generated_at=str(data.get("generated_at", _utc_timestamp())),
        )

    @property
    def fingerprint(self) -> str:
        return _stable_fingerprint(self.to_dict(), exclude=("generated_at",))


@dataclass(frozen=True, slots=True)
class VisualizationAPIReport:
    """Hold an API inventory."""

    module: VisualizationModuleInfo
    symbols: Tuple[PublicSymbolInfo, ...]
    missing_public_names: Tuple[str, ...] = ()
    duplicate_public_names: Tuple[str, ...] = ()
    unexpected_public_names: Tuple[str, ...] = ()

    @property
    def valid(self) -> bool:
        return not self.missing_public_names and not self.duplicate_public_names

    def by_kind(self, kind: str) -> Tuple[PublicSymbolInfo, ...]:
        normalized = str(kind).strip().lower()
        return tuple(item for item in self.symbols if item.kind == normalized)

    def find(self, pattern: str) -> Tuple[PublicSymbolInfo, ...]:
        query = str(pattern).strip().lower()
        if not query:
            return self.symbols
        return tuple(
            item for item in self.symbols
            if query in item.name.lower()
            or query in item.qualified_name.lower()
            or query in (item.doc_summary or "").lower()
        )

    def summary(self) -> Dict[str, Any]:
        counts = Counter(item.kind for item in self.symbols)
        return {
            "valid": self.valid,
            "public_count": len(self.symbols),
            "counts": dict(sorted(counts.items())),
            "missing_count": len(self.missing_public_names),
            "duplicate_count": len(self.duplicate_public_names),
            "unexpected_count": len(self.unexpected_public_names),
            "fingerprint": self.fingerprint,
        }

    def to_dict(self) -> Dict[str, Any]:
        return {
            "module": self.module.to_dict(),
            "symbols": [item.to_dict() for item in self.symbols],
            "missing_public_names": list(self.missing_public_names),
            "duplicate_public_names": list(self.duplicate_public_names),
            "unexpected_public_names": list(self.unexpected_public_names),
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "VisualizationAPIReport":
        module_data = data.get("module", {})
        return cls(
            module=VisualizationModuleInfo.from_dict(
                module_data if isinstance(module_data, Mapping) else {}
            ),
            symbols=tuple(
                PublicSymbolInfo.from_dict(item)
                for item in data.get("symbols", ())
                if isinstance(item, Mapping)
            ),
            missing_public_names=tuple(
                str(item) for item in data.get("missing_public_names", ())
            ),
            duplicate_public_names=tuple(
                str(item) for item in data.get("duplicate_public_names", ())
            ),
            unexpected_public_names=tuple(
                str(item) for item in data.get("unexpected_public_names", ())
            ),
        )

    @property
    def fingerprint(self) -> str:
        return _stable_fingerprint(self.to_dict(), exclude=("generated_at",))


@dataclass(frozen=True, slots=True)
class VisualizationDiagnosticReport:
    """Hold runtime diagnostics."""

    module: VisualizationModuleInfo
    api_valid: bool
    import_valid: bool
    all_unique: bool
    serializable: bool
    backend_available: bool
    optional_dependencies: Mapping[str, bool]
    checks: Mapping[str, bool]
    warnings: Tuple[str, ...] = ()
    errors: Tuple[str, ...] = ()

    @property
    def ok(self) -> bool:
        return not self.errors and all(self.checks.values())

    def to_dict(self) -> Dict[str, Any]:
        return {
            "module": self.module.to_dict(),
            "api_valid": self.api_valid,
            "import_valid": self.import_valid,
            "all_unique": self.all_unique,
            "serializable": self.serializable,
            "backend_available": self.backend_available,
            "optional_dependencies": dict(self.optional_dependencies),
            "checks": dict(self.checks),
            "warnings": list(self.warnings),
            "errors": list(self.errors),
            "ok": self.ok,
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "VisualizationDiagnosticReport":
        module_data = data.get("module", {})
        return cls(
            module=VisualizationModuleInfo.from_dict(
                module_data if isinstance(module_data, Mapping) else {}
            ),
            api_valid=bool(data.get("api_valid", False)),
            import_valid=bool(data.get("import_valid", False)),
            all_unique=bool(data.get("all_unique", False)),
            serializable=bool(data.get("serializable", False)),
            backend_available=bool(data.get("backend_available", False)),
            optional_dependencies=MappingProxyType({
                str(key): bool(value)
                for key, value in dict(data.get("optional_dependencies", {})).items()
            }),
            checks=MappingProxyType({
                str(key): bool(value)
                for key, value in dict(data.get("checks", {})).items()
            }),
            warnings=tuple(str(item) for item in data.get("warnings", ())),
            errors=tuple(str(item) for item in data.get("errors", ())),
        )

    @property
    def fingerprint(self) -> str:
        return _stable_fingerprint(self.to_dict(), exclude=("generated_at",))


def _optional_text(value: Any) -> Optional[str]:
    """Return stripped text or None."""

    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _utc_timestamp() -> str:
    """Return an ISO UTC timestamp."""

    return datetime.now(timezone.utc).isoformat()


def _stable_fingerprint(
    value: Mapping[str, Any],
    *,
    exclude: Sequence[str] = (),
) -> str:
    """Hash JSON-compatible content."""

    excluded = set(exclude)

    def clean(item: Any) -> Any:
        if isinstance(item, Mapping):
            return {
                str(key): clean(val)
                for key, val in sorted(item.items(), key=lambda pair: str(pair[0]))
                if str(key) not in excluded
            }
        if isinstance(item, (list, tuple, set, frozenset)):
            return [clean(entry) for entry in item]
        if isinstance(item, Enum):
            return item.value
        if isinstance(item, Path):
            return str(item)
        return item

    payload = json.dumps(clean(value), sort_keys=True, separators=(",", ":"), default=str)
    return sha256(payload.encode("utf-8")).hexdigest()


def _safe_signature(value: Any) -> Optional[str]:
    """Return a stable signature string."""

    try:
        return str(inspect.signature(value))
    except (TypeError, ValueError):
        return None


def _doc_summary(value: Any) -> Optional[str]:
    """Return the first docstring line."""

    document = inspect.getdoc(value)
    if not document:
        return None
    return document.strip().splitlines()[0].strip() or None


def classify_public_symbol(value: Any) -> str:
    """Classify a public value."""

    if inspect.isclass(value):
        if issubclass(value, Enum):
            return "enum"
        if is_dataclass(value):
            return "dataclass"
        if value.__name__.endswith("Protocol"):
            return "protocol"
        if issubclass(value, Exception):
            return "exception"
        if issubclass(value, Warning):
            return "warning"
        return "class"
    if inspect.iscoroutinefunction(value):
        return "async_function"
    if inspect.isfunction(value) or inspect.isbuiltin(value):
        return "function"
    if isinstance(value, type):
        return "type"
    if callable(value):
        return "callable"
    return "constant"


def inspect_public_symbol(name: str, value: Any) -> PublicSymbolInfo:
    """Inspect one symbol."""

    kind = classify_public_symbol(value)
    module_name = str(getattr(value, "__module__", __name__))
    qualified = str(getattr(value, "__qualname__", name))
    bases: Tuple[str, ...] = ()
    field_names: Tuple[str, ...] = ()
    enum_values: Tuple[str, ...] = ()
    if inspect.isclass(value):
        bases = tuple(base.__name__ for base in value.__bases__)
        if is_dataclass(value):
            field_names = tuple(item.name for item in fields(value))
        if issubclass(value, Enum):
            enum_values = tuple(str(item.value) for item in value)
    return PublicSymbolInfo(
        name=str(name),
        kind=kind,
        module=module_name,
        qualified_name=f"{module_name}.{qualified}",
        signature=_safe_signature(value),
        bases=bases,
        fields=field_names,
        enum_values=enum_values,
        doc_summary=_doc_summary(value),
    )


def iter_public_symbols(
    namespace: Optional[Mapping[str, Any]] = None,
) -> Iterator[Tuple[str, Any]]:
    """Yield registered public symbols."""

    values = globals() if namespace is None else namespace
    seen: Set[str] = set()
    for name in __all__:
        if name in seen or name not in values:
            continue
        seen.add(name)
        yield name, values[name]


def list_public_symbols(
    *,
    kind: Optional[str] = None,
    pattern: Optional[str] = None,
    namespace: Optional[Mapping[str, Any]] = None,
) -> Tuple[PublicSymbolInfo, ...]:
    """List public symbols."""

    normalized_kind = _optional_text(kind)
    query = (_optional_text(pattern) or "").lower()
    result: List[PublicSymbolInfo] = []
    for name, value in iter_public_symbols(namespace):
        info = inspect_public_symbol(name, value)
        if normalized_kind and info.kind != normalized_kind.lower():
            continue
        if query and query not in name.lower() and query not in (info.doc_summary or "").lower():
            continue
        result.append(info)
    return tuple(sorted(result, key=lambda item: (item.kind, item.name.lower())))


def list_public_functions() -> Tuple[PublicSymbolInfo, ...]:
    """List public functions."""

    return tuple(
        item for item in list_public_symbols()
        if item.kind in {"function", "async_function"}
    )


def list_public_classes() -> Tuple[PublicSymbolInfo, ...]:
    """List public classes."""

    return tuple(
        item for item in list_public_symbols()
        if item.kind in {
            "class", "dataclass", "enum", "exception", "warning", "protocol"
        }
    )


def list_public_dataclasses() -> Tuple[PublicSymbolInfo, ...]:
    """List public dataclasses."""

    return tuple(item for item in list_public_symbols() if item.kind == "dataclass")


def list_public_enums() -> Tuple[PublicSymbolInfo, ...]:
    """List public enums."""

    return tuple(item for item in list_public_symbols() if item.kind == "enum")


def get_public_symbol(name: str, default: Any = None) -> Any:
    """Return a registered public symbol."""

    text = str(name).strip()
    if text not in __all__:
        return default
    return globals().get(text, default)


def has_public_symbol(name: str) -> bool:
    """Test public-symbol availability."""

    text = str(name).strip()
    return text in __all__ and text in globals()


def describe_public_symbol(name: str) -> Dict[str, Any]:
    """Describe one registered symbol."""

    value = get_public_symbol(name, None)
    if value is None:
        raise KeyError(f"Unknown public symbol: {name!r}")
    return inspect_public_symbol(str(name), value).to_dict()


def _package_version(module: Any) -> Optional[str]:
    """Read a package version."""

    if module is None:
        return None
    return _optional_text(getattr(module, "__version__", None))


def get_visualization_capabilities() -> Tuple[ModuleCapabilityInfo, ...]:
    """Return runtime capabilities."""

    return (
        ModuleCapabilityInfo(
            "numpy",
            NUMPY_AVAILABLE,
            "numpy",
            _package_version(np),
            "Array and linear-algebra acceleration.",
        ),
        ModuleCapabilityInfo(
            "pillow",
            PILLOW_AVAILABLE,
            "PIL",
            _package_version(Image),
            "Raster image inspection and post-processing.",
        ),
        ModuleCapabilityInfo(
            "chimerax",
            CHIMERAX_AVAILABLE,
            "chimerax",
            _package_version(_chimerax),
            "Interactive command execution.",
        ),
        ModuleCapabilityInfo(
            "command_export",
            True,
            _MODULE_NAME,
            __version__,
            "Backend-neutral ChimeraX script generation.",
        ),
        ModuleCapabilityInfo(
            "dry_run",
            True,
            _MODULE_NAME,
            __version__,
            "Plan validation without ChimeraX.",
        ),
        ModuleCapabilityInfo(
            "json_serialization",
            True,
            "json",
            None,
            "State and specification serialization.",
        ),
    )


def get_visualization_feature_flags() -> Mapping[str, bool]:
    """Return stable feature flags."""

    flags = {
        "molecular_specs": has_public_symbol("MolecularSpecificationBundle"),
        "selection_conversion": has_public_symbol("MolecularSelection"),
        "interaction_visualization": has_public_symbol("InteractionVisualizationSpec"),
        "scene_planning": has_public_symbol("VisualizationPlan"),
        "receptor_visualization": has_public_symbol("ReceptorVisualizationSpec"),
        "ligand_visualization": has_public_symbol("LigandVisualizationSpec"),
        "virtual_points": has_public_symbol("VirtualPointCollection"),
        "residue_visualization": has_public_symbol("InvolvedResidueCollection"),
        "hotspots": has_public_symbol("HotspotCollection"),
        "visual_scoring": has_public_symbol("VisualScoreCollection"),
        "multipose": has_public_symbol("MultiposeVisualizationSpec"),
        "consensus": has_public_symbol("ConsensusCollection"),
        "complementarity": has_public_symbol("ComplementarityResult"),
        "annotations": has_public_symbol("AnnotationCollection"),
        "camera": has_public_symbol("CameraFramingSpec"),
        "snapshots": has_public_symbol("SnapshotCollection"),
        "command_export": has_public_symbol("CommandScriptSpec"),
        "chimerax_backend": has_public_symbol("ChimeraXBackend"),
        "dockmodel_integration": has_public_symbol("DockModelVisualizationState"),
        "convenience_api": has_public_symbol("VisualizationFacade"),
        "permissive_validation": has_public_symbol("VisualizationValidationPolicy"),
    }
    return MappingProxyType(flags)


def _detect_sections(source: Optional[str] = None) -> Tuple[int, ...]:
    """Detect numbered sections from source."""

    text = source
    if text is None:
        path = globals().get("__file__")
        if path:
            try:
                text = Path(str(path)).read_text(encoding="utf-8")
            except OSError:
                text = None
    if not text:
        return tuple(range(1, 30))
    values = {
        int(match.group(1))
        for match in re.finditer(
            r"^# (?:End of )?Section\s+(\d+)\b",
            text,
            re.MULTILINE,
        )
    }
    return tuple(sorted(values))


def get_visualization_module_info() -> VisualizationModuleInfo:
    """Build module metadata."""

    symbols = list_public_symbols()
    counts = Counter(item.kind for item in symbols)
    return VisualizationModuleInfo(
        name=_MODULE_NAME,
        description=_MODULE_DESCRIPTION,
        version=__version__,
        author=__author__,
        license=__license__,
        status=__status__,
        file=_optional_text(globals().get("__file__")),
        python_version=platform.python_version(),
        platform=platform.platform(),
        optimized=sys.flags.optimize,
        public_count=len(symbols),
        symbol_counts=MappingProxyType(dict(sorted(counts.items()))),
        capabilities=get_visualization_capabilities(),
        sections=_detect_sections(),
        generated_at=_utc_timestamp(),
    )


def inspect_visualization_api(
    namespace: Optional[Mapping[str, Any]] = None,
) -> VisualizationAPIReport:
    """Build a complete API report."""

    values = globals() if namespace is None else namespace
    duplicates = tuple(sorted(
        name for name, count in Counter(__all__).items() if count > 1
    ))
    missing = tuple(sorted(name for name in __all__ if name not in values))
    symbols = list_public_symbols(namespace=values)
    unexpected = tuple(sorted(
        name for name, value in values.items()
        if not name.startswith("_")
        and name not in __all__
        and getattr(value, "__module__", None) == __name__
        and (inspect.isclass(value) or inspect.isfunction(value))
    ))
    return VisualizationAPIReport(
        module=get_visualization_module_info(),
        symbols=symbols,
        missing_public_names=missing,
        duplicate_public_names=duplicates,
        unexpected_public_names=unexpected,
    )


def inspect_visualization_dependencies() -> Mapping[str, Any]:
    """Describe dependencies."""

    internal = {
        "config": "internal visualization dataclasses",
        "utils": "not imported by core planning",
        "dock_model": "duck-typed",
    }
    optional = {
        item.name: item.to_dict()
        for item in get_visualization_capabilities()
        if item.name in {"numpy", "pillow", "chimerax"}
    }
    return MappingProxyType({
        "internal": MappingProxyType(internal),
        "optional": MappingProxyType(optional),
        "deferred_heavy_imports": True,
    })


def inspect_visualization_registry() -> Mapping[str, Any]:
    """Describe central registries."""

    enum_registry = globals().get("VISUALIZATION_ENUM_REGISTRY", {})
    validator_registry = globals().get("VISUALIZATION_VALIDATOR_REGISTRY")
    validators: Any = ()
    if validator_registry is not None and hasattr(validator_registry, "entries"):
        try:
            validators = tuple(
                getattr(item, "name", str(item))
                for item in validator_registry.entries()
            )
        except Exception:
            validators = ()
    return MappingProxyType({
        "enums": tuple(sorted(str(key) for key in enum_registry)),
        "validators": tuple(sorted(validators)),
        "public_names": tuple(__all__),
    })


def run_visualization_diagnostics() -> VisualizationDiagnosticReport:
    """Run lightweight module diagnostics."""

    api = inspect_visualization_api()
    warnings_found: List[str] = []
    errors_found: List[str] = []
    optional = {
        item.name: item.available
        for item in get_visualization_capabilities()
        if item.name in {"numpy", "pillow", "chimerax"}
    }
    if not optional.get("chimerax", False):
        warnings_found.append("ChimeraX is unavailable; execution requires dry-run or export mode.")
    if not optional.get("pillow", False):
        warnings_found.append("Pillow is unavailable; raster post-processing is disabled.")
    try:
        payload = api.to_dict()
        json.dumps(payload, sort_keys=True, default=str)
        serializable = True
    except Exception as exc:
        serializable = False
        errors_found.append(f"API serialization failed: {exc}")
    checks = {
        "public_names_present": not api.missing_public_names,
        "public_names_unique": not api.duplicate_public_names,
        "api_serializable": serializable,
        "metadata_available": bool(__version__ and __author__),
        "feature_flags_available": bool(get_visualization_feature_flags()),
        "validator_registry_available": has_public_symbol("VISUALIZATION_VALIDATOR_REGISTRY"),
    }
    for name, passed in checks.items():
        if not passed:
            errors_found.append(f"Diagnostic check failed: {name}")
    return VisualizationDiagnosticReport(
        module=api.module,
        api_valid=api.valid,
        import_valid=True,
        all_unique=not api.duplicate_public_names,
        serializable=serializable,
        backend_available=CHIMERAX_AVAILABLE,
        optional_dependencies=MappingProxyType(optional),
        checks=MappingProxyType(checks),
        warnings=tuple(warnings_found),
        errors=tuple(errors_found),
    )


def summarize_visualization_module() -> Dict[str, Any]:
    """Return a compact module summary."""

    module = get_visualization_module_info()
    flags = get_visualization_feature_flags()
    return {
        "name": module.name,
        "version": module.version,
        "status": module.status,
        "public_count": module.public_count,
        "symbol_counts": dict(module.symbol_counts),
        "section_count": len(module.sections),
        "sections": list(module.sections),
        "capability_count": sum(item.available for item in module.capabilities),
        "feature_count": sum(flags.values()),
        "fingerprint": module.fingerprint,
    }


def visualization_introspection_to_dict(value: Any = None) -> Dict[str, Any]:
    """Serialize introspection data."""

    if value is None:
        value = inspect_visualization_api()
    if hasattr(value, "to_dict"):
        result = value.to_dict()
        if isinstance(result, Mapping):
            return dict(result)
    if isinstance(value, Mapping):
        return dict(value)
    raise TypeError(f"Unsupported introspection value: {type(value).__name__}")


def visualization_introspection_to_json(
    value: Any = None,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize introspection data to JSON."""

    return json.dumps(
        visualization_introspection_to_dict(value),
        indent=indent,
        sort_keys=True,
        default=str,
    )


def format_visualization_api(
    report: Optional[VisualizationAPIReport] = None,
    *,
    include_signatures: bool = True,
    include_docs: bool = False,
) -> str:
    """Format the public API as text."""

    current = report or inspect_visualization_api()
    lines = [
        f"{current.module.name} {current.module.version}",
        f"Public symbols: {len(current.symbols)}",
        f"API valid: {current.valid}",
        "",
    ]
    grouped: Dict[str, List[PublicSymbolInfo]] = defaultdict(list)
    for item in current.symbols:
        grouped[item.kind].append(item)
    for kind in sorted(grouped):
        lines.append(f"[{kind}]")
        for item in sorted(grouped[kind], key=lambda entry: entry.name.lower()):
            suffix = item.signature if include_signatures and item.signature else ""
            lines.append(f"- {item.name}{suffix}")
            if include_docs and item.doc_summary:
                lines.append(f"  {item.doc_summary}")
        lines.append("")
    if current.missing_public_names:
        lines.append("Missing: " + ", ".join(current.missing_public_names))
    if current.duplicate_public_names:
        lines.append("Duplicates: " + ", ".join(current.duplicate_public_names))
    return "\n".join(lines).rstrip() + "\n"


def find_visualization_features(query: str) -> Mapping[str, Any]:
    """Search features and public symbols."""

    text = str(query).strip().lower()
    flags = get_visualization_feature_flags()
    matching_flags = {
        name: enabled for name, enabled in flags.items()
        if text in name.lower()
    }
    matching_symbols = tuple(
        item.to_dict() for item in list_public_symbols(pattern=text)
    )
    return MappingProxyType({
        "query": query,
        "features": MappingProxyType(matching_flags),
        "symbols": matching_symbols,
        "count": len(matching_flags) + len(matching_symbols),
    })


def assert_visualization_api_integrity() -> VisualizationAPIReport:
    """Assert public API integrity."""

    report = inspect_visualization_api()
    problems: List[str] = []
    if report.missing_public_names:
        problems.append("Missing public names: " + ", ".join(report.missing_public_names))
    if report.duplicate_public_names:
        problems.append("Duplicate public names: " + ", ".join(report.duplicate_public_names))
    if problems:
        raise VisualizationValidationError("; ".join(problems))
    return report


