    "classify_public_symbol",
    "inspect_public_symbol",
    "iter_public_symbols",
    "list_public_symbols",
    "list_public_functions",
    "list_public_classes",
    "list_public_dataclasses",
    "list_public_enums",
    "get_public_symbol",
    "has_public_symbol",
