# =============================================================================
# Section 30.1 — Self-tests: infrastructure
# =============================================================================

# 30.1.1. Status and constants
# -----------------------------------------------------------------------------

SELF_TEST_SECTION_INFRASTRUCTURE: Final[str] = "30.1"
SELF_TEST_DEFAULT_TIMEOUT: Final[float] = 30.0
SELF_TEST_MAX_MESSAGE_LENGTH: Final[int] = 4096
SELF_TEST_SCHEMA_VERSION: Final[int] = 1


class VisualizationSelfTestStatus(TextEnum):
    """Self-test outcome."""

    PENDING = "pending"
    PASSED = "passed"
    FAILED = "failed"
    SKIPPED = "skipped"
    ERROR = "error"

    @property
    def successful(self) -> bool:
        return self in {type(self).PASSED, type(self).SKIPPED}


class VisualizationSelfTestError(VisualizationError):
    """Base self-test failure."""

    default_code = "self_test_error"


class VisualizationAssertionError(VisualizationSelfTestError):
    """Self-test assertion failure."""

    default_code = "self_test_assertion_error"


class VisualizationSelfTestRegistrationError(VisualizationSelfTestError):
    """Invalid self-test registration."""

    default_code = "self_test_registration_error"


class VisualizationSelfTestExecutionError(VisualizationSelfTestError):
    """Unexpected self-test execution failure."""

    default_code = "self_test_execution_error"


class VisualizationSelfTestSkip(VisualizationSelfTestError):
    """Internal skip signal."""

    default_code = "self_test_skipped"


# 30.1.2. Test records
# -----------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class VisualizationSelfTestCase:
    """Registered self-test."""

    test_id: str
    name: str
    section: str
    function: Callable[["VisualizationSelfTestContext"], Any] = field(
        repr=False,
        compare=False,
    )
    description: str = ""
    tags: Tuple[str, ...] = ()
    requires: Tuple[str, ...] = ()
    timeout: float = SELF_TEST_DEFAULT_TIMEOUT
    enabled: bool = True

    def __post_init__(self) -> None:
        test_id = str(self.test_id).strip()
        name = str(self.name).strip()
        section = str(self.section).strip()
        if not test_id or not name or not section:
            raise VisualizationSelfTestRegistrationError(
                "Self-test id, name and section are required."
            )
        if not callable(self.function):
            raise VisualizationSelfTestRegistrationError(
                f"Self-test {test_id!r} has no callable function."
            )
        if not math.isfinite(float(self.timeout)) or float(self.timeout) <= 0.0:
            raise VisualizationSelfTestRegistrationError(
                f"Self-test {test_id!r} timeout must be positive."
            )
        object.__setattr__(self, "test_id", test_id)
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "section", section)
        object.__setattr__(self, "description", str(self.description).strip())
        object.__setattr__(self, "tags", _normalize_self_test_tokens(self.tags))
        object.__setattr__(self, "requires", _normalize_self_test_tokens(self.requires))
        object.__setattr__(self, "timeout", float(self.timeout))
        object.__setattr__(self, "enabled", bool(self.enabled))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "test_id": self.test_id,
            "name": self.name,
            "section": self.section,
            "description": self.description,
            "tags": list(self.tags),
            "requires": list(self.requires),
            "timeout": self.timeout,
            "enabled": self.enabled,
        }


@dataclass(frozen=True, slots=True)
class VisualizationSelfTestResult:
    """Single self-test result."""

    test_id: str
    name: str
    section: str
    status: VisualizationSelfTestStatus
    duration_seconds: float = 0.0
    message: str = ""
    details: Mapping[str, Any] = field(default_factory=dict)
    exception_type: Optional[str] = None
    traceback_text: Optional[str] = None
    tags: Tuple[str, ...] = ()

    def __post_init__(self) -> None:
        status = VisualizationSelfTestStatus.parse(self.status)
        duration = max(0.0, float(self.duration_seconds))
        message = _truncate_self_test_text(str(self.message))
        details = MappingProxyType(dict(self.details))
        traceback_text = (
            _truncate_self_test_text(str(self.traceback_text), 16000)
            if self.traceback_text
            else None
        )
        object.__setattr__(self, "status", status)
        object.__setattr__(self, "duration_seconds", duration)
        object.__setattr__(self, "message", message)
        object.__setattr__(self, "details", details)
        object.__setattr__(self, "traceback_text", traceback_text)
        object.__setattr__(self, "tags", _normalize_self_test_tokens(self.tags))

    @property
    def successful(self) -> bool:
        return self.status.successful

    @property
    def failed(self) -> bool:
        return self.status in {
            VisualizationSelfTestStatus.FAILED,
            VisualizationSelfTestStatus.ERROR,
        }

    def to_dict(self) -> Dict[str, Any]:
        return {
            "test_id": self.test_id,
            "name": self.name,
            "section": self.section,
            "status": self.status.value,
            "duration_seconds": self.duration_seconds,
            "message": self.message,
            "details": _safe_error_value(self.details),
            "exception_type": self.exception_type,
            "traceback": self.traceback_text,
            "tags": list(self.tags),
            "successful": self.successful,
        }

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "VisualizationSelfTestResult":
        return cls(
            test_id=str(data.get("test_id", "")),
            name=str(data.get("name", "")),
            section=str(data.get("section", "")),
            status=VisualizationSelfTestStatus.parse(
                data.get("status", VisualizationSelfTestStatus.ERROR.value)
            ),
            duration_seconds=float(data.get("duration_seconds", 0.0)),
            message=str(data.get("message", "")),
            details=dict(data.get("details", {})),
            exception_type=(
                str(data["exception_type"])
                if data.get("exception_type") is not None
                else None
            ),
            traceback_text=(
                str(data["traceback"])
                if data.get("traceback") is not None
                else None
            ),
            tags=tuple(str(item) for item in data.get("tags", ())),
        )


@dataclass(frozen=True, slots=True)
class VisualizationSelfTestReport:
    """Self-test run report."""

    results: Tuple[VisualizationSelfTestResult, ...]
    started_at: str
    finished_at: str
    duration_seconds: float
    selected_sections: Tuple[str, ...] = ()
    selected_tags: Tuple[str, ...] = ()
    pattern: Optional[str] = None
    fail_fast: bool = False
    schema_version: int = SELF_TEST_SCHEMA_VERSION

    def __post_init__(self) -> None:
        object.__setattr__(self, "results", tuple(self.results))
        object.__setattr__(self, "duration_seconds", max(0.0, float(self.duration_seconds)))
        object.__setattr__(
            self,
            "selected_sections",
            _normalize_self_test_tokens(self.selected_sections),
        )
        object.__setattr__(
            self,
            "selected_tags",
            _normalize_self_test_tokens(self.selected_tags),
        )

    @property
    def counts(self) -> Mapping[str, int]:
        values = Counter(result.status.value for result in self.results)
        for status in VisualizationSelfTestStatus:
            values.setdefault(status.value, 0)
        return MappingProxyType(dict(values))

    @property
    def total(self) -> int:
        return len(self.results)

    @property
    def passed(self) -> int:
        return self.counts[VisualizationSelfTestStatus.PASSED.value]

    @property
    def failed(self) -> int:
        return (
            self.counts[VisualizationSelfTestStatus.FAILED.value]
            + self.counts[VisualizationSelfTestStatus.ERROR.value]
        )

    @property
    def skipped(self) -> int:
        return self.counts[VisualizationSelfTestStatus.SKIPPED.value]

    @property
    def successful(self) -> bool:
        return self.failed == 0

    def failures(self) -> Tuple[VisualizationSelfTestResult, ...]:
        return tuple(result for result in self.results if result.failed)

    def by_section(self) -> Mapping[str, Tuple[VisualizationSelfTestResult, ...]]:
        grouped: Dict[str, List[VisualizationSelfTestResult]] = defaultdict(list)
        for result in self.results:
            grouped[result.section].append(result)
        return MappingProxyType({key: tuple(value) for key, value in grouped.items()})

    def to_dict(self) -> Dict[str, Any]:
        return {
            "schema_version": self.schema_version,
            "started_at": self.started_at,
            "finished_at": self.finished_at,
            "duration_seconds": self.duration_seconds,
            "selected_sections": list(self.selected_sections),
            "selected_tags": list(self.selected_tags),
            "pattern": self.pattern,
            "fail_fast": self.fail_fast,
            "counts": dict(self.counts),
            "total": self.total,
            "successful": self.successful,
            "results": [result.to_dict() for result in self.results],
        }

    def to_json(self, *, indent: Optional[int] = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, sort_keys=True)

    @classmethod
    def from_dict(cls, data: Mapping[str, Any]) -> "VisualizationSelfTestReport":
        return cls(
            results=tuple(
                VisualizationSelfTestResult.from_dict(item)
                for item in data.get("results", ())
            ),
            started_at=str(data.get("started_at", "")),
            finished_at=str(data.get("finished_at", "")),
            duration_seconds=float(data.get("duration_seconds", 0.0)),
            selected_sections=tuple(
                str(item) for item in data.get("selected_sections", ())
            ),
            selected_tags=tuple(str(item) for item in data.get("selected_tags", ())),
            pattern=(str(data["pattern"]) if data.get("pattern") is not None else None),
            fail_fast=bool(data.get("fail_fast", False)),
            schema_version=int(data.get("schema_version", SELF_TEST_SCHEMA_VERSION)),
        )

    @classmethod
    def from_json(cls, text: str) -> "VisualizationSelfTestReport":
        data = json.loads(text)
        if not isinstance(data, Mapping):
            raise VisualizationSerializationError("Self-test report JSON must be an object.")
        return cls.from_dict(data)


# 30.1.3. Context and assertions
# -----------------------------------------------------------------------------


@dataclass(slots=True)
class VisualizationSelfTestContext:
    """Mutable self-test context."""

    case: VisualizationSelfTestCase
    capabilities: Mapping[str, bool] = field(default_factory=dict)
    values: Dict[str, Any] = field(default_factory=dict)
    notes: List[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        self.capabilities = MappingProxyType(dict(self.capabilities))

    def note(self, message: str) -> None:
        text = str(message).strip()
        if text:
            self.notes.append(_truncate_self_test_text(text))

    def set(self, name: str, value: Any) -> Any:
        self.values[str(name)] = value
        return value

    def get(self, name: str, default: Any = None) -> Any:
        return self.values.get(str(name), default)

    def skip(self, reason: str) -> None:
        raise VisualizationSelfTestSkip(str(reason))

    def require(self, capability: str) -> None:
        name = str(capability).strip().lower()
        if not self.capabilities.get(name, False):
            self.skip(f"Required capability is unavailable: {name}")


@contextmanager
def visualization_test_workspace(
    *,
    prefix: str = "dockanalyzer_visualization_test_",
) -> Iterator[Path]:
    """Create a temporary self-test directory."""

    import shutil
    import tempfile

    root = Path(tempfile.mkdtemp(prefix=prefix))
    try:
        yield root
    finally:
        shutil.rmtree(root, ignore_errors=True)


def _normalize_self_test_tokens(values: Iterable[Any]) -> Tuple[str, ...]:
    """Normalize test tags and sections."""

    result: List[str] = []
    seen: Set[str] = set()
    for value in values:
        token = str(value).strip().lower()
        if token and token not in seen:
            result.append(token)
            seen.add(token)
    return tuple(result)


def _truncate_self_test_text(value: str, limit: int = SELF_TEST_MAX_MESSAGE_LENGTH) -> str:
    """Bound self-test text."""

    text = str(value)
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 3)] + "..."


def _self_test_failure(
    message: str,
    *,
    actual: Any = None,
    expected: Any = None,
) -> VisualizationAssertionError:
    """Build an assertion error."""

    context: Dict[str, Any] = {}
    if actual is not None:
        context["actual"] = _safe_error_value(actual)
    if expected is not None:
        context["expected"] = _safe_error_value(expected)
    return VisualizationAssertionError(str(message), context=context)


def visualization_assert_true(value: Any, message: str = "Expected a truthy value.") -> None:
    """Assert truthiness."""

    if not value:
        raise _self_test_failure(message, actual=value, expected=True)


def visualization_assert_false(value: Any, message: str = "Expected a falsy value.") -> None:
    """Assert falsiness."""

    if value:
        raise _self_test_failure(message, actual=value, expected=False)


def visualization_assert_equal(
    actual: Any,
    expected: Any,
    message: str = "Values differ.",
) -> None:
    """Assert equality."""

    if actual != expected:
        raise _self_test_failure(message, actual=actual, expected=expected)


def visualization_assert_not_equal(
    actual: Any,
    expected: Any,
    message: str = "Values unexpectedly match.",
) -> None:
    """Assert inequality."""

    if actual == expected:
        raise _self_test_failure(message, actual=actual, expected=f"not {expected!r}")


def visualization_assert_near(
    actual: Number,
    expected: Number,
    *,
    tolerance: float = 1e-7,
    message: str = "Numeric values differ.",
) -> None:
    """Assert numeric proximity."""

    actual_value = float(actual)
    expected_value = float(expected)
    tolerance_value = abs(float(tolerance))
    if not math.isclose(
        actual_value,
        expected_value,
        rel_tol=tolerance_value,
        abs_tol=tolerance_value,
    ):
        raise _self_test_failure(message, actual=actual_value, expected=expected_value)


def visualization_assert_sequence_equal(
    actual: Iterable[Any],
    expected: Iterable[Any],
    message: str = "Sequences differ.",
) -> None:
    """Assert ordered sequence equality."""

    actual_tuple = tuple(actual)
    expected_tuple = tuple(expected)
    if actual_tuple != expected_tuple:
        raise _self_test_failure(message, actual=actual_tuple, expected=expected_tuple)


def visualization_assert_contains(
    container: Any,
    member: Any,
    message: str = "Expected member is absent.",
) -> None:
    """Assert membership."""

    if member not in container:
        raise _self_test_failure(message, actual=container, expected=member)


def visualization_assert_is_instance(
    value: Any,
    expected_type: Any,
    message: str = "Value has an unexpected type.",
) -> None:
    """Assert type compatibility."""

    if not isinstance(value, expected_type):
        raise _self_test_failure(
            message,
            actual=type(value).__name__,
            expected=getattr(expected_type, "__name__", str(expected_type)),
        )


@contextmanager
def visualization_assert_raises(
    expected_exception: Any,
    *,
    message_pattern: Optional[str] = None,
) -> Iterator[None]:
    """Assert that a block raises."""

    caught: Optional[BaseException] = None
    try:
        yield
    except expected_exception as exc:
        caught = exc
    except BaseException as exc:
        raise _self_test_failure(
            "Unexpected exception type.",
            actual=type(exc).__name__,
            expected=getattr(expected_exception, "__name__", str(expected_exception)),
        ) from exc
    if caught is None:
        raise _self_test_failure(
            "Expected exception was not raised.",
            expected=getattr(expected_exception, "__name__", str(expected_exception)),
        )
    if message_pattern and not re.search(message_pattern, str(caught)):
        raise _self_test_failure(
            "Exception message does not match.",
            actual=str(caught),
            expected=message_pattern,
        )


def visualization_assert_json_roundtrip(
    value: Any,
    *,
    to_json: Callable[[Any], str],
    from_json: Callable[[str], Any],
    compare: Optional[Callable[[Any, Any], bool]] = None,
) -> Any:
    """Assert JSON reconstruction."""

    text = to_json(value)
    restored = from_json(text)
    equal = compare(value, restored) if compare else value == restored
    if not equal:
        raise _self_test_failure(
            "JSON round-trip changed the value.",
            actual=restored,
            expected=value,
        )
    return restored


def visualization_assert_fingerprint_stable(
    value: Any,
    restored: Any,
    message: str = "Fingerprint changed after reconstruction.",
) -> None:
    """Assert stable fingerprints."""

    first = getattr(value, "fingerprint", None)
    second = getattr(restored, "fingerprint", None)
    first_value = first() if callable(first) else first
    second_value = second() if callable(second) else second
    if not first_value or first_value != second_value:
        raise _self_test_failure(message, actual=second_value, expected=first_value)


# 30.1.4. Registry
# -----------------------------------------------------------------------------

_SELF_TEST_REGISTRY: Dict[str, VisualizationSelfTestCase] = {}


def register_visualization_self_test(
    *,
    test_id: str,
    name: Optional[str] = None,
    section: str,
    description: str = "",
    tags: Iterable[str] = (),
    requires: Iterable[str] = (),
    timeout: float = SELF_TEST_DEFAULT_TIMEOUT,
    enabled: bool = True,
) -> Callable[[Callable[[VisualizationSelfTestContext], Any]], Callable[[VisualizationSelfTestContext], Any]]:
    """Register a self-test function."""

    def decorator(
        function: Callable[[VisualizationSelfTestContext], Any],
    ) -> Callable[[VisualizationSelfTestContext], Any]:
        normalized_id = str(test_id).strip().lower()
        if normalized_id in _SELF_TEST_REGISTRY:
            raise VisualizationSelfTestRegistrationError(
                f"Duplicate self-test id: {normalized_id}"
            )
        case = VisualizationSelfTestCase(
            test_id=normalized_id,
            name=name or normalized_id,
            section=section,
            function=function,
            description=description,
            tags=tuple(tags),
            requires=tuple(requires),
            timeout=timeout,
            enabled=enabled,
        )
        _SELF_TEST_REGISTRY[normalized_id] = case
        return function

    return decorator


def unregister_visualization_self_test(test_id: str) -> bool:
    """Remove a registered self-test."""

    return _SELF_TEST_REGISTRY.pop(str(test_id).strip().lower(), None) is not None


def get_visualization_self_test(test_id: str) -> VisualizationSelfTestCase:
    """Return one self-test."""

    normalized = str(test_id).strip().lower()
    try:
        return _SELF_TEST_REGISTRY[normalized]
    except KeyError as exc:
        raise VisualizationSelfTestRegistrationError(
            f"Unknown self-test id: {normalized}"
        ) from exc


def list_visualization_self_tests(
    *,
    sections: Iterable[str] = (),
    tags: Iterable[str] = (),
    pattern: Optional[str] = None,
    include_disabled: bool = False,
) -> Tuple[VisualizationSelfTestCase, ...]:
    """List matching self-tests."""

    selected_sections = set(_normalize_self_test_tokens(sections))
    selected_tags = set(_normalize_self_test_tokens(tags))
    regex = re.compile(pattern, re.IGNORECASE) if pattern else None
    selected: List[VisualizationSelfTestCase] = []
    for case in _SELF_TEST_REGISTRY.values():
        if not include_disabled and not case.enabled:
            continue
        if selected_sections and case.section.lower() not in selected_sections:
            continue
        if selected_tags and not selected_tags.issubset(set(case.tags)):
            continue
        searchable = f"{case.test_id} {case.name} {case.description} {' '.join(case.tags)}"
        if regex and not regex.search(searchable):
            continue
        selected.append(case)
    return tuple(sorted(selected, key=lambda item: (_self_test_section_key(item.section), item.test_id)))


def clear_visualization_self_tests(*, section: Optional[str] = None) -> int:
    """Clear registered self-tests."""

    if section is None:
        count = len(_SELF_TEST_REGISTRY)
        _SELF_TEST_REGISTRY.clear()
        return count
    normalized = str(section).strip().lower()
    ids = [
        test_id
        for test_id, case in _SELF_TEST_REGISTRY.items()
        if case.section.lower() == normalized
    ]
    for test_id in ids:
        del _SELF_TEST_REGISTRY[test_id]
    return len(ids)


def _self_test_section_key(value: str) -> Tuple[int, ...]:
    """Build a numeric section sort key."""

    parts = re.findall(r"\d+", str(value))
    return tuple(int(part) for part in parts) or (sys.maxsize,)


def get_visualization_self_test_registry() -> Mapping[str, VisualizationSelfTestCase]:
    """Return a read-only registry view."""

    return MappingProxyType(dict(_SELF_TEST_REGISTRY))


# 30.1.5. Runner
# -----------------------------------------------------------------------------


def _self_test_capabilities() -> Mapping[str, bool]:
    """Return normalized runtime capabilities."""

    values = {
        capability.name: capability.available
        for capability in get_visualization_capabilities()
    }
    values.update({
        "numpy": NUMPY_AVAILABLE,
        "pillow": PILLOW_AVAILABLE,
        "chimerax": CHIMERAX_AVAILABLE,
        "filesystem": True,
        "json": True,
        "dry_run": True,
    })
    return MappingProxyType({str(key).lower(): bool(value) for key, value in values.items()})


def _missing_self_test_requirements(
    case: VisualizationSelfTestCase,
    capabilities: Mapping[str, bool],
) -> Tuple[str, ...]:
    """Return unavailable requirements."""

    return tuple(name for name in case.requires if not capabilities.get(name, False))


def run_visualization_self_test(
    case: Union[str, VisualizationSelfTestCase],
    *,
    capabilities: Optional[Mapping[str, bool]] = None,
) -> VisualizationSelfTestResult:
    """Run one registered self-test."""

    selected = get_visualization_self_test(case) if isinstance(case, str) else case
    runtime_capabilities = MappingProxyType(
        dict(capabilities) if capabilities is not None else dict(_self_test_capabilities())
    )
    missing = _missing_self_test_requirements(selected, runtime_capabilities)
    if not selected.enabled:
        return VisualizationSelfTestResult(
            test_id=selected.test_id,
            name=selected.name,
            section=selected.section,
            status=VisualizationSelfTestStatus.SKIPPED,
            message="Self-test is disabled.",
            tags=selected.tags,
        )
    if missing:
        return VisualizationSelfTestResult(
            test_id=selected.test_id,
            name=selected.name,
            section=selected.section,
            status=VisualizationSelfTestStatus.SKIPPED,
            message="Missing capabilities: " + ", ".join(missing),
            details={"missing_requirements": missing},
            tags=selected.tags,
        )
    context = VisualizationSelfTestContext(
        case=selected,
        capabilities=runtime_capabilities,
    )
    started = datetime.now(timezone.utc)
    status = VisualizationSelfTestStatus.PASSED
    message = "Passed."
    details: Dict[str, Any] = {}
    exception_type: Optional[str] = None
    traceback_text: Optional[str] = None
    try:
        returned = selected.function(context)
        if isinstance(returned, Mapping):
            details.update(returned)
        elif returned is not None:
            details["return_value"] = _safe_error_value(returned)
    except VisualizationSelfTestSkip as exc:
        status = VisualizationSelfTestStatus.SKIPPED
        message = str(exc)
        exception_type = type(exc).__name__
    except VisualizationAssertionError as exc:
        status = VisualizationSelfTestStatus.FAILED
        message = str(exc)
        details.update(getattr(exc, "context", {}) or {})
        exception_type = type(exc).__name__
        traceback_text = traceback.format_exc()
    except BaseException as exc:
        status = VisualizationSelfTestStatus.ERROR
        message = str(exc) or type(exc).__name__
        exception_type = type(exc).__name__
        traceback_text = traceback.format_exc()
    finished = datetime.now(timezone.utc)
    duration = max(0.0, (finished - started).total_seconds())
    if duration > selected.timeout and status == VisualizationSelfTestStatus.PASSED:
        status = VisualizationSelfTestStatus.FAILED
        message = f"Timeout exceeded: {duration:.6f}s > {selected.timeout:.6f}s."
        details["timeout"] = selected.timeout
    if context.notes:
        details["notes"] = tuple(context.notes)
    if context.values:
        details["context"] = _safe_error_value(context.values)
    return VisualizationSelfTestResult(
        test_id=selected.test_id,
        name=selected.name,
        section=selected.section,
        status=status,
        duration_seconds=duration,
        message=message,
        details=details,
        exception_type=exception_type,
        traceback_text=traceback_text,
        tags=selected.tags,
    )


def run_visualization_self_tests(
    *,
    sections: Iterable[str] = (),
    tags: Iterable[str] = (),
    pattern: Optional[str] = None,
    fail_fast: bool = False,
    include_disabled: bool = False,
    capabilities: Optional[Mapping[str, bool]] = None,
) -> VisualizationSelfTestReport:
    """Run selected self-tests."""

    selected_sections = _normalize_self_test_tokens(sections)
    selected_tags = _normalize_self_test_tokens(tags)
    cases = list_visualization_self_tests(
        sections=selected_sections,
        tags=selected_tags,
        pattern=pattern,
        include_disabled=include_disabled,
    )
    started = datetime.now(timezone.utc)
    results: List[VisualizationSelfTestResult] = []
    for case in cases:
        result = run_visualization_self_test(case, capabilities=capabilities)
        results.append(result)
        if fail_fast and result.failed:
            break
    finished = datetime.now(timezone.utc)
    return VisualizationSelfTestReport(
        results=tuple(results),
        started_at=started.isoformat(),
        finished_at=finished.isoformat(),
        duration_seconds=max(0.0, (finished - started).total_seconds()),
        selected_sections=selected_sections,
        selected_tags=selected_tags,
        pattern=pattern,
        fail_fast=fail_fast,
    )


def assert_visualization_self_tests(
    report: Optional[VisualizationSelfTestReport] = None,
    **run_kwargs: Any,
) -> VisualizationSelfTestReport:
    """Run or assert a self-test report."""

    current = report or run_visualization_self_tests(**run_kwargs)
    if not current.successful:
        summary = "; ".join(
            f"{result.test_id}: {result.message}"
            for result in current.failures()[:10]
        )
        raise VisualizationSelfTestExecutionError(
            f"{current.failed} visualization self-test(s) failed: {summary}",
            context={"report": current.to_dict()},
        )
    return current


def format_visualization_self_test_report(
    report: VisualizationSelfTestReport,
    *,
    include_passed: bool = False,
    include_tracebacks: bool = False,
) -> str:
    """Format a self-test report."""

    counts = report.counts
    lines = [
        "Visualization self-tests",
        f"Total: {report.total}",
        f"Passed: {counts['passed']}",
        f"Failed: {counts['failed'] + counts['error']}",
        f"Skipped: {counts['skipped']}",
        f"Duration: {report.duration_seconds:.6f}s",
    ]
    for result in report.results:
        if result.status == VisualizationSelfTestStatus.PASSED and not include_passed:
            continue
        lines.append(
            f"[{result.status.value.upper()}] {result.test_id} - {result.message}"
        )
        if include_tracebacks and result.traceback_text:
            lines.append(result.traceback_text.rstrip())
    return "\n".join(lines) + "\n"


def visualization_self_tests_to_json(
    report: VisualizationSelfTestReport,
    *,
    indent: Optional[int] = 2,
) -> str:
    """Serialize a self-test report."""

    return report.to_json(indent=indent)


