SELF_TEST_SECTION_COLORS_STYLES: Final[str] = "30.2"


def _assert_hex_color(value: Any, *, alpha: Optional[bool] = None) -> str:
    """Assert a normalized hexadecimal color."""

    color = str(value)
    valid_lengths = {9} if alpha is True else {7} if alpha is False else {7, 9}
    visualization_assert_true(
        len(color) in valid_lengths and bool(re.fullmatch(r"#[0-9A-F]+", color)),
        f"Invalid normalized color: {color!r}.",
    )
    return color


@register_visualization_self_test(
    test_id="30.2.color_normalization",
    name="Color normalization",
    section=SELF_TEST_SECTION_COLORS_STYLES,
    tags=("colors", "normalization"),
)
def _self_test_color_normalization(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    cases = {
        "red": COLOR_RED,
        "#abc": "#AABBCC",
        "#abcd": "#AABBCCDD",
        "#12abef": "#12ABEF",
        "rgb(255, 128, 0)": "#FF8000",
        "rgba(255, 128, 0, 0.5)": "#FF800080",
    }
    for source, expected in cases.items():
        visualization_assert_equal(normalize_color(source), expected)
    visualization_assert_equal(normalize_color((1.0, 0.0, 0.5)), "#FF0080")
    visualization_assert_equal(normalize_color((255, 128, 0, 64)), "#FF800040")
    visualization_assert_equal(
        normalize_color({"r": 255, "g": 128, "b": 0, "a": 64}),
        "#FF800040",
    )
    with visualization_assert_raises(VisualizationColorError):
        normalize_color("not-a-color")
    with visualization_assert_raises(VisualizationColorError):
        normalize_color((1, 2))
    return {"cases": len(cases) + 3}


