@register_visualization_self_test(
    test_id="30.2.palette",
    name="Palette resolution",
    section=SELF_TEST_SECTION_COLORS_STYLES,
    tags=("colors", "palette"),
)
def _self_test_palette_resolution(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    palette = ColorPaletteConfig(
        background="white",
        foreground="black",
        role_colors={"receptor": "#abc", "ligand": "orange"},
        interaction_colors={"hbond": "cyan", "salt_bridge": "magenta"},
        hotspot_colors={"high": "red", "medium": "yellow"},
        pose_colors=("red", "green", "blue"),
        score_colors=("blue", "white", "red"),
    )
    visualization_assert_equal(palette.background, "#FFFFFF")
    visualization_assert_equal(palette.color_for_role("receptor"), "#AABBCC")
    visualization_assert_equal(palette.color_for_role("ligand"), COLOR_ORANGE)
    visualization_assert_equal(palette.color_for_role("solvent"), palette.missing)
    visualization_assert_equal(palette.color_for_interaction("hbond"), COLOR_CYAN)
    visualization_assert_equal(
        palette.color_for_interaction("hydrophobic"), palette.missing
    )
    for color in (*palette.pose_colors, *palette.score_colors):
        _assert_hex_color(color, alpha=False)
    visualization_assert_is_instance(palette.role_colors, Mapping)
    with visualization_assert_raises(TypeError):
        palette.role_colors[MolecularRole.RECEPTOR] = COLOR_BLACK  # type: ignore[index]
    with visualization_assert_raises(VisualizationConfigurationError):
        ColorPaletteConfig(pose_colors=())
    return {
        "roles": len(palette.role_colors),
        "interactions": len(palette.interaction_colors),
        "poses": len(palette.pose_colors),
    }


