@register_visualization_self_test(
    test_id="30.2.interaction_style",
    name="Interaction styles",
    section=SELF_TEST_SECTION_COLORS_STYLES,
    tags=("styles", "interactions"),
)
def _self_test_interaction_style(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    style = InteractionStyleConfig(
        render_mode="pseudobond",
        line_style="dashed",
        radius=0.2,
        opacity=0.8,
        family_colors={"hbond": "cyan", "salt_bridge": "magenta"},
        family_radii={"hbond": 0.1, "salt_bridge": 0.3},
    )
    visualization_assert_equal(style.color_for("hbond"), COLOR_CYAN)
    visualization_assert_equal(style.color_for("unknown"), DEFAULT_MISSING_COLOR)
    expected_radius = 0.1 * InteractionStrength.STRONG.radius_multiplier
    visualization_assert_near(
        style.radius_for("hbond", "strong"),
        max(MIN_RADIUS, min(MAX_RADIUS, expected_radius)),
    )
    expected_opacity = (
        0.8
        * InteractionStrength.WEAK.opacity_multiplier
        * ConfidenceLevel.LOW.opacity_multiplier
    )
    visualization_assert_near(
        style.opacity_for("weak", "low"),
        max(0.0, min(1.0, expected_opacity)),
    )
    visualization_assert_true(0.0 <= style.opacity_for("strong", "high") <= 1.0)
    with visualization_assert_raises(VisualizationConfigurationError):
        InteractionStyleConfig(radius=0.0)
    with visualization_assert_raises(VisualizationConfigurationError):
        InteractionStyleConfig(group_name="bad;group")
    return {"families": len(style.family_colors), "scaled": True}


