def _build_specification_self_test_fixture() -> Mapping[str, Any]:
    """Build a compact molecular specification fixture."""

    residue_path = MolecularPathSpec(
        model_id="1",
        chain_id="A",
        residue_number="42",
        residue_name="TYR",
        role=MolecularRole.RECEPTOR,
    )
    atom_ca = AtomSpec(
        path=residue_path.with_atom("CA", alt_loc="B"),
        serial_number=1,
        element="C",
        coordinate=(0.0, 0.0, 0.0),
        occupancy=1.0,
    )
    atom_cb = AtomSpec(
        path=residue_path.with_atom("CB"),
        serial_number=2,
        element="C",
        coordinate=(2.0, 0.0, 0.0),
    )
    residue = ResidueSpec(
        path=residue_path,
        atom_names=("CA", "CB", "CA"),
        center=(1.0, 0.0, 0.0),
        polymer_type="protein",
        one_letter_code="Y",
    )
    chain = ChainSpec(
        path=MolecularPathSpec(model_id="1", chain_id="A", role="receptor"),
        residue_keys=(residue.key,),
        polymer_type="protein",
        sequence="Y",
    )
    receptor_model = ModelSpec(
        model_id="1",
        name="receptor",
        role="receptor",
        chain_ids=("A", "A"),
    )
    ligand_model = ModelSpec(model_id="2", name="ligand", role="ligand")
    aromatic_group = MolecularGroupSpec(
        group_id="ring_1",
        kind="aromatic_ring",
        atoms=(atom_ca, atom_cb),
        normal=(0.0, 0.0, 2.0),
        role="receptor",
    )
    receptor = MolecularObjectSpec(
        object_id="receptor",
        name="Receptor",
        role="receptor",
        models=(receptor_model,),
        paths=(residue.path,),
    )
    ligand = MolecularObjectSpec(
        object_id="ligand",
        name="Ligand",
        role="ligand",
        models=(ligand_model,),
        score=0.75,
    )
    pose = PoseSpec(
        pose_id="pose_1",
        index=0,
        rank=1,
        ligand=ligand,
        affinity=-7.5,
        score=0.85,
        rmsd_lower_bound=0.2,
        rmsd_upper_bound=0.8,
    )
    structure = StructureSpec(
        structure_id="complex",
        models=(receptor_model, ligand_model),
        chains=(chain,),
        residues=(residue,),
        atoms=(atom_ca, atom_cb),
        groups=(aromatic_group,),
        poses=(pose,),
    )
    bundle = MolecularSpecificationBundle(
        receptor=receptor,
        ligands=(ligand,),
        poses=(pose,),
        structure=structure,
        metadata={"fixture": True},
    )
    return MappingProxyType(
        {
            "residue_path": residue_path,
            "atom_ca": atom_ca,
            "atom_cb": atom_cb,
            "residue": residue,
            "chain": chain,
            "receptor_model": receptor_model,
            "ligand_model": ligand_model,
            "group": aromatic_group,
            "receptor": receptor,
            "ligand": ligand,
            "pose": pose,
            "structure": structure,
            "bundle": bundle,
        }
    )


@register_visualization_self_test(
    test_id="30.3.coordinates",
    name="Coordinate normalization",
    section=SELF_TEST_SECTION_SPECIFICATIONS,
    tags=("specifications", "coordinates", "geometry"),
)
def _self_test_specification_coordinates(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    visualization_assert_equal(normalize_point3d((1, 2.5, -3)), (1.0, 2.5, -3.0))
    visualization_assert_equal(
        normalize_point3d({"x": 1, "y": 2, "z": 3}),
        (1.0, 2.0, 3.0),
    )
    unit = normalize_vector3d((0, 0, 4), unit=True)
    visualization_assert_equal(unit, (0.0, 0.0, 1.0))
    visualization_assert_equal(normalize_point3d(None, allow_none=True), None)
    if NUMPY_AVAILABLE:
        visualization_assert_equal(
            normalize_point3d(np.asarray([4.0, 5.0, 6.0])),
            (4.0, 5.0, 6.0),
        )
    with visualization_assert_raises(VisualizationCoordinateError):
        normalize_point3d((1, 2))
    with visualization_assert_raises(VisualizationCoordinateError):
        normalize_point3d((1, 2, math.inf))
    with visualization_assert_raises(VisualizationGeometryError):
        normalize_vector3d((0, 0, 0), unit=True)
    return {"numpy": NUMPY_AVAILABLE, "unit": unit}


