@register_visualization_self_test(
    test_id="30.3.selection_logic",
    name="Selection logic",
    section=SELF_TEST_SECTION_SPECIFICATIONS,
    tags=("specifications", "selections", "logic"),
)
def _self_test_selection_logic(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    residue = MolecularPathSpec(model_id="1", chain_id="A", residue_number="42")
    atom = residue.with_atom("CA")
    residue_selection = molecular_path_to_selection(residue)
    atom_selection = molecular_path_to_selection(atom)
    union = residue_selection | MolecularSelection("#2")
    intersection = MolecularSelection("#1") & MolecularSelection("/A")
    difference = MolecularSelection("#1") - MolecularSelection("solvent")
    negated = ~MolecularSelection("solvent")
    visualization_assert_true(union.is_compound)
    visualization_assert_contains(union.expression, " | ")
    visualization_assert_contains(intersection.expression, " & ")
    visualization_assert_contains(difference.expression, "~")
    visualization_assert_contains(negated.expression, "~")
    visualization_assert_true(selection_contains(residue_selection, atom_selection))
    visualization_assert_true(selection_equivalent(atom_selection, molecular_path_to_selection(atom)))
    simplified = simplify_molecular_paths((residue, atom, residue))
    visualization_assert_equal(simplified, (residue,))
    visualization_assert_equal(selection_union(MolecularSelection.none(), atom_selection), atom_selection)
    visualization_assert_true(selection_intersection(MolecularSelection.all(), atom_selection) == atom_selection)
    return {"union": union.expression, "simplified": len(simplified)}


