SELF_TEST_SECTION_INTERACTIONS: Final[str] = "30.4"


def _build_interaction_self_test_fixture() -> Mapping[str, Any]:
    """Build compact interaction fixtures."""

    def atom(
        model: str,
        chain: str,
        number: str,
        name: str,
        coordinate: Point3D,
        role: MolecularRole,
        residue_name: str,
        serial: int,
    ) -> AtomSpec:
        path = MolecularPathSpec(
            model_id=model,
            chain_id=chain,
            residue_number=number,
            residue_name=residue_name,
            atom_name=name,
            role=role,
        )
        return AtomSpec(path=path, serial_number=serial, coordinate=coordinate)

    ligand_o = atom("2", "L", "1", "O1", (0.0, 0.0, 0.0), MolecularRole.LIGAND, "LIG", 1)
    ligand_c = atom("2", "L", "1", "C2", (0.5, 0.0, 0.0), MolecularRole.LIGAND, "LIG", 2)
    tyr_oh = atom("1", "A", "42", "OH", (2.8, 0.0, 0.0), MolecularRole.RECEPTOR, "TYR", 3)
    lys_nz = atom("1", "A", "43", "NZ", (3.2, 1.0, 0.0), MolecularRole.RECEPTOR, "LYS", 4)
    phe_cz = atom("1", "A", "44", "CZ", (4.0, 0.0, 0.0), MolecularRole.RECEPTOR, "PHE", 5)
    asp_od = atom("1", "A", "45", "OD1", (3.0, -1.0, 0.0), MolecularRole.RECEPTOR, "ASP", 6)
    distant_ca = atom("1", "A", "90", "CA", (15.0, 0.0, 0.0), MolecularRole.RECEPTOR, "ALA", 7)

    hbond = coerce_visual_interaction({
        "interaction_id": "hb_1",
        "family": "hbond",
        "donor": ligand_o,
        "acceptor": tyr_oh,
        "strength": "strong",
        "confidence": "high",
        "distance": 2.8,
        "angle": 165.0,
        "score": 0.92,
        "pose_id": "pose_1",
    })
    hydrophobic = coerce_visual_interaction({
        "interaction_id": "hyd_1",
        "family": "hydrophobic",
        "ligand_atom": ligand_c,
        "protein_atom": phe_cz,
        "strength": "moderate",
        "distance": 3.5,
        "score": 0.65,
        "pose_id": "pose_1",
    })
    salt = coerce_visual_interaction({
        "interaction_id": "salt_1",
        "family": "salt_bridge",
        "positive_group": lys_nz,
        "negative_group": asp_od,
        "strength": "strong",
        "distance": 3.1,
        "score": 0.88,
        "pose_id": "pose_2",
    })
    distant = coerce_visual_interaction({
        "interaction_id": "contact_far",
        "family": "contact",
        "source": ligand_c,
        "target": distant_ca,
        "strength": "weak",
        "distance": 15.0,
        "score": 0.1,
        "pose_id": "pose_2",
    })
    collection = VisualInteractionCollection(
        interactions=(hbond, hydrophobic, salt, distant),
        name="Interaction self-test",
    )
    return MappingProxyType({
        "ligand_o": ligand_o,
        "ligand_c": ligand_c,
        "tyr_oh": tyr_oh,
        "lys_nz": lys_nz,
        "phe_cz": phe_cz,
        "asp_od": asp_od,
        "distant_ca": distant_ca,
        "hbond": hbond,
        "hydrophobic": hydrophobic,
        "salt": salt,
        "distant": distant,
        "collection": collection,
    })


@register_visualization_self_test(
    test_id="30.4.endpoints_geometry",
    name="Interaction endpoints and geometry",
    section=SELF_TEST_SECTION_INTERACTIONS,
    tags=("interactions", "endpoints", "geometry"),
)
def _self_test_interaction_endpoints_geometry(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    fixture = _build_interaction_self_test_fixture()
    source = coerce_interaction_endpoint(fixture["ligand_o"])
    target = coerce_interaction_endpoint(fixture["tyr_oh"])
    visualization_assert_equal(source.role, MolecularRole.LIGAND)
    visualization_assert_equal(target.role, MolecularRole.RECEPTOR)
    visualization_assert_equal(source.selection.expression, "#2/L:1@O1")
    visualization_assert_equal(target.selection.expression, "#1/A:42@OH")
    interaction = fixture["hbond"]
    visualization_assert_near(interaction.distance or 0.0, 2.8)
    visualization_assert_equal(interaction.midpoint, (1.4, 0.0, 0.0))
    visualization_assert_equal(interaction.direction, (1.0, 0.0, 0.0))
    visualization_assert_equal(interaction.residue_pair[0][2], "1")
    visualization_assert_equal(interaction.residue_pair[1][2], "42")
    point_endpoint = coerce_interaction_endpoint({"point": (1.0, 2.0, 3.0)})
    visualization_assert_equal(point_endpoint.point, (1.0, 2.0, 3.0))
    with visualization_assert_raises(VisualizationInteractionError):
        InteractionEndpointSpec()
    return {"source": source.selection.expression, "distance": interaction.distance}


