    reverse = replace(hbond, interaction_id="hb_reverse", source=hbond.target, target=hbond.source)
    deduplicated = deduplicate_visual_interactions((hbond, reverse))
    directed = deduplicate_visual_interactions((hbond, reverse), directed=True)
