    sorted_items = sort_visual_interactions(fixture["collection"].interactions)
    visualization_assert_equal(sorted_items[0].strength, InteractionStrength.STRONG)
    visualization_assert_true(bool(fixture["collection"].involved_selection))
    with visualization_assert_raises(VisualizationInteractionError):
        VisualInteractionCollection((hbond, hbond))
    return {"deduplicated": len(deduplicated), "families": len(grouped)}


