def _build_scene_command_self_test_fixture() -> Mapping[str, Any]:
    """Build a compact scene and command fixture."""

    molecular = _build_specification_self_test_fixture()
    bundle = molecular["bundle"]
    selections = build_molecular_selection_bundle(bundle)
    scene = build_scene_preparation_spec(
        molecular_input=bundle,
        overrides={
            "hide_ions": True,
            "hide_hydrogens": True,
            "focus_distance": 4.5,
            "context_distance": 7.5,
        },
    )
    receptor = build_receptor_visualization_spec(
        bundle,
        show_context=True,
        surface_overlay=True,
    )
    ligand = build_ligand_visualization_spec(
        bundle,
        display_mode=PoseDisplayMode.ALL,
        show_cofactors=False,
    )
    camera = coerce_camera_framing_spec(
        {
            "state": {"view": "front", "clip": True},
            "framing_target": "custom",
        },
        sources=(molecular["atom_ca"], molecular["atom_cb"]),
    )
    return MappingProxyType(
        {
            **dict(molecular),
            "selections": selections,
            "scene": scene,
            "receptor_visualization": receptor,
            "ligand_visualization": ligand,
            "camera": camera,
        }
    )


def _build_scene_command_self_test_plan(
    fixture: Mapping[str, Any],
    *,
    snapshot_directory: Optional[Path] = None,
) -> VisualizationPlan:
    """Build a representative scene plan."""

    plans: List[VisualizationPlan] = [
        build_scene_preparation_plan(fixture["scene"]),
        build_receptor_visualization_plan(
            fixture["bundle"],
            spec=fixture["receptor_visualization"],
        ),
        build_ligand_visualization_plan(
            fixture["bundle"],
            spec=fixture["ligand_visualization"],
        ),
        build_camera_plan(fixture["camera"]),
    ]
    if snapshot_directory is not None:
        snapshots = SnapshotCollection(
            requests=(
                SnapshotRequestSpec(
                    snapshot_id="front",
                    filename=snapshot_directory / "front.png",
                    width=640,
                    height=480,
                    supersample=1,
                    view=StandardView.FRONT,
                    overwrite=True,
                ),
            ),
            restore_camera=True,
        )
        plans.append(build_snapshot_plan(snapshots))
    return merge_visualization_plans(
        *plans,
        plan_id="self-test-scene",
        name="Self-test scene",
    )


