@register_visualization_self_test(
    test_id="30.5.backend_execution",
    name="Backend execution",
    section=SELF_TEST_SECTION_SCENE_COMMANDS,
    tags=("commands", "backend", "execution"),
)
def _self_test_backend_execution(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    executed: List[str] = []

    class _Session:
        logger = None

    def runner(session: Any, command: str, *, log: bool = False) -> str:
        visualization_assert_is_instance(session, _Session)
        executed.append(command)
        return f"ok:{len(executed)}"

    action = VisualizationAction(
        action_id="ligand:test",
        operation=PlanOperation.SHOW_LIGAND,
        layer=VisualLayer.LIGAND,
        selection=MolecularSelection(expression="#2", kind=SelectionKind.MODEL),
        parameters={
            "representation": MolecularRepresentation.STICKS.value,
            "color": DEFAULT_LIGAND_COLOR,
            "opacity": 1.0,
            "radius": 0.25,
        },
    )
    plan = VisualizationPlan(
        plan_id="backend-test",
        name="Backend test",
        actions=(action,),
        execution_mode=ExecutionMode.IMMEDIATE,
    )
    config_value = BackendConfig(
        execution_mode=ExecutionMode.IMMEDIATE,
        error_handling=ErrorHandlingMode.COLLECT,
        wait_frames=0,
        log_commands=False,
    )
    backend = create_chimerax_backend(
        _Session(),
        config=config_value,
        runner=runner,
        activate=True,
    )
    result = backend.execute_plan(plan, mode=ExecutionMode.IMMEDIATE)
    visualization_assert_true(result.success)
    visualization_assert_equal(result.executed_count, result.command_count)
    visualization_assert_equal(len(executed), result.command_count)
    visualization_assert_true(all(command.result_repr for command in result.commands))
    backend.close()
    visualization_assert_equal(backend.state, BackendState.CLOSED)
    with visualization_assert_raises(VisualizationStateError):
        backend.execute_plan(plan, mode=ExecutionMode.IMMEDIATE)
    return {"commands": len(executed), "state": result.state.value}


@register_visualization_self_test(
    test_id="30.5.backend_failure",
    name="Backend failure handling",
    section=SELF_TEST_SECTION_SCENE_COMMANDS,
    tags=("commands", "backend", "negative"),
)
def _self_test_backend_failure(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    class _Session:
        logger = None

    def runner(session: Any, command: str, *, log: bool = False) -> None:
        raise RuntimeError("simulated command failure")

    command = CommandSpec(command_id="failure", text="show #1")
    result = execute_chimerax_command(
        command,
        session=_Session(),
        runner=runner,
        config=BackendConfig(
            execution_mode=ExecutionMode.IMMEDIATE,
            error_handling=ErrorHandlingMode.COLLECT,
            wait_frames=0,
            log_commands=False,
        ),
        mode=ExecutionMode.IMMEDIATE,
    )
    visualization_assert_equal(result.status, CommandStatus.FAILED)
    visualization_assert_equal(result.error_type, "RuntimeError")
    visualization_assert_contains(result.error_message or "", "simulated command failure")
    with visualization_assert_raises(VisualizationExecutionError):
        execute_chimerax_command(
            command,
            session=_Session(),
            runner=runner,
            config=BackendConfig(
                execution_mode=ExecutionMode.IMMEDIATE,
                error_handling=ErrorHandlingMode.RAISE,
                wait_frames=0,
                log_commands=False,
            ),
            mode=ExecutionMode.IMMEDIATE,
        )
    return {"status": result.status.value, "error": result.error_type}



