def _build_multipose_hotspot_self_test_fixture() -> Mapping[str, Any]:
    """Build compact multipose fixtures."""

    base = _build_interaction_self_test_fixture()
    hbond_1 = base["hbond"]
    hydrophobic_1 = base["hydrophobic"]
    hbond_2 = replace(hbond_1, interaction_id="hb_2", pose_id="pose_2", score=0.84)
    salt_2 = base["salt"]
    hydrophobic_3 = replace(
        hydrophobic_1,
        interaction_id="hyd_3",
        pose_id="pose_3",
        score=0.58,
    )
    distant_3 = replace(base["distant"], interaction_id="contact_3", pose_id="pose_3")
    interactions = MappingProxyType({
        "pose_1": VisualInteractionCollection((hbond_1, hydrophobic_1), pose_id="pose_1"),
        "pose_2": VisualInteractionCollection((hbond_2, salt_2), pose_id="pose_2"),
        "pose_3": VisualInteractionCollection((hydrophobic_3, distant_3), pose_id="pose_3"),
    })
    poses = (
        {
            "pose_id": "pose_1",
            "selection": "#2.1",
            "index": 0,
            "rank": 2,
            "score": 0.82,
            "affinity": -7.4,
            "cluster_id": "cluster_a",
            "interaction_ids": ("hb_1", "hyd_1"),
            "metadata": {"consensus": True},
        },
        {
            "pose_id": "pose_2",
            "selection": "#2.2",
            "index": 1,
            "rank": 1,
            "score": 0.91,
            "affinity": -8.1,
            "cluster_id": "cluster_a",
            "interaction_ids": ("hb_2", "salt_1"),
            "metadata": {"complementary": True},
        },
        {
            "pose_id": "pose_3",
            "selection": "#2.3",
            "index": 2,
            "rank": 3,
            "score": 0.67,
            "affinity": -6.8,
            "cluster_id": "cluster_b",
            "interaction_ids": ("hyd_3", "contact_3"),
            "metadata": {"consensus": True, "complementary": True},
        },
    )
    collection = build_pose_visual_collection(
        poses,
        active_pose_id="pose_2",
        reference_pose_id="pose_1",
        interactions=interactions,
    )
    residues = MappingProxyType({
        pose_id: build_involved_residue_collection(items, pose_count=3)
        for pose_id, items in interactions.items()
    })
    hotspots = MappingProxyType({
        pose_id: build_hotspot_collection(
            items,
            distance_cutoff=4.5,
            min_residues=1,
            allow_singletons=True,
            pose_count=3,
        )
        for pose_id, items in residues.items()
    })
    shared_hotspot = hotspots["pose_1"].hotspots[0]
    hotspot_sources = MappingProxyType({
        "pose_1": HotspotCollection((replace(shared_hotspot, hotspot_id="hs_1", pose_ids=("pose_1",)),), pose_count=3),
        "pose_2": HotspotCollection((replace(shared_hotspot, hotspot_id="hs_2", pose_ids=("pose_2",), score=shared_hotspot.score + 0.1),), pose_count=3),
        "pose_3": HotspotCollection((hotspots["pose_3"].hotspots[0],), pose_count=3),
    })
    coverage = PoseCoverageCollection((
        PoseCoverageSpec(
            "pose_1",
            selection="#2.1",
            residue_ids=("#1/A:42", "#1/A:44"),
            families=("hbond", "hydrophobic"),
            interaction_types=("hbond", "hydrophobic"),
            hotspot_ids=("hotspot_a",),
            interaction_ids=("hb_1", "hyd_1"),
            score=0.82,
            affinity=-7.4,
            rank=2,
        ),
        PoseCoverageSpec(
            "pose_2",
            selection="#2.2",
            residue_ids=("#1/A:42", "#1/A:43", "#1/A:45"),
            families=("hbond", "salt_bridge"),
            interaction_types=("hbond", "salt_bridge"),
            hotspot_ids=("hotspot_a", "hotspot_b"),
            interaction_ids=("hb_2", "salt_1"),
            score=0.91,
            affinity=-8.1,
            rank=1,
        ),
        PoseCoverageSpec(
            "pose_3",
            selection="#2.3",
            residue_ids=("#1/A:44", "#1/A:90"),
            families=("hydrophobic", "contact"),
            interaction_types=("hydrophobic", "contact"),
            hotspot_ids=("hotspot_c",),
            interaction_ids=("hyd_3", "contact_3"),
            score=0.67,
            affinity=-6.8,
            rank=3,
        ),
    ))
    return MappingProxyType({
        "collection": collection,
        "poses": poses,
        "interactions": interactions,
        "residues": residues,
        "hotspots": hotspots,
        "hotspot_sources": hotspot_sources,
        "coverage": coverage,
    })


