@register_visualization_self_test(
    test_id="30.6.interaction_consensus",
    name="Interaction consensus and persistence",
    section=SELF_TEST_SECTION_MULTIPOSE_HOTSPOTS,
    tags=("consensus", "interactions", "persistence"),
)
def _self_test_interaction_consensus(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    interactions = _build_multipose_hotspot_self_test_fixture()["interactions"]
    consensus = build_interaction_consensus(
        interactions,
        metric="weighted_frequency",
        pose_weights={"pose_1": 2.0, "pose_2": 1.0, "pose_3": 1.0},
        persistence_threshold=0.2,
        consensus_threshold=0.5,
        core_threshold=0.8,
    )
    visualization_assert_equal(consensus.pose_count, 3)
    visualization_assert_equal(consensus.source_count, 6)
    visualization_assert_true(len(consensus.items) >= 4)
    hbond = next(item for item in consensus if item.family is InteractionFamily.HBOND)
    visualization_assert_near(hbond.frequency, 2.0 / 3.0)
    visualization_assert_near(hbond.weighted_frequency, 0.75)
    visualization_assert_equal(hbond.persistence, PersistenceLevel.PERSISTENT)
    visualization_assert_true(hbond.persistent)
    visualization_assert_true(bool(consensus.selection))
    return {"items": len(consensus), "hbond_frequency": hbond.frequency}


