@register_visualization_self_test(
    test_id="30.6.consensus_state",
    name="Consensus state persistence",
    section=SELF_TEST_SECTION_MULTIPOSE_HOTSPOTS,
    tags=("consensus", "state", "serialization"),
)
def _self_test_consensus_state(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    interactions = _build_multipose_hotspot_self_test_fixture()["interactions"]
    collection = build_interaction_consensus(interactions)
    state = create_consensus_state(collection, state_id="state_a")
    restored = restore_consensus_state(json.loads(consensus_state_to_json(state, indent=None)))
    visualization_assert_equal(restored.collection.to_dict(), state.collection.to_dict())
    reduced = ConsensusCollection(
        items=collection.items[:-1],
        metric=collection.metric,
        pose_count=collection.pose_count,
        source_count=collection.source_count - 1,
        persistence_threshold=collection.persistence_threshold,
        consensus_threshold=collection.consensus_threshold,
        core_threshold=collection.core_threshold,
    )
    state_b = create_consensus_state(reduced, state_id="state_b")
    diff = compare_consensus_states(state, state_b)
    visualization_assert_equal(len(diff.removed_ids), 1)
    merged = merge_consensus_states(state, state_b, state_id="merged")
    visualization_assert_true(len(merged.collection.items) >= len(collection.items))
    return {"removed": len(diff.removed_ids), "merged": len(merged.collection.items)}


