@register_visualization_self_test(
    test_id="30.6.pose_coverage",
    name="Pose coverage and similarity",
    section=SELF_TEST_SECTION_MULTIPOSE_HOTSPOTS,
    tags=("complementarity", "coverage", "similarity"),
)
def _self_test_pose_coverage(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    coverage = _build_multipose_hotspot_self_test_fixture()["coverage"]
    visualization_assert_equal(len(coverage), 3)
    visualization_assert_equal(coverage.universe.counts["residues"], 5)
    visualization_assert_true(coverage.universe.total_count > 6)
    similarity = pose_coverage_similarity(coverage.poses[0], coverage.poses[1])
    distance = pose_coverage_distance(coverage.poses[0], coverage.poses[1])
    visualization_assert_true(0.0 < similarity < 1.0)
    visualization_assert_near(distance, 1.0 - similarity)
    visualization_assert_equal(coverage.pose_map["pose_2"].rank, 1)
    with visualization_assert_raises(VisualizationSpecificationError):
        CoverageUniverseSpec().domain("unknown")
    return {"features": coverage.universe.total_count, "similarity": similarity}


@register_visualization_self_test(
    test_id="30.6.complementarity_selection",
    name="Complementary pose selection",
    section=SELF_TEST_SECTION_MULTIPOSE_HOTSPOTS,
    tags=("complementarity", "selection", "optimization"),
)
def _self_test_complementarity_selection(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    coverage = _build_multipose_hotspot_self_test_fixture()["coverage"]
    greedy = select_complementary_poses(coverage, mode="greedy", set_size=2)
    optimal = select_complementary_poses(coverage, mode="optimal", set_size=2)
    diverse = select_complementary_poses(coverage, mode="diverse", set_size=2)
    manual = select_complementary_poses(
        coverage,
        mode="manual",
        set_size=2,
        selected_pose_ids=("pose_1", "pose_3"),
    )
    for result in (greedy, optimal, diverse, manual):
        visualization_assert_equal(len(result.selected_pose_ids), 2)
        visualization_assert_equal(len(set(result.selected_pose_ids)), 2)
        visualization_assert_equal(len(result.steps), 2)
        visualization_assert_true(result.coverage_fraction > 0.0)
        visualization_assert_true(all(
            left.cumulative_fraction <= right.cumulative_fraction
            for left, right in zip(result.steps, result.steps[1:])
        ))
    visualization_assert_true(optimal.exact)
    visualization_assert_sequence_equal(manual.selected_pose_ids, ("pose_1", "pose_3"))
    matrix = complementarity_pairwise_matrix(greedy)
    visualization_assert_near(matrix["pose_1"]["pose_2"], matrix["pose_2"]["pose_1"])
    return {"greedy": greedy.selected_pose_ids, "optimal": optimal.selected_pose_ids}


