# =============================================================================

SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS: Final[str] = "30.7"


def _build_snapshot_backend_self_test_collection(directory: Path) -> SnapshotCollection:
    """Build compact snapshot requests."""

    postprocess = ImagePostprocessSpec(
        enabled=True,
        size=(160, 120),
        fit_mode=ImageFitMode.CONTAIN,
        background="#FFFFFF",
        output_format=SnapshotFormat.JPEG,
    )
    return SnapshotCollection(
        requests=(
            SnapshotRequestSpec(
                snapshot_id="front",
                filename=directory / "front.png",
                width=320,
                height=240,
                supersample=1,
                view=StandardView.FRONT,
                overwrite=True,
            ),
            SnapshotRequestSpec(
                snapshot_id="detail",
                filename=directory / "detail.png",
                width=400,
                height=300,
                supersample=2,
                view=StandardView.ISOMETRIC,
                postprocess=postprocess,
                overwrite=True,
                optional=True,
            ),
        ),
        name="self-test-snapshots",
        restore_camera=True,
        stop_on_error=False,
    )


class _SnapshotSelfTestUI:
    is_gui = True


class _SnapshotSelfTestSession:
    """Small ChimeraX session double."""

    name = "self-test-session"
    version = "test"
    logger = None
    models: Tuple[Any, ...] = ()
    main_view = object()
    ui = _SnapshotSelfTestUI()
    closed = False


@register_visualization_self_test(
    test_id="30.7.snapshot_request",
    name="Snapshot request specification",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "specification", "serialization"),
)
def _self_test_snapshot_request(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    request = SnapshotRequestSpec(
        snapshot_id="publication",
        filename="figure.jpeg",
        format=SnapshotFormat.JPEG,
        width=1200,
        height=900,
        supersample=2,
        quality=92,
        dpi=300,
        view=StandardView.ISOMETRIC,
        overwrite=True,
    )
    visualization_assert_equal(request.filename.suffix, ".jpeg")
    visualization_assert_sequence_equal(request.size, (1200, 900))
    visualization_assert_sequence_equal(request.render_size, (2400, 1800))
    visualization_assert_equal(request.pixel_count, 4_320_000)
    visualization_assert_equal(request.output_path, request.filename)
    restored = coerce_snapshot_request(json.loads(json.dumps(request.to_dict())))
    visualization_assert_equal(restored.to_dict(), request.to_dict())
    visualization_assert_fingerprint_stable(request, restored)
    return {"pixels": request.pixel_count, "format": request.format.value}


@register_visualization_self_test(
    test_id="30.7.snapshot_collections",
    name="Snapshot collections",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "collections", "views", "poses"),
)
def _self_test_snapshot_collections(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    with visualization_test_workspace(prefix="dockanalyzer_snapshot_collection_") as workspace:
        views = build_view_snapshot_collection(
            (StandardView.FRONT, StandardView.TOP, StandardView.ISOMETRIC),
            directory=workspace,
            prefix="view",
            overrides={"width": 640, "height": 480, "supersample": 1, "overwrite": True},
        )
        visualization_assert_equal(len(views.requests), 3)
        visualization_assert_equal(len(set(views.output_paths)), 3)
        visualization_assert_sequence_equal(
            tuple(item.view for item in views.requests),
            (StandardView.FRONT, StandardView.TOP, StandardView.ISOMETRIC),
        )
        multipose = _build_multipose_hotspot_self_test_fixture()["collection"]
        poses = build_pose_snapshot_collection(
            multipose,
            directory=workspace,
            prefix="pose",
            overrides={"width": 500, "height": 400, "supersample": 1, "overwrite": True},
        )
        visualization_assert_equal(len(poses.requests), len(multipose.poses))
        visualization_assert_true(all("pose_id" in item.metadata for item in poses.requests))
        with visualization_assert_raises(VisualizationSnapshotError):
            SnapshotCollection(requests=(views.requests[0], views.requests[0]))
    return {"views": len(views.requests), "poses": len(poses.requests)}


@register_visualization_self_test(
    test_id="30.7.snapshot_plan",
    name="Snapshot plan actions",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "plan", "dependencies"),
)
def _self_test_snapshot_plan(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    with visualization_test_workspace(prefix="dockanalyzer_snapshot_plan_") as workspace:
        collection = _build_snapshot_backend_self_test_collection(workspace)
        base = VisualizationPlan(
            plan_id="snapshot-base",
            name="Snapshot base",
            actions=(
                VisualizationAction(
                    action_id="camera:frame",
                    operation=PlanOperation.SET_CAMERA,
                    layer=VisualLayer.CAMERA,
                    parameters={"view": StandardView.FRONT.value},
                ),
            ),
        )
        attached = attach_snapshots(base, collection)
        snapshot_actions = tuple(
            action for action in attached.actions
            if action.operation is PlanOperation.SAVE_SNAPSHOT
        )
        visualization_assert_equal(len(snapshot_actions), 2)
        visualization_assert_contains(snapshot_actions[0].depends_on, "camera:frame")
        visualization_assert_contains(snapshot_actions[1].depends_on, snapshot_actions[0].action_id)
        visualization_assert_equal(snapshot_actions[1].parameters["output_path"], str(collection.requests[1].output_path))
        visualization_assert_false(attached.validate())
        rebuilt = build_snapshot_plan(collection)
        visualization_assert_equal(len(rebuilt.actions), 2)
        visualization_assert_fingerprint_stable(rebuilt, coerce_visualization_plan(rebuilt.to_dict()))
    return {"actions": len(snapshot_actions), "optional": snapshot_actions[1].optional}


@register_visualization_self_test(
    test_id="30.7.image_inspection",
    name="Image inspection",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "images", "pillow", "filesystem"),
    requires=("pillow", "filesystem"),
)
def _self_test_image_inspection(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    with visualization_test_workspace(prefix="dockanalyzer_image_inspection_") as workspace:
        path = workspace / "rgba.png"
        image = Image.new("RGBA", (64, 48), (10, 20, 30, 128))  # type: ignore[union-attr]
        image.save(path, format="PNG", dpi=(144, 144))
        info = inspect_image_file(path)
        visualization_assert_equal(info.format, "PNG")
        visualization_assert_equal(info.mode, "RGBA")
        visualization_assert_sequence_equal(info.size, (64, 48))
        visualization_assert_true(info.has_alpha)
        visualization_assert_true((info.file_size or 0) > 0)
        restored = coerce_image_info(info.to_dict())
        visualization_assert_equal(restored.to_dict(), info.to_dict())
        visualization_assert_fingerprint_stable(info, restored)
        with visualization_assert_raises(VisualizationImageError):
            inspect_image_file(workspace / "missing.png")
    return {"format": info.format, "size": info.size, "alpha": info.has_alpha}


@register_visualization_self_test(
    test_id="30.7.image_postprocess",
    name="Image post-processing",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "images", "pillow", "postprocess"),
    requires=("pillow", "filesystem"),
)
def _self_test_image_postprocess(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    with visualization_test_workspace(prefix="dockanalyzer_image_process_") as workspace:
        source = workspace / "source.png"
        image = Image.new("RGBA", (120, 100), (255, 255, 255, 0))  # type: ignore[union-attr]
        for x in range(20, 100):
            for y in range(15, 85):
                image.putpixel((x, y), (200, 20, 40, 220))
        image.save(source, format="PNG", dpi=(96, 96))
        destination = workspace / "processed.jpg"
        spec = ImagePostprocessSpec(
            enabled=True,
            trim=True,
            size=(80, 60),
            fit_mode=ImageFitMode.STRETCH,
            background="#FFFFFF",
            sharpen=True,
            output_format=SnapshotFormat.JPEG,
        )
        info = postprocess_image_file(source, spec, destination=destination, overwrite=True)
        visualization_assert_true(destination.is_file())
        visualization_assert_equal(info.format, "JPEG")
        visualization_assert_equal(info.mode, "RGB")
        visualization_assert_sequence_equal(info.size, (80, 60))
        visualization_assert_false(info.has_alpha)
        visualization_assert_sequence_equal(
            fit_image_dimensions((400, 200), (100, 100), fit_mode=ImageFitMode.CONTAIN),
            (100, 50),
        )
        with visualization_assert_raises(VisualizationImageError):
            postprocess_image_file(source, spec, destination=destination, overwrite=False)
    return {"format": info.format, "size": info.size}


@register_visualization_self_test(
    test_id="30.7.snapshot_manifest",
    name="Snapshot manifest",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "manifest", "serialization"),
)
def _self_test_snapshot_manifest(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    collection = SnapshotCollection(
        requests=(
            SnapshotRequestSpec(snapshot_id="one", filename="one.png"),
            SnapshotRequestSpec(snapshot_id="two", filename="two.png"),
        ),
        name="manifest-test",
    )
    results = (
        SnapshotResultSpec("one", "one.png", success=True, duration=0.1),
        SnapshotResultSpec("two", "two.png", success=False, duration=0.2, error="simulated"),
    )
    plan = build_snapshot_plan(collection)
    manifest = create_snapshot_manifest(collection, results, visualization=plan)
    visualization_assert_equal(len(manifest.successful), 1)
    visualization_assert_equal(len(manifest.failed), 1)
    visualization_assert_true(bool(manifest.visualization_fingerprint))
    summary = summarize_snapshot_manifest(manifest)
    visualization_assert_equal(summary["successful"], 1)
    visualization_assert_equal(summary["failed"], 1)
    visualization_assert_near(summary["duration"], 0.3)
    restored = SnapshotManifestSpec(**json.loads(json.dumps(manifest.to_dict())))
    visualization_assert_equal(restored.to_dict(), manifest.to_dict())
    visualization_assert_fingerprint_stable(manifest, restored)
    with visualization_assert_raises(VisualizationSnapshotError):
        SnapshotResultSpec("bad", "bad.png", success=True, error="not allowed")
    return {"successful": len(manifest.successful), "failed": len(manifest.failed)}


@register_visualization_self_test(
    test_id="30.7.backend_discovery",
    name="ChimeraX backend discovery",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "backend", "discovery"),
)
def _self_test_backend_discovery(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    unavailable = discover_chimerax_backend(None, runner=lambda session, command: None)
    visualization_assert_false(unavailable.available)
    visualization_assert_equal(unavailable.state, BackendState.UNAVAILABLE)
    visualization_assert_true(bool(unavailable.reason))
    session = _SnapshotSelfTestSession()
    runner = lambda current, command: command
    available = discover_chimerax_backend(session, runner=runner)
    visualization_assert_true(available.available)
    visualization_assert_equal(available.state, BackendState.AVAILABLE)
    visualization_assert_equal(available.session_name, session.name)
    visualization_assert_equal(available.version, session.version)
    visualization_assert_true(available.has_gui)
    visualization_assert_false(validate_chimerax_session(session))
    visualization_assert_equal(resolve_chimerax_session(session), session)
    visualization_assert_equal(resolve_chimerax_runner(runner), runner)
    with visualization_assert_raises(VisualizationBackendError):
        resolve_chimerax_runner("invalid")
    return {"available": available.available, "runner": available.runner_name}


@register_visualization_self_test(
    test_id="30.7.backend_modes",
    name="ChimeraX backend modes",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "backend", "modes"),
)
def _self_test_backend_modes(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    command = CommandSpec(command_id="mode", text="show #1")
    config_value = BackendConfig(wait_frames=0, error_handling=ErrorHandlingMode.COLLECT)
    expected = {
        ExecutionMode.DEFERRED: CommandStatus.PENDING,
        ExecutionMode.DRY_RUN: CommandStatus.VALIDATED,
        ExecutionMode.EXPORT_ONLY: CommandStatus.SKIPPED,
    }
    statuses: Dict[str, str] = {}
    for mode, status in expected.items():
        result = execute_chimerax_command(command, config=config_value, mode=mode)
        visualization_assert_equal(result.status, status)
        statuses[mode.value] = result.status.value
    comment = execute_chimerax_command(
        CommandSpec(command_id="comment", text="# note"),
        config=config_value,
        mode=ExecutionMode.DRY_RUN,
    )
    visualization_assert_equal(comment.status, CommandStatus.SKIPPED)
    script = CommandScriptSpec(
        plan_id="modes",
        commands=(command, CommandSpec(command_id="second", text="hide #1", sequence=1)),
    )
    results = execute_chimerax_script(script, config=config_value, mode=ExecutionMode.DRY_RUN)
    visualization_assert_true(all(item.status is CommandStatus.VALIDATED for item in results))
    return {"statuses": statuses, "script_commands": len(results)}


@register_visualization_self_test(
    test_id="30.7.runner_signatures",
    name="ChimeraX runner signatures",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "backend", "runner"),
)
def _self_test_runner_signatures(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    session = _SnapshotSelfTestSession()
    calls: List[Tuple[str, bool]] = []

    def runner_with_log(current: Any, command: str, *, log: bool = False) -> str:
        visualization_assert_equal(current, session)
        calls.append((command, log))
        return "logged"

    def runner_without_log(current: Any, command: str) -> str:
        visualization_assert_equal(current, session)
        calls.append((command, False))
        return "plain"

    config_logged = BackendConfig(
        execution_mode=ExecutionMode.IMMEDIATE,
        error_handling=ErrorHandlingMode.COLLECT,
        wait_frames=0,
        log_commands=True,
    )
    first = execute_chimerax_command(
        "show #1",
        session=session,
        runner=runner_with_log,
        config=config_logged,
        mode=ExecutionMode.IMMEDIATE,
    )
    second = execute_chimerax_command(
        "hide #1",
        session=session,
        runner=runner_without_log,
        config=config_logged,
        mode=ExecutionMode.IMMEDIATE,
    )
    visualization_assert_equal(first.status, CommandStatus.EXECUTED)
    visualization_assert_equal(second.status, CommandStatus.EXECUTED)
    visualization_assert_sequence_equal(calls, (("show #1", True), ("hide #1", False)))
    visualization_assert_contains(first.result_repr or "", "logged")
    visualization_assert_contains(second.result_repr or "", "plain")
    return {"calls": len(calls)}


@register_visualization_self_test(
    test_id="30.7.backend_lifecycle",
    name="ChimeraX backend lifecycle",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "backend", "lifecycle"),
)
def _self_test_backend_lifecycle(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    session = _SnapshotSelfTestSession()
    executed: List[str] = []

    def runner(current: Any, command: str) -> str:
        executed.append(command)
        return command

    backend = create_chimerax_backend(
        session,
        config=BackendConfig(
            execution_mode=ExecutionMode.IMMEDIATE,
            error_handling=ErrorHandlingMode.COLLECT,
            wait_frames=0,
        ),
        runner=runner,
        activate=False,
    )
    visualization_assert_equal(backend.state, BackendState.AVAILABLE)
    visualization_assert_true(backend.available)
    backend.activate()
    visualization_assert_true(backend.active)
    result = backend.execute_command("show #1", mode=ExecutionMode.IMMEDIATE)
    visualization_assert_equal(result.status, CommandStatus.EXECUTED)
    backend.close()
    visualization_assert_equal(backend.state, BackendState.CLOSED)
    visualization_assert_false(backend.available)
    with visualization_assert_raises(VisualizationStateError):
        backend.activate()
    with visualization_assert_raises(VisualizationStateError):
        backend.execute_command("hide #1")
    return {"commands": len(executed), "state": backend.state.value}


@register_visualization_self_test(
    test_id="30.7.snapshot_backend",
    name="Snapshot backend execution",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "snapshots", "execution", "pillow"),
    requires=("pillow", "filesystem"),
)
def _self_test_snapshot_backend_execution(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    import shlex as _shlex

    session = _SnapshotSelfTestSession()
    executed: List[str] = []
    with visualization_test_workspace(prefix="dockanalyzer_snapshot_backend_") as workspace:
        collection = SnapshotCollection(
            requests=(
                SnapshotRequestSpec(
                    snapshot_id="backend",
                    filename=workspace / "backend.png",
                    width=96,
                    height=72,
                    supersample=1,
                    overwrite=True,
                ),
            ),
            name="backend-snapshot",
        )
        plan = build_snapshot_plan(collection)

        def runner(current: Any, command: str, *, log: bool = False) -> str:
            executed.append(command)
            tokens = _shlex.split(command)
            if tokens and tokens[0] == "save":
                path = Path(tokens[1])
                width = int(tokens[tokens.index("width") + 1])
                height = int(tokens[tokens.index("height") + 1])
                path.parent.mkdir(parents=True, exist_ok=True)
                Image.new("RGB", (width, height), (40, 80, 120)).save(path, format="PNG")  # type: ignore[union-attr]
            return "ok"

        result = execute_visualization_plan(
            plan,
            session=session,
            runner=runner,
            config=BackendConfig(
                execution_mode=ExecutionMode.IMMEDIATE,
                error_handling=ErrorHandlingMode.COLLECT,
                wait_frames=0,
            ),
            mode=ExecutionMode.IMMEDIATE,
        )
        path = collection.requests[0].output_path
        visualization_assert_true(result.success)
        visualization_assert_equal(result.executed_count, result.command_count)
        visualization_assert_true(path.is_file())
        info = inspect_image_file(path)
        visualization_assert_sequence_equal(info.size, (96, 72))
        manifest = create_snapshot_manifest(
            collection,
            (SnapshotResultSpec("backend", path, image=info, duration=result.duration_ms / 1000.0),),
            visualization=plan,
        )
        visualization_assert_equal(len(manifest.successful), 1)
    return {"commands": len(executed), "image_size": info.size}


@register_visualization_self_test(
    test_id="30.7.snapshot_validation",
    name="Snapshot validation failures",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("snapshots", "validation", "negative"),
)
def _self_test_snapshot_validation(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    with visualization_assert_raises(VisualizationSnapshotError):
        SnapshotRequestSpec(
            snapshot_id="transparent-jpeg",
            filename="transparent.jpg",
            format=SnapshotFormat.JPEG,
            transparent=True,
        )
    with visualization_assert_raises(VisualizationImageError):
        ImagePostprocessSpec(enabled=True, output_format=SnapshotFormat.SVG)
    empty = SnapshotCollection()
    issues = validate_snapshot_collection(empty)
    visualization_assert_true(any(item.code == "snapshot_collection_empty" for item in issues))
    with visualization_test_workspace(prefix="dockanalyzer_snapshot_validation_") as workspace:
        target = workspace / "existing.png"
        target.write_bytes(b"existing")
        request = SnapshotRequestSpec(
            snapshot_id="existing",
            filename=target,
            overwrite=False,
        )
        file_issues = validate_snapshot_request(request, check_filesystem=True)
        visualization_assert_true(any(item.code == "snapshot_output_exists" for item in file_issues))
    closed = _SnapshotSelfTestSession()
    closed.closed = True
    session_issues = validate_chimerax_session(closed)
    visualization_assert_true(any("closed" in issue.lower() for issue in session_issues))
    with visualization_assert_raises(ChimeraXUnavailableError):
        resolve_chimerax_session(closed)
    return {"collection_issues": len(issues), "session_issues": len(session_issues)}


@register_visualization_self_test(
    test_id="30.7.execution_serialization",
    name="Backend result serialization",
    section=SELF_TEST_SECTION_CHIMERAX_SNAPSHOTS,
    tags=("chimerax", "backend", "serialization"),
)
def _self_test_execution_serialization(
    context: VisualizationSelfTestContext,
) -> Mapping[str, Any]:
    info = ChimeraXBackendInfo(
        available=True,
        state=BackendState.ACTIVE,
        version="test",
        session_name="session",
        has_gui=True,
        runner_name="runner",
    )
    command = CommandExecutionResult(
        command_id="serialized",
        text="show #1",
        status=CommandStatus.EXECUTED,
        action_id="action",
        duration_ms=1.5,
        result_repr="ok",
    )
    action = ActionExecutionResult(
        action_id="action",
        operation=PlanOperation.SHOW_RECEPTOR,
        status=CommandStatus.EXECUTED,
        commands=(command,),
        duration_ms=1.5,
    )
    result = VisualizationExecutionResult(
        plan_id="serialized-plan",
        backend=BackendKind.CHIMERAX,
        execution_mode=ExecutionMode.IMMEDIATE,
        state=LifecycleState.COMPLETED,
        actions=(action,),
        duration_ms=2.0,
        backend_info=info,
    )
    visualization_assert_true(result.success)
    visualization_assert_equal(result.command_count, 1)
    visualization_assert_equal(result.executed_count, 1)
    restored = VisualizationExecutionResult(**json.loads(execution_result_to_json(result, indent=None)))
    visualization_assert_equal(restored.to_dict(), result.to_dict())
    visualization_assert_fingerprint_stable(result, restored)
    summary = summarize_execution_result(result)
    visualization_assert_equal(summary["executed"], 1)
    visualization_assert_equal(summary["failed"], 0)
    return {"commands": result.command_count, "state": result.state.value}



